  getPageSizeOptions(dataSource: { data: any[] }): number[] {
    const dataLength = dataSource.data.length;

    if (dataLength < 5) {
      return [dataLength];

    } else if (dataLength < 10) {
      return [5, dataLength]; 

    } else if (dataLength < 20) {
      return [5, 10, dataLength]; 
      
    } else {
      return [5, 10, 20, dataLength];
    }
  }
  
  

