  onFileSelected(event: any): void {
    const file = event.target.files[0];  // Get the selected file
    if (file) {
      const reader = new FileReader();

      // Listen to the load event to get the base64 string
      reader.onload = (e: any) => {
        const base64String = e.target.result;

        // Update the form with the file metadata and base64 string (or URL)
        this.billForm.patchValue({
          bill_image: {
            file_name: file.name,  // Store the file name
            file_url: base64String // Store the base64 string as file_url for preview
          }
        });
      };

      reader.onerror = (error) => {
        console.error('File reading error:', error);
      };

      reader.readAsDataURL(file);  // Convert file to base64 string
    }
  }

  formatDate(date: Date | null | undefined): string {
    if (!date) return ''; // Return an empty string if date is undefined or null
  
    const validDate = new Date(date); // Ensure we have a Date object
    const day = String(validDate.getDate()).padStart(2, '0');
    const month = String(validDate.getMonth() + 1).padStart(2, '0'); // Months are 0-based
    const year = validDate.getFullYear();
    return `${day}-${month}-${year}`;
  }


