  convertAmountToWords(amount: number): string {
    const singleDigits = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine"];
    const twoDigits = ["", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"];
    const tensMultiple = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];
    const placeValues = ["", "Thousand", "Lakh", "Crore"];
  
    if (amount === 0) {
      return "Zero Rupees";
    }
  
    const numberToWords = (n: number): string => {
      if (n < 10) return singleDigits[n];
      else if (n < 20) return twoDigits[n - 10];
      else if (n < 100) return tensMultiple[Math.floor(n / 10)] + (n % 10 ? ' ' + singleDigits[n % 10] : '');
      else if (n < 1000) return singleDigits[Math.floor(n / 100)] + " Hundred " + (n % 100 ? numberToWords(n % 100) : '');
      return "";
    };
  
    let words = "";
    let index = 0;
  
    // Process digits in reverse for Indian numbering format (split at 2 and 3 digits)
    const splitParts: number[] = [];
    splitParts.push(amount % 1000);
    amount = Math.floor(amount / 1000);
    while (amount > 0) {
      splitParts.push(amount % 100);
      amount = Math.floor(amount / 100);
    }
  
    // Build words from higher places (crore, lakh, thousand)
    for (let i = splitParts.length - 1; i >= 0; i--) {
      if (splitParts[i]) {
        words += numberToWords(splitParts[i]) + " " + placeValues[i] + " ";
      }
    }
  
    return words.trim() + " Rupees Only";
  }
  

