  printSelectedPaidRecords() {
    let selectedRecords = this.selectionPaid.selected;
    if (selectedRecords.length > 0) {
      this.getLogo();
      let company: any = this.currentWorkLocation.company?.[0] || null;
      let branch: any = this.currentWorkLocation.branch?.[0] || null;
      let companyname = company?.companyname || '';
      let  address = (branch && branch.address1 && branch.address2)? `${branch?.address1 || ''}, ${branch?.address2 || ''}`:`${company?.address1 || ''}, ${company?.address2 || ''}`;
      const doc = new jsPDF();
      let currentY = 10; // Start position for first claim
      let claimsPerPage = 0; // Track claims on current page

      let recordPromises = selectedRecords.map(record =>
          this.claims.getClmSelectedRequestData(record.claim_id).toPromise().then((res_data: any) => {
              if (res_data && res_data.status && res_data.bills) {
                  let approvedAmountWords = this.convertAmountToWords(record.approved_amount);
                  currentY = (claimsPerPage === 1) ? currentY+20:10;
                  // Add new page after 2 claims
                  if (claimsPerPage === 2 ||  res_data.bills.length >5) {
                      doc.addPage();
                      claimsPerPage = res_data.bills.length >5 ? 1:0;
                  }
                  // Add Header (Company Name & Address)
                  doc.setFontSize(14).text(companyname, 105, currentY, { align: 'center' });
                  let splitBranchAddress = doc.setFontSize(9).splitTextToSize(address, (doc.internal.pageSize.width - 20));
                  doc.setFontSize(9).text(splitBranchAddress, doc.internal.pageSize.width / 2, currentY + 5, { align: 'center' });
                  currentY = currentY + 5;
                  doc.line(10, currentY + 7, doc.internal.pageSize.width - 10, currentY + 7);
                  currentY += 15;
                  doc.setFontSize(10);
                  doc.text(`Claim ID:`, 14, currentY );
                  doc.text(`${record.claim_number}`, 34, currentY );
                  doc.text(`Voucher ID:`, 150, currentY);
                  doc.text(`${record.voucher_number ?? 'N/A'}`,170, currentY, { align: 'left' });
                  doc.text(`Executive:`, 14, currentY + 5);
                  doc.text(`${record.emp_name}(${record.emp_id||''})`, 34, currentY + 5);
                  doc.text(`Date:`, 150, currentY + 5);
                  doc.text(`${ record.created_on? this.claims.getFormattedDate(record.updated_on) : 'N/A'}`, 170, currentY+5, { align: 'left' });
                
                  // Table Headers
                  let tableColumn = ["S.No", "Particulars", "Amount"];
                  let tableRows: any[] = [];
                  let bill_count = res_data && res_data.bills?res_data.bills.length:0;
                  let min_bills = bill_count <=5 ? 5:bill_count;
                  let row_no = 1;
                  // Check if claim is KMS or GEN
                  if (record.claim_number.includes("KMS")) {
                    let formattedAmount = new Intl.NumberFormat('en-IN', { minimumFractionDigits: 2,  maximumFractionDigits: 2 }).format(parseFloat(record.approved_amount)); 
                      tableRows.push([
                          "1",
                          record.kms_comments ?? 'Kilometers Travelled',
                          { content: formattedAmount, styles: { halign: 'right' }  }
                        // (record.approved_amount).toLocaleString('en-IN', { style: 'currency', currency: 'INR' })
                      ]);
                      for (let i = 1; i < min_bills; i++) {
                          tableRows.push([`${i + 1}`, "", ""]);
                      }
                  } else if (record.claim_number.includes("GEN")) {
                      res_data.bills.forEach((bill: any, index: number) => {
                        let formattedAmount = new Intl.NumberFormat('en-IN', { minimumFractionDigits: 2,  maximumFractionDigits: 2 }).format(parseFloat(bill.bill_amount)); 
                          if (bill.bill_status) {
                            let bill_details = [
                              { content: `${this.getReimbursementTypeName(bill.rbs_type) ?? 'Unknown'}`, styles: { fontSize: 10, fontStyle: 'bold' } },
                              { content: `Bill No: ${bill.bill_no}, Date: ${this.formatDate(bill.bill_date)}`, styles: { fontSize: 8, textColor: 100 } }
                          ];
                              tableRows.push([
                                  `${row_no ++}`,
                                  `${this.getReimbursementTypeName(bill.rbs_type) ?? 'Unknown'}\nBill No: ${bill.bill_no}, Date: ${this.formatDate(bill.bill_date)}`,
                                  //bill_details,
                                  { content: formattedAmount, styles: { halign: 'right' }  }
                              ]);
                          }
                      });
                      for (let i = tableRows.length; i < min_bills; i++) {
                          tableRows.push([`${row_no ++}`, ` \n `, ""]);
                      }
                  }

                  // Add Total Row
                  let formattedTotal = new Intl.NumberFormat('en-IN', { minimumFractionDigits: 2,  maximumFractionDigits: 2 }).format(parseFloat( record.approved_amount)); 
                  tableRows.push(["", "Total", { content: formattedTotal, styles: { halign: 'right' }  }]);

                  // Generate Table
                  const table = autoTable(doc, {
                      startY: currentY + 10,
                      head: [tableColumn],
                      body: tableRows,
                      theme: "grid",
                      styles: { fontSize: 9, cellPadding: 1 },
                      didParseCell: (data) => {
                        if (data.column.index === 1) { // Apply to the second column only
                            data.cell.styles.fontSize = 9; // Set main text font size
                            data.cell.styles.minCellHeight = 2.2; // Adjust line height
                        }
                    },
                      headStyles: { fillColor: [220, 220, 220], textColor: 0, fontStyle: "bold" },
                      //margin: { top: 10, bottom: 10 },
                    // pageBreak: 'auto', // Ensures controlled page breaks
                  });

                  // Get last Y position from table
                  const finalY = (doc as any).lastAutoTable.finalY || currentY + 40;
                
                  // Add Total Approved Amount in Words
                  doc.setFontSize(9).text(`Total Approved Amount in Words: ${approvedAmountWords}`, 14, finalY + 10);
                  
                  doc.setFontSize(10).text(`Approved By: ${record.verified_by}`, 14, finalY + 20);
                  doc.text("Receiver: ________________", 140, finalY + 20);

                  // Move Y for next claim
                  currentY = finalY + 30;
                  claimsPerPage++;
              }
          })
      );

      Promise.all(recordPromises).then(() => {
          doc.save('Selected_Claims.pdf');
      }).catch(error => {
          console.error('Error fetching bill details:', error);
          alert('An error occurred while fetching bill details. Please try again.');
      });
  }
}

