  isAllSelectedPaid() {
    const pageData = this.getCurrentPageData();
    if(pageData  && pageData.length)
    return pageData.every(row => this.selectionPaid.isSelected(row));
    else return null;
  }

  /** Selects all rows on the current page if not all are selected; otherwise clears the selection. */
  masterTogglePaid() {
    const pageData = this.getCurrentPageData();
    if(pageData && pageData.length){
      if (this.isAllSelectedPaid()) {
        pageData.forEach(row => this.selectionPaid.deselect(row));
      } else {
        pageData.forEach(row => this.selectionPaid.select(row));
      }
    }
  }

  
