    getCurrentPageData() {      
      if (!this.paginator_paid) return []; // Return an empty array if paginator is undefined
    
      let filteredData = this.dataSource_paid.filteredData || [];
      const startIndex = this.paginator_paid.pageIndex * this.paginator_paid.pageSize;
      return filteredData.slice(startIndex, startIndex + this.paginator_paid.pageSize);
    } 

