getEmployeeName(){
  let emp_name = '';    
  let userId = this.searchForm.controls.Users.value;
  if (userId == '0' || userId == '') {
    userId=null;
  }
    if(this.filteredEmployees && this.filteredEmployees.length){
      if(userId){
        this.filteredEmployees.forEach((e:any)=>{
          if(e.empid == userId && emp_name == '')
            emp_name = e.empname;
        })
      }
      else emp_name = 'All';      
    }
  return emp_name; 
} 

  generatePDF(){

    let list_selected:any=[];

    if(this.tab_type == 'Pending') 
      list_selected = this.pending_list;
    if(this.tab_type == 'Verified' )
      list_selected = this.userRole == 'Finance'?this.pending_list:this.verified_list;
    if(this.tab_type == 'Approved') 
      list_selected = this.approved_list;
    if(this.tab_type == 'Paid') 
      list_selected = this.paid_list;
    if(this.tab_type == 'Rejected') 
      list_selected = this.rejected_list;
    
    let fromDate = this.datePipe.transform(this.searchForm.controls.fromDate.value, "dd-MM-YYYY");
    let toDate = this.datePipe.transform(this.searchForm.controls.toDate.value, "dd-MM-YYYY");
    let selections = ``;
    
    if(this.userRole == 'Finance' || this.is_super_admin){
      selections = selections + `\n` + `Selected Locations: ${this.getSelectedLocationNames()}`;
      selections = selections + `\n` + `Selected Managers: ${this.getSelectedManagerNames()}`;
    }
    else if(this.userRole == 'Manager')
      selections =  `Date: ${fromDate} To ${toDate},     Employee: ${this.getEmployeeName()},     Manager: ${ this.userSession.firstname||'' + ' '+ this.userSession.middlename||'' + ' '+ this.userSession.lastname||'' }`;

    if(this.userRole == 'Finance')
      selections = selections + `\n` + `Date: ${fromDate} To ${toDate},     Employee: ${this.getEmployeeName()},     Finance Manager: ${ this.userSession.firstname||'' + ' '+ this.userSession.middlename||'' + ' '+ this.userSession.lastname||'' }`;
    
    else if(this.is_super_admin)
      selections = selections + `\n` + `Date: ${fromDate} To ${toDate},     Employee: ${this.getEmployeeName()},     Super Admin: ${ this.userSession.firstname||'' + ' '+ this.userSession.middlename||'' + ' '+ this.userSession.lastname||'' }`;
    let action_status = this.claims.CapitalizeFirstLetter(this.tab_type);
    let action = (action_status == 'Pending')?'Action':action_status;
    let headers_others =['S.No','Applied On',	'Employee','Claim Id','Bills (count)','Claimed Amount',(action== 'Action'?'Approved':action )+' Amount',action +' By', action +' On', 'Claim Status'];  
    let tblWidths_others:any = { 0: { cellWidth: 10 }, 1: { cellWidth: 25 }, 2: { cellWidth: 40 }, 3: { cellWidth: 30 }, 4: { cellWidth: 15 }, 5: { cellWidth: 30 }, 6: { cellWidth: 30 },7: { cellWidth: 25 },8: { cellWidth: 25 },9: { cellWidth: 25 }};
    
   
    let headers_rejected = ['S.No','Applied On',	'Employee','Claim Id','Bills (count)','Claimed Amount','Rejected By','Rejected On', 'Reason'];
    let tblWidths_rejected:any = { 0: { cellWidth: 10 }, 1: { cellWidth: 20 }, 2: { cellWidth: 40 }, 3: { cellWidth: 30 }, 4: { cellWidth: 15 }, 5: { cellWidth: 30 }, 6: { cellWidth: 30 },7: { cellWidth: 20 },8: { cellWidth: 85 }};
   
    
    let  headers_paid  = ['S.No','Applied On',	'Employee','Claim Id','Voucher Id','Bills (count)','Claimed Amount','Paid Amount','Paid By','Paid On'];
    let tblWidths_paid:any = { 0: { cellWidth: 10 }, 1: { cellWidth: 25 }, 2: { cellWidth: 40 }, 3: { cellWidth: 30 }, 4: { cellWidth: 30 },5: { cellWidth: 15 },  6: { cellWidth: 30 },7: { cellWidth: 25 },8: { cellWidth: 40 },9: { cellWidth: 25 } };
   
    let tables:any[] = [];     
    let tblBody:any = [];
    let i = 1;
    let reportName = 'Claims Approval ';
     if(this.tab_type == 'Paid'){   
      tblBody = [  
        ...this['paid_list'].map((row:any)=>[
          i++,
          this.claims.getFormattedDate(row.created_on),
          row.emp_name??'',
          row.claim_number??'',
          row.receipt_number??'',
          row.bill_count,
          row.request_amount,
          row.approved_amount, 
          row.verified_by,
          this.claims.getFormattedDate(row.action_on),        
       
        ])  ];
        reportName = reportName + 'Paid List';
        tables.push({ headers:headers_paid,sub_head: '', body: tblBody, widths: tblWidths_paid,table_name:'assignments',userRole:this.userRole});

      }else if(this.tab_type == 'Rejected'){
  
        tblBody = [  
          ...this['rejected_list'].map((row:any)=>[
            i++,
            this.claims.getFormattedDate(row.created_on),
            row.emp_name??'',
            row.claim_number??'',
            row.bill_count,
            row.request_amount,
            row.verified_by,
            this.claims.getFormattedDate(row.action_on),
            row.verify_comments,
            row.claim_status                  
          ])  ];
          reportName = reportName + 'Rejected List';
          tables.push({ headers:headers_rejected,sub_head: '', body: tblBody, widths: tblWidths_rejected,table_name:'assignments',userRole:this.userRole});
      }
      else{
        tblBody = [  
          ...list_selected.map((row:any)=>[
            i++,
            this.claims.getFormattedDate(row.created_on),
            row.emp_name??'',
            row.claim_number??'',
            row.bill_count,
            row.request_amount,
            row.approved_amount, 
            this.tab_type == 'Pending'?row.action_by_name:row.verified_by,
            this.claims.getFormattedDate(row.action_on),
            row.claim_status       
          ])  ];
          reportName = reportName + (this.tab_type + ' List');
          tables.push({ headers:headers_others,sub_head: '', body: tblBody, widths: tblWidths_others,table_name:'assignments',userRole:this.userRole});
  
      }
   
      this.pdfService.generatePDF_common('landscape',reportName,selections,tables,'Claim_Approval_report.pdf');
    }
  

    getSelectedManagerNames(){
      let selectedManagerNames:string ='';
      if(this.selectedManagers && this.selectedManagers.length){
        this.managersDetails?.forEach((md:any)=>{
          if(this.selectedManagers.includes(md.manager_emp_id)){
            selectedManagerNames = selectedManagerNames + (selectedManagerNames == ''?'': ', ')+ md.manager_name;
          }
        });
      }
      return selectedManagerNames;
    }

    getSelectedLocationNames(){
      let selectedLocationNames:string ='';
      if(this.selectedLocations && this.selectedLocations.length){
        this.worklocationDetails?.forEach((wl:any)=>{
          if(this.selectedLocations.includes(wl.id)){
            selectedLocationNames = selectedLocationNames + (selectedLocationNames == ''?'': ', ')+ wl.location;
          }
        });
      }
      return selectedLocationNames;
    }
