  constructor(private formBuilder: UntypedFormBuilder, private claims: ClaimsService, private companyService: CompanySettingService,private dataTransfer:DataTransferService,
    private spinner: NgxSpinnerService, private route: ActivatedRoute, public dialog: MatDialog,  private translate: TranslateService, private datePipe: DatePipe, public reportsService: ReportsService, 
    private LM: CompanyInformationService, private mainService: MainService,  private cdr: ChangeDetectorRef ,  private router: Router,


  ) {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
  }


  ngOnInit(): void {
    let date = new Date(); // Get the current date
    date.setMonth(date.getMonth() - 1);
    this.previousMonth = date.toLocaleString('default', { month: 'long' });
    const currentPath = this.route.snapshot.routeConfig?.path;
    this.updateBranchWiseHeading('paid'); 
    // Initialize the search form
    this.searchForm = this.formBuilder.group({
      companylocation: ["", Validators.required], // Location field
      managers: [[], Validators.required],        // Managers field
      Users: ['0'],                               // Employees field
    });
    this.route.url.subscribe(segments => {
      this.userRole = segments[0]?.path;  
    });

    // Route-specific logic
    if (this.userRole == 'Finance') {
      this.getWorkLocation();
    } else if (this.userRole == 'Manager') {
      this.getTotalEmployeslistByManagerId(true); // Populate employees under the manager
    } else if (this.userRole == 'Employee') {
      this.getDataForEmployee(); // Load data for logged-in employee
    }

    this.searchControl.valueChanges.subscribe((searchText:any) => {      
      this.filteredEmployees = this.employeelist.filter((e: any) =>
        e.empname.toLowerCase().includes(searchText.toLowerCase()));
     // if(this.filteredEmployees.length <= 0)  this.searchControl.setValue('');
                
    });
   

    if (this.userRole === 'Finance') {
      this.getBranchWiseAmount('paid'); 
    }
      
  }
  
  
  getDataForEmployee() {
    const empid = this.userSession.id; // Logged-in employee ID
    const requestData = {
      empid, // Pass the employee ID
      manager_id: null, // No manager for the logged-in employee
    };

    // Fetch and display data for the employee
    this.getClaimsScorecard(requestData);
    this.getClaimsStatusByCount(requestData);
    this.getReimbursementTypeByAmount(requestData);
    this.getClaimRequestRecords(requestData);    
    this.getClaimRequestRecordsCountOnRole(requestData)
  }


  getClaimRequestRecordsCountOnRole(data:any){
    let req_data= {
        empid:data.empid,
      manager_id:data.manager_id,  
      userRole:this.userRole,
      from_date:null,
      to_date:null,
      claim_status:(this.userRole == 'Finance')?'Verified':'Submitted'	
    }

    this.spinner.show();
    this.claims.getSprypleData(req_data, 'get_clm_request_records_count').subscribe((resdata: any) => {
        this.spinner.hide();
        if (resdata.status && resdata.data && resdata.data[0] && resdata.data[0].status_count) {
          this.alertMessages.push(`Found ${resdata.data[0].status_count} ${resdata.data[0].claim_status}  Claims, waiting for Approval`);
        }
      });
  }








