  getClaimRequestRecords(requestData: any = {}): void {
    const currentPath = this.route.snapshot.routeConfig?.path;
    const user_role = currentPath === 'Finance/ClaimsDashboard' ? 'Finance' :
                      currentPath === 'Manager/ClaimsDashboard' ? 'Manager' : 'Employee';


    let claim_status;
    if (user_role == 'Manager') {
      claim_status = 'Submitted';
    } else if (user_role == 'Finance') {
      claim_status = 'Verified';
    } else if (user_role == 'Employee') {
      claim_status = 'Processed';
    }     
  
    const currentDate = this.datePipe.transform(new Date(), 'yyyy-MM-dd');
    const from_date = user_role == 'Employee' ? currentDate : null;
    const to_date = user_role == 'Employee' ? currentDate : null;
  
    const finalRequestData = {
      empid: requestData?.empid || null,
      manager_id: requestData?.manager_id || null,
      from_date, 
      to_date,
      user_role,
      claim_status,
      page_number: 1,
      page_size: 1
    };
  
    this.claimRecords = [];
    this.spinner.show();

    this.claims.getSprypleData(finalRequestData, 'get_clm_request_records').subscribe(
      (response: any) => {
        this.spinner.hide();
        if (response.status) {
          this.claimRecords = response.data;
        } else {
          console.error('Error fetching claim request records:', response.message);
        }
      },
      (error: any) => {
        this.spinner.hide();
        console.error('Error while fetching claim request records:', error);
      }
    );

  }
  
  getfinancialYearBeginDate(){
    let currentMonth = this.maxDate.getMonth() + 1; // Months are 0-indexed
    let currentYear = this.maxDate.getFullYear();
    let financialYearStartDate = null;
    if (currentMonth >= 4) financialYearStartDate = new Date(currentYear, 3, 1); // If current month is April or later, financial year starts from April of the same year
    else financialYearStartDate =  new Date(currentYear - 1, 3, 1); // If current month is before April, financial year starts from April of the previous year
    return financialYearStartDate;
  }
  
  redirectToApprovals(event:any){
      let back_params:any={};
      back_params.back_route = "/Claims/"+this.userRole+"/ClaimsApprovals";
      back_params.redirected = 1;
      back_params.selectedTabIndex = 0;
      back_params.from_date =  this.getfinancialYearBeginDate();  
      back_params.to_date = this.maxDate;
      back_params.userRole = this.userRole;
      back_params.Users = this.searchForm.controls.Users.value?this.searchForm.controls.Users.value:0;
      back_params.employeelist = this.employeelist||[];
      back_params.filteredEmployees = this.filteredEmployees||[];
      back_params.selectedManagers =  this.selectedManagers||[];
      back_params.selectedLocations = this.selectedLocations||[];
      back_params.managersDetails= this.managersDetails||[];
      back_params.worklocationDetails= this.worklocationDetails||[];
     sessionStorage.setItem('back_url', JSON.stringify(back_params));
     this.router.navigate([back_params.back_route]);
  }

