Searchform() {
  let managerIds:any[] = [];
  if(this.searchForm.invalid){
    this.searchForm.markAllAsTouched();
    if(this.is_super_admin && this.userRole == 'Finance')
    return;
    else if(this.searchForm.controls.Users.invalid)
    return;
   }
 
  if(this.userRole == 'Manager'){
    managerIds.push(this.userSession.id);
  }
  if(this.userRole == 'Finance' && this.searchForm.controls.managers.value){
      managerIds = this.searchForm.controls.managers.value.map((m: any) => m.manager_emp_id);
  }

  let requestData = {
    empid: this.userRole == 'Employee'? this.userSession.id : this.searchForm.controls.Users.value, // Pass employee ID or null if "All Employees" is selected
    manager_id: managerIds.length > 0 ? JSON.stringify(managerIds) : null, // Convert manager IDs to JSON array format
  };
  
  requestData.empid = (requestData.empid == 0) ? null:requestData.empid;
 
  this.claimsData = [];
  this.dataSource.data = [];
  this.billsBarChartData = [];
  this.claimsStatusData = [];
  this.alertMessages = [];
  // Pass the constructed requestData to the procedures
  this.getClaimsScorecard(requestData);
  this.getClaimsStatusByCount(requestData);
  this.getReimbursementTypeByAmount(requestData);
  this.getClaimRequestRecords(requestData);
  this.getClaimRequestRecordsCountOnRole(requestData);
}

  
