import { Directive } from '@angular/core';
import { AbstractControl, NG_VALIDATORS, ValidationErrors } from '@angular/forms';

@Directive({
  selector: '[noRepeatDigits]',
  providers: [{
    provide: NG_VALIDATORS,
    useExisting: NoRepeatDigitsDirective,
    multi: true
  }]
})
export class NoRepeatDigitsDirective {

  constructor() { }

   validate(control: AbstractControl): ValidationErrors | null {
    const value = control.value;
    
    if (!value || value.length < 6) {
      return null; // Let other validators handle length requirements
    }
    
    // Check if all digits are identical
    const firstChar = value[0];
    const allSame = Array.from(value).every(char => char === firstChar);
    
    return allSame ? { 'repeatedDigits': { value: control.value } } : null;
  }

}
