import { Component, OnInit, ViewChild } from '@angular/core';
import { FormGroup, FormBuilder } from '@angular/forms';
import { Router } from '@angular/router';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { PayrollService } from 'src/app/modules/payroll/payroll.service';
import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';

@Component({
  selector: 'app-payroll-policies',
  templateUrl: './payroll-policies.component.html',
  styleUrls: ['./payroll-policies.component.scss']
})
export class PayrollPoliciesComponent implements OnInit {

  constructor(private formBuilder: FormBuilder, private router: Router, private payrollService: PayrollService, private dialogService: ReusableDialogService,) {
    this.companyDBName = sessionStorage.getItem('companyName');
  }
  payrollPoliciesForm!: FormGroup;

  displayedColumns: string[] = ['sno', 'configurationrules', 'data'];
  dataSource: MatTableDataSource<any> = <any>[];
  pageLoading = true;
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort) sort!: MatSort;

  companyDBName: any;
  defaultRuleInfo: any = [];
  isEditDefaultRules: boolean = false;
  defaultDropdownList: any = [{ value: '1', name: 'Yes' }, { value: '0', name: 'No' }];

  msgLM1: any;
  msgLM2: any;
  msgLM3: any;
  msgLM21: any;
  msgLM110: any;
  msgLM111: any;
  msgLM133: any;
  msgLM134: any;
  msgLM135: any;
  msgLM136: any;
  btnDisable: boolean = false;

  variablePaySeqDropdownList: any = [
    { value: '1', name: 'Monthly' },
    { value: '3', name: 'Quarterly' },
    { value: '6', name: 'Half-yearly' },
    { value: '12', name: 'Yearly' }
  ]

  lopdaysDropdownList: any = [
    { value: '0', name: '0' },
    { value: '1', name: '1' },
    { value: '2', name: '2' },
    { value: '3', name: '3' },
    { value: '4', name: '4' },
    { value: '5', name: '5' },
    { value: '31', name:'Not Applicable'}
  ]
  ngOnInit(): void {
    this.payrollPoliciesForm = this.formBuilder.group(
      {
        noOfInstallments: [""],
        monthsToResumeLastRecovery: [""],
        otAmountIncludeSalary: [""],
        isCompanyCoveredUnderGratuityAct: [""],
        isGratuityMonthlyPaid: [""],
        isLOPdeductionBasedOnCalendar: [""],
        isAbsentConsiderLop: [""],
        isDynamicPayrollApplicable: [""],
        leavesThresholdForDynamicPayroll: [""],
        esiAndEpfContributionIndependentOfLOP: [""],
        OTMinExtraHours: [""],
        variablePaySequence: [""],
        lopDaysProportionate: [""],
        extraWorkingDays: [""],
        IS_SALARY_CALCULATION_FOR_THIRTY_DAYS: [""],
        ENABLE_COMP_DEDUCTIONS_AND_REIMBURSEMENTS_FOR_EMP: [""]
      },
    );
    this.getPayrollRules();
  }
  /**Common ems rules */
  getPayrollRules() {
    this.payrollService.getPayrollPolicies().subscribe((result) => {
      this.defaultRuleInfo = result.data;
      this.dataSource = new MatTableDataSource(this.defaultRuleInfo);

      for (let i = 0; i < this.defaultRuleInfo.length; i++) {

        if (this.defaultRuleInfo[i].rule_name == 'NUMBER_OF_INSTALLMENTS_FOR_ADV_SAL_RECOVERY') {
          this.payrollPoliciesForm.controls.noOfInstallments.setValue(this.defaultRuleInfo[i].value);
          this.payrollPoliciesForm.controls.noOfInstallments.disable();
        }
        else if (this.defaultRuleInfo[i].rule_name == 'MONTHS_TO_RESUME_ADV_SAL_AFTER_LAST_RECOVERY') {
          this.payrollPoliciesForm.controls.monthsToResumeLastRecovery.setValue(this.defaultRuleInfo[i].value);
          this.payrollPoliciesForm.controls.monthsToResumeLastRecovery.disable();

        }
        else if (this.defaultRuleInfo[i].rule_name == 'OVER_TIME_AMOUNT_TO_BE_INCLUDED_IN_SALARY') {
          this.payrollPoliciesForm.controls.otAmountIncludeSalary.setValue(this.defaultRuleInfo[i].value);
          this.payrollPoliciesForm.controls.otAmountIncludeSalary.disable();
        }
        else if (this.defaultRuleInfo[i].rule_name == 'IS_COMPANY_COVERED_UNDER_GRATUITY_ACT') {
          this.payrollPoliciesForm.controls.isCompanyCoveredUnderGratuityAct.setValue(this.defaultRuleInfo[i].value);
          this.payrollPoliciesForm.controls.isCompanyCoveredUnderGratuityAct.disable();
        }
        else if (this.defaultRuleInfo[i].rule_name == 'IS_GRATUITY_MONTHLY_PAID') {
          this.payrollPoliciesForm.controls.isGratuityMonthlyPaid.setValue(this.defaultRuleInfo[i].value);
          this.payrollPoliciesForm.controls.isGratuityMonthlyPaid.disable();
        }
        else if (this.defaultRuleInfo[i].rule_name == 'IS_LOP_DEDUCTION_CALCULATION_BASED_ON_30_DAY_CALENDAR') {
          this.payrollPoliciesForm.controls.isLOPdeductionBasedOnCalendar.setValue(this.defaultRuleInfo[i].value);
          this.payrollPoliciesForm.controls.isLOPdeductionBasedOnCalendar.disable();

        } else if (this.defaultRuleInfo[i].rule_name == 'IS_ABSENT_CONSIDERED_AS_LOP') {
          this.payrollPoliciesForm.controls.isAbsentConsiderLop.setValue(this.defaultRuleInfo[i].value);
          this.payrollPoliciesForm.controls.isAbsentConsiderLop.disable();

        } else if (this.defaultRuleInfo[i].rule_name == 'IS_DYNAMIC_PAYROLL_PRCESSING_APPLICABLE') {
          this.payrollPoliciesForm.controls.isDynamicPayrollApplicable.setValue(this.defaultRuleInfo[i].value);
          this.payrollPoliciesForm.controls.isDynamicPayrollApplicable.disable();

        } else if (this.defaultRuleInfo[i].rule_name == 'NUMBER_OF_LEAVES_THRESHOLD_FOR_DYNAMIC_PAYROLL_PROCESSING') {
          this.payrollPoliciesForm.controls.leavesThresholdForDynamicPayroll.setValue(this.defaultRuleInfo[i].value);
          this.payrollPoliciesForm.controls.leavesThresholdForDynamicPayroll.disable();

        } else if (this.defaultRuleInfo[i].rule_name == 'ESI_AND_EPF_CONTRIBUTION_INDEPENDENT_OF_LOP') {
          this.payrollPoliciesForm.controls.esiAndEpfContributionIndependentOfLOP.setValue(this.defaultRuleInfo[i].value);
          this.payrollPoliciesForm.controls.esiAndEpfContributionIndependentOfLOP.disable();
        }
        else if (this.defaultRuleInfo[i].rule_name == 'MINIMUM_EXTRA_HOURS_TO_CONSIDER_FOR_OVER_TIME') {
          this.payrollPoliciesForm.controls.OTMinExtraHours.setValue(this.defaultRuleInfo[i].value);

          this.payrollPoliciesForm.controls.OTMinExtraHours.disable();

        } else if (this.defaultRuleInfo[i].rule_name == 'VARIABLE_PAY_FREQUENCY_IN_MONTHS') {
          this.payrollPoliciesForm.controls.variablePaySequence.setValue(this.defaultRuleInfo[i].value);
          this.payrollPoliciesForm.controls.variablePaySequence.disable();

        } else if (this.defaultRuleInfo[i].rule_name == 'MINIMUM_LOP_DAYS_FOR_PROPORTIONATE_WEEKOFF_DEDUCTION') {
          this.payrollPoliciesForm.controls.lopDaysProportionate.setValue(this.defaultRuleInfo[i].value);
          this.payrollPoliciesForm.controls.lopDaysProportionate.disable();

        } else if (this.defaultRuleInfo[i].rule_name == 'IS_PAYMENT_GIVEN_FOR_EXTRA_WORKING_DAYS') {
          this.payrollPoliciesForm.controls.extraWorkingDays.setValue(this.defaultRuleInfo[i].value);
          this.payrollPoliciesForm.controls.extraWorkingDays.disable();
        }
        else if (this.defaultRuleInfo[i].rule_name == 'IS_SALARY_CALCULATION_FOR_THIRTY_DAYS') {
          this.payrollPoliciesForm.controls.IS_SALARY_CALCULATION_FOR_THIRTY_DAYS.setValue(this.defaultRuleInfo[i].value);
          this.payrollPoliciesForm.controls.IS_SALARY_CALCULATION_FOR_THIRTY_DAYS.disable();
        } else if (this.defaultRuleInfo[i].rule_name == 'ENABLE_COMP_DEDUCTIONS_AND_REIMBURSEMENTS_FOR_EMP') {
          this.payrollPoliciesForm.controls.ENABLE_COMP_DEDUCTIONS_AND_REIMBURSEMENTS_FOR_EMP.setValue(this.defaultRuleInfo[i].value);
          this.payrollPoliciesForm.controls.ENABLE_COMP_DEDUCTIONS_AND_REIMBURSEMENTS_FOR_EMP.disable();
        }
      }
    })
  }

  saveDefaultrules() {


    if (this.payrollPoliciesForm.valid) {
      if (this.btnDisable) {
        return;
      }
      let minLeaves = Number(this.payrollPoliciesForm.controls.leavesThresholdForDynamicPayroll?.value);
      let minOTHours = Number(this.payrollPoliciesForm.controls.OTMinExtraHours?.value);

      if (this.payrollPoliciesForm.controls.isDynamicPayrollApplicable.value == 1 &&
        this.payrollPoliciesForm.controls.leavesThresholdForDynamicPayroll.value == null) {
        this.dialogService.openDialog('Please enter number of leaves threshold for dynamic payroll processing');

      } else if (minLeaves >= 30) {
        this.dialogService.openDialog('Please enter a valid minimum leaves in a month');

      } else if (minOTHours > 23) {
        this.dialogService.openDialog('Please enter a valid minimum Over time hours');
      }
      else {

        for (let i = 0; i < this.defaultRuleInfo.length; i++) {

          if (this.defaultRuleInfo[i].rule_name == 'NUMBER_OF_INSTALLMENTS_FOR_ADV_SAL_RECOVERY') {
            this.defaultRuleInfo[i].value = this.payrollPoliciesForm.controls.noOfInstallments.value;

          }
          else if (this.defaultRuleInfo[i].rule_name == "MONTHS_TO_RESUME_ADV_SAL_AFTER_LAST_RECOVERY") {
            this.defaultRuleInfo[i].value = this.payrollPoliciesForm.controls.monthsToResumeLastRecovery.value;

          }
          else if (this.defaultRuleInfo[i].rule_name == "OVER_TIME_AMOUNT_TO_BE_INCLUDED_IN_SALARY") {
            this.defaultRuleInfo[i].value = this.payrollPoliciesForm.controls.otAmountIncludeSalary.value;

          }
          else if (this.defaultRuleInfo[i].rule_name == "IS_COMPANY_COVERED_UNDER_GRATUITY_ACT") {
            this.defaultRuleInfo[i].value = this.payrollPoliciesForm.controls.isCompanyCoveredUnderGratuityAct.value;

          }
          else if (this.defaultRuleInfo[i].rule_name == "IS_GRATUITY_MONTHLY_PAID") {
            this.defaultRuleInfo[i].value = this.payrollPoliciesForm.controls.isGratuityMonthlyPaid.value;

          }
          else if (this.defaultRuleInfo[i].rule_name == "IS_LOP_DEDUCTION_CALCULATION_BASED_ON_30_DAY_CALENDAR") {
            this.defaultRuleInfo[i].value = this.payrollPoliciesForm.controls.isLOPdeductionBasedOnCalendar.value;

          }
          else if (this.defaultRuleInfo[i].rule_name == "IS_ABSENT_CONSIDERED_AS_LOP") {
            this.defaultRuleInfo[i].value = this.payrollPoliciesForm.controls.isAbsentConsiderLop.value;

          } else if (this.defaultRuleInfo[i].rule_name == "IS_DYNAMIC_PAYROLL_PRCESSING_APPLICABLE") {
            this.defaultRuleInfo[i].value = this.payrollPoliciesForm.controls.isDynamicPayrollApplicable.value;

          } else if (this.defaultRuleInfo[i].rule_name == "NUMBER_OF_LEAVES_THRESHOLD_FOR_DYNAMIC_PAYROLL_PROCESSING") {
            this.defaultRuleInfo[i].value = this.payrollPoliciesForm.controls.leavesThresholdForDynamicPayroll.value;

          } else if (this.defaultRuleInfo[i].rule_name == "ESI_AND_EPF_CONTRIBUTION_INDEPENDENT_OF_LOP") {
            this.defaultRuleInfo[i].value = this.payrollPoliciesForm.controls.esiAndEpfContributionIndependentOfLOP.value;

          } else if (this.defaultRuleInfo[i].rule_name == "MINIMUM_EXTRA_HOURS_TO_CONSIDER_FOR_OVER_TIME") {
            this.defaultRuleInfo[i].value = this.payrollPoliciesForm.controls.OTMinExtraHours.value;
          }
          else if (this.defaultRuleInfo[i].rule_name == "VARIABLE_PAY_FREQUENCY_IN_MONTHS") {
            this.defaultRuleInfo[i].value = this.payrollPoliciesForm.controls.variablePaySequence.value;

          } else if (this.defaultRuleInfo[i].rule_name == "MINIMUM_LOP_DAYS_FOR_PROPORTIONATE_WEEKOFF_DEDUCTION") {
            this.defaultRuleInfo[i].value = this.payrollPoliciesForm.controls.lopDaysProportionate.value;
          } else if (this.defaultRuleInfo[i].rule_name == "IS_PAYMENT_GIVEN_FOR_EXTRA_WORKING_DAYS") {
            this.defaultRuleInfo[i].value = this.payrollPoliciesForm.controls.extraWorkingDays.value;
          }
          else if (this.defaultRuleInfo[i].rule_name == "IS_SALARY_CALCULATION_FOR_THIRTY_DAYS") {
            this.defaultRuleInfo[i].value = this.payrollPoliciesForm.controls.IS_SALARY_CALCULATION_FOR_THIRTY_DAYS.value;
          } else if (this.defaultRuleInfo[i].rule_name == "ENABLE_COMP_DEDUCTIONS_AND_REIMBURSEMENTS_FOR_EMP") {
            this.defaultRuleInfo[i].value = this.payrollPoliciesForm.controls.ENABLE_COMP_DEDUCTIONS_AND_REIMBURSEMENTS_FOR_EMP.value;
          }
        }
        var info = {
          ruleData: this.defaultRuleInfo
        }
        this.btnDisable = true;
        this.payrollService.setPayrollRuleValues(info).subscribe((result) => {

          if (result.status) {
            this.dialogService.openDialog(result.message);
            this.isEditDefaultRules = false;
            this.cancelDefaultRules();
            this.getPayrollRules();

          }
          else {
            this.dialogService.openDialog('Unable to update Payroll policies. Please try again');
            this.btnDisable = false;
          }
        });

      }
    }

  }


  cancelDefaultRules() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Payroll/payrollPolicies"]));
  }
  editDefaultRules() {

    this.isEditDefaultRules = true;
    this.payrollPoliciesForm.controls.noOfInstallments.enable();
    this.payrollPoliciesForm.controls.monthsToResumeLastRecovery.enable();
    this.payrollPoliciesForm.controls.otAmountIncludeSalary.enable();
    this.payrollPoliciesForm.controls.isCompanyCoveredUnderGratuityAct.enable();
    this.payrollPoliciesForm.controls.isGratuityMonthlyPaid.enable();
    this.payrollPoliciesForm.controls.isLOPdeductionBasedOnCalendar.enable();
    this.payrollPoliciesForm.controls.isAbsentConsiderLop.enable();
    this.payrollPoliciesForm.controls.isDynamicPayrollApplicable.enable();
    this.payrollPoliciesForm.controls.leavesThresholdForDynamicPayroll.enable();
    this.payrollPoliciesForm.controls.esiAndEpfContributionIndependentOfLOP.enable();
    this.payrollPoliciesForm.controls.OTMinExtraHours.enable();
    this.payrollPoliciesForm.controls.variablePaySequence.enable();
    this.payrollPoliciesForm.controls.lopDaysProportionate.enable();
    this.payrollPoliciesForm.controls.extraWorkingDays.enable();
    this.payrollPoliciesForm.controls.IS_SALARY_CALCULATION_FOR_THIRTY_DAYS.enable();
    this.payrollPoliciesForm.controls.ENABLE_COMP_DEDUCTIONS_AND_REIMBURSEMENTS_FOR_EMP.enable();

    for (let i = 0; i < this.defaultRuleInfo.length; i++) {

      if (this.defaultRuleInfo[i].rule_name == 'NUMBER_OF_INSTALLMENTS_FOR_ADV_SAL_RECOVERY') {
        this.payrollPoliciesForm.controls.noOfInstallments.setValue(this.defaultRuleInfo[i].value)
      }
      else if (this.defaultRuleInfo[i].rule_name == 'MONTHS_TO_RESUME_ADV_SAL_AFTER_LAST_RECOVERY') {
        this.payrollPoliciesForm.controls.monthsToResumeLastRecovery.setValue(this.defaultRuleInfo[i].value)

      }
      else if (this.defaultRuleInfo[i].rule_name == 'OVER_TIME_AMOUNT_TO_BE_INCLUDED_IN_SALARY') {
        this.payrollPoliciesForm.controls.otAmountIncludeSalary.setValue(this.defaultRuleInfo[i].value)

      }
      else if (this.defaultRuleInfo[i].rule_name == 'IS_COMPANY_COVERED_UNDER_GRATUITY_ACT') {
        this.payrollPoliciesForm.controls.isCompanyCoveredUnderGratuityAct.setValue(this.defaultRuleInfo[i].value)

      }
      else if (this.defaultRuleInfo[i].rule_name == 'IS_GRATUITY_MONTHLY_PAID') {
        this.payrollPoliciesForm.controls.isGratuityMonthlyPaid.setValue(this.defaultRuleInfo[i].value)

      }
      else if (this.defaultRuleInfo[i].rule_name == 'IS_LOP_DEDUCTION_CALCULATION_BASED_ON_30_DAY_CALENDAR') {
        this.payrollPoliciesForm.controls.isLOPdeductionBasedOnCalendar.setValue(this.defaultRuleInfo[i].value)

      } else if (this.defaultRuleInfo[i].rule_name == 'IS_ABSENT_CONSIDERED_AS_LOP') {
        this.payrollPoliciesForm.controls.isAbsentConsiderLop.setValue(this.defaultRuleInfo[i].value)

      } else if (this.defaultRuleInfo[i].rule_name == 'IS_DYNAMIC_PAYROLL_PRCESSING_APPLICABLE') {
        this.payrollPoliciesForm.controls.isDynamicPayrollApplicable.setValue(this.defaultRuleInfo[i].value)

      } else if (this.defaultRuleInfo[i].rule_name == 'NUMBER_OF_LEAVES_THRESHOLD_FOR_DYNAMIC_PAYROLL_PROCESSING') {
        this.payrollPoliciesForm.controls.leavesThresholdForDynamicPayroll.setValue(this.defaultRuleInfo[i].value)

      } else if (this.defaultRuleInfo[i].rule_name == 'ESI_AND_EPF_CONTRIBUTION_INDEPENDENT_OF_LOP') {
        this.payrollPoliciesForm.controls.esiAndEpfContributionIndependentOfLOP.setValue(this.defaultRuleInfo[i].value)

      }
      else if (this.defaultRuleInfo[i].rule_name == 'MINIMUM_EXTRA_HOURS_TO_CONSIDER_FOR_OVER_TIME') {
        this.payrollPoliciesForm.controls.OTMinExtraHours.setValue(this.defaultRuleInfo[i].value);

      } else if (this.defaultRuleInfo[i].rule_name == 'VARIABLE_PAY_FREQUENCY_IN_MONTHS') {
        this.payrollPoliciesForm.controls.variablePaySequence.setValue(this.defaultRuleInfo[i].value);

      } else if (this.defaultRuleInfo[i].rule_name == 'MINIMUM_LOP_DAYS_FOR_PROPORTIONATE_WEEKOFF_DEDUCTION') {
        this.payrollPoliciesForm.controls.lopDaysProportionate.setValue(this.defaultRuleInfo[i].value);
      } else if (this.defaultRuleInfo[i].rule_name == 'IS_PAYMENT_GIVEN_FOR_EXTRA_WORKING_DAYS') {
        this.payrollPoliciesForm.controls.extraWorkingDays.setValue(this.defaultRuleInfo[i].value);
      }
      else if (this.defaultRuleInfo[i].rule_name == 'IS_SALARY_CALCULATION_FOR_THIRTY_DAYS') {
        this.payrollPoliciesForm.controls.IS_SALARY_CALCULATION_FOR_THIRTY_DAYS.setValue(this.defaultRuleInfo[i].value);
      } else if (this.defaultRuleInfo[i].rule_name == 'ENABLE_COMP_DEDUCTIONS_AND_REIMBURSEMENTS_FOR_EMP') {
        this.payrollPoliciesForm.controls.ENABLE_COMP_DEDUCTIONS_AND_REIMBURSEMENTS_FOR_EMP.setValue(this.defaultRuleInfo[i].value);
      }
    }
  }
  preventPlusMinus(event: KeyboardEvent): void {
    if (event.key === '+' || event.key === '-') {
      event.preventDefault();
    }
  }

  limitDecimal(event: Event): void {
    const input = event.target as HTMLInputElement;
    const regex = /^\d+(\.\d{0,2})?$/;

    if (!regex.test(input.value)) {
      input.value = input.value.slice(0, input.value.indexOf('.') + 3);
    }
  }


}
