  async  getTrakckingDetails() {
    this.spinner.show();
    this.markerPositions = [];
    this.last_attd_data = [];
    this.attd_data = [];
    this.trackdata = [];
    let obj = {
      rmid:this.userSession.roles[0].rmid ?? '',      
      empid:this.userSession.id,
      tracking_type:'ALL',
      date_selected:this.pipe.transform(this.currentDate, 'yyyy-MM-dd')
    }
     
    this.crm.getCrmAttendanceTrackingDetails(obj).subscribe(async (info: any) => {
      this.spinner.hide();
      if (info.status && info.data.length != 0) {
        this.trackdata = info.data;
        let level = 0;
        this.trackdata.forEach(async (e: any) => {
              e.level = level;
              this.attd_data[level] = this.attd_data[level] || {};
              this.attd_data[level][e.category] = e.punchtime;
              this.attd_data[level][e.category+'_data'] = JSON.stringify(e);
              level = e.category == 'out' ? level+1 : level;
          });
        
          if(this.attd_data && this.attd_data.length && !this.attd_data[this.attd_data.length-1].out){
            this.last_attd_data = this.attd_data[this.attd_data.length-1];
            this.attd_data[this.attd_data.length-1].is_last = 1;
          }
          
        }
      })
     
  }

  
