  async getClientLocationFromMap_promise() {
    let location_result: any = { address: null, error: null };
  
    return new Promise((resolve, reject) => {
      this.location = null;
      this.selected_location = { lat: null, lng: null };
  
      navigator.geolocation.getCurrentPosition(
        (position) => {
          this.selected_location = {
            lat: position.coords.latitude,
            lng: position.coords.longitude,
          };
  
          let lat = Number(this.selected_location.lat);
          let lng = Number(this.selected_location.lng);
  
          // Perform geocoding
          this.geocoder.geocode(
            { location: { lat, lng } },
            (results: any, status: any) => {
              if (status === google.maps.GeocoderStatus.OK && results && results[0]) {
                this.location = results[0].formatted_address;
                location_result.address = results[0].formatted_address;
                resolve(location_result); // Resolve with the result
              } else {
                location_result.error = 'Geocoding failed.';
                reject(location_result); // Reject with the error
              }
            }
          );
        },
        (error) => {
          // Handle geolocation errors
          if (error.code === 1) {
            location_result.error = 'Location access denied by user.';
          } else if (error.code === 2) {
            location_result.error = 'Location information is unavailable.';
          } else if (error.code === 3) {
            location_result.error = 'Location request timed out.';
          } else {
            location_result.error = 'An unknown error occurred.';
          }
          reject(location_result); // Reject with the error
        }
      );
    });
  }
 
