import { Injectable, LOCALE_ID, Inject } from '@angular/core';
import jsPDF from 'jspdf';
import { CompanySettingService } from '../companysetting.service';
import autoTable from 'jspdf-autotable';
import { DatePipe } from '@angular/common';
@Injectable({
  providedIn: 'root'
})
export class PdfHeaderService {
  companyDBName: any;
  companyDetails: any;
  cmpName: any;
  cmpAddress: any;
  pipe: any;
  userSession: any;
  currentWorkLocation: any = [];
  constructor(@Inject(LOCALE_ID) private locale: string, private css: CompanySettingService, public datePipe: DatePipe,) {
    this.companyDBName = sessionStorage.getItem('companyName');
    this.getCompanyInformation();
    this.pipe = new DatePipe(this.locale);
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
  }
  getCompanyInformation() {
    this.css.getCompanyInformation('companyinformation', null, 1, 10, this.companyDBName).subscribe((data: any) => {
      if (data.status && data.data.length != 0) {
        this.companyDetails = data.data[0];
        this.cmpName = this.companyDetails?.companyname;
        this.cmpAddress = this.companyDetails?.address1 + ',' + this.companyDetails?.city;
      } else {
      }

    })

  }
  generatePDFHeader(
    doc: jsPDF,
    reportName: string,
    location: string,
    managerName: string,
    rtDate: any,
    islocation: boolean,
    isEmployee: boolean
  ): void {
    const pageWidth = doc.internal.pageSize.getWidth();
    let yPosition = 15; // Initial Y position

    // **Company Name - Centered**
    doc.setFontSize(16);
    doc.setFont("helvetica", "bold");
    const companyNameWidth = doc.getTextWidth(this.cmpName);
    doc.text(this.cmpName, (pageWidth - companyNameWidth) / 2, yPosition);
    yPosition += 8; // Move Y down dynamically

    // **Report Name - Left-Aligned**
    doc.setFont("helvetica", "normal");
    doc.setFontSize(12);
    doc.text(reportName, 14, yPosition);

    // **Date - Right-Aligned**
    const formattedDate = `Date: ${rtDate}`;
    doc.text(formattedDate, pageWidth - 14, yPosition, { align: "right" });
    yPosition += 6; // Move down

    if (islocation) {
      // **Location - Left-Aligned**
      doc.setFontSize(12);
      doc.text(`Location: ${location}`, 14, yPosition);

      if (managerName && managerName.trim() !== "") {
        doc.text(`Manager: ${managerName}`, pageWidth - 14, yPosition, { align: "right" });
      }
      yPosition += 6; // Add space after location and manager
    } else if (isEmployee) {
      // **Employee Name - Left-Aligned**
      doc.setFontSize(12);
      doc.text(`Employee Name: ${managerName}`, 14, yPosition);

      yPosition += 6; // Add space after employee name
    }

    // **Draw Line Only If Necessary**
    doc.setLineWidth(0.5);
    doc.line(14, yPosition, pageWidth - 14, yPosition);
  }

  getFormattedDateTime(date: any = null, type: any = 'date') {
    if (date && date.toString().length) {
      date = new Date(date);
      if (type == 'datetime')
        return this.pipe.transform(date, 'dd-MM-yyyy') + ' ' + date.toLocaleTimeString(this.locale, { hour12: true, hour: '2-digit', minute: '2-digit' });
      if (type == 'date')
        return this.pipe.transform(date, 'dd-MM-yyyy');
    }
    else return '';
  }

  generatePDF_common(orientation: any, reportName: any, selections: any, tables: any, file_name: any, set_color: any = 0) {
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    let locationId = this.userSession.worklocation_id || 0;
    this.css.getSprypleData({ id: locationId }, 'get_branch_and_company_details').subscribe((result) => {
      if (result && result.status && result.data && result.data[0]) {
        this.currentWorkLocation = {
          branch: result.data[0].location_details ? JSON.parse(result.data[0].location_details) : null,
          company: result.data[0].company_details ? JSON.parse(result.data[0].company_details) : null
        }
        this.generatePDF(orientation, reportName, selections, tables, file_name, set_color);
      }
    })
  }

  generatePDF(orientation: any, reportName: any, selections: any, tables: any, file_name: any, set_color: any = 0) {
    if (orientation && orientation != '') {
      orientation = (orientation != 'portrait') && (orientation != 'landscape') ? 'portrait' : orientation;
    } else orientation = 'portrait'
    let doc = new jsPDF({ orientation: orientation });
    let pageWidth = Number(doc.internal.pageSize.getWidth().toFixed(2)); 
    let printed_on = `Printed on: ${this.getFormattedDateTime(new Date())}`;
    let company: any = this.currentWorkLocation.company && this.currentWorkLocation.company[0] ? this.currentWorkLocation.company[0] : null;
    let companyname = company?.companyname || ''
    let branch: any = this.currentWorkLocation.branch && this.currentWorkLocation.branch[0] ? this.currentWorkLocation.branch[0] : null;
    let company_address = `${company?.address1} ${company?.address1 ? ', ' : ''} ${company?.address2}`;
    let branch_address = branch ? ((branch.address1 || '') + (branch.address1 ? ', ' : '') + (branch.address2 || '')) : (company_address);
    company_address = 'Main Branch: ' + company_address;
    let company_others = '';
    for (let i = 0; i < 5; i++) {
      if (company?.add_gstnumber == i)
        company_others = company_others + (company_others.toString().length ? ', ' : '') + (company?.add_gstnumber ? ('GSTIN: ' + company?.gstnumber || '') : '');
      if (company?.add_primarycontact == i)
        company_others = company_others + (company_others.toString().length ? ', ' : '') + (company?.add_primarycontact ? ('Phone: ' + company?.primarycontact || '') : '');
      if (company?.add_primaryemail == i)
        company_others = company_others + (company_others.toString().length ? ', ' : '') + (company?.add_primaryemail ? ('e-mail: ' + company?.primaryemail || '') : '');
      if (company?.add_website == i)
        company_others = company_others + (company_others.toString().length ? ', ' : '') + (company?.add_website ? ('Website: ' + company?.companywebsite || '') : '');
    }
    let finalY = company_others == '' ? 35 : 40;
    if (orientation === 'portrait' && doc.getTextWidth(branch_address) > doc.internal.pageSize.width) {
      finalY = company_others == '' ? 40 : 45;
    }
    let userRole: any = (tables && tables[0] && tables[0].userRole) ? tables[0].userRole : '';
    let is_super_admin: any = !!(this.userSession.is_super_admin && this.userSession.is_super_admin == 1);
    if (is_super_admin || userRole == 'Finance') {
      finalY = finalY + 10;
    }
    let header_height = finalY;
    let footer_text = '';
    let selectionText = doc.setFontSize(9).splitTextToSize(selections, pageWidth-20); 
    let selection_head = 5;
    selectionText?.forEach((s:any)=>{
      if(s != "") selection_head = selection_head + 5;
    });
    selection_head = selection_head/2;       
   
tables?.forEach((table: any, index: any) => {
  footer_text = table.footer_text || '';

  // ------------------------------------------
  // FIX: Calculate Page-1 header height
  // ------------------------------------------
  let headerHeight = 12;

  doc.setFontSize(16);
  headerHeight += 7;

  let branchWrapped = doc.splitTextToSize(branch_address, pageWidth - 20);
  headerHeight += branchWrapped.length * 5;

  if (company_others) {
    let othersWrapped = doc.splitTextToSize(company_others, pageWidth - 20);
    headerHeight += othersWrapped.length * 5;
  }

  headerHeight += 10;  // line + spacing
  headerHeight += 7;   // report name + printed on

  let selectionWrapped = doc.splitTextToSize(selectionText, pageWidth - 20);
  headerHeight += selectionWrapped.length * 5;

  if (headerHeight < 50) headerHeight = 50; // safety

  // ------------------------------------------
  // Now draw table (first page gets correct padding)
  // ------------------------------------------
  autoTable(doc, {
    head: [table.headers],
    body: table.body,
    margin: { 
      top: headerHeight,   // ✔ FIXED
      right: table.side_margin?table.side_margin:10,
      bottom: 10,
      left: table.side_margin?table.side_margin:10
    },
    columnStyles: table.widths,
    styles: { fontSize: table.cellFontSize || 9,cellPadding: table.cellPadding || 1, lineWidth: 0.01 },
    
        didDrawPage: (data) => {
  
  let pageWidth = doc.internal.pageSize.getWidth();
  let marginLeft = table.side_margin?table.side_margin:10;
  let y = 12; // Starting top margin

  // --- COMPANY NAME ---
  doc.setFontSize(16).setFont("helvetica", "bold");
  doc.text(companyname || "", pageWidth / 2, y, { align: "center" });
  y += 7;

  // --- BRANCH ADDRESS WITH WRAP ---
  let branchText = doc.splitTextToSize(branch_address || "", pageWidth - 20);
  doc.setFontSize(9).setFont("helvetica", "normal");
  doc.text(branchText, pageWidth / 2, y, { align: "center" });
  y += branchText.length * 5;

  // --- COMPANY OTHERS (GST, Phone, Email, Website) ---
  if (company_others) {
    let otherLines = doc.splitTextToSize(company_others, pageWidth - 20);
    doc.setFontSize(9);
    doc.text(otherLines, pageWidth / 2, y, { align: "center" });
    y += otherLines.length * 5;
  }

  // --- HORIZONTAL LINE ---
  doc.setLineWidth(0.3);
  doc.line(10, y + 2, pageWidth - 10, y + 2);
  y += 10;

  // --- REPORT TITLE ---
  doc.setFontSize(13).setFont("helvetica", "bold");
  doc.text(reportName, pageWidth / 2, y, { align: "center" });
  
  // --- PRINTED ON (RIGHT) ---
  doc.setFontSize(9);
  let selectionText = selections;
  doc.text(printed_on, pageWidth - 10, y, { align: "right" });
  y += 7;

  // --- SELECTION TEXT (Wrapped) ---
  doc.setFontSize(9);
  let selectionLines = doc.splitTextToSize(selectionText, pageWidth - 20);
  doc.text(selectionLines, 10, y);

  // Tell AutoTable where to start table  
  data.settings.margin.top = y + selectionLines.length * 5;

}

      });
      finalY = (doc as any).lastAutoTable.finalY + 5;
    });
    let totalPages = doc.getNumberOfPages();
    for (let i = 1; i <= totalPages; i++) {
      doc.setPage(i);
      const pageStr = `Page ${i} of ${totalPages}`;
      if(footer_text != '')  doc.setFontSize(8).text(footer_text, 10, doc.internal.pageSize.height - 5, { align: 'left' });
      doc.setFontSize(8).text(pageStr, doc.internal.pageSize.width - 10, doc.internal.pageSize.height - 5, { align: 'right' });
    }
    doc.save(file_name);
  }

    generatePDF_grid(orientation: any, reportName: any, selections: any, tables: any, file_name: any, set_color: any = 0) {
    if (orientation && orientation != '') {
      orientation = (orientation != 'portrait') && (orientation != 'landscape') ? 'portrait' : orientation;
    } else orientation = 'portrait'
    let doc = new jsPDF({ orientation: orientation });
    let pageWidth = Number(doc.internal.pageSize.getWidth().toFixed(2)); 
    let printed_on = `Printed on: ${this.getFormattedDateTime(new Date())}`;
    let company: any = this.currentWorkLocation.company && this.currentWorkLocation.company[0] ? this.currentWorkLocation.company[0] : null;
    let companyname = company?.companyname || ''
    let branch: any = this.currentWorkLocation.branch && this.currentWorkLocation.branch[0] ? this.currentWorkLocation.branch[0] : null;
    let company_address = `${company?.address1} ${company?.address1 ? ', ' : ''} ${company?.address2}`;
    let branch_address = branch ? ((branch.address1 || '') + (branch.address1 ? ', ' : '') + (branch.address2 || '')) : (company_address);
    company_address = 'Main Branch: ' + company_address;
    let company_others = '';
    for (let i = 0; i < 5; i++) {
      if (company?.add_gstnumber == i)
        company_others = company_others + (company_others.toString().length ? ', ' : '') + (company?.add_gstnumber ? ('GSTIN: ' + company?.gstnumber || '') : '');
      if (company?.add_primarycontact == i)
        company_others = company_others + (company_others.toString().length ? ', ' : '') + (company?.add_primarycontact ? ('Phone: ' + company?.primarycontact || '') : '');
      if (company?.add_primaryemail == i)
        company_others = company_others + (company_others.toString().length ? ', ' : '') + (company?.add_primaryemail ? ('e-mail: ' + company?.primaryemail || '') : '');
      if (company?.add_website == i)
        company_others = company_others + (company_others.toString().length ? ', ' : '') + (company?.add_website ? ('Website: ' + company?.companywebsite || '') : '');
    }
    let finalY = company_others == '' ? 35 : 40;
    if (orientation === 'portrait' && doc.getTextWidth(branch_address) > doc.internal.pageSize.width) {
      finalY = company_others == '' ? 40 : 45;
    }
    let userRole: any = (tables && tables[0] && tables[0].userRole) ? tables[0].userRole : '';
    let is_super_admin: any = !!(this.userSession.is_super_admin && this.userSession.is_super_admin == 1);
    if (is_super_admin || userRole == 'Finance') {
      finalY = finalY + 10;
    }
    let header_height = finalY;
    let footer_text = '';
    let selectionText = doc.setFontSize(9).splitTextToSize(selections, pageWidth-20); 
    let selection_head = 5;
    selectionText?.forEach((s:any)=>{
      if(s != "") selection_head = selection_head + 5;
    });
    selection_head = selection_head/2;       
   
    tables?.forEach((table: any, index: any) => {
      footer_text = table.footer_text||'';
      doc.setFontSize(10).text(table.sub_head, 10, finalY + selection_head - 2.5, { align: table.headers_align? table.headers_align: 'left' });
      autoTable(doc, {
        head: [table.headers],
        body: table.body,
        startY: finalY + selection_head,
        //columnStyles: {...table.widths,6: { halign:index == 1 ? 'right':'left' }, 7: { halign: index == 1 ? 'right':'left'}}, 
        columnStyles: table.widths,
        margin: { top: header_height + selection_head , right: table.side_margin?table.side_margin:10, bottom: 10, left: table.side_margin?table.side_margin:10 },
        styles: { fontSize: table.cellFontSize || 9, cellPadding: table.cellPadding || 1, lineWidth: 0.01, lineColor: [169, 169, 169] },
        headStyles: { fontSize: table.headFontSize || 10 },
        willDrawCell: (data) => {
          if (set_color) {
            let { row, column, cell } = data;
            let rowData: any = row.raw;
            if (row.section === 'head') doc.setTextColor(255, 255, 255);
            else if (table.table_name == 'tracking' && rowData && rowData[3]) {
              let text_color = this.setTextColorByName(rowData[3].toString());
              doc.setTextColor(...text_color);
            } else doc.setTextColor(0, 0, 0); // Default text color (black)
          }
        },
        didDrawPage: (data: any) => {
          let doc_height = 10;
          if (data.pageNumber > 1) {
            doc.setFontSize(10).text("Contd...", 10, doc_height - 5, { align: "left" });
          }

          // Company Name
          doc.setFontSize(16).text(companyname, pageWidth / 2, doc_height, { align: 'center' });

          // --- Wrap Branch Address ---
          let branchAddressText = doc.setFontSize(9).splitTextToSize(branch_address, pageWidth-20); // leave some margin
          doc.setFontSize(9).text(branchAddressText,pageWidth/2, doc_height + 5, { align: 'center' });
          doc_height += branchAddressText.length * 5; // move cursor down depending on wrapped lines

          // --- Company Others ---
          if (company_others != '') {
            let companyOthersText = doc.setFontSize(10).splitTextToSize(company_others, pageWidth - 20);
            doc.setFontSize(10).text(companyOthersText, pageWidth / 2, doc_height + 5, { align: 'center' });
            doc_height += companyOthersText.length * 5;
          }
          // Horizontal Line
          doc.line(2, doc_height + 2, pageWidth - 2, doc_height + 2);
          // Report Title
          doc.setFontSize(14).text(reportName, pageWidth / 2, doc_height + 10, { align: 'center' });
          // Printed On (Right aligned)
          doc.setFontSize(9).text(printed_on, pageWidth - 10, doc_height + 10, { align: 'right' });
          // --- Wrap Selections ---
          doc.setFontSize(9).text(selectionText, 10, doc_height + 15, { align: 'left' });      
        }
      });
      finalY = (doc as any).lastAutoTable.finalY + 5;
    });
    let totalPages = doc.getNumberOfPages();
    for (let i = 1; i <= totalPages; i++) {
      doc.setPage(i);
      const pageStr = `Page ${i} of ${totalPages}`;
      if(footer_text != '')  doc.setFontSize(8).text(footer_text, 10, doc.internal.pageSize.height - 5, { align: 'left' });
      doc.setFontSize(8).text(pageStr, doc.internal.pageSize.width - 10, doc.internal.pageSize.height - 5, { align: 'right' });
    }
    doc.save(file_name);
  }

  setTextColorByName(duration: string) {
    let totalMinutes = 0;
    let color = 'black';
    let colorRange: any = [
      { min: 0, max: 5, color: 'black' }, { min: 5, max: 10, color: 'blue' }, { min: 10, max: 15, color: 'pink' }, { min: 15, max: 20, color: 'gray' }, { min: 20, max: -1, color: 'red' }
    ];
    let colorMap: { [key: string]: [number, number, number] } = {
      'red': [255, 0, 0], 'green': [0, 255, 0], 'blue': [0, 0, 255], 'yellow': [255, 255, 0], 'black': [0, 0, 0], 'white': [255, 255, 255], 'gray': [169, 169, 169],
    };

    if (duration && duration.toString().length) {
      let hoursMatch = duration.match(/(\d+)\s*hours?/);
      let minutesMatch = duration.match(/(\d+)\s*min/);
      let secondsMatch = duration.match(/(\d+)\s*sec/);
      let hours = hoursMatch ? parseInt(hoursMatch[1], 10) : 0;
      let minutes = minutesMatch ? parseInt(minutesMatch[1], 10) : 0;
      let seconds = secondsMatch ? parseInt(secondsMatch[1], 10) : 0;
      totalMinutes = (hours ? (hours * 60) : 0) + (minutes ? minutes : 0) + (seconds ? Math.floor(seconds / 60) : 0); // Total minutes
    }

    let set_color = false;
    colorRange.forEach((c: any) => {
      if (totalMinutes >= c.min && !set_color) {
        if (c.max == -1 || totalMinutes < c.max) {
          color = c.color;
          set_color = true;
        }
      }
    });
    return colorMap[color.toLowerCase()] || [0, 0, 0]; // Default to black if color not found
  }

  formatCell(cell: any, colIndex: any, index: any, table_name: any, format_string: boolean = false): any {
    // let currencySymbol = '₹';
    let val: any = `${cell}`;
    if (format_string) {
      let value = parseFloat(cell);
      let formattedValue = new Intl.NumberFormat('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2, }).format(value);
      return { content: formattedValue, styles: { halign: 'right' } };
    } else if (!isNaN(val)) {
      return { content: `${cell}`, styles: { halign: 'right' } };
    }
    return { content: `${cell}` };
  }

}
