import { Component, OnInit, ViewChild } from '@angular/core';
import { FormControl, FormGroup, UntypedFormBuilder, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { PayrollService } from '../../payroll.service';
import { MatTableDataSource } from '@angular/material/table';
import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { AnyARecord } from 'dns';

@Component({
  selector: 'app-employee-hourly-pay-configure',
  templateUrl: './employee-hourly-pay-configure.component.html',
  styleUrls: ['./employee-hourly-pay-configure.component.scss']
})
export class EmployeeHourlyPayConfigureComponent implements OnInit {
  hourlyPayForm!: FormGroup;
  userSession: any;
  constructor(
    private formBuilder: UntypedFormBuilder,
    private payrollService: PayrollService,
    private dialogService: ReusableDialogService,
    private router: Router,
  ) {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
  }
  displayedColumns: string[] = ['sno', 'empname', 'designation', 'location', 'hourly_pay_value', 'action'];
  dataSource: MatTableDataSource<any> = <any>[];
  @ViewChild('paginator') paginator!: MatPaginator;
  @ViewChild('sort') sort!: MatSort;
  pageSizeOptions: number[] = [5, 10, 20];
  filteredEmployees: any = [];
  searchControl = new FormControl('');
  employeeId: any;
  btnDisable: boolean = false;
  empdata: any = [];
  hourlyPayrollOptions: any = [];
  options: any[] = [];
  selectedOptions: any[] = [];
  isUpdate: boolean = false;
  selectedId: any;
  ngOnInit(): void {
    this.getEmployeesForAssignPaygroup();
    this.getOptionsForHourlyPayroll();
    this.hourlyPayForm = this.formBuilder.group(
      {
        empName: ["", Validators.required],
        amount: ["", Validators.required],
        professionalTax: [""],
        tds: [""],
        editEmpName: [""],
      })
    this.hourlyPayForm.get('empName')?.valueChanges.subscribe((selectedValue: any) => {

      this.employeeId = selectedValue;

    });
    this.searchControl.valueChanges.subscribe(searchText => {
      this.filterLocations(searchText);
    });
    this.getEmployeeHourlyList();
  }

  getEmployeesForAssignPaygroup() {
    this.empdata = [];
    this.payrollService.getEmployeesForHourlyPay().subscribe((result: any) => {
      if (result.status && result.data.length > 0) {
        this.empdata = result.data;
        this.filteredEmployees = this.empdata
      }
    })
  }
  getOptionsForHourlyPayroll() {
    this.hourlyPayrollOptions = [];
    this.payrollService.getOptionsForHourlyPayroll().subscribe((result: any) => {
      if (result.status && result.data.length > 0) {
        this.hourlyPayrollOptions = result.data;
      }
    })
  }
  onCheckboxChange(event: any, option: any) {
    if (event.target.checked) {
      this.selectedOptions.push(option);
    } else {
      const index = this.selectedOptions.indexOf(option);
      if (index > -1) {
        this.selectedOptions.splice(index, 1);
      }
    }
  }

  submit() {
    if (this.hourlyPayForm.valid) {
      const formData = this.hourlyPayForm.value;
      let payload = {
        id_value: this.isUpdate ? this.selectedId : null,
        employee_id_value: formData.empName,
        hourly_pay: formData.amount,
        pt_deductible_value: formData.professionalTax ? 1 : 0,
        tds_deductible_value: formData.tds ? 1 : 0,
        created_by_value: this.userSession.id
      }
      this.payrollService.setEmployeeHourlyPay(payload).subscribe((res: any) => {
        if (res.status && res.data.length > 0) {
          let result = res.data[0];
          this.dialogService.openDialog(result.message);
          this.clear();
        } else {

          this.dialogService.openDialog('There is an issue. Please try again.');
          this.clear();
        }
      })
    }
  }
  clear() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(['/Payroll/addHourlyPay']));
  }

  getHourlyPayEmployeeDetails() {
    this.empdata = [];
    this.payrollService.getHourlyPayEmployeeDetails().subscribe((result: any) => {
      if (result.status && result.data.length > 0) {
        this.empdata = result.data;
        this.filteredEmployees = this.empdata
      }
    })
  }

  filterLocations(searchText: any) {
    this.filteredEmployees = this.empdata.filter((val: any) =>
      val.empid.toLowerCase().includes(searchText.toLowerCase()) ||
      val.empname.toLowerCase().includes(searchText.toLowerCase())
    );
  }
  getEmployeeHourlyList() {
    let list: any = [];
    this.payrollService.getHourlyPayEmployeeDetails().subscribe((info: any) => {
      if (info.status && info.data.length !== 0) {
        list = info.data;
        this.dataSource = new MatTableDataSource(list);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.getPageSizes();
      } else {
        list = [];
        this.dataSource = new MatTableDataSource(list);
      }
    })
  }
  edit(data: any) {
    this.isUpdate =true;
    this.selectedId = data.hourly_pay_id;
    this.hourlyPayForm.patchValue({
      editEmpName:data.employee_name,
      empName:data.employee_id,
      amount:parseFloat(data.hourly_pay_value),
      professionalTax:data.pt_deductible,
      tds:data.tds_deductible,
   })
  }

  getPageSizes() {
    const customPageSizeArray: number[] = [];
    const dataLength = this.dataSource?.data?.length || 0;

    if (dataLength > 5) {
      customPageSizeArray.push(5);
    }
    if (dataLength > 10) {
      customPageSizeArray.push(10);
    }
    if (dataLength > 30) {
      customPageSizeArray.push(30);
    }

    if (dataLength > 0) {
      customPageSizeArray.push(dataLength);
    }

    this.pageSizeOptions = customPageSizeArray;
  }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }
}
