import { DatePipe } from '@angular/common';
import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, FormControl, UntypedFormControl, UntypedFormGroup, Validators } from '@angular/forms';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { MatDatepicker, MatDatepickerInputEvent } from '@angular/material/datepicker';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { Router } from '@angular/router';
import * as XLSX from 'xlsx';
import { ReportsService } from '../../reports.service';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import * as _moment from 'moment';
import { Moment } from 'moment';
import { MatDialog } from '@angular/material/dialog';
import { EmsService } from 'src/app/modules/ems/ems.service';
const moment = _moment;
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { PdfHeaderService } from 'src/app/services/pdf-header-service/pdf-header.service';
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
@Component({
  selector: 'app-hr-missed-punch-out-report',
  templateUrl: './hr-missed-punch-out-report.component.html',
  styleUrls: ['./hr-missed-punch-out-report.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },

    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})



export class HrMissedPunchOutReportComponent implements OnInit {
  @ViewChild('table') table!: ElementRef;
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort) sort!: MatSort;

  searchForm: any = UntypedFormGroup;
  employeelist: any = [];
  arrayList: any = [];
  minFromDate: Date | undefined;
  maxFromDate: Date | undefined;
  minToDate: Date | null;
  maxToDate: Date | undefined;
  currentDate: Date = new Date();
  List: any[] = [
  ];
  dataSource: MatTableDataSource<any> = <any>[];
  displayedColumns: string[] = ['sno', 'empid', 'empname','attendancedate','intime', 'location'];
  pageLoading = true;
  searchControl = new FormControl('');
  empSearchControl = new FormControl('');
  filteredEmployees: any = [];
  userSession: any;
  isLoading = false;
  locationList: any = [];
  filteredLocations: any = [];
  companyDBName: any;
  date: any;
  minDate: any = new Date('2000-01-01');
  max = this.getEndOfMonth(new Date());
  monthfirstDay: any;
  monthLastDay: any;
  /**Here select Month and Date from month year picker */
  setMonthAndYear(normalizedMonthAndYear: Moment, datepicker: MatDatepicker<Moment>) {
    const ctrlValue = this.date.value!;
    ctrlValue.month(normalizedMonthAndYear.month());
    ctrlValue.year(normalizedMonthAndYear.year());
    this.date.setValue(ctrlValue);
    datepicker.close();
  }
  months = [{ id: 0, month: 'Jan' }, { id: 1, month: 'Feb' }, { id: 2, month: 'Mar' }, { id: 3, month: 'Apr' }, { id: 4, month: 'May' }, { id: 5, month: 'Jun' }, { id: 6, month: 'Jul' }, { id: 7, month: 'Aug' }, { id: 8, month: 'Sep' }, { id: 9, month: 'Oct' }, { id: 10, month: 'Nov' }, { id: 11, month: 'Dec' }]
  locationName:any;
  cityName:any;
  locationFullName:any;

  constructor(
    private formBuilder: FormBuilder,
    private router: Router,
    public datePipe: DatePipe,
    private reportsService: ReportsService,
    private companyService: CompanySettingService,
    public dialog: MatDialog,
    private emsService: EmsService,
    private pdfService: PdfHeaderService,
  ) {

    this.minFromDate = new Date();
    this.minFromDate.setDate(this.currentDate.getDate() - 90);
    this.maxFromDate = new Date();
    this.minToDate = new Date();
    this.minToDate.setDate(this.currentDate.getDate() - 90);
    this.maxToDate = new Date();
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    this.getWorkLocation();

  }

  ngOnInit(): void {
    this.searchForm = this.formBuilder.group({
      employees: ['0', Validators.required],
      fromDate: [new Date(), Validators.required],
      toDate: [this.max, Validators.required],
      location: [0, Validators.required],
    });
    /** */
    this.searchForm.get('location')?.valueChanges.subscribe((selectedValue: any) => {
    this.getEmployeelist(selectedValue)  ;
    if(selectedValue == 0){
      this.locationFullName = 'All Locations'
    } else{
      const selectedLocation = this.filteredLocations.find((loc:any) => loc.id === selectedValue);
      this.locationName = selectedLocation ? selectedLocation.location : '';
      this.cityName = selectedLocation ? selectedLocation.cityname : '';
      this.locationFullName = this.locationName +','+ this.cityName;
    }
 
    }) 
    /**This is used for drop down filters */
    this.searchControl.valueChanges.subscribe(searchText => {
      this.filterLocations(searchText);
    });

    this.empSearchControl.valueChanges.subscribe(searchText => {
      this.filterEmployees(searchText);
    });

    /** */
    
  
   
   

    // this.getEmployeelist();
    
    this.companyDBName = sessionStorage.getItem("companyName") ? sessionStorage.getItem("companyName") : null;
    this.date = new UntypedFormControl(moment())
    let prevDate = new Date();
    prevDate.setDate(0);
    // this.Searchform();
  }

  /** Function to get the end of the current month*/
  getEndOfMonth(date: Date): Date {
    const year = date.getFullYear();
    const month = date.getMonth();
    return new Date(year, month + 1, 0); // Last day of the current month
  }

  fromDateChange(type: string, event: MatDatepickerInputEvent<Date>) {
    this.minToDate = event.value;
    if (event.value !== null) {
      this.maxToDate = new Date(
      );
    }
  }
  /**Missed Punches Report*/
  Searchform() {
    var firstDay = new Date((this.date.value._d).getFullYear(), (this.date.value._d).getMonth(), 1);
    var lastDay = new Date((this.date.value._d).getFullYear(), (this.date.value._d).getMonth() + 1, 0);
    this.monthfirstDay = this.datePipe.transform(firstDay, "yyyy-MM-dd")
    this.monthLastDay = this.datePipe.transform(lastDay, "yyyy-MM-dd")
    let data = {
      "location_id":this.searchForm.controls.location.value==0?null:this.searchForm.controls.location.value,
      "employee_id":this.searchForm.controls.employees.value=='0'?null:this.searchForm.controls.employees.value,
      "calendar_date": this.monthfirstDay
    }
    this.arrayList = []
    this.dataSource = new MatTableDataSource()
    this.reportsService.getMissedOutPunchesReportHR(data).subscribe((res: any) => {
      if (res.status) {
        this.arrayList = res.data
        this.dataSource = new MatTableDataSource(res.data);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;
      }
    })

  }
  /**Clear Functionality */
  resetform() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Attendance/missedPunchOutReport"]));
  }

  exportAsXLSX() {
    /** */
    const ws: XLSX.WorkSheet = XLSX.utils.table_to_sheet(this.table.nativeElement);
    const wb: XLSX.WorkBook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Missed_Out_Punches_Report');

    /* save to file */
    XLSX.writeFile(wb,  'Missed_Out_Punches_Report for ' +this.datePipe.transform(new Date(), 'MMM yyyy') +'.xlsx');

  }

  getPageSizes(): number[] {

    var customPageSizeArray = [];
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  /**Drop Down Loactions Filter */
  filterLocations(searchText: any) {
    this.filteredLocations = this.locationList.filter((val: any) =>
      val.location.toLowerCase().includes(searchText.toLowerCase()) || 
      val.cityname.toLowerCase().includes(searchText.toLowerCase()) 
    );
    if (this.filteredLocations.length <= 0) {
      this.searchControl.setValue('');
    } else {

    }
  }

  /**Drop Down Employees Filter */
  filterEmployees(searchText: any) {
    this.filteredEmployees = this.employeelist.filter(
      (val: any) =>
        val.empid.toLowerCase().includes(searchText.toLowerCase()) ||
        val.ename.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredEmployees.length <= 0) {
      this.empSearchControl.setValue('');
    }
  }
  /**Get Employees List */

  getEmployeelist(data:any) {
    this.employeelist = [];
    let ldata:number = data == 0 ? null :data;
    this.emsService.getEmployeeDirectoryList(ldata).subscribe((res: any) => {
      if (res.status && res.data.length != 0) {
        this.employeelist = [];
        this.employeelist = res.data;
        this.filteredEmployees = this.employeelist
        this.searchForm.controls.employees.setValue('0');
      }
    })
  }

  /**Get All Active Work Locations */
  getWorkLocation() {
    this.companyService.getactiveWorkLocation({ id: null, companyName: this.companyDBName }).subscribe((result) => {
      this.locationList = result.data;
      this.filteredLocations = this.locationList;
      this.searchForm.controls.location.setValue(0);
      this.getEmployeelist(null)
    })
  }
  /**Table Search Functioanlity */
  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

generatePDF() {
  
  const doc = new jsPDF();
  const reportName = 'Missed Out Punch Report';
  let formattedDate: string;
  formattedDate = this.datePipe.transform(this.date.value._d, 'MMMM-yyyy') || '';

  let manager = '';
  let locationName = this.locationFullName;
  let reportDate = formattedDate;
  const headerHeight = 37;
  const tableData = this.arrayList.map((emp:  { 
    empcode: any;    
    empname: any;    
    attendancedate: any;  
    firstlogintime: any ;
    locationid: any; 
  }, index: number) => [
   
      index + 1,
    emp.empcode,
    emp.empname,
    this.datePipe.transform(emp.attendancedate,"dd-MM-yyyy"),
    this.datePipe.transform(emp.firstlogintime,"dd-MM-yyyy HH:mm"),
    emp.locationid,
    ]);
        autoTable(doc, {
          head: [['S. No.','Emp. ID','Emp. Name', 'Date','CheckIn Time','Attendance Source']],
          body:tableData,
          startY: headerHeight,
          styles: { fontSize: 10 },
          headStyles: { fontSize: 11 },
          margin: { top: headerHeight },
          didDrawPage: (data) => {
            this.pdfService.generatePDFHeader(doc, reportName,locationName,manager,reportDate,true,false);
            doc.setFontSize(10);
            doc.setTextColor(40);
          }
        });
     doc.save('missed_out_punches_report.pdf');
} 
}

