  exportAsXLSX() {
    const ws: XLSX.WorkSheet = XLSX.utils.table_to_sheet(
      document.getElementById('table'), {raw:true}
    );
   Object.keys(ws).forEach(cell => {
    if (cell[0] !== '!') {
      // Check if this is your Date of Joining column
      if (cell.startsWith('C')) { // change 'C' to your actual column letter
        const date = new Date(ws[cell].v);
        if (!isNaN(date.getTime())) {
          ws[cell].t = 'd'; // Excel date type
          ws[cell].v = date;
          ws[cell].z = 'dd-mm-yyyy'; // Apply date format in Excel
        }
      } else {
        ws[cell].t = 's'; // keep other columns as text
        ws[cell].v = ws[cell].v?.toString();
      }
    }
  });
    const wb: XLSX.WorkBook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Employee_Report');
    /* save to file */
    XLSX.writeFile(wb, 'Employee_Report.xlsx');
  }
