import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';

@Component({
  selector: 'app-chapters-screen',
  templateUrl: './chapters-screen.component.html',
  styleUrls: ['./chapters-screen.component.scss']
})
export class ChaptersScreenComponent implements OnInit {

  list: any = ['chapters', 'PDF', 'Links', 'tests', 'certificates']
  constructor(
    private router: Router,
  ) { }

  ngOnInit(): void {
  }
  navigationToChaptersScreen() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/learning/chaptersList']));
  }
  navigationToPDF() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/learning/coursePDF']));
  }
  navigationToLinks() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/learning/courseLinks']));
  }
  navigationToCertificates() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/learning/certificates']));
  }
  navigationToPrevScreen() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/learning/courseList']));
  }
}
