  /**For this CTC get paygroups */
  getPayGroupsForCtc() {
    if (this.Assignpaygroupform.valid) {
      let data = {
        ctc: this.Assignpaygroupform.controls.CTC.value,
        empid: this.employeeId,
        date: null
        // date:this.pipe.transform(new Date(), 'yyyy-MM-dd')
      }
      this.PR.getPayGroupsForCtc(data).subscribe((result: any) => {
        this.dataSource = new MatTableDataSource;
        this.paygroupid = '';
        if (result.status && result.data.length > 0) {
          this.dataSource = new MatTableDataSource(result.data)
          this.hide = true;
        }
        else {
          let dialogRef = this.dialog.open(ReusableDialogComponent, {
            position: { top: `70px` },
            disableClose: true,
            data: this.PR44
          });

        }
      })
    }


  }
   getWorkLocation() {
    this.companyService.getactiveWorkLocation({ id: null, companyName: this.companyName }).subscribe((result) => {
      this.worklocationDetails = result.data;
      this.filteredLocations = this.worklocationDetails;
    })
  }
  filterLocationss(searchText: any) {
    this.filteredLocations = this.worklocationDetails.filter((val: any) =>
      val.cityname.toLowerCase().includes(searchText.toLowerCase()) || val.location.toLowerCase().includes(searchText.toLowerCase()));
    if (this.filteredLocations.length <= 0) {
      this.searchControl.setValue('');
    }

  }
