  applyFilterData(event: Event){
     const filterValue = (event.target as HTMLInputElement).value
    .trim()
    .toLowerCase();
   console.log("file",filterValue)
  this.dataSource.filter = filterValue;

  
  }
applyFilter(event: Event) {
  const filterValue = (event.target as HTMLInputElement).value
    .trim()
    .toLowerCase();

  this.dataSource2.filter = filterValue;

  if (this.dataSource2.paginator) {
    this.dataSource2.paginator.firstPage();
  }

  this.updateIndex(); // 👈 ADD THIS
}
  updateIndex() {
  const pageIndex = this.paginator?.pageIndex ?? 0;
  const pageSize = this.paginator?.pageSize ?? this.dataSource2.data.length;

  this.dataSource2.filteredData.forEach((item: any, index: number) => {
    item.sno = index + 1 + (pageIndex * pageSize);
  });
}

    getPageSizes(): number[] {

    var customPageSizeArray = [];
    if (this.dataSource2.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource2.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource2.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource2.data.length);
    return customPageSizeArray;
  }
  getMessagesList() {
    let data =
    {
      "code": null,
      "pagenumber": 1,
      "pagesize": 1000
    }
    this.PR.getErrorMessages(null, 1, 1000).subscribe((res: any) => {
      if (res.status && res.data && res.data.length > 0) {
        this.messagesList = res.data;
        this.messagesList.forEach((e: any) => {
          if (e.code == "PR1") {
            this.PR1 = e.message
          } else if (e.code == "PR30") {
            this.PR30 = e.message
          }
          else if (e.code == "PR31") {
            this.PR31 = e.message
          }
          else if (e.code == "PR32") {
            this.PR32 = e.message
          }
          else if (e.code == "PR35") {
            this.PR35 = e.message
          }
          else if (e.code == "PR36") {
            this.PR36 = e.message
          }
          else if (e.code == "PR43") {
            this.PR43 = e.message
          }
          else if (e.code == "PR44") {
            this.PR44 = e.message
          }
        })
      }

    })
  }
  getEarningsDetails(row: any): string {
    return [
      `Earnings: ${row.Earnings || ''} `,
      
    ].join('\n');
  }
  getDeductionDetails(row: any): string {
    return [
      `Deductions: ${row.Deductions || ''} `,
    ].join('\n');
  }
  getReason(row: any): string {
    return [
      `Reject Reason: ${row.rejection_reason || ''} `,
    ].join('\n');
  }
  filterLocations(searchText: any) {
    this.filteredEmployees = this.empdata.filter((val: any) =>
      val.empid.toLowerCase().includes(searchText.toLowerCase()) ||
      val.empname.toLowerCase().includes(searchText.toLowerCase())
    );
  }
