import { Component, OnInit, TemplateRef, ViewChild, ViewContainerRef } from '@angular/core';
import { FormControl, FormGroup, UntypedFormControl, Validators } from '@angular/forms';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { TdsService } from '../../tds.service';
import { PayrollService } from '../../payroll.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { TdsDialogsComponent } from '../../dialogs/tds-dialogs/tds-dialogs.component';
import { MatDialog } from '@angular/material/dialog';
import { DatePipe } from '@angular/common';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { MatDatepicker } from '@angular/material/datepicker';
import { Moment } from 'moment';
import * as _moment from 'moment';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { alphanumericValidator } from 'src/app/custom-directive/alphanumaricRequired';
const moment = _moment;
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
@Component({
  selector: 'app-add-previous-company-payment',
  templateUrl: './add-previous-company-payment.component.html',
  styleUrls: ['./add-previous-company-payment.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class AddPreviousCompanyPaymentComponent implements OnInit {
  info: any = null;
  companyDBName: any = null;
  stateDetails: any = [];
  cityDetails: any = [];
  userSession: any = null;
  pageLoading: boolean = true;
  pipe = new DatePipe('en-US');
  maxDate = new Date();
  minDate: any;
  minFromDate: any;
  maxFromDate: any;
  minToDate: any;
  maxToDate: any;
  dateofjoin: any;
  showForm: boolean = true;
  isDateValidate: boolean = true;
  basicDeclarationDetail: any = [];
  @ViewChild('popupTemplate', { static: true }) popupTemplate!: TemplateRef<any>;
  constructor(private vcr: ViewContainerRef, private companyService: CompanySettingService, private tdsService: TdsService
    , private payrollService: PayrollService, private dialog: MatDialog
  ) {

    this.companyDBName = sessionStorage.getItem('companyName')
      ? sessionStorage.getItem('companyName')
      : null;
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.fnGetCurrentFinYearDates();
    if (this.userSession.dateofjoin != null) {
      this.dateofjoin = new Date(this.userSession.dateofjoin);

    }
    this.getPreviousCompanyPayments();
  }
  companyForm = new FormGroup({
    id: new FormControl(null),
    financialYear: new FormControl(null),
    employeeId: new FormControl(null),
    companyNameValue: new FormControl(null, Validators.required),
    address1: new FormControl(null, Validators.required),
    address2: new FormControl(null, Validators.required),
    city: new FormControl(null, Validators.required),
    state: new FormControl(null, Validators.required),
    country: new FormControl(null, Validators.required),
    companyTan: new FormControl(null, [Validators.required, alphanumericValidator()]),
    fromDate: new FormControl(null, Validators.required),
    toDate: new FormControl(null, Validators.required),
    grossPaidAmount: new FormControl(null, Validators.required),
    basicSalary: new FormControl(null, Validators.required),
    hra: new FormControl(null),
    deductedTaxAmount: new FormControl(null),
    rentPaid: new FormControl(null),
    documentPath: new FormControl(null),
    fileName: new FormControl(null),
    submissionStatus: new FormControl(''),
    createdBy: new FormControl(null),
    updatedBy: new FormControl(null),
    approvedBy: new FormControl(null),
  });
  editRowDetails: any = null;
  countryDetails: any = []
  searchControlForControl = new FormControl('');
  filteredCountryDetails: any = [];

  searchControlForState = new FormControl('');
  filteredStateDetails: any = [];

  searchControlForCity = new FormControl('');
  filteredCityDetails: any = [];
  financialYear: any = null;

  displayedColumns: string[] = ['s_no', "company_name", 'city', 'company_tan', 'employment_from_date', 'employment_to_date', 'submission_status', 'actions']
  dataSource: MatTableDataSource<any> = <any>[];
  emptyData = new MatTableDataSource([{ empty: "row" }]);
  companyDetails: any = []
  @ViewChild('firstPaginator') paginator!: MatPaginator;

  /*bellow three is related to file upload*/
  selectedFile: any = null;
  filesize: boolean = true;
  fileNameError: boolean = true
  fileType: boolean = true;
  fileName: any = null
  isDisableFinalSubmit: boolean = false;
  finYearStartDate: any;
  finYearEndDate: any;
  deleteRow: boolean = false;

  async ngOnInit() {
    this.financialYear = await this.getFinancialYears();
    this.getCountry();

    this.basicDeclarationDetail = await this.getEmpBasicDeclarationDetails();
    if (this.basicDeclarationDetail.length) {
      let validate = await this.validateDates(this.basicDeclarationDetail[0].declaration_open_date, this.basicDeclarationDetail[0].declaration_close_date);
      if (!validate) {
        this.displayedColumns.pop()
        return
      }
    }
    this.companyForm.get('country')?.valueChanges.subscribe((selectedValue) => {
      this.stateDetails = [];
      this.searchControlForControl.setValue('');
      this.companyService.getStatesc(selectedValue).subscribe((data) => {
        this.stateDetails = data.data;
        this.filteredStateDetails = this.stateDetails;
      });
    });


    this.companyForm.get('state')?.valueChanges.subscribe((selectedValue) => {
      this.cityDetails = [];
      this.companyForm.controls.city.setValue(null);
      this.searchControlForState.setValue('');
      this.companyService.getCities(selectedValue).subscribe((data) => {
        this.cityDetails = data.data;
        this.filteredCityDetails = this.cityDetails;
      });
    });

    this.searchControlForCity.valueChanges.subscribe(searchText => {
      this.filterCityDetails(searchText);
    });

    this.searchControlForState.valueChanges.subscribe(searchText => {
      this.filterStateDetails(searchText);
    });
    this.getFinalSubmitStatus();

    this.companyForm.get('fromDate')?.valueChanges.subscribe((selectedValue: any) => {
      const selectedDate = selectedValue._d;
      const newDate = new Date(selectedDate);
      newDate.setDate(newDate.getDate() + 1);
      this.minToDate = newDate;
    });
  }

  getFinancialYears() {
    return new Promise((resolve) => {
      this.payrollService.getFinancialYears().subscribe((result: any) => {
        if (result.status && result.data.length) {
          resolve(result.data[0].financial_year)
        } else {
          resolve('')
        }
      });
    });
  }

  filterCityDetails(searchText: any) {
    this.filteredCityDetails = this.cityDetails.filter((val: any) =>
      val.location.toLowerCase().includes(searchText.toLowerCase()));
    if (this.filteredCityDetails.length <= 0) {
      this.searchControlForCity.setValue('');
    }
  }
  filterStateDetails(searchText: any) {
    this.filteredStateDetails = this.stateDetails.filter((val: any) =>
      val.state.toLowerCase().includes(searchText.toLowerCase()));
    if (this.filteredStateDetails.length <= 0) {
      this.searchControlForState.setValue('');
    }
  }

  filterCountryDetails(searchText: any) {
    this.filteredCountryDetails = this.countryDetails.filter((val: any) =>
      val.country.toLowerCase().includes(searchText.toLowerCase()));
    if (this.filteredCountryDetails.length <= 0) {
      this.searchControlForControl.setValue('');
    }
  }
  addPayment() {
    this.vcr.clear();
    this.fileName = null;
    this.vcr.createEmbeddedView(this.popupTemplate);
  }
  editRecord() {
    this.vcr.clear();
    this.vcr.createEmbeddedView(this.popupTemplate);
  }
  close() {
    this.companyForm.reset()
    this.editRowDetails = null;
    this.info = null;
    this.vcr.clear();

  }


  getCountry() {
    this.countryDetails = [];
    this.companyService
      .getCountry('countrymaster', null, 1, 10, this.companyDBName)
      .subscribe((result) => {
        this.countryDetails = result.data;
        this.filteredCountryDetails = this.countryDetails;
      });
  }

  submitCompany() {
    if (this.companyForm.valid) {
      if (!this.fileName) {
        this.tdsService.message('Please attach previous company documents');
        return;
      }
      if (!this.editRowDetails) {
        this.companyForm.get('submissionStatus')?.setValue('Submitted')
        this.companyForm.get('financialYear')?.setValue(this.financialYear)
        this.companyForm.get('employeeId')?.setValue(this.userSession.id)
        this.companyForm.get('createdBy')?.setValue(this.userSession.id)
        this.companyForm.get('updatedBy')?.setValue(this.userSession.id)
      }
      this.companyForm.get('updatedBy')?.setValue(this.userSession.id);
      this.companyForm.get('documentPath')?.setValue(this.fileName ? this.editRowDetails.document_path : null);
      this.companyForm.get('fileName')?.setValue(this.selectedFile ? this.selectedFile.name : this.fileName ? this.fileName : null);

      this.tdsService.setEmployeePreviousCompanyPayment(this.companyForm.getRawValue(), this.selectedFile).subscribe((results: any) => {
        if (!results.status) {
          this.tdsService.message('Please try again later.')
        }
        else {
          if (this.editRowDetails) {
            this.tdsService.message(this.deleteRow ? "Previous company payment deleted successfully." : "Previous company payment updated successfully.")
            this.companyForm.reset();
            this.fileName = null;
            this.close()
            this.getPreviousCompanyPayments()
            return
          }
          this.tdsService.message("Previous company payment added successfully.")
          this.companyForm.reset()
          this.close();
          this.fileName = null;
          this.getPreviousCompanyPayments();

        }
      })
    }


  }
  updateCompany() {
    this.submitCompany();
  }

  getPreviousCompanyPayments() {
    this.companyDetails = []
    this.tdsService.getPreviousCompanyPayments(this.userSession.id).subscribe((results: any) => {
      if (results.status) {
        this.companyDetails = results.data;
        this.dataSource = new MatTableDataSource(this.companyDetails)
        this.dataSource.paginator = this.paginator;
        this.pageLoading = results.data.length <= 20 ? true : false;
      }
    })
  }


  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.dataSource.data.length < 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  edit(rowData: any) {
    this.editRowDetails = rowData;
    // this.selectedFile = rowData
    this.companyForm.setValue({
      id: rowData.id,
      financialYear: this.financialYear,
      employeeId: this.userSession.id,
      companyNameValue: rowData.company_name,
      address1: rowData.address1,
      address2: rowData.address2,
      country: rowData.country_id,
      state: rowData.state_id,
      city: rowData.city_id,
      companyTan: rowData.company_tan,
      fromDate: rowData.employment_from_date,
      toDate: rowData.employment_to_date,
      grossPaidAmount: rowData.total_gross_paid_amount ? rowData.total_gross_paid_amount.slice(0, -3) : rowData.total_gross_paid_amount,
      basicSalary: rowData.basic_salary ? rowData.basic_salary.slice(0, -3) : rowData.basic_salary,
      hra: rowData.house_rent_allowance ? rowData.house_rent_allowance.slice(0, -3) : rowData.house_rent_allowance,
      deductedTaxAmount: rowData.deducted_tax_amount ? rowData.deducted_tax_amount.slice(0, -3) : rowData.deducted_tax_amount,
      rentPaid: rowData.rent_paid ? rowData.rent_paid.slice(0, -3) : rowData.rent_paid,
      documentPath: rowData.document_path,
      fileName: rowData.file_name,
      submissionStatus: "Submitted",
      createdBy: this.userSession.id,
      updatedBy: this.userSession.id,
      approvedBy: null,
    });
    this.fileName = rowData.file_name;
    this.editRecord()

  }

  removeRow(rowData: any) {
    let dialogRef1 = this.dialog.open(TdsDialogsComponent, {
      position: { top: `50px` },
      disableClose: true,
      data: { regimeFlag: true, message: 'Are you sure you want to delete ?' }
    });
    dialogRef1.afterClosed().subscribe((result: any) => {
      if (result) {
        this.deleteRow = true
        this.companyForm.setValue({
          id: rowData.id,
          financialYear: this.financialYear,
          employeeId: this.userSession.id,
          companyNameValue: rowData.company_name,
          address1: rowData.address1,
          address2: rowData.address2,
          country: rowData.country_id,
          state: rowData.state_id,
          city: rowData.city_id,
          companyTan: rowData.company_tan,
          fromDate: rowData.employment_from_date,
          toDate: rowData.employment_to_date,
          grossPaidAmount: rowData.total_gross_paid_amount,
          basicSalary: rowData.basic_salary,
          hra: rowData.house_rent_allowance,
          deductedTaxAmount: rowData.deducted_tax_amount,
          fileName: rowData.file_name,
          rentPaid: rowData.rent_paid,
          documentPath: rowData.document_path,
          submissionStatus: "Deleted",
          createdBy: this.userSession.id,
          updatedBy: this.userSession.id,
          approvedBy: null,
        });
        rowData.isDeleted = true
        this.editRowDetails = rowData
        this.fileName = rowData.file_name
        this.submitCompany()
        // this.houseForm.setValue({
        //   propertyName: ele.property_name,
        //   purchaseFinancialYear: ele.purchase_financial_year,
        //   natureOfProperty: ele.nature_of_property,
        //   whenLoanWasTaken: ele.when_loan_was_taken,
        //   purposeOfLoan: ele.s24b_id,
        // }, { emitEvent: false });
        // this.fileName = ele.file_name
        // ele.isDeleted = true;
        // this.editRowDetails = ele;
        // this.submitHouseProperty()
      }
    })
  }

  view(ele: any) {
    this.info = ele;
    this.fileName = ele.file_name;
    this.editRecord();
  }

  onFileSelected(event: Event): void {

    const input = event.target as HTMLInputElement;

    if (input.files && input.files[0]) {
      const file = input.files[0];
      if (file) {
        const maxSize = 5 * 1024 * 1024; // 5 MB in bytes
        this.filesize = true;
        this.fileNameError = true;
        this.fileType = true;
        const allowedExtensions = ['jpg', 'png', 'pdf', 'jpeg'];
        const fileExtension = file.name.split('.').pop()?.toLowerCase();
        if (!fileExtension || !allowedExtensions.includes(fileExtension)) {
          this.fileType = false
          this.selectedFile = null
          return;
        }
        if (file.size > maxSize) {
          this.filesize = false;
          this.selectedFile = null
          return
        }
        if (file.name.length > 90) {
          this.fileNameError = false;
          this.selectedFile = null
          return
        } else {
          this.selectedFile = file
          this.fileName = file.name
        }
      }
    }
  }
  showPdf(path: any, file_name: any) {
    this.tdsService.showPdf(path, file_name)
  }

  deleteDocument() {
    this.fileName = null;
  }

  getFinalSubmitStatus() {
    this.tdsService.getFinalSubmitStatus(this.financialYear, this.userSession.id).subscribe((results) => {
      if (results && results.status && results.data) {
        this.isDisableFinalSubmit = results.data[0].enable_status ? false : true;
      }
    })
  }

  changeAmount(a: any, b: any, c: any, d: any) {
    let grossAmt = Number(this.companyForm.get('grossPaidAmount')?.value);
    let basicAmt = Number(this.companyForm.get('basicSalary')?.value);
    let houseRent = Number(this.companyForm.get('hra')?.value);
    let deductionAmt = Number(this.companyForm.get('deductedTaxAmount')?.value);
    let totalSubAmt = basicAmt + houseRent + deductionAmt;
    if (totalSubAmt > grossAmt) {
      this.tdsService.showSnackBar('You cannot declare beyond the gross amount.');
      a == true ? this.companyForm.controls.grossPaidAmount?.setValue(null) : null;
      b == true ? this.companyForm.controls.basicSalary?.setValue(null) : null;
      c == true ? this.companyForm.controls.hra?.setValue(null) : null;
      d == true ? this.companyForm.controls.deductedTaxAmount?.setValue(null) : null;

    } else if (basicAmt > grossAmt) {
      this.tdsService.showSnackBar('You cannot declare beyond the gross amount.')
      this.companyForm.controls.basicSalary?.setValue(null);

    } else if (houseRent > grossAmt) {
      this.tdsService.showSnackBar('You cannot declare beyond the gross amount.')
      this.companyForm.controls.hra?.setValue(null);

    } else if (deductionAmt > grossAmt) {
      this.tdsService.showSnackBar('You cannot declare beyond the gross amount1.');
      this.companyForm.controls.deductedTaxAmount?.setValue(null);
    }
  }

  fnGetCurrentFinYearDates() {
    this.tdsService.fnGetCurrentFinYearDates().subscribe((result: any) => {
      if (result.status) {
        this.finYearEndDate = new Date(result.data[0].end_date);
        this.finYearStartDate = new Date(result.data[0].start_date);
        if (this.dateofjoin.getTime() > this.finYearStartDate.getTime()) {
          this.minFromDate = this.finYearStartDate;
          this.minToDate = this.finYearStartDate;
          // this.maxFromDate =  this.dateofjoin.getMonth()-1;
          this.maxFromDate = this.dateofjoin;
          // this.maxToDate = this.dateofjoin.getMonth()-1;
          this.maxToDate = this.dateofjoin;

        } else {
          this.showForm = false;
          let dialogRef = this.dialog.open(ReusableDialogComponent, {
            position: { top: `70px` },
            disableClose: true,
            data: "This screen is for the employees who joined in the middle of the financial year only."
          });

        }
      }

    })
  }

  validateDates(declarationOpenDate: any, declarationClosureDate: any) {
    return new Promise((resolve) => {
      if (!declarationOpenDate) { //dates not declared 
        this.tdsService.message("The tax exemption declaration window is not yet declared. Please proceed with addition of other earning once the window is declared.")
        this.isDateValidate = false;
        resolve(false)
      } else if (declarationOpenDate && moment().startOf('day').toDate() < moment(declarationOpenDate).startOf('day').toDate()) { //dates declared but not opened
        this.tdsService.message("The tax exemption declaration window is not yet opened. Please proceed with addition of other earning once the window is declared.");
        this.isDateValidate = false;
        resolve(false)
      }
      else if (moment().startOf('day').toDate() > moment(declarationClosureDate).startOf('day').toDate()) { //dates closed 
        this.tdsService.message("The tax exemption declaration window is closed. Please contact your Finance Manager to proceed with addition of other earning.");
        this.isDateValidate = false;
        resolve(false)
      } else {
        this.isDateValidate = true;
        resolve(true)

      }
    })
  }

  getEmpBasicDeclarationDetails() {
    return new Promise((resolve) => {
      this.tdsService.getEmpBasicDeclarationDetails(this.userSession.id, this.financialYear).subscribe((_results) => {
        if (_results && _results.status) {
          resolve(_results.data)
        } else {
          resolve([])
        }
      })
    })
  }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();

    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }
}
