import { Component, OnInit } from '@angular/core';
import { LearnService } from '../../learn.service';

@Component({
  selector: 'app-lms-configurations',
  templateUrl: './lms-configurations.component.html',
  styleUrls: ['./lms-configurations.component.scss']
})
export class LmsConfigurationsComponent implements OnInit {

  scoreConfig: any[] = [];
  displayedColumns: string[] = ['id', 'attribute_name','description', 'attribute_value', 'actions'];
  editMode: number | null = null; // Track the current row being edited
  userSession: any

  constructor(private learn: LearnService) { 
        this.userSession = JSON.parse(sessionStorage.getItem('user') || '');

  }

  ngOnInit(): void {
    this.fetchScoreConfig();
  }

  fetchScoreConfig(): void {
    this.learn.getScoreconfig().subscribe({
      next: (data) => {
        this.scoreConfig = data;
      },
      error: (error) => {
        console.error('Error fetching score config:', error);
      }
    });
  }

  edit(element: any): void {
    this.editMode = element.id;
  }

  cancel(): void {
    this.editMode = null;
    this.fetchScoreConfig(); // Reset the data
  }

  save(element: any): void {

  if (!/^\d{1,4}$/.test(element.attribute_value)) {
    alert("Please enter a valid value (1–4 digit number)");
    return;
  }

  const payload = {
    id: element.id,
    attribute_value: element.attribute_value,
    created_by: this.userSession.id
  };

  this.learn.updateScoreConfig(payload).subscribe({
    next: () => {
      this.editMode = null;
      this.fetchScoreConfig();
    },
    error: (error) => console.error('Error saving score config:', error)
  });
}



}
