  edit(event: any) {
    this.isAddRentAmount = true;
    this.editRow = true;
    this.searchForm.controls.rentAmount.setValue(event.rent_paid.slice(0, -3));
    this.rentPaid = this.rentPaid - Number(event.rent_paid);
    this.addRent();
    if (event.name_of_the_owner !== null) {
      this.displayOwnerDetails = true;
      this.searchForm.controls.ownerName.setValue(event.name_of_the_owner);
      this.searchForm.controls.pancardNumber.setValue(event.owner_pan_number);
    }
    this.id = event.id;
    this.ownerPanList = this.ownerPanList.filter((item: any) => item.owner_pan_number !== event.owner_pan_number)
  }

