  validateEmployeeTaxExemptionStatus(): Promise<boolean> {
    return new Promise((resolve) => {
      this.tdsService.validateEmployeeTaxExemptionStatus(this.userSession.id, this.financialYear).subscribe((results: any) => {
        if (results && results.status && results.data) {
          if (results.data[0] && results.data[0].tds_status.toString().includes(this.activeChild?.screenid)) {
            this.tdsService.message(results.data[0].tds_message)
            resolve(false)
            return;
          } else {
            resolve(true)
          }
        } else {
          resolve(true)
        }
      })
    })

  }

  removeRow(row: any) {
    let payload = {
      id_value: row.id,
      employee_id_value: this.userSession.id,
      financial_year_value: this.financialYear,
      rent_value: row.rent_paid,
      owner_name: row.name_of_the_owner,
      owner_pan: row.owner_pan_number,
      submission_status_value: 'Deleted',
      created_by_value: this.userSession.id,
      updated_by_value: this.userSession.id,
    }
    this.setEmployeeAnnualRent(payload)
  }
  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();

    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

  getOwnersList() {
    this.tdsService.getOwnersList(this.financialYear, this.userSession.id).subscribe((result: any) => {
      if (result.status) {
        this.ownerPanList = result.data
      }
    })
  }

  view(element: any) {
    this.info = element;
    this.vcr.clear(); // Clear previous views if any
    this.vcr.createEmbeddedView(this.popupTemplate); // Render the popup template
  }

  close() {
    this.info = null;
    this.vcr.clear(); // Clear previous views if any
    this.isAddRentAmount = false;
    this.searchForm.reset();
  }

  getEmpBasicDeclarationDetails() {
    return new Promise((resolve) => {
      this.tdsService.getEmpBasicDeclarationDetails(this.userSession.id, this.financialYear).subscribe((_results) => {
        if (_results && _results.status) {
          resolve(_results.data)
        } else {
          resolve([])
        }
      })
    })
  }




  validateDates(declarationOpenDate: any, declarationClosureDate: any) {
    return new Promise((resolve) => {
      if (!declarationOpenDate) { //dates not declared 
        this.tdsService.message("The tax exemption declaration window is not yet declared. Please proceed with addition of annual house rent once the window is declared.")
        this.isDateValidate = false;
        resolve(false)
      } else if (declarationOpenDate && moment().startOf('day').toDate() < moment(declarationOpenDate).startOf('day').toDate()) { //dates declared but not opened
        this.tdsService.message("The tax exemption declaration window is not yet opened. Please proceed with addition of annual house rent once the window is declared.");
        this.isDateValidate = false;
        resolve(false)
      }
      else if (moment().startOf('day').toDate() > moment(declarationClosureDate).startOf('day').toDate()) { //dates closed 
        this.tdsService.message("The tax exemption declaration window is closed. Please contact your Finance Manager to proceed with addition of annual house rent.");
        this.isDateValidate = false;
        resolve(false)
      } else {
        this.isDateValidate = true;
        resolve(true)

      }
    })
  }

  applyValidators() {
    if (this.searchForm.controls.rentAmount.value > this.houserentLimit) {

      this.searchForm.get('ownerName').setValidators([Validators.required]);
      this.searchForm.get('ownerName').updateValueAndValidity();

      this.searchForm.get('pancardNumber').setValidators([Validators.required, Validators.minLength(10), alphanumericValidator()]);
      this.searchForm.get('pancardNumber').updateValueAndValidity();

    } else {
      this.searchForm.controls['ownerName'].clearValidators();
      this.searchForm.controls['pancardNumber'].clearValidators();
    }
  }

  getFinalSubmitStatus() {
    this.tdsService.getFinalSubmitStatus(this.financialYear, this.userSession.id).subscribe((results) => {
      if (results && results.status && results.data) {
        this.isDisableFinalSubmit = results.data[0].enable_status ? false : true;
      }
    })
  }
