import { Component, OnInit, ViewChild, AfterViewInit, ViewContainerRef , TemplateRef} from '@angular/core';
import { Router } from '@angular/router';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { EmsService } from '../../ems.service';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import * as _moment from 'moment';
import { AdminService } from 'src/app/modules/admin/admin.service';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { NgxSpinnerService } from 'ngx-spinner';
import { MatDialog } from '@angular/material/dialog';
import { TranslateService } from '@ngx-translate/core';
import { Overlay, OverlayRef } from '@angular/cdk/overlay';
import { TemplatePortal } from '@angular/cdk/portal';
 
const moment = _moment;
 
export const MY_FORMATS = {
  parse: { dateInput: 'LL' },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
 
@Component({
  selector: 'app-rehire',
  templateUrl: './rehire.component.html',
  styleUrls: ['./rehire.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})

export class RehireComponent implements OnInit, AfterViewInit {
 
  selectedStatus: 'Separated' | 'Terminated' = 'Separated';
  displayedColumns: string[] = [];
   overlayRef: OverlayRef | null = null;
    currentDescription = '';
    pageLoading = true;
    
 
  separatedColumns: string[] = [
    'sno',
    'empid',
    'empname',
    'aadharnumber',
    'details',
    'department',
    'designation',
    'worklocation',
    'lastrm',
    'seperationdate',
    'reasons',
    'status'
  ];
  terminatedColumns: string[] = [
    'sno',
    'empid',
    'empname',
    'aadharnumber',
    'details',
    'department',
    'designation',
    'worklocation',
    'lastrm',
    'terminationdate',
    'reason',
    'status'
  ];
 
  dataSource = new MatTableDataSource<any>([]);
 
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort) sort!: MatSort;
  @ViewChild('descriptionPopup') descriptionPopup!: TemplateRef<any>;
  @ViewChild('viewDialog') viewDialog!: TemplateRef<any>;
  @ViewChild('searchInput') searchInput!: any;

 
  constructor(
    private emsService: EmsService,
    public spinner: NgxSpinnerService,
    private translate: TranslateService,
     private overlay: Overlay,
     private viewContainerRef: ViewContainerRef
  ) {}
 
  ngOnInit(): void {
    this.onStatusChange();
  }
 
  ngAfterViewInit(): void {
    this.dataSource.paginator = this.paginator;
    this.dataSource.sort = this.sort;
    this.paginator.page.subscribe(() => {
    this.dataSource._updateChangeSubscription();
  });
  }
 
 onStatusChange(): void {
  this.pageLoading = true;
   if (this.searchInput) {
    this.searchInput.nativeElement.value = '';
  }
  this.dataSource.filter = '';
    if (this.paginator) {
    this.paginator.pageIndex = 0;
    this.paginator.pageSize = 5; // default
  }
  if (this.selectedStatus === 'Separated') {
    this.displayedColumns = [...this.separatedColumns]; 
  } else {
    this.displayedColumns = [...this.terminatedColumns];
  }
 
  this.loadEmployeeList(this.selectedStatus);
}
 
  private loadEmployeeList(type: 'Separated' | 'Terminated'): void {
    this.spinner.show();
 
    const api$ =
      type === 'Separated'
        ? this.emsService.getAllEmployeeSResignation()
        : this.emsService.getAllEmployeeTerminations();
 
    api$.subscribe({
      next: (res: any) => {
        console.log('API RESPONSE =>', res);
 
        const list = res?.data || res?.result || res || [];
 
        this.dataSource = new MatTableDataSource<any>(
          Array.isArray(list) ? list : []
        );
 
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;

      setTimeout(() => {
        this.paginator?.firstPage();
      })
 
        this.spinner.hide();
      },
      error: (err) => {
        console.error('Employee List Error:', err);
        this.dataSource = new MatTableDataSource<any>([]);
        this.pageLoading = false;
        this.spinner.hide();
      }
    });
  }
  applyFilter(event: Event): void {
  const filterValue = (event.target as HTMLInputElement).value
    .trim()
    .toLowerCase();
 
  this.dataSource.filterPredicate = (data: any, filter: string) => {
    const empName = data.empname?.toLowerCase() || '';
    const empId = data.empcode?.toString().toLowerCase() || '';
    const aadhar = data.aadharnumber?.toString().toLowerCase() || '';
    const department = data.department_name?.toString().toLowerCase() || '';
    const designation = data.designation_name?.toString().toLowerCase() || ''; 
    const location = data.worklocation_name?.toString().toLowerCase() || '';
    const rm = data.managername?.toString().toLowerCase() || '';
     const status = data.status?.toString().toLowerCase() || '';
 
 
    return empName.includes(filter) || empId.includes(filter)||
    aadhar.includes(filter) ||
      department.includes(filter) ||
      designation.includes(filter) ||
      location.includes(filter) ||
      status.includes(filter) ||
      rm.includes(filter)
   
  };
 
  this.dataSource.filter = filterValue;
 
  // Reset paginator so "No data found" shows correctly
  if (this.dataSource.paginator) {
    this.dataSource.paginator.firstPage();
  }
}
 
  getEmployerDetails(row:any){
    const formatDate = (dateStr: string) => {
    if (!dateStr) return '';
    const d = new Date(dateStr);
    const day = ('0' + d.getDate()).slice(-2);
    const month = ('0' + (d.getMonth() + 1)).slice(-2);
    const year = d.getFullYear();
    return `${day}-${month}-${year}`;
  };
     const details = [
    `Previous Hired Date: ${formatDate(row.previoushireddate)} |`,
    `Previous Joining Date: ${formatDate(row.previousjoiningdate)} |`,
    // `Role: ${row.rolenames ? row.rolenames.replace(/[\[\]"]/g,'').replace(/,/g, ', ') : 'Not Assigned'} |`
  ];
  return details.join('\n');
  }
    // description custom popup
    showDescriptionPopup(event: MouseEvent, description: string, index: number): void {
  if (!description || description.length <= 50) return;

  this.currentDescription = description;

  const positionStrategy = this.overlay.position()
    .flexibleConnectedTo(event.target as HTMLElement)
    .withPositions([
      {
        originX: 'start',
        originY: 'bottom',
        overlayX: 'start',
        overlayY: 'top'
      },
      {
        originX: 'start',
        originY: 'top',
        overlayX: 'start',
        overlayY: 'bottom'
      }
    ]);

  this.overlayRef = this.overlay.create({
    positionStrategy,
    scrollStrategy: this.overlay.scrollStrategies.close()
  });

  const portal = new TemplatePortal(
    this.descriptionPopup,
    this.viewContainerRef
  );

  this.overlayRef.attach(portal);
}

hideDescriptionPopup(): void {
  if (this.overlayRef) {
    this.overlayRef.dispose();
    this.overlayRef = null;
  }
}

getTruncatedText(text: string, maxLength: number): string {
  if (!text) return '';
  return text.length > maxLength
    ? text.substring(0, maxLength) + '...'
    : text;
}
 getPageSizes(): number[] {
    var customPageSizeArray = [];
    
      if (this.dataSource.data.length > 5) {
        customPageSizeArray.push(5);
      }
      if (this.dataSource.data.length > 10) {
        customPageSizeArray.push(10);
      }
      if (this.dataSource.data.length > 20) {
        customPageSizeArray.push(20);
      }
      customPageSizeArray.push(this.dataSource.data.length);
      return customPageSizeArray;
 }

}
 
 