

import { Component, OnInit, TemplateRef, ViewChild, ViewContainerRef } from '@angular/core';
import { TdsService } from '../../tds.service';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { MatDialog } from '@angular/material/dialog';

import moment from 'moment';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { decimalWithDotTwoDirective } from '../../../../custom-directive/decimal-with-dot-two/decimal-with-dot-two.directive'
import { MatSelectChange } from '@angular/material/select';
import { property } from 'lodash';
import { PayrollService } from '../../payroll.service';
import { Action } from 'rxjs/internal/scheduler/Action';

@Component({
  selector: 'app-add-employee-earning-tds',
  templateUrl: './add-behalf-employee-earning-tds.component.html',
  styleUrls: ['./add-behalf-employee-earning-tds.component.scss']
})

export class AddBehalfEmployeeEarningTdsComponent implements OnInit {

  userSession: any
  validationMessage: boolean = false;
  selectedFile: any = null;
  financeYears: any = [];
  financialYear: any;
  currentFinancialYear: any;
  fileName: any = null
  noDataFound:boolean = false;
  constructor(private tdsService: TdsService, private dialog: MatDialog, private vcr: ViewContainerRef, private payrollService: PayrollService,) {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');

  }
  earningForm = new FormGroup({
    empname: new FormControl('', Validators.required),
    otherEarningType: new FormControl(null, Validators.required),
    earningDetail: new FormControl(null, Validators.required),
    property: new FormControl(null),
    earningAmount: new FormControl('', [
      Validators.required,
      decimalWithDotTwoDirective(), // Apply custom decimal validator
    ]),
  });
  filteredEmployeeList: any = [];
  searchControl = new FormControl('');
  empList: any = [];
  employeeHousePropertyDetails: any = [];
  housePropertiesDisplayedColumns: string[] = ['s_no', "employee_name", 'designation', 'deptname', 'category', 'earning_amount_approved', 'actions']
  //'category','document_path','manager_name'
  otherEarningsDataSource: MatTableDataSource<any> = <any>[];
  emptyData = new MatTableDataSource([{ empty: "row" }]);

  @ViewChild('popupTemplate', { static: true }) popupTemplate!: TemplateRef<any>;
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  pageLoading: boolean = true;
  editRowDetails: any = null;
  basicDeclarationDetail: any = [];
  isDateValidate: boolean = true;
  one: boolean = false;
  otherEarningTypes: any = [];
  earningTypeDetails: any = [];
  section24DropdownThree: any = [];
  employeeHouseProperties: any = [];
  islettingOut: boolean = false;

  async ngOnInit(): Promise<void> {
    this.financialYear = await this.getFinancialYears();
    this.currentFinancialYear = JSON.parse(JSON.stringify(this.financialYear))
    this.earningForm.get('empname')?.valueChanges.subscribe((selectedValue: any) => {
      if (selectedValue) {
        this.getEmployeeHousePropertiesForEarning(selectedValue);
        this.getEmployeeEarningsForTdsByEmpId(selectedValue);
      }
    });
    this.getEmployeeListForExemptionSubmission();
    this.getEmployeeEarningsForManager();
    // this.getEmployeeHousePropertiesForEarning();
    this.basicDeclarationDetail = await this.getEmpBasicDeclarationDetails();
    if (this.basicDeclarationDetail.length) {
      let validate = await this.validateDates(this.basicDeclarationDetail[0].declaration_open_date, this.basicDeclarationDetail[0].declaration_close_date);
      if (!validate) {
        this.housePropertiesDisplayedColumns.pop()
        return
      }
    }

    this.getOtherEarningMaster();

    this.earningForm.get('otherEarningType')?.valueChanges.subscribe((selectedValue: any) => {
      if (selectedValue) {
        this.getOtherEarningDetails(selectedValue);
      }
    });
    this.earningForm.get('earningDetail')?.valueChanges.subscribe((selectedValue: any) => {
      if (selectedValue && this.employeeEarnings.length && selectedValue != 5) {
        this.validations(selectedValue, true)
      }
      if (selectedValue && selectedValue == 5) {
        if (this.employeeHouseProperties.length == 0) {
          this.tdsService.message('Let Out house properties are not yet added or submissions are already done for added properties.')
          setTimeout(() => { this.earningForm.get('earningDetail')?.setValue(null) })
          return
        }
        this.islettingOut = true;
        this.togglePropertyValidation(true);
      } else if (selectedValue) {
        this.islettingOut = false;
        this.togglePropertyValidation(false);
      }
    });

    this.earningForm.get('earningAmount')?.valueChanges.subscribe(
      (selectedValue: string | null) => {
        if (selectedValue !== null) {
          const formattedValue: string = this.formatDecimalValue(selectedValue);
          this.earningForm.get('earningAmount')?.setValue(formattedValue, { emitEvent: false });
        }
      }
    );
    this.searchControl.valueChanges.subscribe(searchText => {
      this.filterEmpList(searchText);
    });


    this.earningForm.get('property')?.valueChanges.subscribe(
      (selectedValue: string | null) => {
        if (selectedValue !== null) {
          this.validations(selectedValue, false)
        }
      }
    );

  }

  formatDecimalValue(value: string): string {
    // Allow only up to 10 digits before the dot and 2 digits after
    const regex = /^\d{0,10}(\.\d{0,2})?$/;
    if (!regex.test(value)) {
      value = value.replace(/[^0-9.]/g, '').replace(/(\..*?)\..*/g, '$1'); // Clean invalid input
      const parts = value.split('.');
      if (parts[1]?.length > 2) {
        parts[1] = parts[1].substring(0, 2); // Limit decimal places to 2
      }
      value = parts.join('.');
    }
    return value;
  }
  // Method to add/remove required validator based on a condition
  togglePropertyValidation(condition: boolean): void {
    const propertyControl = this.earningForm.get('property');

    if (condition) {
      propertyControl?.setValidators([Validators.required]);
    } else {
      propertyControl?.clearValidators();
    }

    // Update the control's validity after changing validators
    propertyControl?.updateValueAndValidity();
  }

  filterEmpList(searchText: any) {
    this.filteredEmployeeList = this.empList.filter((val: any) =>
      val.employee_name.toLowerCase().includes(searchText.toLowerCase()) || val.employee_code.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredEmployeeList.length <= 0) {
      this.noDataFound = true
    } else {
      this.noDataFound = false
    }
  }
  getEmployeeListForExemptionSubmission() {
    let payLoad = {
      financial_year: this.financialYear
    }
    this.tdsService.getEmployeeListForExemptionSubmission(payLoad).subscribe((result: any) => {
      this.empList = result.data;
      this.filteredEmployeeList = this.empList;
    })
  }
  submitOtherEarning() {
    let data = {
      id_value: this.editRowDetails ? this.editRowDetails.id : null,
      employeeId: this.earningForm.get('empname')?.value,
      financial_year_value: this.financialYear,
      other_earning_id_value: this.earningForm.get('otherEarningType')?.value,
      other_earning_detail_id_value: this.earningForm.get('earningDetail')?.value,
      house_property_id_value: this.earningForm.get('property')?.value,
      earning_amount_value: this.earningForm.get('earningAmount')?.value,
      documentPath: this.fileName ? this.editRowDetails.document_path : null,
      fileName: this.selectedFile ? this.selectedFile.name : this.fileName ? this.fileName : null,
      existingFileName: this.editRowDetails ? this.editRowDetails.file_name : null,
      submission_status: 'Approved',
      mgr_id_value: this.userSession.id
    }
    this.tdsService.setEmployeeEarningForTds(data, this.selectedFile).subscribe((results: any) => {
      if (!results || (results.data && results.data[0] && results.data[0].Code) || !results.status) {
        this.tdsService.message('Please try again later.')
      }
      else {
        if (this.editRowDetails) {
          this.tdsService.message("Other earning updated successfully.")
          this.earningForm.reset()
          this.closePopup()
          this.getEmployeeEarningsForManager()
          return
        }
        this.tdsService.message("Other earning added successfully.")
        this.earningForm.reset()
        this.closePopup()
      }
      this.getEmployeeEarningsForManager()
    })

  }


  cancel() {
    this.earningForm.reset();
    this.one = !this.one;
    this.vcr.clear(); // Remove the popup from the DOM
  }
  /** getFinancialYears Data*/
  getFinancialYears() {
    return new Promise((resolve) => {
      this.tdsService.getFinancialYears().subscribe((result: any) => {
        if (result.status && result.data.length) {
          this.financeYears = result.data;
          resolve(result.data[0].financial_year)
        } else {
          resolve('')
        }
      });
    });
  }

  getEmpBasicDeclarationDetails() {
    return new Promise((resolve) => {
      this.tdsService.getEmpBasicDeclarationDetails(this.userSession.id, this.financialYear).subscribe((_results) => {
        if (_results && _results.status) {
          resolve(_results.data)
        } else {
          resolve([])
        }
      })
    })
  }
  validateDates(declarationOpenDate: any, declarationClosureDate: any) {
    return new Promise((resolve) => {
      if (!declarationOpenDate) { //dates not declared 
        this.tdsService.message("The tax exemption declaration window is not yet declared. Please proceed with addition of other earning once the window is declared.")
        this.isDateValidate = false;
        resolve(false)
      } else if (declarationOpenDate && moment().startOf('day').toDate() < moment(declarationOpenDate).startOf('day').toDate()) { //dates declared but not opened
        this.tdsService.message("The tax exemption declaration window is not yet opened. Please proceed with addition of other earning once the window is declared.");
        this.isDateValidate = false;
        resolve(false)
      }
      else if (moment().startOf('day').toDate() > moment(declarationClosureDate).startOf('day').toDate()) { //dates closed 
        this.tdsService.message("The tax exemption declaration window is closed. Please contact your Finance Manager to proceed with addition of other earning.");
        this.isDateValidate = false;
        resolve(false)
      } else {
        this.isDateValidate = true;
        resolve(true)

      }
    })
  }
  onFinancialYearChange(event: MatSelectChange): void {
    // Perform your logic here
    this.getEmployeeEarningsForManager()
    if (event.value == this.currentFinancialYear) {
      this.isDateValidate = true;
    } else {
      this.isDateValidate = false;
    }
  }

  getOtherEarningMaster() {

    this.tdsService.getOtherEarningMaster().subscribe((result: any) => {
      if (result && result.status == true) {

        this.otherEarningTypes = result.data;
      } else {
        this.otherEarningTypes = [];
      }
    })

  }
  getOtherEarningDetails(otherEarningId: any) {

    this.tdsService.getOtherEarningDetails(otherEarningId).subscribe((result: any) => {
      if (result && result.status == true) {
        this.earningTypeDetails = result.data;
      } else {
        this.earningTypeDetails = [];
      }
    })

  }

  getEmployeeHousePropertiesForEarning(empId: any) {

    return new Promise((resolve) => {
      this.tdsService.getEmployeeHousePropertiesForEarning(empId).subscribe((result) => {
        if (result && result.status) {
          this.employeeHouseProperties = result.data;
        } else {
          resolve([])
        }
      })
    })
  }
  getEmployeeEarningsForManager() {

    return new Promise((resolve) => {
      this.tdsService.getEmployeeEarningsForManager(this.financialYear).subscribe((result) => {
        if (result && result.status) {
          this.employeeHousePropertyDetails = result.data;
          this.otherEarningsDataSource = new MatTableDataSource(this.employeeHousePropertyDetails)
          this.otherEarningsDataSource.paginator = this.paginator;
          this.pageLoading = result.data.length <= 20 ? true : false;

        } else {
          resolve([])
        }
      })
    })
  }
  closePopup() {
    this.vcr.clear(); // Remove the popup from the DOM
    this.editRowDetails = null;
    this.fileName = null;
    this.selectedFile = null;
    /*bellow three is related to file upload*/
    this.filesize = true;
    this.fileNameError = true;
    this.fileType=true;
  }
  addProperty() {
    /*bellow three is related to file upload*/
    this.filesize = true;
    this.fileNameError = true;
    this.fileType=true;
    this.vcr.clear(); // Clear previous views if any
    this.vcr.createEmbeddedView(this.popupTemplate); // Render the popup template

  }
  edit(ele: any) {

    this.editRowDetails = ele;
    this.earningForm.setValue({
      earningAmount: ele.earning_amount_declared,
      otherEarningType: ele.poem_id,
      earningDetail: ele.poed_id,
      property: ele.house_property_id,
      empname: ele.empname
    });
    this.fileName = ele.file_name
    this.addProperty()
  }
  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.otherEarningsDataSource.data.length < 5) {
      customPageSizeArray.push(5);
    }
    if (this.otherEarningsDataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.otherEarningsDataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.otherEarningsDataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.otherEarningsDataSource.data.length);
    return customPageSizeArray;
  }



 
/*bellow three is related to file upload*/
filesize: boolean = true;
fileNameError: boolean = true
fileType:boolean =true;
onFileSelected(event: Event): void {
  const input = event.target as HTMLInputElement;
  if (input.files && input.files[0]) {
    const file = input.files[0];
    if (file) {
      const maxSize = 5 * 1024 * 1024; // 5 MB in bytes
      this.filesize = true;
      this.fileNameError = true;
      this.fileType =true;  
      const allowedExtensions = ['jpg', 'png', 'pdf', 'doc', 'docx'];
      const fileExtension = file.name.split('.').pop()?.toLowerCase();
      if (!fileExtension || !allowedExtensions.includes(fileExtension)) {
        this.fileType =false  
        this.selectedFile = null      
        return;
      }
     if (file.size > maxSize) {
        this.filesize = false;
        this.selectedFile = null
        return
      } 
       if (file.name.length > 90) {
        this.fileNameError = false;
        this.selectedFile = null
        return
      } else {
        this.selectedFile = file
      }
    }
  }
}
  showPdf(path: any, file_name: any) {
    this.tdsService.showPdf(path,file_name)
  }

  deleteDocument() {
    this.fileName = null;
  }
  info: any = null
  view(ele: any) {
    this.info = ele;
    this.vcr.clear(); // Clear previous views if any
    this.vcr.createEmbeddedView(this.popupTemplate); // Render the popup template
  }
  close() {
    this.info = null;
    this.vcr.clear(); // Clear previous views if any
  }

  employeeEarnings: any = []
  getEmployeeEarningsForTdsByEmpId(empId: any) {
    let data = {
      "employee_id_value": empId,
      "financial_year_value": this.financialYear
    }
    return new Promise((resolve) => {
      this.tdsService.getEmployeeEarningsForTdsByEmpId(data).subscribe((result) => {
        if (result && result.status) {
          this.employeeEarnings = result.data;
        } else {
          resolve([])
        }
      })
    })
  }



  validations(selectedValue: any, flag: any) {
    for (let i = 0; i < this.employeeEarnings.length; i++) {
      if (flag && selectedValue === this.employeeEarnings[i].poed_id && this.employeeEarnings[i].submission_status !== 'Rejected') {
        this.tdsService.message('An amount was already submitted for this earning type. Edit the amount to increase or decrease the total earning for this earning type.')
        setTimeout(() => { this.earningForm.get('earningDetail')?.setValue(null) })
        break;
      }
      if (!flag && selectedValue === this.employeeEarnings[i].house_property_id && this.employeeEarnings[i].submission_status !== 'Rejected') {
        this.tdsService.message('An amount was already submitted for this earning type. Edit the amount to increase or decrease the total earning for this earning type.')
        setTimeout(() => { this.earningForm.get('property')?.setValue(null) })
        break;
      }
    }
  }

  onBlur() {
    this.earningForm.get('earningAmount')?.markAsTouched();
  }
}
