import { Component, OnInit, ViewChild } from '@angular/core';
import { FormGroup, FormControl, Validators } from '@angular/forms';
import moment from 'moment';
import { MAT_DATE_LOCALE, MAT_DATE_FORMATS, DateAdapter } from '@angular/material/core';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { resolve, SrvRecord } from 'dns';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { MatDialog } from '@angular/material/dialog';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { TdsService } from '../../tds.service'
import { Router } from '@angular/router';
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};


@Component({
  selector: 'app-tax-exemption-declaration-dates',
  templateUrl: './tax-exemption-declaration-dates.component.html',
  styleUrls: ['./tax-exemption-declaration-dates.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class TaxExemptionDeclarationDatesComponent implements OnInit {
  currentFinancialYearDates:any={start_date:null,end_date:null};
  constructor(private tdsService: TdsService, private dialog: MatDialog, private router: Router) {
  }
  currentDate:any=new Date()
  declarationData:any=[];
  displayedColumns: string[] = ['s_no', 'emp_name', 'employee_code','declaration_open_date', 'declaration_close_date', 'declare_status', 'comments', 'extension_status','actions'];
  dataSource: MatTableDataSource<any> = <any>[]
  // dataSource:any= [
  //   {s_no: 1, emp_name: "Sreekanthjjjjjjjjjjjjjjjjjjj lllllllllll 888888888888888888 88888888888 88888888888888 555555555555555555555", declaration_open_date: "01-04-2023", declaration_close_date: "21-04-2023",declaration_status:'Declared',proof_upload_status:'Inprogress',actions:''},
  //   {s_no: 2, emp_name: "Gopi", declaration_open_date: "01-04-2023", declaration_close_date: "21-04-2023",declaration_status:'Declared',proof_upload_status:'Pending',actions:''},
  //   {s_no: 3, emp_name: "Mani", declaration_open_date: "01-04-2023", declaration_close_date: "25-04-2023",declaration_status:'Declared',proof_upload_status:'Pending',actions:''},
  //   {s_no: 4, emp_name: "Saida", declaration_open_date: "01-04-2023", declaration_close_date: "30-04-2023",declaration_status:'Declared',proof_upload_status:'Completed',actions:''},

  // ];
  pageLoading:boolean=true;
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  enable: any;

  ngAfterViewInit() {
    this.dataSource.paginator = this.paginator;
  }
  taxForm = new FormGroup({
    openDate: new FormControl(null, Validators.required),
    closeDate: new FormControl(null, Validators.required),
  });
  minDataForCloseDate: any = null
  editCloseDate: any = null;
  editInputMinDate: any = null;
  editInputMaxDate: any = null;

  financialYear: any = ''
  async ngOnInit() {
    this.financialYear = await this.getFinancialYears()
    this.fnGetCurrentFinYearDates();
    this.getEmployeesTdsDateDetails();
    this.taxForm.get('closeDate')?.disable();
    this.taxForm.get('openDate')?.valueChanges.subscribe(value => {
      if(value){
        if(this.taxForm.get('closeDate')?.value){
          setTimeout(()=>{this.taxForm.get('closeDate')?.setValue(null)},100)
        }
        if(moment(value).toDate()>=moment(this.currentFinancialYearDates.deduction_commencement_month).toDate() ){
          this.message('The TDS deductions start from '+moment(this.currentFinancialYearDates.deduction_commencement_month).format('DD-MM-YYYY')+'. The declaration dates should be prior to this date. To change this date, change the TDS deduction commencement month configuration.')
            setTimeout(()=>{this.taxForm.get('openDate')?.setValue(null)},100)
            this.taxForm.get('closeDate')?.disable();
            return
        }
        this.taxForm.get('closeDate')?.enable();

      }
    });

    this.taxForm.get('closeDate')?.valueChanges.subscribe(value => {
      if(value){
        if(moment(value).toDate()>=moment(this.currentFinancialYearDates.deduction_commencement_month).toDate() ){
          this.message('The TDS deductions start from '+moment(this.currentFinancialYearDates.deduction_commencement_month).format('DD-MM-YYYY')+'. The declaration dates should be prior to this date. To change this date, change the TDS deduction commencement month configuration.')
            setTimeout(()=>{this.taxForm.get('closeDate')?.setValue(null)},100)
        }
      }
    });
  }
  /** getFinancialYears Data*/
  getFinancialYears() {
    return new Promise((resolve) => {
      this.tdsService.getFinancialYears().subscribe((result: any) => {
        if (result.status && result.data.length) {
          resolve(result.data[0].financial_year)
        } else {
          resolve('')
        }
      });
    });
  }
  async getEmployeesTdsDateDetails() {
    this.tdsService.getEmployeeTdsExempDeclarationWindowDates(this.financialYear).subscribe((result: any) => {
      this.declarationData = []
      if (result.status && result.data.length) {
        result.data.forEach((ele: any, index: number) => {
          ele.s_no = index + 1;
          ele.isEdit = false;
          ele.action = '';
          // ele.comments = null;
          // if(index <3){
          //   ele.comments = 'please extends declaration dates to 4 days '
          // }
        })
        this.declarationData = result.data;
        this.dataSource = new MatTableDataSource(result.data);
        this.dataSource.paginator = this.paginator;
        // this.dataSource.sort = this.sort;
        this.pageLoading = result.data.length <= 20?true:false;
        this.taxForm.get('openDate')?.disable();
        this.taxForm.get('closeDate')?.disable();
      }
    })
  }

  async submitDates(employee: any = null) {
    if (employee) {
      employee.isEdit = false;
      if (employee.declaration_close_date === moment(this.editCloseDate).format('YYYY-MM-DD')) {
        return
      }
    }

    let input = {
      employeeIds: employee ? [employee.employee_id] : employee,
      windowOpenDate: employee ? employee.declaration_open_date : moment(this.taxForm.value?.openDate).format('YYYY-MM-DD'),
      windowCloseDate: employee ? moment(this.editCloseDate).format('YYYY-MM-DD') : moment(this.taxForm.value?.closeDate).format('YYYY-MM-DD')
    }
    this.tdsService.setEmpTdsExemptionDeclarationWindowDates(input).subscribe((results) => {
      if (results.status) {
        if(employee){
          employee.declaration_close_date = this.editCloseDate;
          employee.extension_status = 'Extended';
          this.message("Date updated successfully.");
          this.reload();
        }else{
          this.message("Declaration dates saved successfully");
          this.reload();
        }
      } else {
        this.message("Please try again later.")

      }
    })
  }
  edit(employee: any = null) {
    this.enable = employee.employee_id; 
    this.editCloseDate = moment(employee.declaration_close_date)
    this.editInputMinDate = moment().toDate() > moment(employee.declaration_open_date).toDate()?moment().toDate():moment(employee.declaration_open_date).toDate()
    // this.editInputMaxDate = moment(employee.declaration_open_date).add(30,'day')
    employee.isEdit = true;
  }

  message(message: any) {
    this.dialog.open(ReusableDialogComponent, {
      position: { top: `70px` },
      disableClose: true,
      data: message,
    });
  }

  cancel(employee: any = null) {
    if (employee) {
      employee.isEdit = false;
      return
    }
    this.taxForm.reset()
    this.taxForm.get('closeDate')?.disable();

  }

  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.dataSource.data.length < 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  fnGetCurrentFinYearDates(){
    this.tdsService.fnGetCurrentFinYearDates().subscribe((results) => {
      if(results && results.status && results.data[0]){
        this.currentFinancialYearDates = results.data[0];
        this.currentFinancialYearDates.start_date = this.currentFinancialYearDates.start_date?moment(this.currentFinancialYearDates.start_date):null;
        this.currentFinancialYearDates.end_date = this.currentFinancialYearDates.end_date?moment(this.currentFinancialYearDates.end_date):null;
        this.currentFinancialYearDates.deduction_commencement_month =this.currentFinancialYearDates.deduction_commencement_month? moment(this.currentFinancialYearDates.deduction_commencement_month) :null
      }
    })
  }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
  
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

  reload(){
    this.router
    .navigateByUrl('/', { skipLocationChange: true })
    .then(() => this.router.navigate(['/Payroll/taxExemptionDeclarationDates']));
  }

}
