  transform(value: string) {
    return value.toLowerCase() // Convert to lowercase to ensure consistent capitalization
      .split('_')    // Split by underscore
      .map(word => word.charAt(0).toUpperCase() + word.slice(1)) // Capitalize first letter of each word
      .join(' ');
  }

  selectClient(event: any, row: any) {
    let clientId = this.encriptPipe.transform(row.client_id.toString());
    this.router.navigate(["/Crm/CrmClientEditAndUpdate", { clientId }])
  }

  back_report() {
    if (sessionStorage.getItem('back_url') != '') {
      let back_params: any = JSON.parse(sessionStorage.getItem('back_url') ?? '[]');
      this.dataTransfer.setData({
        redirected: this.redirected
      });
      if (back_params.back_route) {
        this.router.navigate([back_params.back_route]);
      }
    }
  }


  getEmployeeName() {
    let emp_name = '';
    let userId = this.searchForm.controls.Users.value;
    if (userId == '0' || userId == '') {
      userId = null;
    }
    if (this.filteredEmployees && this.filteredEmployees.length) {
      if (userId) {
        this.filteredEmployees.forEach((e: any) => {
          if (e.empid == userId && emp_name == '')
            emp_name = e.empname;
        })
      }
      else emp_name = 'All';
    }
    return emp_name;
  }


  generatePDF() {
    let fromDate = this.datePipe.transform(this.searchForm.controls.fromDate.value, "dd-MM-YYYY");
    // let selections =  `Date: ${fromDate},  Employee: ${this.getEmployeeName()}   Manager: ${ this.userSession.firstname||'' + ' '+ this.userSession.middlename||'' + ' '+ this.userSession.lastname||'' }`;
    let selections = ``;
    if (this.is_super_admin) {
      selections = selections + `\n` + `Selected Locations: ${this.getSelectedLocationNames()}`;
      selections = selections + `\n` + `Selected Managers: ${this.getSelectedManagerNames()}`;
      selections = selections + `\n` + `Date: ${fromDate},    Employee: ${this.getEmployeeName()},     Super Admin: ${this.userSession.firstname || '' + ' ' + this.userSession.middlename || '' + ' ' + this.userSession.lastname || ''}`;
      selections = selections + `\n\n`; 
    } else {
      selections = `Date: ${fromDate},    Employee: ${this.getEmployeeName()},     Manager: ${this.userSession.firstname || '' + ' ' + this.userSession.middlename || '' + ' ' + this.userSession.lastname || ''}`;
      selections = selections + `\n\n`;
    }



    let trackingHeaders = ['S.no', 'Started At', 'Start Location', 'Details', 'Stay Duration', 'Travel Duration', 'KMS Traveled', 'Reached At', 'End Location'];
    let trackingWidths = { 0: { cellWidth: 12 }, 1: { cellWidth: 20  }, 2: { cellWidth: 55  }, 3: { cellWidth: 55  }, 4: { cellWidth: 20  }, 5: { cellWidth: 20  }, 6: { cellWidth: 20 }, 7: { cellWidth: 20  }, 8: { cellWidth: 55 } };

    let trackingTable = [
      ...this.List.map((row, index) => [
        index + 1,
        this.getFormattedTime(row.start_time),
        this.getAddress(row, 'start'),
        this.getDetailsForPdf(row.details, 'pdf', ' '),
        this.getFormattedTimeDifference(row.spent_time, 'Stay'),
        this.getFormattedTimeDifference(row.travel_time, 'Travel'),
        this.convertToKms(row.distance).val,
        this.getFormattedTime(row.end_time),
        this.getAddress(row, 'end'),
      ])
    ];

    let summaryHeaders = ['Work Location','Date', 'First Login Time', 'Last Logout time', 'Worked Hours', 'New Visits', 'New Clients', 'Total Visits', 'KMS Travelled', 'Total Activites'];
    let summaryWidths = { 0: { cellWidth: 40 }, 1: { cellWidth: 25 }, 2: { cellWidth: 30 }, 3: { cellWidth: 30 }, 4: { cellWidth: 25 }, 5: { cellWidth: 25 }, 6: { cellWidth: 25 }, 7: { cellWidth: 25 }, 8: { cellWidth: 30 }, 9: { cellWidth: 25 } };

    let summaryTable = [
      ...this.emp_attendance.map(row => [
        row.work_location ?? '',
        row.attendancedate ?? '',
        this.getFormattedTime(row.firstlogintime),
        this.getFormattedTime(row.lastlogouttime),
        row.workedhours,
        row.new_visits,
        row.new_clients,
        row.visits_total,
        row.Km_travelled,
        row.activities_total
      ])];

    let activityHeaders = ['Activity Type', 'Client Name', 'Contact Person', 'Client Contact', 'Activity Status', 'Client Status', 'Next Follow Up On', 'Final Price', 'Received Amount'];
    let activityWidths = { 0: { cellWidth: 20 }, 1: { cellWidth: 60 }, 2: { cellWidth: 25 }, 3: { cellWidth: 25 }, 4: { cellWidth: 30 }, 5: { cellWidth: 35 }, 6: { cellWidth: 35 }, 7: { cellWidth: 25 }, 8: { cellWidth: 25 } };

    let activityTable = [
      ...this.employeeDayActivities.map(row => [
        row.activity_type,
        row.client_name,
        row.contact_person,
        row.client_contact,
        row.activity_status,
        row.client_status,
        row.next_follow_up_on,
        row.final_price || 0,
        row.received_amount || 0
      ])];

    let tables = [];
    (this.emp_attendance && this.emp_attendance.length) ? tables.push({ headers: summaryHeaders, sub_head: 'Summary Information', body: summaryTable, widths: summaryWidths, table_name: 'summary',  startYOffset: 10  }) : null;
    (this.employeeDayActivities && this.employeeDayActivities.length) ? tables.push({ headers: activityHeaders, sub_head: 'Activity Logs', body: activityTable, widths: activityWidths, table_name: 'activiites' }) : null;
    (this.List && this.List.length) ? tables.push({ headers: trackingHeaders, sub_head: 'Tracking Information', body: trackingTable, widths: trackingWidths, table_name: 'tracking' }) : null;

    this.pdfService.generatePDF_common('landscape', 'Employee Wise Detailed Tracking log Report', selections, tables, 'Employee_wise_detailed_tracking_log.pdf');

  }



  getSelectedManagerNames() {
    let selectedManagerNames: string = '';
    if (this.selectedManagers && this.selectedManagers.length) {
      this.managersDetails?.forEach((md: any) => {
        if (this.selectedManagers.includes(md.manager_emp_id)) {
          selectedManagerNames = selectedManagerNames + (selectedManagerNames == '' ? '' : ', ') + md.manager_name;
        }
      });
    }
    return selectedManagerNames;
  }

  getSelectedLocationNames() {
    let selectedLocationNames: string = '';
    if (this.selectedLocations && this.selectedLocations.length) {
      this.worklocationDetails?.forEach((wl: any) => {
        if (this.selectedLocations.includes(wl.id)) {
          selectedLocationNames = selectedLocationNames + (selectedLocationNames == '' ? '' : ', ') + wl.location;
        }
      });
    }
    return selectedLocationNames;
  }

