import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from "@angular/common/http";
import { Observable } from "rxjs/index";
import { environment } from '../../environments/environment'


@Injectable({
  providedIn: 'root'
})
export class LeavePoliciesService {
  httpOptions: any;
  companyName: any
  constructor(private hClient: HttpClient) {
    this.companyName = sessionStorage.getItem('companyName');
    this.httpOptions = {
      headers: new HttpHeaders({
        'content-Type': 'application/json',
        "Authorization": JSON.parse(JSON.stringify(sessionStorage.getItem('token') || '')),
      })
    };
  }




  url: any = environment.apiUrl;



  setAddLeaveBalance(info: any) {
    return this.hClient.post(this.url + 'api/setAddLeaveBalance', JSON.stringify(info), this.httpOptions);
  }

  getLeaveTypes(tableName: any, page: any, size: any): Observable<any> {
    return this.hClient.get(this.url + 'api/getLeaveTypes/' + tableName + '/' + page + '/' + size, this.httpOptions);

  }

  getLeavePolicies(data: any): Observable<any> {

    return this.hClient.get(this.url + 'leavesApi/getLeavePolicies/' + data.policy_id_value + '/' + data.leaveid + '/' + data.iscommonrule + '/' + data.company_rule + '/' + this.companyName, this.httpOptions);

  }
  getleavetypesforadvancedleave(): Observable<any> {
    return this.hClient.get(this.url + 'leavesApi/getLeaveTypesForAdvancedLeave/' + this.companyName, this.httpOptions);

  }

  getLeaves(page: any, size: any): Observable<any> {
    return this.hClient.get(this.url + 'leavesApi/getLeaves/' + page + '/' + size, this.httpOptions);

  }

  getLeaveRules(Id: any, page: any, size: any): Observable<any> {
    return this.hClient.get(this.url + 'leavesApi/getLeaveRules/' + Id + '/' + page + '/' + size, this.httpOptions);

  }

  getAddLeaveBalance() {
    return this.hClient.get(this.url + 'leavesApi/getAddLeaveBalance', { responseType: 'json' });

  }

  putAddLeaveBalance(info: any) {
    return this.hClient.put(this.url + 'leavesApi/putAddLeaveBalance', JSON.stringify(info), this.httpOptions);

  }

  deleteAddLeaveBalance(leaveBalanceId: any) {
    return this.hClient.delete(this.url + 'leavesApi/deleteAddLeaveBalance/' + leaveBalanceId, this.httpOptions);

  }

  setLeaveConfigure(info: any): Observable<any> {
    info.companyName = this.companyName;
    return this.hClient.post(this.url + 'leavesApi/setLeavePolicies/', JSON.stringify(info), this.httpOptions);

  }
  setAdvancedLeaveRuleValues(info: any): Observable<any> {
    info.companyName = this.companyName;
    return this.hClient.post(this.url + 'leavesApi/setAdvancedLeaveRuleValues', JSON.stringify(info), this.httpOptions);

  }
  updateLeaveDisplayName(info: any): Observable<any> {
    info.companyName = this.companyName;
    return this.hClient.post(this.url + 'leavesApi/updateLeaveDisplayName', JSON.stringify(info), this.httpOptions);

  }

  getLeaveDetails(tableName: any, status: any, page: any, size: any): Observable<any> {
    return this.hClient.get(this.url + 'commonApi/getMastertable/' + tableName + '/' + status + '/' + page + '/' + size + '/' + this.companyName, this.httpOptions);
  }
  getLeaveTypesToAdd(policyType: any): Observable<any> {
    return this.hClient.get(this.url + 'leavesApi/getLeaveTypesToAdd/' + policyType + '/' + this.companyName, this.httpOptions);
  }

  setNewLeaveType(info: any): Observable<any> {
    this.companyName = sessionStorage.getItem('companyName');
    return this.hClient.post(this.url + 'leavesApi/setNewLeaveType/' + this.companyName, JSON.stringify(info), this.httpOptions);
  }

  getLeavesTypeInfo(policyId: any, employeeId: any): Observable<any> {
    return this.hClient.get(this.url + 'leavesApi/getLeavesTypeInfo/' + policyId + '/' + employeeId + '/' + this.companyName, this.httpOptions);

  }
  setToggleLeaveType(info: any): Observable<any> {
    info.companyName = this.companyName;
    return this.hClient.post(this.url + 'leavesApi/setToggleLeaveType', JSON.stringify(info), this.httpOptions);
  }
  getCarryforwardedLeaveMaxCount(leaveId: any): Observable<any> {
    return this.hClient.get(this.url + 'leavesApi/getCarryforwardedLeaveMaxCount/' + leaveId + '/' + this.companyName, this.httpOptions);

  }
  getLeaveCycleYearOptions() {
    this.companyName = sessionStorage.getItem('companyName');
    return this.hClient.get(this.url + 'leavesApi/getLeaveCycleYearOptions/' + this.companyName, this.httpOptions);
  }
  setLeavePoliciesOrg(info: any): Observable<any> {
    info.companyName = this.companyName;
    return this.hClient.post(this.url + 'leavesApi/setLeavePoliciesOrg/', info, this.httpOptions);

  }

  getLeavetypesDataForAdmin(policyId: any): Observable<any> {
    return this.hClient.get(this.url + 'leavesApi/getLeavetypesDataForAdmin/' + policyId + '/' + this.companyName, this.httpOptions);

  }

}
