import { SelectionModel } from '@angular/cdk/collections';
import { DatePipe } from '@angular/common';
import { Component, OnInit, ViewChild } from '@angular/core';
import { UntypedFormGroup, UntypedFormBuilder, Validators, AbstractControl, FormControl } from '@angular/forms';
import { MatDatepickerInputEvent } from '@angular/material/datepicker';
import { MatDialog } from '@angular/material/dialog';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { Router } from '@angular/router';
import { AdminService } from 'src/app/modules/admin/admin.service';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { EmsService } from 'src/app/modules/ems/ems.service';



import * as _moment from 'moment';
import { AttendanceService } from 'src/app/modules/attendance/attendance.service';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { WeekoffHistoryDialogComponent } from 'src/app/modules/attendance/pages/weekoff-history-dialog/weekoff-history-dialog.component';
import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';
// import {default as _rollupMoment} from 'moment';
const moment = _moment;

export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
@Component({
  selector: 'app-admin-weekoff-configuration',
  templateUrl: './admin-weekoff-configuration.component.html',
  styleUrls: ['./admin-weekoff-configuration.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class AdminWeekoffConfigurationComponent implements OnInit {

  requestform: any = UntypedFormGroup;
  searchform: any = UntypedFormGroup;
  minFromDate: Date;
  maxFromDate: Date | null;
  minToDate: Date | null;
  maxToDate: Date;
  currentDate: Date = new Date();
  pipe = new DatePipe('en-US');
  todayWithPipe: any;
  displayedColumns: string[] = ['select', 'id', 'empid', 'empname', 'weekoffs', 'status'];
  dataSource: MatTableDataSource<any> = <any>[];
  ATT74: any;
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  searchControl = new FormControl('');

  arrayList: any = [];
  userSession: any;
  shiftDataList: any = [];
  employeesData: any;
  weekDaysDetails: any = [];
  workingDays: any = [];
  weekoffs: any = [];
  selectedEmps: any = [];
   worklocationDetails: any[] = [];
  sectionSearchControl = new FormControl('');
  section: any[] = [];
  filteredSections: any[] = [];
  sectionflag: boolean = false;
  ismappingEnable: boolean = false;
  mappingValue: any;
  personalInfoForm: any = UntypedFormGroup;
  EM2: any;

  pageLoading = true;
  messagesDataList: any = [];
  requiredOption: any;
  dataSave: any;
  dataNotSave: any;
  recordExist: any;
  companyDBName: any;
  availableDepartments: any = [];
  isShow = false;
  filteredDepartments: any = [];
  btnDisable: boolean = false;
  constructor(private formBuilder: UntypedFormBuilder, private attendanceService: AttendanceService,
    public dialog: MatDialog, public datePipe: DatePipe, private router: Router,
    private companyService: CompanySettingService, private adminService: AdminService,
    private dialogService:ReusableDialogService, private emsService: EmsService
  ) {
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    this.companyDBName = sessionStorage.getItem('companyName');
    this.minFromDate = new Date();
    this.minFromDate.setDate(this.currentDate.getDate());
    this.maxFromDate = new Date();
    this.maxFromDate.setDate(this.currentDate.getFullYear() + 1);
    this.minToDate = new Date();
    this.minToDate.setDate(this.currentDate.getDate() + 1);
    this.maxToDate = new Date();
    this.maxToDate.setDate(this.currentDate.getFullYear() + 1);
    this.arrayList = [];

  }
  selection = new SelectionModel<any>(true, []);
  shifDetails: any;
  finaldate: any;

  ngOnInit(): void {
   this.sectionflag = Number(sessionStorage.getItem('section')) == 1 ? true :false;
   this.getWorkLocation();
    this.getMessagesList();
    this.todayWithPipe = this.pipe.transform(Date.now(), 'dd/MM/yyyy');
    this.searchform = this.formBuilder.group(
      { 
        companylocation: ['', Validators.required],
        department: ['', Validators.required],
        section: ['']
      });
    this.requestform = this.formBuilder.group(
      {
        fromDate: [''],
        toDate: [''],
      });
    this.dataSource.paginator = this.paginator;
    this.getDepartmentsMaster();
    this.getWeekDays();
    this.searchControl.valueChanges.subscribe(searchText => {

      this.filterDepartments(searchText);
    });
    
this.searchform.get('department')?.valueChanges.subscribe((deptId: any) => {

  const sectionControl = this.searchform.get('section');



  if (deptId) {

    this.sectionflag? this.getSectionsForDepartment(deptId):null;

      if(this.sectionflag){

          // enable the control and make it required

          sectionControl?.enable();

          sectionControl?.setValidators([Validators.required]);

          sectionControl?.reset();

          sectionControl?.updateValueAndValidity();

        } else {   



          // clear validators, reset and disable the control

          sectionControl?.clearValidators();

          sectionControl?.reset();

          sectionControl?.updateValueAndValidity();

          sectionControl?.disable();

        }

  }



});
  }

  ngAfterViewInit() {
  }
  get f(): { [key: string]: AbstractControl } {
    return this.requestform.controls;
  }

  getWeekDays() {
    this.weekDaysDetails = [];
    this.workingDays = [];
    this.attendanceService.getMastertable('week_master', null, 1, 10, this.companyDBName)
      .subscribe((data) => {
        if (data.status) {
          this.weekDaysDetails = data.data;
          data.data.forEach((i: any) => {
            let obj = { id: i.id, name: i.week_name };
            this.workingDays.push(obj);
          });
        }
      });
  }

  fromDateChange(type: string, event: any) {
    this.minToDate = event.value['_d']
    if (event.value['_d'] !== null) {
      this.maxToDate = new Date(
        event.value['_i'].year + 1,
        event.value['_i'].month,
        event.value['_i'].date - 31
      );
    }
    this.requestform.controls.toDate.setValue('');
  }

  toDateChange(type: string, event: MatDatepickerInputEvent<Date>) {
  }


  getEmployeeWeekoffConfigure() {
    if (this.searchform.valid) {
      this.isShow = true;
      this.arrayList = [];
      let obj = {
        "location_id": this.searchform.controls.companylocation.value || null,
        "manager_empid": null,
        "department_id": this.searchform.controls.department.value,
        "section_id": this.sectionflag  ? this.searchform.controls.section.value : null
      };
      this.attendanceService.getEmployeeWeekoffConfigure(obj).subscribe((res) => {
        if (res.status) {
          this.arrayList = res.data;
          this.dataSource = new MatTableDataSource(this.arrayList);
          this.dataSource.paginator = this.paginator;
          this.dataSource.sort = this.sort;
          this.pageLoading = false;
        } else {
          this.arrayList = [];
          this.dataSource = new MatTableDataSource(this.arrayList);
          this.dataSource.paginator = this.paginator;
          this.dataSource.sort = this.sort;
        }
      });
    }
  }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();

    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

  submit() {
    // this.addValidators() ;
    // if (this.requestform.invalid) {
    //   return;
    // } else {
    if (this.btnDisable) {
      return;
    }
    if (this.selection.selected.length > 0) {
      this.selectedEmps = [];
      this.selection.selected.forEach((e: any) => {
        this.selectedEmps.push(e.empid);
      });
      let obj = {
        // "from_date": this.pipe.transform(new Date(this.requestform.controls.fromDate.value ?? ''), 'yyyy-MM-dd'),
        // "to_date": this.pipe.transform(new Date(this.requestform.controls.toDate.value ?? ''), 'yyyy-MM-dd'),
        "weekoffs": JSON.stringify(this.weekoffs),
        "empids": JSON.stringify(this.selectedEmps)

      };
      this.btnDisable = true;
      this.attendanceService.setEmployeeWeekoffs(obj).subscribe((res) => {
        if (res.status) {
          this.dialogService.openDialog('Weekoff assigned successfully');
          this.resetform();
        } else {
          this.dialogService.openDialog('Weekoff assigned not successfully');
          this.btnDisable = false;
        }
      });

    } else {
      this.dialogService.openDialog('Select atleast one employee');
      this.btnDisable = false;
      return;
    }
    // }
  }

  resetform() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Admin/AdminWeekoffConfiguration"]));

  }

  checkCheckBoxvalue(event: any, data: any) {

    if (event.checked == true) {
      this.weekoffs.push(data.id);
      this.workingDays.forEach((e: any, index: any) => {
        if (e.id == data.id) {
          this.workingDays.splice(index, 1);
        }
      });

    } else {
      this.weekoffs.forEach((a: any, index: any) => {
        if (a == data.id) {
          this.weekoffs.splice(index, 1);
        }
      })
      let obj = { "id": data.id, "name": data.week_name }
      this.workingDays.push(obj);
    }
  }
  /** Whether the number of selected elements matches the total number of rows. */
  isAllSelected() {
    const numSelected = this.selection.selected.length;
    const numRows = this.dataSource.data.length;
    return numSelected === numRows;
  }

  /** Selects all rows if they are not all selected; otherwise clear selection. */
  masterToggle() {
    // if there is a selection then clear that selection
    if (this.isSomeSelected()) {
      this.selection.clear();
    } else {
      this.isAllSelected()
        ? this.selection.clear()
        : this.dataSource.data.forEach(row => this.selection.select(row));
    }
  }

  isSomeSelected() {
    return this.selection.selected.length > 0;
  }

  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  getMessagesList() {
    let data =
    {
      "code": null,
      "pagenumber": 1,
      "pagesize": 100
    }
    this.adminService.getMessagesListApi(data).subscribe((res: any) => {
      if (res.status) {
        this.messagesDataList = res.data;
        this.messagesDataList.forEach((e: any) => {
          if (e.code == "ATT2") {
            this.requiredOption = e.message
          } else if (e.code == "ATT69") {
            this.dataSave = e.message
          } else if (e.code == "ATT70") {
            this.dataNotSave = e.message
          } else if (e.code == "ATT74") {
            this.ATT74 = e.message
          }
        })
      }
      else {
        this.messagesDataList = [];
      }

    })
  }

  getDepartmentsMaster() {
    this.companyService.getMastertable('departmentsmaster', 1, 1, 1000, this.companyDBName).subscribe(data => {
      if (data.status) {
        this.availableDepartments = data.data;
        this.filteredDepartments = this.availableDepartments;
      }
    })
  }

  view(data: any) {
    let givenData = {
      "empId": data.empid,
      "empCode": data.emp_code,
      "empName": data.empname,
    }
    let dialogRef = this.dialog.open(WeekoffHistoryDialogComponent, {
      width: '500px', position: { top: `100px` },
      disableClose: true,
      data: givenData
    });
    // this.clearValidators();
  }

  addValidators() {
    this.requestform.controls.fromDate.setValidators([Validators.required])
    this.requestform.controls.toDate.setValidators([Validators.required])

    this.requestform.get('fromDate').updateValueAndValidity();
    this.requestform.get('toDate').updateValueAndValidity();
  }


  clearValidators() {
    this.requestform.reset();
    this.requestform.get('fromDate').clearValidators();
    this.requestform.get('fromDate').updateValueAndValidity();

    this.requestform.get('toDate').clearValidators();
    this.requestform.get('toDate').updateValueAndValidity();

  }
  filterDepartments(searchText: any) {

    this.filteredDepartments = this.availableDepartments.filter((val: any) =>
      val.deptname.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredDepartments.length <= 0) {
      this.searchControl.setValue('');
    } else {

    }
  }
      getWorkLocation() {

    this.companyService

      .getactiveWorkLocation({ id: null, companyName: this.companyDBName })

      .subscribe((result) => {

        this.worklocationDetails = result.data;

      });

  }



getSectionsForDepartment(deptId: any) {

  this.emsService.getSectionsForDepartment(deptId).subscribe((res: any) => {

    if (res.status && res.data?.length) {

      this.section = res.data;

      this.filteredSections = [...this.section];

      //this.sectionflag = true;

      // ensure control is enabled (in case called from elsewhere)

      this.searchform.get('section')?.enable();

    } else {

      this.section = [];

      this.filteredSections = [];

      this.sectionflag = false;

      // disable control if no sections found

      this.searchform.get('section')?.clearValidators();

      this.searchform.get('section')?.reset();

      this.searchform.get('section')?.updateValueAndValidity();

      this.searchform.get('section')?.disable();

    }

  });

}
}

