import { Component, OnInit } from '@angular/core';
import { ClaimsService } from '../../claims.service';
import { UntypedFormBuilder, UntypedFormGroup, Validators } from '@angular/forms';

@Component({
  selector: 'app-claims-summary-report',
  templateUrl: './claims-summary-report.component.html',
  styleUrls: ['./claims-summary-report.component.scss']
})
export class ClaimsSummaryReportComponent implements OnInit {
  userSession: any;
  employeelist: any[] = [];
  searchForm!: UntypedFormGroup;
  isRedirected: boolean = false;
  
  // Declare maxDate, minDate, and minToDate
  maxDate: Date = new Date();  // Set the maximum date as today
  minDate: Date = new Date(new Date().setFullYear(new Date().getFullYear() - 1));  // Minimum date is 1 year ago
  minToDate: Date = this.minDate;  // Initialize minToDate to match minDate, can be updated dynamically

  constructor(private claim: ClaimsService, private formBuilder: UntypedFormBuilder) { }

  ngOnInit(): void {
    this.searchForm = this.formBuilder.group({
      fromDate: ["", [Validators.required, Validators.maxLength(50)]],
      toDate: ["", [Validators.required]],
      Users: ["", [Validators.required]],
    });

    this.getEmployeelist();

    // Update minToDate whenever fromDate changes
    this.searchForm.get('fromDate')?.valueChanges.subscribe((fromDate: Date) => {
      this.minToDate = fromDate;  // Ensure To Date is always after From Date
    });
  }

  getEmployeelist() {
    if (!this.userSession?.id) {
      console.error('User session or user ID is missing!');
      return;
    }   
  
    let obj = {
      "rm_id": this.userSession?.id,
    };
  
    this.claim.getgetemployeesByMangerId(obj).subscribe(
      (res: any) => {
        if (res.status) {
          this.employeelist = res.data || [];
          if (!this.isRedirected) {
            this.searchForm.controls.Users.setValue('0');
          }
        } else {
          console.error('Error: API did not return success status');
        }
      },
      (error) => {
        console.error('Error fetching employee list:', error); // Handle error case
      }
    );
  }
  
}
