import { Component, OnInit, TemplateRef, ViewChild, ViewContainerRef } from '@angular/core';
import { TdsService } from '../../tds.service';
import { MatDialog } from '@angular/material/dialog';
import { FormControl, FormGroup, UntypedFormGroup, Validators } from '@angular/forms';
import { MatTableDataSource } from '@angular/material/table';
import { TdsDialogsComponent } from '../../dialogs/tds-dialogs/tds-dialogs.component';
import { MatPaginator } from '@angular/material/paginator';
import moment from 'moment';
import { PayrollService } from '../../payroll.service';
import { Router } from '@angular/router';

@Component({
  selector: 'app-add-house-property-onbehalf-of',
  templateUrl: './add-house-property-onbehalf-of.component.html',
  styleUrls: ['./add-house-property-onbehalf-of.component.scss']
})
export class AddHousePropertyOnbehalfOfComponent implements OnInit {

  @ViewChild('popupTemplate', { static: true }) popupTemplate!: TemplateRef<any>;
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  
  houseForm:any=UntypedFormGroup;
  fileName:any = null
  purchaseFinancialYears:any=[];
  section24DropdownOne:any=[];
  section24DropdownThree:any=[];
  userSession:any;
  activeChild:any;
  activeModule:any;
  financialYear:any;
  section24DropdownTwo:any=[];
  employeeHousePropertyDetails:any=[];
  housePropertiesDisplayedColumns: string[] = ['s_no',"emp_name",'designation','deptname', "property_name", 'purchase_financial_year','actions']
  housePropertiesDataSource: MatTableDataSource<any> = <any>[];
  emptyData = new MatTableDataSource([{ empty: "row" }]);  
  filteredEmployeeList:any = [];
  searchControl = new FormControl('');
  empList: any;
  info: any = null;
  btnDisable:boolean = true;

  
  fileNameError: boolean =true
  editRowDetails:any = null;
  basicDeclarationDetail:any=[];
  pageLoading:boolean=true;
  isDateValidate:boolean=true;
  filesize:boolean = true;
  selectedFile:any=null;
  selfOccupiedLimit:any=null;
  selfOccupiedSubmittedCount:any=null;
  noDataFound:boolean = false



  constructor(
    private tdsService:TdsService,
    private vcr: ViewContainerRef,
    private dialog: MatDialog,
    private payrollService: PayrollService,
    private router:Router,
  ) { 
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.activeChild = JSON.parse(sessionStorage.getItem('activeChild')||'')
    this.activeModule = JSON.parse(sessionStorage.getItem('activeModule')||'');
  

  }

  async ngOnInit(){
      this.houseForm = new FormGroup({ 
        empname:new FormControl(null,Validators.required),
        propertyName: new FormControl(null, Validators.required),
        purchaseFinancialYear:new FormControl(null, Validators.required),
        natureOfProperty: new FormControl(null, Validators.required),
        whenLoanWasTaken: new FormControl(null, Validators.required),
        purposeOfLoan:new FormControl(null, Validators.required),
     });

     this.financialYear = await this.getFinancialYears();
     this.getEmployeeListForExemptionSubmission();
  
     this.getEmployeeHousePropertiesForManager();
     this.basicDeclarationDetail = await this.getEmpBasicDeclarationDetails();
     if(this.basicDeclarationDetail.length){
       let validate = await this.validateDates(this.basicDeclarationDetail[0].declaration_open_date, this.basicDeclarationDetail[0].declaration_close_date);
       if(!validate){
         this.housePropertiesDisplayedColumns.pop()
         return
       }
     }
     this.getSection24bDetails();
     this.getSection24bLimits();
     this.getPurchaseFinancialYears();
     this.houseForm.get('natureOfProperty')?.valueChanges.subscribe((value:any) => {
       if(value){
         this.houseForm.get('whenLoanWasTaken')?.enable()
         this.houseForm.get('whenLoanWasTaken')?.setValue(null)
         this.houseForm.get('purposeOfLoan')?.setValue(null)
         if(value === 'Self-Occupied' && this.selfOccupiedLimit && this.selfOccupiedSubmittedCount && this.selfOccupiedLimit === this.selfOccupiedSubmittedCount){
           this.tdsService.message(`The maximum number of house properties as Self-Occupied is ${this.selfOccupiedLimit} and the limit is reached.`)
           setTimeout(()=>{
           this.houseForm.get('natureOfProperty')?.setValue(null)
          },1000)
         }
 
       }else{
         this.houseForm.get('whenLoanWasTaken')?.disable()
         this.houseForm.get('purposeOfLoan')?.disable()
       }
     })
     this.houseForm.get('whenLoanWasTaken')?.valueChanges.subscribe((value:any)=>{
       if(value){
         this.houseForm.get('purposeOfLoan')?.enable()
         this.houseForm.get('purposeOfLoan')?.setValue(null)
       }else{
         this.houseForm.get('purposeOfLoan')?.disable()
       }
     })

    this.searchControl.valueChanges.subscribe(searchText => {
      this.filterEmpList(searchText);
    });
  }

  addProperty(){
    this.filesize = true;
    this.fileNameError = true;
    this.vcr.clear(); // Clear previous views if any
    this.vcr.createEmbeddedView(this.popupTemplate); // Render the popup template

  }



    getSection24bDetails() {
      this.tdsService.getSection24bDetails().subscribe((results) => {
        if (results && results.status) {
          if (results.data && results.data.length) {
            results.data.forEach((ele: any) => {
              if (!this.section24DropdownOne.find((item: any) => item.nature_of_property === ele.nature_of_property)) {
                this.section24DropdownOne.push(ele);
              }
              if (!this.section24DropdownTwo.find((item: any) => item.when_loan_was_taken === ele.when_loan_was_taken)) {
                this.section24DropdownTwo.push(ele);
              }
              this.section24DropdownThree.push(ele);
            })
          }
        }
      })
    }

    getPurchaseFinancialYears(){
      this.tdsService.getPurchaseFinancialYears().subscribe((results:any)=>{
        if(results && results.status){
          this.purchaseFinancialYears = results.data;
        }
      })
    }
    
    submitHouseProperty(){
      this.btnDisable = false;
      let input = {
        id:this.editRowDetails?this.editRowDetails.property_id:null,
        propertyName:this.houseForm.get('propertyName')?.value, 
        employeeId:this.houseForm.controls.empname.value,
        financialYear:this.financialYear,
        purchaseFinYear: this.houseForm.get('purchaseFinancialYear')?.value, 
        id24b: this.houseForm.get('purposeOfLoan')?.value,
        documentPath:this.fileName?this.editRowDetails.document_path:null,
        fileName:this.selectedFile?this.selectedFile.name:this.fileName?this.fileName:null,
        existingFileName:this.editRowDetails?this.editRowDetails.file_name:null,
        status:this.editRowDetails?this.editRowDetails.isDeleted?'Deleted':'Approved':'Approved', 
        createdBy:this.userSession.id,
        updatedBy:null
      }
      
      this.tdsService.setEmployeeHouseProperty(input,this.selectedFile).subscribe((results:any)=>{
        if(!results || (results.data && results.data[0] && results.data[0].Code) || !results.status){
          this.tdsService.message('Please try again later.')
          this.btnDisable = true;
    
        }
        else {
          if(this.editRowDetails){
            this.tdsService.message(this.editRowDetails.isDeleted?"House property deleted successfully.":"House property updated successfully.")
            this.houseForm.reset()
            this.closePopup()
            this.getEmployeeHousePropertiesForManager();
          
            return
          }
          this.tdsService.message("House property added successfully.")
          this.houseForm.reset()
          this.closePopup()
          this.navigationToCurrentPage();
        }
        this.getEmployeeHousePropertiesForManager();
      })

    }
  
    cancel(){
      this.houseForm.reset();
      this.closePopup()
      }
  
      /** getFinancialYears Data*/
      getFinancialYears() {
        return new Promise((resolve) => {
          this.tdsService.getFinancialYears().subscribe((result: any) => {
            if (result.status && result.data.length) {
              resolve(result.data[0].financial_year)
            } else {
              resolve('')
            }
          });
        });
      }
  
    getEmployeeHousePropertiesForManager(){
      this.employeeHousePropertyDetails=[];
      this.tdsService.getEmployeeHousePropertiesForManager(this.userSession.id,this.financialYear).subscribe((results:any)=>{
        if(results && results.status){
          this.employeeHousePropertyDetails=  results.data;
          if(this.employeeHousePropertyDetails.length > 0){
            this.selfOccupiedSubmittedCount = this.employeeHousePropertyDetails[0].so_count
          }
          this.housePropertiesDataSource = new MatTableDataSource(this.employeeHousePropertyDetails)
          this.housePropertiesDataSource.paginator = this.paginator;
          this.pageLoading = results.data.length <= 20?true:false;
        }
      })
    }
  
   
    edit(ele:any){
      this.editRowDetails = ele;
      this.houseForm.setValue({
        propertyName: ele.property_name,
        purchaseFinancialYear: ele.purchase_financial_year,
        natureOfProperty: ele.nature_of_property,
        whenLoanWasTaken:ele.when_loan_was_taken,
        purposeOfLoan:ele.s24b_id,
      },{ emitEvent: false});  
      this.fileName =ele.file_name
      this.addProperty()
    }
  
    removeRow(ele:any){
      let dialogRef1 = this.dialog.open(TdsDialogsComponent, {
        position:{top:`50px`},
        disableClose: true,
        data: {regimeFlag:true, message:'Are you sure you want to delete ?'}
      });
      dialogRef1.afterClosed().subscribe((result: any) => {
        if(result){
          this.houseForm.setValue({
            propertyName: ele.property_name,
            purchaseFinancialYear: ele.purchase_financial_year,
            natureOfProperty: ele.nature_of_property,
            whenLoanWasTaken:ele.when_loan_was_taken,
            purposeOfLoan:ele.s24b_id,
          },{ emitEvent: false });  
          this.fileName =ele.file_name
          ele.isDeleted=true;
          this.editRowDetails = ele;
          this.submitHouseProperty()
        }
      })
    }
  
    closePopup() {
      this.vcr.clear(); // Remove the popup from the DOM
      this.editRowDetails = null;
      this.filesize = true;
      this.fileNameError = true;
      this.fileName =null;
      this.selectedFile = null;
    }
  
  
    getEmpBasicDeclarationDetails() {
      return new Promise((resolve)=>{
      this.tdsService.getEmpBasicDeclarationDetails(this.userSession.id, this.financialYear).subscribe((_results) => {
        if (_results && _results.status) {
          resolve(_results.data)
        }else{
          resolve([])
        }
      })
      })
    }

    validateDates(declarationOpenDate: any, declarationClosureDate: any) {
      return new Promise((resolve)=>{
        if (!declarationOpenDate) { //dates not declared 
          this.tdsService.message("The tax exemption declaration window is not yet declared. Please proceed with addition of house property once the window is declared.")
          this.isDateValidate = false;
          resolve(false) 
        } else if (declarationOpenDate && moment().startOf('day').toDate() < moment(declarationOpenDate).startOf('day').toDate()) { //dates declared but not opened
          this.tdsService.message("The tax exemption declaration window is not yet opened. Please proceed with addition of house property once the window is declared.");
          this.isDateValidate = false;
          resolve(false) 
        }
        else if( moment().startOf('day').toDate() > moment(declarationClosureDate).startOf('day').toDate()){ //dates closed 
          this.tdsService.message("The tax exemption declaration window is closed. Please contact your Finance Manager to proceed with addition of house property.");
          this.isDateValidate = false;
          resolve(false) 
        }else{
          this.isDateValidate = true;
          resolve(true) 
  
        }
      })
    }
  
  
  
    getPageSizes(): number[] {
      var customPageSizeArray = [];
      if (this.housePropertiesDataSource.data.length < 5) {
        customPageSizeArray.push(5);
      }
      if (this.housePropertiesDataSource.data.length > 5) {
        customPageSizeArray.push(5);
      }
      if (this.housePropertiesDataSource.data.length > 10) {
        customPageSizeArray.push(10);
      }
      if (this.housePropertiesDataSource.data.length > 20) {
        customPageSizeArray.push(20);
      }
      customPageSizeArray.push(this.housePropertiesDataSource.data.length);
      return customPageSizeArray;
    }
  
    onFileSelected(event: Event): void {
      const input = event.target as HTMLInputElement;
      if (input.files && input.files[0]) {
        const file = input.files[0];
        if (file) {
          const maxSize = 5 * 1024 * 1024; // 5 MB in bytes
          this.filesize = true;
          this.fileNameError =true;
          if (file.size > maxSize) {
            this.filesize = false;
            this.selectedFile = null
            return
          } if(file.name.length >90 ) {
            this.fileNameError =false;
            this.selectedFile = null
            return
          }else {
            this.selectedFile = file
          }
        }
      }
    }

    showPdf(path:any,file_name:any) {
      this.tdsService.showPdf(path,file_name)
    }
  
    deleteDocument(){
      this.fileName = null;
    }

    getSection24bLimits(){
      this.tdsService.getSection24bLimits().subscribe((results:any)=>{
        if(results && results.status){
          let data = JSON.parse(results.data[0]?.json_data);
          this.selfOccupiedLimit = null
          data.forEach((ele:any)=>{
            if(ele.rule_name === "MAXIMUM SELF-OCCUPIED HOUSE PROPERTIES"){
              this.selfOccupiedLimit = Number(ele.value)
            }
          })
        }
      })
    }
  
  
    validateEmployeeTaxExemptionStatus(): Promise<boolean>{
      return new Promise((resolve)=>{
        this.tdsService.validateEmployeeTaxExemptionStatus(this.userSession.id,this.financialYear).subscribe((results:any)=>{
          if(results && results.status&& results.data){
            if(results.data[0] && results.data[0].tds_status.toString().includes(this.activeChild?.screenid)){
              this.tdsService.message(results.data[0].tds_message)
              resolve(false)
              return;
            }else{
              resolve(true)
           }
          }else{
             resolve(true)
          }
        })
      })
  
    }

    filterEmpList(searchText: any){
      this.filteredEmployeeList = this.empList.filter((val: any) =>
        val.employee_name.toLowerCase().includes(searchText.toLowerCase()) || val.employee_code.toLowerCase().includes(searchText.toLowerCase())
      );
      if (this.filteredEmployeeList.length <= 0) {
          this.noDataFound = true
      } else {
          this.noDataFound = false
      }
    }

    getEmployeeListForExemptionSubmission(){
      let payLoad = {
        financial_year : this.financialYear
      }
      this.tdsService.getEmployeeListForExemptionSubmission(payLoad).subscribe((result:any)=>{
        this.empList = result.data;
        this.filteredEmployeeList = this.empList;
      })
    }
    view(ele: any) {
      this.info = ele;
      this.vcr.clear(); // Clear previous views if any
      this.vcr.createEmbeddedView(this.popupTemplate); // Render the popup template
    } 
    close() {
      this.info = null;
      this.vcr.clear(); // Clear previous views if any
    }

    navigationToCurrentPage(){
      this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
        this.router.navigate(["/Payroll/housePropertyByManager"]));
    }

    applyFilter(event: Event) {
      const filterValue = (event.target as HTMLInputElement).value;
      this.housePropertiesDataSource.filter = filterValue.trim().toLowerCase();
    
      if (this.housePropertiesDataSource.paginator) {
        this.housePropertiesDataSource.paginator.firstPage();
      }
    }
    resetFields(){
     this.houseForm.controls.propertyName.reset('');
     this.houseForm.controls.purchaseFinancialYear.reset('');
     this.houseForm.controls.natureOfProperty.reset('');
     this.houseForm.controls.whenLoanWasTaken.reset(''); 
     this.houseForm.controls.purposeOfLoan.reset('');
     
    } 
}
