import {  Component, OnInit, ViewChild } from '@angular/core';
import { DatePipe, formatDate } from '@angular/common';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import * as _moment from 'moment';
import { ChartComponent } from 'angular2-chartjs';
import { LearnService } from 'src/app/modules/learning/learn.service';
import { TranslateService } from '@ngx-translate/core';
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    // dateInput: 'MM-YYYY',
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
@Component({
  selector: 'app-client-sa-dashboard-learning',
  templateUrl: './client-sa-dashboard-learning.component.html',
  styleUrls: ['./client-sa-dashboard-learning.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class ClientSaDashboardLearningComponent implements OnInit {
  pipe = new DatePipe('en-US');
  companyName: any;
  branches: any[] = [];
  departments: any[] = [];
  selectedBranchIds: number[] = [];
  selectedDepartmentIds: number[] = [];
  isLmsPresent: boolean = false;

  @ViewChild('completionChart', { static: false }) completionChart!: ChartComponent;
  @ViewChild('enrollmentChart', { static: false }) enrollmentChart!: ChartComponent;

  completionChartType = 'doughnut';
  completionChartData: any = { labels: [], datasets: [{ data: [], backgroundColor: [] }] };
  completionChartOptions: any = {
  responsive: true,
  cutoutPercentage: 70,    // v2 name for “cutout”
  legend: {
    display: true,
    position: 'bottom',
    labels: {
      fontSize: 12
    }
  }
};
  enrollmentChartType = 'doughnut';
  enrollmentChartData: any = { labels: [], datasets: [{ data: [], backgroundColor: [] }] };
 
enrollmentChartOptions: any = {
  responsive: true,
  cutoutPercentage: 70,
  legend: {
    display: true,
    position: 'bottom',
    labels: {
      fontSize: 12
    }
  }
};

@ViewChild('coursePieChart', { static: false })
coursePieChart!: ChartComponent;
  coursePieType    = 'pie';
  // coursePieData: any;
  coursePieData:any = { labels: [], datasets: [{ data: [], backgroundColor: [] }] };

coursePieOptions: any = {
  responsive: true,
  legend: {
    display: true,
    position: 'bottom',
    labels: {
      fontSize: 12
    }
  }
};

  courseToDate: Date | null = new Date();
  courseFromDate: Date | null = new Date(Date.now() - 30*24*60*60*1000);
  minDate: Date = new Date(1950, 0, 1); // Disable years below 1950
  maxDate: Date = new Date();          

  constructor(
    private learnService: LearnService,private translate: TranslateService,
  ) {
    this.companyName = sessionStorage.getItem('companyName');
  }

  ngOnInit(): void {
    let  savedLang = localStorage.getItem('lang');
    this.translate.use(savedLang || 'english');

    this.getBranches();
    this.getDepartments();
    this.getLmsStatus();
  }
 
  getBranches() {
    this.learnService.getLocationMaster().subscribe({
      next: (data: any) => {
        this.branches = data.locations || data;
        if(this.branches && this.branches.length)
          this.selectedBranchIds = this.branches.map(b => b.id);
        this.loadCourseOverviewPie();
      },
      error: err => console.error(err)
    });
  }

resetCharts(): void {
  this.coursePieData = {
    labels: [],
    datasets: [{ data: [], backgroundColor: [] }]
  };

  this.completionChartData = {
    labels: [],
    datasets: [{ data: [], backgroundColor: [] }]
  };

  this.enrollmentChartData = {
    labels: [],
    datasets: [{ data: [], backgroundColor: [] }]
  };
}

  // ─── Load dept list + default-select all ───
  getDepartments() {
    this.learnService.getDepartments().subscribe({
      next: (data: any) => {
        this.departments = data.departments;
        if(this.departments && this.departments.length)
          this.selectedDepartmentIds = this.departments.map(d => d.id);
        this.loadCourseOverviewPie();
      },
      error: err => console.error(err)
    });
  }

  // ─── Toggle helpers (copy from LMS) ───
isAllBranchesSelected(): boolean {
  return this.branches.length > 0 &&
         this.selectedBranchIds.length === this.branches.length;
}

toggleAllBranches(): void {
  if (this.isAllBranchesSelected()) {
    // Deselect all branches and also clear departments (learning-progress expectation)
    this.selectedBranchIds = [];
    this.selectedDepartmentIds = [];
  } else {
    // Select all branches (leave departments as-is so user selection isn't lost unexpectedly)
    this.selectedBranchIds = this.branches.map(b => b.id);
  }

  this.loadCourseOverviewPie();
}


isAllDepartmentsSelected(): boolean {
  return this.departments.length > 0 &&
         this.selectedDepartmentIds.length === this.departments.length;
}

toggleAllDepartments(): void {
  if (this.isAllDepartmentsSelected()) {
    this.selectedDepartmentIds = [];
  } else {
    this.selectedDepartmentIds = this.departments.map(d => d.id);
  }

  this.loadCourseOverviewPie();
}


// ─── The pie-loader itself ───
loadCourseOverviewPie() {

  // ⛔ If no branches or departments selected → clear charts & stop
  if (!this.selectedBranchIds.length || !this.selectedDepartmentIds.length) {
    this.resetCharts();
    return;
  }

  const from = formatDate(this.courseFromDate!, 'yyyy-MM-dd', 'en-GB');
  const to   = formatDate(this.courseToDate!, 'yyyy-MM-dd', 'en-GB');

  // no managers/employees in this view → just pass [0]
  const managers  = [0];
  const employees = [0];

  // Load course pie chart
  this.learnService
    .getManagerDashboardPie(
      this.selectedBranchIds,
      managers,
      this.selectedDepartmentIds,
      employees,
      from,
      to
    )
    .subscribe(data => {
      const labels = Object.keys(data);
      const values = Object.values(data) as number[];
      const hasData = values.length > 0 && values.some(v => v > 0);

  if (!hasData) {
    this.coursePieData = {
      labels: [],
      datasets: [{ data: [], backgroundColor: [] }]
    };
    return;
  }

      this.coursePieData = {
        labels,
        datasets: [{
          data: values,
          backgroundColor: [
            '#ff6384',
            '#36a2eb',
            '#ffcd56',
            '#4bc0c0',
            '#9966ff',
            '#ff9f40'
          ]
        }]
      };
    });

  // Load completion & enrollment rates
  this.learnService
    .getSuperadminDashboard(this.selectedBranchIds, this.selectedDepartmentIds, from, to)
    .subscribe((res: any[]) => {
      if (!res.length) {
  this.resetCharts(); 
  return;
}
      const stats = res[0];

      const compPct   = parseFloat(stats.completion_rate);
      const enrollPct = parseFloat(stats.enrollment_rate);

      this.completionChartData = {
        labels: ['Completion Rate', ''],
        datasets: [{
          data: [compPct, 100 - compPct],
          backgroundColor: ['#36a2eb', '#e0e0e0']
        }]
      };

      this.enrollmentChartData = {
        labels: ['Enrollment Rate', ''],
        datasets: [{
          data: [enrollPct, 100 - enrollPct],
          backgroundColor: ['#4bc0c0', '#e0e0e0']
        }]
      };
    });

}

  getLmsStatus(): void {
  this.isLmsPresent = false;
  this.learnService.getLmsStatus().subscribe(
      (data: any) => { 
        const flag = (data && data.flag)? Number(data.flag):0;
        if (flag === 1) {
          this.isLmsPresent = true;
        }
      },
      (error: any) => {
        console.error('Error fetching LMS status', error);
      }
    );
  }

  // Handle date changes
  onCourseFromDateChange(event: any): void {
    if (event && event.value) {
      if (this.courseToDate && event.value > this.courseToDate) {
        this.courseFromDate = null;
        return;
      }
      this.courseFromDate = event.value;
      this.loadCourseOverviewPie();
    }
  }

  onCourseToDateChange(event: any): void {
    if (event && event.value) {
      if (this.courseFromDate && event.value < this.courseFromDate) {
        this.courseToDate = null;
        return;
      }
      this.courseToDate = event.value;
      this.loadCourseOverviewPie();
    }
  }

  hasCoursePieData(): boolean {
    const d = this.coursePieData?.datasets?.[0]?.data;
    return Array.isArray(d) && d.length > 0 && d.some((v: number) => v > 0);
  }
 
  hasCompletionData(): boolean {
    const d = this.completionChartData?.datasets?.[0]?.data;
  if (!Array.isArray(d) || d.length === 0) return false;
  // Only show chart if the actual rate (first value) is > 0
  return d[0] > 0;
  }
 
  hasEnrollmentData(): boolean {
     const d = this.enrollmentChartData?.datasets?.[0]?.data;
  if (!Array.isArray(d) || d.length === 0) return false;
  return d[0] > 0;
  }
}


