import { Component, OnInit } from '@angular/core';
import { LearnService } from '../../learn.service';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';

@Component({
  selector: 'app-lms-achivements',
  templateUrl: './lms-achivements.component.html',
  styleUrls: ['./lms-achivements.component.scss']
})
export class LmsAchivementsComponent implements OnInit {
  earnedBadges: any[] = [];
  nextTargetBadgeGroups: { category: string, badges: any[] }[] = [];
  certificates: any[] = [];

  userSession: any

  constructor(private learn: LearnService) {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');

   }

  ngOnInit(): void {
    this.getbadges(); 
    this.getCertificates();
  }


getbadges(): void {
  const userId = this.userSession.id;
  if (!userId) {
    console.warn('No user ID found in session; skipping getbadges()');
    return;
  }

  this.learn.getEmployeeBadges(userId).subscribe(
    (res: any) => {
      console.log('Raw getEmployeeBadges response:', res);
      if (!res || !Array.isArray(res.badges)) {
        console.error('Unexpected badges payload:', res);
        return;
      }

      // 1) Earned badges (status === 1)
      this.earnedBadges = res.badges.filter((b: any) => b.status === 1);
      console.log('Filtered earnedBadges:', this.earnedBadges);

      // 2) Next target badges (status === 0), grouped by raw category
      const grouped = res.badges
        .filter((b: any) => b.status === 0)
        .reduce((acc: { [cat: string]: any[] }, badge: any) => {
          const cat = badge.badge_category || 'uncategorized';
          if (!acc[cat]) {
            acc[cat] = [];
          }
          acc[cat].push(badge);
          return acc;
        }, {});

      console.log('Next-target groups before sorting:', grouped);

      // Map to title-cased category + sort badges within each group
      this.nextTargetBadgeGroups = Object.entries(grouped).map(
        (entry) => {
          const [rawCategory, badges] = entry as [string, any[]];
          return {
            category: rawCategory
              .split('_')
              .map(word => word.charAt(0).toUpperCase() + word.slice(1))
              .join(' '),
            badges: badges.sort((a, b) => a.total - b.total),
          };
        }
      );

      console.log('Next-target badgeGroups after sorting:', this.nextTargetBadgeGroups);
    },
    (err) => {
      console.error('Error fetching badges:', err);
    }
  );
}




  getCertificates(){
    const userId = this.userSession.id;

    this.learn.getEmployeeCertificates(userId, 0).subscribe((res: any[]) => {
      this.certificates = res;
    });
    
  }


  toBase64Image(base64: string): string {
    return base64;
  }

  getProgressPercentage(completed: number, total: number): number {
    return Math.min((completed / total) * 100, 100);
  }

downloadAsPng(el: HTMLElement, certificateId: string) {
  if (!(el instanceof HTMLElement)) {
    console.error('downloadAsPng: not a valid HTMLElement', el);
    return;
  }

  // 1) Grab & hide the button
  const btn = el.querySelector('.cert-download-btn') as HTMLElement | null;
  if (btn) {
    btn.style.display = 'none';
  }

  // 2) Render to canvas
  html2canvas(el, { scale: 2 })
    .then(canvas => {
      // 3) Download the blob
      canvas.toBlob(blob => {
        if (!blob) return;
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `Certificate_${certificateId}.png`;
        a.click();
        URL.revokeObjectURL(url);
      });
    })
    .catch(err => {
      console.error('html2canvas failed:', err);
    })
    .then(() => {
      // 4) Restore the button no matter what
      if (btn) {
        btn.style.display = '';
      }
    });
}




}

