import { Component, OnInit, ViewChild } from '@angular/core';
import { UntypedFormGroup, Validators, UntypedFormBuilder, UntypedFormArray } from '@angular/forms';
import { Router } from '@angular/router';
import { MatDialog } from '@angular/material/dialog';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatSelect } from '@angular/material/select';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { DatePipe } from '@angular/common';
import * as _moment from 'moment';
import { ComfirmationDialogComponent } from 'src/app/pages/comfirmation-dialog/comfirmation-dialog.component';
import { EmsService } from 'src/app/modules/ems/ems.service';
import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';
import { TranslateService } from '@ngx-translate/core';


// import {default as _rollupMoment} from 'moment';
const moment = _moment;

export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
@Component({
  selector: 'app-holidays',
  templateUrl: './holidays.component.html',
  styleUrls: ['./holidays.component.scss'],
  // 
   providers: [
    // { provide: MAT_DATE_LOCALE, useValue: 'ar' }, //  Set Arabic locale here
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class HolidaysComponent implements OnInit {
 
  HolidayForm: any = UntypedFormGroup;
  HolidayEditForm:any = UntypedFormGroup;
  selectedBranch: any = [];
  worklocationDetails: any = [];
  holidaysDetails: any = [];
  maxDate = new Date();
  isadd: boolean = false;
  isview: boolean = true;
  isEdit: boolean = true;
  isSave: boolean = false;
  ishide: boolean = false;
  ischecked: boolean = false;
  enable: any = null;
  selecteditems: any = [];
  msgEM1: any;
  msgEM2: any;
  msgEM126: any;
  msgEM127: any;
  msgEM125: any;
  msgEM114: any;
  msgEM116: any;
  msgEM115: any;
  pipe = new DatePipe('en-US');
  page = 1;
  count = 0;
  tableSize = 10;
  tableSizes = [10, 25, 50, 'All'];
  displayedColumns: string[] = ['sno', 'holiday', 'date', 'day', 'location', 'action'];
  dataSource: MatTableDataSource<any> = <any>[];
  selectedOptions: any = [];
  btnDisable:boolean = false;
  pageLoading = true;
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  userSession: any;
  companyDBName: any;
  isOptionalHoliday:boolean = true;
  optionalHolidaysList:any=[];
  publicHolidayList:any=[];
  min:any= new Date('2000-01-01');
  max: any = new Date(new Date().getFullYear(), 11, 31);
  languages = [
    { code: 'english', label: 'ENGLISH', name: 'English' },
    { code: 'arabic', label: 'ARABIC', name: 'Arabic' }
  ];
  
  constructor(private formBuilder: UntypedFormBuilder, private router: Router,
    private companyService: CompanySettingService, private dialog: MatDialog, 
    private dialogService:ReusableDialogService,
    private emsService: EmsService, private translate: TranslateService, private dateAdapter: DateAdapter<any>) { 
      this.companyDBName = sessionStorage.getItem('companyName');
    }
  messagesDataList: any = [];
  selectAll(select: MatSelect, values: any, array: any) {
    this.ishide = true;
    this.ischecked = true;
    select.value = values;
    array = values;
    this.HolidayForm.controls.branch.setValue(array)


  }

  deselectAll(select: MatSelect) {
    this.ishide = false;
    this.ischecked = false
    this.selectedBranch = [];
    select.value = [];
    this.HolidayForm.controls.branch.setValue('')

  }
  //   setDatepickerLocale(lang: string) {
  //   if (lang === 'arabic') {
  //     this.dateAdapter.setLocale('ar');  // Arabic 
  //   } else {
  //     this.dateAdapter.setLocale('en');  // English 
  //   }
  // }

  ngOnInit(): void {
   const today = new Date();
   const currentYear = today.getFullYear();
   const currentMonth = today.getMonth();
 
    this.max = currentMonth >= 3  ? new Date(currentYear + 1, 2, 31)  : new Date(currentYear, 2, 31);
    
  //  const savedLang = localStorage.getItem('lang')|| 'english';
  //  this.translate.use(savedLang);
  //  this.setDatepickerLocale(savedLang);
  const savedLang = localStorage.getItem('lang');
   this.translate.use(savedLang || 'english');

    this.getWorkLocation();
    this.getHolidays(null, null);
    this.getMessagesList();
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.HolidayForm = this.formBuilder.group(
      {
        holiday: ["", [Validators.required]],
        date: ["", Validators.required],
        branch: ["", Validators.required],
        itemdata: this.formBuilder.array([]),
        holidayType:['',Validators.required],
 
      });
    this.HolidayEditForm = this.formBuilder.group(
      {
        date: ["", Validators.required],
        branch: ["", Validators.required],
        radioButton:['1'],
        holiday: ["", [Validators.required]],
      }
    )
  }
  getWorkLocation() {
    this.companyService.getActiveBranchCities()
      .subscribe((result: any) => {
        if (result.status) {
          this.worklocationDetails = JSON.parse(result.data)
        }
      })
  }

  itemdata(): UntypedFormArray {
    return this.HolidayForm.get("edu") as UntypedFormArray
  }
  submit() {
 
    this.selecteditems = [];
    if (this.HolidayForm.valid) {
      if (this.btnDisable) {
        return;
      }

      let location = this.HolidayForm.controls.branch.value;
      location.forEach((e: any) => {
        this.selecteditems.push(e.city);
      });
      let year = this.pipe.transform(this.HolidayForm.controls.date.value, 'yyyy')
      let data = {
        hid: null,
        holiday_year: year,
        holiday_description: this.HolidayForm.controls.holiday.value.replace(/\s{1,}/g, ' ').trim(),
        holiday_date: this.pipe.transform(this.HolidayForm.controls.date.value, 'yyyy-MM-dd'),
        holiday_location: this.selecteditems,
        createdby: this.userSession.id,
        holidayType: this.HolidayForm.controls.holidayType.value,

      };
      if (this.HolidayForm.controls.holiday.value !== null && this.holidaysDetails.holidayName !== null) { }
    
      this.btnDisable = true;
      this.companyService.setHolidays(data).subscribe((data) => {
        if (data.status && data.data == 0) {
          this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
          this.router.navigate(["/Admin/Holidays"]));
          this.dialogService.openDialog(this.msgEM114);
         
        } else if (data.status && data.data == 1) {
          this.dialogService.openDialog('Record already exists.');
          this.btnDisable = false;
        }
        else {
          this.dialogService.openDialog(this.msgEM125);
          this.btnDisable = false;
        }
      })
    }
  }

  add() {
    this.isview = false;
    this.isadd = true;
    this.HolidayForm.controls.holiday.setValue()
    this.HolidayForm.controls.branch.value
    this.HolidayForm.controls.holiday.value
    this.HolidayForm.controls.date.setValue();
  }
  /**Search functionality */
  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }

  }
  getHolidays(year: any, locationId: any) {

    this.companyService.getHolidays(year, locationId,0, 1, 10000).subscribe((result) => {
      if (result.status) {
        this.holidaysDetails = result.data;

        for (let i = 0; i < this.holidaysDetails.length; i++) {
          this.holidaysDetails[i].city = this.holidaysDetails[i].cityname;
          this.holidaysDetails[i].date = (this.holidaysDetails[i].date);
          if(this.holidaysDetails[i].isOptionalHoliday==0){
            this.publicHolidayList.push(this.holidaysDetails[i])
          }else{
            this.optionalHolidaysList.push(this.holidaysDetails[i])
          }
        }
        this.dataSource = new MatTableDataSource(this.publicHolidayList);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;
        // this.count = result.data.length >0?result.data[0].total:0;
      }

    })

  }
  getPageSizes(): number[] {
    var customPageSizeArray = [];

    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);

    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }
  // deleteHolidayPopup(event: any, holidayId: any) {
  //   let dialogRef = this.dialog.open(ComfirmationDialogComponent, {
  //     position: { top: `70px` },
  //     disableClose: true,
  //     data: { message: "Are you sure you want to delete ?", YES: 'YES', NO: 'No' }
  //   });
  //   dialogRef.afterClosed().subscribe(result => {
  //     if (result == 'YES') {
  //       this.deleteHoliday(event, holidayId)
  //     }
  //   });
  // }
  
deleteHolidayPopup(event: any, holidayId: any) {
  // Get translated strings
  const message = this.translate.instant('DELETE_CONFIRMATION'); 
  const yesText = this.translate.instant('Yes'); 
  const noText = this.translate.instant('No');  

  // Open confirmation dialog
  const dialogRef = this.dialog.open(ComfirmationDialogComponent, {
    position: { top: '70px' },
    disableClose: true,
    data: { message, YES: yesText, NO: noText }
  });

  // Handle dialog result
  dialogRef.afterClosed().subscribe(result => {
    console.log('Dialog result:', result); 
    if (result?.toUpperCase() === yesText.toUpperCase()) {
      // Call your delete method
      this.deleteHoliday(event, holidayId);
    }
  });
}

  deleteHoliday(event: any, holidayId: any) {

    this.companyService.deleteHoliday(holidayId).subscribe(data => {
        console.log('Delete API response:', data);

      if (data.status) {
        this.dialogService.openDialog(this.msgEM116);
        this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
          this.router.navigate(["/Admin/Holidays"]));
      } else {
        this.dialogService.openDialog(this.msgEM127);
      
      }

    })
  }
  cancel() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Admin/Holidays"]));

  }
  edit(event: any, row: any) {
    for (let i = 0; i < this.worklocationDetails.length; i++) {
      if (this.worklocationDetails[i].cityname == row.cityname) {
        this.HolidayEditForm.controls.branch.setValue(this.worklocationDetails[i].city)
        break;
      }
    }
    this.enable = row.id;
    this.isEdit = false;
    this.isSave = true;
    this.HolidayEditForm.controls.holiday.setValue(row.description)
    // this.HolidayForm.controls.branch.setValue(row.cityname)
    this.HolidayEditForm.controls.date.setValue(new Date(row.date))
  }

  canceledit(event: any, id: any) {
    this.enable = null;
    this.isEdit = true;
    this.isSave = false;
    // this.ngOnInit();

  }

  update(event: any, id: any, holiday: any, city: any, date: any) {
    if (this.HolidayEditForm.valid) {
      if (this.btnDisable) {
        return;
      }
      let year = this.pipe.transform(date, 'yyyy');
      let cities = [];
      cities.push(city);
      let data = {
        hid: id,
        holiday_year: year,
        holiday_description: holiday.replace(/\s{1,}/g, ' ').trim(),
        holiday_date: this.pipe.transform(date, 'yyyy-MM-dd'),
        holiday_location: cities,
        createdby: this.userSession.id,
      };

      this.btnDisable = true;
      this.companyService.setHolidays(data).subscribe((data) => {

        if (data.status && data.data == 0) {
          this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
            this.router.navigate(["/Admin/Holidays"]));
          this.dialogService.openDialog(this.msgEM115);
            
        } else if (data.status && data.data == 1) {
          this.dialogService.openDialog('Record already exists');
           this.btnDisable = false;
        }
        else {
          this.dialogService.openDialog(this.msgEM125);
          this.btnDisable = false;
        }
      })

    }

  }

  getMessagesList() {
    let data =
    {
      "code": null,
      "pagenumber": 1,
      "pagesize": 1000
    }

    this.emsService.getMessagesListApi(data).subscribe((result: any) => {
      if (result.status) {
        this.messagesDataList = result.data;
        this.messagesDataList.forEach((e: any) => {
          if (e.code == "EM1") {
            this.msgEM1 = e.message
          } else if (e.code == "EM2") {
            this.msgEM2 = e.message
          } else if (e.code == "EM114") {
            this.msgEM114 = e.message
          } else if (e.code == "EM126") {
            this.msgEM126 = e.message
          } else if (e.code == "EM125") {
            this.msgEM125 = e.message
          } else if (e.code == "EM127") {
            this.msgEM127 = e.message
          } else if (e.code == "EM115") {
            this.msgEM115 = e.message
          } else if (e.code == "EM116") {
            this.msgEM116 = e.message
          }
        })
      } else {
        this.messagesDataList = [];
      }

    })


  }

  onSelectionChange(event: any) {
    this.selectedOptions = event.value;
    if (this.selectedOptions.length === this.worklocationDetails.length) {
      this.ishide = true;
    }
  }

  radioChange(event:any){
    if(event.value == '1'){
      this.dataSource = new MatTableDataSource(this.publicHolidayList);
      this.dataSource.paginator = this.paginator;
      this.dataSource.sort = this.sort;
      this.pageLoading = false;
    }else{
      this.dataSource = new MatTableDataSource(this.optionalHolidaysList);
      this.dataSource.paginator = this.paginator;
      this.dataSource.sort = this.sort;
      this.pageLoading = false;
    }
  }
}
