import { Injectable,LOCALE_ID,Inject } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import {Observable,of } from "rxjs/index";
import {environment} from "../../../environments/environment";
import { DatePipe } from '@angular/common';
@Injectable({
    providedIn: 'root'
  })

  export class ClaimsService {
  getFilteredClaims(requestData: { companylocation: any; managers: any; Users: any; }) {
    throw new Error('Method not implemented.');
  }
    mainUrl = environment.apiUrl;
    userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    httpOptions:any;
    companyName:any;
    constructor(@Inject(LOCALE_ID) private locale: string,private http: HttpClient,private pipe: DatePipe,
       //private deviceDetectorService: DeviceDetectorService
        ) {

      this.httpOptions = {
        headers: new HttpHeaders({
          'content-Type': 'application/json',
          "Authorization": JSON.parse(JSON.stringify(sessionStorage.getItem('token') || '')),
        })
      };
    }

    getCompany(){
      this.companyName=sessionStorage.getItem("companyName")?sessionStorage.getItem("companyName"):null;
      return sessionStorage.getItem("companyName")?sessionStorage.getItem("companyName"):null;
    }

    getMastertable(tableName:any,status:any,page:any,size:any,companyName:any):Observable<any>{
        return this.http.get(this.mainUrl+'commonApi/getMastertable/'+tableName+'/'+status+'/'+page+'/'+size+'/'+this.getCompany(), this.httpOptions);
    }

    getCountry(  status: any, page: any, size: any): Observable<any>{
        return this.http.get(this.mainUrl + 'commonApi/getMastertable/' + 'countrymaster' + '/' + status + '/' + page + '/' + size + '/' + this.getCompany(), this.httpOptions);
    }

    getClaimsReimbursementTypes(pagenumber:any,pagesize:any):Observable<any>{
           return this.http.get(this.mainUrl+'claims/getClaimsReimbursementTypes/'+pagenumber+'/'+pagesize+'/'+this.getCompany(), this.httpOptions);
    }
    getClaimsActiveReimbursementTypes():Observable<any>{
      let emp_id=0;
      return this.http.get(this.mainUrl+'claims/getClaimsActiveReimbursementTypes/'+emp_id+'/'+this.getCompany(), this.httpOptions);
   }

    getClaimsReimbursementRequests(data:any):Observable<any>{
      data.companyName=this.getCompany();
      return this.http.get(this.mainUrl+'claims/getClaimsReimbursementRequests/'+JSON.stringify(data),this.httpOptions);
    }

    setClaimsReimbursementTypes(info:any){
      info.companyName=this.getCompany();
      return this.http.post(this.mainUrl + 'claims/setClaimsReimbursementTypes',(info) , this.httpOptions);
    }

    setClaimsEmployeeReimbursementRequest(info:any){
      info.companyName=this.getCompany();
      return this.http.post(this.mainUrl + 'claims/setClaimsEmployeeReimbursementRequest',(info) , this.httpOptions);
    }

    getFormattedDateTime(date:any = null){
      if(!date)
      date = new Date();
      else date = new Date(date);
      return this.pipe.transform(date, 'dd-MM-yyyy') +' '+date.toLocaleTimeString(this.locale, {hour12: true, hour: '2-digit',minute: '2-digit' });
    }

    getFormattedDate(date:any = null) {
      if(!date)
      date = new Date();
      else date = new Date(date);
      return this.pipe.transform(date, 'dd-MM-yyyy');
    }

    getClaimsEmployeeWiseDetailedReport(data:any):Observable<any>{
      data.companyName=this.getCompany();
      return this.http.get(this.mainUrl+'claims/getClaimsEmployeeWiseDetailedReport/'+JSON.stringify(data),this.httpOptions);
    }

    setClaimRequest(info: any): Observable<any> {
      info.companyName = this.getCompany();  // Include the company name in the request
      return this.http.post(this.mainUrl + 'claims/setClaimRequest', info, this.httpOptions);  // Call the API
    }

    setClaimRequestBill(info: any): Observable<any> {
      info.companyName = this.getCompany();  // Include the company name in the request
      return this.http.post(this.mainUrl + 'claims/setClaimRequestBill', info, this.httpOptions);  // Call the API
    }


  getSprypleData(data: any,procedure:any): Observable<any> {
    if(data && typeof data == 'object'){
        data = JSON.stringify(data);
    }
    if(procedure)
    return this.http.get(this.mainUrl + 'api/getSprypleData/' + data + '/'+ procedure + '/' + this.getCompany(), this.httpOptions);
    else 
    return of({ status: false, Message: 'Please provide procedure' });
  }

  getClmSelectedRequestData(claim_id:any):Observable<any>{
    return this.http.get(this.mainUrl+'claims/getClmSelectedRequestData/'+claim_id+ '/' + this.getCompany(),this.httpOptions);
  }
  
  setClmApproval(info:any){
    info.companyName=this.getCompany();
    return this.http.post(this.mainUrl + 'claims/setClmApproval',(info) , this.httpOptions);
  }
    setClmRbsType(info: any): Observable<any> {
      info.companyName = this.getCompany();  
      return this.http.post(this.mainUrl + 'claims/setClmRbsType', info, this.httpOptions);  
    }

  getClmRbsTypes(pagenumber: any, pagesize: any): Observable<any> {
    return this.http.get(this.mainUrl + 'claims/getClmRbsTypes/' + pagenumber + '/' + pagesize + '/' + this.getCompany(), this.httpOptions);
  }

  getClmActiveRbsTypes(): Observable<any> {
    let emp_id = 0;
    return this.http.get(this.mainUrl + 'claims/getClmActiveRbsTypes/' + emp_id + '/' + this.getCompany(), this.httpOptions);
  }

  getClmRbsPriceRevisions(p_reimbursement_type_id: number): Observable<any> {
    return this.http.get(this.mainUrl + 'claims/getClmRbsPriceRevisions/' + p_reimbursement_type_id + '/' + this.getCompany(), this.httpOptions);
  }
  
  getgetemployeesByMangerId(employee_id: any): Observable<any> {
    return this.http.get(this.mainUrl + 'attendance/api/getEmployeesByManagerId/' + employee_id + '/' + this.companyName, this.httpOptions);
}

setClmRbsTypeStatus(info: any): Observable<any> {
  info.companyName = this.getCompany();  
  return this.http.post(this.mainUrl + 'claims/setClmRbsTypeStatus', info, this.httpOptions);  
}

CapitalizeFirstLetter (value:any) { 
    if (!value) return '';
    return value.charAt(0).toUpperCase() + value.slice(1).toLowerCase();
  }

}
