getDesignationsFromMappingtable(deptId: any, callback?: () => void) {
  const payload = { department_id: Number(deptId) };

  this.adminService.getDepartDesigMapping(payload).subscribe((res: any) => {
    if (res.status && Array.isArray(res.data) && Array.isArray(res.data[0])) {
      this.designationsList = res.data[0];
      this.filteredDesignations = [...this.designationsList];
      console.log("filteredDesignationsfilteredDesignations",this.filteredDesignations)
    } else {
      this.designationsList = [];
      this.filteredDesignations = [];
    }

    if (callback) callback();
  });
}


