 // Add this property

applySearchFilter(event: Event): void {
  const value = (event.target as HTMLInputElement).value.trim();

  // Empty input → no error, clear table
  if (value.length === 0) {
    this.searchError = false;
    this.dataSource = new MatTableDataSource<any>([]);
    return;
  }

  // 1–2 characters → show error
  if (value.length < 3) {
    this.searchError = true;
    this.dataSource = new MatTableDataSource<any>([]);
    return;
  }

  // Valid input (3+ characters)
  this.searchError = false;

  const payload = {
    companyName: this.companyDBName,
    search: value,
    search_by: 1
  };

  this.spinner.show();
  this.emsService.getEmployeesDetailsBySearch(payload)
    .subscribe(
      (res: any) => {
        this.spinner.hide();
        if (res.status) {
          this.dataSource = new MatTableDataSource(res.data);
          this.dataSource.paginator = this.paginator;
          this.dataSource.sort = this.sort;
          this.lastData = res.data;
        } else {
          this.dataSource = new MatTableDataSource<any>([]);
        }
      },
      (err) => {
        this.spinner.hide();
        console.error(err);
      }
    );
}
  
