  getFormattedRoles(employee: any): string {
  if (!employee?.rolenames) return 'Not Assigned';

  try {
    // Parse the stringified JSON array
    const roles = JSON.parse(employee.rolenames);
    // Join array elements with comma and space
    return Array.isArray(roles) ? roles.join(', ') : employee.rolenames;
  } catch {
    // fallback if parsing fails
    return employee.rolenames;
  }
}


