 getEmployerDetails(row: any): string {
  // Helper to format date as dd-MM-yyyy
  const formatDate = (dateStr: string) => {
    if (!dateStr) return '';
    const d = new Date(dateStr);
    const day = ('0' + d.getDate()).slice(-2);
    const month = ('0' + (d.getMonth() + 1)).slice(-2);
    const year = d.getFullYear();
    return `${day}-${month}-${year}`;
  };

  const details = [
    `Joining Date: ${formatDate(row.dateofjoin)} |`,
    `Hired On: ${formatDate(row.hired_date)} |`,
    `Role: ${row.rolenames ? row.rolenames.replace(/[\[\]"]/g,'').replace(/,/g, ', ') : 'Not Assigned'} |`
  ];

  // Add termination info if employee is not Hired/Active
  if (row.employee_status !== 'Hired' && row.employee_status !== 'Active') {
    details.push(`Termination Reason: ${row.exit_comments || 'NA'} |`);
    details.push(`Termination Date: ${formatDate(row.exit_on) || 'NA'} |`);
  }

  return details.join('\n');
}
onSearchClick(control?: any) {
  if (control?.control) {
    control.control.markAsTouched();
    control.control.updateValueAndValidity();
  }

  const value = this.searchValue.trim();

  if (value.length < 3) {
    this.searchError = true;
    this.dataSource = new MatTableDataSource<any>([]);
    return;
  }

  this.searchError = false;

  const payload = {
    companyName: this.companyDBName,
    search: value,
    search_by: 1
  };

  this.spinner.show();
  this.emsService.getEmployeesDetailsBySearch(payload).subscribe(
    (res: any) => {
      this.spinner.hide();
      if (res.status) {
        this.dataSource = new MatTableDataSource(res.data);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.lastData = res.data;
      } else {
        this.dataSource = new MatTableDataSource<any>([]);
      }
    },
    (err) => {
      this.spinner.hide();
      console.error(err);
    }
  );
}


onCancelClick(control: any) {
  this.searchValue = '';
   if (control) {
    control.reset(); // resets the ngModel without triggering validation
  }
  // this.searchError = false;
 this.dataSource = new MatTableDataSource<any>([]);
  this.dataSource.paginator = this.paginator;
  this.dataSource.sort = this.sort;

}



