import { Component, Inject, OnInit } from '@angular/core';
import { MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';

@Component({
  selector: 'app-tds-dialogs',
  templateUrl: './tds-dialogs.component.html',
  styleUrls: ['./tds-dialogs.component.scss']
})
export class TdsDialogsComponent implements OnInit {

  constructor(public dialogRef: MatDialogRef<TdsDialogsComponent>,
    @Inject(MAT_DIALOG_DATA) public data: any) { }

  ngOnInit(): void {
  }

  ok(){
    this.dialogRef.close(true)
  }
}
