import { Component, OnInit, TemplateRef, ViewChild } from '@angular/core';
import { FormBuilder, UntypedFormGroup, Validators } from '@angular/forms';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { PayrollService } from '../../payroll.service';
import { DialogComponent } from '../../dialog/dialog.component';
import { MatDialog } from '@angular/material/dialog';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { Router } from '@angular/router';

@Component({
  selector: 'app-variable-pay-schedule',
  templateUrl: './variable-pay-schedule.component.html',
  styleUrls: ['./variable-pay-schedule.component.scss']
})
export class VariablePayScheduleComponent implements OnInit {

  constructor( private payrollService:PayrollService, 
    private formBuilder:FormBuilder,
    public dialog: MatDialog,
    private router: Router ) { }
  scheduleForm: any = UntypedFormGroup;
  dataSource: MatTableDataSource<any> = <any>[];
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort) sort!: MatSort;
  @ViewChild('dialogTemplate') dialogTemplate!: TemplateRef<any>;

  displayedColumns: string[] = ['sno','year','duration','value','save','denied'];
  variableList:any = [];
  pageLoading = true;
  permisionList:any = [{id:1,value:'Allow'},{id:2,value:'Denied'}]
  variablePayTypeList:any = [{id:'Lumpsum',value:'Lump Sum'},{id:'Monthly',value:'Monthly Share'}];
  selectedFrequency:any;
  deniedRemarks: string = '';
  payScheduleDetails: any = [];
  userSession: any;
  remarksView:any;
  ngOnInit(): void {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.scheduleForm = this.formBuilder.group({
        distributionType : ['',Validators.required]
    })
    this.getVariablePayList();
  }

  getVariablePayList() {
    this.variableList = [];

      this.payrollService.getVariablePaySchedule().subscribe((res: any) => {
        if (res.status && res.data.length > 0 ) {
            this.variableList = res.data;
            // this.variableList.array.forEach((val:any) => {
              
            // });
            this.dataSource = new MatTableDataSource(this.variableList);
            this.pageLoading = false;
       
      } else{
        this.dataSource = new MatTableDataSource(this.variableList);
        this.pageLoading = false;

      }
    })
  }


  onTypeChange(event: any, element: any) {
    this.selectedFrequency = event.value;
  }

  submit(data:any){
    
    if( this.scheduleForm.valid ){

    this.payScheduleDetails =[];
    this.payScheduleDetails.push({
      id:data.id,
      status:data.status,
      distribution_frequency:this.selectedFrequency,
    });

    let value = {
      "json_val": this.payScheduleDetails,
      "action_by":parseInt(this.userSession.id),
    }
    this.payrollService.setVariablePayConfiguration(value).subscribe((res: any) => {
      if (res.status ) {
        let dialogRef = this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: "Data is saved successfully."
        });
        this.clear();
      } else{
        let dialogRef = this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: "Unable to save data."
        });
        this.getVariablePayList();
      }
    });
  }
  }

  denied(data:any){
    const dialogRef = this.dialog.open(DialogComponent, {
      width: '450px', position: { top: `100px` },
      data: { reason: this.deniedRemarks, }
    });

    dialogRef.afterClosed().subscribe(result => {

      if (result != undefined) {
        if (result !== true) {
          this.deniedRemarks = result.reason;
          this.deniedSubmit(data);
        }
      }
    });
  }



  deniedSubmit(data:any){
    this.payScheduleDetails =[];
    this.payScheduleDetails.push({
      id:data.id,
      status:'Denied',
      remarks:this.deniedRemarks
    });

    let value = {
      "json_val": this.payScheduleDetails,
      "action_by":parseInt(this.userSession.id),
    }
    this.payrollService.setVariablePayConfiguration(value).subscribe((res: any) => {
      if (res.status ) {
        let dialogRef = this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: "Data is saved successfully."
        });
        this.clear();
      } else{
        let dialogRef = this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: "Unable to save data."
        });
        this.getVariablePayList();
      }
    });
 
  }
  requestView(data:any){

    this.remarksView = data.remarks;
    const dialogData = data.remarks;
    this.dialog.open(this.dialogTemplate, {
      data: dialogData,
    });

  }
  clear(){
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Payroll/variablePaySchedule"]));
  }
}
