// Allow all past dates and today, disable future dates
disableFutureDates = (d: Date | null): boolean => {
  if (!d) return false;
  const today = new Date();
  today.setHours(0, 0, 0, 0); // ignore time
  const date = new Date(d);
  date.setHours(0, 0, 0, 0);
  return date <= today; // true = selectable
};

onReportTypeChange1(event: any) {
  const reportType = event.value;
  this.searchForm.controls['reportType'].setValue(reportType);

  const today = new Date();

  if (reportType === 'custom') {
    // Set default From Date = today
    this.searchForm.controls['fromDate'].setValue(today);
    this.searchForm.controls['toDate'].setValue(today);

    // FROM-DATE allowed: all past + today
    this.minFromDate = null;   // optional
    this.maxFromDate = today;  // future dates disabled visually

    // TO-DATE allowed: same logic (or use minToDate = fromDate)
    this.minToDate = today;
    this.maxToDate = today;
  } else {
    this.setMonthDateRange();
  }

  this.Searchform();
}








