  setMonthDateRange() {
      let sDate: any = moment(this.selectedMonth).startOf('month');
      let eDate: any = moment(this.selectedMonth).endOf('month');
      if(this.reportType == 2){
        this.searchForm.controls['fromDate'].enable() 
      }
        else this.searchForm.controls['fromDate'].disable();  
       
       if (this.reportType == 1) {     //'leave window'
        if(!this.leaveWindowStartDate){
          this.getLeaveDate();
          return;
        }
        else{
          this.searchForm.controls['fromDate'].disable();
          if (this.leaveWindowStartDate === 'LAST_BUT_2_DAYS') {
            sDate = moment(this.selectedMonth).subtract(1, 'month').endOf('month').subtract(2, 'days').startOf('day');  
            eDate = moment(this.selectedMonth).endOf('month').subtract(3, 'days').startOf('day');
          } else if (this.leaveWindowStartDate === 'LAST_BUT_1_DAY') {
            sDate = moment(this.selectedMonth).subtract(1, 'month').endOf('month').subtract(1, 'days').startOf('day');  
            eDate = moment(this.selectedMonth).endOf('month').subtract(2, 'days').startOf('day');
          } else if (this.leaveWindowStartDate === 'LAST_DAY') {
            sDate = moment(this.selectedMonth).subtract(1, 'month').endOf('month').startOf('day');  
            eDate = moment(this.selectedMonth).endOf('month').subtract(1, 'day').startOf('day');
          } else {
            const startDate = Number(this.leaveWindowStartDate);
            sDate = moment(this.selectedMonth).subtract(1, 'month').startOf('month').add(startDate - 1, 'days').startOf('day');
            eDate = moment(this.selectedMonth).startOf('month').add(startDate - 2, 'days').startOf('day');
          }     
        }   
      }
       (moment(eDate).isAfter(moment())) ? eDate = moment() :null;
       if(this.reportType != 2){
          this.minToDate = sDate.toDate();
          this.maxToDate = eDate.toDate();
       } 
     
       this.searchForm.controls['fromDate'].setValue(sDate.toDate());
       this.searchForm.controls['toDate'].setValue(eDate.toDate());
       this.dateRangeLabel = `${sDate.format('DD MMM YYYY')} - ${eDate.format( 'DD MMM YYYY' )}`;
    }

 
