onFromDateChange(event: any) {
  
  const fromVal = this.searchForm.controls.fromDate.value;
  if (!fromVal) return;

  const fromM = moment(fromVal).startOf('day');
  const today = moment().startOf('day');

  if (this.reportType == 2 ) {
     const toVal = this.searchForm.controls.toDate.value
    // this.searchForm.controls['toDate'].setValue(null);
    this.minToDate = fromM.toDate();     // To >= From
    this.maxToDate = today.toDate();     // To <= Today
    if (toVal) {
    const toM = moment(toVal).startOf('day');
    if (fromM.isAfter(toM)) {
      this.searchForm.controls['toDate'].setValue(null);
    }
  }
    return;
  }

}



onToDateChange(event: any) {
 
  const fromVal = this.searchForm.controls.fromDate.value;
  const toVal = this.searchForm.controls.toDate.value;
  if (!fromVal || !toVal) return;

  const fromM = moment(fromVal);
  const toM = moment(toVal);

  if (this.reportType == 2 ) {
    this.dateRangeLabel = `${fromM.format('DD MMM YYYY')} - ${toM.format('DD MMM YYYY')}`;
    return;
  }

  // Existing validation for calendar/leave window
  if (toM.isBefore(fromM)) {
    this.searchForm.patchValue({ toDate: null });
    return;
  }
  this.dateRangeLabel = `${fromM.format('DD MMM YYYY')} - ${toM.format('DD MMM YYYY')}`;
}
toDateFilter = (d: Date | null): boolean => {
  if (!d) return false;

  const reportType = this.searchForm.controls.reportType.value;
  const date = moment(d).startOf('day');

  if (reportType == 2) {

    const fromVal = this.searchForm.controls.fromDate.value;
    const fromMoment = fromVal ? moment(fromVal).startOf('day') : null;
    const today = moment().startOf('day');

    // If FROM not selected → only allow TODAY and before
    if (!fromMoment) {
      return date.isSameOrBefore(today);
    }

    // If FROM selected → To-Date allowed: fromDate … today
    return (
      date.isSameOrAfter(fromMoment) &&
      date.isSameOrBefore(today)
    );
  }

  // NON-CUSTOM
  return true;
};


fromDateFilter = (d: Date | null): boolean => {
  if (!d) return false;

  const reportType = this.searchForm.controls.reportType.value;
  const date = moment(d).startOf('day');

  // CUSTOM → allow selecting ANY from-date
  if (this.reportType == 2) return true;

  // NON-CUSTOM → use monthly restriction
  if (this.minFromDate && date.isBefore(moment(this.minFromDate).startOf('day'))) return false;
  if (this.maxFromDate && date.isAfter(moment(this.maxFromDate).endOf('day'))) return false;

  return true;
};





