// helpers: normalize header name for robust matching
private normalizeKey(k: any): string {
  if (k === null || k === undefined) return '';
  return String(k).replace(/[_\s.-]/g, '').toLowerCase();
}

/**
 * background + cell layout (kept similar to your previous logic)
 * value: cell value (could be 'A', 'P' or a number, etc.)
 * key: header key name like '01_Mon' or 'Absents' or 'Presents'
 */
getCellStyle(value: any, key: string) {
  return {
    'background-color':
      value === 'A'
        ? '#F5DADF'                   // Absent → Light Red background
        : (value === 'H' || value === 'W')
        ? '#E2E5DE'                   // Holiday / Weekoff → Grey
        : '#ffffff',                  // Others → White

    'text-align': 'center',
    'padding': '4px'
  } as {[k:string]: any};
}

/**
 * Return the text color for a given cell.
 * - Numeric Absents => red
 * - Numeric Presents => green
 * - Letter status codes (A/P/H/W/L/HD/...) still get the corresponding color
 * - Totals rows are handled specially (still preserved)
 */
getCellTextColor(cellValue: any, headerKey: any, isTotals: boolean = false, rowItem?: any): string {
  const raw = (cellValue ?? '').toString().trim();
  const keyNorm = this.normalizeKey(headerKey);

  // 1) Totals-row special coloring (use your previous totals-detector if present)
  if (isTotals && rowItem) {
    const t = this.getTotalsRowType(rowItem);
    switch (t) {
      case 'employees': return 'black';
      case 'presents':  return 'green';
      case 'weekoffs':  return 'blue';
      case 'leaves':    return '#FFA500';   // orange
      case  'lop':    return '#FFA500';
      case 'holidays':  return '#8B4513';   // brown
      case 'absents':   return 'red';
      default: return 'black';
    }
  }

  // 2) If the header name indicates Presents/Absents (numeric columns)
  if (keyNorm.includes('present') || keyNorm.includes('presents')) {
    // if numeric and >0 → green; else keep default (black or 0)
    const n = Number(raw);
    return (!isNaN(n) && n > 0) ? 'green' : 'black';
  }
  if (keyNorm.includes('absent') || keyNorm.includes('absents')) {
    const n = Number(raw);
    return (!isNaN(n) && n > 0) ? 'red' : 'black';
  }
   if (keyNorm.includes('leaves') || keyNorm.includes('leave') || keyNorm.includes('lop')) {
    const n = Number(raw);
    return (!isNaN(n) && n > 0) ? '#ff8c00' : 'black';
  }

  // 3) If the cell value is a known status code (A,P,H,W,L,HD,WP,HP,HL)
  const code = raw.toUpperCase();
  if (code === 'P') return 'green';
  if (code === 'A') return 'red';
  if (code === 'H') return '#800000';
  if (code === 'W') return 'blue';
  if (code === 'L') return '#ff8c00';
  if (code === 'HD') return '#ce06e4';
  if (code === 'WP') return '#06c3e4';
  if (code === 'HP') return '#06e471';
  if (code === 'HL') return '#8338ec';
  if (code == "CL") return '#ff8c00';
  if (code == "BL") return '#ff8c00';
  if (code == "SL") return '#ff8c00';      
  if (code == "LOP") return '#ff8c00';
  if (code == "CPL") return '#ff8c00';
  if (code == "MTL") return '#ff8c00';
  if (code == "PTL") return '#ff8c00';
  if (code == "EL") return  '#ff8c00';
  if (code == "ML") return '#ff8c00';
  

  // 4) late_count style (if you want late counts red when >0)
  if (keyNorm.includes('late') || keyNorm.includes('latecount') || keyNorm.includes('late_count')) {
    const n = Number(raw);
    return (!isNaN(n) && n > 0) ? 'red' : 'black';
  }

  // default fallthrough
  return 'black';
}


// Text color logic (same as your old getColor function)
isTotalsRow(row: any): boolean {
  if (!row) return false;

  // If any cell contains 'total' or 'totals' (case-insensitive) treat as totals row
  return Object.values(row)
    .some(v => {
      if (v === null || v === undefined) return false;
      return String(v).toLowerCase().includes('total');
    });
}
/** treat keys like 'sno','s_no','S.No','S_No','S' as serial column */
isSerialKey(key: any): boolean {
  if (!key && key !== 0) return false;
  const normalized = String(key).toLowerCase().replace(/[^a-z0-9]/g, '');
  // normalized will convert "S_No" -> "sno", "S.No" -> "sno", "S" -> "s"
  return normalized === 'sno' || normalized === 's';
}





// determine what kind of totals row this is by scanning the row text
getTotalsRowType(item: any): 'employees'|'presents'|'weekoffs'|'leaves'|'lop'|'holidays'|'absents'|null {
  if (!item) return null;
  const allText = Object.values(item)
    .map(v => String(v || '').toLowerCase())
    .join(' ');

  if (allText.includes('employees total') || allText.includes('employees total')) return 'employees';
  if (allText.includes('presents total') || allText.includes('presents total') || allText.includes('present total')) return 'presents';
  if (allText.includes('week-offs total') || allText.includes('week offs total') || allText.includes('week-offs') || allText.includes('week offs')) return 'weekoffs';
  if (allText.includes('leaves total') || allText.includes('leaves')) return 'leaves';
  if (allText.includes('lop total') || allText.includes('lop')) return 'lop';
  if (allText.includes('holidays total') || allText.includes('holidays') || allText.includes('holiday total')) return 'holidays';
  if (allText.includes('absents total') || allText.includes('absents') || allText.includes('absent total')) return 'absents';

  return null;
}

