import { Component, OnInit, ViewChild } from '@angular/core';
import { DatePipe } from '@angular/common';
import { NgxSpinnerService } from 'ngx-spinner';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import * as _moment from 'moment';
import { TranslateService } from '@ngx-translate/core';
import { CrmService } from 'src/app/modules/crm/crm.service';
//import ChartDataLabels from 'chartjs-plugin-datalabels';
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    // dateInput: 'MM-YYYY',
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
@Component({
  selector: 'app-client-sa-dashboard-crm',
  templateUrl: './client-sa-dashboard-crm.component.html',
  styleUrls: ['./client-sa-dashboard-crm.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class ClientSaDashboardCrmComponent implements OnInit {
  pipe = new DatePipe('en-US'); 
  currentYear: any = new Date();
  companyName: any;
  minDate = new Date('2000/01/01');
  maxDate = new Date();
 // ChartDataLabels = ChartDataLabels; 
   deptWisePayrollbgColor: any[] = ["#118ab2", "#ffd166", "#06d6a0", "#28acaf", "#ef476f", "#ffa1b5",
    "#86c7f3", "#ffe29a", "#838c95", "#7FDBFF", "#a7c957", "#c385d8",];
  crm_counts:any = [];
  reference_tbl:any = []; 
  crm_charts:any = {
    predective:{type:'bar',data:[],options:{Response:true} },
    revenue:{type:'bar',data:[],options:{Response:true}} ,
    toppers:{type:'bar',data:[],options:{Response:true}} ,
    team:{type:'line',data:[],options:{Response:true}} ,
    source:{type:'pie',data:[],options:{Response:true}},
    ratio:{type:'doughnut',data:[],options:{Response:true},labels:[]}
  }; 

 constructor(private spinner: NgxSpinnerService, private crm:CrmService,private translate: TranslateService,) {
    this.companyName = sessionStorage.getItem('companyName');
 }
  ngOnInit(): void {
    //  let  savedLang = localStorage.getItem('lang') || ;
    // this.translate.use(savedLang || 'english');
    this.getCrmLeadsAndStatusCounts();
    this.getCrmPredectiveTotals();
    this.getCrmRevenueTotals();
    this.getCrmSalesTeamPerformance();
    this.getCrmReferenceCounts();
    this.getCrmConvertionRatios();
  }
  
 // CRM DASHBOARD ITEMS
  getCrmLeadsAndStatusCounts(){
     let date = this.pipe.transform(this.currentYear, 'yyyy-MM-dd');
     this.spinner.show();
    this.crm.getSprypleData({date_selected:date,user_role:'SA',months:3,cols:null},'get_crm_dashboard_leads_and_status_counts').subscribe((crm_counts_res:any)=>{
      this.spinner.hide();     
      
      if(crm_counts_res && crm_counts_res.status && crm_counts_res.data)
        this.crm_counts = crm_counts_res.data;     
        this.crm_counts?.forEach((c:any)=>{
             c.data = c.count_data? JSON.parse(c.count_data):null;
            if(c.data && c.data.length){
              c.data.forEach((m:any)=>{
                let [month, year] = m.month_selected.split(' ');
                 m.month_name = month;
                 m.year = year;
              });     
            }          
        });       
    });   
  }
  // crm predective
  getCrmPredectiveTotals() {
    let date = this.pipe.transform(this.currentYear, 'yyyy-MM-dd');
  
    this.crm_charts.predective.options ={  
      responsive: true, scales: {
        xAxes: [ { barPercentage: 0.3, categoryPercentage: 0.5,  ticks: {  autoSkip: false   } } ],
        yAxes: [ { display: true,   ticks: { suggestedMin: 10000  } } ]
      }
    };

    this.spinner.show();
    let datasets:any = [];
    let labels:any = [];
    // let translatedLabel = this.translate.instant('Predective Amount');
    this.translate.get('Predective Amount').subscribe((translatedLabel: string) => {
    let object:any = { label: translatedLabel, data: [],backgroundColor:'blue' };
       
    this.crm.getSprypleData({date_selected:date,user_role:'SA',months:3},'get_crm_dashboard_predictive_amounts').subscribe((res: any) => {
      if (res.status && res.data) {  
        res.data.forEach((e: any,index:any) => {
            labels.push(e.month_selected);    
            object.data.push(e.predective_total);
        });
        datasets.push(object);
        this.crm_charts.predective.data = {labels: labels, datasets: datasets  };
      }       
      
     });
    })
  }

  getCrmRevenueTotals() {
    let date = this.pipe.transform(this.currentYear, 'yyyy-MM-dd');
  
    this.crm_charts.revenue.options ={  
      responsive: true, scales: {
        xAxes: [ { barPercentage: 0.3, categoryPercentage: 0.5,  ticks: {  autoSkip: false   } } ],
        yAxes: [ { display: true,   ticks: { suggestedMin: 10000  } } ]
      }
    };

    this.spinner.show();
    let datasets:any = [];
    let labels:any = [];
    this.translate.get('Revenue Amount').subscribe((translatedLabel: string) => {
    let object: any = { label: translatedLabel, data: [], backgroundColor: 'blue' };
    // let object:any = { label: 'Revenue Amount', data: [],backgroundColor:'blue' };
    this.crm.getSprypleData({date_selected:date,user_role:'SA',months:9},'get_crm_dashboard_revenue_totals').subscribe((res: any) => {
      if (res.status && res.data) {  
        res.data.forEach((e: any,index:any) => {
            labels.push(e.month_selected);    
            object.data.push(e.predective_total);
        });
        datasets.push(object);
        this.crm_charts.revenue.data = {labels: labels, datasets: datasets  };
      }       
    })
     });
  }

  getCrmSalesTeamPerformance() {
    let date = this.pipe.transform(this.currentYear, 'yyyy-MM-dd');
  
    this.crm_charts.toppers.options = { responsive: true,    parsing: {  yAxisKey: 'y'  },
          plugins: {  tooltip: {  callbacks: {
                label: function (context: any) { return `${context.dataset.label} — ${context.raw?.emp_name || 'N/A'}: ₹${context.raw?.y ?? 0}`;  }
      } } } 
    };

    this.crm_charts.team.options = {responsive: true, elements: {line: { tension: 0.4,fill: false }}, scales: { yAxes: [{ticks: { beginAtZero: true } }]  }};
    

    let toppers_json:any = [];
    let toppers_labels:any = [];
    let toppers_datasets: any = [];
    
    let team_json:any = []; 
    let team_labels:any = [];
    let team_datasets: any = [];

    this.spinner.show();     
    this.crm.getSprypleData({date_selected:date,user_role:'SA',months:3},'get_crm_dashboard_team_wise_performance').subscribe((res: any) => {
       this.spinner.hide();     
      if (res.status && res.data && res.data[0]) {
        toppers_json = res.data[0].toppers_json ? JSON.parse(res.data[0].toppers_json) : [];
        team_json = res.data[0].team_json ? JSON.parse(res.data[0].team_json) : [];

        // toppers    
        if(toppers_json && toppers_json[0]){  
          toppers_labels = toppers_json[0].monthlist ? JSON.parse(toppers_json[0].monthlist) : [];     

          if (toppers_labels && toppers_labels.length) {
              toppers_json.forEach((team: any, index: number) => {
              let monthlyJson = JSON.parse(team.monthly_json || '[]');
              let monthlyData = toppers_labels.map((label: string) => {
                let mj = monthlyJson.find((x: any) => x.month_name === label);
                return mj && mj.value ?  mj.value :  null;
              });
              let bgcolor = this.deptWisePayrollbgColor[index] || '#888';
              toppers_datasets.push({label: team.team_name, data: monthlyData, backgroundColor: bgcolor  });
            });
            this.crm_charts.toppers.data = { labels:toppers_labels, datasets:toppers_datasets };
          }
        }

        // team      
        if(team_json && team_json[0]){ 
          team_labels = team_json[0].monthlist ? JSON.parse(team_json[0].monthlist) : [];     

          if (team_labels && team_labels.length) {
              team_json.forEach((team: any, index: number) => {
              let monthlyJson = JSON.parse(team.monthly_json || '[]');
              let monthlyData = team_labels.map((label: string) => {
                let mj = monthlyJson.find((x: any) => x.month_name === label);
                return mj && mj.monthly_total ?  mj.monthly_total :  null;
              });
              let bgcolor = this.deptWisePayrollbgColor[index] || '#888';
              team_datasets.push({label: team.team_name, data: monthlyData, backgroundColor: bgcolor, borderColor:bgcolor,pointBorderColor:bgcolor,pointBackgroundColor: bgcolor, tension: 0.4,fill: false  });
            });
            this.crm_charts.team.data = { labels: team_labels, datasets: team_datasets   };
          }
        }
      }
     });
  }

  
  getCrmReferenceCounts() {
    let date = this.pipe.transform(this.currentYear, 'yyyy-MM-dd');
    let reference_list:any = [];
    let backgroundColors:any = [];
    let reference_counts:any = [];
    let reference_percents:any = [];
   
    this.crm_charts.source.options = {responsive: true, maintainAspectRatio: false, 
      usePointStyle: true,  pointStyle: 'circle',
      legend: {  display:  true, position: 'right', labels: { fontSize: 9}},
     };

    this.spinner.show();
    this.crm.getSprypleData({date_selected:date,user_role:'SA',months:3},'get_crm_dashboard_reference_counts').subscribe((res: any) => {
      if (res.status && res.data) {  
        
        res.data.forEach((e: any,index:any) => {
            reference_list.push(e.reference_name);    
            backgroundColors.push(e.bg_color);     
            reference_counts.push(e.total_count);         
            reference_percents.push(e.total_percent);           
            (e.count_json)?e.count_json = JSON.parse(e.count_json):null;
            this.reference_tbl.push(e);
        });
         
        this.crm_charts.source.data = { labels: reference_list, render: 'percentage', datasets: [{backgroundColor: backgroundColors,data: reference_percents }]  }  
      }       
       
     });
  }

  async getCrmConvertionRatios(){
    let date = this.pipe.transform(this.currentYear, 'yyyy-MM-dd');
    let ratio_colors:any = [];
    let ratio_datasets:any = [];
    let ratio_labels:any = [];
    let plugins:any = {
            legend: {display: false }, tooltip: {enabled: false  },  datalabels: { display: true, color: 'white', font: { size: 14 , weight:500 }, // color: '#e5e5e5',
                formatter: (value: any, context: any) => {
                  let data = context.chart.data.datasets[0].data;
                  let total = data.reduce((acc: number, val: number) => acc + val, 0);
                  let percent = total > 0 ? (value / total) * 100 : 0;
                  return `${Math.round(percent)}%`;
                },
            }
          };
   
    this.crm_charts.ratio.options = { responsive: true, rotation: -90, circumference: 180,cutout: '70%',  plugins: plugins };

    this.spinner.show();
    this.crm.getSprypleData({date_selected:date,user_role:'SA',months:3},'get_crm_dashboard_convertion_ratios').subscribe((res: any) => {
      if (res.status && res.data && res.data[0]) {  
        this.crm_charts.ratio.data = res.data;
        
          for(let i=0;i<res.data.length;i++){
              ratio_labels.push(res.data[i].label)
              ratio_colors.push(res.data[i].bg_color); 
          }
         this.crm_charts.ratio.data = res.data;
          this.crm_charts.ratio.data.forEach(async (e: any) => {
            this.crm_charts.ratio.labels.push({label:e.label,bg_color:e.bg_color});
              let value = Number(e.ratio_percent);
              e.gauge_data =  { labels: [e.label,'Others'], datasets: [{ data: [value, 100 - value], backgroundColor: [e.bg_color,'#118ab2'], borderWidth: 0 }] };
          });

          this.crm_charts.ratio.labels.push({label:'Others',bg_color:'#118ab2'});
      }     
     });
  }

  toTitleCase(str: string): string {
    if(str){
        return str.trim().replace(/\w\S*/g, (txt) => {
          return txt.charAt(0).toUpperCase() + txt.substr(1).toLowerCase();
        });
    } else return '';  
  }

}


