import { Component, OnInit, ViewChild } from '@angular/core';
import { UntypedFormGroup, Validators, UntypedFormBuilder } from '@angular/forms';
import { Router } from '@angular/router';
import { MatDialog } from '@angular/material/dialog';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { DatePipe } from '@angular/common';
import { AdminService } from '../../admin.service';
import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';

export interface UserData {
  deptname: string;
  status: string;
  depthead: string;
  headcount: number;
  id: number;
  total: number;
}

@Component({
  selector: 'app-reason-master',
  templateUrl: './reason-master.component.html',
  styleUrls: ['./reason-master.component.scss']
})
export class ReasonMasterComponent implements OnInit {
  constructor(private formBuilder: UntypedFormBuilder, private router: Router, private dialog: MatDialog,
    private LM: CompanySettingService, private adminService: AdminService,private dialogService:ReusableDialogService,) { }

  reasonsForm!: UntypedFormGroup;
  pipe = new DatePipe('en-US');
  isAdd: boolean = false;
  isdata: boolean = true;
  isEdit: boolean = true;
  isSave: boolean = false;
  enable: any = null;
  valid: boolean = false;
  PageLoading = true;
  displayedColumns: string[] = ['sno', 'termination', 'status', 'Action'];
  reasonsDataList: any = [];
  statusList: any;
  dataSource: MatTableDataSource<UserData> = <any>[];
  pageLoading = true;
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  reasonId!: number;
  userSession: any;
  messagesDataList: any = [];
  requiredField: any;
  requiredOption: any;
  dataSave: any;
  dataNotSave: any;
  reason: any;

  EX14: any;
  EX1: any;
  EX2: any;
  EX16: any;
  EX15: any;
  EX17: any;
  EX18: any;
  EX8: any;
  EX24: any;
  btnDisable: boolean = false;
  ngOnInit(): void {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.getstatuslist();
    this.getReasons();
    this.reasonsForm = this.formBuilder.group(
      {
        reason: ["", [Validators.required]],
      },
    );
    this.getMessagesList();
  }

  ngAfterViewInit() {

  }

  Add() {
    this.isAdd = true;
    this.isdata = false;
    this.reasonsForm.controls.reason.setValue('')
  }

  cancel() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Admin/Reason"]));
  }

  edit(w: any, i: any) {
    this.reasonsForm.controls.reason.setValue(i.reason);
    this.enable = i.id;
    this.isEdit = false;
    this.isSave = true;
  }

  validateData(data: any) {
    if (this.reasonsDataList.length == 0) {
      this.valid = true;
    }
    else {
      if (this.reasonsDataList.length > 0) {
        for (let i = 0; i < this.reasonsDataList.length; i++) {
          if (data.replace(/\s{1,}/g, '').trim().toLowerCase() === this.reasonsDataList[i].reason.replace(/\s{1,}/g, '').trim().toLowerCase()) {
            this.valid = false;
            break;
          }
          else {
            this.valid = true;
          }
        }
      }
    }
  }
  validateUpdateData(id: any, data: any) {
    if (this.reasonsDataList.length == 0) {
      this.valid = true;
    }
    else {
      if (this.reasonsDataList.length > 0) {
        for (let i = 0; i < this.reasonsDataList.length; i++) {
          if (id != this.reasonsDataList[i].id && data.replace(/\s{1,}/g, '').trim().toLowerCase() === this.reasonsDataList[i].reason.replace(/\s{1,}/g, '').trim().toLowerCase()) {
            this.valid = false;
            break;
          }
          else {
            this.valid = true;
          }
        }
      }
    }
  }

  saveReason() {
    if (this.reasonsForm.valid) {
      if (this.btnDisable) {
        return;
      }
      this.validateData(this.reasonsForm.controls.reason.value)
      this.reason = this.reasonsForm.controls.reason.value;
      let data = {
        reason: this.reason,
        reason_status: 1,
        actionby: this.userSession.id,
      };
      if (this.valid) {
        this.btnDisable = true;
        this.adminService.saveReasonData(data).subscribe((res: any) => {
          this.valid = false;
          if (res.status && res.data.statuscode == 0) {
            this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
              this.router.navigate(["/Admin/Reason"]));
            this.dialogService.openDialog(this.EX14);
            this.btnDisable = false;
          } else {
            this.dialogService.openDialog(this.EX24);
            this.btnDisable = false;
          }
        });
      }
      else {
        this.dialogService.openDialog(this.EX8);
        this.btnDisable = false;
      }
    }
  }

  updateData(reason: any, value: any) {
    if (this.reasonsForm.valid) {
      // this.validateData(reason)
      this.validateUpdateData(value.id, reason)
      let data = {
        reason_id: value.id,
        reason: reason,
        reason_status: value.status,
        actionby: this.userSession.id,
      };
      if (this.valid) {
        this.adminService.saveReasonData(data).subscribe((res: any) => {
          this.valid = false;
          if (res.status && res.data.statuscode == 0) {
            this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
              this.router.navigate(["/Admin/Reason"]));
            this.dialogService.openDialog(this.EX15);
  
          } else {
            this.dialogService.openDialog(this.EX16);
          }
        });
      }
      else {
        this.dialogService.openDialog(this.EX8);
      }
    }
  }

  

  statusUpdate(status: any, value: any) {
    let data = {
      reason_id: value.id,
      reason: value.reason,
      reason_status: status,
      actionby: this.userSession.id,
    };

    this.adminService.saveReasonData(data).subscribe((res: any) => {
      this.valid = false;
      if (res.status && res.data.statuscode == 0) {
        this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
          this.router.navigate(["/Admin/Reason"]));
        this.dialogService.openDialog(this.EX17);

      } else {
        this.dialogService.openDialog(this.EX18);
      }
    });
  }

  canceledit(event: any, id: any) {
    this.enable = null;
    this.isEdit = true;
    this.isSave = false;
    this.ngOnInit();

  }
  getReasons() {
    this.adminService.getAllReasonsList().subscribe((res: any) => {
      if (res.status && res.data.length != 0) {
        this.reasonsDataList = res.data;
        this.dataSource = new MatTableDataSource(this.reasonsDataList);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;
      }
    })
  }

  getstatuslist() {
    this.LM.getstatuslists().subscribe((result: any) => {
      if (result.status) {
        this.statusList = result.data;
      }

    })
  }

  getMessagesList() {
    let data =
    {
      "code": null,
      "pagenumber": 1,
      "pagesize": 100
    }
    this.adminService.getExitMessagesList(data).subscribe((res: any) => {
      if (res.status) {
        this.messagesDataList = res.data;
        this.messagesDataList.forEach((e: any) => {
          if (e.code == "EX1") {
            this.requiredField = e.message
          } else if (e.code == "EX2") {
            this.requiredOption = e.message
          } else if (e.code == "EX14") {
            this.dataSave = e.message
          } else if (e.code == "EX16") {
            this.dataNotSave = e.message
          } else if (e.code == "EX15") {
            this.EX15 = e.message
          }
          else if (e.code == "EX17") {
            this.EX17 = e.message
          }
          else if (e.code == "EX18") {
            this.EX18 = e.message
          }
          else if (e.code == "EX8") {
            this.EX8 = e.message
          } else if (e.code == "EX24") {
            this.EX24 = e.message
          }

        })
      } else {
        this.messagesDataList = [];
      }

    })
  }

  getPageSizes(): number[] {
    var customPageSizeArray = [];

    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);

    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }
  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }
}

