import { Component,Inject, OnInit } from '@angular/core';
import { MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';
@Component({
  selector: 'app-comfirmation-dialog',
  templateUrl: './comfirmation-dialog.component.html',
  styleUrls: ['./comfirmation-dialog.component.scss']
})
export class ComfirmationDialogComponent implements OnInit {
  isTerminate:boolean = false;
  isRemarksRequired:any = false;
  isRemakrsNotChanged:any = true;
  constructor(public dialogRef: MatDialogRef<ComfirmationDialogComponent>,
    @Inject(MAT_DIALOG_DATA) public data: any) {
      if(data.status == 'terminate'){
        this.isTerminate =true;
      }
     }

    onNoClick(): void {
        this.dialogRef.close();
    }
    close(){
      if(this.isRemarksRequired){
        if(this.data.remarks && this.data.remarks.toString().trim().length){
          this.dialogRef.close({
            remarks: this.isRemarksRequired? this.data.remarks:null,
            result_value:'YES'
          });
        }
      }
    }
  ngOnInit(): void {
    this.isRemarksRequired = this.data?(this.data.isRemarksRequired??false):false;
    if(this.isRemarksRequired){
      this.data.remarks = '';
    }
    
  }

  checkRemarks(){    
    if(this.isRemarksRequired){
      //this.isRemakrsNotChanged = (this.data.remarks.trim() == '')
      if(!this.data.remarks || this.data.remarks.trim() == ''){
          return true;
      }
      else{
        this.isRemakrsNotChanged = false;
      }
    }
    return false;
  }
}
