import { Directive, HostListener } from '@angular/core';
import { NgControl } from '@angular/forms';

@Directive({
  selector: '[alphaNumericColonUnderscoreOnly]'
})
export class AlphabetsNumbersCharsDirective {

  constructor(private ngControl: NgControl) {}

  @HostListener('input', ['$event'])
  onInputChange(event: Event): void {
    const input = event.target as HTMLInputElement;
    // Allows only alphabets, numbers, colon (:), and underscore (_)
    const filteredValue = input.value.replace(/[^a-zA-Z0-9:_]/g, '');
    this.ngControl.control?.setValue(filteredValue);
  }
}
