    this.selection_approved =  new SelectionModel<any>(true, []);
    this.dataSource = new MatTableDataSource(this.List);
    this.dataEmployeeSummary = new MatTableDataSource(this.summaryEmployeeList);
    this.dataSelectedSummary = new MatTableDataSource(this.selectedSummaryList);
    this.dataSelectedSummaryApproved = new MatTableDataSource(this.selectedSummaryApprovedList);
    let fromDate = this.datePipe.transform(this.searchForm.controls.fromDate.value, "yyyy-MM-dd");
    let toDate = this.datePipe.transform(this.searchForm.controls.toDate.value, "yyyy-MM-dd");
    let userId = this.searchForm.controls.Users.value;
     
    if(!this.searchForm.controls.min_visits.valid){
        return;
     }

    if (userId == '0') {
      userId=null;
    }
