getExcelColumnIndex(columnName: string): number {
  const cols = this.getCurrentDisplayedColumns();
  return cols.indexOf(columnName);
}




  removeExcelColumn(ws: XLSX.WorkSheet, colIndex: number) {

 

  if (!ws['!ref']) {

    return; // safety check

  }

 

  const range = XLSX.utils.decode_range(ws['!ref']);

 

  for (let R = range.s.r; R <= range.e.r; ++R) {

    for (let C = colIndex; C < range.e.c; ++C) {

      const nextCell = ws[XLSX.utils.encode_cell({ r: R, c: C + 1 })];

      const currentCell = ws[XLSX.utils.encode_cell({ r: R, c: C })];

 

      if (nextCell) {

        ws[XLSX.utils.encode_cell({ r: R, c: C })] = nextCell;

      } else {

        delete ws[XLSX.utils.encode_cell({ r: R, c: C })];

      }

    }

  }

 

  range.e.c--;

  ws['!ref'] = XLSX.utils.encode_range(range);

}
