hasTableData(): boolean {
  const table = document.getElementById('table');
  if (!table) {
    return false;
  }

  const rows = table.querySelectorAll('tbody tr');

  if (rows.length === 0) {
    return false;
  }

  // Cast Element → HTMLElement
  const firstRow = rows[0] as HTMLElement;

  if (rows.length === 1 && firstRow.innerText.includes('No data')) {
    return false;
  }

  return true;
}











