 /**Search functionality */
 applyFilter(event: Event) {
  const filterValue = (event.target as HTMLInputElement).value;
  this.dataSource.filter = filterValue.trim().toLowerCase();
  if (this.dataSource.paginator) {
    this.dataSource.paginator.firstPage();
  }
}

getkm_travelled(distance:any){
  if(distance)
    return  isNaN(distance) ? 0 : (parseFloat(distance)/1000).toFixed(3) ;
  else return 0;
}

getkm_revised(row:any){
  if(row && row.km_travelled){
    row.km_revised = isNaN(row.km_travelled) ? 0 : (parseFloat(row.km_travelled)/1000).toFixed(1);
  }
  return  row.km_revised ?row.km_revised : 0;
}

recalculate(row:any){
  let dialogRef = this.dialog.open(ComfirmationDialogComponent, {
    position: { top: `70px` },  disableClose: true,
    data: { message: this.translate.instant('CONFIRM_RECOMPUTE'),
        YES: this.translate.instant('YES'),
        NO: this.translate.instant('NO')
      // "Are you sure you want to recompute ?", YES: 'YES', NO: 'No'
     }
  });
  dialogRef.afterClosed().subscribe(result => {
    if (result == 'YES') {
      let data ={
        empid:row.empid,
        date_selected:row.date_selected,
        re_calculate:0,
        route_type:''
      }
      this.spinner.show();
      this.crm.setCrmSelectedEmployeeLocationRoutes(data).subscribe((res: any) => {
        this.spinner.hide();
          if (res.status) {
            this.Searchform();
          }
      });
    }
  });
}

transform(value: string){     
      return value.toLowerCase() // Convert to lowercase to ensure consistent capitalization
        .split('_')    // Split by underscore
        .map(word => word.charAt(0).toUpperCase() + word.slice(1)) // Capitalize first letter of each word
        .join(' '); 
  }

transform_kms(row:any){
    if(Number(row.km_travelled)>0){
      return  row.km_travelled +' (' +(row.route_type == 'LIVE_TRACKING'?'L':'P') +')';
    } else return  row.km_travelled;
  }

