  timeStringToSeconds(timeString: string): number {
    if(timeString && timeString.length > 0){
    const [hours, minutes, seconds] = timeString.split(':').map(Number);
    return hours * 3600 + minutes * 60 + seconds;
    }
    else return 0;
  }
  
  // Function to convert total seconds back to 'hh:mm:ss' format
  secondsToTimeString(totalSeconds: number): string {
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;
    return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
  }

  onInputChange(row:any){
    if(Number(row.km_revised) > Number(row.km_travelled?row.km_travelled:0)){
      let dialogRef = this.dialog.open(ReusableDialogComponent, { position: { top: `70px` },disableClose: true, data:  "Revised kilometers are not greater than traveled kilometers."}); 
      dialogRef.afterClosed().subscribe(result => {
        row.km_revised = row.km_travelled ? Math.round(Number(row.km_travelled)*10)/10 : 0;
        row.amount_revised = Number(row.km_price) * Number(row.km_revised);
        this.getSummaryTotals();
        this.calculateTotalsForSelected();
      });      
    } 
    else {
      row.amount_revised = Number(row.km_price) * Number(row.km_revised);
      this.getSummaryTotals();
      this.calculateTotalsForSelected();
    }  
  }

