  async  setCrmKilometerApprovals(km_json:any,action_status:any) {
    
    let km_json_final:any[] = [];
    let approvable = true;
    let error_msg =null;
    km_json.forEach((row:any)=>{
      if( Number(row.km_revised) == 0){
        approvable = false;        
      }
      km_json_final.push({
        attendanceid:row.attendanceid,
        empid:row.empid,
        date_selected:row.date_selected,
        km_travelled:row.km_travelled,
        km_revised:row.km_revised,
        amount_revised: (action_status != 'Rejected') ? row.amount_revised:0,
        km_action_id:row.km_action_id,
        km_price:row.km_price,
        remarks:row.remarks?row.remarks:'',
        is_live:row.is_live
      });
    });
      if(action_status != 'Rejected'){
        if(!approvable){
          error_msg = "The revised" + (this.userRole == 'Finance'?' amount':' kilometers') + "  for the selected records must be greater than zero";
        }
      }
      if(error_msg){
        let dialogRef = this.dialog.open(ReusableDialogComponent, {position: { top: `70px` }, disableClose: true, data: error_msg  }); 
        dialogRef.afterClosed().subscribe(result => { });
      }else{
        var obj = {
        action_by:this.userSession.id,      
        action_on: this.pipe.transform(new Date(), 'yyyy-MM-dd HH:mm:ss'),
        action_status:action_status,    
        user_role:this.userRole,     
        km_json:km_json_final
        }     
        this.spinner.show();
        this.crm.setCrmKilometerApprovals(obj).subscribe(async (info: any) => {
          this.spinner.hide();
        
          if (info.status && info.data.length != 0) {
            
              let dialogRef = this.dialog.open(ReusableDialogComponent, {
                position: { top: `70px` },
                disableClose: true,
                data: action_status + " successfully"            
              }); 
              dialogRef.afterClosed().subscribe(result => { 
              this.Searchform();            
              });
            }
        })
      } 
  }

  isSomeSelected() {
    return this.selection.selected.length > 0;
  }
  isAllSelected() {
    let numSelected = this.selection.selected.length;
    let numRows = this.dataSource_pending.data.length;
    return numSelected === numRows;
  }

  isSomeSelectedApproved() {
    return this.selection_approved.selected.length > 0;
  }

  isAllSelectedApproved() {
    let numSelected = this.selection_approved.selected.length;
    let numRows = this.dataSource_approved.data.length;
    return numSelected === numRows;
  }

