    masterToggle() {
      let records_count = this.dataSource_pending.data && this.dataSource_pending.data.length ? this.dataSource_pending.data.length:0;
      // if there is a selection then clear that selection
      if (this.isSomeSelected()) {
        this.selection.clear();
      } else {        
         this.dataSource_pending.data.forEach(async (row) => {
            row.disabled == 0 ? this.selection.select(row):null;
          });         
      }  
      this.calculateTotalsForSelected();
    }  

    approvedMasterToggle(){
      let records_count = this.dataSource_approved.data && this.dataSource_approved.data.length ? this.dataSource_approved.data.length:0;
      // if there is a selection then clear that selection
      if (this.isSomeSelectedApproved()) {
        this.selection_approved.clear();
      } else {        
         this.dataSource_approved.data.forEach(async (row) => {
            row.disabled == 0 ? this.selection_approved.select(row):null;
          });         
      }  
      this.calculateTotalsForSelectedApproved();
    }

