
import { SelectionModel } from '@angular/cdk/collections';
import { Component, OnInit, ViewChild } from '@angular/core';
import { FormArray, FormBuilder, FormControl, FormGroup, UntypedFormGroup, Validators } from '@angular/forms';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { PayrollService } from '../../payroll.service';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { MatDialog } from '@angular/material/dialog';
import { Router } from '@angular/router';

export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
interface Employee {
  empid: number;
  empCode: string;
  empName: string;
}
@Component({
  selector: 'app-variable-pay-distribution',
  templateUrl: './variable-pay-distribution.component.html',
  styleUrls: ['./variable-pay-distribution.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class VariablePayDistributionComponent implements OnInit {
  UserSession:any;
  companyName: any;
  constructor(
    private fb: FormBuilder,
    private companyService: CompanySettingService,
    private payroll:PayrollService,
    private dialog:MatDialog,
    private router: Router,
  ) { 
    this.companyName = sessionStorage.getItem("companyName");
    this.UserSession = JSON.parse(sessionStorage.getItem('user') ?? '');
  }
  employeeForm: any = UntypedFormGroup;
  vpHistoryForm!: FormGroup;
  @ViewChild('firstPaginator') paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  @ViewChild('secondPaginator') paginatorcompleted!: MatPaginator;
  @ViewChild(MatSort)
  sortcompleted!: MatSort;
  pageLoading = true;
  pageLoading1 = true;

  displayedColumns: string[] = ['select', 'sno', 'empCode', 'empName', 'amount'];
  dataSource:MatTableDataSource<Employee> = <any>[];

  displayedColumns2: string[] = ['sno','year','type' ,'empCode', 'empName', 'amount'];
  dataSource2: MatTableDataSource<any> = <any>[];

  worklocationDetails:any=[];
  calculationPeriodDetails:any=[];
  distributionPeriodDetails:any=[];
  filteredLocations:any=[];
  filteredHistoryLocations:any=[];
  searchControlforLoc = new FormControl('');
  historySearchControl = new FormControl('');


  selectedEmployees: Set<number> = new Set();
  employeeList:any =[];
  employeeHistory:any =[];
  btnDisable:boolean = false;
  branchSelected:boolean = true;

  employeeArray:any;
  selection = new SelectionModel<any>(true, []);
  tdsAmount: FormControl[] = [];
  selectedEmployeesList: any[] = [];
  ngOnInit(): void {
    this.employeeForm = this.fb.group({

      companylocation: ["",[Validators.required]],
      calculationPeriod: ["",[Validators.required]],
      distributionPeriod: ["",[Validators.required]],
      employees: this.fb.array([]) 
    });
    this.getWorkLocation();

    this.vpHistoryForm = this.fb.group({
      location : ['',Validators.required],

    }); 
    this.employeeForm.get('companylocation')?.valueChanges.subscribe((selectedValue:any)=>{
      this.employeeList=[];
      this.dataSource =  new MatTableDataSource(this.employeeList);
      this.dataSource.paginator = this.paginator;
      this.dataSource.sort = this.sort;
      this.pageLoading = false;
      this.employeeForm.controls.calculationPeriod.setValue('');

    })
  }

  getWorkLocation() {
    this.companyService.getactiveWorkLocation({ id: null, companyName: this.companyName }).subscribe((result) => {
      this.worklocationDetails = result.data;
      this.filteredLocations = this.worklocationDetails;
      this.filteredHistoryLocations = this.worklocationDetails;
      this.getCalculationPeriod();
    })
  }

  getCalculationPeriod() {
    this.payroll.getVariablepayCalculationPeriod().subscribe((res) => {
      if(res.status){
        this.calculationPeriodDetails = res.data;
      }
    })
  }
  onchangeCalculation(id:any){
    this.getDistributionPeriod(id);
    this.getEmployeeList(id);
  }

  getDistributionPeriod(sid:any) {
    let scheduleId = sid;
    this.distributionPeriodDetails = [];
    this.payroll.getVariablepayDistributionPeriod(scheduleId).subscribe((res) => {
      if(res.status){
        this.distributionPeriodDetails = res.data;
      }
    })
  }

  
  getEmployeeList(sid: any) {
    let scheduleId = sid;
    let locationId = this.employeeForm.controls.companylocation.value;
    this.branchSelected = false;
    
    this.payroll.getLocationWiseEmployeesForVariablePaySetting(scheduleId, locationId).subscribe((res: any) => {
      this.pageLoading = false;
  
      if (res.status) {
        this.employeeList = res.data;
        this.dataSource = new MatTableDataSource(this.employeeList);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.initEmployeeFormArray();
      } else {
        this.employeeList = [];
        this.dataSource = new MatTableDataSource(this.employeeList);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
      }
    });
  }
  
  // ------------------------------

  initEmployeeFormArray() {
    this.employeeArray = this.employeeForm.get('employees') as FormArray;
    this.employeeArray.clear();
    
    if (this.dataSource?.data) {
      this.dataSource.data.forEach((employee: any) => {
        this.employeeArray.push(this.fb.group({
          empid: employee.empid,
          empname: employee.empname,
          tdsAmount: ['']
        }));
      });
    }
  }
 
isRowSelected(row: any): boolean {
  return this.selectedEmployeesList.some(selected => selected.empid === row.empid);
}


toggleRowSelection(row: any): void {
  const index = this.selectedEmployeesList.findIndex(selected => selected.empid === row.empid);
  if (index === -1) {
    this.selectedEmployeesList.push(row);
  } else {
    this.selectedEmployeesList.splice(index, 1);
  }
  this.selection.toggle(row);
}

getTdsAmountControl(empid: any): FormControl | any {
  const employeesFormArray = this.employeeForm.get('employees') as FormArray;
  const formGroup = employeesFormArray.controls.find(control => 
    control.get('empid')?.value === empid
  );
  return formGroup ? (formGroup.get('tdsAmount') as FormControl) : null;
}


isFormValid(): boolean {
  const employeesFormArray = this.employeeForm.get('employees') as FormArray;
  if (this.selectedEmployeesList.length === 0) return false;
  for (let selected of this.selectedEmployeesList) {
    const formGroup = employeesFormArray.controls.find(control => 
      control.get('empid')?.value === selected.empid
    );
    if (formGroup) {
      const tdsAmountControl = formGroup.get('tdsAmount');
      if (!tdsAmountControl || 
          tdsAmountControl.invalid || 
          tdsAmountControl.value === null ||
          tdsAmountControl.value === '' || 
          isNaN(Number(tdsAmountControl.value))) {
        return false;
      }
    } else {
      return false;
    }
  }
  return true;
}


  masterToggle() {
    // if there is a selection then clear that selection
    if (this.isSomeSelected()) {
      this.selection.clear();
      this.selectedEmployeesList =[]
    } else {
      this.isAllSelected()
        ? this.selection.clear()
        : this.dataSource.data.forEach((row:any) => this.selection.select(row));
        this.selectedEmployeesList = this.dataSource.data.slice();
    }
  }

  isSomeSelected() {
    return this.selection.selected.length > 0;
  }

  isAllSelected() {
    const numSelected = this.selection.selected.length;
    const numRows = this.dataSource.data.length;
    return numSelected === numRows;
  }
onSubmit(){

  if(this.employeeForm.valid){
  
  if(this.selectedEmployeesList.length > 0){
    if(this.btnDisable){
      return;
    }

    if (this.isFormValid()) {
      const employeesFormArray = this.employeeForm.get('employees') as FormArray;
    const submittedData = this.selectedEmployeesList.map(selected => {
      const formGroup = employeesFormArray.controls.find(control => 
        control.get('empid')?.value === selected.empid
      );
      return {
        empid: selected.empid,
        amount: Number(formGroup?.get('tdsAmount')?.value)
      };
    });
  
      let obj = {
        calc_period: this.employeeForm.controls.calculationPeriod.value,
        dist_period: this.employeeForm.controls.distributionPeriod.value,
        emp_amounts_array: JSON.stringify(submittedData),
        user_id_value: this.UserSession.id,
      };
      this.btnDisable=true;
      this.payroll.setEmployeeVariablePay(obj).subscribe((res:any)=>{
       if(res.status){
         this.dialog.open(ReusableDialogComponent, {
           position: { top: `70px` },
           disableClose: true,
           data: 'Variable pay amount submitted successfully.',
         });
         this.btnDisable=false;
         this.cancel();
       } else {
         this.dialog.open(ReusableDialogComponent, {
           position: { top: `70px` },
           disableClose: true,
           data: 'Unable to save data.',
         });
         this.btnDisable=false;
       }
      })
    } 
    else{
      this.dialog.open(ReusableDialogComponent, {
        position: { top: `70px` },
        disableClose: true,
        data: 'Please enter variable pay amount.',
      });
      return;
    }
    
  }else{
    this.dialog.open(ReusableDialogComponent, {
      position: { top: `70px` },
      disableClose: true,
      data: 'Select atleast one employee.',
    });
  }
}

}

// ------------------------------

getEmployeeHistory(id:any){
  this.employeeHistory = [];
  let data = {
    location_id: id,
    employeeId:null,
    status:"Calculated"
  }

  this.payroll.getVariablePayHistory(data).subscribe((res:any)=>{
    if(res.status){
    this.employeeHistory = res.data;
    this.dataSource2 =  new MatTableDataSource( this.employeeHistory);
    this.dataSource2.paginator = this.paginatorcompleted;
    this.dataSource2.sort = this.sort;
    this.pageLoading1 = false;
    }  else{
      this.employeeHistory =[];
    this.dataSource2 =  new MatTableDataSource( this.employeeHistory);
    this.dataSource2.paginator = this.paginatorcompleted;
    this.dataSource2.sort = this.sort;
    this.pageLoading1 = false;
    }
  })

}

cancel(){
  this.router.navigateByUrl('/', { skipLocationChange: true })
  .then(() => this.router.navigate(['/Payroll/variablePayDistribute']));
}

getPageSizes(): number[] {
  var customPageSizeArray = [];
  if (this.dataSource.data.length < 5) {
    customPageSizeArray.push(5);
  }
  if (this.dataSource.data.length > 5) {
    customPageSizeArray.push(5);
  }
  if (this.dataSource.data.length > 10) {
    customPageSizeArray.push(10);
  }
  if (this.dataSource.data.length > 20) {
    customPageSizeArray.push(20);
  }
  customPageSizeArray.push(this.dataSource.data.length);
  return customPageSizeArray;
}

getPageSizes1(){
  var customPageSizeArray = [];

  if (this.dataSource2.filteredData.length < 5) {
    customPageSizeArray.push(5);
  }
  if (this.dataSource2.filteredData.length > 5) {
    customPageSizeArray.push(5);
  }
  if (this.dataSource2.filteredData.length > 10) {
    customPageSizeArray.push(10);
  }
  if (this.dataSource2.filteredData.length > 20) {
    customPageSizeArray.push(20);
  }
  customPageSizeArray.push(this.dataSource2.filteredData.length);
  return customPageSizeArray;
  
}

applyFilter(event: Event) {
  const filterValue = (event.target as HTMLInputElement).value;
  this.dataSource.filter = filterValue.trim().toLowerCase();
  if (this.dataSource.paginator) {
    this.dataSource.paginator.firstPage();
    this.employeeArray = this.employeeForm.get('employees') as FormArray; 
    this.employeeArray.clear(); 
    if (this.dataSource?.filteredData) {
      this.dataSource.filteredData.forEach((employee :any)=> {
      this.employeeArray.push(this.fb.group({
        empid: employee.empid,
        empname: employee.empname,
        tdsAmount:  ['']
      }));
    });

  }
  }
  this.dataSource2.filter = filterValue.trim().toLowerCase();
  if (this.dataSource2.paginator) {
    this.dataSource2.paginator.firstPage();
  }
}

}