import { Component, OnInit, ViewChild } from '@angular/core';
import { UntypedFormGroup, Validators, UntypedFormBuilder } from '@angular/forms';
import { Router } from '@angular/router';
import { MatDialog } from '@angular/material/dialog';
import { LoginService } from 'src/app/services/login.service';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { DatePipe } from '@angular/common';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { EmsService } from 'src/app/modules/ems/ems.service';
import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';
import { TranslateService } from '@ngx-translate/core';
export interface UserData {
  deptname: string;
  status: string;
  depthead: string;
  headcount: number;
  id: number;
  total: number;
}

@Component({
  selector: 'app-departmentsection',
  templateUrl: './departmentsection.component.html',
  styleUrls: ['./departmentsection.component.scss']
})
export class DepartmentsectionComponent implements OnInit {
  departmentForm!: UntypedFormGroup;
  department: any;
  userSession: any;
  pipe = new DatePipe('en-US');
  issubmitted: boolean = false;
  isvalid: boolean = false;
  isView: boolean = false;
  isAdd: boolean = false;
  isdata: boolean = true;
  isEdit: boolean = true;
  isSave: boolean = false;
  enable: number | null = null;
  valid: boolean = false;
  msgEM1: any;
  msgEM84: any;
  msgEM85: any;
  msgEM88: any;
  msgEM89: any;
  msgEM90: any
  msgEM91: any;
  msgEM92: any;
  msgEM151: any;
  msgEM152: any;
  todayDate: any = new Date();
  displayedColumns: string[] = ['sno', 'deptname','section','empcount', 'status', 'Action'];
  departmentData: any = [];
  departmentDropDown: any = [];
  arrayValue: any = [{"id":1,"name":"Active"},{"id":0,"name":"Inactive"}]
  dataSource: MatTableDataSource<UserData>;
  pageLoading = true;
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort) sort!: MatSort;
  companyDBName: any;
  btnDisable: boolean = false;
  
  messagesDataList: any = [];
    languages = [
    { code: 'english', label: 'ENGLISH', name: 'English' },
    { code: 'arabic', label: 'ARABIC', name: 'Arabic' }
  ];
  constructor(private formBuilder: UntypedFormBuilder, private router: Router,
    private dialog: MatDialog, private LM: CompanySettingService, private dialogService:ReusableDialogService,
    private emsService: EmsService, private translate: TranslateService) {
    // this.getstatuslist();
    this.getdepartmentSections();
    this.dataSource = new MatTableDataSource(this.departmentData);
  }

  ngOnInit(): void {
  const savedLang = localStorage.getItem('lang');
   this.translate.use(savedLang || 'english');
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
        console.log("this",sessionStorage.getItem('section'))
    this.companyDBName = sessionStorage.getItem('companyName');
    console.log("enable",this.enable)
   this.getDepartments();
    this.getMessages();
    this.departmentForm = this.formBuilder.group(
      {
        department: ["", [Validators.required]],
        section: ["",[Validators.required] ],

      },
    );
  }
validatedepartments(sectionName: any, deptId: number, editSectionId?: number) {
  if (!sectionName || typeof sectionName !== 'string') {
    this.valid = false;
    return;
  }

  const value = sectionName.replace(/\s+/g, '').trim().toLowerCase();

  this.valid = !this.departmentData.some((row: any) => {
    // skip empty section names
    if (!row.section_name) return false;

    // skip same record while editing
    if (editSectionId && row.section_id === editSectionId) return false;

    return (
      row.dept_id === deptId &&
      row.section_name.replace(/\s+/g, '').trim().toLowerCase() === value
    );
  });
}

  validateupdatedepartments(id: any, data: any) {
    console.log("test",id,data)
    if (this.departmentData.length == 0) {
      this.valid = true;
    }
    else {
      if (this.departmentData.length > 0) {
        for (let i = 0; i < this.departmentData.length; i++) {
          if (id != this.departmentData[i].section_id && data.replace(/\s{1,}/g, '').trim().toLowerCase() === this.departmentData[i].section_name.replace(/\s{1,}/g, '').trim().toLowerCase()) {
            this.valid = false;
            break;
          }
          else {
            this.valid = true;
          }
        }
      }
    }
  }
  setdepartmentSection() {
    if (this.btnDisable) {
      return;
    }
    this.validatedepartments(this.departmentForm.controls.section.value,this.departmentForm.controls.department.value,0)
    this.department = this.departmentForm.controls.department.value;
    var data = {
      id_value:null,
      section_name:this.departmentForm.controls.section.value,
      status:1,
      dept_id:this.department,
      created_by: this.userSession.id,
      created_on: this.pipe.transform(new Date(), 'yyyy-MM-dd') + ' ' + this.pipe.transform(new Date(), 'HH:mm:ss'),
      companyDBName: this.companyDBName
    }
    if (this.departmentForm.valid) {
      if (this.valid) {
        this.btnDisable = true;
        this.LM.setDepartmentsSection(data).subscribe((data) => {
          this.valid = false;
          if (data.status) {
            this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
              this.router.navigate(["/Admin/Section"]));
            this.dialogService.openDialog(data.message);

          } else {
            this.dialogService.openDialog(data.message);
            this.btnDisable = false;
          }
        })
      }
      else {
        this.dialogService.openDialog('Section already existed.');
      }

    }

  }

  Add() {
    this.isAdd = true;
    this.isdata = false;
    this.departmentForm.controls.section.setValue('');
    this.departmentForm.controls.department.setValue('')
  }
  cancel() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Admin/Section"]));
  }
  status(status: any, id: any, section: any) {
    const isNotAssigned =  status == 1 ? true: this.departmentData.find((row: any) => row.section_id === id)?.section_count === 'Not Assigned';
    if(isNotAssigned){
        var data = {
        id_value:section.section_id,
        section_name:section.section_name,
        status:status,
        dept_id:section.dept_id,
        created_by: this.userSession.id,
        created_on: this.pipe.transform(new Date(), 'yyyy-MM-dd') + ' ' + this.pipe.transform(new Date(), 'HH:mm:ss'),
        companyDBName: this.companyDBName
      }
        this.LM.setDepartmentsSection(data).subscribe((data) => {
            this.valid = false;
            if (data.status) {
              this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
                this.router.navigate(["/Admin/Section"]));
              this.dialogService.openDialog(data.message);

            } else {
              this.dialogService.openDialog(data.message);
              this.btnDisable = false;
            }
          })

    }
    else{
      this.dialogService.openDialog('Employees are assigned to the selected section. It cannot be inactivated.');
      this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Admin/Section"]));
    }


  }

  edit(w: any, i: any) {
    this.departmentForm.controls.section.setValue(i.section_name);
    this.enable = i.section_id;
    this.isEdit = false;
    this.isSave = true;

  }
  save(event: any, id: any, section: any, datas: any) {
  
    if (this.departmentForm.get('section')?.valid) {
      // this.validateupdatedepartments(id, section)
      this.validatedepartments(this.departmentForm.controls.section.value,datas.dept_name,id)
      this.enable = null;
      this.isEdit = true;
      this.isSave = false;
      if (this.valid) {
      var data = {
      id_value:id,
      section_name:this.departmentForm.controls.section.value,
      status:1,
      dept_id:datas.dept_id,
      created_by: this.userSession.id,
      created_on: this.pipe.transform(new Date(), 'yyyy-MM-dd') + ' ' + this.pipe.transform(new Date(), 'HH:mm:ss'),
      companyDBName: this.companyDBName
    }
        this.LM.setDepartmentsSection(data).subscribe((data) => {
          this.valid = false;
          if (data.status) {
            this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
              this.router.navigate(["/Admin/Section"]));
            this.dialogService.openDialog(data.message);

          } else {
            this.dialogService.openDialog(data.message);
            this.btnDisable = false;
          }
        })


      }
      else {
        this.ngOnInit();
        this.dialogService.openDialog(this.msgEM92);
      }
    }
  }
  canceledit(event: any, id: any) {
    this.enable = null;
    this.isEdit = true;
    this.isSave = false;
    this.ngOnInit();

  }
  getDepartments() {
    this.LM.getDepartments('departmentsmaster', null, 1, 1000, this.companyDBName).subscribe((info: any) => {
      if (info.status && info.data.length != 0) {
        this.departmentDropDown = info.data.filter((item:any) => item.status == 1);
      }

    })

  }

  getdepartmentSections(){
       this.LM.getDepartmentSections().subscribe((info: any) => {
      if (info.status && info.data.length != 0) {
        this.departmentData = info.data.filter((item: any) => item.status_value !== null);
        this.dataSource = new MatTableDataSource(this.departmentData);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;
      }

    })
  }
  getPageSizes(): number[] {
    var customPageSizeArray = [];

    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);

    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }
  getstatuslist() {
    this.LM.getstatuslists().subscribe((result: any) => {
      if (result.status) {
        this.arrayValue = result.data;
      }
    })
  }
  getMessages() {
    let data =
    {
      "code": null,
      "pagenumber": 1,
      "pagesize": 1000
    }
    this.emsService.getMessagesListApi(data).subscribe((result: any) => {
      if (result.status) {
        this.messagesDataList = result.data;
        this.messagesDataList.forEach((e: any) => {

          if (e.code == "EM1") {
            this.msgEM1 = e.message
          }
          else if (e.code == "EM84") {
            this.msgEM84 = e.message;
          }
          else if (e.code == "EM85") {
            this.msgEM85 = e.message
          }
          else if (e.code == "EM88") {
            this.msgEM88 = e.message
          }
          else if (e.code == "EM89") {
            this.msgEM89 = e.message
          }
          else if (e.code == "EM90") {
            this.msgEM90 = e.message
          }
          else if (e.code == "EM91") {
            this.msgEM91 = e.message
          }

          else if (e.code == "EM92") {
            this.msgEM92 = e.message
          }

          else if (e.code == "EM151") {
            this.msgEM151 = e.message
          }

          else if (e.code == "EM152") {
            this.msgEM152 = e.message
          }

        })
      } else {
        this.messagesDataList = [];
      }
    })
  }

  /**Search functionality */
  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }

  }

}

