    fetchMapLocationDetails(data:any):Observable<any>{ 
      let address = null;
      let userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
        try{
          address =  this.http.get(`https://geocode.maps.co/reverse?lat=${data.lat}&lon=${data.lng}&api_key=${userSession.geocode_apikey}`);
          }
        catch{
          //error logs
          address = this.http.get(`https://maps.googleapis.com/maps/api/geocode/json?latlng=${data.lat},${data.lng}&key=${userSession.google_map_apikey}`);
        }            
      return address;
    }

