import { Component, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, FormControl, UntypedFormGroup, Validators } from '@angular/forms';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { PayrollService } from '../../payroll.service';
import { MatDialog } from '@angular/material/dialog';
import { TdsService } from '../../tds.service';
import { Router } from '@angular/router';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';

@Component({
  selector: 'app-add-annual-house-rent-behalf-for-tds',
  templateUrl: './add-annual-house-rent-behalf-for-tds.component.html',
  styleUrls: ['./add-annual-house-rent-behalf-for-tds.component.scss']
})
export class AddAnnualHouseRentBehalfForTDSComponent implements OnInit {

  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  pageLoading = true;
  searchForm :any = UntypedFormGroup;
  displayOwnerDetails:boolean=false;
  userSession:any;
  financialYear:any;
  dataSource: MatTableDataSource<any> = <any>[];
  displayedColumns:string[] = ['sno','empcode','empname','deptName','designation','amount','ownerName','ownerPanNumber'];
  houserentLimit:any;
  isSubmit:boolean=false;
  isAddRentAmount:boolean = false;
  finYearStartDate:any;
  finYearEndDate:any;
  filteredEmployeeList:any = [];
  searchControl = new FormControl('');
  empList: any;
  id:any;
  btnDisable :boolean = false;
  ownerPanList:any=[];
  noDataFound:boolean = false;

  constructor(
      private fb : FormBuilder,
      private payrollService: PayrollService,
      private dialog:MatDialog,
      private tdsService:TdsService,
      private router:Router,
  ) { 
     this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
        this.searchForm =this.fb.group({
          empname:['',Validators.required],
          rentAmount : ['',Validators.required],
          ownerName:[''],
          pancardNumber:[''],
        })
        this.getAnnualRentLimitForNoSubmission();
  }

  async ngOnInit() {
    this.financialYear  = await this.getFinancialYears();
    this.getEmployeeAnnualRentsForManager();

    this.searchForm.get('rentAmount').valueChanges.subscribe((val:any) => {
      if (val > this.houserentLimit) {
        this.searchForm.controls['ownerName'].setValidators([Validators.required]);
        this.searchForm.controls['pancardNumber'].setValidators([Validators.required]);
      } else {
        this.searchForm.controls['ownerName'].clearValidators();
        this.searchForm.controls['pancardNumber'].clearValidators();
      }
      this.searchForm.controls['ownerName'].updateValueAndValidity();
      this.searchForm.controls['pancardNumber'].updateValueAndValidity();
    });
    this.getEmployeeListForExemptionSubmission();
    this.fnGetCurrentFinYearDates();

    this.searchControl.valueChanges.subscribe(searchText => {
      this.filterEmpList(searchText);
    });

  }

  submit(){
    if(this.searchForm.controls.rentAmount.value > 0){
     
      if(this.searchForm.controls.rentAmount.value > this.houserentLimit && !this.displayOwnerDetails){
        let dialogRef = this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true, 
          data: "If annual house rent exceeds "+this.houserentLimit+" owner's details are needed to be submitted."
        });
        this.displayOwnerDetails = true;
        this.isSubmit = false;
        this.btnDisable = false;
      }else if(this.searchForm.controls.rentAmount.value <= this.houserentLimit){
          if(this.searchForm.valid){
            this.displayOwnerDetails = false;
            this.isSubmit = true;
            this.btnDisable = true;
          }
        
      }else if(this.searchForm.controls.rentAmount.value > this.houserentLimit && this.displayOwnerDetails){
        if(this.searchForm.valid){
          this.isSubmit = true;
          this.btnDisable = true;
        }
      }
      if(this.isSubmit){
        this.ownerPanList.forEach((element:any) => {
          if(element.owner_pan_number === this.searchForm.controls.pancardNumber.value.toUpperCase()){
            let dialogRef = this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true, 
              data: "There is already a record with these details. A new record with the same details cannot be added."
            });
            this.btnDisable = false;
            return;
          }
        });
        let payLoad = {
          id_value: this.id ? this.id : null,
          employee_id_value : this.searchForm.controls.empname.value,
          financial_year_value :this.financialYear,
          rent_value :this.searchForm.controls.rentAmount.value,
          owner_name : this.searchForm.controls.ownerName.value ? this.searchForm.controls.ownerName.value : null,
          owner_pan : this.searchForm.controls.pancardNumber.value ? this.searchForm.controls.pancardNumber.value.toUpperCase() : null,
          submission_status_value: 'Approved',
          created_by_value: this.userSession.id,
          updated_by_value: this.id ? this.userSession.id : null,
        }
     this.setEmployeeAnnualRent(payLoad)
      }
    }else if(this.searchForm.controls.rentAmount.value == 0){
      this.searchForm.controls.rentAmount.setValue('')

    }
 
  }
  setEmployeeAnnualRent(payLoad:any){
    this.tdsService.setEmployeeAnnualRent(payLoad).subscribe((result :any)=>{
      if(result.status){
        this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: result.data.message
        });
        this.navigationToCurrentPage();
      }else { 
        this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: 'Unable to submit data.'
        });
        this.btnDisable= false;
      }
    
    })
  }

  
  cancel(){
    this.searchForm.reset('');
    this.isAddRentAmount = false;
    this.navigationToCurrentPage();
  }

  getEmployeeAnnualRentsForManager(){
    let payLoad ={
      financial_year_value:this.financialYear,
      employee_id_value : this.userSession.id,
      }
    this.tdsService.getEmployeeAnnualRentsForManager(payLoad).subscribe((result:any)=>{
      if(result.data){
        this.dataSource = new MatTableDataSource(result.data);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;
      }
    })
  }

  getFinancialYears() {
    return new Promise((resolve) => {
      this.payrollService.getFinancialYears().subscribe((result: any) => {
        if (result.status && result.data.length) {
          resolve(result.data[0].financial_year)
        } else {
          resolve('')
        }
      });
    });
  }

  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.dataSource.data.length < 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  getAnnualRentLimitForNoSubmission(){
    this.tdsService.getAnnualRentLimitForNoSubmission().subscribe((result:any)=>{
      this.houserentLimit = Number(result.data[0].vlimit);
    })
  }

  navigationToCurrentPage(){
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Payroll/annualRentByManager"]));
  }

  addRent(){
    this.isAddRentAmount = true;
  }

  fnGetCurrentFinYearDates(){
    this.tdsService.fnGetCurrentFinYearDates().subscribe((result:any)=>{
      if(result.status){
        this.finYearEndDate=result.data[0].end_date;
        this.finYearStartDate = result.data[0].start_date;
      }
        
    })
  }
  
  filterEmpList(searchText: any){
    this.filteredEmployeeList = this.empList.filter((val: any) =>
      val.employee_name.toLowerCase().includes(searchText.toLowerCase()) || val.employee_code.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredEmployeeList.length <= 0) {
        this.noDataFound = true
    } else {
      this.noDataFound = false
    }
  }

  getEmployeeListForExemptionSubmission(){
    let payLoad = {
      financial_year : this.financialYear
    }
    this.tdsService.getEmployeeListForExemptionSubmission(payLoad).subscribe((result:any)=>{
      this.empList = result.data;
      this.filteredEmployeeList = this.empList;
    })
  }

  edit(event:any){
    this.isAddRentAmount = true;
    this.searchForm.controls.empname.setValue(event.employee_id);
    this.searchForm.controls.rentAmount.setValue(event.rent_paid);
    this.searchForm.controls.ownerName.setValue(event.name_of_the_owner);
    this.searchForm.controls.pancardNumber.setValue(event.owner_pan_number);
    this.id = event.id;
    if(event.owner_pan_number !== null){
      this.displayOwnerDetails = true;
    }
  }

  removeRow(row:any){
    let payload = {
      id_value: row.id,
      employee_id_value : this.userSession.id,
      financial_year_value :this.financialYear,
      rent_value :row.rent_paid,
      owner_name : row.name_of_the_owner,
      owner_pan : row.owner_pan_number,
      submission_status_value: 'Deleted',
      created_by_value: this.userSession.id,
      updated_by_value: this.userSession.id,
    }
    this.setEmployeeAnnualRent(payload)
  }

  validateEmpRentSubmissions(count:any){
    if(count > 11){
      let dialogRef = this.dialog.open(ReusableDialogComponent, {
        position: { top: `70px` },
        disableClose: true, 
        data: "The selected employee has already reached the maximum rent records submission limit"
      });

      this.searchForm.controls.empname.setValue('');
      this.getOwnersList();
    }
  }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
  
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

  getOwnersList(){
    this.tdsService.getOwnersList(this.financialYear,this.searchForm.controls.empname.value).subscribe((result:any)=>{
      if(result.status){
        this.ownerPanList = result.data
      }
    })
  }

}
