
import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import * as XLSX from 'xlsx';
import { Router } from '@angular/router';
import {
  FormControl,
  UntypedFormBuilder,
  UntypedFormControl,
  UntypedFormGroup,
  Validators,
} from '@angular/forms';
import {
  DateAdapter,
  MAT_DATE_FORMATS,
  MAT_DATE_LOCALE,
} from '@angular/material/core';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { PayrollService } from '../../payroll.service';
import { DomSanitizer, SafeResourceUrl } from '@angular/platform-browser';
import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';
import { TranslateService } from '@ngx-translate/core';
import { MatDatepicker } from '@angular/material/datepicker';
import { DatePipe } from '@angular/common';
import { Moment } from 'moment';
import * as _moment from 'moment';
type AOA = any[][];
const moment = _moment;
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
@Component({
  selector: 'app-payroll-bulkupload',
  templateUrl: './payroll-bulkupload.component.html',
  styleUrls: ['./payroll-bulkupload.component.scss'],
  providers: [
      {
        provide: DateAdapter,
        useClass: MomentDateAdapter,
        deps: [MAT_DATE_LOCALE],
      },
  
      { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class PayrollBulkuploadComponent implements OnInit {
  uploadForm!: UntypedFormGroup;
  date = new UntypedFormControl(moment());
  minDate: any = new Date('2025-12-01');
  max = new Date();
  data: AOA = [[], []];
  viewdata: AOA = [[], []];
  isview: boolean = false;
  isadd: boolean = true;
  wopts: XLSX.WritingOptions = { bookType: 'xlsx', type: 'array' };
  fileName: string = 'SheetJS.xlsx';
  @ViewChild('inputFile') inputFile!: ElementRef;
  convertedJson!: string;
  viewconvertedJson!: string;
  messagesDataList: any = [];
  reqField: any;
  reqOption: any;
  reqSave: any;
  reqNotSave: any;
  isLoading = false;
  companyName: any;
  userSession: any;
  fileURL: any;
    setMonthAndYear(
      normalizedMonthAndYear: Moment,
      datepicker: MatDatepicker<Moment>
    ) {
      const ctrlValue = this.date.value!;
      ctrlValue.month(normalizedMonthAndYear.month());
      ctrlValue.year(normalizedMonthAndYear.year());
      this.date.setValue(ctrlValue);
      datepicker.close();
    }
  constructor(private PRService: PayrollService, public dialog: MatDialog, private router: Router, public formBuilder: UntypedFormBuilder,
     private dialogService:ReusableDialogService, private sanitizer: DomSanitizer,private translate: TranslateService,private datePipe: DatePipe ) {
    this.companyName = sessionStorage.getItem("companyName") ? sessionStorage.getItem("companyName") : null;
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    // this.agreement();
  }
     languages = [
    { code: 'english', label: 'ENGLISH', name: 'English' },
    { code: 'arabic', label: 'ARABIC', name: 'Arabic' }
  ];
  ngOnInit(): void {
     const savedLang = localStorage.getItem('lang');
   this.translate.use(savedLang || 'english');
     this.uploadForm = this.formBuilder.group({
      date: [new Date(),Validators.required],

    });
     this.uploadForm
      .get('date')
      ?.valueChanges.subscribe((selectedValue: any) => {
        // this.getESIValuesForChallan();
        console.log("Selected Value",selectedValue)
      });
  }
  onChange(event: any) {
    const selectedFile = event.target.files[0];
    const fileReader = new FileReader();
    fileReader.readAsBinaryString(selectedFile);
    fileReader.onload = (event: any) => {
      let binaryData = event.target.result;
      let workbook = XLSX.read(binaryData, { type: "binary", cellText: false, cellDates: true });

      /* grab first sheet */
      const wsname: string = workbook.SheetNames[0];
      const ws: XLSX.WorkSheet = workbook.Sheets[wsname];

      /* save data */
      this.data = <AOA>(XLSX.utils.sheet_to_json(ws, { header: 1, raw: true, dateNF: 'yyyy-mm-dd' }));
      let data:any[] = XLSX.utils.sheet_to_json(ws, { raw: true, dateNF: 'yyyy-mm-dd' });
      data.forEach(row => {
        Object.keys(row).forEach(key => {
          if (row[key] !== null && row[key] !== undefined && !isNaN(row[key]))
            {
              row[key] = Number(row[key]).toLocaleString('fullwide', {
                useGrouping: false
              });
            }
          });
        });

      
      this.viewdata = <AOA>(XLSX.utils.sheet_to_json(ws, { header: 1, raw: true, dateNF: 'd-m-yy' }));
      
      let viewdata = XLSX.utils.sheet_to_json(ws, { raw: true, dateNF: 'd-m-yy' });
      this.viewdata.forEach(row => {
      row.forEach((cell: any, index: number) => {
         if (cell !== null && cell !== undefined && !isNaN(cell))  {
          row[index] = Number(cell) .toLocaleString('fullwide', {
             useGrouping: false
            });
          }
        });
      });

      // this.data = <AOA>(XLSX.utils.sheet_to_json(ws, { header: 1 ,raw:false}));
      // let data=XLSX.utils.sheet_to_json(ws,{ raw:true});
      this.convertedJson = JSON.stringify(data, undefined, 4);
      this.isview = true;
      this.isadd = false;

    }
  }
  getMonthYear(date: Date): string {
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const year = date.getFullYear();
  return `${month},${year}`;
}
 getFinancialYearFromDate(date: Date): string {
  const year = date.getFullYear();
  const month = date.getMonth() + 1;

  // Financial year: Apr–Mar
  if (month >= 4) {
    return `${year}-${year + 1}`;
  } else {
    return `${year - 1}-${year}`;
  }
 }



  SaveUploadedData() {
    const dateValue  = this.getMonthYear(this.uploadForm.controls.date.value);
    const date = this.uploadForm.controls.date.value;
    const financialYear = this.getFinancialYearFromDate(date);
    this.isLoading = true;
    // let data = {
    //   'month':String(date.getMonth() + 1).padStart(2, '0'),
    //   'year':date.getFullYear(),
    //   'date':dateValue,
    //   'emplist': JSON.parse(this.convertedJson),
    //   'createdby': this.userSession.id
    // }
      let data = {
      'month':1,
      'year':2026,
      'date':dateValue,
      'financialYear': financialYear,
      'emplist': JSON.parse(this.convertedJson),
      'createdby': this.userSession.id
    }
   console.log("testData",data)
    
    this.PRService.setPayrllBulkuploadExcelData(data).subscribe(
      (res: any) => {
        this.isLoading = false;
        if(res.success_statusCode != 400){
        if (res.status) {
           let value =res.data[0]
          if (value.statuscode == 0) {
            this.removeData();
            this.isview = false;
            this.isadd = true;
            this.dialogService.openDialog(value.message);
            this.cancel();
          } else if (value.statuscode == 1) {
            this.dialogService.openDialog(value.message);
            this.removeData();
            this.isview = false;
            this.isadd = true;
            this.cancel();
          } else {
            this.dialogService.openDialog('Unable to save data.');
            this.removeData();
            this.isview = false;
            this.isadd = true;
            this.cancel();
          }
        } else {
          this.dialogService.openDialog('Unable to save data.');
          this.removeData();
          this.isview = false;
          this.isadd = true;
          this.cancel();
        }
       }
       else if(res.success_statusCode == 400){
        console.log("result",res)
        let msg = res.message;

          if (Array.isArray(res.errors) && res.errors.length > 0) {
            msg += '<br><br>' + res.errors.join('<br>');
          }
          this.dialogService.openDialog(msg);

       }
      },
      error => {
        error.error.text
      })
  }
  removeData() {
    this.isview = false;
    this.isadd = true;
    this.data = [[], []];
    this.convertedJson = '';
    this.cancel();
  }
cancel(){
 this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
            this.router.navigate(["/Payroll/bulkUpload"]));
}
  getExampleFileUrl(): SafeResourceUrl {
    const filePath = 'assets/images/bulk_upload.xlsx';
    const url = this.sanitizer.bypassSecurityTrustResourceUrl(filePath);
    return url;
  }
}


