import { Directive, ElementRef, HostListener } from '@angular/core';

@Directive({
  selector: '[numberDotOnly]'
})
export class NumberDotOnlyDirective {
  private regex = /^\d*\.?\d{0,2}$/;
  private specialKeys = [
    'Backspace', 'Tab', 'End', 'Home', 'ArrowLeft', 'ArrowRight', 'Delete'
  ];

  constructor(private el: ElementRef<HTMLInputElement>) {}

  @HostListener('keydown', ['$event'])
  onKeyDown(event: KeyboardEvent) {
    const input = this.el.nativeElement;

    // Allow special keys
    if (this.specialKeys.includes(event.key)) return;

    // Allow only digits and dot
    if (!/^[0-9.]$/.test(event.key)) {
      event.preventDefault();
      return;
    }

    const { selectionStart, selectionEnd, value } = input;

    const newValue =
      value.substring(0, selectionStart!) + event.key + value.substring(selectionEnd!);

    // Prevent leading dot
    if (newValue.startsWith('.')) {
      event.preventDefault();
      return;
    }

    // Prevent multiple dots or more than two decimal places
    if (!this.regex.test(newValue) || (newValue.match(/\./g)?.length ?? 0) > 1) {
      event.preventDefault();
    }
  }

  @HostListener('paste', ['$event'])
  onPaste(event: ClipboardEvent) {
    const clipboard = event.clipboardData?.getData('text') || '';
    const input = this.el.nativeElement;
    const { selectionStart, selectionEnd, value } = input;

    const newValue =
      value.substring(0, selectionStart!) + clipboard + value.substring(selectionEnd!);

    if (
      newValue.startsWith('.') ||
      !this.regex.test(newValue) ||
      (newValue.match(/\./g)?.length ?? 0) > 1
    ) {
      event.preventDefault();
    }
  }
}
