
import { Component, OnInit, ViewChild } from '@angular/core';
import { Router } from '@angular/router';
import { AdminService } from '../../admin.service';
import { MatDialog } from '@angular/material/dialog';
import { DesignationConfirmDialogComponent } from '../designation-confirm-dialog/designation-confirm-dialog.component';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { LeavePoliciesService } from 'src/app/services/leave-policies.service';
import { FormBuilder, UntypedFormControl, UntypedFormGroup, Validators } from '@angular/forms';
import { Location } from '@angular/common';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { environment } from 'src/environments/environment';
import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';

@Component({
  selector: 'app-organization-leave-policies',
  templateUrl: './organization-leave-policies.component.html',
  styleUrls: ['./organization-leave-policies.component.scss']
})
export class OrganizationLeavePoliciesComponent implements OnInit {
  selectedPolicyType: number | null = null;
  leavePolicies: any[] = [];
  companyName: string = '';
  newPolicyName: string = '';
  errorMessage: string = '';
  policyTypes: any[] = [];
  showDesignation = false;
  showLocation = false;
  isButtonsDisabled: boolean = true;
  showCreatePolicyForm: boolean = false;
  newLeavePolicyName: string = '';
  showTable: boolean = false;
  showPolicies = false;
  newLeavePolicyStatus: number = 1;
  showCreateForm = false;
  isLoading: boolean = false;
  dataSource: MatTableDataSource<any> = <any>[];
  dataSource1: MatTableDataSource<any> = <any>[];
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  pageLoading = true;

  displayedColumns: string[] = ['sno', 'policy_name', 'created_on', 'emp_count', 'status', 'actions'];
  displayedColumns2: string[] = ['sno', 'configurationrules', 'data', 'addditionalinformation'];
  defaultRuleInfo: any = [];
  isEditDefaultRules: boolean = false;
  statusList: any = [{ id: 1, status: 'Active' }, { id: 0, status: 'Inactive' }]
  arrayValue: any = [{ Value: '1', name: 'Yes' }, { Value: '0', name: 'No' }]
  arrayValues: any = [{ Value: '1', name: 'Yes' }, { Value: '0', name: 'No' }]
  arrayValuess: any = [{ Value: '1', name: 'Monthly' }, { Value: '3', name: 'Quarterly' }, { Value: '6', name: 'Half-Yearly' }, { Value: '12', name: 'Yearly' }]
  msgLM1: any;
  leavepoliciesForm: any = UntypedFormGroup;
  arrayValueOne: any;
  data: any;
  leavePolicyType: string = 'designation-based';
  DEDUCTION: boolean = false;
  INCLUDED: boolean = false;
  MAIL: boolean = false;
  BACKDATED: boolean = false;
  policyIdValue: any;
  leavePoliciesCount: any;
  selectedtab = new UntypedFormControl(0);
  userSession: any;


  constructor(
    private leavePoliciesService: AdminService,
    private router: Router,
    private dialog: MatDialog,
    private LM: LeavePoliciesService,
    private formBuilder: FormBuilder,
    private location: Location,
    private http: HttpClient,
    private dialogService: ReusableDialogService

  ) {
    this.data = this.location.getState();
    this.leavepoliciesForm = this.formBuilder.group({
      leavecycleyear: [""],
      mail: ["",],
      leavePolicy: ["", Validators.required],
    });
    if (this.data.viewPolicies) {
      this.selectedtab.setValue(1);
    }
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
  }

  ngOnInit(): void {


    this.getOrganizationLeavePolicies();
    if (this.selectedPolicyType) {
      this.onPolicyTypeChange(this.selectedPolicyType);
    }
    this.getCompanyLeavePolicies();
    this.getLeaveRules();
    this.getLeaveCycleYearOptions();

  }

  getOrganizationLeavePolicies() {
    this.leavePoliciesService.getOrganizationLeavePolicies().subscribe({
      next: (data: any) => {

        this.policyTypes = data.data || [];

        if (this.policyTypes.length > 0) {

          this.onPolicyTypeChange(this.selectedPolicyType);
          // this.isButtonsDisabled = true;
        }
        this.policyTypes.forEach((i: any) => {
          if (i.is_active === 1) {
            this.policyIdValue = i.id;
            this.selectedPolicyType = i.id;
          }
        })
        if (this.selectedPolicyType === this.policyIdValue) {
          this.isButtonsDisabled = true
        } else {
          this.isButtonsDisabled = false
        }
      },
    });
  }
  getCompanyLeavePolicies(callback?: () => void) {
    this.leavePoliciesService.getCompanyLeavePolicies().subscribe({
      next: (data: any) => {
        this.leavePolicies = data.data || [];
        this.leavePoliciesCount = this.leavePolicies.length;
        this.dataSource = new MatTableDataSource(this.leavePolicies);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;

        if (callback) {
          callback();
        }
      },
    });
  }

  onPolicyTypeChange(policyId: number | null): void {

    if (this.selectedPolicyType === this.policyIdValue) {
      this.isButtonsDisabled = true
    } else {
      this.isButtonsDisabled = false
    }
    if (policyId === null) return;
    // this.isButtonsDisabled = policyId === 1;  

    this.selectedPolicyType = policyId;
    this.showDesignation = policyId === 2;
    this.showLocation = policyId === 3;

    this.showTable = false;
    this.showCreateForm = false;
  }
  submit() {
    const data = { policyType: this.selectedPolicyType };

    this.leavePoliciesService.setchangeCompanyLeavePolicy(data).subscribe(
      (res: any) => {
        if (res.status) {

          this.getCompanyLeavePolicies(() => {

            const count = this.leavePolicies?.length || 0;


            if (this.selectedPolicyType === 2) {

              if (count > 0) {


                this.dialog.open(DesignationConfirmDialogComponent, {
                  data: {
                    title: '',
                    message: `The organization's leave policy is changed to Designation-based leave policies successfully. You will be redirected to <strong>Designation - Leave Policy Mapping</strong> screen.`,
                    confirmText: 'OK',
                    cancelText: 'Cancel'
                  }
                }).afterClosed().subscribe(result => {
                  if (result) {

                    this.router.navigate(['/Admin/dLPMapping']);
                  } else {
                    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
                      this.router.navigate(['/Admin/OrgLeavePolicies']))
                  }
                });
              } else {
                this.dialog.open(DesignationConfirmDialogComponent, {
                  data: {
                    title: '',
                    message: `The organization's leave policy is changed to Designation-based leave policies successfully. There are no exclusive leave policies. A new leave policy has to be created to map with the designations.`,
                    confirmText: 'OK',
                    cancelText: 'Cancel'
                  }
                }).afterClosed().subscribe(result => {
                  this.updateUIForPolicyCreation(true, true, true);
                });
              }
            } else if (this.selectedPolicyType === 1) {

              if (count > 0) {

                this.dialogService.openDialog(`The company's leave policy is changed successfully.`);

                this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
                  this.router.navigate(['/Admin/OrgLeavePolicies'])
                )
                // this.dialog.open(DesignationConfirmDialogComponent, {
                //   data: {
                //     title: '',
                //     message: `The company's leave policy is changed successfully.`,
                //     confirmText: 'OK',
                //     cancelText: 'Cancel'
                //   }
                // }).afterClosed().subscribe(result => {

                //     this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
                //       this.router.navigate(['/Admin/OrgLeavePolicies'])
                //     );

                // });
              } else {
                this.dialog.open(DesignationConfirmDialogComponent, {
                  data: {
                    title: '',
                    message: `The company's leave policy is changed to Common policy for all employees successfully. There are no exclusive leave policies. A new leave policy has to be created.`,
                    confirmText: 'OK',
                    cancelText: 'Cancel'
                  }
                }).afterClosed().subscribe(result => {
                  if (result) {
                    this.updateUIForPolicyCreation(true, true, true);
                  }
                });
              }
            }
          });
        } else {

          this.openDialog('Leave policy update failed.');
        }
      },
      (err: any) => {
        console.error('API error while changing policy:', err);
        this.openDialog('Something went wrong while changing the policy.');
      }
    );
  }

  openDialog(message: string): void {
    const dialogRef = this.dialog.open(DesignationConfirmDialogComponent, {
      data: {
        title: 'Error',
        message: message
      }
    });

    dialogRef.afterClosed().subscribe(result => {
      // if (result) {
      //   console.log('User clicked Yes');
      // } else {
      //   console.log('User clicked No');
      // }
    });
  }

  private openPolicyCreationDialog() {
    const dialogRef = this.dialog.open(DesignationConfirmDialogComponent, {
      width: '300px',
      data: {
        title: 'No Leave Policies',
        message: 'There are no exclusive leave policies. A new leave policy needs to be created to map with the designations.'
      }
    });

    dialogRef.afterClosed().subscribe(result => {
      if (result) {
        this.updateUIForPolicyCreation(true, true, true);
      } else {
        this.updateUIForPolicyCreation(true, false, false);
      }
    });
  }

  private updateUIForPolicyCreation(showTable: boolean, showCreatePolicyForm: boolean, showCreateForm: boolean) {
    this.selectedtab.setValue(1)
    this.showTable = showTable;
    this.showCreatePolicyForm = showCreatePolicyForm;
    this.showCreateForm = showCreateForm;
  }

  submitNewPolicy() {
    if (this.newLeavePolicyName && this.newLeavePolicyName.trim() !== '') {
      const duplicatePolicy = this.leavePolicies.find(p => p.policy_name.toLowerCase() === this.newLeavePolicyName.trim().toLowerCase());
      if (duplicatePolicy) {
        this.dialogService.openDialog('A leave policy with this name already exists. Please enter a different name.');
        return;
      }
      this.isLoading = true;
      const payload = {
        policy_name: this.newLeavePolicyName.trim(),
        status: this.newLeavePolicyStatus,
        created_by: 1
      };
      this.leavePoliciesService.setOrganizationLeavePolicy(payload).subscribe({
        next: (res: any) => {
          const statusCode = res.data.statuscode;
          const policyData = {
            id: res.data.policy_id,
            policy_name: res.data.policy_name,

          }
          if (statusCode === 0) {
            if (this.selectedPolicyType === 2) {
              const dialogRef = this.dialog.open(DesignationConfirmDialogComponent, {
                width: '1000px',
                data: {
                  message: 'A new leave policy is created successfully. You will be redirected to the <strong>Leave Policy</strong> screen. Do you wish to proceed?'
                }
              });

              dialogRef.afterClosed().subscribe(result => {
                if (result) {
                  // this.redirectToMappingScreen();
                  this.viewPolicy(policyData)
                } else {
                  this.newLeavePolicyName = '';
                  this.showCreateForm = false;
                  this.getCompanyLeavePolicies();

                }
              });

            } else {
              this.dialogService.openDialog('Leave Policy created successfully!');
              this.newLeavePolicyName = '';
              this.showCreateForm = false;
              this.getCompanyLeavePolicies();
            }
            this.isLoading = false;
          }
        },
        error: (err: any) => {
          this.isLoading = false;
          this.dialogService.openDialog('Failed to create leave policy. Please try again later.');

        }
      });
    } else {
      this.dialogService.openDialog('Please provide a valid leave policy name.');
    }
  }

  redirectToMappingScreen() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Admin/dLPMapping"]));

  }

  getPageSizes(): number[] {

    var customPageSizeArray = [];
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);

    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }


  toggleCreatePolicyForm() {
    this.showCreateForm = !this.showCreateForm;
  }


  clear() {
    this.newLeavePolicyName = '';
  }

  clearForm() {
    this.newLeavePolicyName = '';
  }



  reset() {

    this.selectedPolicyType = this.policyIdValue;
    this.isButtonsDisabled = true;
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Admin/OrgLeavePolicies"]));
  }


  viewPolicies() {

    this.showTable = true;
    this.showCreatePolicyForm = true;
    this.showCreateForm = false;
    this.getCompanyLeavePolicies();
  }

  viewPolicy(policy: any) {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Admin/Leavepolicies"], { state: { policyData: policy } }));

    // this.router.navigate(["/Admin/Leavepolicies"],{state: {policyData:policy}});
  }

  editPolicy(policy: any) {
  }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();

    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

  getLeaveRules() {
    let data = {
      policy_id_value: this.selectedPolicyType,
      leaveid: null,
      iscommonrule: null,
      company_rule: 1,
    }
    this.LM.getLeavePolicies(data).subscribe((result) => {
      this.defaultRuleInfo = JSON.parse(result.data[0].json);
      for (let obj of this.defaultRuleInfo) {
        if (obj.status === "Inactive") {
          obj.isselected = false;

        } else {
          obj.isselected = true;

        }

        obj.isValidate = false;
      }
      this.dataSource1 = new MatTableDataSource(this.defaultRuleInfo);
    })
  }

  valuesForCarryForwordleaves: any = [];
  getCarryforwardedLeaveMaxCount(leaveId: any) {
    this.valuesForCarryForwordleaves = [];
    this.valuesForCarryForwordleaves.push({ value: '', name: 'Select' })

    // for(let i=1;i<=12;i++){
    //   this.valuesForCarryForwordleaves.push({value:i,name:i})
    // }

    this.LM.getCarryforwardedLeaveMaxCount(leaveId).subscribe((result: any) => {
      if (result.status) {
        for (let i = 1; i <= parseInt(result.data[0].max_count); i++) {
          this.valuesForCarryForwordleaves.push({ value: i, name: i })
        }
      }
    })
  }

  activeLeaveTypesForCarryForword: any;
  getLeaveTypesForCarryForword() {

    this.LM.getLeaveDetails('lm_leavesmaster', 'Active', 1, 100).subscribe((result) => {
      this.activeLeaveTypesForCarryForword = result.data;
      this.activeLeaveTypesForCarryForword.push({ id: '', leavename: 'Select' })
    })
  }

  getLeaveCycleYearOptions() {
    this.LM.getLeaveCycleYearOptions().subscribe((result: any) => {
      if (result.status) {
        this.arrayValueOne = result.data
      }
    })

  }

  editDefaultRules() {
    this.isEditDefaultRules = true;
    for (let i = 0; i < this.defaultRuleInfo.length; i++) {
      if (this.defaultRuleInfo[i].rulename === "LEAVES_IS_MAIL_FACILITY_REQUIRED") {
        this.leavepoliciesForm.controls.mail.setValue(this.defaultRuleInfo[i].value);
      }
      else if (this.defaultRuleInfo[i].rulename === "LEAVE_CYCLE_YEAR") {
        this.leavepoliciesForm.controls.leavecycleyear.setValue(this.defaultRuleInfo[i].value)

      }
      else if (this.defaultRuleInfo[i].rulename === "COMPANY_LEAVE_POLICY_TYPE") {
        this.leavepoliciesForm.controls.leavePolicy.setValue(Number(this.defaultRuleInfo[i].value))
      }
    }
  }

  cancelDefaultRules() {

    this.isEditDefaultRules = !this.isEditDefaultRules;

  }

  submitLeavePolicy() {
    const requestData = {
      policy_id_value: this.selectedPolicyType,
      companyName: this.companyName
    };

    this.http.post(`${environment.apiUrl}/change-leave-policy`, requestData).subscribe(
      (response: any) => {
        if (response.status) {
          console.log('Leave policy updated successfully');
        } else {
          console.log('Leave policy update failed');
        }
      },
      (error: HttpErrorResponse) => {
        console.error('Error calling the API', error);
      }
    );
  }

  saveDefaultrules() {

    for (let i = 0; i < this.defaultRuleInfo.length; i++) {
      if (this.defaultRuleInfo[i].rulename == "LEAVES_IS_MAIL_FACILITY_REQUIRED") {
        this.defaultRuleInfo[i].value = this.leavepoliciesForm.controls.mail.value;
      }
      else if (this.defaultRuleInfo[i].rulename == "LEAVE_CYCLE_YEAR") {
        this.defaultRuleInfo[i].value = this.leavepoliciesForm.controls.leavecycleyear.value;
      }
    }


    var info = {
      ruleData: this.defaultRuleInfo,
      policyId: null,
      isCompanyRule: 1,
    }
    this.LM.setLeavePoliciesOrg(info).subscribe((data) => {
      /*  this.isEditLeaveType = false;*/
      this.getLeaveRules();
      if (data.status) {
        this.dialogService.openDialog(data.message);
        this.isEditDefaultRules = false;
        // this.addBtn1 = true;
        this.ngOnInit();
      }
      else {
        this.dialogService.openDialog('Unable to update leave policies. Please try again.');
      }
    });


  }
  backToViewPolicies() {
    this.showCreateForm = !this.showCreateForm;


  }
  status(halfid: any, policy: any) {
    if (halfid === 0) {
      if (policy.id === null) {
        if (this.selectedPolicyType === 1) {
          this.dialogService.openDialog('Cannot Inactive Common Leave policy for all employees');
          this.getCompanyLeavePolicies();
        } else {
          this.toggleLeavePolicy(halfid, policy)
        }
      } else {
        if (policy.emp_count === 0) {
          this.toggleLeavePolicy(halfid, policy)
        } else {
          this.dialogService.openDialog(`This leave policy is in use by some designations. Assign these designations to another leave policy before deactivating this leave policy.`);
          this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
            this.router.navigate(['/Admin/dLPMapping']))
        }
      }
    } else {
      this.toggleLeavePolicy(halfid, policy)
    }

  }
  toggleLeavePolicy(status: any, policy: any) {
    let payload = {
      leave_policy_id_value: policy.id,
      status_value: status,
      updated_by_value: this.userSession.id
    }
    this.leavePoliciesService.toggleLeavePolicy(payload).subscribe((result: any) => {
      if (result.status) {
        this.dialogService.openDialog(result.message);
        this.getCompanyLeavePolicies();
      } else {
        this.dialogService.openDialog(result.message);
      }
    })
  }

}
