import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
@Component({
  selector: 'app-test-screen',
  templateUrl: './test-screen.component.html',
  styleUrls: ['./test-screen.component.scss']
})
export class TestScreenComponent implements OnInit {

  question: any = 1;
  marks: any = 30;
  duration: any = 30;
  displayQuestion: any = ['1. What is MySQL?'];
  options: any = [
    { id: 1, value: 'a.' },
    { id: 2, value: 'b.' },
    { id: 3, value: 'c.' },
    { id: 4, value: 'd.' },
  ]
  number: any = [];
  constructor(
    private router: Router,
  ) { }

  ngOnInit(): void {
    this.questionNumbers();
  }
  questionNumbers() {
    for (let i = 0; i <= 28; i++) {
      this.number[0] = 1;
      this.number[i + 1] = this.number[i] + 1;
    }

  }
  applyFilter() {

  }
  navigateToResult() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/learning/testResult']));
  }
}
