import { Component, OnInit, ViewChild } from '@angular/core';
import { AdminService } from '../../admin.service';
import { MatPaginator } from '@angular/material/paginator';
import { MatTableDataSource } from '@angular/material/table';
import { FormBuilder, FormControl, UntypedFormGroup } from '@angular/forms';
import { UserData } from '../deparment/deparment.component';
import { MatSort } from '@angular/material/sort';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { MatDialog } from '@angular/material/dialog';
import { Router } from '@angular/router';
import { DesignationConfirmDialogComponent } from '../designation-confirm-dialog/designation-confirm-dialog.component';

@Component({
  selector: 'app-designation-leave-policy',
  templateUrl: './designation-leave-policy.component.html',
  styleUrls: ['./designation-leave-policy.component.scss']
})
export class DesignationLeavePolicyComponent implements OnInit {

  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort) sort!: MatSort;
  pageLoading = true;
  designations: any[] = [];
  dataSource!: MatTableDataSource<UserData>;
  displayedColumns: string[] = ['sno', 'designation', 'display_name', 'emp_count', 'policy_id'];
  leavePolicies: any[] = [];
  searchControl = new FormControl('');
  filteredPolicies: any = [];
  mappingForm: any = UntypedFormGroup;
  UserSession:any;
  policyTypes:any=[];
  policyIdValue:any;
  submitDisabled:boolean = false;
  resetDisabled = true;
  initialDesignations: any[] = [];

  constructor(
    private leavePoliciesService: AdminService,
    private formBuilder: FormBuilder,
    private dialog:MatDialog,
     private router: Router,  
  ) { 
    this.UserSession = JSON.parse(sessionStorage.getItem('user') ?? '')
    this.getOrganizationLeavePolicies()
  }

  ngOnInit(): void {
    this.mappingForm = this.formBuilder.group({
      policyId: this.formBuilder.array([])
    });
    this.getDesignations();
    this.getCompanyLeavePolicies();
    this.searchControl.valueChanges.subscribe(searchText => {
      this.filterPolicies(searchText || '');
    });
  }

   getDesignations() {
    this.leavePoliciesService.getCompanyDesignations().subscribe((res: any) => {
      if (res.data) {
        this.designations = res.data || [];
        this.initialDesignations = JSON.parse(JSON.stringify(this.designations));
      this.updateButtonStates();
        this.dataSource = new MatTableDataSource(this.designations);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;
      }
    });
  }

  getCompanyLeavePolicies() {
    this.leavePoliciesService.getCompanyLeavePolicies().subscribe((data: any) => {
      if (data && data.data) {
        this.leavePolicies = data.data.filter((policy: any) => policy.id !== null && policy.policy_status !== 0);
        this.filteredPolicies = this.leavePolicies;
      }
    });
  }

  onSubmit() {

    const unmappedDesignations = this.designations.filter(d => !d.policy_id);
    
    if (unmappedDesignations.length > 0) {
      this.dialog.open(ReusableDialogComponent, {
                    position: { top: `70px` },
                    disableClose: true,
                    data: `Please map policies for all designations. ${unmappedDesignations.length} designation(s) still need mapping.`,
      });
      return
    }

    const mappingArray = this.designations
      .filter(d => d.policy_id) // Filter only rows with selected policies
      .map(d => ({
        designation_id: d.id,
        leave_policy_id: d.policy_id
      }));

    const payload = {
      mapping_data: JSON.stringify(mappingArray),
      created_by_value: this.UserSession.id,
      updated_by_value: this.UserSession.id,
    };

    this.leavePoliciesService.setDesignationLeavePolicyMapping(payload).subscribe((res: any) => {
        if (res.status) {
          if(res.statusCode === 0 ){
            this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: 'The designations are mapped to the respective leave policies successfully.',
            });
            this.onReset();
          }else{
            this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: 'Mapping already exists.',
            });
          }
        } else {
          this.dialog.open(ReusableDialogComponent, {
            position: { top: `70px` },
            disableClose: true,
            data: res.message || 'Something went wrong',
          });
        }
      },
    );
  }

  onReset() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
    this.router.navigate(["/Admin/dLPMapping"],{state:{viewPolicies :true}}));
    this.updateButtonStates();
}


  onPolicySelect(row: any, policyId: any): void {
    // Update the policy_id property on the row when selection changes
    row.policy_id = policyId;
    this.updateButtonStates();

  }

  filterPolicies(searchText: string) {
    this.filteredPolicies = this.leavePolicies.filter((val: any) =>
      val.policy_name.toLowerCase().includes(searchText.toLowerCase())
    );
  }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

  getPageSizes(): number[] {
    var customPageSizeArray = [];

    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  getOrganizationLeavePolicies() {
    this.leavePoliciesService.getOrganizationLeavePolicies().subscribe({
      next: (data: any) => {
     
        this.policyTypes = data.data || [];
        
        this.policyTypes.forEach((i:any)=>{
          if(i.is_active === 1){
            this.policyIdValue = i.id;

          }
       
    });

    if(this.policyIdValue ===1){
      let dialogRef1 = this.dialog.open(ReusableDialogComponent, {
        position:{top:`70px`},
        disableClose: true,
        data: 'Please change the organization leave policy to Designation-based leave policies to access this screen.'
      });
      dialogRef1.afterClosed().subscribe(result => {
        this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
          this.router.navigate(["/Admin/OrgLeavePolicies"]));
      });

}

  }
})}

updateButtonStates() {
  this.submitDisabled = this.designations.some(d => !d.policy_id);
  this.resetDisabled = !this.designations.some((d, i) => {
    return d.policy_id !== this.initialDesignations[i]?.policy_id;
  });
}
}