import { Component, OnInit, ViewChild, AfterViewInit, ElementRef } from '@angular/core';
import { LearnService } from '../../learn.service';
import { DomSanitizer, SafeHtml, SafeUrl } from '@angular/platform-browser';
import { Chart } from 'chart.js';
import { MatDialog } from '@angular/material/dialog';
import { Router } from '@angular/router';
import { switchMap } from 'rxjs/operators';
import { Observable, of } from 'rxjs';
import { ChangeDetectorRef } from '@angular/core';

interface TimeFilter {
  filter_name: string;
  id: number;
}


interface Badge {
  badge_id: number;
  badge_image: string | null;
  badge_name: string;
}

interface LeaderboardItem {
  avatar: string | null;
  average_test_score: number;
  badges: Badge[];
  highest_streak: number;
  rank: number;
  total_acquired_points: number;
  user_id: number;
  username: string;
}


interface CourseResponse {
  courses: any[];
}

@Component({
  selector: 'app-lms-emp-dashboard',
  templateUrl: './lms-emp-dashboard.component.html',
  styleUrls: ['./lms-emp-dashboard.component.scss']
})
export class LmsEmpDashboardComponent implements OnInit, AfterViewInit {
  enrolledCourses: any[] = [];
  assignedCourses: any[] = [];
  recommendedCourses: any[] = [];
  trendingCourses: any[] = [];
  popularCourses: any[] = [];
  activeTab: string = 'enrolled';  // Default tab
  showEdit = false;
  avatarPopupOpen = false;
  avatars: { id: number; avatar: string }[] = [];

  canScrollLeft: boolean = false;
  canScrollRight: boolean = false;

  // Navigation state for course carousels
  currentIndex: Record<string, number> = {
    enrolled: 0,
    assigned: 0,
    recommended: 0,
    trending: 0,
    popular: 0,
    personal: 0
  }
  itemsPerView = 4

  employeeDashboard: any = {};
  badgePopupOpen: { [userId: number]: boolean } = {};

  employeeId: number = 2; // Set your employee id here
  branchId: number = 0;  // Set your branch id here
  leaderboardData: LeaderboardItem[] = [];
  userSession: any

  showConfirmDialog = false;
  selectedEnrollCourseId: number | null = null;
  enrollmentComplete = false;
  enrollmentSuccessMessage = '';
  enrollmentInProgress = false;
  profileQuote: string = '';
insights: SafeHtml = '';


  @ViewChild('carousel') carousel: any;
@ViewChild('scrollContainer', { static: true }) scrollContainer!: ElementRef<HTMLElement>;
  @ViewChild('barChart') barChart!: ElementRef<HTMLCanvasElement>;
  progressData: any[] = [];
  filters: TimeFilter[] = [];
  selectedFilterId: number = 0;
  chartInstance: Chart | undefined;
  profileImage: SafeUrl | null = null;
  userName: string = '';
  constructor(private learnService: LearnService, private cd: ChangeDetectorRef, private sanitizer: DomSanitizer, private dialog: MatDialog, private router: Router) {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.userName = this.userSession.firstname;


   }

  ngOnInit(): void {
    this.getLeaderboard();
    this.getEnrolledCourses();
    this.getAssignedCourses();
    this.getRecommendedCourses();
    this.getTrendingCourses();
    this.getPopularCourses();
    this.getUserDailyProgress();
    this.getTimeFilters();
    this.fetchEmployeeDashboardData();
    this.getProfileImage();

  }

  ngAfterViewInit(): void {
    this.updateScrollButtons();
  }


  openAvatarPopup() {
    this.avatarPopupOpen = true;
    this.learnService.getAvatars().subscribe({
      next: (list) => this.avatars = list,
      error: (e) => console.error('could not load avatars', e)
    });
  }

  closeAvatarPopup() {
    this.avatarPopupOpen = false;
  }

  selectAvatar(avatarId: number, avatarBase64: string) {
    const userId = this.userSession.id;
    this.learnService.setAvatar(userId, avatarId).subscribe({
      next: () => {
        this.profileImage = this.sanitizer.bypassSecurityTrustUrl(avatarBase64);
        this.avatarPopupOpen = false;
      },
      error: (e) => console.error('could not set avatar', e)
    });
  }


  getLeaderboard(): void {
    this.learnService.getLeaderboardData(0, 0,0)
      .subscribe(
        // 3) Tell TypeScript exactly what shape we expect back:
        (data: { employees_leaderboard: LeaderboardItem[] }) => {
          this.leaderboardData = data.employees_leaderboard;
        },
        (error: any) => {
          console.error('Error loading leaderboard data', error);
        }
      );
  }

  getEnrolledCourses(): void {
    const courseId=0;
    const userId = this.userSession.id;
    const deptId: any=0;
    const difficultyLevelId:  any=0;
    const timeFilterId=0;
    const instructorId=0;
    const statusId: any=2; //enrolled

    this.learnService.get_lms_course(courseId, userId, deptId, difficultyLevelId,timeFilterId,instructorId,statusId ).subscribe(
      (data: { courses: any[]; }) => {
        this.enrolledCourses = data.courses;
        console.log('Enrolled courses loaded:', this.enrolledCourses.length, this.enrolledCourses);
      },
      (error: any) => {
        console.error('Error loading enrolled courses:', error);
      }
    );
  }

  getAssignedCourses(): void {
    const courseId=0;
    const userId = this.userSession.id;
    const deptId: any=0;
    const difficultyLevelId:  any=0;
    const timeFilterId=0;
    const instructorId=0;
    const statusId: any=1; //Assigned

    this.learnService.get_lms_course(courseId, userId, deptId, difficultyLevelId,timeFilterId,instructorId,statusId ).subscribe(
      (data: { courses: any[]; }) => {
        this.assignedCourses = data.courses;
        this.cd.detectChanges();
      },
      (error: any) => {
        console.error('Error loading assigned courses:', error);
      }
    );
  }

  getRecommendedCourses(): void {
    this.learnService.getRecommendedCourses(this.userSession.id)
      .pipe(
        switchMap((ids: number[]): Observable<CourseResponse> => {
          console.log('Recommended course IDs:', ids); // Debug log
          if (!ids || ids.length === 0) {
            console.log('No recommended course IDs found');
            this.recommendedCourses = [];
            return of({ courses: [] });
          }
          return this.learnService.get_lms_course(
            ids,
            this.userSession.id,
            0, 0, 0, 0,
            4
          ) as Observable<CourseResponse>;
        })
      )
      .subscribe(
        (res: CourseResponse) => {
          console.log('Recommended courses response:', res); // Debug log
          this.recommendedCourses = res.courses;
          this.updateScrollButtons();
        },
        (err: any) => {
          console.error('Error loading recommended courses:', err);
          this.recommendedCourses = []; // Ensure empty array on error
        }
      );
  }
  


  getTrendingCourses(): void {
    this.learnService.getTrendingCourses(this.userSession.id)
      .pipe(
        switchMap(ids =>
          ids && ids.length
            ? this.learnService.get_lms_course(ids, this.userSession.id, 0,0,0,0,4)
            : of({ courses: [] })
        )
      )
      .subscribe({
        next: (data) => {
          // cast `data` from unknown → known shape
          const payload = data as { courses: any[] };
          this.trendingCourses = payload.courses;
          this.updateScrollButtons();
        },
        error: e => console.error('Error loading trending courses:', e)
      });
  }
  
  getPopularCourses(): void {
    this.learnService.getPopularCourses(this.userSession.id)
      .pipe(
        switchMap(ids =>
          ids && ids.length
            ? this.learnService.get_lms_course(ids, this.userSession.id, 0,0,0,0,4)
            : of({ courses: [] })
        )
      )
      .subscribe({
        next: (data) => {
          const payload = data as { courses: any[] };
          this.popularCourses = payload.courses;
          this.updateScrollButtons();
        },
        error: e => console.error('Error loading popular courses:', e)
      });
  }  

  // Switch tab logic
switchTab(tab: string): void {
  this.activeTab = tab;
  this.updateScrollButtons();

  if (tab === 'personal') {
    this.loadPersonalRecommendations();
  }
}


loadPersonalRecommendations(): void {
  const userId = this.userSession.id;
  this.learnService.generateRecommendations({ user_id: userId })
    .subscribe({
      next: (res: { insights: string }) => {
        this.insights = res.insights;
      },
      error: err => {
        console.error('Error loading recommendations', err);
        this.insights = 'Could not load recommendations. Please try again later.';
      }
    });
}


  // Update the scroll buttons visibility based on content width
updateScrollButtons(): void {
  const el = this.scrollContainer?.nativeElement;
  if (!el) {
    this.canScrollLeft = false;
    this.canScrollRight = false;
    return;
  }

  const cw = el.offsetWidth;
  const sw = el.scrollWidth;

  this.canScrollLeft  = el.scrollLeft > 0;
  this.canScrollRight = el.scrollLeft < sw - cw;
}

scrollLeft(): void {
  const el = this.scrollContainer.nativeElement;
  el.scrollBy({ left: -300, behavior: 'smooth' });
  this.updateScrollButtons();
}

scrollRight(): void {
  const el = this.scrollContainer.nativeElement;
  el.scrollBy({ left:  300, behavior: 'smooth' });
  this.updateScrollButtons();
}



  scrollRecommended(dir: 'left' | 'right') {
    if (!this.scrollContainer?.nativeElement) {
      console.warn('Scroll container not available');
      return;
    }
    const el = this.scrollContainer.nativeElement;
    const amount = dir === 'left' ? -300 : 300;
    el.scrollBy({ left: amount, behavior: 'smooth' });
  }

  // New navigation methods for course carousels
  navigateCourses(direction: 'left' | 'right', courseType: string) {
    console.log('navigateCourses called:', direction, courseType);
    
    const courses = this.getCoursesByType(courseType)
    
    if (direction === 'left' && this.currentIndex[courseType] > 0) {
      this.currentIndex[courseType] = Math.max(0, this.currentIndex[courseType] - 1)
    } else if (direction === 'right' && this.currentIndex[courseType] + this.itemsPerView < courses.length) {
      this.currentIndex[courseType] = Math.min(courses.length - this.itemsPerView, this.currentIndex[courseType] + 1)
    }
    
    console.log(`Navigation ${direction} for ${courseType}:`, {
      currentIndex: this.currentIndex[courseType],
      totalCourses: courses.length,
      itemsPerView: this.itemsPerView
    })
  }

  onScroll(event: any, courseType: string) {
    const element = event.target
    const scrollLeft = element.scrollLeft
    const scrollWidth = element.scrollWidth
    const clientWidth = element.clientWidth
    
    // Calculate which "page" we're on based on scroll position
    const cardWidth = clientWidth / this.itemsPerView
    const newIndex = Math.round(scrollLeft / cardWidth)
    
    // Update currentIndex if it changed
    if (newIndex !== this.currentIndex[courseType]) {
      this.currentIndex[courseType] = newIndex
      console.log(`Scroll detected for ${courseType}, new index:`, newIndex)
    }
  }

  getCoursesByType(type: string): any[] {
    switch(type) {
      case 'enrolled': return this.enrolledCourses || []
      case 'assigned': return this.assignedCourses || []
      case 'recommended': return this.recommendedCourses || []
      case 'trending': return this.trendingCourses || []
      case 'popular': return this.popularCourses || []
      default: return []
    }
  }

  getVisibleCourses(courseType: string): any[] {
    const courses = this.getCoursesByType(courseType)
    if (!courses || courses.length === 0) return []
    
    const start = this.currentIndex[courseType]
    const visible = courses.slice(start, start + this.itemsPerView)
    
    if (courseType === 'enrolled') {
      console.log('Enrolled courses debug:', {
        totalCourses: courses.length,
        currentIndex: start,
        itemsPerView: this.itemsPerView,
        visibleCount: visible.length,
        courseNames: visible.map(c => c.course_name)
      })
    }
    
    return visible
  }

  isLeftDisabled(courseType: string): boolean {
    const courses = this.getCoursesByType(courseType)
    return !courses || courses.length === 0 || this.currentIndex[courseType] === 0
  }

  isRightDisabled(courseType: string): boolean {
    const courses = this.getCoursesByType(courseType)
    if (!courses || courses.length === 0) return true
    
    const disabled = this.currentIndex[courseType] >= courses.length - this.itemsPerView
    
    if (courseType === 'enrolled') {
      console.log('Right button disabled check:', {
        currentIndex: this.currentIndex[courseType],
        itemsPerView: this.itemsPerView,
        totalCourses: courses.length,
        calculation: `${this.currentIndex[courseType]} >= ${courses.length - this.itemsPerView}`,
        result: disabled
      })
    }
    
    return disabled
  }


  courseContinue(courseId: number): void {
    this.router.navigate(['/learning/LmsViewCourse', courseId]);
  }

  getUserDailyProgress(): void {
  const userId = this.userSession.id;

  this.learnService
    .getUserDailyProgress(userId, this.selectedFilterId)
    .subscribe(
      (data: { [x: string]: any[] }) => {
        this.progressData = data['completed sections'] || [];

        // 🔥 If NO DATA → destroy chart & skip rendering
        if (!this.progressData || this.progressData.length === 0) {
          if (this.chartInstance) {
            this.chartInstance.destroy();
          }
          this.chartInstance = undefined;
          this.cd.detectChanges();   // refresh HTML
          return;
        }

        // Otherwise, render normally
        this.renderChart();
      },
      (error: any) => {
        console.error('Error fetching progress data', error);
      }
    );
}



  getTimeFilters(): void {
    this.learnService.getTimeFilters().subscribe(
      (      data: { filters: TimeFilter[]; }) => {
        this.filters = data.filters;
        if (this.filters && this.filters.length > 0) {
          // Set default filter id to the first filter
          this.selectedFilterId = this.filters[1].id;
        }
        // Load the progress data using the default filter
        this.getUserDailyProgress();
      },
      (      error: any) => {
        console.error('Error fetching time filters', error);
      }
    );
  }

  onFilterChange(): void {
    this.getUserDailyProgress();
  }

    // Separate function to fetch employee dashboard data
  fetchEmployeeDashboardData(): void {
    const userId   = this.userSession.id;
      this.learnService.getEmployeeDashboard(userId).subscribe(
        (data: { employee_dashboard: any; }) => {
          // The API returns { "employee_dashboard": { ... } }
          this.employeeDashboard = data.employee_dashboard;
        },
        (error: any) => {
          console.error('Error loading employee dashboard data:', error);
        }
      );
  }
  


  renderChart(): void {
    // Destroy previous chart instance if it exists
    if (this.chartInstance) {
      this.chartInstance.destroy();
    }
    // Map labels and data from progressData
    const labels = this.progressData.map(item => item.period_label);
    const completedSections = this.progressData.map(item => item.completed_sections);

    // Create new chart instance
    this.chartInstance = new Chart(this.barChart.nativeElement, {
      type: 'bar',
      data: {
        labels: labels,
        datasets: [{
          label: 'Completed Sections',
          data: completedSections,
        }]
      },
      options: {
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              precision: 0
            }
          }
        }
      }
    });
  }


  getProfileImage(): void {
   const userId = this.userSession.id;

    this.learnService.getEmployeeAvatar(userId).subscribe(
         (data: { avatar: string; message?: string; }) => {
        if (data && data.avatar) {
          const imageUrl = data.avatar;
          this.profileImage = this.sanitizer.bypassSecurityTrustUrl(imageUrl);
        }
      const raw = data.message || '';
      this.profileQuote = raw.replace(/^"(.*)"$/, '$1');
      },
      (error: any) => {
        console.error('Error fetching profile image', error);
      }
    );
  }


  toggleBadgePopup(userId: number) {
    this.badgePopupOpen[userId] = !this.badgePopupOpen[userId];
  }



  getProgress(course: any): number {
    if (!course.total_sections || course.total_sections === 0) return 0;
    const completed = course.completed_sections || 0;
    return Math.floor((completed / course.total_sections) * 100);
  }



    getThumbnail(thumbnail: string): SafeUrl {
      if (thumbnail && !thumbnail.startsWith('data:image')) {
        return this.sanitizer.bypassSecurityTrustUrl(`data:image/png;base64,${thumbnail}`);
      }
      return this.sanitizer.bypassSecurityTrustUrl(thumbnail);
    }

    getFormattedDuration(duration: string): string {
      const [hours, minutes] = duration.split(':').map(num => parseInt(num));
      return `${hours.toString().padStart(2, '0')}hr : ${minutes.toString().padStart(2, '0')}min`;
    }

 
  enrollCourse(courseId: number): void {
    this.selectedEnrollCourseId = courseId;
    this.showConfirmDialog = true;
    this.enrollmentComplete = false;
    this.enrollmentSuccessMessage = '';
  }

  confirmEnroll(): void {
    if (this.selectedEnrollCourseId == null) return;
  
    this.enrollmentInProgress = true;
  
    // ← define both userId and courseId
    const userId   = this.userSession.id;
    const courseId = this.selectedEnrollCourseId;
  
    // ← now courseId exists!
    this.learnService
      .setEnrollment(userId, courseId)
      .subscribe({
        next: (res: any) => {
          this.enrollmentSuccessMessage = res.message || 'Enrollment successful';
          this.enrollmentComplete       = true;
          this.enrollmentInProgress     = false;
        },
        error: (err) => {
          console.error('Enrollment error:', err);
          this.enrollmentSuccessMessage = 'Enrollment failed. Please try again.';
          this.enrollmentComplete       = true;
          this.enrollmentInProgress     = false;
        }
      });
  }
  

  // Called when user clicks “No”
  cancelEnroll(): void {
    this.showConfirmDialog = false;
    this.selectedEnrollCourseId = null;
  }

  // After success, proceed to view-course
  proceedToCourse(): void {
    if (this.selectedEnrollCourseId != null) {
      this.showConfirmDialog = false;
      this.router.navigate(
        ['/learning/LmsViewCourse', this.selectedEnrollCourseId]
      );
    }
  }
  
  
}
