import {  Component, OnInit,ChangeDetectorRef } from '@angular/core';
import { DatePipe } from '@angular/common';
import {  UntypedFormControl } from '@angular/forms';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import * as _moment from 'moment';
import ChartDataLabels from 'chartjs-plugin-datalabels';
import { MainService } from 'src/app/services/main.service';
import { NgxSpinnerService } from 'ngx-spinner';
import { TranslateService } from '@ngx-translate/core';
const moment = _moment;
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    // dateInput: 'MM-YYYY',
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
@Component({
  selector: 'app-client-sa-dashboard',
  templateUrl: './client-sa-dashboard.component.html',
  styleUrls: ['./client-sa-dashboard.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class ClientSaDashboardComponent implements OnInit {
  pipe = new DatePipe('en-US');
  currentYear: any = new Date();
  companyName: any;
  minDate = new Date('2000/01/01');
  maxDate = new Date();
  ChartDataLabels = ChartDataLabels;
  selectedtab = new UntypedFormControl(0);
  userSession:any;
  is_not_verified:any = true;
  is_module:any = {        
      employee:{id:1,present:false,name:null},
      leave:{id:2,present:false,name:null},      
      timesheet:{id:3,present:false,name:null},
      attendance:{id:4,present:false,name:null},
      payroll:{id:5,present:false,name:null},
      assets:{id:6,present:false,name:null},
      recruitment:{id:7,present:false,name:null},
      employeeselfservice:{id:8,present:false,name:null},
      claims:{id:9,present:false,name:null},
      subscription:{id:10,present:false,name:null},      
      exit:{id:11,present:false,name:null},
      salespro:{id:12,present:false,name:null},
      reports:{id:13,present:false,name:null}, 
      learning:{id:14,present:false,name:null},
    };   
  constructor(private main:MainService, private spinner: NgxSpinnerService,private translate: TranslateService,private cdr: ChangeDetectorRef) {
    this.companyName = sessionStorage.getItem('companyName');   
  }
  ngOnInit(): void {   
    let  savedLang = localStorage.getItem('lang');
    this.translate.use(savedLang || 'english');

    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');   
    this.getModulesData();     
  }

   ngAfterViewInit() {
    let  savedLang = localStorage.getItem('lang');
    this.translate.use(savedLang || 'english');
    this.cdr.detectChanges(); // ✅ refresh view safely
  }

  selectedTabChange(event: any) {
    if (event.index == 0) {
      this.selectedtab.setValue(0);
    } else if (event.index == 1) {
      this.selectedtab.setValue(1);
    } else if (event.index == 2) {
      this.selectedtab.setValue(2);
    } else if (event.index == 3) {
      this.selectedtab.setValue(3);
    } else if (event.index == 4) {
      this.selectedtab.setValue(4);
    }
  }
 
 
  getModulesPresent(modules:any){     
     if (modules.length && this.is_not_verified) {
            for(let i = 0;i<modules.length;i++){
                let m = modules[i].modulename.toString().toLowerCase().replace('management','').replace(' ','').trim();
                if(this.is_module[m].id == modules[i].id){
                  this.is_module[m].present = true;
                  this.is_module[m].name = modules[i].modulename;
                }  
            }   
            this.is_not_verified = false;  
          }
    }


  getModulesData() {   
      let menuList:any = null;      
      if (!(sessionStorage.getItem("moduleData") && sessionStorage.getItem("moduleData")?.toString().length)) {
      this.spinner.show();
      this.main.getSideNavigation({ empid: this.userSession.id, companyName: sessionStorage.getItem('companyName') }).subscribe((res: any) => {
        this.spinner.hide();
        menuList = res.data;   
        sessionStorage.setItem("moduleData", JSON.stringify(menuList));
        sessionStorage.setItem('selectedModule', 'Spryple');
        sessionStorage.setItem('compOffEnabled', res.compOffEnabled ? 'Active' : 'Inactive');
        this.getModulesPresent(menuList);
      });
    }
    else {
         menuList = sessionStorage.getItem("moduleData");
        if (menuList && menuList.toString().length) menuList = JSON.parse(menuList);
        this.getModulesPresent(menuList);
    }

  }
}


