  /** Load token + companyName and configure headers */
  private refreshSession(): void {
    const token = sessionStorage.getItem('token');
    this.companyName = sessionStorage.getItem('companyName') || '';
    this.httpOptions = {
      headers: new HttpHeaders({
        'Content-Type': 'application/json',
        Authorization: token ? `Bearer ${token}` : '',
      }),
    };
  }

  /** Build GET URL with /companyName inserted before query parameters */
  private buildGetUrl(path: string): string {
    // Split path into base URL and query parameters
    const [basePath, queryString] = path.split('?');
    const cleanPath = basePath.replace(/\/+$/, '');

    // Insert company code before query string (if query string exists)
    if (queryString) {
      return `${cleanPath}/${this.companyName}?${queryString}`;
    }
    return `${cleanPath}/${this.companyName}`;
  }

  /** Inject company_name into JSON body */
  private addCompanyToBody<T extends object>(
    body: T,
  ): T & { company_code: string } {
    return { ...body, company_code: this.companyName };
  }

