  // In LearnService (add alongside existing addQuestions)
  addQuestionsMultipart(formData: FormData): Observable<any> {
    const url = `${this.mainUrl}/lms_add_questions`;
    const token = sessionStorage.getItem('token') || '';
    const opts = {
      headers: new HttpHeaders({
        Authorization: token ? `Bearer ${token}` : '',
      }),
    };

    console.log('🟨 addQuestionsMultipart() called');
    const fdWithCompany = this.addCompanyToFormData(formData);
    console.log('🟨 Final FormData being sent:');
    fdWithCompany.forEach((v, k) => console.log(`   ${k}:`, v));

    return this.http.post(url, fdWithCompany, opts).pipe(
      tap({
        next: (res) => console.log('✅ Server Multipart Response:', res),
        error: (err) => console.error('❌ Multipart Upload Error:', err),
      }),
      catchError((err) => {
        console.error('🔥 Caught multipart error:', err);
        return throwError(() => err);
      }),
    );
  }

