import { Component, OnInit, TemplateRef, ViewChild, ViewContainerRef } from '@angular/core';
import { UntypedFormGroup, UntypedFormBuilder, Validators } from '@angular/forms';
import { MatDialog } from '@angular/material/dialog';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { Router } from '@angular/router';
import { TdsService } from '../../tds.service';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { DialogComponent } from '../../dialog/dialog.component';
import { ApproveEarningDialogComponent } from '../approve-earning-dialog/approve-earning-dialog.component'
@Component({
  selector: 'app-earning-approvals-tds',
  templateUrl: './earning-approvals-tds.component.html',
  styleUrls: ['./earning-approvals-tds.component.scss']
})
export class EarningApprovalsTdsComponent implements OnInit {
  userSession: any;
  companyName: any;
  pageLoading: boolean = true;
  pageLoadingHistory: boolean = true;
  displayedColumns: string[] = ['sno','employee_code', 'employee_name', 'earning', 'earning_amount_declared','category', 'action'];
  displayedColumnsHistory: string[] = ['sno','employee_code', 'employee_name', 'earning', 'earning_amount_declared','category','submission_status','action'];

  tdsApprovalForm: any = UntypedFormGroup;
  dataSource: MatTableDataSource<any> = <any>[];
  dataSourceHistory: MatTableDataSource<any> = <any>[];

  emptyData = new MatTableDataSource([{ empty: "row" }]);
  @ViewChild('firstPaginator') paginator!: MatPaginator;
  @ViewChild('firstPaginatorTwo') paginatorHistory!: MatPaginator;

  @ViewChild(MatSort) sort!: MatSort;
  @ViewChild('popupTemplate', { static: true }) popupTemplate!: TemplateRef<any>;

  constructor(private dialog: MatDialog, private tdsService: TdsService,
    private formBuilder: UntypedFormBuilder, private router: Router, private vcr: ViewContainerRef) { }

  financialYear: any;
  employeeList: any = [];
  employeeRecordList: any = [];
  isEnable: any = null;
  isEdit: boolean = false;
  isReject: boolean = false;
  titleName: string = '';
  rejectReason: any;
  employeeEarningHistory:any=[];
  async ngOnInit() {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.companyName = sessionStorage.getItem('companyName');
    this.tdsApprovalForm = this.formBuilder.group(
      {
        amount: ["", [Validators.required]],

      },
    );
    this.financialYear = await this.getFinancialYears();
    this.getOtherEarningRequestsForApproval();
    this.getEmployeeEarningsHistory()
  }
  getFinancialYears() {
    return new Promise((resolve) => {
      this.tdsService.getFinancialYears().subscribe((result: any) => {
        if (result.status && result.data.length) {
          resolve(result.data[0].financial_year)
        } else {
          resolve('')
        }
      });
    });
  }
  getOtherEarningRequestsForApproval() {

    this.tdsService.getEmployeeEarningsForApproval(this.financialYear).subscribe((res) => {
      if (res.status && res.data) {
        this.employeeRecordList = res.data;
        this.dataSource = new MatTableDataSource(this.employeeRecordList);
        this.dataSource.paginator = this.paginator;
        this.pageLoading = res.data.length <= 20 ? true : false;
      }
    })
  }
  approvedRequest(data: any) {

    this.isEdit == true ? this.tdsApprovalForm.controls.amount.value : this.tdsApprovalForm.controls.amount.setValue(data.approveAmount);
    let itemData = data.item.value;
    if (this.tdsApprovalForm.valid) {

      let value = {
        "peoem_id": itemData.id,
        "status_value": "Approved",
        "approved_value": this.tdsApprovalForm.controls.amount.value,
        "rejection_reason_value": null,
        "mgr_id_value": this.userSession.id,
        "companyName": this.companyName,
      }
      this.tdsService.setApproveEmployeeEarningForTds(value).subscribe((res: any) => {
        if (res.status) {

          let data = {
            "employee_id_value": itemData.emp_id,
            "financial_year_value": this.financialYear,
            "declared_amount_value": itemData.earning_amount_declared,
            "approved_amount_value": this.tdsApprovalForm.controls.amount.value
          }
          this.tdsService.setTdsAmountsWhenEarningApproved(data).subscribe((result) => {
            if (result.status) {

              this.tdsService.message('Earning amount approved successfully')
              // this.dialog.open(ReusableDialogComponent, {
              //   position: { top: `70px` },
              //   disableClose: true,
              //   data: "Data is saved successfully."
              // });
              this.closePopup()
              this.getOtherEarningRequestsForApproval();
              this.getEmployeeEarningsHistory()
            } else {
              this.dialog.open(ReusableDialogComponent, {
                position: { top: `70px` },
                disableClose: true,
                data: "Unable to save data."
              });
            }
          })

        } else {
          this.dialog.open(ReusableDialogComponent, {
            position: { top: `70px` },
            disableClose: true,
            data: "Unable to save data."
          });
        }
      });

    }
  }
  requestApprove(data: any) {
    this.isReject = true;
    this.isEdit = false;
    this.titleName = "Reject";
    this.openApproveDialog(data);
  }
  openApproveDialog(rowData: any): void {
    const dialogRef = this.dialog.open(ApproveEarningDialogComponent, {
      width: '400px',
      data: rowData,
    });

    dialogRef.afterClosed().subscribe((result) => {
      if (result) {
        if (result != undefined) {
          if (result !== true) {
            this.rejectReason = result.reason;
            this.approvedRequest(result);

          }
        }
        // Process the approved data
      }
    });
  }

  rejectedReuqest(data: any) {
    this.isEdit == true ? this.tdsApprovalForm.controls.amount.value : this.tdsApprovalForm.controls.amount.setValue(data.earning_amount_declared);
    let itemData = data;
    if (this.tdsApprovalForm.valid) {

      let value = {
        "peoem_id": data.id,
        "status_value": "Rejected",
        "approved_value": 0,
        "rejection_reason_value": this.isReject ? this.rejectReason : null,
        "mgr_id_value": this.userSession.id,
        "companyName": this.companyName,
      }
      this.tdsService.setApproveEmployeeEarningForTds(value).subscribe((res: any) => {
        if (res.status) {
          if (this.isReject) {
            let data = {
              "employee_id_value": itemData.emp_id,
              "financial_year_value": this.financialYear,
              "amount_value": itemData.earning_amount_declared
            }
            this.tdsService.setTdsAmountsWhenEarningRejected(data).subscribe((result) => {
              if (result.status) {
                this.tdsService.message('Earning amount request rejected')

                // this.dialog.open(ReusableDialogComponent, {
                //   position: { top: `70px` },
                //   disableClose: true,
                //   data: "Data is saved successfully."
                // });
                this.closePopup();
                this.getOtherEarningRequestsForApproval();
                this.getEmployeeEarningsHistory();
              } else {
                this.dialog.open(ReusableDialogComponent, {
                  position: { top: `70px` },
                  disableClose: true,
                  data: "Unable to save data."
                });
              }
            })
          }

        } else {
          this.dialog.open(ReusableDialogComponent, {
            position: { top: `70px` },
            disableClose: true,
            data: "Unable to save data."
          });
        }
      });

    }
  }
  requestReject(data: any) {
    this.isReject = true;
    this.isEdit = false;
    this.titleName = "Reason For Rejection";
    this.openDialog(data);
  }
  openDialog(data: any): void {
    const dialogRef = this.dialog.open(DialogComponent, {
      width: '600px', position: { top: `100px` },
      data: { name: this.titleName, reason: this.rejectReason, }
    });
    dialogRef.afterClosed().subscribe(result => {
      if (result != undefined) {
        if (result !== true) {
          this.rejectReason = result.reason;
          this.rejectedReuqest(data);
        }
      }
    });
  }


  showPdf(path: any, file_name: any) {
    this.tdsService.showPdf(path,file_name)
  }


  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.dataSource.data.length < 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }


  getPageSizesHistory(): number[] {
    var customPageSizeArray = [];
    if (this.dataSourceHistory.data.length < 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSourceHistory.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSourceHistory.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSourceHistory.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSourceHistory.data.length);
    return customPageSizeArray;
  }


  info: any = null;
  onlyView:boolean = false;
  addProperty(ele: any,view:boolean=false) {
    this.info = ele;
    this.vcr.clear(); // Clear previous views if any
    this.vcr.createEmbeddedView(this.popupTemplate); // Render the popup template
    this.onlyView = view
  }
  closePopup() {
    this.info = null;
    this.vcr.clear();
    this.onlyView = false;
  }


  getEmployeeEarningsHistory(){
    this.tdsService.getEmployeeEarningsHistory(this.financialYear).subscribe((results:any)=>{
      if(results && results.status){
        this.employeeEarningHistory = results.data
        this.dataSourceHistory = new MatTableDataSource(this.employeeEarningHistory)
        this.dataSourceHistory.paginator = this.paginatorHistory;
        this.pageLoadingHistory = results.data.length <= 20 ? true : false;
      }
    })
  }




  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();

    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

  applyHistoryFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSourceHistory.filter = filterValue.trim().toLowerCase();

    if (this.dataSourceHistory.paginator) {
      this.dataSourceHistory.paginator.firstPage();
    }
  }
}
