import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
@Component({
  selector: 'app-certificates-screen',
  templateUrl: './certificates-screen.component.html',
  styleUrls: ['./certificates-screen.component.scss']
})
export class CertificatesScreenComponent implements OnInit {

  list: any = [
    'Certificate got in Java course',
    'Certificate got in Angular course',
    'Certificates got in React course'
  ]
  constructor(
    private router: Router,
  ) { }

  ngOnInit(): void {
  }
  navigationToPrevScreen() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/learning/chapterScreen']));
  }
}
