import { Component, OnInit, ViewChild } from '@angular/core';
import { UntypedFormGroup, Validators, UntypedFormBuilder } from '@angular/forms';
import { Router } from '@angular/router';
import { MatDialog } from '@angular/material/dialog';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { DatePipe } from '@angular/common';
import { EmsService } from 'src/app/modules/ems/ems.service';
import { ComfirmationDialogComponent } from 'src/app/pages/comfirmation-dialog/comfirmation-dialog.component';
import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';
import { TranslateService } from '@ngx-translate/core';
export interface UserData {
  id: number;
  designation: string;
  status: string;
}
@Component({
  selector: 'app-designations',
  templateUrl: './designations.component.html',
  styleUrls: ['./designations.component.scss']
})

export class DesignationsComponent implements OnInit {
  designationForm!: UntypedFormGroup;
  designation: any;
  errorDesName: any = '';
  saveResponseMessage: any = '';
  editResponseMessage: any = '';
  issubmitted: boolean = false;
  isvalid: boolean = false;
  isView: boolean = false;
  isAdd: boolean = false;
  isdata: boolean = true;
  isEdit: boolean = true;
  isSave: boolean = false;
  valid: boolean = false;
  userSession: any;
  pipe = new DatePipe('en-US');
  msgEM94: any;
  msgEM93: any;
  msgEM96: any
  msgEM97: any;
  msgEM98: any;
  msgEM95: any;
  msgEM153: any;
  msgEM154: any;
  displayedColumns: string[] = ['sno', 'designation', 'displayname', 'status', 'Action'];
  designationData: any = [];
  arrayValue: any;
  enable: any = null;
  dataSource: MatTableDataSource<UserData>;
  btndisable: boolean = false;

  // @ViewChild(MatPaginator) paginator: MatPaginator;
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort) sort!: MatSort;
  pageLoading = true;
  companyDBName: any;
    languages = [
    { code: 'english', label: 'ENGLISH', name: 'English' },
    { code: 'arabic', label: 'ARABIC', name: 'Arabic' }
  ];
  constructor(private formBuilder: UntypedFormBuilder, private router: Router, private dialog: MatDialog,
    private LM: CompanySettingService,
    private dialogService:ReusableDialogService,
    private emsService: EmsService, private translate: TranslateService) {
    this.companyDBName = sessionStorage.getItem('companyName');
    this.getDesignation();
    this.dataSource = new MatTableDataSource(this.designationData);
  }
  messagesDataList: any = [];
  ngOnInit(): void {
    const savedLang = localStorage.getItem('lang');
   this.translate.use(savedLang || 'english');
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.getDesignation();
    this.getstatuslist();
    this.getMessages();
    this.designationForm = this.formBuilder.group(
      {
        designation: ["", [Validators.required]],
        displayName: ["", [Validators.required]],

      },
    );
    this.designationForm.get('designation')?.valueChanges.subscribe(value => {
      this.designationForm.get('displayName')?.setValue(value);
    });
  }
  validatedesignation(data: any) {
    if (this.designationData.length == 0) {
      this.valid = true;

    }

    else {
      if (this.designationData.length > 0) {
        for (let i = 0; i < this.designationData.length; i++) {
          if (data.replace(/\s{1,}/g, '').trim().toLowerCase() === this.designationData[i].designation.replace(/\s{1,}/g, '').trim().toLowerCase()) {
            this.valid = false;
            break;
          }
          else {
            this.valid = true;
          }
        }
      }
    }
  }
  validateupdatedesignation(id: any, data: any) {
    if (this.designationData.length == 0) {
      this.valid = true;
    }
    else {
      if (this.designationData.length > 0) {
        for (let i = 0; i < this.designationData.length; i++) {
          if (id != this.designationData[i].id && data.replace(/\s{1,}/g, '').trim().toLowerCase() === this.designationData[i].designation.replace(/\s{1,}/g, '').trim().toLowerCase()) {
            this.valid = false;
            break;
          }
          else {
            this.valid = true;
          }
        }
      }
    }
  }

  setdesignations() {
    if (this.designationForm.valid) {
      if (this.btndisable) {
        return;
      }
      let designame = this.designationForm.controls.designation.value;
      let display = this.designationForm.controls.displayName.value;
      let message =this.translate.instant ("Designation and Display names are the same, Are you sure you want to proceed?")
      let yesText = this.translate.instant('YES');
      let noText = this.translate.instant('NO');
      if (designame == display) {
        let dialogRef = this.dialog.open(ComfirmationDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: { message: message, YES: yesText, NO: noText },
        });
        dialogRef.afterClosed().subscribe((result) => {
          if (result == 'YES'|| result == yesText) {
            this.submit();
          } 
        });

      } else {
        this.submit();
      }
    }
  }

  submit() {
    let designationdata = {
      desig_name: this.designationForm.controls.designation.value,
      display_name: this.designationForm.controls.displayName.value,
      action_by: this.userSession.id,
      dept_id: 1,
    };
    this.btndisable = true;
    this.LM.setNewDesignationMapping(designationdata).subscribe((data: any) => {
      if (data.status && data.data[0].successstate == 0) {
        this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
        this.router.navigate(["/Admin/Designation"]));
        this.dialogService.openDialog('Designation added successfully');
        this.btndisable = false;

      } else if (data.status && data.data[0].successstate == 1) {
        this.dialogService.openDialog('Designation already exists');
        this.btndisable = false;
      } else {
        this.dialogService.openDialog('Unable to add designation. Please try again');
        this.btndisable = false;
      }

    });
  }
  status(status: any, id: any, deptname: any) {
    let data = {
      id: id,
      deptname: deptname,
      status: status,
      tableName: 'employee_designations',
      columnName: 'designationid',
      depthead: null,
      headcount: null
    }
    this.LM.designationstatus(data).subscribe((result) => {
      if (result.status) {
        let dialogRef = this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: status == 1 ? this.msgEM153 : this.msgEM154
        });
        this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
          this.router.navigate(["/Admin/Designation"]));
      } else {
        this.ngOnInit();
        this.dialogService.openDialog(this.msgEM98);
      }
    })
  }
  ngAfterViewInit() {
    this.dataSource.paginator = this.paginator;
  }

  Add() {
    this.designationForm.controls.designation.setValue('');
    this.isAdd = true;
    this.isdata = false;
  }
  cancel() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Admin/Designation"]));
    // this.designationForm.reset();
    // this.isAdd = false;
    // this.isdata = true;
    // this.getDesignation();
  }
  edit(event: any, i: any) {
    this.designationForm.controls.designation.setValue(i.designation);
    this.designationForm.controls.displayName.setValue(i.display_name);
    this.enable = i.id;
    this.isEdit = false;
    this.isSave = true;

  }
  save(event: any, id: any, desname: any, display: any, datas: any) {
    if (this.designationForm.valid) {
      if (this.btndisable) {
        return;
      }
      // this.validatedesignation(desname)
      this.validateupdatedesignation(id, desname)
      this.enable = null;
      this.isEdit = true;
      this.isSave = false;
      if (this.valid) {
        let data = {
          id: id,
          name: desname,
          displayName: display,
          created_by: datas.created_by,
          created_on: datas.created_on,
          status: datas.status,
          updated_by: this.userSession.id,
          updated_on: this.pipe.transform(new Date(), 'yyyy-MM-dd') + ' ' + this.pipe.transform(new Date(), 'HH:mm:ss'),
        }
        this.btndisable = true;
        this.LM.putDesignation(data).subscribe((data) => {
          if (data.status) {
            this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
              this.router.navigate(["/Admin/Designation"]));
            this.enable = null;
            this.getDesignation();
            this.dialogService.openDialog(this.msgEM96);
          } else {
            this.dialogService.openDialog(this.editResponseMessage);
            this.btndisable = false;
          }
        })
      }
      else {
        this.ngOnInit();
        this.dialogService.openDialog(this.msgEM95);
      }
    }
  }
  canceledit(event: any, id: any) {
    this.enable = null;
    this.isEdit = true;
    this.isSave = false;
    this.ngOnInit();
  }
  getstatuslist() {
    this.LM.getstatuslists().subscribe((result: any) => {
      if (result.status) {
        this.arrayValue = result.data;
      }
    })
  }
  getDesignation() {
    this.LM.getDesignation('designationsmaster', null, 1, 1000, this.companyDBName).subscribe((info) => {
      if (info.status && info.data.length != 0) {
        this.designationData = info.data;
        this.dataSource = new MatTableDataSource(this.designationData);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;
      }
    })
  }
  getMessages() {
    let data =
    {
      "code": null,
      "pagenumber": 1,
      "pagesize": 1000
    }
    this.emsService.getMessagesListApi(data).subscribe((result: any) => {
      if (result.status) {
        this.messagesDataList = result.data;
        this.messagesDataList.forEach((e: any) => {
          if (e.code == "EM1") {
            this.errorDesName = e.message
          } else if (e.code == "EM93") {
            this.saveResponseMessage = e.message;
            this.msgEM93 = e.message;
          } else if (e.code == "EM97") {
            this.editResponseMessage = e.message
          } else if (e.code == "EM94") {
            this.msgEM94 = e.message
          } else if (e.code == "EM96") {
            this.msgEM96 = e.message
          } else if (e.code == "EM98") {
            this.msgEM98 = e.message
          }
          else if (e.code == "EM95") {
            this.msgEM95 = e.message
          }
          else if (e.code == "EM153") {
            this.msgEM153 = e.message
          }
          else if (e.code == "EM154") {
            this.msgEM154 = e.message
          }
        })
      } else {
        this.messagesDataList = [];
      }
    })
  }
  getPageSizes(): number[] {
    var customPageSizeArray = [];

    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);

    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }

  }

  onKeyUp(value: any) {

  }
}
