import { SelectionModel } from '@angular/cdk/collections';
import { Component, OnInit, ViewChild } from '@angular/core';
import { FormArray, FormBuilder, FormControl, UntypedFormControl, UntypedFormGroup, Validators } from '@angular/forms';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { MatDatepicker } from '@angular/material/datepicker';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import moment from 'moment';
import { Moment } from 'moment';
import { UserData } from 'src/app/modules/attendance/models/EmployeeData';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { PayrollService } from '../../payroll.service';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { MatDialog } from '@angular/material/dialog';
import { Router } from '@angular/router';

export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
@Component({
  selector: 'app-arrear-distribution',
  templateUrl: './arrear-distribution.component.html',
  styleUrls: ['./arrear-distribution.component.scss'],
   providers: [
      {provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE]},
  
      {provide: MAT_DATE_FORMATS, useValue: MY_FORMATS},
    ],
})
export class ArrearDistributionComponent implements OnInit {

 @ViewChild('firstPaginator') paginator!: MatPaginator;
   @ViewChild(MatSort)
   sort!: MatSort;
   @ViewChild('secondPaginator') paginatorcompleted!: MatPaginator;
   @ViewChild(MatSort)
   sortcompleted!: MatSort;
   pageLoading = true;
   pageLoading1 = true;
   date:any;
   dates:any
   searchForm:any = UntypedFormGroup;
   arrearDistributionForm:any = UntypedFormGroup;
   max:any;
   maxdate:any;
   minDate:any= new Date('2022-01-01');
   minDates:any=new Date('2022-01-01');
   worklocationDetails:any=[];
   employeeDetails:any=[];
   filteredLocations:any=[];
   filteredEmployees:any=[];
   filteredCompanyLocations:any=[];
   companyName: any;
   searchControlforLoc = new FormControl('');
   searchControlforEmp = new FormControl('');
   searchControl = new FormControl('');
   selectedEmps:any;
   arrearAmount: FormControl[] = [];
   UserSession:any;
   dataSource1: MatTableDataSource<UserData> = <any>[];
   dataSource:MatTableDataSource<UserData> = <any>[];
   selection = new SelectionModel<any>(true, []);
   displayedColumns: string[] = [
     'select',
     'sno',
     'arrearName',
     'amount',
   ];
   displayedColumns1:string[]=[
     'sno',
     'date',
     'empcode',
     'empname',
     'arrearname',
     'arrearamount',
     'createdby',
     'status'
   ]
   branchSelected:boolean = true;
   arrearListArray:any;
   btnDisable:boolean = false;
   constructor(
     private formBuilder: FormBuilder,
     private companyService: CompanySettingService,
     private payroll:PayrollService,
     private dialog:MatDialog,
     private router: Router,
   ) { 
     
     this.companyName = sessionStorage.getItem("companyName");
     this.UserSession = JSON.parse(sessionStorage.getItem('user') ?? '')
     this.date = new UntypedFormControl(moment().subtract(1, "month"))
     this.dates = new UntypedFormControl(moment().subtract(1,"month"))
     let prevDate = new Date();
     prevDate.setDate(0)
     this.max = prevDate;
     this.maxdate = prevDate;
     this.searchForm = this.formBuilder.group({
       companylocation : ['',Validators.required],
       employeeName : ['',Validators.required],
       fromDate:[prevDate],
       arrersName: this.formBuilder.array([])
     }); 
     this.arrearDistributionForm = this.formBuilder.group({
       companylocation : ['',Validators.required],
       fromDateC:[prevDate],
     }); 
 
 
   }
   selectedArrearList: any[] = [];
   totalArrearAmount:any;
   ngOnInit(): void {  
     this.getWorkLocation();
     this.searchControlforLoc.valueChanges.subscribe(searchText => {
       this.filterLocations(searchText);
     }); 
     this.searchControl.valueChanges.subscribe(searchText => {
       this.filterCompanyLocations(searchText);
     }); 
     this.searchControlforEmp.valueChanges.subscribe(searchText => {
      this.filterEmployeeList(searchText);
    });
   }
 
   setMonthAndYear(normalizedMonthAndYear: Moment, datepicker: MatDatepicker<Moment>) {
     const ctrlValue = this.date.value!;
     ctrlValue.month(normalizedMonthAndYear.month());
     ctrlValue.year(normalizedMonthAndYear.year());
     this.date.setValue(ctrlValue); 
     datepicker.close();
     this.searchForm.controls.companylocation.setValue('')
     this.dataSource.data = [];
     this.searchForm.controls.employeeName.setValue('')
   }
 
   setMonthAndYear1(normalizedMonthAndYear:Moment, datepicker:MatDatepicker<Moment>){
     const ctrlValue = this.date.value!;
     ctrlValue.month(normalizedMonthAndYear.month());
     ctrlValue.year(normalizedMonthAndYear.year());
     this.dates.setValue(ctrlValue); 
     datepicker.close();
     this.arrearDistributionForm.controls.companylocation.setValue('')
     this.dataSource1.data = []
   }
 
  
 
   getWorkLocation() {
     this.companyService.getactiveWorkLocation({ id: null, companyName: this.companyName }).subscribe((result) => {
       this.worklocationDetails = result.data;
       this.filteredLocations = this.worklocationDetails;
       this.filteredCompanyLocations = this.worklocationDetails;
     })
   }
 
   filterLocations(searchText: any) {
     this.filteredLocations = this.worklocationDetails.filter((val: any) =>
       val.cityname.toLowerCase().includes(searchText.toLowerCase()) || val.location.toLowerCase().includes(searchText.toLowerCase())
     );
   }

   filterEmployeeList(searchText: any) {
    this.filteredEmployees = this.employeeDetails.filter((val: any) =>
      val.employeeCode.toLowerCase().includes(searchText.toLowerCase()) || val.employeeName.toLowerCase().includes(searchText.toLowerCase())
    );
  }
   filterCompanyLocations(searchText: any) {
     this.filteredCompanyLocations = this.worklocationDetails.filter((val: any) =>
       val.cityname.toLowerCase().includes(searchText.toLowerCase()) || val.location.toLowerCase().includes(searchText.toLowerCase())
     );
   }
   getEmployeeList() {
    this.searchForm.controls.employeeName.setValue('')
    let payload ={
      'year': this.date.value._d.getFullYear(),
      'month': this.date.value._d.getMonth() + 1,
      'locationId':this.searchForm.controls.companylocation.value,
      'companyName':this.companyName
    }
    this.payroll.getEmployeesForArrears(payload).subscribe((result) => {
      this.employeeDetails = result.data;
      this.filteredEmployees = this.employeeDetails;
      // this.filteredCompanyLocations = this.worklocationDetails;
    })
  }
   getArrearsList(){
       let data = [];
       this.payroll.getArrearNames().subscribe((res:any)=>{
       data = res.data;
       this.dataSource =  new MatTableDataSource(data)
       this.dataSource.paginator = this.paginator;
       this.dataSource.sort = this.sort;
       this.pageLoading = false;
       if(this.dataSource != undefined){
         this.dataSource.data.forEach(() => {
           this.arrearAmount.push(new FormControl(''));
         });
         this.initArrearFormArray();
       }
     })
   }
   initArrearFormArray() {
     this.arrearListArray = this.searchForm.get('arrersName') as FormArray; 
     this.arrearListArray.clear(); 
     if (this.dataSource?.data) {
       this.dataSource.data.forEach((value :any)=> {
       this.arrearListArray.push(this.formBuilder.group({
        arrearId: value.arrearId,
        arrearName: value.arrearName,
         arrearAmount:  ['', [Validators.required, Validators.min(0)]]
       }));
     });
   }
 }

 isRowSelected(row: any): boolean {
   return this.selectedArrearList.some(selected => selected.arrearId === row.arrearId);
 }
 
 toggleRowSelection(row: any): void {
   const index = this.selectedArrearList.findIndex(selected => selected.arrearId === row.arrearId);
   if (index === -1) {
     this.selectedArrearList.push(row);
   } else {
     this.selectedArrearList.splice(index, 1);
   }
   this.selection.toggle(row);
 }
 
 getArrearAmountControl(arrearId: any): FormControl | any {
   const arrearFormArray = this.searchForm.get('arrersName') as FormArray;
   const formGroup = arrearFormArray.controls.find(control => 
     control.get('arrearId')?.value === arrearId
   );
   this.branchSelected=false;
   return formGroup ? (formGroup.get('arrearAmount') as FormControl) : null;
 }
 
 masterToggle() {
   // if there is a selection then clear that selection
   if (this.isSomeSelected()) {
     this.selection.clear();
     this.selectedArrearList = [];
   } else {
     this.isAllSelected()
       ? this.selection.clear()
       : this.dataSource.data.forEach((row:any) => this.selection.select(row));
       this.selectedArrearList = this.dataSource.data.slice();
   }
 
 }
 
   isSomeSelected() {
     return this.selection.selected.length > 0;
   }
 
   isAllSelected() {
     const numSelected = this.selection.selected.length;
     const numRows = this.dataSource.data.length;
     return numSelected === numRows;
   }
 
   isFormValid(): boolean {
     if (!this.searchForm.get('companylocation')?.valid || !this.searchForm.get('fromDate')?.valid) {
       return false;
     }
     const arrearFormArray = this.searchForm.get('arrersName') as FormArray;
 
     if (this.selectedArrearList.length === 0) return false;
   
     for (let selected of this.selectedArrearList) {
       const formGroup = arrearFormArray.controls.find(control => 
         control.get('arrearId')?.value === selected.arrearId
       );
       if (formGroup) {
         const arrearAmountControl = formGroup.get('arrearAmount');
         if (!arrearAmountControl || 
             arrearAmountControl.invalid || 
             isNaN(Number(arrearAmountControl.value))) {
           return false;
         }
       } else {
         return false;
       }
     }
     return true;
     }
 
 
   submit(){
     if(this.selectedArrearList.length > 0){
       if(this.btnDisable){
         return;
       }
  
       if(this.isFormValid()){
         const arrearFormArray = this.searchForm.get('arrersName') as FormArray;
         const arrearData = this.selectedArrearList.map(selected => {
           const formGroup = arrearFormArray.controls.find(control => 
             control.get('arrearId')?.value === selected.arrearId
           );
           return {
            arrear_id: selected.arrearId,
            arrear_amount: Number(formGroup?.get('arrearAmount')?.value)
           };
         });
         let totalAmount = 0;
         for (const arrear of arrearData) {
           totalAmount += arrear.arrear_amount;
         }
         let obj = {
          employee_id_value:this.searchForm.controls.employeeName.value,
           year_value: this.date.value._d.getFullYear(),
           month_value:this.date.value._d.getMonth() + 1 ,
           amount_value:totalAmount,
           arrear_value: JSON.stringify(arrearData),
           user_id_value:this.UserSession.id,
           companyName:this.companyName
          }
          this.btnDisable=true;
          this.payroll.setEmployeeMonthlyArrears(obj).subscribe((res:any)=>{
            if(res.status){
              if(res.data[0].statusCode == 0){
                this.dialog.open(ReusableDialogComponent, {
                  position: { top: `70px` },
                  disableClose: true,
                  data: 'Arrear amount is submitted successfully.',
                });
                this.btnDisable=false;
                this.refreshScreen();
             
               } else if(res.data[0].statusCode == 1){
                 this.dialog.open(ReusableDialogComponent, {
                   position: { top: `70px` },
                   disableClose: true,
                   data: 'Arrear amount is updated successfully.',
                 });
                 this.btnDisable=false;
                 this.refreshScreen();
               }
            } else {
              this.dialog.open(ReusableDialogComponent, {
                position: { top: `70px` },
                disableClose: true,
                data: 'Unable to submit the data. Please try again.',
              });
              this.btnDisable=false;
            }

           })
       }else{
         this.dialog.open(ReusableDialogComponent, {
           position: { top: `70px` },
           disableClose: true,
           data: 'Please enter arrear amount.',
         });
         return;
       }
       
     }else{
       this.dialog.open(ReusableDialogComponent, {
         position: { top: `70px` },
         disableClose: true,
         data: 'Select atleast one arrear name.',
       });
     }
   }
 
 
 
 
   cancel(){
     this.refreshScreen()
   }
 
   getArrearDistributionList(){
     let data ={
       location_id_value:this.arrearDistributionForm.controls.companylocation.value,
       year_value: this.date.value._d.getFullYear(),
       month_value:this.date.value._d.getMonth() + 1,
       companyName: this.companyName
     }
     this.payroll.getEmployeeArrearDetails(data).subscribe((res:any)=>{
       this.dataSource1 = new MatTableDataSource(res.data);
       this.dataSource1.paginator = this.paginatorcompleted;
       this.dataSource1.sort = this.sortcompleted;
       this.pageLoading1 = false;
     })
   }
 
   refreshScreen(){
     this.router.navigateByUrl('/', { skipLocationChange: true })
       .then(() => this.router.navigate(['/Payroll/arrearsDistribution']));
   }
   getPageSizes1(){
     var customPageSizeArray = [];
  
     if (this.dataSource1.filteredData.length < 5) {
       customPageSizeArray.push(5);
     }
     if (this.dataSource1.filteredData.length > 5) {
       customPageSizeArray.push(5);
     }
     if (this.dataSource1.filteredData.length > 10) {
       customPageSizeArray.push(10);
     }
     if (this.dataSource1.filteredData.length > 20) {
       customPageSizeArray.push(20);
     }
     customPageSizeArray.push(this.dataSource1.filteredData.length);
     return customPageSizeArray;
     
   }
   applyFilter(event: Event) {
     const filterValue = (event.target as HTMLInputElement).value;
     this.dataSource1.filter = filterValue.trim().toLowerCase();
     if (this.dataSource1.paginator) {
       this.dataSource1.paginator.firstPage();
     }
   }
 
   getPageSizes(): number[] {
     var customPageSizeArray = [];
     if (this.dataSource.data.length < 5) {
       customPageSizeArray.push(5);
     }
     if (this.dataSource.data.length > 5) {
       customPageSizeArray.push(5);
     }
     if (this.dataSource.data.length > 10) {
       customPageSizeArray.push(10);
     }
     if (this.dataSource.data.length > 20) {
       customPageSizeArray.push(20);
     }
     customPageSizeArray.push(this.dataSource.data.length);
     return customPageSizeArray;
   }
}
