import { Component, OnInit, ViewChild } from '@angular/core';
import { UntypedFormGroup, Validators, UntypedFormBuilder } from '@angular/forms';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { MatDialog } from '@angular/material/dialog';
import { Router } from '@angular/router';
import { AdminService } from '../../admin.service';

import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';

@Component({
  selector: 'app-exit-messages',
  templateUrl: './exit-messages.component.html',
  styleUrls: ['./exit-messages.component.scss']
})
export class ExitMessagesComponent implements OnInit {
  errorMessagesForm!: UntypedFormGroup;
  displayedColumns: string[] = ['sno','code','screenName','message','action'];
  dataSource!: MatTableDataSource<any>;
  isEdit:boolean=true;
  isSave:boolean=false;
  enable:any=null;
  valid: boolean = false;
 
  messagesDataList:any=[];

  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  pageLoading = true;
  requiredField: any;
  dataUpdate: any;
  dataNotUpdate: any;
  recordExist: any;
  userSession:any;

  constructor(private formBuilder: UntypedFormBuilder,private router: Router, private dialog: MatDialog,
    private adminService: AdminService,
    private dialogService:ReusableDialogService,) {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');}
 

  ngOnInit(): void {
    this.getMessagesList();
    this.errorMessagesForm=this.formBuilder.group(
      {
        code:[],
        message:["",Validators.required],
     },
    );
  }

  submit(event: any, rcode: any, rmessage: any, screenname:any) {
    if (this.errorMessagesForm.valid) {
      if (rmessage.length == 0) {
        this.dialogService.openDialog(this.requiredField);
       }
      else {
        const toSelect = this.messagesDataList.find((res: { message: string;code:string }) => res.message.trim().toLowerCase() == rmessage.toLowerCase()
        && res.code != rcode);
        if(toSelect!=undefined){
          this.dialogService.openDialog(this.recordExist);
       }
        else{
          this.save(rcode,rmessage,screenname)
        }
      }
    }
  }

  save(rcode: any, rmessage: any, screenname:any) {
    let dataList =[
      {
       "code": rcode,
       "message": rmessage,
       "screenname": screenname,
       "action_by":this.userSession.id
      }]
       this.adminService.updateExitMessagesData(dataList).subscribe((res: any) => {
      if (res.status) {
        let resMessage: any;
        if (res.data == "dataSaved") {
          resMessage = this.dataUpdate
        } else {
          resMessage = this.dataNotUpdate
        }
          this.dialogService.openDialog(resMessage);
          this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
          this.router.navigate(["/Admin/exitmessage"]));
          this.getMessagesList();
        } else {
          this.dialogService.openDialog( this.dataNotUpdate);
          this.getMessagesList();
        }
      }

      )
    }
    edit(w: any, res: any) {

      this.errorMessagesForm.controls.message.setValue(res.message);
      this.enable = res.id;
      this.isEdit=false;
      this.isSave=true;
    
    }
    canceledit(event:any,id:any){
      this.enable = null;
      this.isEdit=true;
      this.isSave=false;
      this.ngOnInit();
    
    }
    getMessagesList() {
      let data =
       {
         "code": null,
         "pagenumber":1,
         "pagesize":1000
     }
     this.adminService.getExitMessagesList(data).subscribe((res:any)=>{
       if(res.status) {
         this.messagesDataList = res.data;
         this.messagesDataList.forEach((e: any) => {
           if (e.code == "EX1") {
            this.requiredField = e.message
           } else if (e.code == "EX8") {
             this.recordExist =e.message
           }else if (e.code == "EX9") {
             this.dataUpdate =e.message
           } else if (e.code == "EX10") {
             this.dataNotUpdate =e.message
           }
         })
         this.dataSource = new MatTableDataSource(this.messagesDataList);
         this.dataSource.paginator = this.paginator;
         this.dataSource.sort = this.sort;
         this.pageLoading=false;
       } else {
         this.messagesDataList = [];
         this.dataSource = new MatTableDataSource(this.messagesDataList);
         this.dataSource.paginator = this.paginator;
         this.dataSource.sort = this.sort;
       }
    
     })
    }
    applyFilter(event: Event) {
      const filterValue = (event.target as HTMLInputElement).value;
      this.dataSource.filter = filterValue.trim().toLowerCase();
       if (this.dataSource.paginator) {
         this.dataSource.paginator.firstPage();
      }
    }
    getPageSizes(): number[] {
      var customPageSizeArray = [];
      
      if (this.dataSource.data.length > 5) {
        customPageSizeArray.push(5);
      }
      if (this.dataSource.data.length > 10) {
        customPageSizeArray.push(10);
      }
      if (this.dataSource.data.length > 20) {
        customPageSizeArray.push(20);
       
      }
      customPageSizeArray.push(this.dataSource.data.length);
      return customPageSizeArray;
    }

}
