import { Component, Inject } from '@angular/core';
import { MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';

@Component({
  selector: 'app-designation-confirm-dialog',
  templateUrl: './designation-confirm-dialog.component.html',
  styleUrls: ['./designation-confirm-dialog.component.scss']
})
export class DesignationConfirmDialogComponent {
  constructor(
    public dialogRef: MatDialogRef<DesignationConfirmDialogComponent>,
    @Inject(MAT_DIALOG_DATA) public data: { title: string; message: string; confirmText?: string;  
      cancelText?: string;}  
    
  ) {}

  onYes(): void {
    this.dialogRef.close(true);  
  }

  onNo(): void {
    this.dialogRef.close(false);  
  }
}


