  getActiveEmployeeDashboard() {
    var jsonString = sessionStorage.getItem('activeModule');
    if (jsonString && jsonString.toString().length > 0) {
      var activeModule: any = JSON.parse(jsonString);
      activeModule.module.children.forEach((c: any) => {
        if (c.displayName === 'Employee') {
          c.subChildren.forEach((e: any) => {
            if (e.parentrole === 'Employee' && e.screen_name === 'Employee Dashboard')
              this.userDashboard = e.routename;
          });
        }
      });
    }
  }
  filterLeaves(searchText: any) {
    this.filteredLeaveTypeData = this.leavesTypeData.filter((val: any) =>
      val.display_name.toLowerCase().includes(searchText.toLowerCase()));
    if (this.filteredLeaveTypeData.length <= 0) {
      this.searchControl.setValue('');
    }
  }

  getSelectedModules() {
    if (sessionStorage.getItem('moduleData') && sessionStorage.getItem('moduleData')?.length) {
      this.selected_modules = sessionStorage.getItem('moduleData');
      try {
        this.selected_modules = JSON.parse(this.selected_modules);
      } catch (e) {
        this.selected_modules = [];
      }
      if (this.selected_modules.length) {
        this.selected_modules.forEach((e: any) => {
          if (e.id == 2) {
            this.isLeaveModule = true;
          }
        });
      }
    }

  }
  onchangeLeave(event: any) {
    this.isBereavement = event.is_b === 1 ? true : false
    this.isCompOffLeave = event.is_comp === 1 ? true : false
    this.isEvent = event.is_event === 1 ? true : false
    this.isSickLeave = event.is_sick_leave === 1 ? true : false
    if (this.isEvent) {
      this.getMaxCountPerTermValue();
    }

  }
