interface Resource {
  resourceType: 'link' | 'document';

  link?: string;
  file?: File;
  linkName?: string; // ← new

  docUrl?: string; // The actual blob/object URL or a server URL
  docName?: string; // The displayed file name

  // Editing states
  editingResource?: boolean; // Are we in the "edit resource" mode
  replaceMode?: boolean; // If user is replacing the document

  // Temp placeholders for new doc if user replaces
  tempNewDocUrl?: string;
  tempNewDocName?: string;
}

interface Section {
  section_id?: number;

  title: string;
  showContentOptions: boolean;
  selectedContentType?: string;
  videoUrl?: string;
  documentUrl?: string;
  sanitizedDocumentUrl?: SafeResourceUrl;

  editingDescription?: boolean;
  description?: string;
  tempDescription?: string;

  textContent?: string;
  documentFile?: File;
  file?: File;

  questionsDraft?: QuestionItem[];

  // Resource flow
  showResourceForm?: boolean;
  selectedResourceTab?: number;
  resources: Resource[]; // Not optional => always an array

  // Temp fields (always defined as strings)
  tempLink: string;
  tempLinkName: string; // ← new

  tempDocumentUrl: string;
  tempDocumentName: string;

  isManualQuiz?: number; // 1 = manual, 0 = AI
}

interface Module {
  id: number | undefined;
  module_id?: number;
  description: any;
  title: string;
  sections: Section[];
  _savedModuleId?: number;
}

interface QuestionItem {
  question: string;
  A: string;
  B: string;
  C: string;
  D: string;
  answer: 'A' | 'B' | 'C' | 'D';
  content?: string; // optional Data URL preview
  contentFile?: File | null; // the actual file to send
}

