  dueDate: Date | null = null;

  branches: any[] = [];
  departments: any[] = [];
  managers: any[] = [];
  employees: any[] = [];
  filteredEmployees: any[] = [];

  // ============================================================
  // CHANGE 1: Add reviewers and approvers arrays
  // ============================================================
  reviewers: any[] = [];
  approvers: any[] = [];
