  selectedBranchIds: number[] = [];
  selectedDepartmentIds: number[] = [];
  selectedManagerIds: number[] = [];
  selectedEmployeeIds: number[] = [];
  assigningCourseId!: number;
  successDialogRef: any;
  dialogSelectedManagerIds: number[] = [];
  dialogSelectedEmployeeIds: number[] = [];

  dialogDepartments: any[] = [];
  dialogManagers: any[] = [];
  dialogEmployees: any[] = [];
  filteredDialogEmployees: any[] = [];

  dialogSelectedDepartmentIds: number[] = [];

  readOnlyContent = false;
  viewCourseID!: number;
  courses: any[] = [];

  separatorKeysCodes: number[] = [ENTER, COMMA];
  tagCtrl = new FormControl();
  suggestedTags: string[] = [];
  selectedTags: string[] = [];
  filteredTags!: Observable<string[]>;

  isGeneratingContent = false;
  isGeneratingTags = false;
  isGeneratingPrerequisites = false;
