  approvalForm: FormGroup;
  // ============================================================

  modules: Module[] = [];
  private _moduleIndexToDelete: number | null = null;
  private _sectionToDelete: {
    moduleIndex: number;
    sectionIndex: number;
  } | null = null;

  generatedImageUrl: SafeUrl | null = null;

  isModuleEdit = false;
  editingModuleIndex: number | null = null;

  isSectionEdit = false;
