  @ViewChild('assignDialog') assignDialog!: TemplateRef<any>;
  @ViewChild('assignSuccessDialog') assignSuccessDialog!: TemplateRef<any>;
  @ViewChild('validationErrorDialog') validationErrorDialog!: TemplateRef<any>;
  @ViewChild('addSectionDialog') addSectionDialog!: TemplateRef<any>;
  @ViewChild('addModuleDialog') addModuleDialog!: TemplateRef<any>;
