  async onSelectFile(event: any, section: Section): Promise<void> {
    const file: File | undefined = event.target?.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('video')) {
      alert('Please select a valid video file.');
      return;
    }

    if (file.size > this.MAX_FILE_BYTES) {
      event.target.value = '';
      this.openFileSizeError();
      return;
    }

    const duration = await this.getVideoDuration(file);
    if (duration > this.MAX_VIDEO_SECONDS) {
      event.target.value = '';
      this.openVideoDurationError();
      return;
    }

    section.file = file;
    const reader = new FileReader();
    reader.onload = () => {
      section.videoUrl = reader.result as string;
      section.showContentOptions = false;
      this.cdRef.detectChanges();
    };
    reader.readAsDataURL(file);
  }

  onSelectDocument(event: any, section: Section): void {
    const file: File | undefined = event.target?.files?.[0];
    if (!file) return;

    if (file.size > this.MAX_FILE_BYTES) {
      event.target.value = '';
      this.openFileSizeError();
      return;
    }

    const allowedExtensions = ['pdf', 'doc', 'docx', 'txt'];
    const ext = file.name.split('.').pop()?.toLowerCase();
    if (!ext || !allowedExtensions.includes(ext)) {
      alert('Please select a valid document file.');
      return;
    }

    const objectUrl = URL.createObjectURL(file);
    section.documentUrl = objectUrl;
    section.sanitizedDocumentUrl =
      this.sanitizer.bypassSecurityTrustResourceUrl(objectUrl);
    section.file = file;
    section.showContentOptions = false;
  }

