  initQuillEditor(moduleIndex: number, sectionIndex: number): void {
    const editorId = `quill-editor-${moduleIndex}-${sectionIndex}`;
    const key = `${moduleIndex}-${sectionIndex}`;
    if (this.quillEditors.has(key)) return;

    const container = document.getElementById(editorId);
    if (container) {
      const quill = new Quill(`#${editorId}`, {
        theme: 'snow',
        modules: {
          toolbar: [
            ['bold', 'italic', 'underline'],
            [{ list: 'ordered' }, { list: 'bullet' }],
            ['clean'],
          ],
        },
      });

      const section = this.modules[moduleIndex].sections[sectionIndex];
      if (section.textContent) {
        quill.root.innerHTML = section.textContent;
      }

      quill.on('text-change', () => {
        section.textContent = quill.root.innerHTML;
      });
      this.quillEditors.set(key, quill);
    }
  }

  fillSectionTextContent(
    section: Section,
    moduleIndex: number,
    sectionIndex: number,
  ): void {
    if (this.isGeneratingSectionText) return;

    this.isGeneratingSectionText = true;
    const key = `${moduleIndex}-${sectionIndex}`;

    this.learnService
      .generateSectionNotes({
        course_name: this.courseForm.get('courseTitle')?.value,
        module_name: this.modules[moduleIndex]?.title,
        section_name: section.title,
      })
      .subscribe({
        next: (res: any) => {
          const generatedContent = res.description || '';
          section.textContent = generatedContent;

          setTimeout(() => {
            let quill = this.quillEditors.get(key);
            if (!quill) {
              this.initQuillEditor(moduleIndex, sectionIndex);
              quill = this.quillEditors.get(key);
            }

            if (quill && generatedContent) {
              quill.setContents([]);
              quill.clipboard.dangerouslyPasteHTML(generatedContent);
              section.textContent = quill.root.innerHTML;
            }

            this.isGeneratingSectionText = false;
            this.cdRef.detectChanges();
          }, 200);
        },
        error: () => (this.isGeneratingSectionText = false),
      });
  }

