import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { MainComponent } from 'src/app/pages/main/main.component';
import { ClaimsReimbursementTypesComponent } from './pages/claims-reimbursement-types/claims-reimbursement-types.component';
import { ClaimsUserRequestComponent } from './pages/claims-user-request/claims-user-request.component';
import { ClaimsApprovalsComponent } from './pages/claims-approvals/claims-approvals.component';
import { ClaimsEmployeeWiseDetailedComponent } from './pages/claims-employee-wise-detailed/claims-employee-wise-detailed.component';
import { ClaimsDetailedReportComponent } from './pages/claims-detailed-report/claims-detailed-report.component';
import { CrmTravelApprovalsComponent } from 'src/app/modules/crm/pages/crm-travel-approvals/crm-travel-approvals.component';
import { ClaimsPaymentReceiptComponent } from './pages/claims-payment-receipt/claims-payment-receipt.component';
import { ClaimsSummaryReportComponent } from './pages/claims-summary-report/claims-summary-report.component';
import { ClaimsEmployeeRequestComponent } from './pages/claims-employee-request/claims-employee-request.component';
import { ClaimBillApprovalsComponent } from './pages/claim-bill-approvals/claim-bill-approvals.component';
import { ClaimsDashboardComponent } from './pages/claims-dashboard/claims-dashboard.component';
const routes: Routes = [
  {
    path: '', component: MainComponent,
    children: [
      { path: 'ClaimsReimbursementTypes', component: ClaimsReimbursementTypesComponent},
      { path: 'UserClaimRequest', component: ClaimsEmployeeRequestComponent},
     // { path: 'Manager/ClaimsApprovals', component: ClaimsApprovalsComponent},
      { path: 'ClaimsEmployeeWiseDetailedReport', component: ClaimsEmployeeWiseDetailedComponent},
      { path: 'ClaimsDetailedReport', component: ClaimsDetailedReportComponent},
      //{ path: 'FInance/ClaimsApprovals', component: ClaimsApprovalsComponent},
       {path: 'Finance/CrmTravelApprovals', component: CrmTravelApprovalsComponent},
      { path: 'ClaimsPaymentReceipt', component: ClaimsPaymentReceiptComponent},
      { path: 'ClaimsSummaryReport', component: ClaimsSummaryReportComponent},
      { path: 'Manager/ClaimsApprovals', component: ClaimBillApprovalsComponent},
      { path: 'Finance/ClaimsApprovals', component: ClaimBillApprovalsComponent},
      { path: 'Manager/ClaimsDashboard', component: ClaimsDashboardComponent},
      { path: 'Finance/ClaimsDashboard', component: ClaimsDashboardComponent},
      { path: 'Employee/ClaimsDashboard', component: ClaimsDashboardComponent},

    ]
  }];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class ClaimsRoutingModule { }
