  // ------Leave Balance Report-----

  getHeaders() {
    let headers: string[] = [];
    if (this.dataForLeaveBalanceReport) {
      this.dataForLeaveBalanceReport.forEach((value: any) => {
        Object.keys(value).forEach((key) => {
          if (!headers.find((header) => header == key)) {
            headers.push(key);
          }
        });
      });
    }
    return headers;
  }

