import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';

@Component({
  selector: 'app-course-list',
  templateUrl: './course-list.component.html',
  styleUrls: ['./course-list.component.scss']
})
export class CourseListComponent implements OnInit {

  list: any = ['Angular Course Online with Certificates',
    'Java Online with Certificates',
    'MySQL Online with Certificates',
    'React Online with Certificates',
    'Node JS Online with Certificates',
    'Front-end Online with Certificates',
    'Full-Stack Online with Certificates',
    'Backend Online with Certificates',
    'UI/UX Online with Certificates',]
  constructor(
    private router: Router,
  ) { }

  ngOnInit(): void {
  }

  submit() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/learning/chapterScreen']));
  }
  navigationToPrevScreen() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/learning/emp_dashboard']));
  }
}
