import { DatePipe } from '@angular/common';
import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, UntypedFormControl, UntypedFormGroup, Validators } from '@angular/forms';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { MatDatepicker, MatDatepickerInputEvent } from '@angular/material/datepicker';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { Router } from '@angular/router';
import * as XLSX from 'xlsx';
import { ReportsService } from '../../reports.service';
import * as _moment from 'moment';
import { Moment } from 'moment';
import { MatDialog } from '@angular/material/dialog';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { PdfHeaderService } from 'src/app/services/pdf-header-service/pdf-header.service';
import { MatRadioChange } from '@angular/material/radio';
const moment = _moment;

export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
@Component({
  selector: 'app-extra-days-penalty-report-manager',
  templateUrl: './extra-days-penalty-report-manager.component.html',
  styleUrls: ['./extra-days-penalty-report-manager.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class ExtraDaysPenaltyReportManagerComponent implements OnInit {
  @ViewChild('table') table!: ElementRef;
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort) sort!: MatSort;

  searchForm: any = UntypedFormGroup;
  employeeList: any = [];
  arrayList: any = [];
  minFromDate: Date | undefined;
  maxFromDate: Date | undefined;
  minToDate: Date | null;
  maxToDate: Date | undefined;
  currentDate: Date = new Date();
  dataSource: MatTableDataSource<any> = <any>[];
  dataSource2: MatTableDataSource<any> = <any>[];
  displayedColumns: string[] = ['sno', 'date', 'day', 'empid', 'empname', 'extradayscount', 'ed_descr'];
  displayedColumns2: string[] = ['sno', 'date', 'day', 'empid', 'empname', 'penalty', 'penalty_descr'];
  pageLoading = true;
  pageLoading2 = true;
  userSession: any;
  isLoading = false;
  companyDBName: any;
  date: any;
  minDate: any = new Date('2000-01-01');
  max = this.getEndOfMonth(new Date());
  reportType: any;
  extradaysReport = true;
  isHRManagerReport = false;
  isManagerReport = false;
  currentUrl: any;
  setMonthAndYear(normalizedMonthAndYear: Moment, datepicker: MatDatepicker<Moment>) {
    const ctrlValue = this.date.value!;
    ctrlValue.month(normalizedMonthAndYear.month());
    ctrlValue.year(normalizedMonthAndYear.year());
    this.date.setValue(ctrlValue);
    datepicker.close();
  }

  constructor(
    private formBuilder: FormBuilder,
    private router: Router,
    public datePipe: DatePipe,
    private reportsService: ReportsService,
    public dialog: MatDialog,
    private pdfService: PdfHeaderService,
  ) {
    this.currentUrl = this.router.url;
    if(this.currentUrl == '/Attendance/extradaysreport-manager' ){
      this.isManagerReport =true;
      this.isHRManagerReport =false;
    } else{
      this.isHRManagerReport =true;
      this.isManagerReport = false;
    }
    this.minFromDate = new Date();
    this.minFromDate.setDate(this.currentDate.getDate() - 90);
    this.maxFromDate = new Date();
    this.minToDate = new Date();
    this.minToDate.setDate(this.currentDate.getDate() - 90);
    this.maxToDate = new Date();

  }

  ngOnInit(): void {
    this.searchForm = this.formBuilder.group({
      fromDate: [new Date(), Validators.required],
      search: [''],
    });

    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    this.companyDBName = sessionStorage.getItem("companyName") ? sessionStorage.getItem("companyName") : null;
    this.date = new UntypedFormControl(moment())
    let prevDate = new Date();
    prevDate.setDate(0);
    this.reportType = "extradays";
    this.getReportList();
  }

  getEndOfMonth(date: Date): Date {
    const year = date.getFullYear();
    const month = date.getMonth();
    return new Date(year, month + 1, 0);
  }

  fromDateChange(type: string, event: MatDatepickerInputEvent<Date>) {
    this.minToDate = event.value;
    if (event.value !== null) {
      this.maxToDate = new Date(
      );
    }
  }
  radioChange(event: MatRadioChange) {
    if (event.value == 1) {
      this.reportType = "extradays";
      this.extradaysReport = true;
      this.getReportList();
      this.searchForm.controls.search.setValue('');

    } else if (event.value == 2) {
      this.reportType = "penalty";
      this.extradaysReport = false;
      this.getReportList();
      this.searchForm.controls.search.setValue('');
    }
  }
  getReportList() {
    let data = {
      'manager_id': this.isManagerReport ? this.userSession.id: null,
      'emp_id': null,
      'year': (this.date.value._d).getFullYear(),
      'month': (this.date.value._d).getMonth() + 1,
      "type": this.reportType
    }
    this.reportsService.getExtradaysAndPenaltiesReport(data).subscribe((res: any) => {
      if (res.status) {
        this.arrayList = [];
        this.arrayList = res.data;
        if (this.extradaysReport) {

          this.dataSource = new MatTableDataSource(res.data);
          this.dataSource.paginator = this.paginator;
          this.dataSource.sort = this.sort;
          this.pageLoading = false;

        } else {
          this.dataSource2 = new MatTableDataSource(res.data);
          this.dataSource2.paginator = this.paginator;
          this.dataSource2.sort = this.sort;
          this.pageLoading2 = false;
        }

      }
    })
  }

  resetform() {
    if(this.isManagerReport){
      this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
        this.router.navigate(["/Attendance/extradaysreport-manager"]));
    } else {
      this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Attendance/extradaysreport-hrmanager"]));
    }

  }

  getPageSizes(): number[] {

    var customPageSizeArray = [];
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    if(this.extradaysReport){
      this.dataSource.filter = filterValue.trim().toLowerCase();
      if (this.dataSource.paginator) {
        this.dataSource.paginator.firstPage();
      }
    } else {
    this.dataSource2.filter = filterValue.trim().toLowerCase();
    if (this.dataSource2.paginator) {
      this.dataSource2.paginator.firstPage();
    }
  }
  }

  generatePDF() {

    if (this.extradaysReport) {
      const doc = new jsPDF();
      const reportName = 'Extra Days Report';
      let manager = '';
      let locationName = '';
      let reportDate = this.datePipe.transform(this.date.value._d, "MMMM-YYYY");
      const headerHeight = 33;
      const tableData = this.arrayList.map((emp: {
        edate: any;
        dayname: any;
        empcode: any;
        empname: any;
        count: any;
        description: any;

      }, index: number) => [

          index + 1,
          this.datePipe.transform(emp.edate, "dd-MM-yyyy"),
          emp.dayname,
          emp.empcode,
          emp.empname,
          parseFloat(emp.count).toFixed(1),
          emp.description,

        ]);
      autoTable(doc, {
        head: [['S. No.', 'Date', 'Day', 'Emp. ID', 'Emp. Name', 'Extra Days Count', 'Description']],
        body: tableData,
        startY: headerHeight,
        styles: { fontSize: 10 },
        headStyles: { fontSize: 11 },
        margin: { top: headerHeight },
        didDrawPage: (data) => {
          this.pdfService.generatePDFHeader(doc, reportName, locationName, manager, reportDate, false,false);
          doc.setFontSize(10);
          doc.setTextColor(40);
        }
      });
      doc.save('Extra_Days_Report.pdf');

    } else {

      const doc = new jsPDF();
      const reportName = 'Penalty Days Report';
      let manager = '';
      let locationName = '';
      let reportDate = this.datePipe.transform(this.date.value._d, "MMMM-YYYY");
      const headerHeight = 33;
      const tableData = this.arrayList.map((emp: {
        edate: any;
        dayname: any;
        empcode: any;
        empname: any;
        count: any;
        description: any;

      }, index: number) => [

          index + 1,
          this.datePipe.transform(emp.edate, "dd-MM-yyyy"),
          emp.dayname,
          emp.empcode,
          emp.empname,
          parseFloat(emp.count).toFixed(1),
          emp.description,

        ]);
      autoTable(doc, {
        head: [['S. No.', 'Date', 'Day', 'Emp. ID', 'Emp. Name', 'Penalty Days Count', 'Description']],
        body: tableData,
        startY: headerHeight,
        styles: { fontSize: 10 },
        headStyles: { fontSize: 11 },
        margin: { top: headerHeight },
        didDrawPage: (data) => {
          this.pdfService.generatePDFHeader(doc, reportName, locationName, manager, reportDate, false,false);
          doc.setFontSize(10);
          doc.setTextColor(40);
        }
      });
      doc.save('Penalty_Days_Report.pdf');
    }
  }


  exportAsXLSX() {
    if (this.extradaysReport) {
      const exportData = this.arrayList.map((row: any, index: any) => ({
        "S.No": index + 1,
        "Date": this.datePipe.transform(row.edate, "dd-MM-yyyy"),
        "Day": row.dayname,
        "Emp. ID": row.empcode,
        "Emp. Name": row.empname,
        "Extra Days Count":parseFloat(row.count).toFixed(1),
        "Description": row.description,
      }));
      const ws: XLSX.WorkSheet = XLSX.utils.json_to_sheet(exportData);
      const wb: XLSX.WorkBook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, 'Extradays_Days_Report');
      XLSX.writeFile(wb, 'Extradays_Days_Report.xlsx');

    } else {
      const exportData = this.arrayList.map((row: any, index: any) => ({
        "S.No": index + 1,
        "Date": this.datePipe.transform(row.edate, "dd-MM-yyyy"),
        "Day": row.dayname,
        "Emp. ID": row.empcode,
        "Emp. Name": row.empname,
        "Penalty Days Count": parseFloat(row.count).toFixed(1),
        "Description": row.description,
      }));
      const ws: XLSX.WorkSheet = XLSX.utils.json_to_sheet(exportData);
      const wb: XLSX.WorkBook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, 'Penalty_Days_Report');
      XLSX.writeFile(wb, 'Penalty_Days_Report.xlsx');
    }
  }

  getPageSizes2(): number[] {

    var customPageSizeArray = [];
    if (this.dataSource2.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource2.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource2.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource2.data.length);
    return customPageSizeArray;
  }
}