import { Component, EventEmitter, OnInit, Output, ViewChild } from '@angular/core';
import { UserData } from "../../../attendance/models/EmployeeData";
import { MatPaginator } from "@angular/material/paginator";
import { MatTableDataSource } from "@angular/material/table";
import { MatSort } from "@angular/material/sort";
import { LeavesService } from '../../leaves.service';
import { Router } from "@angular/router";
import { ReviewAndApprovalsComponent } from "../../dialog/review-and-approvals/review-and-approvals.component";
import { MatDialog } from "@angular/material/dialog";
import { DatePipe } from "@angular/common";
import { ConfirmationComponent } from "../../dialog/confirmation/confirmation.component";
import { NgxSpinnerService } from 'ngx-spinner';
import { EmsService } from 'src/app/modules/ems/ems.service';
import { LoginService } from 'src/app/services/login.service';
import { AdminService } from 'src/app/modules/admin/admin.service';

@Component({
  selector: 'app-pending-approvals',
  templateUrl: './pending-approvals.component.html',
  styleUrls: ['./pending-approvals.component.scss']
})
export class PendingApprovalsComponent implements OnInit {
  displayedColumns: string[] = ['appliedOn', 'empId', 'empName', 'leaveType', 'fromDate', 'toDate', 'noOfDays', 'pendingSince', 'action'];
  dataSource: MatTableDataSource<UserData> = <any>[];
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  // @Input() search: search;

  titleName: any;
  reason: any;
  LM113: any;
  LM114: any;
  pipe = new DatePipe('en-US');
  userSession: any;
  arrayList: any = [];
  LM119: any;
  pageLoading = true;
  employeeEmailData: any = [];
  employeeId: any;
  userDashboard: any = '/LeaveManagement/ManagerDashboard';
  moduleName: any = 'leave management';
  messageList: any = [];
  companyName: any;
  @Output() countUpdated = new EventEmitter<number>();
  constructor(private LM: LeavesService, private router: Router, public dialog: MatDialog,
    public spinner: NgxSpinnerService, private emsService: EmsService, private adminService: AdminService) { }

  ngOnInit(): void {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.companyName = sessionStorage.getItem('companyName')
    // this.getActiveEmployeeDashboard();
    this.getLeavesForApprovals();
    this.getErrorMessagesforLeave()


  }

  /**
   * get all pending leave for approvals
   * **/
  getLeavesForApprovals() {
    this.spinner.show();
    this.arrayList = [];
    this.LM.getLeavesForApprovals(this.userSession.id).subscribe((res: any) => {

      this.spinner.hide();
      if (res.status) {
        this.arrayList = res.data;
        // for(let i = 0; i<res.data.length;i++){
        //   var date = new Date();
        //   var appliedDate = new Date(res.data[i].appliedon)
        //   res.data[i].pendingSince = date.getDate() - appliedDate.getDate();
        //   this.arrayList.push(res.data[i])
        // }

        this.dataSource = new MatTableDataSource(this.arrayList);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;
        const updatedCount = res.data.length;
        this.countUpdated.emit(updatedCount);
      } else {
        this.arrayList = [];
        this.dataSource = new MatTableDataSource(this.arrayList);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        const updatedCount = res.data.length;
        this.countUpdated.emit(updatedCount);
      }
    })
  }

  applyFilter(event: Event) {
    // const filterValue = (event.target as HTMLInputElement).value;
    // this.dataSource.filter = filterValue.trim().toLowerCase();
    //
    // if (this.dataSource.paginator) {
    //   this.dataSource.paginator.firstPage();
    // }
  }
  /**
   * on click review and approve
   * **/

  leaveReview(leave: any) {
    leave.url = this.userDashboard
    this.router.navigate(["/LeaveManagement/ReviewAndApprovals"], { state: { leaveData: leave, isleave: true } });
  }
  submit(leave: any, status: any, approverId: any) {
    this.employeeId = leave.empid;
    this.getEmployeeEmailData(leave, status, approverId);
  }
  leaveApprove(leave: any, status: any, approverId: any) {
    if (this.employeeEmailData.length == 0) {
      this.getEmployeeEmailData(leave, status, approverId);
    }
    else {
      let obj = {
        "id": leave.id,
        "leaveId": leave.leave_id,
        "empId": leave.empid,
        "approverId": approverId ? approverId : this.userSession.id,
        "leaveStatus": status,
        "reason": status == 'Approved' ? null : leave.action_reason ? leave.action_reason : this.reason,
        "detail": leave.bereavement_id ? leave.bereavement_id : leave.comp_off_worked_date ? leave.comp_off_worked_date : null,
        /// email data
        "leavedata": leave,
        "emaildata": this.employeeEmailData,

      };

      this.LM.setApproveOrReject(obj).subscribe((res: any) => {
        this.spinner.hide();

        if (res && res.status) {
          if (res.leaveStatus == 'Approved') {
            this.dialog.open(ConfirmationComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: { Message: this.LM113, url: this.userDashboard }
            });
            this.getLeavesForApprovals();
          } else {
            this.dialog.open(ConfirmationComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: { Message: this.LM114, url: this.userDashboard }
            });
            this.getLeavesForApprovals();
            this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>

              this.router.navigate([this.userDashboard]));

          }
        } else {
          this.dialog.open(ConfirmationComponent, {
            position: { top: `70px` },
            disableClose: true,
            data: { Message: this.LM119, url: this.userDashboard }
          });

        }


      })
    }
  }
  leaveReject(leave: any, status: any, rejectId: any) {
    this.titleName = "Reject"
    this.openDialog(leave)
  }

  openDialog(leave: any): void {
    const dialogRef = this.dialog.open(ReviewAndApprovalsComponent, {
      width: '600px', position: { top: `100px` },
      data: { name: this.titleName, reason: this.reason, }
    });

    dialogRef.afterClosed().subscribe(result => {

      if (result != undefined) {
        if (result !== true) {
          this.reason = result.reason;
          //  this.leaveApprove(leave, 'Rejected', null);
          this.employeeId = leave.empid;
          this.getEmployeeEmailData(leave, 'Rejected', null);
        }
      }
    });
  }

  getErrorMessagesforLeave() {
    let payload = {
      "code": null,
      "pagenumber": 1,
      "pagesize": 100,
      "companyName": this.companyName
    }
    this.adminService.getErrorMessagesforLeave(payload).subscribe((result: any) => {
      this.messageList = result.data
      if (result.status) {
        this.messageList.forEach((message: any) => {
          if (message.errorcode == 'LM113') {
            this.LM113 = message.errormessage
          }
          else if (message.errorcode == 'LM114') {
            this.LM114 = message.errormessage

          }
          else if (message.errorcode == 'LM119') {
            this.LM119 = message.errormessage
          }

        })


      }

    })
  }

  getPageSizes(): number[] {

    var customPageSizeArray = [];
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }
  getEmployeeEmailData(leave: any, status: any, approverId: any) {
    this.employeeEmailData = [];
    this.employeeId = leave.empid;
    this.emsService.getEmployeeEmailDataByEmpid(this.employeeId)
      .subscribe((res: any) => {
        this.employeeEmailData = JSON.parse(res.data[0].jsonvalu)[0];
        this.leaveApprove(leave, status, approverId)
      })

  }

  getActiveEmployeeDashboard() {
    var jsonString = sessionStorage.getItem('activeModule');
    if (jsonString && jsonString.toString().length > 0) {
      var activeModule: any = JSON.parse(jsonString);

      if (activeModule.module.modulename.toString().toLowerCase() != this.moduleName) {
        if (activeModule.module.modulename.toString().toLowerCase() === 'sales pro management') {
          this.userDashboard = '/Crm/PendingLeaveApprovals';
        }
        else {
          activeModule.module.children.forEach((c: any) => {
            if (c.displayName === 'Employee') {
              c.subChildren.forEach((e: any) => {
                if (e.parentrole === 'Employee' && e.screen_name === 'Employee Dashboard')
                  this.userDashboard = e.routename;
              });
            }
          });
        }
      }
    }
  }

}
