  // ─── Toggle helpers (copy from LMS) ───
  isAllBranchesSelected() {
    return this.branches.length > 0
      && this.selectedBranchIds.length === this.branches.length;
  }
  toggleAllBranches() {
    this.selectedBranchIds = this.isAllBranchesSelected()
      ? []
      : this.branches.map(b => b.id);
    this.loadCourseOverviewPie();
  }

  isAllDepartmentsSelected() {
    return this.departments.length > 0
      && this.selectedDepartmentIds.length === this.departments.length;
  }
  toggleAllDepartments() {
   if(this.departments && this.departments.length)
      this.selectedDepartmentIds = this.isAllDepartmentsSelected() ? [] : this.departments.map(d => d.id);
    this.loadCourseOverviewPie();
  }

  // ─── The pie-loader itself ───
  loadCourseOverviewPie() {

    //console.log('coursePieChart instance:', this.coursePieChart);

    const from = this.courseFromDate.toISOString().slice(0,10);
    const to   = this.courseToDate  .toISOString().slice(0,10);

    const branches   = this.selectedBranchIds.length   ? this.selectedBranchIds   : [0];
    const departments= this.selectedDepartmentIds.length? this.selectedDepartmentIds: [0];
    // no managers/employees in this view → just pass [0]
    const managers   = [0];
    const employees  = [0];

    this.learnService
      .getManagerDashboardPie(branches, managers, departments, employees, from, to)
      .subscribe(data => {
        const labels = Object.keys(data);
        const values = Object.values(data) as number[];

        this.coursePieData = {
          labels,
          datasets: [{
            data: values,
            backgroundColor: [
              '#ff6384','#36a2eb','#ffcd56','#4bc0c0','#9966ff','#ff9f40'
            ]
          }]
        };
      });


// 2) Load completion & enrollment rates
this.learnService
  .getSuperadminDashboard(branches, departments, from, to)
  .subscribe((res: any[]) => {
    if (!res.length) return;
    const stats = res[0];
    // stats.completion_rate === "42"  → 42%
    // stats.enrollment_rate === "1"  → 1%
    const compPct   = parseFloat(stats.completion_rate);
    const enrollPct = parseFloat(stats.enrollment_rate);

    // Completion donut: value + remainder
    this.completionChartData = {
      labels: ['Completion Rate', ''],
      datasets: [{
        data: [compPct, 100 - compPct],
        backgroundColor: ['#36a2eb', '#e0e0e0']
      }]
    };

    // Enrollment donut: value + remainder
    this.enrollmentChartData = {
      labels: ['Enrollment Rate', ''],
      datasets: [{
        data: [enrollPct, 100 - enrollPct],
        backgroundColor: ['#4bc0c0', '#e0e0e0']
      }]
    };
  });


  }

