  async getCrmConvertionRatios(){
    let date = this.pipe.transform(this.currentYear, 'yyyy-MM-dd');
    let ratio_colors:any = [];
    let ratio_datasets:any = [];
    let ratio_labels:any = [];
    let plugins:any = {
            legend: {display: false }, tooltip: {enabled: false  },  datalabels: { display: true, color: 'white', font: { size: 14 , weight:500 }, // color: '#e5e5e5',
                formatter: (value: any, context: any) => {
                  let data = context.chart.data.datasets[0].data;
                  let total = data.reduce((acc: number, val: number) => acc + val, 0);
                  let percent = total > 0 ? (value / total) * 100 : 0;
                  return `${Math.round(percent)}%`;
                },
            }
          };
   
    this.crm_charts.ratio.options = { responsive: true, rotation: -90, circumference: 180,cutout: '70%',  plugins: plugins };

    this.spinner.show();
    this.crm.getSprypleData({date_selected:date,user_role:'SA',months:3},'get_crm_dashboard_convertion_ratios').subscribe((res: any) => {
      if (res.status && res.data && res.data[0]) {  
        this.crm_charts.ratio.data = res.data;
        
          for(let i=0;i<res.data.length;i++){
              ratio_labels.push(res.data[i].label)
              ratio_colors.push(res.data[i].bg_color); 
          }
         this.crm_charts.ratio.data = res.data;
          this.crm_charts.ratio.data.forEach(async (e: any) => {
            this.crm_charts.ratio.labels.push({label:e.label,bg_color:e.bg_color});
              let value = Number(e.ratio_percent);
              e.gauge_data =  { labels: [e.label,'others'], datasets: [{ data: [value, 100 - value], backgroundColor: [e.bg_color,'#118ab2'], borderWidth: 0 }] };
          });

          this.crm_charts.ratio.labels.push({label:'others',bg_color:'#118ab2'});
      }     
     });
  }

