import { Component, Inject } from '@angular/core';
import { MAT_SNACK_BAR_DATA } from '@angular/material/snack-bar';

@Component({
  selector: 'app-custom-snackbar',
  template: `
   <div
      class="snackbar-container"
      (mouseenter)="handleMouse(true)"
      (mouseleave)="handleMouse(false)"
    >
      <mat-icon class="snackbar-icon" [ngClass]="data.isSuccess ? 'success' : 'error'">
        {{ data.isSuccess ? 'check_circle' : 'warning' }}
      </mat-icon>
      <span class="snackbar-message">{{ data.message }}</span>
    </div>
  `,
  styles: [`
    .snackbar-container {
      display: flex;
      align-items: flex-start;
      flex-wrap: nowrap;
      max-width: 100%;
    }

    .snackbar-icon {
      margin-right: 8px;
      flex-shrink: 0;
      font-size: 24px;
      line-height: 24px;
    }

    .snackbar-icon.success {
      color:rgb(255, 255, 255);
    }

    .snackbar-icon.error {
      color:white;
    }

    .snackbar-message {
      word-wrap: break-word;
      overflow-wrap: break-word;
      white-space: normal;
      flex: 1;
    }
  `]
})

export class CustomSnackbarComponent {
  constructor(@Inject(MAT_SNACK_BAR_DATA) public data: any) {}
   onHover?: (hovering: boolean) => void;

  handleMouse(hovering: boolean) {
    if (this.onHover) {
      this.onHover(hovering);
    }
  }
}
