    getDepartmentsMaster() {
    this.companyService.getMastertable('departmentsmaster', 1, 1, 1000, this.companyDBName).subscribe(data => {
      if (data.status) {
        this.availableDepartments = data.data;
        this.filteredDepartments = [...this.availableDepartments];
      }
    })
  }
filterDepartments() {
  const value = this.departmentSearchControl.value?.toLowerCase().trim() || '';

  if (!value) {
    this.filteredDepartments = [...this.availableDepartments];
    return;
  }

  this.filteredDepartments = this.availableDepartments.filter((dep: any) =>
    dep.deptname.toLowerCase().includes(value)
  );
}
filterSection() {
  const value = this.sectionSearchControl.value?.toLowerCase().trim() || '';

  if (!value) {
    this.section = [...this.filteredSections];
    return;
  }

  this.section = this.filteredSections.filter((sec: any) =>
    sec.section_name.toLowerCase().includes(value)
  );
}

onDepartmentClose() {
  this.departmentSearchControl.setValue('');          // clear input
  this.filteredDepartments = [...this.availableDepartments]; // reset list
}

onSectionClose() {
  this.sectionSearchControl.setValue('');  // if you have FormControl for section, else skip
  this.section = [...this.filteredSections]; // reset list
}

