import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { BehaviorSubject, Observable } from 'rxjs';
import { environment } from 'src/environments/environment';

// import {subscription} from '../models/subscription';
// import { changePassword } from '../models/changePassword';
// import { resetPassword } from '../models/resetPassword';



@Injectable({
  providedIn: 'root'
})
export class LoginService {
  mainBeUrl = environment.apiUrl;
  userSession: any;
  companyName: any;
  httpOptions: any;
  httpOptionslogin = {
    headers: new HttpHeaders({ 'content-Type': 'application/json' })
  };

  httpOptionsOne = {
    headers: new HttpHeaders({ 'content-Type': 'multipart/form-data' })
  };

  private loggedInSubject = new BehaviorSubject<boolean>(false);
  loggedIn$: Observable<boolean> = this.loggedInSubject.asObservable();

  constructor(private hClient: HttpClient) {
    this.userSession = (sessionStorage.getItem('user'));
    this.companyName = sessionStorage.getItem('companyName');


    this.httpOptions = {
      headers: new HttpHeaders({
        'content-Type': 'application/json',
        "Authorization": JSON.parse(JSON.stringify(sessionStorage.getItem('token') || '')),
      })
    };


    // this.loggedIn$.subscribe(() => {
    //   this.httpOptions = {
    //     headers: new HttpHeaders({
    //       'content-Type': 'application/json',
    //       "Authorization": JSON.parse(JSON.stringify(sessionStorage.getItem('token') || '')),
    //     })
    //   };
    // })
  }

  setLoggedInState(isLoggedIn: boolean) {
    this.loggedInSubject.next(isLoggedIn);
  }

  /* get All Subscriptions */

  getallSubscriptions(): Observable<any> {
    return this.hClient.get(this.mainBeUrl + 'savesubscription', { responseType: 'json' });
  }
  getErrorMessages(errorCode: any, page: any, size: any): Observable<any> {
    this.companyName = sessionStorage.getItem('companyName') ? sessionStorage.getItem('companyName') : null
    return this.hClient.get(this.mainBeUrl + 'commonApi/getErrorMessages/' + errorCode + '/' + page + '/' + size + '/' + this.companyName, this.httpOptions);
  }
  Savelogin(data: any): Observable<any> {
    console.log(this.mainBeUrl)
    return this.hClient.post(this.mainBeUrl + 'commonApi/emp_login', JSON.stringify(data), this.httpOptionslogin);
  }
  /* save change password */
  changepassword(changePassword: any): Observable<any> {
    this.httpOptions = {
      headers: new HttpHeaders({
        'content-Type': 'application/json',
        "Authorization": JSON.parse(JSON.stringify(sessionStorage.getItem('token') || '')),
      })
    };
    changePassword.companyName = sessionStorage.getItem('companyName');
    return this.hClient.post(this.mainBeUrl + 'commonApi/changePassword', JSON.stringify(changePassword), this.httpOptions);
  }
  resetpassword(resetPassword: any): Observable<any> {
    // resetPassword.companyName = this.companyName;
    return this.hClient.post(this.mainBeUrl + 'commonApi/resetpassword', JSON.stringify(resetPassword), this.httpOptions);

  }
  // forgot password
  verifyEmail(email: any, companyName: any): Observable<any> {
    return this.hClient.get(this.mainBeUrl + 'commonApi/forgetpassword/' + email + '/' + companyName, this.httpOptions);
  }
  // forgot password
  // getModules(): Observable<any> {
  //   return this.hClient.get(this.mainBeUrl + 'attendance/api/getModules',this.httpOptions);
  // }
  getModules(tableName: any, status: any, page: any, size: any, cname: any): Observable<any> {
    this.httpOptions = {
      headers: new HttpHeaders({
        'content-Type': 'application/json',
        "Authorization": JSON.parse(JSON.stringify(sessionStorage.getItem('token') || '')),
      })
    };
    return this.hClient.get(this.mainBeUrl + 'commonApi/getMastertable/' + tableName + '/' + status + '/' + page + '/' + size + '/' + cname, this.httpOptions);
  }
  getrolescreenfunctionalities(empId: any, moduleId: any): Observable<any> {
    return this.hClient.get(this.mainBeUrl + 'adminApi/getrolescreenfunctionalities/' + empId + '/' + moduleId, this.httpOptions);
  }
  getMinUsers(data: any): Observable<any> {
    return this.hClient.get(this.mainBeUrl + 'subscriptionApi/getMinUserForPlan/' + data, this.httpOptions);
  }

  /** password reset in admin */
  updateEmployeeLoginsForAdmin(data: any) {
    return this.hClient.post(this.mainBeUrl + 'commonApi/updateEmployeeLoginsForAdmin', data, this.httpOptions);
  }
  // getErrorMessagesforLeave(data: any) {

  //   return this.hClient.post(this.mainBeUrl + 'commonApi/getErrorMessages', JSON.stringify(data), this.httpOptions);
  // }
}
