import { Injectable } from '@angular/core';
import { MatSnackBar, MatSnackBarRef } from '@angular/material/snack-bar';
import { CustomSnackbarComponent } from './custom-snackbar';


@Injectable({
  providedIn: 'root'
})
export class CommonSnackbarService {
  private timeoutHandle: any;

  constructor(private snackBar: MatSnackBar) {}

  show(message: string, isSuccess: boolean = true): void {
    const snackRef: MatSnackBarRef<CustomSnackbarComponent> =
      this.snackBar.openFromComponent(CustomSnackbarComponent, {
        horizontalPosition: 'end',
        verticalPosition: 'top',
        panelClass: isSuccess ? ['snackbar-success'] : ['snackbar-error'],
        duration: undefined, // we control closing manually
        data: { message, isSuccess }
      });

    // Auto-dismiss logic
    this.timeoutHandle = setTimeout(() => {
      snackRef.dismiss();
    }, 3000);

    // Listen for mouse enter/leave to pause/resume timeout
    const instance = snackRef.instance as any;
    instance.onHover = (hovering: boolean) => {
      if (hovering) {
        clearTimeout(this.timeoutHandle);
      } else {
        this.timeoutHandle = setTimeout(() => snackRef.dismiss(), 3000);
      }
    };
  }
}
