import { Pipe, PipeTransform } from '@angular/core';
import { NarrationService } from '../services/narration.service';

@Pipe({  name: 'narration',pure: false  })
export class NarrationPipe implements PipeTransform {
  constructor(private narrationService: NarrationService) {}
  transform(key: string): string {
    let lang = localStorage.getItem('lang') || 'english';
    return this.narrationService.getNarration(key, lang as 'english' | 'arabic');
  }
}