import { Component, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, FormControl, UntypedFormGroup, Validators } from '@angular/forms';
import { Observable } from 'rxjs/internal/Observable';
import { map, startWith } from 'rxjs/operators';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { PayrollService } from '../../payroll.service';
import { Router } from '@angular/router';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { MatDialog } from '@angular/material/dialog';
import { TdsService } from '../../tds.service';
import { DialogComponent } from '../../dialog/dialog.component';

@Component({
  selector: 'app-add-employee-exemption-submission',
  templateUrl: './add-employee-exemption-submission.component.html',
  styleUrls: ['./add-employee-exemption-submission.component.scss']
})
export class AddEmployeeExemptionSubmissionComponent implements OnInit {

  // @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatPaginator) set _paginator(paginator: MatPaginator) {
     this.paginator = paginator;
     this.dataSource.paginator = this.paginator;
   }
  @ViewChild(MatSort)
  sort!: MatSort;
  searchEmp:any = UntypedFormGroup;
  addExcemptionForm :any= UntypedFormGroup;
  editForm:any = UntypedFormGroup;
  myControl = new FormControl('');
  options: any=[];
  filteredOptions!: Observable<string[]>;
  filteredEmployeeList:any = [];
  searchControl= new FormControl('');
  empList:any=[];
  dataSource: MatTableDataSource<any> = <any>[];
  displayedColumns:string[] = ['sno','section','sectionLimit','amountDeclared','amountApproved','prevSubExcemptions','proof','dateOfSub','status','actions'];
  pageLoading = true;
  userSession:any;
  financialYear:any;
  employeename:any;
  designation:any;
  department:any;
  age:any;
  grossIncome:any;
  taxableIncome:any;
  taxRegime:any;
  deductibleTaxAmount:any;
  deductedTaxAmount:any;
  pendingTaxAmount:any;
  completedDeductions:any;
  PendingDeductions:any;
  employeeCode:any;
  searchControlForSections = new FormControl('');
  sectionList:any = [
    {id:'1', sectionName : '80CCC'},
    {id:'2', sectionName : '80CC'},
  ];
  filteredSectionList:any;
  arrayList:any=[];
  enable:any;
  hideSave:boolean = false;
  employee_id:any;
  isReject:boolean=false;
  displayEmpDetails:boolean=false;
  totalDeductions:any;
  noData:boolean= false;
  isEdit:boolean=false;
  companyName: any;
  rejectReason: any;
  titleName: string = '';
  isNoData:boolean = false;


  

  constructor(
    private payrollService:PayrollService,
    private fb:FormBuilder,
    private router : Router,
    public dialog: MatDialog,
    public tdsService:TdsService,
  ){

    this.searchEmp = this.fb.group({
      empname : ['',Validators.required],
    })
    this.addExcemptionForm = this.fb.group({
       section:['',Validators.required],
    })
    this.editForm = this.fb.group({
      amountApproved : ['',Validators.required]
    })

  }
  async ngOnInit() {

    this.financialYear  = await this.getFinancialYears();
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    this.getEmployeeListForExemptionSubmission();
    this.getEmployeesForAssignPaygroup();
    this.companyName = sessionStorage.getItem('companyName');

    this.filteredOptions = this.myControl.valueChanges.pipe(
      startWith(''),
      map((value:any) => this._filter(value || ''))
    );
 
    this.searchControl.valueChanges.subscribe(searchText => {
      this.filterEmpList(searchText);
    });
  
    this.searchControlForSections.valueChanges.subscribe((searchText:any) => {
      this.filterSectionList(searchText);
    });
    this.filteredSectionList = this.sectionList;
    // this.getTdsExemptionRequestsOfEmployeeForApproval();
  }

  private _filter(value: any): any[] {
    const filterValue = value.toLowerCase();
    return this.options.filter((option:any) => option.empname.toLowerCase().includes(filterValue));
  }
  
    // New function to check if any filtered options exist
    hasFilteredOptions(filteredOptions: string[]): boolean {
      return filteredOptions.length > 0;
    }
    empdata:any=[]
    
      /**Employees list for assigning paygroup */
  getEmployeesForAssignPaygroup() {
    this.empdata = [];
    this.payrollService.getEmployeesForAssignPaygroup(0).subscribe((result: any) => {
      if (result.status && result.data.length > 0) {
        this.options = result.data;
      }
    })
  }

  filterEmpList(searchText: any){
    this.filteredEmployeeList = this.empList.filter((val: any) =>
      val.employee_name.toLowerCase().includes(searchText.toLowerCase()) || val.employee_code.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredEmployeeList.length <= 0) {
      this.noData = true;
    } else {
      this.noData = false;
    }
  }

  filterSectionList(searchText:any){
    this.filteredSectionList = this.sectionList.filter((val: any) =>
      val.sectionName.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredSectionList.length <= 0) {
      this.searchControlForSections.setValue('');
    } else {

    }
  }
  search(){
    this.employeename='';
    this.designation='';
    this.department='';
    this.age='';
    this.grossIncome='';
    this.taxableIncome='';
    this.taxRegime='';
    this.deductibleTaxAmount='';
    this.deductedTaxAmount='';
    this.pendingTaxAmount='';
    this.completedDeductions='';
    this.PendingDeductions='';  
    this.employeeCode = '';
    this.totalDeductions='';

    this.arrayList = []
    this.dataSource = new MatTableDataSource(this.arrayList);
    
    if(this.searchEmp.valid){
      this.getEmployeeDetailsForExemptionSubmission();
      this.getTdsExemptionRequestsOfEmployeeForApproval();
    }
  }
  
  cancel(){
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Payroll/addEmployeeExemptionSubmission"]));
  }


  Approve(row:any,index:any){
    
    let value = {
      "peted_id": row.id,
      "status_value": this.isReject ? "Rejected":"Approved",
      "approved_value": this.editForm.controls.amountApproved.value ? this.editForm.controls.amountApproved.value : row.amount_declared ,
      "rejection_reason":this.isReject ? this.rejectReason : null,
      "mgr_id_value": this.userSession.id,
      "declared_amount": row.amount_declared,
      "financial_year": this.financialYear,
      "companyName": this.companyName,
      "employee_id": this.employee_id,
    }

    this.tdsService.setEmployeeTdsExemptionRequest(value).subscribe((res: any) => {
      if (res.status && res.data) {
        if(res.data[0].output == 2){
          this.tdsService.showSnackBar(row[0].message,true)
          return ;
        }else{
          this.tdsService.showSnackBar(`The submission is ${this.isReject?'Rejected': 'Approved'} successfully.`)
          this.isReject = false;
          // this.dialog.open(ReusableDialogComponent, {
          //   position: { top: `70px` },
          //   disableClose: true,
          //   data: `The submission is ${this.isReject?'Rejected': 'Approved'} successfully.`
          // });
          this.getTdsExemptionRequestsOfEmployeeForApproval();
          this.hideSave = false;
          this.isEdit =false;
          this.search();
          this.editForm.controls.amountApproved.setValue('')
        }
        
      } else{
        this.tdsService.showSnackBar(`Unable to ${this.isReject?'Reject': 'Approve'} the submission.` ,true)
        //  this.dialog.open(ReusableDialogComponent, {
        //   position: { top: `70px` },
        //   disableClose: true,
        //   data: `Unable to ${this.isReject?'Reject': 'Approve'} the submission.`
        // });
      }
    });

  }
  
  reject(row:any,index:any){
    this.isEdit =false;
    this.isReject = true;
    this.titleName = "Reason For Rejection";
    this.openDialog(row,index);
  }    

  cancelRow(row:any){
    this.hideSave = false;
    this.enable = null;
    this.isEdit = false;
  }

  edit(row:any){
    this.enable = row.id;
    this.hideSave = true;
    this.isEdit =true;
    this.editForm.controls.amountApproved.setValue(row.amount_declared )
    // this.isEdit == true ?  this.editForm.controls.amount.value : this.editForm.controls.amount.setValue(row.amount_declared);

  }

  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.dataSource.data.length < 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  getTdsExemptionRequestsOfEmployeeForApproval(){
    this.arrayList = []
    this.enable = null;
    let payLoad = {
      financial_year : this.financialYear,
      empid : this.searchEmp.controls.empname.value,
    }
    this.tdsService.getTdsExemptionRequestsOfEmployeeForApproval(payLoad).subscribe((result:any)=>{
      if(result.data.length > 0){
        this.isEdit = false;  
        this.employee_id = result.data[0].employee_id;
        this.arrayList = JSON.parse(result.data[0].records)
        this.dataSource = new MatTableDataSource(this.arrayList);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;
      }
    })
    }
  
    getFinancialYears() {
      return new Promise((resolve) => {
        this.payrollService.getFinancialYears().subscribe((result: any) => {
          
          if (result.status && result.data.length) {
            resolve(result.data[0].financial_year)
          } else {
            resolve('')
          }
        });
      });
    }

    getEmployeeDetailsForExemptionSubmission(){
      let payLoad = {
        financial_year : this.financialYear,
        empid : this.searchEmp.controls.empname.value,
      }
      this.tdsService.getEmployeeDetailsForExemptionSubmission(payLoad).subscribe((result:any)=>{
      if(result.data.length > 0){
        this.isEdit = false;  
        this.employeename=result.data[0].employee_name;
        this.designation=result.data[0].designation;
        this.department=result.data[0].deptname;
        this.age=result.data[0].age_as_on_end_of_fin_yr.slice(0,-3);
        this.grossIncome=Math.abs(result.data[0].gross_financial_year_income);
        this.taxableIncome=Math.abs(result.data[0].taxable_income);
        this.taxRegime=result.data[0].regime_name;
        this.deductibleTaxAmount=Math.abs(result.data[0].deductible_tax_amount);
        this.deductedTaxAmount=Math.abs(result.data[0].deducted_tax_amount);
        this.pendingTaxAmount= Math.abs(result.data[0].pending_tax_amount);
        this.completedDeductions= Math.abs(result.data[0].completed_deductions_count);
        this.PendingDeductions=Math.abs(result.data[0].pending_deductions_count) ;  
        this.employeeCode = result.data[0].employee_code;
        this.totalDeductions = Math.abs(result.data[0].total_deductions);
      }
      if(this.employeeCode){
        this.displayEmpDetails = true;
        this.isNoData = false;
      }else{
        this.displayEmpDetails = false;
        this.isNoData = true
      }
      })
    }

    getEmployeeListForExemptionSubmission(){
      let payLoad = {
        financial_year : this.financialYear
      }
      this.tdsService.getEmployeeListForExemptionSubmission(payLoad).subscribe((result:any)=>{
        this.empList = result.data;
        this.filteredEmployeeList = this.empList;
      })
    }
    showPdf(path:any,file_name:any) {
      this.tdsService.showPdf(path,file_name)
  
    // this.dialog.open(ViewPdfImageDocPopUpComponent, {
    //   width: '80%',  // Set width
    //   height: '70%', // Set height
    //   position: { top: `70px` },
    //   disableClose: true,
    //   data: `http://localhost:6060/pdf/${path}/${file_name}`
    // });
  }
  preventPlusMinus(event: KeyboardEvent): void {
    if (event.key === '+' || event.key === '-') {
      event.preventDefault();
    }
  }
  
  limitDecimal(event: Event): void {
    const input = event.target as HTMLInputElement;
    const regex = /^\d+(\.\d{0,2})?$/;
  
    if (!regex.test(input.value)) {
      input.value = input.value.slice(0, input.value.indexOf('.') + 3);
    }
  }

  change( record: any) {
    let inputAmount = Number(this.editForm.get('amountApproved')?.value);
    record.section_limit = Number(record.section_limit)
    if(record.section_total){
      let totalLimit = record.section_limit - record.section_total
      if (inputAmount > totalLimit) {
        setTimeout(() => {
        this.tdsService.showSnackBar('You cannot declare beyond the section maximum limit.',true)
        this.editForm.get('amountApproved')?.setValue(totalLimit)       
      }
      , 100);
      }
    }else{
      if (inputAmount > record.section_limit) {
        setTimeout(() => {
        this.tdsService.showSnackBar('You cannot declare beyond the section maximum limit.',true)
        this.editForm.get('amountApproved')?.setValue(record.section_limit)       
      }
      , 100);
      }
    }
}

  openDialog(data:any,index:any): void {
      const dialogRef = this.dialog.open(DialogComponent, {
        width: '500px', position: { top: `70px` },
        data: { name: this.titleName, reason: this.rejectReason, }
      });
      dialogRef.afterClosed().subscribe(result => {
        if (result != undefined) {
          if (result !== true) {
            this.rejectReason = result.reason;
            this.Approve(data,index);
          }
        }
      });
    }


}
