  setEmployeePreviousCompanyPayment(data: any,file: File | null): Observable<any> {
    data.companyName = this.companyName;
    data.fromDate = moment(data.fromDate).format('YYYY-MM-DD');
    data.toDate = moment(data.toDate).format('YYYY-MM-DD');
    const formData = new FormData();
    formData.append("previouscompany", JSON.stringify(data));
    if(file) {
      formData.append("file", file, file.name);
    }
    return this.http.post(`${this.mainBeUrl}tdsApi/setEmployeePreviousCompanyPayment`, formData, this.formDataHttpOptions);
  }
  

