import { Component, OnInit, ViewChild } from '@angular/core';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { FormBuilder, FormControl, UntypedFormGroup, Validators } from '@angular/forms';
import { MatTableDataSource } from '@angular/material/table';
import { PayrollService } from '../../payroll.service';
import { MatDialog } from '@angular/material/dialog';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';

@Component({
  selector: 'app-payroll-deduction-reimbursements',
  templateUrl: './payroll-deduction-reimbursements.component.html',
  styleUrls: ['./payroll-deduction-reimbursements.component.scss']
})
export class PayrollDeductionReimbursementsComponent implements OnInit {

  // Tab management
  selectedTabIndex: number = 0;
  searchControl = new FormControl('');
  searchControlforType = new FormControl('');


  // Forms
  managerForm!: UntypedFormGroup;
  employeeDeductionForm!: UntypedFormGroup;

  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort) sort!: MatSort;
  pageLoading = true;
  dataSource: MatTableDataSource<any> = <any>[];
  displayedColumns = ['sno', 'empid', 'empname', 'designation', 'componentname', 'startdate', 'enddate', 'totalDedAmt', 'deductions', 'dedAmt', 'pendingDedCount', 'pendingDedAmt', 'totalReimAmt', 'reimbursements', 'reimAmt', 'pendingReimCount', 'pendingReimAmt', 'status']

  // UI states
  btnDisable: boolean = false;
  isEdit: boolean = false;
  editIndex: number = -1;
  loading: boolean = false;

  // Dropdown data
  employees: any[] = [];
  filteredEmployees: any[] = [];
  employeeDeductions: any[] = [];
  availableMonths: any[] = [];
  filteredEmployeeDeductions: any[] = [];

  // Filter data
  selectedEmployee: any = null;
  selectedManagerId: any = null;
  currentMonth: any = null;
  currentYear: any = null;
  selectedLocationId: any = null;
  userSession: any;

  // Month selection data
  selectedEmployeeForDeduction: any = null;
  employeeDeductionConfig: any = null;
  deductionMonths: any[] = [];
  reimbursementMonths: any[] = [];
  selectedDeductionMonths: any[] = [];
  selectedReimbursementMonths: any[] = [];

  // Section visibility
  showDeductionSection: boolean = false;
  showReimbursementSection: boolean = false;



  constructor(
    private formBuilder: FormBuilder,
    private payrollService: PayrollService,
    private dialog: MatDialog
  ) { }

  ngOnInit(): void {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.initializeForms();
    this.initializeData();
    this.employeeDeductionForm.get('employeeName')?.valueChanges.subscribe((selectedValue: any) => {
      // clear selections whenever employee changes
      this.clearMonthSelections();

      if (!selectedValue) {
        this.showDeductionSection = false;
        this.showReimbursementSection = false;
        this.employeeDeductions = [];
        return;
      }

      // If the employee object carries flags (e.g., deduction: 1, reimbursement: 1),
      // use them. Adjust property names to match your API.
      // Example fields used here: selectedValue.is_deduction, selectedValue.is_reimbursement
      const empDedFlag = selectedValue?.is_deduction ?? selectedValue?.deduction ?? null;
      const empReimFlag = selectedValue?.is_reimbursement ?? selectedValue?.reimbursement ?? null;

      this.showDeductionSection = empDedFlag === 1 || empDedFlag === true;
      this.showReimbursementSection = empReimFlag === 1 || empReimFlag === true;

      // Load available deduction/reimbursement types for the selected employee
      this.loadEmployeeDeductionsTypes(selectedValue.empId);
    });
    this.employeeDeductionForm.get('deductionType')?.valueChanges.subscribe((selectedValue: any) => {
      // clear selections when type changes
      this.clearMonthSelections();

      if (!selectedValue) {
        // If no type selected, keep sections as per selected employee (no change).
        return;
      }

      // Use the employeeDeductions array (loaded earlier) to find selected type metadata.
      // This assumes your API returns objects with flags like `is_deduction` and `is_reimbursement`.
      const selType = this.employeeDeductions.find((t: any) => t.id == selectedValue);

      if (selType) {
        const typeDed = selType?.is_deduction ?? selType?.deduction ?? null;
        const typeReim = selType?.is_reimbursement ?? selType?.reimbursement ?? null;

        // If the type explicitly indicates deduction/reimbursement, use that to show/hide sections.
        // Fallback: if the type has a `type` or `component_name` you can use that to decide.
        if (typeDed !== null || typeReim !== null) {
          this.showDeductionSection = typeDed === 1 || typeDed === true;
          this.showReimbursementSection = typeReim === 1 || typeReim === true;
        }
      }

      // Also ensure months for this employee+type are loaded (if your backend requires both)
      const emp = this.employeeDeductionForm.get('employeeName')?.value;
      if (emp && selType) {
        this.loadMonthsForDeduction(emp.empId, selectedValue);
      }
    });
    this.searchControl.valueChanges.subscribe(searchText => {
      this.filterEmployees(searchText);
    });

    this.searchControlforType.valueChanges.subscribe(searchText => {

      this.filterDeductionsTypes(searchText);
    });
  }
  updateReimbursementAmountValidators() {
    const control = this.employeeDeductionForm.get('reimbursementAmount');
    if (this.showReimbursementSection) {
      control?.setValidators([Validators.required, Validators.min(0.01)]);
    } else {
      control?.clearValidators();
      control?.setValue(null); // Optionally clear value when hidden
    }
    control?.updateValueAndValidity();
  }


  initializeForms(): void {
    this.managerForm = this.formBuilder.group({
      componentName: ["", [Validators.required]],
      months: ["", [Validators.required]],
      isDeduction: [false],
      isReimbursement: [false]
    });

    this.employeeDeductionForm = this.formBuilder.group({
      employeeName: ["", [Validators.required]],
      deductionType: ["", [Validators.required]],
      deductionAmount: ["", [Validators.required, Validators.min(0.01)]],
      reimbursementAmount: ["", [Validators.required, Validators.min(1)]]
    });
  }

  // Initialize Data
  initializeData(): void {
    this.loadActiveDeductions();
    this.loadEmployeesForDedAndReimbursements();
  }

  // Tab Methods
  onTabChange(event: any): void {
    this.selectedTabIndex = event.index;
    if (event.index === 0) {
      this.loadActiveDeductions();
    }
  }
  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }

  }
  getPageSizes(): number[] {
    var customPageSizeArray = [];

    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);

    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }
  // Load Employees for Salary Processing (for dropdown)
  loadEmployeesForDedAndReimbursements(): void {
    this.loading = true;
    this.payrollService.getEmployeesForDedAndReimbursements().subscribe({
      next: (response: any) => {
        if (response && response.data.length > 0) {
          this.employees = response.data.map((emp: any) => ({
            empId: emp.id,
            name: emp.employee_name,
            code: emp.employee_code,
            designation: emp.designation,
            location: emp.location
          }));
          this.filteredEmployees = [...this.employees];
        }
        this.loading = false;
      },
      error: (error: any) => {
        console.error('Error loading employees:', error);
        this.loading = false;
      }
    });
  }



  loadEmployeeDeductionsTypes(employeeId: any): void {
    this.loading = true;
    this.payrollService.getDedAndReimForEmployee(employeeId).subscribe({
      next: (response: any) => {
        if (response && response.data.length > 0) {
          this.employeeDeductions = response.data;
          this.filteredEmployeeDeductions = [...this.employeeDeductions];

          // Load months for the first deduction by default

        }
        this.loading = false;
      },
      error: (error: any) => {
        console.error('Error loading employee deductions:', error);
        this.loading = false;
      }
    });
  }

  // Load available months for deductions
  loadMonthsForDeduction(employeeId: any, edrmId: any): void {
    this.payrollService.getMonthsForDedAndReimbursements(employeeId, edrmId).subscribe({
      next: (response: any) => {
        if (response && response.data.length > 0) {
          this.availableMonths = response.data.map((month: any, index: number) => ({
            id: index,
            month: month.month_id,
            year: month.year_value,
            label: month.label
          }));
        }
        this.updateReimbursementAmountValidators();
      },
      error: (error: any) => {
        console.error('Error loading months:', error);
      }
    });
  }

  // Manager Screen Methods (Tab 1) - Load Active Deductions
  loadActiveDeductions(): void {
    // Get manager ID from session or user context
    this.selectedManagerId = this.userSession.id; // Default manager ID

    if (this.selectedManagerId) {
      this.pageLoading = true;
      this.payrollService.getDedAndReimDetails(null, this.selectedManagerId).subscribe({
        next: (response: any) => {
          if (response && response.data.length > 0) {
            this.dataSource = new MatTableDataSource(response.data);
            this.dataSource.paginator = this.paginator;
            this.dataSource.sort = this.sort;
            this.pageLoading = false;

          }

          else {
            // this.dataSource =  new MatTableDataSource([]);
          }

        },
        error: (error: any) => {
          console.error('Error loading active deductions:', error);
          this.loading = false;
          // this.dataSource = new MatTableDataSource([]);
        }
      });
    }
  }




  resetEmployeeForm(): void {
    this.employeeDeductionForm.reset();
    this.btnDisable = false;
  }

  // Utility Methods
  markFormGroupTouched(formGroup: UntypedFormGroup): void {
    Object.keys(formGroup.controls).forEach(key => {
      const control = formGroup.get(key);
      control?.markAsTouched();
    });
  }

  // helper: build unique key for a month object
  private monthKey(m: { month_id?: number, year_value?: number, month?: number, year?: number }): string {
    const year = m.year_value ?? m.year;
    const month = m.month_id ?? m.month;
    return `${year}-${month}`; // unique
  }

  isMonthSelectedInDeduction(m: any): boolean {
    return this.selectedDeductionMonths.indexOf(this.monthKey(m)) !== -1;
  }

  isMonthSelectedInReimbursement(m: any): boolean {
    return this.selectedReimbursementMonths.indexOf(this.monthKey(m)) !== -1;
  }

  toggleDeductionMonth(checked: boolean, m: any): void {
    const key = this.monthKey(m);
    if (checked) {
      if (!this.isMonthSelectedInDeduction(m)) {
        this.selectedDeductionMonths.push(key);
      }
      const idxR = this.selectedReimbursementMonths.indexOf(key);
      if (idxR !== -1) this.selectedReimbursementMonths.splice(idxR, 1);
    } else {
      const idx = this.selectedDeductionMonths.indexOf(key);
      if (idx !== -1) this.selectedDeductionMonths.splice(idx, 1);
    }
  }

  toggleReimbursementMonth(checked: boolean, m: any): void {
    const key = this.monthKey(m);
    if (checked) {
      if (!this.isMonthSelectedInReimbursement(m)) {
        this.selectedReimbursementMonths.push(key);
      }
      const idxD = this.selectedDeductionMonths.indexOf(key);
      if (idxD !== -1) this.selectedDeductionMonths.splice(idxD, 1);
    } else {
      const idx = this.selectedReimbursementMonths.indexOf(key);
      if (idx !== -1) this.selectedReimbursementMonths.splice(idx, 1);
    }
  }

  clearMonthSelections(): void {
    this.selectedDeductionMonths = [];
    this.selectedReimbursementMonths = [];
  }
  private toTwoDecimalString(value: number): string {
    // Avoid floating precision issues
    return (Math.round((value + Number.EPSILON) * 100) / 100).toFixed(2);
  }

  submitEmployeeDeduction(): void {
    if (!this.employeeDeductionForm.valid) {
      this.markFormGroupTouched(this.employeeDeductionForm);
      return;
    }

    // get form values
    const formData = this.employeeDeductionForm.value;
    const employee = formData.employeeName;
    const edrmId = formData.deductionType; // edrm_id
    if (!employee || !edrmId) {
      console.error('Employee or deduction type missing');
      return;
    }

    // convert selected keys back to month/year
    const deductionMonths = this.selectedDeductionMonths.map(k => {
      const [yearStr, monthStr] = k.split('-');
      return { month_id: Number(monthStr), year_id: Number(yearStr) }; // note year_id naming to match payload shape
    });

    const reimbursementMonths = this.selectedReimbursementMonths.map(k => {
      const [yearStr, monthStr] = k.split('-');
      return { month_id: Number(monthStr), year_id: Number(yearStr) };
    });

    // validate at least one month selected for whichever sections are visible
    if (this.showDeductionSection && deductionMonths.length === 0) {

      this.dialog.open(ReusableDialogComponent, {
        position: { top: `70px` },
        disableClose: true,
        data: 'Please select at least one deduction month.'
      });
      return;
    }
    if (this.showReimbursementSection && reimbursementMonths.length === 0) {

      this.dialog.open(ReusableDialogComponent, {
        position: { top: `70px` },
        disableClose: true,
        data: 'Please select at least one reimbursement month.'
      });
      return;
    }
    if (this.showDeductionSection && this.showReimbursementSection &&
      deductionMonths.length === 0 && reimbursementMonths.length === 0) {
      // alert('Please select at least one month for deduction or reimbursement.');
      this.dialog.open(ReusableDialogComponent, {
        position: { top: `70px` },
        disableClose: true,
        data: 'Please select at least one month for deduction or reimbursement.'
      });
      return;
    }

    // Build arrays
    const deductionsPayload: any[] = [];
    const reimbursementsPayload: any[] = [];

    // helper to push items for a month array
    const buildEntries = (monthsArr: { month_id: number, year_id: number }[], isDeduction: boolean, totalAmountValue: number) => {
      if (!monthsArr || monthsArr.length === 0) return;
      const numMonths = monthsArr.length;
      // installment per month: equal split
      const installmentRaw = totalAmountValue / numMonths;
      const installmentStr = this.toTwoDecimalString(installmentRaw);
      const totalStr = this.toTwoDecimalString(totalAmountValue);

      monthsArr.forEach(m => {
        const entry = {
          employee_id: employee.empId ?? employee.id,
          edrm_id: edrmId,
          month_id: m.month_id,
          year_id: m.year_id,
          total_amount: totalStr,
          installment_amount: installmentStr,
          deduction_or_reimbursement: isDeduction ? 1 : 0
        };
        if (isDeduction) deductionsPayload.push(entry);
        else reimbursementsPayload.push(entry);
      });
    };

    // parse amounts from form; if fields are empty, use 0
    const deductionAmount = Number(formData.deductionAmount ?? 0);
    const reimbursementAmount = Number(formData.reimbursementAmount ?? 0);

    // Compare deductionAmount and reimbursementAmount
    if (reimbursementAmount > deductionAmount) {
      // alert();
      this.dialog.open(ReusableDialogComponent, {
        position: { top: `70px` },
        disableClose: true,
        data: 'Reimbursement amount should be less than or equal to deduction amount.'
      });
      return;
    }

    // only build entries for visible sections (you asked visible sections should be used)
    if (this.showDeductionSection && deductionMonths.length > 0) {
      buildEntries(deductionMonths, true, deductionAmount);
    }
    if (this.showReimbursementSection && reimbursementMonths.length > 0) {
      buildEntries(reimbursementMonths, false, reimbursementAmount);
    }

    // final payload
    const payload = {
      deductions: deductionsPayload,
      reimbursements: reimbursementsPayload
    };

    let data = {
      json_data: JSON.stringify(payload),
      created_by_value: this.userSession.id
    };

    // call your save API (replace with actual service method)
    this.btnDisable = true;
    this.payrollService.setEmployeeDeductionsAndReimbursements(data).subscribe({
      next: (res: any) => {
        // handle success: show message, refresh tables, reset form
        // console.log('Save successful', res);
        if (res && res.status === true) {
          this.payrollService.message(res.data[0].message);
          // Example: reload active list
          this.loadActiveDeductions();
          this.resetEmployeeForm();
          this.clearMonthSelections();
          this.btnDisable = false;
          this.loadActiveDeductions
        }
        this.loadActiveDeductions()
      },
      error: (err: any) => {
        console.error('Save failed', err);
        this.payrollService.message(err.message);
        this.btnDisable = false;
        // show error UI as needed
      }
    });
  }

  filterEmployees(searchText: any) {
    this.filteredEmployees = this.employees.filter((val: any) =>
      val.code.toLowerCase().includes(searchText.toLowerCase()) ||
      val.name.toLowerCase().includes(searchText.toLowerCase()) ||
      val.designation.toLowerCase().includes(searchText.toLowerCase()) ||
      val.location.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredEmployees.length <= 0) {
      this.searchControl.setValue('');
    }
  }

  filterDeductionsTypes(searchText: any) {
    this.filteredEmployeeDeductions = this.employeeDeductions.filter((val: any) =>
      val.component_name.toLowerCase().includes(searchText.toLowerCase())

    );
    if (this.filteredEmployees.length <= 0) {
      this.searchControl.setValue('');
    }
  }

}
