import { Component, OnInit, TemplateRef, ViewChild, ViewContainerRef } from '@angular/core';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { TdsService } from '../../tds.service';
import { MatDialog } from '@angular/material/dialog';
import { PayrollService } from '../../payroll.service';
import { resolve } from 'dns';
import { ReviewAndApprovalsComponent } from 'src/app/modules/leaves/dialog/review-and-approvals/review-and-approvals.component';
import { Router } from '@angular/router';
import { forEach } from 'lodash';

@Component({
  selector: 'app-annual-houserent-approvals',
  templateUrl: './annual-houserent-approvals.component.html',
  styleUrls: ['./annual-houserent-approvals.component.scss']
})
export class AnnualHouserentApprovalsComponent implements OnInit {
  pageLoading:boolean=true;
  @ViewChild('firstPaginator') paginator!: MatPaginator;
  pageLoadingHistory:boolean=true;
  @ViewChild('secondPaginator') paginatorHistory!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  displayedColumns: string[] = ['s_no','empid','employee_name',"house_rent", 'owner_name', 'owner_pan_number', 'actions']
  dataSource: MatTableDataSource<any> = <any>[];
  // emptyData = new MatTableDataSource([{ empty: "row" }]);
  houseRentDetails:any=[];
  financialYear:any;
  info: any = null;
  @ViewChild('popupTemplate', { static: true }) popupTemplate!: TemplateRef<any>;
  userSession:any;
  btnDisable:boolean = false;
  houseRentApprovalHistory:any=[];
  dataSourceHistory: MatTableDataSource<any> = <any>[];
  arrayList:any=[];
  onlyView:boolean=false;
  displayedColumns1: string[] = ['s_no','empid','employee_name',"house_rent", 'owner_name', 'owner_pan_number','submission_status', 'actions']
 

  constructor(
    private tdsService:TdsService,
    private dialog: MatDialog,
    private payrollService : PayrollService,
    private vcr: ViewContainerRef,
    private router : Router,
  ) {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    
   }

  async ngOnInit() {
    this.financialYear  = await this.getFinancialYears();
    this.getHouseRentsForApproval();
    this.getEmployeeHouseRentHistory();
   
  }


  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.dataSource.data.length < 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  getPageSizesHistory(): number[] {
    var customPageSizeArray = [];
    if (this.dataSourceHistory.data.length < 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSourceHistory.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSourceHistory.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSourceHistory.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSourceHistory.data.length);
    return customPageSizeArray;
  }


  getHouseRentsForApproval(){
    this.arrayList =[]
      this.tdsService.getHouseRentsForApproval(this.financialYear).subscribe((result:any) =>{
        if(result.data){
          this.arrayList = result.data;
          this.dataSource = new MatTableDataSource(result.data);
          this.dataSource.paginator = this.paginator;
          this.dataSource.sort = this.sort;
          this.pageLoading = false;
        }
      })
  }

  getFinancialYears() {
    return new Promise((resolve) => {
      this.payrollService.getFinancialYears().subscribe((result: any) => {
        if (result.status && result.data.length) {
          resolve(result.data[0].financial_year)
        } else {
          resolve('')
        }
      });
    });
  }

  approve(val: any) {
    let input = {
      id: val.id,
      status: 'Approved',
      rejectReason: null,
      managerId: this.userSession.id
    }
    this.submitStatus(input, 'House rent approved successfully.')
  }

  reject(val: any) {
    let input = {
      id: val.id,
      status: 'Rejected',
      rejectReason: null,
      managerId: this.userSession.id,
      financialYear: this.financialYear,
      empid: val.emp_id,
    }
    const dialogRef = this.dialog.open(ReviewAndApprovalsComponent, {
      width: '600px', position: { top: `100px` },
      data: { name: "Reason For Rejection", reason: '', }
    });

    dialogRef.afterClosed().subscribe(result => {
      if (result) {
        input.rejectReason = result.reason;
        this.submitStatus(input, 'House rent rejected successfully.')
      }
    });
  }
  closePopup() {
    this.info = null;
    this.vcr.clear();
    this.btnDisable = false;
  }
   
  addProperty(ele: any,view:boolean=false) {
    this.info = ele;
    this.vcr.clear(); // Clear previous views if any
    this.vcr.createEmbeddedView(this.popupTemplate); // Render the popup template
    this.onlyView =view;
  }

  submitStatus(input: any, message: any) {
    this.tdsService.approveEmployeeHouseRent(input).subscribe((results: any) => {
      this.btnDisable = true;
      if (!results || (results.data && results.data[0] && results.data[0].Code) || !results.status) {
        this.tdsService.message('Please try again later.')
        this.btnDisable = false;
      }
      else {
        this.tdsService.message(message)
        this.closePopup()
        this.getHouseRentsForApproval();
        this.getEmployeeHouseRentHistory();
        // this.navigationToCurrentPage();
      }
    })
  }


  navigationToCurrentPage(){
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Payroll/annualHouserentApprovals"]));
  }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
  
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

  applyFilterHistory(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSourceHistory.filter = filterValue.trim().toLowerCase();
  
    if (this.dataSourceHistory.paginator) {
      this.dataSourceHistory.paginator.firstPage();
    }
  }


  getEmployeeHouseRentHistory(){
    this.tdsService.getEmployeeHouseRentHistory(this.financialYear).subscribe((results: any) => {
      if(results && results.status){
        results.data.forEach((e:any) => {
          if(e.submission_status === 'Approved' || e.submission_status === 'Rejected'){
            this.houseRentApprovalHistory.push(e)
          }
        });
        this.dataSourceHistory = new MatTableDataSource(this.houseRentApprovalHistory)
        this.dataSourceHistory.paginator =this.paginatorHistory;
        this.pageLoadingHistory = results.data.length <= 20 ? true : false;
      }
    })

  }
}
