  /* ---------------- DROPDOWNS ---------------- */
  worklocationDetails: any[] = [];
  worklocationDetails_assign:any[] = [];
  managersDetails: any[] = [];
    managersDetails_assign: any[] = [];
  attendanceData: any[] = [];
  filteredEmployees: any[] = [];
   filteredEmployees_assign: any[] = [];
  employeelist:any =[];
  employeelist_assign:any =[];
  selectedLocations: number[] = [];
  selectedLocations_assign: number[] = [];
  selectedLocation: any = null;
  selectedLocation_assign: any = null;
  selectedManagers: any = [];
  selectedManagers_assign: any = [];
  selectedManager: any = null;
  selectedManager_assign: any = null;
  selectedManagerId: number | null = null;
  isProcessing:any = false;
 selectedEmployee: number | null = null;
 selectedEmployee_assign: number | null = null;
 selectedRow:any = {};
  expandedElement: any | null = null;
  // 🔹 Change assignment section state
  assignmentChecked = false;
  assignmentEmployeeId: number | null = null;
  assignmentEmployeeName = '';
  clientList: any[] = [];          // full API data
// filteredClientList: any[] = [];  // table datasource
searchText: string = '';
clientSearchText: string = '';




  /* ---------------- TABLE ---------------- */
  totalsDataSource = new MatTableDataSource<any>([]);
  clientListDataSource = new MatTableDataSource<any>([]);
  filteredClientList = new MatTableDataSource<any>([]);
  selection = new SelectionModel<any>(true, []);


  totalsColumns: string[] = ['sno','responsible_emp_code', 'responsible_emp_name','total_clients','self_added_clients','assigned_clients','final_price', 'responsible_emp_status',
    // 'amount_collected', 
    'action'];
  clientColumns: string[] = ['select','sno','client_name', 'city','state','client_status','assigned_by', 'assigned_on','status_message' ];

  onChange(row: any) {
    this.expandedElement = this.expandedElement === row ? null : row;
  }
  @ViewChild('clientPaginator') clientPaginator!: MatPaginator;
  @ViewChild('totalsPaginator') totalsPaginator!: MatPaginator;
