    getClientListBackground(row:any){  
      let clbColor = 'white';                
      if(row && row.status_message && row.status_message == 'Not assigned')
        clbColor = 'lightred';        
      else if(row && row.assigned_id > 0)
        clbColor = 'lightgreen';
      return clbColor;
    }

    loadClientsTotalsForSelectedEmployee() {
      if(this.searchForm.invalid){
              this.searchForm.markAllAsTouched();
              if(this.is_super_admin && this.userRole == 'Manager') return;
              else if(this.userRole == 'Manager' && this.searchForm.controls.Users.invalid) return;
        } 

      let obj =  this.buildRequestForSummary();
          obj.employees = [];
          obj.employees.push(this.selectedEmployee);
          obj.employees.push(this.selectedEmployee_assign);
       
      this.pageLoading = true;
      this.spinner.show();
      this.crmService.getCrmClientsWithEmpStatusAsOnDate(obj).subscribe((res: any) => {
        this.spinner.hide();
        if(res && res.status && res.data){
          res.data.forEach((r:any)=>{
              for (let c of this.totalsDataSource.data) {                     
                if(c.responsible_empid == r.responsible_empid){      
                    c.total_clients = r.total_clients;
                    c.self_added_clients = r.self_added_clients; 
                    c.assigned_clients = r.assigned_clients;
                    // c.amount_collected = r.amount_collected;
                    c.final_price = r.final_price;
                     break; //  stops loop
                }
              }
            });
        }
          this.pageLoading = false;
        });
    }
applySearchFilter(event?: any) {
  this.searchText = this.clientSearchText?.trim().toLowerCase() || '';
  this.applyClientFilters();
}



applyClientFilters() {
  if (!this.clientList || !this.clientList.length) {
    this.filteredClientList.data = [];
    return;
  }

  let data = [...this.clientList];

  // Radio filter
  if (this.selectedClientType === 'own') {
    data = data.filter(d => d.assigned_status !== 'Assigned'); // Self-added
  } else if (this.selectedClientType === 'assigned') {
    data = data.filter(d => d.assigned_status === 'Assigned');
  }

  //  Search filter
  if (this.searchText) {
    const text = this.searchText.toLowerCase();
    data = data.filter(d =>
      (d.client_name || '').toLowerCase().includes(text) ||
      (d.city || '').toLowerCase().includes(text) ||
      (d.state || '').toLowerCase().includes(text) ||
      (d.client_status || '').toLowerCase().includes(text) ||
      (d.assigned_by || '').toLowerCase().includes(text) ||
      (d.status_message || '').toLowerCase().includes(text) ||
      (d.assigned_on ? new Date(d.assigned_on).toLocaleDateString().toLowerCase().includes(text) : false)
    );
  }

  this.filteredClientList.data = data;

  if (this.filteredClientList.paginator) {
    this.filteredClientList.paginator.firstPage();
  }
}




