import { Component, OnInit,ViewChild,Inject,LOCALE_ID, TemplateRef } from '@angular/core';
import { AbstractControl, UntypedFormGroup,UntypedFormBuilder, ValidationErrors, ValidatorFn, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { MatSort } from '@angular/material/sort';
import { DatePipe } from '@angular/common';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { ComfirmationDialogComponent } from 'src/app/pages/comfirmation-dialog/comfirmation-dialog.component';
import { ClaimsService } from '../../claims.service';
import { MAT_DATE_LOCALE, MAT_DATE_FORMATS, DateAdapter } from '@angular/material/core';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { NgxSpinnerService } from 'ngx-spinner';
import { TranslateService } from '@ngx-translate/core';
import { MatSnackBar } from '@angular/material/snack-bar';
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
export interface UserData {
  rbs_type: string;
  payslip_name: string;
  accounts_name: string;
  notes: string;
  status: string;
  id: number;
  total: number;
}

@Component({
  selector: 'app-claims-reimbursement-types',
  templateUrl: './claims-reimbursement-types.component.html',
  styleUrls: ['./claims-reimbursement-types.component.scss'],
  providers: [
    {provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE]},
    {provide: MAT_DATE_FORMATS, useValue: MY_FORMATS},
  ],
})
export class ClaimsReimbursementTypesComponent implements OnInit {
  rbsTypeForm!: UntypedFormGroup;
  userSession:any;
  pipe = new DatePipe(this.locale);
  issubmitted: boolean = false;
  isvalid: boolean = false;
  isView: boolean = false;
  isAdd: boolean = false;
  isdata: boolean = true;
  isEdit: boolean = true;
  isSave: boolean = false;
  isDelete: boolean = true;
  enable: any = null;
  valid: boolean = false;
  rbsData:any =[];
  displayedColumns: string[] = ['sno','rbs_type','payslip_name','accounts_name','control_amount','effective_date', 'rbs_status', 'Action'];
  minDate:any;
  arrayValue: any;
  effective_date:any= new Date();
  dataSource: MatTableDataSource<UserData> = <any>[];
  selected_row:any;
  pageLoading = true;
  selectedRbsTypeId: number | null = null;
  priceRevisionsData: any[] = [];
  @ViewChild('dialogTemplate') dialogTemplate!: TemplateRef<any>;

  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort)sort!: MatSort;
   // messagesDataList: any = [];

  constructor(@Inject(LOCALE_ID) private locale: string,private claims:ClaimsService,private Company:CompanySettingService,private formBuilder: UntypedFormBuilder,
    private router: Router, private dialog: MatDialog,private spinner: NgxSpinnerService, private translate: TranslateService, private snackBar: MatSnackBar) {
      this.userSession = JSON.parse(sessionStorage.getItem('user') || '');

     }


  ngOnInit(): void {
    this.rbsTypeForm = this.formBuilder.group({
      rbs_type: ["",[Validators.required ,Validators.maxLength(50)]],
      payslip_name: ["",[Validators.required ]],
      accounts_name: ["",[Validators.required ]],
      notes: ["",[Validators.required ]],
      control_amount: ['',[Validators.required,Validators.min(0.01), Validators.pattern(/^[1-9]\d*(\.\d+)?$/)]],
      effective_date: ["", [Validators.required]],  
      rbs_status:["",[Validators.required]],
    }, );

    this.minDate = new Date();
    this.rbsTypeForm.controls.effective_date.setValue(new Date());

    this.getReimbursementTypes();
  }

  getReimbursementTypes() {
    this.rbsData = [];
    this.spinner.show();
    this.claims.getClaimsReimbursementTypes(1, 100).subscribe((res: any) => {
      this.spinner.hide();
  
      if (res.status) {
        this.rbsData = res.data;
        this.arrayValue = res.statusValues;
      }
  
      this.dataSource = new MatTableDataSource(res.data);
      this.dataSource.paginator = this.paginator;
      this.dataSource.sort = this.sort;
    });
  }
  



  Add() {
    this.selected_row = null;
    this.enable = null;
    this.isAdd = true;
    this.isEdit=false;
    this.isView=false;
    this.isdata = false;
    this.rbsTypeForm.controls.rbs_type.setValue('');
    this.rbsTypeForm.controls.payslip_name.setValue('');      
    this.rbsTypeForm.controls.accounts_name.setValue('');
    this.rbsTypeForm.controls.notes.setValue('');
    this.rbsTypeForm.controls.control_amount.setValue('');
    this.rbsTypeForm.controls.effective_date.setValue('');
    this.rbsTypeForm.controls.rbs_status.setValue(1);
  }

  cancel() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Claims/ClaimsReimbursementTypes"]));
  }


edit(row: any) {
  this.isView = false;
  this.selected_row = row;
    this.enable = row.id;
    this.isAdd = true;
    this.isEdit=true;
    this.isdata = false;
    this.rbsTypeForm.controls.rbs_type.setValue(row.rbs_type);
    this.rbsTypeForm.controls.payslip_name.setValue(row.name_in_payslip);      
    this.rbsTypeForm.controls.accounts_name.setValue(row.name_in_accounts);
    this.rbsTypeForm.controls.effective_date.setValue(new Date(row.effective_date))
    this.rbsTypeForm.controls.notes.setValue(row.notes);
    this.rbsTypeForm.controls.control_amount.setValue(parseInt(row.control_amount, 10)); 
    this.rbsTypeForm.controls.rbs_status.setValue(row.rbs_status);
  }

  view(row: any) {
    this.isView = true;
    this.isEdit=false;
    this.rbsTypeForm.disable();

      //this.selected_row = row;
      //this.enable = row.id;
      this.isAdd = true;
      this.isdata = false;
      this.rbsTypeForm.controls.rbs_type.setValue(row.rbs_type);
      this.rbsTypeForm.controls.payslip_name.setValue(row.name_in_payslip);      
      this.rbsTypeForm.controls.accounts_name.setValue(row.name_in_accounts);
      this.rbsTypeForm.controls.effective_date.setValue(new Date(row.effective_date))
      this.rbsTypeForm.controls.notes.setValue(row.notes);
      this.rbsTypeForm.controls.control_amount.setValue(row.control_amount);
      this.rbsTypeForm.controls.rbs_status.setValue(row.rbs_status);

    }
    
    changeStatus(status:any,row:any){
      let typeTranslated = this.translate.instant(row.rbs_type.toUpperCase());
      let message = this.translate.instant('CONFIRM_CHANGE_STATUS',{ type: this.translate.instant(row.rbs_type) });
        //  { type: row.rbs_type });  
      let dialogRef = this.dialog.open(ComfirmationDialogComponent, { position: { top: `70px` },   disableClose: true,
        data: { message: message,
            YES: 'YES', NO: 'NO'
          // message: "Are you sure you want to change status for "+ row.rbs_type +" ?", YES: 'YES', NO: 'No' 
        }
      });  
      dialogRef.afterClosed().subscribe(result => {
        if (result === 'YES') {
            if(row.id > 0){
              let data = {
                rbs_type_id: row.id,
                rbs_status:status,
                action_on:this.pipe.transform(new Date(), 'yyyy-MM-dd HH:mm:ss'),
                action_by:this.userSession.id
              }
              this.spinner.show();
              this.claims.setClmRbsTypeStatus(data).subscribe((res:any)=>{
                this.spinner.hide();
                if(res.status) {
                  let dialogRef = this.dialog.open(ReusableDialogComponent, { position: { top: `70px` },  disableClose: true, 
                    // data:res.data[0].resultmsg
                     data: res.data[0].resultmsg 
                ? this.translate.instant(res.data[0].resultmsg) 
                : this.translate.instant('STATUS_UPDATED_SUCCESSFULLY')
                   });
                  dialogRef.afterClosed().subscribe(result => {    
                    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>  this.router.navigate(["/Claims/ClaimsReimbursementTypes"]));
                    this.dataSource.paginator = this.paginator;
                    });
                }
              else {
                let dialogRef = this.dialog.open(ReusableDialogComponent, { position: { top: `70px` }, disableClose: true,
                  data: (res && res.data && res.data[0] && res.data[0].resultmsg)? 
                  // res.data[0].resultmsg: "Unable to update Status. Please try again. "
                   this.translate.instant(res.data[0].resultmsg)
                : this.translate.instant('UNABLE_TO_UPDATE_STATUS')
                });
              }
            })
          }
        }
      });  
 }



 AddData() {
  if (!this.rbsTypeForm.valid) {
    return;
  }

  let data = {
    rbs_type_id: this.selected_row && this.selected_row.id ? this.selected_row.id : 0,  // 1st parameter
    rbs_type: this.rbsTypeForm.controls.rbs_type.value.trim().replace(/\s+/g, ' '),      // 2nd parameter
    payslip_name: this.rbsTypeForm.controls.payslip_name.value.trim().replace(/\s+/g, ' '), // 3rd parameter
    accounts_name: this.rbsTypeForm.controls.accounts_name.value.trim().replace(/\s+/g, ' '), // 4th parameter
    notes: this.rbsTypeForm.controls.notes.value.trim().replace(/\s+/g, ' '),           // 5th parameter
    amount: Number(this.rbsTypeForm.controls.control_amount.value).toFixed(2),          // 6th parameter
    effective_fromdate: this.pipe.transform(this.rbsTypeForm.controls.effective_date.value, 'yyyy-MM-dd HH:mm:ss'), // 8th parameter
    rbs_status: this.rbsTypeForm.controls.rbs_status.value,                             // 7th parameter
    created_on: this.pipe.transform(new Date(), 'yyyy-MM-dd HH:mm:ss'),                 // 9th parameter
    created_by: this.userSession.id                                                     // 10th parameter
  };



  if (data.rbs_type && data.rbs_type.toString().length) {
      this.setClmRbsType(data);
  }
}


 setClmRbsType(data:any){
    if(data.rbs_type && data.rbs_type.toString().length){
      this.spinner.show();
      this.claims.setClmRbsType(data).subscribe((res:any)=>{
        this.spinner.hide();        
        if(res.status ) {
            if( res.data && res.data[0] && res.data[0].successState == 0){              
              let dialogRef = this.dialog.open(ReusableDialogComponent, {
                position: { top: `70px` },
                disableClose: true,
                data:res.data[0].resultmsg,
              });
              dialogRef.afterClosed().subscribe(result => {
                this.enable = null;
                this.selected_row = null;
                this.isdata = true;
                this.isAdd = false;
                this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
                this.router.navigate(["/Claims/ClaimsReimbursementTypes"]));
                 // this.dataSource.paginator = this.paginator;
              });
            }     
            else {
              let dialogRef = this.dialog.open(ReusableDialogComponent, {
                position: { top: `70px` },
                disableClose: true,
                data:res.data[0].resultmsg,
              });
            } 
         
        }
        else {
          let dialogRef = this.dialog.open(ReusableDialogComponent, {
            position: { top: `70px` },
            disableClose: true,
            data: (res && res.data && res.data[0] && res.data[0].resultmsg)? res.data[0].resultmsg: "Unable to add Reimbursement type. Please try again. "
          });
        }
    })
  }
 }
  canceledit(event: any, id: any) {
    this.isdata = true;
    this.enable = null;
    this.isEdit = true;
    this.isSave = false;
    this.isDelete = true;
    this.ngOnInit();
  }

  getPageSizes(): number[] {
    var customPageSizeArray = [];

    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);

    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

    /**Search functionality */
    applyFilter(event: Event) {
      const filterValue = (event.target as HTMLInputElement).value;
      this.dataSource.filter = filterValue.trim().toLowerCase();
      if (this.dataSource.paginator) {
        this.dataSource.paginator.firstPage();
      }

    }

    showPriceRevisions(p_reimbursement_type_id: number) {
      // Fetch the price revisions first
      this.getPriceRevisions(p_reimbursement_type_id);
  
      // After fetching the revisions, open the dialog
      const dialogConfig = {
        width: '600px',
      };
  
      // Use the template reference to open the dialog
      this.dialog.open(this.dialogTemplate, dialogConfig);
    }
  
    getPriceRevisions(p_reimbursement_type_id: number) {
      this.claims.getClmRbsPriceRevisions(p_reimbursement_type_id).subscribe((res: any) => {
        if (res.status && res.data) {
          this.priceRevisionsData = res.data;
        }
      }, error => {
        console.error('Error fetching price revisions:', error);
      });
    }


    disableStatus(row:any){
      if(row && row.is_default)
        return true;
      else if(this.enable == row.id)
        return true;
      else return false;
    }

    onChangeRadio(){
       const message = this.translate.instant('STATUS_UPDATED_SUCCESSFULLY');
  
    this.snackBar.open(message, '', { duration: 3000 });

    }
    getFormattedDateTime(date:any){
      return this.claims.getFormattedDateTime(date);
    }
    getStatus(row:any){
      let status  = '';
      this.arrayValue.forEach((e:any) => {
        if(e.id === row.rbs_status){
          status = e.name;
        }
      });
      return status;
    }

}


