import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { LearnService } from '../../learn.service';
import { DomSanitizer, SafeResourceUrl } from '@angular/platform-browser';
import { take } from 'rxjs/operators';

@Component({
  selector: 'app-lms-view-course',
  templateUrl: './lms-view-course.component.html',
  styleUrls: ['./lms-view-course.component.scss'],
})
export class LmsViewCourseComponent implements OnInit {
  courseId: number = 0;
  course: any;
  modules: any[] = [];
  sectionsMap = new Map<number, any[]>();
  roleId: number = 1;

  selectedSection: any = null;
  safeDocumentUrl: SafeResourceUrl | null = null;
  quizSection: any = null;
  userSession: any;
  safeVideoUrl: SafeResourceUrl | null = null; // for binding to video
  rawVideoBlobUrl: string | null = null; // to keep for revocation

  summaryText: string = '';
  resources: Array<{ resource_name: string; resource_content: string }> = [];
  loadingSummary = false;
  loadingResources = false;

  safeDocumentUrlWithParams: SafeResourceUrl | null = null;

  videoBlobUrl: string | null = null;
  pdfBlobUrl: string | null = null;
  loadingContent: boolean = false; // optional spinner flag

  constructor(
    private route: ActivatedRoute,
    private learnService: LearnService,
    private domSanitizer: DomSanitizer,
    private router: Router
  ) {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');

    const roles: any[] = this.userSession.roles || [];

    // look for an Employee role (role_name exactly "Employee" or where role_id === 1)
    const employeeRole = roles.find(
      (r) => r.role_name?.toLowerCase() === 'employee' || r.role_id === 1
    );

    if (employeeRole) {
      this.roleId = employeeRole.role_id;
    } else if (roles.length) {
      // no employee, so just take the first one
      this.roleId = roles[0].role_id;
    } else {
      console.warn('No roles found for user, defaulting roleId to 0');
    }
  }

  ngOnInit(): void {
    const idParam = this.route.snapshot.paramMap.get('id');
    if (idParam) {
      this.courseId = +idParam;
      this.loadCourseDetails();
      this.loadModules();
    } else {
      console.error('No course ID provided in the URL');
    }
  }

  loadCourseDetails(): void {
    const userId = this.userSession.id;

    this.learnService
      .get_lms_course(this.courseId, userId, 0, 0, 0, 0, 4)
      .subscribe({
        next: (data: any) => {
          if (data.courses && Array.isArray(data.courses)) {
            this.course = data.courses[0];
          } else {
            this.course = data.course || data;
          }
        },
        error: (err: any) =>
          console.error('Error fetching course details', err),
      });
  }

  loadModules(): void {
    this.learnService.getModules(0, this.courseId).subscribe({
      next: (data: any) => {
        this.modules = data.modules;
        this.modules.forEach((module, i) => this.loadSections(module, i));
      },
      error: (err) => console.error('Error fetching modules', err),
    });
  }

  loadSections(module: any, index: number): void {
    const userId = this.userSession.id;
    const roleId = this.roleId;
    this.learnService.getSections(userId, 0, module.id, roleId).subscribe({
      next: (data: any) => {
        const sections = data.sections || data.modules || [];
        this.sectionsMap.set(module.id, sections);
        if (index === 0 && sections.length > 0 && !this.selectedSection) {
          this.onSectionClick(sections[0]);
        }
      },
      error: (err) =>
        console.error(`Error fetching sections for module ${module.id}`, err),
    });
  }

  getProgress(course: any): number {
    if (!course.total_sections || course.total_sections === 0) return 0;
    const completed = course.completed_sections || 0;
    return Math.floor((completed / course.total_sections) * 100);
  }

  onSectionClick(section: any): void {
    if (section.status === 0) {
      return;
    }

    // revoke previous blob URLs
    if (this.videoBlobUrl) {
      this.learnService.revokeObjectUrl(this.videoBlobUrl);
      this.videoBlobUrl = null;
    }
    if (this.pdfBlobUrl) {
      this.learnService.revokeObjectUrl(this.pdfBlobUrl);
      this.pdfBlobUrl = null;
    }

    this.selectedSection = section;
    this.quizSection = null;

    // reset UI state
    this.summaryText = '';
    this.resources = [];
    this.loadingSummary = false;
    this.loadingResources = false;

    // load content as blob and convert
if (section.content_type === 'video') {
  this.loadingContent = true;
 
  this.learnService
    .fetchBlob(section.content)
    .pipe(take(1))
    .subscribe({
      next: (blob) => {
        // revoke previous if any
        if (this.rawVideoBlobUrl) {
          this.learnService.revokeObjectUrl(this.rawVideoBlobUrl);
          this.rawVideoBlobUrl = null;
          this.safeVideoUrl = null;
        }
 
        this.rawVideoBlobUrl = this.learnService.createObjectUrl(blob);
        this.safeVideoUrl = this.domSanitizer.bypassSecurityTrustResourceUrl(this.rawVideoBlobUrl);
      },
      error: (err) => {
        console.error('Error fetching video blob', err);
      },
      complete: () => {
        this.loadingContent = false;
      },
    });
 
  // clear document-related
  this.safeDocumentUrl = null;
  this.safeDocumentUrlWithParams = null;
}
    
    else if (section.content_type === 'document') {
      this.loadingContent = true;
      this.learnService
        .fetchBlob(section.content)
        .pipe(take(1))
        .subscribe({
          next: (blob) => {
            this.pdfBlobUrl = this.learnService.createObjectUrl(blob);
            const urlWithParams = this.pdfBlobUrl + '#toolbar=0&navpanes=0';
              this.safeDocumentUrlWithParams =
                this.domSanitizer.bypassSecurityTrustResourceUrl(urlWithParams);
              this.safeDocumentUrl = this.safeDocumentUrlWithParams;
          },
          error: (err) => {
            console.error('Error fetching document blob', err);
          },
          complete: () => {
            this.loadingContent = false;
          },
        });
      // clear video-related
      this.videoBlobUrl = null;
    } else {
      // other content types
      this.safeDocumentUrl = null;
      this.safeDocumentUrlWithParams = null;
      this.videoBlobUrl = null;
      this.loadingContent = false;
    }
  }

  // onSectionClick(section: any): void {
  //   // disable if status = 0
  //   if (section.status === 0) {
  //     return;
  //   }

  //   this.selectedSection = section;
  //   this.quizSection     = null;
  //   if (section.content_type === 'document') {
  //     const url = section.content;
  //     // append #toolbar=0 to suppress PDF viewer controls
  //     const urlWithParams = `${url}#toolbar=0&navpanes=0`;
  //     this.safeDocumentUrl     = this.domSanitizer.bypassSecurityTrustResourceUrl(url);
  //     this.safeDocumentUrlWithParams = this.domSanitizer.bypassSecurityTrustResourceUrl(urlWithParams);
  //   } else {
  //     this.safeDocumentUrl = null;
  //     this.safeDocumentUrlWithParams = null;
  //   }

  //   // reset tabs
  //   this.summaryText      = '';
  //   this.resources        = [];
  //   this.loadingSummary   = false;
  //   this.loadingResources = false;
  // }

  /** Fired when user switches tabs */
  onTabChange(index: number) {
    if (!this.selectedSection) return;

    const secId = this.selectedSection.id;
    if (index === 1) {
      this.fetchSummary(secId);
    } else if (index === 2) {
      this.fetchResources(secId);
    }
  }

  /** Call your getSummary API */
  fetchSummary(sectionID: number) {
    this.loadingSummary = true;
    this.learnService.getSummary(sectionID).subscribe({
      next: (res: any) => {
        this.summaryText = res.performance_stats?.summary || '';
      },
      error: (err) => {
        console.error('Summary error', err);
      },
      complete: () => (this.loadingSummary = false),
    });
  }

  fetchResources(sectionID: number) {
    this.loadingResources = true;
    this.learnService.getResources(sectionID).subscribe({
      next: (res: any) => {
        this.resources = (res.resources || []).map(
          (r: { resource_content: string }) => ({
            ...r,
            // strip the quotes here, so the template just uses a plain string
            resource_content: r.resource_content.replace(/"/g, ''),
          })
        );
      },
      error: (err) => console.error(err),
      complete: () => (this.loadingResources = false),
    });
  }

  selectQuiz(section: any): void {
    this.quizSection = section;
    this.selectedSection = null;
  }

  startQuiz(): void {
    this.router.navigate(['/learning/LmsAssessment'], {
      queryParams: {
        section: this.quizSection.id,
        sectionName: this.quizSection.section_name,
        course: this.courseId,
      },
    });
  }

  ngOnDestroy(): void {
    if (this.rawVideoBlobUrl) {
      this.learnService.revokeObjectUrl(this.rawVideoBlobUrl);
      this.rawVideoBlobUrl = null;
    }
    if (this.pdfBlobUrl) {
      this.learnService.revokeObjectUrl(this.pdfBlobUrl);
      this.pdfBlobUrl = null;
    }
  }
}
