
import { Component, OnInit, ViewChild } from '@angular/core';
import { AbstractControl, UntypedFormGroup, ValidationErrors, ValidatorFn } from '@angular/forms';
import { Router } from '@angular/router';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { CrmService } from '../../crm.service';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { MatSort } from '@angular/material/sort';
import { environment } from 'src/environments/environment';
import { UserData } from 'src/app/modules/attendance/models/EmployeeData';
import { DatePipe } from '@angular/common';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';

@Component({
    selector: 'app-crm-masters-for-status',
    templateUrl: './crm-masters-for-status.component.html',
    styleUrls: ['./crm-masters-for-status.component.scss']
  })
  export class CrmMastersForStatusComponent implements OnInit {
  
  demoForm!: UntypedFormGroup;
  department: any;
  userSession:any;
  pipe = new DatePipe('en-US');
  issubmitted: boolean = false;
  isvalid: boolean = false;
  isView: boolean = false;
  isAdd: boolean = false;
  isdata: boolean = true;
  isEdit: boolean = true;
  isSave: boolean = false;
  enable: any = null;
  valid: boolean = false;



  todayDate:any=new Date();
  displayedColumns: string[] = ['sno','department', 'status', 'Action'];
  departmentData: any = [];
  arrayValue: any;

  dataSource: MatTableDataSource<UserData> = <any>[];
  pageLoading = true;
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  companyDBName:any;
    messagesDataList: any = [];
  
  
  LM: any;
  demoData: UserData[] | undefined;
  dialog: any;
  
  constructor(private router: Router,private crmService:CrmService) {
    this.companyDBName = sessionStorage.getItem('companyName');
   }

  ngOnInit(): void {
  }
  cancel() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
    this.router.navigate(["/crm/client-edit-and-update"]));
  }
  submit() {

    this.saveNewHireData()
  }
  saveNewHireData() {
    throw new Error('Method not implemented.');
  }
  setdepartment() {
  }







edit(w: any, i: any) {
    this.demoForm.controls.department.setValue(i.deptname);
    this.enable = i.id;
    this.isEdit = false;
    this.isSave = true;
    // VOFormElement.get('VORows').at(i).get('isEditable').patchValue(false);

  }
  save(event: any, id: any, deptname: any, datas: any) {

    if (this.demoForm.valid) {
      // this.validatedepartments(deptname)
      this.validateupdatedemo(id,deptname)
      this.enable = null;
      this.isEdit = true;
      this.isSave = false;
      if (this.valid) {
        let data={
          id:id,
          name:deptname,
          created_by: datas.created_by,
          created_on:datas.created_on,
          status:datas.status,
          updated_by:this.userSession.id,
          updated_on:this.pipe.transform(new Date(), 'yyyy-MM-dd')+' '+this.pipe.transform(new Date(), 'HH:mm:ss'),
        }
        this.LM.putDepartments(data).subscribe((data: { status: any; }) => {
          if (data.status) {
            this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
              this.router.navigate(["/Admin/Department"]));
            // this.enable = null;
            let dialogRef = this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              
            });
            this.getDepartments();
  
          } else {
            let dialogRef = this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              
            });
          }
        })
      }
      else {
        this.ngOnInit();
        let dialogRef = this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          // data: this.
        });
  
      }
    }
  }
  validateupdatedemo(id: any, deptname: any) {
    throw new Error('Method not implemented.');
  }
  canceledit(event: any, id: any) {
    this.enable = null;
    this.isEdit = true;
    this.isSave = false;
    this.ngOnInit();

  }

  getDepartments() {
    this.LM.getDepartments('departmentsmaster', null, 1, 1000, this.companyDBName).subscribe((info:any) => {
      if (info.status && info.data.length != 0) {
      this.demoData = info.data;
        this.dataSource = new MatTableDataSource(this.demoData);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;
      }

    })

  }
  getPageSizes(): number[] {
    var customPageSizeArray = [];
    
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
     
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }
  getstatuslist(){
    this.LM.getstatuslists().subscribe((result:any) => {
      if(result.status){
        this.arrayValue = result.data;
      }

    })
  }
  getMessages() {
    let data =
    {
      "code": null,
      "pagenumber": 1,
      "pagesize": 1000
    }
    // this.crmService.getMessagesListApi(data).subscribe((result: any) => {
    //   if(result.status) {
    //     this.messagesDataList = result.data;
    //     this.messagesDataList.forEach((e: any) => {
     
    //       })
    //   } else {
    //     this.messagesDataList = [];
    //   }
    // })
  }

    /**Search functionality */
    applyFilter(event: Event) {
      const filterValue = (event.target as HTMLInputElement).value;
      this.dataSource.filter = filterValue.trim().toLowerCase();
      if (this.dataSource.paginator) {
        this.dataSource.paginator.firstPage();
      }
  
    }

}

