import { DatePipe } from '@angular/common';
import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { UntypedFormBuilder, UntypedFormControl, FormGroup, Validators, FormControl } from '@angular/forms';
import { MatDialog } from '@angular/material/dialog';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { Router } from '@angular/router';
import { ReportsService } from '../../reports.service';
import { DialogDetailComponent } from '../dialog-detail/dialog-detail.component';
import * as XLSX from 'xlsx';
import * as pdfMake from "pdfmake/build/pdfmake";
import * as pdfFonts from "pdfmake/build/vfs_fonts";
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { MatDatepicker } from '@angular/material/datepicker';
import { Moment } from 'moment';
import * as _moment from 'moment';
import { MatSelect } from '@angular/material/select';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { NgxSpinnerService } from 'ngx-spinner';
import { PdfHeaderService } from 'src/app/services/pdf-header-service/pdf-header.service';
(pdfMake as any).vfs = (pdfFonts as any).pdfMake?.vfs;
const htmlToPdfmake = require("html-to-pdfmake");
const moment = _moment;
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  }
};
 
@Component({
  selector: 'app-admin-late-attendance-detailed-report',
  templateUrl: './admin-late-attendance-detailed-report.component.html',
  styleUrls: ['./admin-late-attendance-detailed-report.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class AdminLateAttendanceDetailedReportComponent implements OnInit {
  searchForm: any = FormGroup;
  List: any[] = [];
  activeModule:any = null;
  employeelist: any;
  Users: any;
  minDate = new Date('2020/01/01'); maxDate = new Date();
  userSession: any;
  date = new Date();
  firstDay: any;
  lastDay: any;
  startDate = new Date(this.date.getFullYear(), this.date.getMonth(), 1);
  endDate = new Date(this.date.getFullYear(), this.date.getMonth() + 1, 0);
  dateDayArray: any = [];
  obj: any;
  monthdata: any;
  year: any;
  months = [{ id: 0, month: 'Jan' }, { id: 1, month: 'Feb' }, { id: 2, month: 'Mar' }, { id: 3, month: 'Apr' }, { id: 4, month: 'May' }, { id: 5, month: 'Jun' }, { id: 6, month: 'Jul' }, { id: 7, month: 'Aug' }, { id: 8, month: 'Sep' }, { id: 9, month: 'Oct' }, { id: 10, month: 'Nov' }, { id: 11, month: 'Dec' }]
  headersList: any = [];
  @ViewChild('table') table!: ElementRef;
  companyName: any;
  companyFullName:any;
  constructor(public reportsService: ReportsService, public datePipe: DatePipe,private pdfService: PdfHeaderService,
    public formBuilder: UntypedFormBuilder, private router: Router,
    public dialog: MatDialog, private companyService: CompanySettingService,
    private spinner: NgxSpinnerService) {
    this.companyName = sessionStorage.getItem("companyName");
    this.companyFullName = sessionStorage.getItem('companyFullName');
    this.minFromDate = new Date();
    this.minFromDate.setDate(this.currentDate.getDate() - 90);
    this.maxFromDate = new Date();
    this.minToDate = this.maxFromDate;
    // this.minToDate.setDate(this.currentDate.getDate() - 90);
    this.maxToDate = new Date();
  }
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort) sorter!: MatSort;
  filter = new UntypedFormControl();
  // searchForm = this.formBuilder.group({
  //    fromDate: [new Date()], toDate: [new Date()], Users: ['0'] ,
  //    companylocation: [''],
  //    managers: [''],});
  is_super_admin:any = false;
  searchControl = new FormControl('');
  searchControlforLoc = new FormControl('');
  searchControlforRM = new FormControl('');
  filteredLocations: any = [];
  filteredManagers: any = [];
  dataSource: MatTableDataSource<any> = <any>[];
  displayedColumns: string[] = ['sno', 'empid', 'empname', 'shift', 'attendancedate',  'shiftstarttime', 'actual_in_time', 'latehours'];
  //displayedColumns: string[] = ['sno', 'empname', 'attendancedate', 'firstlogintime', 'lastlogouttime', 'totalhours', 'breaks', 'breaktime', 'productivehours', 'action'];
  isLoading = true;
  is_reports_module:any = false;
  worklocationDetails: any[] = [];
  managersDetails: any[] = [];
  locationIshide: boolean = false;
  locationIschecked: boolean = false;
  mgrIshide: boolean = false;
  mgrIschecked: boolean = false;
  selectedLocations: any = [];
  selectedManagers: any = [];
  filteredEmployees: any = [];
  minFromDate: Date;
  maxFromDate: Date | null;
  minToDate: Date | null;
  maxToDate: Date;
  currentDate: Date = new Date();
  ngOnInit() {
    this.activeModule = JSON.parse(sessionStorage.getItem('activeModule') || '');
     if(this.activeModule && this.activeModule.module && this.activeModule.module?.modulename?.toString().trim().toLowerCase() == 'reports'){
      this.is_reports_module = true;
     }
    this.searchForm = this.formBuilder.group(
      {
        companylocation: ["", Validators.required],
        managers: ["", Validators.required],
        fromDate: [new Date()],
        toDate: [new Date()],
        Users: ['0']
      });
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    if (this.userSession.is_super_admin =="1"){
      this.is_super_admin = true;
    }
    this.getEmployeelist();

    this.getDateArray(this.startDate, this.endDate);
    this.getWorkLocation();
    this.searchControl.valueChanges.subscribe(searchText => {
      this.filterEmp(searchText);
    });
    this.searchControlforLoc.valueChanges.subscribe(searchText => {
      this.filterLocations(searchText);
    });
    this.searchControlforRM.valueChanges.subscribe(searchText => {
      this.filterRM(searchText);
    });
    this.searchForm.get('fromDate')?.valueChanges.subscribe((selectedValue: any) => {
      // this.searchForm.get('toDate').reset();
      this.minToDate = selectedValue._d;
       // Clear TO DATE when FROM DATE changes
      this.searchForm.get('toDate')?.reset();
    })
  }
  ngAfterViewInit() {
  if (this.dataSource) {
    this.dataSource.paginator = this.paginator;
    this.dataSource.sort = this.sorter;
  }
}
  locationSelectAll(select: MatSelect, values: any, array: any) {
    this.locationIshide = true;
    this.locationIschecked = true;
    select.value = values;
    array = values;
    this.searchForm.controls.companylocation.setValue(array)
    let locations = this.searchForm.controls.companylocation.value;
    locations.forEach((e: any) => {
      this.selectedLocations.push(e.id);
    });
    this.getManagersList();
  }

  locationDeselectAll(select: MatSelect) {
    this.locationIshide = false;
    this.locationIschecked = false
    this.selectedLocations = [];
    select.value = [];
    this.searchForm.controls.companylocation.setValue('')
  }

  managerSelectAll(select: MatSelect, values: any, array: any) {
    this.mgrIshide = true;
    this.mgrIschecked = true;
    select.value = values;
    array = values;
    this.searchForm.controls.managers.setValue(array)
    let managerdata = this.searchForm.controls.managers.value;
    managerdata.forEach((e: any) => {
      this.selectedManagers.push(Number(e.manager_emp_id));
    });
    this.getEmployeelist();
  }

  managerDeselectAll(select: MatSelect) {
    this.mgrIshide = false;
    this.mgrIschecked = false
    this.selectedManagers = [];
    select.value = [];
    this.searchForm.controls.managers.setValue('')
    this.selectedManagers = [];
  }

  getWorkLocation() {
    this.managersDetails = [];
    this.worklocationDetails = [];
    this.filteredLocations = [];
    
    if(this.is_reports_module){
      if(this.userSession.is_super_admin){
      this.companyService.getactiveWorkLocation({ id: null, companyName: this.companyName }).subscribe((result) => {
          this.worklocationDetails = result.data;
          this.filteredLocations = this.worklocationDetails;
        })
      }
      else if(this.userSession.is_reports_user){
          this.companyService.getactiveWorkLocationForGeneralManager({ id: this.userSession.id }).subscribe((result) => {
            this.worklocationDetails = result.data;
            this.filteredLocations = this.worklocationDetails;
          });
      }
    }
   else  {
      this.companyService.getactiveWorkLocation({ id: null, companyName: this.companyName }).subscribe((result) => {
          this.worklocationDetails = result.data;
          this.filteredLocations = this.worklocationDetails;
      })
    }    
  }
  onchangeLocation(value: any) {
    this.selectedLocations = [];
    let location = this.searchForm.controls.companylocation.value;
    location.forEach((e: any) => {
      this.selectedLocations.push(e.id);
    });
    this.getManagersList();
  }

  getManagersList() {
    this.managersDetails = [];
    let data = {
      location_id: JSON.stringify(this.selectedLocations),
      companyName: this.companyName
    }
    this.reportsService.getManagersListByLocation(data).subscribe((res: any) => {
      if (res.status && res.data.length > 0) {
        this.managersDetails = res.data;
        this.filteredManagers = this.managersDetails;
      }
    })

  }

  onchangeManager(value: any) {
    this.selectedManagers = [];
    let location = this.searchForm.controls.managers.value;
    location.forEach((e: any) => {
      this.selectedManagers.push(Number(e.manager_emp_id));
    });
    this.getEmployeelist()
  }
  getDateArray(start: any, end: any) {
    const arr = [];
    const dt = new Date(start);
    while (dt <= end) {
      arr.push(new Date(dt));
      dt.setDate(dt.getDate() + 1);
    }
    for (const val of arr) {

      this.obj = {
        date: val,
        day: val.toLocaleDateString('en-US', { weekday: 'short' }),
      };

      this.dateDayArray.push(this.obj);
    }
  }
  getEmployeelist() {
    let obj = {
      "rm_id": JSON.stringify(this.selectedManagers),
      "location_id": JSON.stringify(this.selectedLocations),
    };
    this.reportsService.getLocationWiseEmployeesForManagers(obj).subscribe((res: any) => {
      if (res.status) {
        this.employeelist = [];
        this.employeelist = res.data;
        this.filteredEmployees = this.employeelist;
        this.searchForm.controls.Users.setValue('0');
      }

    });
  }
  //All Employees API
  Searchform() {
     this.addValidators();  
    if (this.searchForm.valid) {
      this.List = [];
      this.dataSource = new MatTableDataSource(this.List);
      this.dataSource.paginator = this.paginator;
      this.dataSource.sort = this.sorter;
      let userId = this.searchForm.controls.Users.value? Number(this.searchForm.controls.Users.value):0;
      let data =  {
          'manager_employee_id': JSON.stringify(this.selectedManagers),
          'location_id': JSON.stringify(this.selectedLocations),
          'employee_id': userId,
          'from_date': this.datePipe.transform(this.searchForm.controls.fromDate.value, "yyyy-MM-dd"),
          'to_date': this.datePipe.transform(this.searchForm.controls.toDate.value, "yyyy-MM-dd"),

        }
      this.spinner.show();
      this.isLoading = true;
      this.reportsService.getAdminLateAttendanceReport(data).subscribe((res: any) => {
        this.spinner.hide();
        this.isLoading = false;
        if(res.status && res.data && res.data.length){
          this.List = res.data;
          this.dataSource = new MatTableDataSource(this.List);
          this.dataSource.paginator = this.paginator;
          this.dataSource.sort = this.sorter;
        }
      });
    }
  }




  // resetform() {
  //   this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
  //     this.router.navigate(["/Attendance/AdminLateAttendanceReport"]));
  // }
  resetform() {
  this.searchForm.reset({
    // companylocation: [],
    managers: [],
    Users: '0',
    fromDate: new Date(),
    toDate: new Date()
  });
   this.searchForm.get('companylocation').clearValidators();
    this.searchForm.get('companylocation').updateValueAndValidity();

    this.searchForm.get('managers').clearValidators();
    this.searchForm.get('managers').updateValueAndValidity();
  // Reset selections
  this.selectedLocations = [];
  this.selectedManagers = [];
  this.filteredEmployees = [];
  this.filteredLocations = this.worklocationDetails;
  this.filteredManagers = [];

  // Reset table
  this.List = [];
  this.dataSource.data = [];

  // Reset date limits
  this.minToDate = new Date();
  this.maxToDate = new Date();

  // Clear search filters
  this.searchControl.setValue('');
  this.searchControlforLoc.setValue('');
  this.searchControlforRM.setValue('');
}
 addValidators() {
    this.searchForm.controls.companylocation.setValidators([Validators.required])
    this.searchForm.controls.managers.setValidators([Validators.required])

    this.searchForm.get('companylocation').updateValueAndValidity();
    this.searchForm.get('managers').updateValueAndValidity();
  }
  openDialog(item: any): void {
    const dialogRef = this.dialog.open(DialogDetailComponent, {
      //  width: '500px',position:{top:`70px`},
      data: { attendanceid: item.attendanceid, }
    });
    dialogRef.afterClosed().subscribe(result => {
    });
  }

  exportAsXLSX() {
    let date = (this.datePipe.transform(this.searchForm.controls.fromDate.value, "MM-YYYY"))
    const ws: XLSX.WorkSheet = XLSX.utils.table_to_sheet(this.table.nativeElement);
    const wb: XLSX.WorkBook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Late Attendance Report');
    XLSX.writeFile(wb, date + '-' + 'Late Attendance Report.xlsx');

  }

  getColor(i: string): String {
    let color = ''
    if (i == "P") {
      return color = 'green'
    } else if (i == "H") {
      return color = '#800000';
    } else if (i == "W") {
      return color = 'blue';
    } else if (i == "L") {
      return color = 'orange';
    } else if (i == "HD") {
      return color = '#ce06e4';

    } else if (i == "WP") {
      return color = '#06c3e4';

    } else if (i == "HP") {
      return color = '#06e471';

    } else if (i == "HL") {
      return color = '#8338ec';
  
    }
    else {
      return color = 'red';
    }
  }
  public exportPDF(): void {
    let date = (this.datePipe.transform(this.searchForm.controls.fromDate.value, "MMMM-YYYY"))
    const pdfTable = this.table.nativeElement;
    var html = htmlToPdfmake(pdfTable.innerHTML);
    pdfMake.createPdf({
      info: {
        title: date + "-" + "Late Attendance Report - Branch Wise",
        author: 'Sreeb tech',
        subject: 'Theme',
        keywords: 'Report'
      },
      footer: function (currentPage, pageCount) {
        return {
          margin: 10,
          columns: [
            {
              fontSize: 9,
              text: [
                {
                  text: 'Page ' + currentPage.toString() + ' of ' + pageCount,
                }
              ],
              alignment: 'center'
            }
          ]
        };
      },
      content: [

        {
          columns: [
            { text: this.companyFullName, style: 'title', alignment: 'center' },
           
          ],
        },
        {
          columns: [
            {
              text: "Late Attendance Detailed Report ",
              style: 'subtitle',
              alignment: 'left',
              fontSize: 14
            },
            { text: `Date: ${date}`, style: 'subtitle', alignment: 'right' },
          ]
        },
        {
          canvas: [   {    type: 'line',   x1: 0,    y1: 0,  x2: 1110,      y2: 0,   lineWidth: 1,     }, ],
        },'\n',
        
        html,

      ],  styles: {
        title: {
          fontSize: 16,
          bold: true,
          margin: [0, 0, 0, 5],
        },
        subtitle: {
          fontSize: 12,
          bold: true,
          margin: [0, 5, 0, 10],
        },
        date: {
          fontSize: 10,
          margin: [0, 0, 0, 5],
        },
        html: {
          alignment: 'center',
        },
      },
      pageOrientation: 'landscape',
      pageSize: 'A3'
      //'portrait'
    }).download("Late Attendance Report.pdf");

  }

  cdate = new UntypedFormControl(moment());
  setMonthAndYear(normalizedMonthAndYear: Moment, datepicker: MatDatepicker<Moment>) {
    const ctrlValue = this.cdate.value!;
    ctrlValue.month(normalizedMonthAndYear.month());
    ctrlValue.year(normalizedMonthAndYear.year());
    this.searchForm.controls.fromDate.setValue(ctrlValue);
    datepicker.close();
  }
  filterEmp(searchText: any) {
    this.filteredEmployees = this.employeelist.filter((val: any) =>
      val.empname.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredEmployees.length <= 0) {
      this.searchControl.setValue('');
    }
  }
  filterLocations(searchText: any) {
    this.filteredLocations = this.worklocationDetails.filter((val: any) =>
      val.cityname.toLowerCase().includes(searchText.toLowerCase()) || val.location.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredLocations.length <= 0) {
      this.searchControlforLoc.setValue('');
    }
  }
  filterRM(searchText: any) {
    this.filteredManagers = this.managersDetails.filter((val: any) =>
      val.manager_name.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredManagers.length <= 0) {
      this.searchControlforRM.setValue('');
    }
  }
  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  generatePDF(){
    let fromDate = this.datePipe.transform(this.searchForm.controls.fromDate.value, "dd-MM-YYYY");
    let toDate = this.datePipe.transform(this.searchForm.controls.toDate.value, "dd-MM-YYYY");
   // let selections =  `Date: ${fromDate} To ${toDate},  Employee: ${this.getEmployeeName()}   Manager: ${ this.userSession.firstname||'' + ' '+ this.userSession.middlename||'' + ' '+ this.userSession.lastname||'' }`;
    let selections = ``;
    if(this.is_super_admin){
      selections = selections + `\n` + `Selected Locations: ${this.getSelectedLocationNames()}`;
      selections = selections + `\n` + `Selected Managers: ${this.getSelectedManagerNames()}`;
      selections = selections + `\n` + `Date: ${fromDate} to ${toDate},    Employee: ${this.getEmployeeName()},     Super Admin: ${ this.userSession.firstname||'' + ' '+ this.userSession.middlename||'' + ' '+ this.userSession.lastname||'' }`;
    }
    else if(this.is_reports_module){
      selections = selections + `\n` + `Selected Locations: ${this.getSelectedLocationNames()}`;
      selections = selections + `\n` + `Selected Managers: ${this.getSelectedManagerNames()}`;
      selections = selections + `\n` + `Date: ${fromDate} to ${toDate},    Employee: ${this.getEmployeeName()},     Reports Admin: ${ this.userSession.firstname||'' + ' '+ this.userSession.middlename||'' + ' '+ this.userSession.lastname||'' }`;
    }  
    
    else selections =  `Date: ${fromDate} to ${toDate},    Employee: ${this.getEmployeeName()},     Manager: ${ this.userSession.firstname||'' + ' '+ this.userSession.middlename||'' + ' '+ this.userSession.lastname||'' }`;
   

  
    let headers = ['Emp Id','Employee', 'Shift', 'Date', 'shift In-time', 'Login time', 'Late Hours']; 
    let tblWidths:any = { 0: { cellWidth: 25 }, 1: { cellWidth: 50 }, 2: { cellWidth: 35 }, 3: { cellWidth: 20 }, 4: { cellWidth: 20 }, 5: { cellWidth: 20 }, 6: { cellWidth: 20 }};
    let tblBody:any = [  
      ...this.List.map(row=>[
        row.empid??'',
        row.empname??'',
        row.shiftname,
        row.attendancedate,
        row.shiftstarttime.slice(0, 5),  
        row.actual_in_time.slice(0, 5),      
        row.latehours.slice(0, 5),
      ])  ];

      let tables = [{ headers:headers,sub_head: '', body: tblBody, widths: tblWidths,table_name:'assignments'}];      
      this.pdfService.generatePDF_common('potrait','Late Attendance Report',selections,tables,'late_attendance_report.pdf');
  }

  getSelectedManagerNames(){
    let selectedManagerNames:string ='';
    if(this.selectedManagers && this.selectedManagers.length){
      this.managersDetails?.forEach((md:any)=>{
        if(this.selectedManagers.includes(md.manager_emp_id)){
          selectedManagerNames = selectedManagerNames + (selectedManagerNames == ''?'': ', ')+ md.manager_name;
        }
      });
    }
    return selectedManagerNames;
  }

  getSelectedLocationNames(){
    let selectedLocationNames:string ='';
    if(this.selectedLocations && this.selectedLocations.length){
      this.worklocationDetails?.forEach((wl:any)=>{
        if(this.selectedLocations.includes(wl.id)){
          selectedLocationNames = selectedLocationNames + (selectedLocationNames == ''?'': ', ')+ wl.location;
        }
      });
    }
    return selectedLocationNames;
  }
  getEmployeeName(){
    let emp_name = '';    
    let userId = this.searchForm.controls.Users.value;
    if (userId == '0' || userId == '') {
      userId=null;
    }
      if(this.filteredEmployees && this.filteredEmployees.length){
        if(userId){
          this.filteredEmployees.forEach((e:any)=>{
            if(e.empid == userId && emp_name == '')
              emp_name = e.empname;
          })
        }
        else emp_name = 'All';      
      }
    return emp_name; 
  } 
}
