import { Component, OnInit } from '@angular/core';
import { FormControl, UntypedFormBuilder, UntypedFormGroup, Validators } from '@angular/forms';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { MatTableDataSource } from '@angular/material/table';
import { Router } from '@angular/router';
import { AttendanceService } from 'src/app/modules/attendance/attendance.service';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { ReportsService } from '../../reports.service';
import { DatePipe } from '@angular/common';
import * as XLSX from 'xlsx';
import { MatDatepickerInputEvent } from '@angular/material/datepicker';
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};


@Component({
  selector: 'app-daily-punch-report',
  templateUrl: './daily-punch-report.component.html',
  styleUrls: ['./daily-punch-report.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },

    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})



export class DailyPunchReportComponent implements OnInit {

  requestform: any = UntypedFormGroup;
  requestform2: any = UntypedFormGroup;
  activeShiftsList: any = [];
  locationsList: any = [];
  filteredShiftTypes: any = [];
  filteredLocations: any = [];
  filteredShiftTypes2: any = [];
  filteredLocations2: any = [];
  minFromDate: Date | undefined;
  maxFromDate: Date | null | undefined;
  minFromDate2: Date | undefined;
  maxFromDate2: Date | null | undefined;
  mintoDate: Date | null | undefined;
  maxtoDate: Date | null | undefined;
  myDateFilter: any;
  currentDate = new Date();
  searchControl = new FormControl('');
  searchControlLocation = new FormControl('');
  searchControl2 = new FormControl('');
  searchControlLocation2 = new FormControl('');
  btnDisable: boolean = false;
  companyName: string | null = null;
  userSession: any;
  headersList: any = [];
  List: any = [];
  List2: any = [];
  headersList2: any = [];
  dataSource: MatTableDataSource<any> = <any>[];
  dataSource2: MatTableDataSource<any> = <any>[];
  noDataFound: boolean = false;
  noDataFound2: boolean = false;

  constructor(
    private formBuilder: UntypedFormBuilder,
    private router: Router,
    public attendanceService: AttendanceService,
    private companyService: CompanySettingService,
    public reportsService: ReportsService,
    public datePipe: DatePipe,
  ) {

    this.minFromDate = new Date();
    this.minFromDate.setDate(this.currentDate.getDate() - 90);
    this.maxFromDate = new Date();
    this.maxFromDate.setDate(this.currentDate.getDate());

    this.minFromDate2 = new Date();
    this.minFromDate2.setDate(this.currentDate.getDate() - 90);
    this.maxFromDate2 = new Date();
    this.maxFromDate2.setDate(this.currentDate.getDate());

    this.mintoDate = new Date();
    this.maxtoDate = new Date();
    this.maxtoDate.setDate(this.currentDate.getDate());
    this.companyName = sessionStorage.getItem("companyName");
    this.getActiveShiftIds();
    this.getWorkLocation();

  }

  ngOnInit(): void {
    this.searchControl.valueChanges.subscribe(searchText => {
      this.filterShiftTypes(searchText);
    });

    this.searchControlLocation.valueChanges.subscribe(searchText => {
      this.filterLocations(searchText);
    });

    this.searchControl2.valueChanges.subscribe(searchText => {
      this.filterShiftTypes2(searchText);
    });

    this.searchControlLocation2.valueChanges.subscribe(searchText => {
      this.filterLocations2(searchText);
    });
    this.requestform = this.formBuilder.group(
      {
        shiftType: ['', Validators.required],
        location: ['', Validators.required],
        fromDate: [new Date(), Validators.required],
      });
    this.requestform2 = this.formBuilder.group(
      {
        shiftType: ['', Validators.required],
        location: ['', Validators.required],
        fromDate: [new Date(), Validators.required],
        toDate: [new Date(), Validators.required],
      });

    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
  }
  getActiveShiftIds() {
    this.attendanceService.getActiveShiftIds().subscribe((res) => {
      if (res.status) {
        this.activeShiftsList = res.data;
        this.filteredShiftTypes = this.activeShiftsList;
        this.filteredShiftTypes2 = this.activeShiftsList;
      }
    })
  }
  getWorkLocation() {
    this.companyService.getactiveWorkLocation({ id: null, companyName: this.companyName }).subscribe((result) => {
      this.locationsList = result.data;
      this.filteredLocations = this.locationsList
      this.filteredLocations2 = this.locationsList
    })
  }

  searchForm() {
    if (this.requestform.valid) {
      this.noDataFound = false;
      this.btnDisable = true;
      let data = {
        manager_id_value: this.userSession.id,
        shiftid: this.requestform.controls.shiftType.value,
        location: this.requestform.controls.location.value,
        calender_date: this.datePipe.transform(
          this.requestform.controls.fromDate.value,
          'y-MM-dd'
        ),
      }

      this.reportsService.getDailyPunchReport(data).subscribe((res: any) => {
        this.headersList = [];
        this.List = [];
        if (res.status) {
          let i = 0;
          if (res.status && res.data.length > 0) {
            res.data.forEach((e: any) => {
              if (i < 1) {
                let header = JSON.parse(e.output);
                this.headersList.push(header);
              } else {
                let header = JSON.parse(e.output);
                this.List.push(header);
              }
              i++;
            });

          }
          if (res.data.length <= 1) {
            this.noDataFound = true
          }

          this.btnDisable = false;
          this.dataSource = new MatTableDataSource(this.List);
        }
      })

    }
  }
  resetform() {
    this.List = [];
    this.headersList = [];
    this.dataSource = new MatTableDataSource(this.List);
    this.noDataFound = false;
    this.requestform.patchValue({
      fromDate: new Date(),
      shiftType: '',
      location: '',
    });
    // Reset validation states
    this.requestform2.markAsPristine();
    this.requestform2.markAsUntouched();
    // Make controls valid without emitting events
    Object.keys(this.requestform.controls).forEach(key => {
      const control = this.requestform.patchValue({
        fromDate: new Date(),

        shiftType: '',
        location: '',
      });
      this.requestform.markAsPristine();
      this.requestform.markAsUntouched();
      this.requestform.updateValueAndValidity({ emitEvent: false });
      this.requestform.get(key);
      control.setErrors(null);
    });
    this.requestform.updateValueAndValidity({ emitEvent: false });
    this.requestform.controls['fromDate'].setValue(new Date());
    this.requestform.controls['toDate'].setValue(new Date());
  }

  searchForm2() {
    if (this.requestform2.valid) {
      this.noDataFound2 = false;
      this.btnDisable = true;
      let data = {
        manager_id_value: this.userSession.id,
        shiftid: this.requestform2.controls.shiftType.value,
        location: this.requestform2.controls.location.value,
        from_date: this.datePipe.transform(
          this.requestform2.controls.fromDate.value,
          'y-MM-dd'
        ),
        to_date: this.datePipe.transform(
          this.requestform2.controls.toDate.value,
          'y-MM-dd'
        ),
      }

      this.reportsService.getPunchMissesReport(data).subscribe((res: any) => {
        this.headersList2 = [];
        this.List2 = [];
        if (res.status) {
          let i = 0;
          if (res.status && res.data.length > 0) {
            res.data.forEach((e: any) => {
              if (i < 1) {
                let header = JSON.parse(e.output);
                this.headersList2.push(header);
              } else {
                let header = JSON.parse(e.output);
                this.List2.push(header);
              }
              i++;
            });

          }
          if (res.data.length <= 1) {
            this.noDataFound2 = true
          }

          this.btnDisable = false;
          this.dataSource2 = new MatTableDataSource(this.List2);
        }
      })

    }
  }

  resetform2() {
    this.mintoDate = new Date();
    this.List2 = [];
    this.headersList2 = [];
    this.dataSource2 = new MatTableDataSource(this.List2);
    this.noDataFound2 = false;
    this.requestform2.patchValue({
      fromDate: new Date(),
      toDate: new Date(),
      shiftType: '',
      location: '',
    });
    // Reset validation states
    this.requestform2.markAsPristine();
    this.requestform2.markAsUntouched();
    // Make controls valid without emitting events
    Object.keys(this.requestform2.controls).forEach(key => {
      const control = this.requestform2.patchValue({
        fromDate: new Date(),
        toDate: new Date(),
        shiftType: '',
        location: '',
      });
      this.requestform2.markAsPristine();
      this.requestform2.markAsUntouched();
      this.requestform2.updateValueAndValidity({ emitEvent: false });
      this.requestform2.get(key);
      control.setErrors(null);
    });
    this.requestform2.updateValueAndValidity({ emitEvent: false });
    this.requestform2.controls['fromDate'].setValue(new Date());
    this.requestform2.controls['toDate'].setValue(new Date());
    this.mintoDate = new Date();

  }

  filterShiftTypes(searchText: any) {
    if (searchText) {
      this.filteredShiftTypes = this.activeShiftsList.filter((shift: any) =>
        shift.shiftname.toLowerCase().includes(searchText.toLowerCase())
      );
      this.requestform.controls.shiftType.setValue('')
    } else {
      this.filteredShiftTypes = this.activeShiftsList;
    }
  }
  filterLocations(searchText: any) {
    if (searchText) {
      this.filteredLocations = this.locationsList.filter((loc: any) =>
        loc.cityname.toLowerCase().includes(searchText.toLowerCase() || loc.location.toLowerCase().includes(searchText.toLowerCase())
        ));
      this.requestform.controls.location.setValue('')
    } else {
      this.filteredLocations = this.locationsList;
    }
  }

  filterShiftTypes2(searchText: any) {
    if (searchText) {
      this.filteredShiftTypes2 = this.activeShiftsList.filter((shift: any) =>
        shift.shiftname.toLowerCase().includes(searchText.toLowerCase())
      );
      this.requestform2.controls.shiftType.setValue('')
    } else {
      this.filteredShiftTypes2 = this.activeShiftsList;
    }
  }
  filterLocations2(searchText: any) {
    if (searchText) {
      this.filteredLocations2 = this.locationsList.filter((loc: any) =>
        loc.cityname.toLowerCase().includes(searchText.toLowerCase() || loc.location.toLowerCase().includes(searchText.toLowerCase())
        ));
      this.requestform2.controls.location.setValue('')
    } else {
      this.filteredLocations2 = this.locationsList;
    }
  }

  exportAsXLSX() {
    if (!this.dataSource || !this.dataSource.data || this.dataSource.data.length === 0) {
      return;
    }
    let date = this.datePipe.transform(
      this.requestform.controls.fromDate.value,
      'dd-MM-YYYY'
    );

    // Prepare header row from displayed columns
    const displayedColumns = Object.keys(this.dataSource.data[0]);
    const headerRow = displayedColumns;

    // Prepare data rows
    const dataRows = this.dataSource.data.map((row: any) =>
      displayedColumns.map((col: string) => {
        let value = row[col];
        return Array.isArray(value) ? value.join(', ') : value;
      })
    );

    // Combine header and data
    const excelData = [headerRow, ...dataRows];

    // Create worksheet and workbook
    const ws: XLSX.WorkSheet = XLSX.utils.aoa_to_sheet(excelData);
    const wb: XLSX.WorkBook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Daily Punch Report');

    // Download file
    XLSX.writeFile(wb, `${date}-daily_punch_report.xlsx`);


  }
  fromDateChange(type: string, event: MatDatepickerInputEvent<Date>) {
    this.requestform2.controls.toDate.setValue('')
    this.mintoDate = event.value;
    if (event.value !== null) {
      this.maxtoDate = new Date(
      );
    }
  }
  tabClick(event: any) {
    // if (event.index === 0) {
    //   this.resetform2()
    // } else {
    //   this.resetform()
    // }
  }

}
