import { Component, OnInit, ViewChildren, QueryList, ChangeDetectorRef } from '@angular/core';
import { Router } from '@angular/router';
import { forkJoin } from 'rxjs';
import { LearnService } from '../../learn.service';
import { CustomSelectComponent } from './custom-select.component';
import { CommonSnackbarService } from '../../../../services/snackbar-service/common-snackbar.service';

@Component({
  selector: 'app-lms-employee-reviewer',
  templateUrl: './lms-employee-reviewer.component.html',
  styleUrls: ['./lms-employee-reviewer.component.scss']
})
export class LmsEmployeeReviewerComponent implements OnInit {
  openMenu: string | null = null;
  selectedTab: number = 0;
  completedCourses: any[] = [];
  pendingReviews: any[] = [];
  reviewHistory: any[] = [];
  userSession: any;

  // Reviewer and Approver selection
  reviewerOptions: any[] = [
    { id: 1, name: 'Karishma' },
    { id: 2, name: 'Karishma' },
    { id: 3, name: 'Karishma' },
    { id: 4, name: 'Karishma' }
  ];
  approverOptions: any[] = [
    { id: 1, name: 'Karishma' },
    { id: 2, name: 'Karishma' },
    { id: 3, name: 'Karishma' },
    { id: 4, name: 'Karishma' }
  ];

  // Employee list used for header edit mode
  employeeOptions: { id: number; name: string }[] = [];
  allEmployeeOptions: { id: number; name: string }[] = [];
  // Per-row options for search (to avoid affecting other dropdowns)
  optionsByRow: Map<number, { id: number; name: string }[]> = new Map();

  selectedReviewer: any = null;
  selectedApprover: any = null;

  // Header edit mode flags and selections (scoped per tab)
  editingReviewerTab: number | null = null;
  editingApproverTab: number | null = null;
  // row index currently being edited for reviewer/approver (null = none)
  editingReviewerRow: number | null = null;
  editingApproverRow: number | null = null;
  selectedEmployeeForReviewer: any = null;
  selectedEmployeeForApprover: any = null;
  // For per-row edit mode
  originalReviewerMap: Map<number, any> = new Map();
  originalApproverMap: Map<number, any> = new Map();

  // Tab-specific storage for reviewers and approvers
  // Structure: Map<tabIndex, Map<courseIndex, selectedIds[]>>
  reviewerByTab: Map<number, Map<number, any[]>> = new Map();
  approverByTab: Map<number, Map<number, any[]>> = new Map();
  // Track submitted reviewers to avoid clearing them on Clear
  submittedReviewerByTab: Map<number, Map<number, any[]>> = new Map();

  @ViewChildren(CustomSelectComponent) customSelects!: QueryList<CustomSelectComponent>;

  constructor(private learnService: LearnService, private cdr: ChangeDetectorRef, private router: Router, private snackbarService: CommonSnackbarService) {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '{}');
  }

  ngOnInit(): void {
    this.loadEmployeeDataCombined();
  }

  onTabChange(event: any): void {
    // When switching to Reviewers tab (index 1), refresh pending reviews
    if (event.index === 1) {
      this.refreshPendingReviews();
    } else if (event.index === 2) {
      this.refreshReviewHistory();
    }
  }

  private refreshReviewHistory(): void {
    const userId = this.userSession?.id || 2;
    this.learnService.getreviewhistory(userId).subscribe({
      next: (result: any) => {
        this.reviewHistory = result?.review_history ?? result ?? [];
        this.cdr.detectChanges();
      },
      error: (err: any) => {
        console.error('Error loading review history:', err);
        this.reviewHistory = [];
      }
    });
  }

  private refreshPendingReviews(): void {
    const userId = this.userSession?.id || 2;
    this.learnService.getpendingreviews(userId).subscribe({
      next: (result: any) => {
        this.pendingReviews = result.pending_reviews || [];
        // Normalize pending review objects
        this.pendingReviews = this.pendingReviews.map((p: any) => ({
          ...p,
          course_id: p.course_id ?? p.courseId ?? p.id ?? null,
          section_id: p.section_id ?? p.sectionId ?? (p.section && p.section.id) ?? null,
          employee_id: p.employee_id ?? p.employeeId ?? null,
          employee_name: p.employee_name ?? p.employeeName ?? p.emp_name ?? ''
        }));
        this.cdr.detectChanges();
      },
      error: (err: any) => {
        console.error('Error refreshing pending reviews:', err);
      }
    });
  }
  // localStorage persistence removed; use backend API instead

  // localStorage persistence removed; use backend API instead

  /**
   * Load both courses and all employees in parallel, wait for both to complete,
   * then merge employee lists to avoid race conditions.
   */
  loadEmployeeDataCombined(): void {
    const userId = this.userSession?.id || 2;

    forkJoin({
      courses: this.learnService.getEmployeeCourses(userId),
      allEmployees: this.learnService.getALLEmployees(),
      pendingReviews: this.learnService.getpendingreviews(userId)
    }).subscribe({
      next: (result: any) => {
        // Process completed courses
        this.completedCourses = result.courses?.completed_courses || [];

        // Normalize course objects to ensure `course_id` and `section_id` are always available
        this.completedCourses = this.completedCourses.map((c: any) => ({
          ...c,
          course_id: c.course_id ?? c.courseId ?? c.id ?? null,
          section_id: c.section_id ?? c.sectionId ?? (c.section && c.section.id) ?? null,
          employee_id: c.employee_id ?? c.employeeId ?? null,
          employee_name: c.employee_name ?? c.employeeName ?? c.emp_name ?? ''
        }));

        // Process pending reviews
        this.pendingReviews = result.pendingReviews?.pending_reviews || [];

        // Normalize pending review objects to ensure `course_id` and `section_id` are available
        this.pendingReviews = this.pendingReviews.map((p: any) => ({
          ...p,
          course_id: p.course_id ?? p.courseId ?? p.id ?? null,
          section_id: p.section_id ?? p.sectionId ?? (p.section && p.section.id) ?? null,
          employee_id: p.employee_id ?? p.employeeId ?? null,
          employee_name: p.employee_name ?? p.employeeName ?? p.emp_name ?? ''
        }));

        // Build employee list from both sources (deduplicated by ID)
        const empMap = new Map<number, string>();

        // 1. Add all employees from getALLEmployees
        const allEmpList = result.allEmployees?.employees || [];
        allEmpList.forEach((e: any) => {
          if (e.employee_id) {
            empMap.set(e.employee_id, e.emp_name);
          }
        });

        // 2. Add/supplement with employees from completed courses (in case some are missing from all-employees)
        this.completedCourses.forEach((c: any) => {
          if (c.employee_id && !empMap.has(c.employee_id)) {
            empMap.set(c.employee_id, c.employee_name);
          }
        });

        // 3. Also add employees from pending reviews
        this.pendingReviews.forEach((p: any) => {
          if (p.employee_id && !empMap.has(p.employee_id)) {
            empMap.set(p.employee_id, p.employee_name);
          }
        });

        // 4. Convert map to array for dropdown options
        this.employeeOptions = Array.from(empMap.entries()).map(([id, name]) => ({ id, name }));

        // Store full list for search reset
        this.allEmployeeOptions = [...this.employeeOptions];

        // 5. Also set reviewer/approver options with the full list
        this.reviewerOptions = [...this.employeeOptions];
        this.approverOptions = [...this.employeeOptions];

        // Populate reviewer selections from API if backend provided them
        // Backend may return a CSV string in `selected_reviewers` (e.g. "2,1") or an array in `reviewer_ids`.
        if (!this.reviewerByTab.has(0)) this.reviewerByTab.set(0, new Map());
        const tabMap = this.reviewerByTab.get(0)!;
        this.completedCourses.forEach((course: any, idx: number) => {
          // prefer `selected_reviewers` (CSV string) but accept `reviewer_ids` array if present
          const csv = (course.selected_reviewers ?? '').toString().trim();
          if (csv && csv !== "") {
            const ids = csv.split(',').map((s: string) => parseInt(s.trim(), 10)).filter((n: number) => !isNaN(n));
            if (ids.length) tabMap.set(idx, ids);
            return;
          }
          const arr = course.reviewer_ids ?? course.reviewerId ?? null;
          if (Array.isArray(arr) && arr.length) {
            const ids = arr.map((v: any) => Number(v)).filter((n: number) => !isNaN(n));
            if (ids.length) tabMap.set(idx, ids);
          }
        });

        // Initialize submitted reviewers from initial API data
        this.submittedReviewerByTab.set(0, new Map(tabMap));

        // Ensure change detection fires
        this.cdr.detectChanges();
      },
      error: (err: any) => {
        console.error('Error loading employee data:', err);
      }
    });
  }

  toggleMenu(menuName: string, tabIndex: number, event?: any): void {
    const key = `${tabIndex}_${menuName}`;
    this.openMenu = this.openMenu === key ? null : key;
  }



  addReviewer(tabIndex?: number): void {
    const tab = typeof tabIndex === 'number' ? tabIndex : this.selectedTab;
    this.openMenu = null;
    this.editingReviewerTab = tab;
    this.editingReviewerRow = null; // header edit affects all rows
    this.originalReviewerMap.clear();

    // Initialize tab map if needed
    if (!this.reviewerByTab.has(tab)) {
      this.reviewerByTab.set(tab, new Map());
    }
    const tabMap = this.reviewerByTab.get(tab)!;

    this.completedCourses.forEach((course, idx) => {
      const current = tabMap.get(idx) || null;
      this.originalReviewerMap.set(idx, current);
      (course as any)._selectedReviewerId = current;
    });
  }

  addApprover(tabIndex?: number): void {
    const tab = typeof tabIndex === 'number' ? tabIndex : this.selectedTab;
    this.openMenu = null;
    this.editingApproverTab = tab;
    this.originalApproverMap.clear();

    // Initialize tab map if needed
    if (!this.approverByTab.has(tab)) {
      this.approverByTab.set(tab, new Map());
    }
    const tabMap = this.approverByTab.get(tab)!;

    this.completedCourses.forEach((course, idx) => {
      const current = tabMap.get(idx) || null;
      this.originalApproverMap.set(idx, current);
      (course as any)._selectedApproverId = current;
    });
  }

  onReviewerChange(tabIndex: number, rowIndex: number, selectedIds: any): void {
    if (!this.reviewerByTab.has(tabIndex)) {
      this.reviewerByTab.set(tabIndex, new Map());
    }
    let validIds: any[] = [];
    if (Array.isArray(selectedIds)) {
      validIds = selectedIds;
    } else if (selectedIds !== null && selectedIds !== undefined) {
      validIds = [selectedIds];
    }
    this.reviewerByTab.get(tabIndex)!.set(rowIndex, validIds);

    // ✅ REMOVED: don't auto-close editing — let user confirm via Submit
    // The row stays in edit mode so user can see the selected value in the dropdown
    this.cdr.detectChanges();
  }
  saveReviewerForRow(rowIndex: number): void {
    const tabIndex = 0; // My Courses tab
    const selectedId = this.completedCourses[rowIndex]?._selectedReviewerId;
    if (!this.reviewerByTab.has(tabIndex)) {
      this.reviewerByTab.set(tabIndex, new Map());
    }
    // Store as array since formatReviewerNames expects an array
    this.reviewerByTab.get(tabIndex)!.set(rowIndex, selectedId ? [selectedId] : []);
    // Force change detection immediately
    this.cdr.detectChanges();
    // kept for in-memory update
  }

  onApproverChange(tabIndex: number, rowIndex: number, selectedIds: any): void {
    if (!this.approverByTab.has(tabIndex)) {
      this.approverByTab.set(tabIndex, new Map());
    }
    // Handle both single value (from single-select mode) and array (from multi-select mode)
    let validIds: any[] = [];
    if (Array.isArray(selectedIds)) {
      validIds = selectedIds;
    } else if (selectedIds !== null && selectedIds !== undefined) {
      validIds = [selectedIds];
    }
    this.approverByTab.get(tabIndex)!.set(rowIndex, validIds);
    // Force change detection immediately
    this.cdr.detectChanges();
    // kept for in-memory update
  }

  getReviewerForTab(tabIndex: number, courseIndex: number): any[] | null {
    const tab = this.reviewerByTab.get(tabIndex);
    // Return null when there is no stored selection to avoid returning a fresh [] reference
    return tab ? (tab.get(courseIndex) ?? null) : null;
  }

  getApproverForTab(tabIndex: number, courseIndex: number): any[] | null {
    const tab = this.approverByTab.get(tabIndex);
    // Return null when there is no stored selection to avoid returning a fresh [] reference
    return tab ? (tab.get(courseIndex) ?? null) : null;
  }

  saveReviewer(): void {
    if (this.selectedEmployeeForReviewer) {
      // TODO: persist selection per your backend
      this.editingReviewerTab = null;
    }
  }

  cancelReviewer(): void {
    this.editingReviewerTab = null;
    this.selectedEmployeeForReviewer = null;
  }

  saveApprover(): void {
    if (this.selectedEmployeeForApprover) {
      // TODO: persist selection per your backend
      this.editingApproverTab = null;
    }
  }

  cancelApprover(): void {
    this.editingApproverTab = null;
    this.selectedEmployeeForApprover = null;
  }

  createReviewer(): void {
    // Add your create reviewer logic here
  }

  createApprover(): void {
    // Add your create approver logic here
  }

  formatReviewerNames(tabIndex: number, courseIndex: number): string {
    const reviewerIds = this.getReviewerForTab(tabIndex, courseIndex);
    if (!reviewerIds || reviewerIds.length === 0) {
      return '-';
    }
    const names = reviewerIds
      .map((id: any) => {
        const emp = this.employeeOptions.find(e => e.id === id);
        return emp?.name || '';
      })
      .filter((n: string) => n !== '');
    return names.length > 0 ? names.join(', ') : '-';
  }

  formatApproverNames(tabIndex: number, courseIndex: number): string {
    const approverIds = this.getApproverForTab(tabIndex, courseIndex);
    if (!approverIds || approverIds.length === 0) return '-';
    const names = approverIds.map((id: any) => {
      const emp = this.employeeOptions.find(e => e.id === id);
      return emp?.name || '';
    }).filter((n: string) => n);
    return names.length > 0 ? names.join(', ') : '-';
  }

  hasReviewer(tabIndex: number, courseIndex: number): boolean {
    const reviewerIds = this.getReviewerForTab(tabIndex, courseIndex);
    return Array.isArray(reviewerIds) && reviewerIds.length > 0;
  }

  /** Get options for a specific row (with search results if available) */
  getOptionsForRow(rowIndex: number): { id: number; name: string }[] {
    return this.optionsByRow.get(rowIndex) || this.employeeOptions;
  }

  /** Handle search input from custom-select */
  onSearchChange(data: { query: string, rowIndex: number }): void {
    const { query, rowIndex } = data;

    if (query.trim()) {
      this.learnService.searchEmployees(query).subscribe({
        next: (res: any) => {
          console.log('[onSearchChange] API Response:', res);
          // Handle multiple possible response formats
          let employees: any[] = [];
          if (Array.isArray(res)) {
            employees = res;
          } else if (Array.isArray(res.employees)) {
            employees = res.employees;
          } else if (Array.isArray(res.data)) {
            employees = res.data;
          } else {
            console.warn('[onSearchChange] Unexpected response format:', res);
            employees = [];
          }

          const mappedOptions = employees.map((e: any) => ({
            id: e.id,
            name: e.full_name || e.name
          }));
          this.optionsByRow.set(rowIndex, mappedOptions);
          console.log('[onSearchChange] Mapped options for row', rowIndex, ':', mappedOptions);
          this.cdr.detectChanges();
        },
        error: (err: any) => {
          console.error('Error searching employees:', err);
          // On error, reset to full list for this row
          this.optionsByRow.set(rowIndex, [...this.allEmployeeOptions]);
          this.cdr.detectChanges();
        }
      });
    } else {
      // Reset to full list when search is empty
      this.optionsByRow.delete(rowIndex);
      this.cdr.detectChanges();
    }
  }

  /**
   * invoked when user clicks the + icon in a specific row
   */
  startReviewerRowEdit(tabIndex: number, rowIndex: number) {

    // ✅ STEP 1: Commit all open dropdowns before switching
    if (this.customSelects) {
      this.customSelects.forEach(select => {
        if (select.isOpen) {
          select.commitSelection(); // 🔥 important
        }
      });
    }

    // ✅ STEP 2: Now switch to new row
    this.editingReviewerTab = tabIndex;
    this.editingReviewerRow = rowIndex;

    if (!this.reviewerByTab.has(tabIndex)) {
      this.reviewerByTab.set(tabIndex, new Map());
    }

    const tabMap = this.reviewerByTab.get(tabIndex)!;
    const current = tabMap.get(rowIndex) || null;
    this.originalReviewerMap.set(rowIndex, current);
  }


  viewCourseDetails(tabIndex: number, courseIndex: number): void {
    let course: any;

    // Get course based on tab
    if (tabIndex === 0) {
      course = this.completedCourses[courseIndex];
    } else if (tabIndex === 1) {
      course = this.pendingReviews[courseIndex];
    }

    console.log('[viewCourseDetails] tabIndex:', tabIndex, 'courseIndex:', courseIndex, 'course:', course);

    if (!course) {
      console.error('[viewCourseDetails] Course not found at index:', courseIndex);
      return;
    }

    if (!course.course_id) {
      console.error('[viewCourseDetails] Course ID not found in course object:', course);
      return;
    }

    // Persist selected course/section to sessionStorage for robustness
    try {
      sessionStorage.setItem('selected_course_id', String(course.course_id));
      if (course.section_id) sessionStorage.setItem('selected_section_id', String(course.section_id));
    } catch (e) {
      // ignore storage errors
    }

    // Build navigation state; include section_id and review_id when present
    const navState: any = {
      course_id: course.course_id,
      course_name: course.course_name ?? course.courseName ?? course.title ?? '',
      employee_name: course.employee_name ?? course.employeeName ?? '',
      tab_index: tabIndex // Pass the tab index to quiz-details
    };
    if (course.section_id) navState.section_id = course.section_id;
    if (course.review_id) navState.review_id = course.review_id; // Pass review_id for reviewer tab

    this.router.navigate(['/learning/LmsQuizDetails'], { state: navState });
  }

  getReviewStatus(tabIndex: number, courseIndex: number): string {
    const course = this.completedCourses[courseIndex];
    // Use final_status from API response
    return course?.final_status || '-';
  }

  onDoneButtonClick(): void {
    if (this.customSelects) {
      this.customSelects.forEach(select => {
        if (select.isOpen) {
          select.commitSelection();
        }
        const t = select.tabIndex ?? null;
        const r = select.rowIndex ?? null;
        if (t !== null && r !== null) {
          if (!this.reviewerByTab.has(t)) this.reviewerByTab.set(t, new Map());

          const values = Array.isArray(select.selectedValues) && select.selectedValues.length > 0
            ? select.selectedValues
            : Array.isArray(select.tempSelectedValues) && select.tempSelectedValues.length > 0
              ? select.tempSelectedValues
              : null; // ✅ null instead of [] — don't overwrite with empty

          // ✅ Only update if there are actual values selected
          if (values && values.length > 0) {
            this.reviewerByTab.get(t)!.set(r, values);
          }
        }
      });
    }

    const enrollmentsToUpdate: any[] = [];
    this.completedCourses.forEach((course, courseIndex) => {
      const tabIndex = this.selectedTab;
      const reviewerIds = this.getReviewerForTab(tabIndex, courseIndex);
      const alreadySubmitted = this.submittedReviewerByTab.get(tabIndex)?.get(courseIndex);

      console.log(`Course ${courseIndex}:`, { enrollment_id: course.enrollment_id, reviewerIds, alreadySubmitted });

      // ✅ Skip if already submitted OR no reviewers selected
      if (reviewerIds && reviewerIds.length > 0 && !alreadySubmitted) {
        enrollmentsToUpdate.push({
          enrollment_id: course.enrollment_id,
          reviewer_ids: reviewerIds
          // ✅ No need to add company_code here — addCompanyToBody() in service handles it
        });
      }
    });

    console.log('Final enrollmentsToUpdate:', enrollmentsToUpdate);

    if (enrollmentsToUpdate.length > 0) {
      enrollmentsToUpdate.forEach((payload) => {
        this.learnService.assignreviewers(payload).subscribe({
          next: (response: any) => {
            const courseIndex = this.completedCourses.findIndex(c => c.enrollment_id === payload.enrollment_id);
            if (courseIndex !== -1) {
              this.completedCourses[courseIndex].final_status = 'Under Review';

              // ✅ Mark as submitted to prevent re-submission
              if (!this.submittedReviewerByTab.has(0)) this.submittedReviewerByTab.set(0, new Map());
              this.submittedReviewerByTab.get(0)!.set(courseIndex, [...payload.reviewer_ids]);

              // ✅ DON'T delete from reviewerByTab — keep names visible in UI
            }
            this.refreshPendingReviews();
            this.snackbarService.show('Submitted successfully', true);
            this.cdr.detectChanges();
          },
          error: (err: any) => {
            console.error('Error assigning reviewers:', err);
          }
        });
      });
    }

    Promise.resolve().then(() => {
      setTimeout(() => {
        this.editingReviewerTab = null;
        this.editingApproverTab = null;
        this.editingReviewerRow = null;
        this.editingApproverRow = null;
        this.cdr.detectChanges();
      }, 0);
    });
  }

  // new helpers for footer buttons
 onSubmitButtonClick(): void {
  const tab = this.selectedTab;

  if (!this.completedCourses || this.completedCourses.length === 0) {
    this.snackbarService.show('No data available to submit', false);
    return;
  }

  let hasAtLeastOneReviewer = false;
  let hasNewSelection = false;

  this.completedCourses.forEach((course, index) => {

    const reviewerIds = this.getReviewerForTab(tab, index);
    let currentValues: any[] = [];

    // ✅ Check committed values
    if (reviewerIds && reviewerIds.length > 0) {
      currentValues = reviewerIds;
      hasAtLeastOneReviewer = true;
    }

    // ✅ Check temp dropdown values
    if (this.customSelects) {
      const select = this.customSelects.find(
        s => s.tabIndex === tab && s.rowIndex === index
      );

      if (select && select.tempSelectedValues && select.tempSelectedValues.length > 0) {
    currentValues = select.tempSelectedValues;
    hasAtLeastOneReviewer = true;
      }
    }

    // ✅ Check if NEW data (not already submitted)
    const submitted = this.submittedReviewerByTab.get(tab)?.get(index);

    if (currentValues.length > 0) {
      if (!submitted || JSON.stringify(submitted) !== JSON.stringify(currentValues)) {
        hasNewSelection = true;
      }
    }
  });

  // ❌ ONLY this case should show error
  if (!hasAtLeastOneReviewer) {
    this.snackbarService.show('Please select at least one reviewer', false);
    return;
  }


  // ✅ Proceed
  this.onDoneButtonClick();
}
  onClearButtonClick(): void {
    // clear all reviewer selections for the current tab, but restore submitted ones
    const tab = this.selectedTab;
    if (this.reviewerByTab.has(tab)) {
      this.reviewerByTab.get(tab)!.clear();
    }
    // Restore submitted selections
    if (this.submittedReviewerByTab.has(tab)) {
      this.reviewerByTab.set(tab, new Map(this.submittedReviewerByTab.get(tab)!));
    }
    // also clear any editing state
    this.editingReviewerTab = null;
    this.editingReviewerRow = null;
    this.cdr.detectChanges();
  }
}

