onChange(event: any) {

  const selectedFile = event.target.files[0];
  if (!selectedFile) return;

  const fileReader = new FileReader();

  fileReader.readAsBinaryString(selectedFile);

  fileReader.onload = (e: any) => {

    const binaryData = e.target.result;

    const workbook = XLSX.read(binaryData, {type: 'binary', });

    const wsname = workbook.SheetNames[0];
    const ws: XLSX.WorkSheet = workbook.Sheets[wsname];

    // RAW DATA 
    const rawData: any[] = XLSX.utils.sheet_to_json(ws, {
      raw: true, defval: ''
    });

    if (!rawData.length) return;

    //  API DATA (yyyy-mm-dd)
    const apiData = rawData.map(row => ({
      ...row,
      dateofbirth: this.formatDateForApi(row.dateofbirth),
      dateofjoin: this.formatDateForApi(row.dateofjoin)
    }));

    //  VIEW DATA 
    const headers = Object.keys(rawData[0]) .filter(h => !h.startsWith('__EMPTY'));;

    const viewDataAOA = [
      headers,
      ...rawData.map(r =>
        headers.map(k => {
          if (k === 'dateofbirth') return this.formatDateForView(r[k]);
          if (k === 'dateofjoin') return this.formatDateForView(r[k]);
          return r[k]?? '';
        })
      )
    ];

    this.data = apiData;          // used for submit
    this.viewdata = viewDataAOA;  // used for preview table

    this.convertedJson = JSON.stringify(this.data, null, 2);

    this.isview = true;
    this.isadd = false;
  };
}

formatDateForApi(value: any): string | null {

  if (!value) return null;

    if (typeof value === 'number') {
    const d = XLSX.SSF.parse_date_code(value);
    return `${d.y}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`;
  }
  //   if (typeof value === 'string') {
          const clean = value.trim().replace(/\//g, '-');

    // yyyy-mm-dd
    if (/^\d{4}-\d{2}-\d{2}$/.test(clean)) {
      return clean;
    }

    if (/^\d{2}-\d{2}-\d{4}$/.test(clean)) {
      const [dd, mm, yyyy] = clean.split('-');

      return `${yyyy}-${mm}-${dd}`; 
    }
  //   return value.replace(/\//g, '-');
  // }

  return null;
}

formatDateForView(value: any): string | null {

  if (!value) return null;

  if (typeof value === 'number') {
    const d = XLSX.SSF.parse_date_code(value);
    return `${String(d.d).padStart(2,'0')}-${String(d.m).padStart(2,'0')}-${d.y}`;
  }
    if (typeof value === 'string') {
    return value.replace(/\//g, '-');
  }

  return value;
}

  SaveUploadedData() {
    this.isLoading = true;
    let data = {
      'emplist': JSON.parse(this.convertedJson),
      'createdby': this.userSession.id
    }
    this.emsService.setEmployeeExcelData(data).subscribe(
      (res: any) => {
        this.isLoading = false;
        if (res.status) {
           let value =res.data[0]
          if (value.statuscode == 0) {
            this.removeData();
            this.isview = false;
            this.isadd = true;
            this.dialogService.openDialog(value.message);
            this.cancel();
          } else if (value.statuscode == 1) {
            this.dialogService.openDialog(value.message);
            this.removeData();
            this.isview = false;
            this.isadd = true;
            this.cancel();
          } else {
            this.dialogService.openDialog('Unable to save data.');
            this.removeData();
            this.isview = false;
            this.isadd = true;
            this.cancel();
          }
        } else {
          this.dialogService.openDialog('Unable to save data.');
          this.removeData();
          this.isview = false;
          this.isadd = true;
          this.cancel();
        }
      },
      error => {
        error.error.text
      })
  }
  removeData() {
    this.isview = false;
    this.isadd = true;
    this.data = [[], []];
    this.convertedJson = '';
    this.cancel();
  }
cancel(){
 this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
            this.router.navigate(["/ems/employee-excel-upload"]));
}
