Searchform() {   
  this.addValidators();

  /*START MANAGER EMPTY VALIDATION (NEW) */
  const managerCtrl = this.searchForm.controls.managers;

  if (!managerCtrl.value || managerCtrl.value.length === 0) {
    managerCtrl.setErrors({ required: true });
    managerCtrl.markAsTouched();
    managerCtrl.markAsDirty();
    managerCtrl.updateValueAndValidity();
    return; //  stop search
  }
  /*END MANAGER EMPTY VALIDATION */

  if (this.searchForm.valid) {
    this.List = [];
    this.headersList = [];

    let fromDate =
      new Date(this.searchForm.controls.fromDate.value).getFullYear() +
      '-' +
      (new Date(this.searchForm.controls.fromDate.value).getMonth() + 1) +
      '-01';

    let userId =
      this.searchForm.controls.Users.value == '0'
        ? null
        : this.searchForm.controls.Users.value;

    let data = {
      manager_employee_id: userId ? null : JSON.stringify(this.selectedManagers),
      location_id: JSON.stringify(this.selectedLocations),
      employee_id: userId,
      calendar_date: fromDate,
    };

    this.spinner.show();
    this.isLoading = true;

    this.reportsService.getBranchwiseAttendanceMonthlyReport(data).subscribe(
      (res: any) => {
        this.spinner.hide();
        this.isLoading = false;

        if (res.data && res.data.length) {
          this.List = res.data;
          this.headersList = Object.keys(res.data[0]);
        }
      },
      (error) => {
        this.spinner.hide();
        this.isLoading = false;
        error.error.text;
      }
    );
  }
}


