  filterAttendanceSource(searchText: string) {

  const search = searchText.toLowerCase();

  let filtered = this.attendanceSourceList.filter((val: any) =>
    val.name.toLowerCase().includes(search)
  );

  const selected = this.searchForm.controls.attendanceSource.value || [];

  selected.forEach((sel: any) => {
    if (!filtered.some((item: any) => item.id === sel.id)) {
      filtered.unshift(sel);
    }
  });

  this.filteredAttendanceSources = filtered;
}
