  isTotalsRow(row: any): boolean {
  if (!row) return false;
  return Object.values(row).some(v => String(v || '').toLowerCase().includes('total'));
}

getTotalsRowType(item: any): 'employees'|'presents'|'weekoffs'|'leaves'|'holidays'|'absents'|null {
  if (!item) return null;
  const allText = Object.values(item).map(v => String(v || '').toLowerCase()).join(' ');
  if (allText.includes('employees total')) return 'employees';
  if (allText.includes('presents total') || allText.includes('present total')) return 'presents';
  if (allText.includes('week-offs') || allText.includes('week offs')) return 'weekoffs';
  if (allText.includes('leaves')) return 'leaves';
  if (allText.includes('holidays') || allText.includes('holiday total')) return 'holidays';
  if (allText.includes('absents') || allText.includes('absent total')) return 'absents';
  return null;
}
getCellTextColor(cellValue: any, headerKey: any, isTotals: boolean = false, rowItem?: any): string {
  const raw = (cellValue ?? '').toString().trim();
  const keyNorm = this.normalizeKey(headerKey);

  if (isTotals && rowItem) {
    const t = this.getTotalsRowType(rowItem);
    switch (t) {
      case 'employees': return 'black';
      case 'presents':  return 'green';
      case 'weekoffs':  return 'blue';
      case 'leaves':    return '#FFA500';
      case 'holidays':  return '#8B4513';
      case 'absents':   return 'red';
      default: return 'black';
    }
  }

  if (keyNorm.includes('present')) return Number(raw) > 0 ? 'green' : 'black';
  if (keyNorm.includes('absent'))  return Number(raw) > 0 ? 'red' : 'black';

  const code = raw.toUpperCase();
  if (code === 'P') return 'green';
  if (code === 'A') return 'red';
  if (code === 'H') return '#800000';
  if (code === 'W') return 'blue';
  if (code === 'L') return '#ff8c00';
  if (code === 'HD') return '#ce06e4';
  if (code === 'WP') return '#06c3e4';
  if (code === 'HP') return '#06e471';
  if (code === 'HL') return '#8338ec';
  if (code == "CL") return '#ff8c00';
  if (code == "BL") return '#ff8c00';
  if (code == "SL") return '#ff8c00';      
  if (code == "LOP") return '#ff8c00';
  if (code == "CPL") return '#ff8c00';
  if (code == "MTL") return '#ff8c00';
  if (code == "PTL") return '#ff8c00';
  if (code == "EL") return  '#ff8c00';
  if (code == "ML") return '#ff8c00';

  if (keyNorm.includes('late') && Number(raw) > 0) return 'red';

  return 'black';
}
getCellStyle(value: any, key: string) {
  return {
    'background-color':
      value === 'A' ? '#F5DADF' :       // Absent → Light Red
      (value === 'H' || value === 'W') ? '#E2E5DE' : // Holiday / Week-Off → Grey
      '#ffffff',                         // Others → White
    'text-align': 'center',
    'padding': '4px'
  } as { [k: string]: any };
}
isSerialKey(key: any): boolean {
  if (key === null || key === undefined) return false;

  // Normalize: remove non-alphanumeric characters and lowercase
  const normalized = String(key).toLowerCase().replace(/[^a-z0-9]/g, '');
  
  // Return true if it matches common serial number identifiers
  return normalized === 'sno' || normalized === 's';
}
private normalizeKey(k: any): string {
  if (k === null || k === undefined) return '';
  return String(k).replace(/[_\s.-]/g, '').toLowerCase();
}
