  cdate = new UntypedFormControl(moment());
  setMonthAndYear(normalizedMonthAndYear: Moment, datepicker: MatDatepicker<Moment>) {
    const ctrlValue = this.cdate.value!;
    ctrlValue.month(normalizedMonthAndYear.month());
    ctrlValue.year(normalizedMonthAndYear.year());
    ctrlValue.startOf('day');
    this.searchForm.controls.fromDate.setValue(ctrlValue);
    datepicker.close();
  }
  filterEmp(searchText: any) {
    this.filteredEmployees = this.employeelist.filter((val: any) =>
      val.empname.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredEmployees.length <= 0) {
      this.searchControl.setValue('');
    }
  }
  filterLocations(searchText: any) {
  const search = searchText.toLowerCase();

  // Normal filter
  let filtered = this.worklocationDetails.filter((val: any) =>
    val.cityname.toLowerCase().includes(search) ||
    val.location.toLowerCase().includes(search)
  );

  // Always keep selected locations
  const selected = this.searchForm.controls.companylocation.value || [];

  selected.forEach((sel: any) => {
    if (!filtered.some((item: any) => item.id === sel.id)) {
      filtered.unshift(sel); // add selected item to top
    }
  });

  this.filteredLocations = filtered;
}
filterRM(searchText: any) {
  const search = searchText.toLowerCase();
  
  // Normal filter
  let filtered = this.managersDetails.filter((val: any) =>
    val.manager_name.toLowerCase().includes(search)
  );

  // Keep selected managers always in list
  const selected = this.searchForm.controls.managers.value || [];

  selected.forEach((sel: any) => {
    if (!filtered.some((item: any) => item.manager_emp_id === sel.manager_emp_id)) {
      filtered.unshift(sel); // push to top
    }
  });

  this.filteredManagers = filtered;
}

