import { Component, OnInit } from '@angular/core';
import { TdsService } from '../../tds.service';
import { result } from 'lodash';
import { MatTableDataSource } from '@angular/material/table';

@Component({
  selector: 'app-configure-tds-rules',
  templateUrl: './configure-tds-rules.component.html',
  styleUrls: ['./configure-tds-rules.component.scss']
})
export class ConfigureTdsRulesComponent implements OnInit {
  financeYear:any
  tdsPolices:any=[];
  tdsPolicesDeepCopy:any=[];
  isLeavePolicesChanged :boolean = false;
  secondTdsPolices:any = [];
  constructor(private tdsService:TdsService) { }
  displayedColumns: string[] = [ 'description', 'title', 'value'];
  dataSource: MatTableDataSource<any> = <any>[]

 async ngOnInit() {
    this.financeYear = await this.getFinancialYears();
    this.getTdsPolicies();
  }

  data = [
    { col1: 'Row 1 Col 1', col2: 'Row 1 Col 2', col3: 'Row 1 Col 3', col4: 'Row 1 Col 4', col5: 'Row 1 Col 5' },
    { col1: 'Row 2 Col 1', col2: 'Row 2 Col 2', col3: 'Row 2 Col 3', col4: 'Row 2 Col 4', col5: 'Row 2 Col 5' },
    { col1: 'Row 3 Col 1', col2: 'Row 3 Col 2', col3: 'Row 3 Col 3', col4: 'Row 3 Col 4', col5: 'Row 3 Col 5' },
  ];

   months = [
    { number: 1, month: "January" },
    { number: 2, month: "February" },
    { number: 3, month: "March" },
    { number: 4, month: "April" },
    { number: 5, month: "May" },
    { number: 6, month: "June" },
    { number: 7, month: "July" },
    { number: 8, month: "August" },
    { number: 9, month: "September" },
    { number: 10, month: "October" },
    { number: 11, month: "November" },
    { number: 12, month: "December" }
  ];
  
  getTdsPolicies(){
    this.tdsPolices = [];
    this.secondTdsPolices = [];
    this.tdsPolicesDeepCopy = [];
    this.tdsService.getTdsPolicies(this.financeYear).subscribe((result:any)=>{
      if(result && result.status){
        this.tdsPolices = JSON.parse(result.data[0][0].json_data);
        this.tdsPolices.forEach((ele:any)=>{
          ele.title = null;
          if(ele.rule_id === 1 || ele.rule_id === 2 ){
            ele.title = 'This value can be edited in the TDS Declarations screen.';
          }else if(ele.rule_id === 4 || ele.rule_id === 5){
             ele.title ='This value can be edited in Proof Upload Declarations screen.'
          }
        })
        this.dataSource = new MatTableDataSource(this.tdsPolices);
        this.tdsPolicesDeepCopy = JSON.parse(JSON.stringify(this.tdsPolices))
        this.secondTdsPolices = JSON.parse(result.data[1][0].json_data);
      }
    })
  }
    /** getFinancialYears Data*/
    getFinancialYears() {
      return new Promise((resolve) => {
        this.tdsService.getFinancialYears().subscribe((result: any) => {
          if (result.status && result.data.length) {
            resolve(result.data[0].financial_year)
          } else {
            resolve('')
          }
        });
      });
    }

  update(){
    if(this.isLeavePolicesChanged){
      let input = {tdsPolices:this.tdsPolices}
      this.tdsService.setTdsPolicies(input).subscribe((results:any)=>{
        if(results && results.status){
          if(results.data && results.data[0] && results.data[0].Code){
            this.tdsService.message('Please try again later.')
          }else{
            this.tdsService.message('TDS polices updated successfully.');
            this.getTdsPolicies();
          }
        }else{
          this.tdsService.message('Please try again later.')
        }
      })
    }else{
      this.tdsService.showSnackBar('Please make a modification to update.',true)
    }
  } 
  validateLeavePolices(val:any){
    this.isLeavePolicesChanged = false;
    for(let i =0;i<this.tdsPolicesDeepCopy.length;i++){
      if(this.tdsPolicesDeepCopy[i].rule_id == 3 && this.tdsPolicesDeepCopy[i].value !==  val){
        this.isLeavePolicesChanged = true;
      }
    }
  }
  reset(){
    // setTimeout(() => {
      this.tdsPolices = JSON.parse(JSON.stringify(this.tdsPolicesDeepCopy));
      this.dataSource = new MatTableDataSource(this.tdsPolices);

    // }, 100);
  }
}
