  getDynamicFields(){
  this.dynamic_json = [];
    this.spinner.show();
    this.crm.getSprypleData({client_id:0},'get_crm_add_client_dynamic_fields').subscribe(async (res)=>{
      this.spinner.hide();
      if(res && res.data && res.data[0] && res.data[0].dynamic_fields){
            this.dynamic_json = this.getFieldPairs(JSON.parse(res.data[0].dynamic_fields));
             
            this.isLoading = false;
        }  
    })
}

  getFieldPairs(fields: any[]): any[][] {
    const pairs = [];
    if(fields && fields.length){
      for (let i = 0; i < fields.length; i += 2) {
        pairs.push([fields[i], fields[i + 1]]);
        if(fields[i] && fields[i].f_required == 1){
          if(!fields[i].f_value || fields[i].f_value == '' || fields[i].f_value == undefined){
            this.fields_validated = false;
          }
        }
        if(fields[i + 1] && fields[i + 1].f_required == 1){
          if(!fields[i + 1].f_value || fields[i + 1].f_value == '' || fields[i + 1].f_value == undefined){
            this.fields_validated = false;
          }
        }
      }
    }
    return pairs;
  }

  get_fields_validated(field:any = null){
  
    if(field){    
      field.showError = false;
      if(field.f_required == 1 && (!field.f_value || field.f_value == '' || field.f_value == undefined)){
        this.fields_validated = false;
        field.showError = true;
      }
    }else{
      this.fields_validated = true;
      this.dynamic_json.forEach((f:any)=>{
        f[0]?f[0].showError = false:null;
        f[1]?f[1].showError = false:null;
        if(f[0] && f[0].f_required == 1 && (!f[0].f_value || f[0].f_value == '' || f[0].f_value == undefined)){
          this.fields_validated = false;
          f[0].showError = true;

        }
        if(f[1] && f[1].f_required == 1 && (!f[1].f_value || f[1].f_value == '' || f[1].f_value == undefined)){
          this.fields_validated = false;
          f[1].showError = true;

        }
      });
    } 

  }
