import { Component, OnInit, TemplateRef, ViewChild, ViewContainerRef } from '@angular/core';
import { FormBuilder, FormControl, FormGroup, UntypedFormGroup, Validators } from '@angular/forms';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { SelectionModel } from '@angular/cdk/collections';
import * as XLSX from 'xlsx';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { MatSort } from '@angular/material/sort';
import { Router } from '@angular/router';
import { DatePipe } from '@angular/common';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { CommonSnackbarService } from 'src/app/services/snackbar-service/common-snackbar.service';
import { EmsService } from 'src/app/modules/ems/ems.service';
import { DialogComponent } from 'src/app/modules/attendance/dialog/dialog.component';
import { MatDialog } from '@angular/material/dialog';
import { Overlay, OverlayRef } from '@angular/cdk/overlay';
import { TemplatePortal } from '@angular/cdk/portal';
import { AttendanceService } from '../../attendance.service';
import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
@Component({
  selector: 'app-extra-hours-request-approvals',
  templateUrl: './extra-hours-request-approvals.component.html',
  styleUrls: ['./extra-hours-request-approvals.component.scss'],
    providers: [
      { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
      { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
    ],
})
export class ExtraHoursRequestApprovalsComponent implements OnInit {



  selectedTabIndex = 0;
  timesheetForm!: FormGroup;
  approvedFromDate!: FormGroup;
  pendingDataSource = new MatTableDataSource<any>([]);
  approvedDataSource = new MatTableDataSource<any>([]);
  selection = new SelectionModel<any>(true, []);
  displayedColumns: string[] = ['sno', 'empcode', 'empname', 'date', 'hours','action'];
  displayedColumns2: string[] = ['sno', 'empcode', 'empname', 'date', 'hours','status'];

  dataSource: MatTableDataSource<any> = <any>[];
  dataSource2: MatTableDataSource<any> = <any>[];

  pageLoading = true;
  @ViewChild('paginator') paginator!: MatPaginator;
  @ViewChild('paginator2') paginator2!: MatPaginator;
  @ViewChild('sort') sort!: MatSort;
  @ViewChild('sort2') sort2!: MatSort;
  pageSizeOptions: number[] = [5, 10, 20];
  pageSizeOptions2: number[] = [5, 10, 20];
  row: any;
  btnDisable: boolean = false;
  userSession: any;
  searchForm: any = UntypedFormGroup;
  historyForm: any = UntypedFormGroup;
  minFromDate: Date;
  maxFromDate: Date | null;
  minToDate: Date | null;
  maxToDate: Date;
  currentDate: Date = new Date();
  isApprovalDetailsView: boolean = false;
  approvalDetailData: any;
  rejectReason: string = '';
  titleName: string = '';
  isTaskEnable: boolean = true;
  constructor(private fb: FormBuilder,
    public datePipe: DatePipe,
    private router: Router,
    private attendanceService: AttendanceService,
    private dialogService: ReusableDialogService,
    public dialog: MatDialog,

  ) {

    this.minFromDate = new Date();
    this.minFromDate.setDate(this.currentDate.getDate() - 90);
    this.maxFromDate = new Date();
    this.minToDate = this.maxFromDate;
    this.maxToDate = new Date();

  }
  selectedEmps: any = [];
  selectedEmpid: any;
  isProjectManager: boolean = false;
  minDate = new Date('2000/01/01');
  today = new Date();
  rejectData:any;

  ngOnInit(): void {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.searchForm = this.fb.group({
      fromDate: [''],
      toDate: [''],
      project: ['', Validators.required],
    })
    this.historyForm = this.fb.group({
      fromDate: [''],
      toDate: [''],
    })
    this.getApprovalList();
    this.getApprovedList();
  }

  getApprovalList() {
    let rmid = this.userSession.id;
    let list:any = []
    this.attendanceService.getEmployeeExtraHourRequestsForApproval(rmid).subscribe((res:any)=>{
     if (res.status && res.data.length !== 0) {
        list = res.data;
        this.dataSource = new MatTableDataSource(list);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.getPageSizes();
      } else{

        this.dataSource = new MatTableDataSource(list);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.getPageSizes();
      }
    })
  }

acceptRequest(data:any){

  let payload = {
    id_value:data.id,
    action_by:this.userSession.id,
    status_value:'Approved',
    reason_value: null,
  }

  this.attendanceService.setApproveExtraHourRequest(payload).subscribe((res:any)=>{
    if( res.data[0].successState == 0 ){
        this.dialogService.openDialog('Extra work hours approved successfully');
        this.clear();
    } else{
       this.dialogService.openDialog('Unable to approve the request, please try again');
    }
  })
}
rejectRequest(data:any){
  this.rejectData =data;
  this.titleName = "Reject"
  this.openDialog();

}
  openDialog(): void {
    const dialogRef = this.dialog.open(DialogComponent, {
      width: '450px', position: { top: `100px` },
      data: { name: this.titleName, reason: this.rejectReason, }
    });

    dialogRef.afterClosed().subscribe(result => {

      if (result != undefined) {
        if (result !== true) {
          this.rejectReason = result.reason;
          this.rejectSubmit();
        }
      }
    });
  }

rejectSubmit(){
  let data = this.rejectData;
  let payload = {
    id_value:data.id,
    action_by:this.userSession.id,
    status_value:'Rejected',
    reason_value: this.rejectReason,
  }
  this.attendanceService.setApproveExtraHourRequest(payload).subscribe((res:any)=>{
    if( res.data[0].successState == 0 ){
        this.dialogService.openDialog('Extra work hours request rejected successfully');
        this.clear();
    } else{
       this.dialogService.openDialog('Unable to reject the request, please try again');
    }
  })
}

  getApprovedList() {
    let rmid = this.userSession.id;
    let list:any = []
    this.attendanceService.getEmployeeHourRequestsHistory(rmid).subscribe((res:any)=>{
     if (res.status && res.data.length !== 0) {
        list = res.data;
        this.dataSource2 = new MatTableDataSource(list);
        this.dataSource2.paginator = this.paginator2;
        this.dataSource2.sort = this.sort2;
        this.getPageSizes2();
      } else{

        this.dataSource2 = new MatTableDataSource(list);
        this.dataSource2.paginator = this.paginator2;
        this.dataSource2.sort = this.sort2;
        this.getPageSizes2();
      }
    })
  }

clear(){
     this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
     this.router.navigate(["/Attendance/approveExtraWorkHours"]))
}

  getPageSizes() {
    const customPageSizeArray: number[] = [];
    const dataLength = this.dataSource?.data?.length || 0;

    if (dataLength > 5) {
      customPageSizeArray.push(5);
    }
    if (dataLength > 10) {
      customPageSizeArray.push(10);
    }
    if (dataLength > 30) {
      customPageSizeArray.push(30);
    }

    if (dataLength > 0) {
      customPageSizeArray.push(dataLength);
    }

    this.pageSizeOptions = customPageSizeArray;
  }

  getPageSizes2() {
    const customPageSizeArray: number[] = [];
    const dataLength = this.dataSource2?.data?.length || 0;

    if (dataLength > 5) {
      customPageSizeArray.push(5);
    }
    if (dataLength > 10) {
      customPageSizeArray.push(10);
    }
    if (dataLength > 30) {
      customPageSizeArray.push(30);
    }

    if (dataLength > 0) {
      customPageSizeArray.push(dataLength);
    }

    this.pageSizeOptions2 = customPageSizeArray;
  }
  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource2.filter = filterValue.trim().toLowerCase();
    if (this.dataSource2.paginator) {
      this.dataSource2.paginator.firstPage();
    }
  }


}
