import { Directive, ElementRef, forwardRef, HostListener, Renderer2, StaticProvider } from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

export const CUSTOM_INPUT_DECIMAL_PICKER_CONTROL_VALUE_ACCESSOR: StaticProvider = {
    provide: NG_VALUE_ACCESSOR,
    useExisting: forwardRef(() => DecimalNumberDirective),
    multi: true
};

@Directive({
    selector: '[decimalNumber]',
    providers: [CUSTOM_INPUT_DECIMAL_PICKER_CONTROL_VALUE_ACCESSOR]
})
export class DecimalNumberDirective implements ControlValueAccessor {
    private onChange!: (val: string) => void;
    private onTouched!: () => void;
    private value!: string;

    constructor(
        private elementRef: ElementRef,
        private renderer: Renderer2
    ) {
    }

    @HostListener('input', ['$event.target.value'])
    onInputChange(value: string) {
        const filteredValue: string = filterDecimalValue(value);
        this.updateTextInput(formatForDisplay(filteredValue), this.value !== filteredValue);
    }

    @HostListener('blur')
    onBlur() {
        this.onTouched();
        // Append .00 only if the value is not empty and does not already have a decimal part
        if (this.value && !this.value.includes('.')) {
            this.updateTextInput(formatForDisplay(this.value + '.00'), true);
        } else if (this.value && this.value.split('.')[1]?.length === 0) {
            this.updateTextInput(formatForDisplay(this.value + '00'), true);
        } else if (this.value && this.value.split('.')[1]?.length === 1) {
            this.updateTextInput(formatForDisplay(this.value + '0'), true);
        }
    }

    private updateTextInput(value: string, propagateChange: boolean) {
        // Remove commas for saving the actual value
        const valueWithoutCommas = value.replace(/,/g, '');
        this.renderer.setProperty(this.elementRef.nativeElement, 'value', value);
        if (propagateChange) {
            this.onChange(valueWithoutCommas);
        }
        this.value = valueWithoutCommas;
    }

    // ControlValueAccessor Interface
    registerOnChange(fn: any): void {
        this.onChange = fn;
    }

    registerOnTouched(fn: any): void {
        this.onTouched = fn;
    }

    setDisabledState(isDisabled: boolean): void {
        this.renderer.setProperty(this.elementRef.nativeElement, 'disabled', isDisabled);
    }

    writeValue(value: any): void {
        value = value ? String(value) : '';
        this.updateTextInput(formatForDisplay(value), false);
    }
}

// Function to filter and allow only valid decimal numbers
function filterDecimalValue(value: string): string {
    // This regex matches only valid decimal numbers with up to 7 digits before the decimal point and up to 2 digits after
    const regex = /^(\d{0,7})(\.\d{0,2})?$/;

    // Remove non-numeric characters except the decimal point
    value = value.replace(/[^0-9.]/g, '');

    let match = value.match(regex);
    if (match) {
        return match[0];
    }

    // If input doesn't match the pattern, truncate to the first valid part
    const truncatedValue = value.split('.')[0].substring(0, 7);  // Take only first 7 digits before decimal
    const decimalPart = value.includes('.') ? '.' + value.split('.')[1].substring(0, 2) : '';  // Allow 2 digits after decimal

    return truncatedValue + decimalPart;
}

// Function to format number with thousand separators for display
function formatForDisplay(value: string): string {
    if (!value) return value;

    // Split into integer and decimal parts
    const parts = value.split('.');
    const integerPart = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');  // Add thousand separators
    const decimalPart = parts[1] ? '.' + parts[1] : '';

    return integerPart + decimalPart;
}
