import { Component, Input, Output, EventEmitter, ViewChild, ElementRef, HostListener, OnInit, SimpleChanges, OnChanges } from '@angular/core';

@Component({
  selector: 'app-custom-select',
  templateUrl: './custom-select.component.html',
  styleUrls: ['./custom-select.component.scss']
})
export class CustomSelectComponent implements OnInit, OnChanges {
  @Input() tabIndex?: number | null = null;
  @Input() rowIndex?: number | null = null;
  @Input() label: string = '';
  @Input() options: { id: any; name: string }[] = [];
  @Input() selectedValues: any[] | null = null;
  @Input() multiSelect: boolean = false;
  @Input() forceOpen: boolean = false; // New input to force dropdown open
  @Output() selectionChange = new EventEmitter<any>();
  @Output() searchChange = new EventEmitter<{query: string, rowIndex: number}>();

  @ViewChild('dropdownPanel') dropdownPanel!: ElementRef;
  @ViewChild('triggerButton') triggerButton!: ElementRef;

  panelTop: string = '0px';
  panelLeft: string = '0px';
  isOpen = false;
  // temporary selection while panel is open (for multi-select)
  tempSelectedValues: any[] = [];
  // cached display label to avoid heavy template calls and noisy logs
  displayLabel: string = '';
  searchQuery: string = '';

  ngOnInit(): void {
    if (this.forceOpen && !this.isOpen) {
      this.isOpen = true;
      if (this.tempSelectedValues.length === 0) {
        this.tempSelectedValues = Array.isArray(this.selectedValues) ? [...this.selectedValues] : [];
      }
      this.updateDisplayLabel();
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    // Listen to options changes (from search)
    if (changes['options']) {
      console.log('[ngOnChanges] options changed:', this.options);
    }
    
    // Listen to both forceOpen and selectedValues changes
    if (changes['selectedValues']) {
      // Update cached label when parent changes committed values
      // Do not overwrite temp selections while open
      if (!this.isOpen) {
        this.tempSelectedValues = Array.isArray(this.selectedValues) ? [...this.selectedValues] : [];
      }
      this.updateDisplayLabel();
    }

    
    
    if (changes['forceOpen']) {
  if (changes['forceOpen'].currentValue && !this.isOpen) {
    this.isOpen = true;
    this.tempSelectedValues = Array.isArray(this.selectedValues) ? [...this.selectedValues] : [];
    this.updateDisplayLabel();
    setTimeout(() => this.calculateDropdownPosition());
  } else if (!changes['forceOpen'].currentValue && this.isOpen) {
    // ✅ Commit before closing, so the selection isn't lost
    if (this.tempSelectedValues.length > 0) {
      if (this.multiSelect) {
        this.selectedValues = [...this.tempSelectedValues];
        this.selectionChange.emit(this.selectedValues);
      } else {
        this.selectedValues = [...this.tempSelectedValues];
        this.selectionChange.emit(this.selectedValues[0]);
      }
    }
    this.isOpen = false;
    this.updateDisplayLabel();
  }
}
  }

  toggleDropdown() {
    this.isOpen = !this.isOpen;
    if (this.isOpen) {
      // Opening: initialize temp selections from committed values or existing temp
      if (this.tempSelectedValues.length === 0) {
        this.tempSelectedValues = Array.isArray(this.selectedValues) ? [...this.selectedValues] : [];
      }
      this.calculateDropdownPosition();
    }
    // Don't clear tempSelectedValues when closing - preserve selections for reopening
    this.updateDisplayLabel();
  }

  calculateDropdownPosition() {
    if (!this.triggerButton) {
      return;
    }
    
    const trigger = this.triggerButton.nativeElement;
    const rect = trigger.getBoundingClientRect();
    
    // Position below the trigger button
    this.panelTop = (rect.bottom + 2) + 'px';
    this.panelLeft = rect.left + 'px';
  }

  selectOption(value: any) {
    if (this.multiSelect) {
      // toggle in temporary selection and don't emit until Done is clicked
      if (this.tempSelectedValues.includes(value)) {
        this.tempSelectedValues = this.tempSelectedValues.filter(v => v !== value);
      } else {
        this.tempSelectedValues = [...this.tempSelectedValues, value];
      }
      // reflect temporary selection in the trigger while open
      this.updateDisplayLabel();
      this.selectedValues = [value];
        this.selectionChange.emit(value);
    } else {
      // single select
      if (this.forceOpen) {
        // In edit mode: store temporarily and wait for commitSelection (Done button)
        this.tempSelectedValues = [value];
        this.updateDisplayLabel();
      } else {
        // Normal mode: commit immediately and close
        this.selectedValues = value === null ? [] : [value];
        this.selectionChange.emit(this.selectedValues.length > 0 ? this.selectedValues[0] : null);
        this.isOpen = false;
        this.updateDisplayLabel();
      }
    }
  }

  isSelected(value: any): boolean {
    // For single-select in edit mode, check tempSelectedValues
    if (!this.multiSelect && this.forceOpen && this.tempSelectedValues.length > 0) {
      return this.tempSelectedValues.includes(value);
    }
    // Otherwise check committed selectedValues
    return Array.isArray(this.selectedValues) && this.selectedValues.includes(value);
  }
  // update the cached display label used in template
  updateDisplayLabel(): void {
  // ✅ Prefer tempSelectedValues if they exist (covers both open and just-closed states)
  const valuesToDisplay = (this.tempSelectedValues && this.tempSelectedValues.length > 0)
    ? this.tempSelectedValues
    : this.selectedValues;

  if (!Array.isArray(valuesToDisplay) || valuesToDisplay.length === 0) {
    this.displayLabel = this.label || '';
    return;
  }

  if (this.multiSelect) {
    const names = valuesToDisplay
      .map(id => this.options.find(opt => opt.id === id)?.name)
      .filter((n): n is string => n !== undefined);
    this.displayLabel = names.length > 0 ? names.join(', ') : (this.label || '');
    return;
  }

  const selected = this.options.find(opt => opt.id === valuesToDisplay[0]);
  this.displayLabel = selected ? selected.name : (this.label || '');
}

  onSearchInput(query: string): void {
    this.searchQuery = query;
    if (this.rowIndex !== null) {
      this.searchChange.emit({query, rowIndex: this.rowIndex as number});
    }
  }

  // commit temporary selection
  commitSelection() {
    if (this.multiSelect) {
      this.selectedValues = [...this.tempSelectedValues];
      this.selectionChange.emit(this.selectedValues);
    } else if (!this.multiSelect && this.tempSelectedValues.length > 0) {
      // Single-select in edit mode: commit from tempSelectedValues
      this.selectedValues = [...this.tempSelectedValues];
      this.selectionChange.emit(this.selectedValues[0]);
    }
    this.isOpen = false;
    // Don't clear tempSelectedValues - preserve for reopening
    this.updateDisplayLabel();
  }

  @HostListener('document:click', ['$event'])
onDocumentClick(event: MouseEvent) {
  if (!this.dropdownPanel?.nativeElement?.contains(event.target as HTMLElement) &&
      !(event.target as HTMLElement).closest('.custom-select-trigger')) {
    
    // ✅ Commit tempSelectedValues into selectedValues before closing
    if (this.isOpen && this.tempSelectedValues.length > 0) {
      if (this.multiSelect) {
        this.selectedValues = [...this.tempSelectedValues];
        this.selectionChange.emit(this.selectedValues);
      } else {
        this.selectedValues = [...this.tempSelectedValues];
        this.selectionChange.emit(this.selectedValues[0]);
      }
    }

    this.isOpen = false;
    this.updateDisplayLabel();
  }
}
}

