          //         imageInfo.employeeId = employee.id; // Ensure employeeId is passed

          //         // *** API CALL 2: Get Profile Image (1 call per employee with metadata) ***
          //         this.LM.getProfileImage(imageInfo).subscribe({
          //           next: (imageData: any) => {
          //             console.log('Profile image data for ' + employee.ename, imageData);
          //             if (imageData.success && imageData.image) {
          //               // Convert and set image
          //               let TYPED_ARRAY = new Uint8Array(imageData.image.data);
          //               const STRING_CHAR = TYPED_ARRAY.reduce((data, byte) => {
          //                 return data + String.fromCharCode(byte);
          //               }, '');
          //               let base64String = btoa(STRING_CHAR);
          //               employee.imageUrl = 'data:image/png;base64,' + base64String;
          //             }
          //           },
          //           error: (error: any) => {
          //             console.error('Error fetching profile image for ' + employee.ename, error);
          //           }
