
import { Component, OnInit, ViewChild, ElementRef } from '@angular/core';
import { UntypedFormBuilder, UntypedFormControl, UntypedFormGroup } from "@angular/forms";
import { DatePipe } from "@angular/common";
import { MatPaginator } from "@angular/material/paginator";
import { MatSort } from "@angular/material/sort";
import { Router } from '@angular/router';
import { MatTableDataSource } from "@angular/material/table";
import * as XLSX from "xlsx";
import { NgxSpinnerService } from 'ngx-spinner';
import { ReportsService } from 'src/app/modules/reports/reports.service';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { MatDatepicker } from '@angular/material/datepicker';
import { PayrollService } from '../../payroll.service';
import { Moment } from 'moment';
import * as _moment from 'moment';
import * as pdfMake from "pdfmake/build/pdfmake";
import * as pdfFonts from "pdfmake/build/vfs_fonts";
import { MatDialog } from '@angular/material/dialog';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
// import {default as _rollupMoment} from 'moment';
const moment =  _moment;
(pdfMake as any).vfs = (pdfFonts as any).pdfMake?.vfs;
const htmlToPdfmake = require("html-to-pdfmake");

export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};


@Component({
  selector: 'app-pftax-reports',
  templateUrl: './pftax-reports.component.html',
  styleUrls: ['./pftax-reports.component.scss'],
  providers: [
    {provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE]},

    {provide: MAT_DATE_FORMATS, useValue: MY_FORMATS},
  ],
})
export class PftaxReportsComponent implements OnInit {
  date = new UntypedFormControl(moment());
  statehide:boolean = false;
  reporthide:boolean=false;
  detailreporthide:boolean=false;
  setMonthAndYear(normalizedMonthAndYear: Moment, datepicker: MatDatepicker<Moment>) {
    const ctrlValue = this.date.value!;
    ctrlValue.month(normalizedMonthAndYear.month());
    ctrlValue.year(normalizedMonthAndYear.year());
    this.date.setValue(ctrlValue);
    datepicker.close();
    this.getStatesForProfessionalTax();
  }
  searchForm!: UntypedFormGroup;
  displayedColumns: string[] = ['sno','state','payrange','tax','employees'];
  displayedColumns2: string[] = [ 'Employee_Id', 'Employee_Name', 'Gross_Salary', 'Professionam_Tax'];
 
  dataSource : MatTableDataSource<any> = <any>[];
  dataSource2 : MatTableDataSource<any> = <any>[];
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  pageLoading = true;
  pageLoading2 = true;
  arrayList:any=[];
  pipe = new DatePipe('en-US');
  userSession:any;
  employeeDetails: any;
  year:any;
  max = new Date();
  minDate:any= new Date('2022-01-01');
  months=[{id:0,month:'Jan'},{id:1,month:'Feb'},{id:2,month:'Mar'},{id:3,month:'Apr'},{id:4,month:'May'},{id:5,month:'Jun'},{id:6,month:'Jul'},{id:7,month:'Aug'},{id:8,month:'Sep'},{id:9,month:'Oct'},{id:10,month:'Nov'},{id:11,month:'Dec'}]
  monthdata: any;
  stateslist:any=[{id:null,state:"ALL"}];
  arrayValue:any=[{Value:0,name:'State-wise Report',"checked": true},{Value:1,name:'Detailed Report',"checked": false}];
  companyName:any;

  constructor(private router: Router,public formBuilder: UntypedFormBuilder,private PR:PayrollService,
    public spinner :NgxSpinnerService,private RS:ReportsService,private dialog: MatDialog) { }
  @ViewChild('table') table!: ElementRef;
statewiseList:any=[];
detailedList:any=[];
  ngOnInit(): void {
    // this.getallEmployeesList();
    
    this.searchForm = this.formBuilder.group({
      fromDate:[new Date()],
      changePaygroup:[0],
      state:[""]
    });
    this.searchForm.controls.sta
    
    this.searchForm.get('state')?.valueChanges.subscribe((selectedValue:any) => {
      if(selectedValue == 'All'){
        this.searchForm.controls.changePaygroup.setValue(1)
      }
    })
    this.companyName = sessionStorage.getItem('companyFullName')
  }
  exportAsXLSX() {
    
    this.year=this.date.value._d.getFullYear();
      for(let i =0;i<this.months.length;i++){
      if((this.date.value._d).getMonth()==this.months[i].id){
       this.monthdata = this.months[i].month;
       break;
      }
    }
    // var ws:XLSX.WorkSheet=XLSX.utils.table_to_sheet('Payroll_report_for_financeteam_');
    var ws:XLSX.WorkSheet=XLSX.utils.table_to_sheet(document.getElementById('table'));
    const wb: XLSX.WorkBook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, this.reporthide?'Pttax_report_for_financeteam_':'Pttax_detail_report_');

    /* save to file */
    // XLSX.writeFile('Payroll_report_for_financeteam_'+this.monthdata,'Payroll_report_for_financeteam_'+this.monthdata+'_'+this.year+'.xlsx')
    XLSX.writeFile(wb, this.reporthide?'Pttax_report_for_financeteam_'+this.monthdata+'_'+this.year+'.xlsx':'Pttax_detail_report_'+this.monthdata+'_'+this.year+'.xlsx');

  }

  Searchform(){
if(this.searchForm.controls.state.value == '' && this.searchForm.controls.state.value != null){
  let dialogRef = this.dialog.open(ReusableDialogComponent, {
    position: { top: `70px` },
    disableClose: true,
    data:"State is not available"
  });
  return ;
}else{

    let data ={
      date:this.pipe.transform( this.date.value._d, 'yyyy-MM-dd')
    }
    if(this.searchForm.controls.changePaygroup.value == 0 ){
      this.detailreporthide = false;
      this.reporthide = true;
      this.getProfessionalTaxValuesForChallan();
    }
    else{
      this.detailreporthide = true;
      this.reporthide = false;
      this.getProfessionalTaxDetailReport()
    }
  }

  }
  resetform(){
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
          this.router.navigate(["/Payroll/ProfessionaTaxReport"]));
    }
    getPageSizes(): number[] {
      var customPageSizeArray = [];
      
        if (this.dataSource.data.length > 5) {
          customPageSizeArray.push(5);
        }
        if (this.dataSource.data.length > 10) {
          customPageSizeArray.push(10);
        }
        if (this.dataSource.data.length > 20) {
          customPageSizeArray.push(20);
         
        }
        customPageSizeArray.push(this.dataSource.data.length);
        return customPageSizeArray;
   }
   getPageSizes2(): number[] {
    var customPageSizeArray = [];
    
      if (this.dataSource2.data.length > 5) {
        customPageSizeArray.push(5);
      }
      if (this.dataSource2.data.length > 10) {
        customPageSizeArray.push(10);
      }
      if (this.dataSource2.data.length > 20) {
        customPageSizeArray.push(20);
       
      }
      customPageSizeArray.push(this.dataSource2.data.length);
      return customPageSizeArray;
 }
  public exportPDF(): void {
    this.year=this.date.value._d.getFullYear();
    for(let i =0;i<this.months.length;i++){
    if((this.date.value._d).getMonth()==this.months[i].id){
     this.monthdata = this.months[i].month;
     break;
    }
  }
    const pdfTable = this.table.nativeElement;
    var html = htmlToPdfmake(pdfTable.innerHTML);
    pdfMake.createPdf({
      info: {
        title: this.reporthide?"Professional Tax Report":"Professional Tax Detail Report",
        author:'Sreeb tech',
        subject:'Theme',
            keywords:'Report'
      },
      footer: function (currentPage, pageCount) {
        return {
          margin: 10,
          columns: [
            {
              fontSize: 9,
              text: [
                {
                  text: 'Page ' + currentPage.toString() + ' of ' + pageCount,
                }
              ],
              alignment: 'center'
            }
          ]
        };
      },
      content: [
        { columns: [
          { text: this.companyName, style: 'title', alignment: 'center' },
        ]      
      },
        {
          columns: [
              {
                text: this.reporthide ? "Professional Tax Report" : "Professional Tax Detail Report",
                style: 'subtitle',
                alignment: 'left',
                margin:[0, 5, 0, 10]
              },
              { text: `Date: ${this.monthdata}- ${this.year}`, style: 'subtitle', alignment: 'right' },
            ]      

        },
      {
        canvas: [   {    type: 'line',   x1: 0,    y1: 0,  x2: 1110,      y2: 0,   lineWidth: 1,     }, ],
      },'\n', 
    

        // {
        //   text:
        //     "Designation :  " + this.designationForPdf +"\n" +
        //     "Employee Name and Id:  " + this.employeeNameForPdf + "\n" +
        //     "Year:  " + this.searchForm.controls.calenderYear.value+ "\n",
        //   fontSize: 10,
        //   margin: [0, 0, 0, 20],
        //   alignment: 'left'
        // },
        html
      ],

      styles:{
        title: {
          fontSize: 16,
          bold: true,
          margin: [0, 0, 0, 5],
        },
        subtitle: {
          fontSize: 12,
          bold: true,
          margin: [0, 5, 0, 10],
        },
        html: {
          alignment: 'center',
        },
      },
      pageOrientation: 'landscape'//'portrait'
    }).download(this.reporthide?"Professional tax challan Report for "+this.monthdata+","+this.year +".pdf":"Professional tax detail Report for "+this.monthdata+","+this.year +".pdf");

  }
  getProfessionalTaxValuesForChallan(){
    let data ={
      year:this.date.value._d.getFullYear(),
      month:this.date.value._d.getMonth()+1,
      state:this.searchForm.controls.state.value=='All'?null:Number(this.searchForm.controls.state.value)
    }
    this.dataSource=new MatTableDataSource()
    this.PR.getProfessionalTaxValuesForChallan(data).subscribe((result:any)=>{
     if(result.status){
       this.reporthide = true;
       this.detailedList = result.data;
        this.detailedList[0].Gross_Salary == null || undefined ? this.dataSource = new MatTableDataSource(result.data) : this.dataSource = new MatTableDataSource();
      // this.dataSource = new MatTableDataSource(result.data);
       this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;
     }
       
      
    })
  }
  getProfessionalTaxDetailReport(){
    let data ={
      year:this.date.value._d.getFullYear(),
      month:this.date.value._d.getMonth()+1,
      state:this.searchForm.controls.state.value=='All'?null:Number(this.searchForm.controls.state.value)
    }
    this.dataSource2=new MatTableDataSource()
    this.PR.getProfessionalTaxDetailReport(data).subscribe((result:any)=>{
     if(result.status){
      this.detailreporthide = true;
      this.reporthide = false;
      this.statewiseList = result.data;
      this.statewiseList[0].Gross_Salary != null ?this.dataSource2 = this.statewiseList : this.dataSource2 = new MatTableDataSource();
      this.dataSource2.paginator = this.paginator;
        this.dataSource2.sort = this.sort;
        this.pageLoading2 = false;
     }
   })
 }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
     if (this.dataSource.paginator) {
       this.dataSource.paginator.firstPage();
    }
  }
  getStatesForProfessionalTax(){
    let data ={
      year:this.date.value._d.getFullYear(),
      month:this.date.value._d.getMonth()+1,
     
    }
    this.PR.getStatesForProfessionalTax(data).subscribe((result:any)=>{
     if(result.status){
      this.stateslist = result.data;
      if(result.data[0].status == 0){
        this.statehide= true;

      }else{
        this.statehide= false;
      }

      
     }
       
      
    })
  }

}

