  requestView(event: any) {
    this.isView = true;
     
    if (event.comment != null || "") {
      if (event.status == 'Approved') {
        this.isStatus = true;
      } else {
        this.isStatus = false;
      }
      this.requestform.controls.comment.setValue("");
    };
    this.fhalfDisable = true;
    this.shalfDisable = true;
    this.isFirstHalf = false;
    this.isSecondHalf = false;
    this.attendanceid = event.id;
    this.isRequestView = true;
    this.isEditView = false;
    this.isCommentView = false;
    this.requestform.controls.document.setValue('');
    this.fileURL = '';
    this.pdfName = '';
    this.requestform.controls.appliedDate.setValue(this.pipe.transform(event.applieddate, 'dd-MM-yyyy'));
    this.requestform.controls.shift.setValue(event.shift);
    this.requestform.controls.shift.disable();
    this.requestform.controls.fromDate.setValue(event.fromdate);
    this.requestform.controls.fromDate.disable();
    this.requestform.controls.toDate.setValue(event.todate);
    this.requestform.controls.toDate.disable();
    this.requestform.controls.reason.setValue(event.reason);
    this.requestform.controls.reason.disable();
    if (event.comment != null || "") {
      this.isCommentView = true;
      this.requestform.controls.comment.setValue(event.comment);
      this.requestform.controls.comment.disable();
    }
    this.workTypeData.forEach((e: any) => {
      if (e.type == event.worktype) {
        this.requestform.controls.workType.setValue(e.id);
        this.requestform.controls.workType.disable();
      }
    });
    if (event.halfdayattendance == 1) {
      this.isFirstHalf = true;
    } else if (event.halfdayattendance == 2) {
      this.isSecondHalf = true;
    } else {
      this.isFirstHalf = false;
      this.isSecondHalf = false;
    }
    this.getEmployeeShiftDetailsByIdWithDates();
    this.getUploadDocument();
  }


  getMessagesList() {
    let data =
    {
      "code": null,
      "pagenumber": 1,
      "pagesize": 100
    }
    this.adminService.getMessagesListApi(data).subscribe((res: any) => {
      if (res.status) {
        this.messagesDataList = res.data;
        this.messagesDataList.forEach((e: any) => {
          if (e.code == "ATT2") {
            this.requiredOption = e.message
          } else if (e.code == "ATT1") {
            this.requiredField = e.message
          } else if (e.code == "ATT12") {
            this.dataNotSave = e.message
          } else if (e.code == "ATT11") {
            this.dataSave = e.message
          } else if (e.code == "ATT75") {
            this.ATT75 = e.message
          }
          else if (e.code == "ATT74") {
            this.ATT74 = e.message
          } else if (e.code == "ATT62") {
            this.ATT62 = e.message
          }
        })
      }
      else {
        this.messagesDataList = [];
      }

    })
  }

  getEmployeeEmailData() {
    this.employeeEmailData = [];
    this.emsService.getEmployeeEmailDataByEmpid(this.userSession.id)
      .subscribe((res: any) => {
        this.employeeEmailData = JSON.parse(res.data[0].jsonvalu)[0];
      })
  }



  onSelectFile(event: any) {
    this.iseditDoc = true;
    if (event.target.files.length != 0) {
      if (event.target.files[0].size <= 2097152) {
        this.file = event.target.files[0];
        var pdf = this.file.name.split('.');
        if (pdf[pdf.length - 1] == 'pdf' || pdf[pdf.length - 1] == 'jpg' || pdf[pdf.length - 1] == 'png') {
          this.isFile = true;
        } else {
          this.isFile = false;
          this.dialogService.openDialog("Only PNG,JPEG,JPG & PDF format allowed");
          this.requestform.controls.document.setValue('');
        }
      } else {
        this.isFile = false;
        this.dialogService.openDialog("Please upload less than 2MB file");
        this.requestform.controls.document.setValue('');
      }
    } else {
      this.dialogService.openDialog("Invalid document");
      this.requestform.controls.document.setValue('');
    }
  }

  deleteIcon() {
    this.isedit = false;
    this.requestform.controls.document.setValue('');
  }

  delete() {
    this.isedit = false;
  }

  getUploadDocument() {
    let info = {
      'employeeId': this.userSession.id,
      'candidateId': null,
      'filecategory': 'ATTENDANCE',
      'moduleId': 4,
      'requestId': this.attendanceid,
      'status': 'Submitted'
    }
    this.LM.getFilesMaster(info).subscribe((result) => {
      if (result && result.status && result.data.length > 0) {
        this.documentId = result.data[0].id;
        this.documentInfo = JSON.stringify(result.data[0])
        this.pdfName = result.data[0].fname

        result.data[0].employeeId = this.userSession.id;
        let info = result.data[0]
        this.LM.getProfileImage(info).subscribe((imageData) => {
          if (imageData.success) {
            this.document = true;
            this.requestform.controls.document.value = true;
            this.requestform.controls.document.clearValidators();
            this.requestform.controls.document.updateValueAndValidity();
            this.iseditDoc = false;


            let TYPED_ARRAY = new Uint8Array(imageData.image.data);
            const STRING_CHAR = TYPED_ARRAY.reduce((data, byte) => {
              return data + String.fromCharCode(byte);
            }, '');
            var documentName = this.pdfName.split('.');
            // const file = new Blob([TYPED_ARRAY], { type: "application/pdf" });
            // this.fileURL = URL.createObjectURL(file);
            if (documentName[documentName.length - 1] == 'pdf') {
              const file = new Blob([TYPED_ARRAY], { type: 'application/pdf' });
              this.fileURL = URL.createObjectURL(file);
            } else {
              const file = new Blob([TYPED_ARRAY], { type: 'image/png' });
              this.fileURL = URL.createObjectURL(file);
            }
          }
        })
      }
      else {
      }
    })
  }

  fileView() {
    window.open(this.fileURL);
  }

  editdoc() {
    this.pdfName = null;
  }

