import { DatePipe } from '@angular/common';
import { Component, ElementRef, OnInit, ViewChild,Output,EventEmitter,Input } from '@angular/core';
import { FormBuilder, FormControl, UntypedFormControl,FormGroup  } from '@angular/forms';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import * as _moment from 'moment';
import { MatDatepicker } from '@angular/material/datepicker';
import { Moment } from 'moment';
import { NgxSpinnerService } from 'ngx-spinner';
// import {default as _rollupMoment} from 'moment';
const moment = _moment;

export const MONTH_FORMAT = {
  parse: { dateInput: 'MMM YYYY' },
  display: {
    dateInput: 'MMM YYYY',
    monthYearLabel: 'MMM YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'MMMM YYYY'
  }
};

@Component({
  selector: 'app-month-year-selection',
  templateUrl: './month-year-selection.component.html',
  styleUrls: ['./month-year-selection.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE],  },
    { provide: MAT_DATE_FORMATS, useValue: MONTH_FORMAT, },  
  ]
  })
export class MonthYearSelectionComponent implements OnInit {
  minDate = new Date('2020/01/01'); maxDate = new Date();
  userSession: any;
  date = new Date();
  startDate = new Date(this.date.getFullYear(), this.date.getMonth(), 1);
  endDate = new Date(this.date.getFullYear(), this.date.getMonth() + 1, 0);
  maxToDate: Date | null = null;
  minToDate: Date | null = null;

  maxFromDate: Date | null = null;
  minFromDate: Date | null = null;
  minMonthYear = moment('2020-01-01', 'YYYY-MM');
  maxMonthYear = moment('2025-12-31', 'YYYY-MM');
  minYear = moment().year() - 4;
  maxYear = moment().year();
  today = moment();
  selectedMonth:any ='';
@Input() reset: boolean = false;
  @ViewChild('table') table!: ElementRef;
  constructor( public datePipe: DatePipe, public formBuilder: FormBuilder, 
    private spinner: NgxSpinnerService,private fb: FormBuilder, ) { }
  searchForm = this.formBuilder.group({
    monthYear: [moment()]   // default to current month/year
  });
  dateFilter = (date: Moment | null): boolean => {
    if (!date) return false;
    const year = date.year();
    return year >= this.minYear && year <= this.maxYear;
  };

  @Output() month_selected = new EventEmitter<any>();

sendData() {
  this.month_selected.emit(this.selectedMonth);
}

ngOnInit() {
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    this.selectedMonth = moment().startOf('month');
    this.searchForm.controls['monthYear'].setValue(this.selectedMonth);
    this.sendData();
}


ngOnChanges(changes: any) {
  if (changes['reset'] && this.reset) {
    this.selectedMonth = moment().startOf('month');
    this.searchForm.controls['monthYear'].setValue(this.selectedMonth);
    setTimeout(() => this.reset = false);
    this.sendData();
  }
}


onSetMonthAndYear(normalizedMonthAndYear: Moment, datepicker: MatDatepicker<Moment>) {
  const year = normalizedMonthAndYear.year();
  const month = normalizedMonthAndYear.month();
 // if (year < this.minYear || year > this.maxYear) return; // prevent future years
  this.selectedMonth = moment({ year, month });
  this.searchForm.controls['monthYear'].setValue(this.selectedMonth);
  datepicker.close();
  this.sendData();
}
  
}