import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
@Component({
  selector: 'app-test-result-screen',
  templateUrl: './test-result-screen.component.html',
  styleUrls: ['./test-result-screen.component.scss']
})
export class TestResultScreenComponent implements OnInit {

  constructor(
    private router: Router,
  ) { }

  ngOnInit(): void {
  }

  navigateToTestScreen() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/learning/detailedCourseInformation']));
  }
  navigationToPrevScreen() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/learning/detailedCourseInformation']));
  }
  viewReport() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/learning/testReport']));

  }
  Test() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/learning/testScreen']));
  }
}
