import { Component, OnInit, Renderer2, TemplateRef, ViewChild } from '@angular/core';
import { CrmService } from "../../crm.service";
import { FormControl } from '@angular/forms';
import { CalendarOptions } from '@fullcalendar/angular';
import { ActivatedRoute } from '@angular/router';
import { MatDialog } from '@angular/material/dialog';
import dayGridPlugin from '@fullcalendar/daygrid';
import timeGridPlugin from '@fullcalendar/timegrid';
import interactionPlugin from '@fullcalendar/interaction';

@Component({
  selector: 'app-crm-tour-plan',
  templateUrl: './crm-tour-plan.component.html',
  styleUrls: ['./crm-tour-plan.component.scss']
})
export class CrmTourPlanComponent implements OnInit {
  @ViewChild('dialogTemplate') dialogTemplate!: TemplateRef<any>;

  userSession: any;
  isManager: boolean = false;
  employees: any[] = [];
  leadStatuses: any[] = [];
  leadStages: any[] = []; // Add leadStages
  selectedLeadStatusControl: FormControl = new FormControl(0);
  selectedLeadStageControl: FormControl = new FormControl(0); // Control for lead stages
  employeeColors: { [key: string]: string } = {};
  selectedEventData: any = {};
  hoveredEmployeeId: number | null = null;
  selectedEmployeeIds: number[] = [];
  isSelectAllActive: boolean = false;
  colorPalette: string[] = ['#9966ff', '#00FF00', '#FFFF00', '#FFA500', '#800080', '#FFC0CB', '#A52A2A', '#808080', '#00000', '#00FFFF', '#FF00FF', '#00FF00', '#FA8072', '#008080'];

  calendarOptions: CalendarOptions = {
    initialView: 'dayGridMonth',
    plugins: [dayGridPlugin, timeGridPlugin, interactionPlugin],
    events: [],
    height: 'auto',
    editable: false,
    selectable: true,
    headerToolbar: {
      left: 'prev,next today',
      center: 'title',
      right: 'dayGridMonth,timeGridWeek,timeGridDay'
    },
    slotLabelFormat: {
      hour: '2-digit',
      minute: '2-digit',
      hour12: true
    },
    eventTimeFormat: { 
      hour: '2-digit',
      minute: '2-digit',
      hour12: true 
    },
    eventBorderColor: '#D3DED3',
    eventTextColor: '#000',
    dayMaxEventRows: 3,
    moreLinkClick: 'popover',
    eventClick: this.handleEventClick.bind(this),
    eventMouseEnter: this.handleEventMouseEnter.bind(this), 
    eventMouseLeave: this.handleEventMouseLeave.bind(this),
    datesSet: this.applyFixedDayCellHeight.bind(this) // Reapply fixed height when the dates are updated 
  };

  constructor(
    private crm: CrmService,
    private route: ActivatedRoute,
    public dialog: MatDialog,
    private renderer: Renderer2 
  ) { }

  ngOnInit(): void {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '{}');
    this.isSelectAllActive = true; // Highlight the "Select All" button initially
    this.route.url.subscribe(segments => {
      const path = segments[0]?.path;
      this.isManager = path.startsWith('Mgr'); // Detect if the user is a manager
  
      if (this.isManager) {
        this.loadEmployeesForManager(); // Load employees for the manager
      } else {
        this.loadTourPlanData(this.userSession.id, this.selectedLeadStatusControl.value); // Load employee's own data
      }
    });
  
    this.loadLeadStatuses();
    this.loadLeadStages(); // Load lead stages

  

  
    // Listen to lead status selection changes
    this.selectedLeadStatusControl.valueChanges.subscribe((selectedStatus: number) => {
      this.loadTourPlanData(this.selectedEmployeeIds[0], selectedStatus); // Load data for selected lead status and employee
    });

    this.selectedLeadStageControl.valueChanges.subscribe((selectedStage: number) => {
      this.loadTourPlanData(this.selectedEmployeeIds[0], this.selectedLeadStatusControl.value, selectedStage);
    });


    setTimeout(() => {
      this.animateScrollIndicator();
    }, 2000); 

    setTimeout(() => {
      this.applyFixedDayCellHeight();
    }, 500); // Ensure calendar is rendered before applying styles

  
  
  }
  

  // Load lead statuses for filtering
  loadLeadStatuses(): void {
    const params = { page: 1, limit: 100 };
    this.crm.getSprypleData(params, 'get_crm_client_status_values_master').subscribe(
      (res: any) => {
        if (res && res.status && res.data.length > 0) {
          this.leadStatuses = res.data;
        }
      },
      (error: any) => {
        console.error('Error fetching lead statuses:', error);
      }
    );
  }

  loadLeadStages(): void {
    const params = {
      is_active: 1,  
      pagenumber: 1, 
      pagesize: 100  
    };
  
    this.crm.getSprypleData(params, 'get_crm_lead_stages').subscribe(
      (res: any) => {
        if (res && res.status && res.data.length > 0) {
          this.leadStages = res.data;
        }
      },
      (error: any) => {
        console.error('Error fetching lead stages:', error);
      }
    );
  }
  


  

  // Load employees for the manager
  loadEmployeesForManager(): void {
    const params = { rm_id: this.userSession.id, selected_date: null };
    this.crm.getSprypleData(params, 'get_crm_employees_for_managers').subscribe(
      (res: any) => {
        if (res && res.status && res.data.length > 0) {
          this.employees = res.data;
          this.assignColorsToEmployees();
          this.loadTourPlanData(0);
        }
      },
      (error: any) => {
        console.error('Error fetching employees:', error);
      }
    );
  }

  // Assign colors to employees
  assignColorsToEmployees(): void {
    this.employees.forEach((emp, index) => {
      this.employeeColors[emp.empid] = this.colorPalette[index % this.colorPalette.length];
    });
  }

  // Load tour plan data for selected employee and lead status

  loadTourPlanData(empId?: number, selectedLeadStatus?: number, selectedLeadStage?: number): void {
    // Ensure values are being correctly set
    const employeeId = empId !== undefined ? empId : this.selectedEmployeeIds.length > 0 ? this.selectedEmployeeIds[0] : 0;
    const leadStatusId = selectedLeadStatus !== undefined ? selectedLeadStatus : this.selectedLeadStatusControl.value;
    const leadStageId = selectedLeadStage !== undefined ? selectedLeadStage : 0; // Set to 0 if no lead stage is selected
  
    // Create the params object to pass to your API
    const params = {
      manager_id: this.isManager ? this.userSession.id : null,
      empid: employeeId,  // Use 0 for all employees or a specific employee ID
      from_date: null,
      to_date: null,
      client_status_id: leadStatusId, // Pass lead status ID
    };
  
    // Log params to debug their values and ensure they are correct
  
    // Pass the params object to your service call
    this.crm.getSprypleData(params, 'get_crm_follow_ups_filtered').subscribe(
      (res: any) => {
        if (res && res.status && res.data.length > 0) {
          const events = res.data.map((followUp: any) => ({
            title: followUp.client_name,
            start: followUp.next_follow_up_on,
            description: followUp.notes,
            backgroundColor: this.employeeColors[followUp.emp_id] || '#2196F3',
            borderColor: this.employeeColors[followUp.emp_id],
            textColor: '#000000',
            extendedProps: {
              emp_id: followUp.emp_id, // Employee ID for hover and highlight
              clientName: followUp.client_name,
              // leadName:followUp.lead_name,
              phone: followUp.phone,
              email: followUp.email,
              location: followUp.location,
              leadStatus: followUp.client_status,
              assignedBy:followUp.assigned_by_name,
              // leadStage: followUp.lead_stage_name, 
              empName: followUp.emp_name,
              description: followUp.notes
            }
          }));
  
          this.calendarOptions.events = events;
        } else {
          this.calendarOptions.events = [];
        }
      },
      (error: any) => {
        console.error('Error fetching follow-up data:', error);
        this.calendarOptions.events = [];
      }
    );
  }
  
  
  
  handleEventClick(info: any): void {
    this.dialog.open(this.dialogTemplate, {
      data: {
        empName: info.event.extendedProps.empName,
        leadName: info.event.extendedProps.leadName,
        clientName: info.event.extendedProps.clientName,
        phone: info.event.extendedProps.phone,
        email: info.event.extendedProps.email,
        location: info.event.extendedProps.location,
        leadStatus: info.event.extendedProps.leadStatus,
        leadStage: info.event.extendedProps.leadStage,
        description: info.event.extendedProps.description,
        assignedBy: info.event.extendedProps.assignedBy,
        date: info.event.start 
      },
      width: '350px', 
    });
  }
  

  handleEventMouseEnter(info: any): void {
    this.hoveredEmployeeId = info.event.extendedProps.emp_id;
  }

  handleEventMouseLeave(info: any): void {
    this.hoveredEmployeeId = null;
  }

  toggleEmployeeSelection(empId: number): void {
    this.isSelectAllActive = false; // Deselect "Select All" when an employee is selected
    this.selectedEmployeeIds = [empId]; // Select only one employee
    this.loadTourPlanData(empId, this.selectedLeadStatusControl.value);
  }
  
  
  toggleSelectAll(): void {
    this.isSelectAllActive = true;
    this.selectedEmployeeIds = [0]; // Select all employees
    this.loadTourPlanData(0, this.selectedLeadStatusControl.value);
  }
  
  
  
  animateScrollIndicator(): void {
    const legendElement = document.querySelector('.color-legend');
    if (legendElement) {
      let scrollAmount = 0;
      const scrollMax = 20; // Amount to scroll
      let scrollDirection = 1; // 1 for down, -1 for up
  
      const scrollInterval = setInterval(() => {
        scrollAmount += scrollDirection;
        legendElement.scrollTop = scrollAmount;
        if (scrollAmount === scrollMax || scrollAmount === 0) {
          scrollDirection *= -1; // Reverse direction
        }
      }, 65); // Adjust speed if necessary
  
      // Stop the scroll animation after 3 seconds
      setTimeout(() => clearInterval(scrollInterval), 2500);
    }
  
  }

  applyFixedDayCellHeight(): void {
    const dayCells = document.querySelectorAll('.fc-daygrid-day');
    dayCells.forEach(cell => {
      this.renderer.setStyle(cell, 'height', '120px'); // Apply fixed height of 100px
    });
  }

  
  
}
