import { SelectionModel } from '@angular/cdk/collections';
import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';

@Component({
  selector: 'app-assign-course',
  templateUrl: './assign-course.component.html',
  styleUrls: ['./assign-course.component.scss']
})
export class AssignCourseComponent implements OnInit {
  courseForm!: FormGroup;

  list: string[] = [
    'Angular Course Online with Certificates',
    'Java Online with Certificates',
    'MySQL Online with Certificates',
    'React Online with Certificates',
    'NodeJS Online with Certificates',
    'Front-end Online with Certificates',
    'Full-Stack Online with Certificates',
    'Backend Online with Certificates',
    'UI/UX Online with Certificates',
  ];

  displayedColumns: string[] = ['select', 'sno', 'employeeId', 'employeeName', 'course'];

  dataSource = [
    { id: 1, empid: 'KP1', name: 'Pranitha', course: 'Angular Course Online with Certificates' },
    { id: 2, empid: 'KP2', name: 'Mahesh', course: 'Java Course Online with Certificates' },
    { id: 3, empid: 'KP3', name: 'Vinil', course: 'MySQL Course Online with Certificates' },
    { id: 4, empid: 'KP4', name: 'Manasa', course: 'React Course Online with Certificates' },
    { id: 5, empid: 'KP5', name: 'Shruthi', course: 'NodeJS Course Online with Certificates' },
    { id: 6, empid: 'KP6', name: 'Prasad', course: 'Front-end Course Online with Certificates' },
    { id: 7, empid: 'KP7', name: 'SriRamya', course: 'Full-Stack Course Online with Certificates' },
    { id: 8, empid: 'KP8', name: 'Rakesh', course: 'Backend Course Online with Certificates' },
  ];

  selection = new SelectionModel<any>(true, []);

  constructor(private fb: FormBuilder) {}

  ngOnInit(): void {
    this.courseForm = this.fb.group({
      course: ['', Validators.required],
      is_mandatory: [0, Validators.required],
      due_date: [new Date(), Validators.required],
    });
  }

  masterToggle() {
    if (this.isSomeSelected()) {
      this.selection.clear();
    } else {
      this.isAllSelected()
        ? this.selection.clear()
        : this.dataSource.forEach((row) => this.selection.select(row));
    }
  }

  isSomeSelected() {
    return this.selection.selected.length > 0;
  }

  isAllSelected() {
    const numSelected = this.selection.selected.length;
    const numRows = this.dataSource.length;
    return numSelected === numRows;
  }
  submit() { }
  cancel() { }

}
