  mixedRegularization(data: any) {
    this.regularDayData = data;
    let givenData = {
      "halfDaytype": data.halfday,
      "attendancetype": true,
      "regularType": 'regular',
      "isLogoutTime": data.logouttime
    }
    let dialogRef = this.dialog.open(HalfdayDialogboxComponent, {
      width: '500px', position: { top: `100px` },
      disableClose: true,
      data: givenData

    });
    dialogRef.afterClosed().subscribe(result => {

      if (result != undefined) {
        if (result == 'attendance') {
          this.isFulldayRegularization = true;
          this.setMixedAttendanceRegularization(this.regularDayData);

        } else if (result == 'leave') {
          this.isFulldayRegularization = false;
          this.setLeaveRegularization(this.regularDayData);

        } else if (result == 'halfday_attendance_leave') {
          this.isFulldayRegularization = false;
          this.setMixedAttendanceRegularization(this.regularDayData);

        }
      }
    });
  }

  setMixedAttendanceRegularization(value: any) {
    if (this.btnDisable) {
      return;
    }
    let selectedEmp = [];
    let setdata = {
      emp_id: value.empid,
      shiftid: value.shiftid,
      attendancedate: value.attendancedate,
      logintime: value.logintime,
      logouttime: value.logouttime,
      worktype: value.worktypeid,
      halfday: this.isFulldayRegularization == true ? 0 : value.halfday,
      raisedby: value.empid,
      approvercomments: '',
      actionby: this.userSession.id,
      status: 'Approved'
    }
    selectedEmp.push(setdata)
    let payload = {
      input_data: selectedEmp,
    }
    this.btnDisable = true;
    this.attendanceService.setDiscrepanciesAttendanceRegularization(payload).subscribe((result: any) => {
      if (result.status && result.data[0].validity_status == 1) {
        this.dialogService.openDialog('Attendance regularization saved successfully');
        this.getMixedRegularizationList();
        this.btnDisable = false;

      } else if (result.status && result.data[0].validity_status == 0) {
        this.dialogService.openDialog('Record already exist');
        this.btnDisable = false;
      } else {
        this.dialogService.openDialog('Unable to save attendance regularization');
        this.btnDisable = false;
      }

    })

  }

