  fulldayGeneratePDF() {

    const doc = new jsPDF();
    const reportName = 'Full day attendance regularization pending list';
    let manager = '';
    let locationName = '';
    let reportDate = this.datePipe.transform(new Date(), "dd-MM-YYYY");
    const headerHeight = 33;
    const tableData = this.fullDayList.map((emp: {
      attendancedate: any;
      empcode: any;
      empname: any;
      shiftname: any;


    }, index: number) => [

        index + 1,
        this.datePipe.transform(emp.attendancedate, "dd-MM-yyyy"),
        emp.empcode,
        emp.empname,
        emp.shiftname,

      ]);
    autoTable(doc, {
      head: [['S. No.', 'Date', 'Emp. ID', 'Emp. Name', 'Shift']],
      body: tableData,
      startY: headerHeight,
      styles: { fontSize: 10 },
      headStyles: { fontSize: 11 },
      margin: { top: headerHeight },
      didDrawPage: (data) => {
        this.pdfService.generatePDFHeader(doc, reportName, locationName, manager, reportDate, false, false);
        doc.setFontSize(10);
        doc.setTextColor(40);
      }
    });
    doc.save('Full_day_attendance_regularize_Report.pdf');

  }

  fulldayExportAsXLSX() {
    const exportData = this.fullDayList.map((row: any, index: any) => ({
      "S.No": index + 1,
      "Date": this.datePipe.transform(row.attendancedate, "dd-MM-yyyy"),
      "Emp. ID": row.empcode,
      "Emp. Name": row.empname,
      "Shift": row.shiftname,
    }));
    const ws: XLSX.WorkSheet = XLSX.utils.json_to_sheet(exportData);
    const wb: XLSX.WorkBook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Fullday_attendance_regularize');
    XLSX.writeFile(wb, 'Fullday_attendance_regularize.xlsx');
  }

