  private getCellValue(row: any, key: string) {
    switch (key) {
      case 'sno': return row.sno ?? '';
      case 'empname': return row.emp_name ?? row.empname ?? '';
      case 'empcode': return row.empcode ?? '';
      case 'department': return row.deptname ?? '';
      case 'section': return row.section ?? '';
      case 'designation': return row.designation ?? '';
      case 'location': return row.location ?? '';
      case 'grosssalary': return row.total_salary ?? row.grosssalary ?? 0;
      case 'extradaysamount': return row.extra_days_amount ?? row.extradaysamount ?? 0;
      case 'professionaltax': return row.professional_tax ?? row.professionaltax ?? 0;
      case 'esi': return row.total_esi_value ?? row.esi ?? 0;
      case 'epf': return row.total_epf_value ?? row.epf ?? 0;
      case 'latecount': return row.late_count ?? row.latecount ?? 0;
      case 'lopsforlate': return row.lops_for_late ?? row.lopsforlate ?? 0;
      case 'amountlate': return row.amount_late ?? row.amountlate ?? 0;
      case 'totaldeductions': return row.total_deductions ?? row.totaldeductions ?? 0;
      case 'totaldays': return row.total_days ?? row.totaldays ?? 0;
      case 'paiddays': return row.paid_days ?? row.paiddays ?? 0;
      case 'extradays': return row.extra_days ?? row.extradays ?? 0;
      case 'penaltydays': return row.penalty_days ?? row.penaltydays ?? 0;
      case 'leaveCount': return row.leaveCount ?? row.leave_count ?? 0;
      case 'leaveEncashment': return row.leaveEncashment ?? row.leave_encashment ?? 0;
      case 'lopdays': return row.lop_days ?? row.lopdays ?? 0;
      case 'netsalary': return row.total_net_salary ?? row.netsalary ?? 0;

      default: return row[key] ?? '';
    }
  }


  showEmployeeDetails(emp: any): void {
    if (this.selectedEmployee && this.selectedEmployee.empcode === emp.empcode) {
      this.selectedEmployee = null;
    } else {
      this.selectedEmployee = emp;
    }

    setTimeout(() => {
      if (this.detailsSection) {
        this.detailsSection.nativeElement.scrollIntoView({ behavior: 'smooth' });
      }
    }, 100);
  }

