  exportToExcel(): void {
    if (!this.previewDataSource.data.length) {
      alert('No data available to export');
      return;
    }

    const exportData = this.previewDataSource.data.map((row, index) => {

  const base: any = {
    'S.No': index + 1,
    'Emp. Code': row.empcode,
    'Emp. Name': row.emp_name,
    'Department': row.deptname,
  };

  //  Insert Section right after Department
  if (this.sectionflag) {
    base['Section'] = row.section_name;
  }

  Object.assign(base, {
    'Designation': row.designation,
    'Work Location': row.location,
    'Gross Salary': row.total_salary,
    'Extra Days Amount': row.extra_days_amount,
    'Professional Tax': row.professional_tax,
    'ESI': row.total_esi_value,
    'EPF': row.total_epf_value,
    'Late Count': row.late_count,
    'Deducted LoPs': row.lops_for_late,
    'Deducted Amount': row.amount_late,
    'Total Deductions': row.total_deductions,
    'Total Days': row.total_days,
    'leaveCount': row.leave_count ?? row.leaveCount ?? 0,
    'leaveEncashment': row.leave_encashment,
    'Paid Days': row.paid_days,
    'Extra Days': row.extra_days,
    'LoP Days': row.lop_days,
    'Net Salary': row.total_net_salary,
  });

  // Penalty can still be conditional
  if (this.showPenalty) {
    base['Penalty Days'] = row.penalty_days;
  }

  return base;
});


    const worksheet: XLSX.WorkSheet = XLSX.utils.json_to_sheet(exportData);
    const workbook: XLSX.WorkBook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Salary Preview');
    XLSX.writeFile(workbook, 'SalaryPreview.xlsx');
  }

  exportToPDF(): void {
    if (!this.previewDataSource.data.length) {
      alert('No data available to export');
      return;
    }

    const doc = new jsPDF({ orientation: 'landscape' });
    doc.setFontSize(14);
    // doc.text('Salary Preview', 14, 15);
     doc.text(
    'Preview Salaries',
    doc.internal.pageSize.getWidth() / 2,
    15,
    { align: 'center' }
  );

    const head = [this.displayedColumns.map(col => this.columnLabelMap[col] || col)];


    const body = this.previewDataSource.data.map((row, index) =>
      this.displayedColumns.map(col => {
          if (col === 'sno') {
      return index + 1; 
    }
        return this.getCellValue(row, col)
  })
    );

    (doc as any).autoTable({
      head: head,
      body: body,
      startY: 22,
      styles: { fontSize: 7 },
      theme: 'striped',
    });

    doc.save('SalaryPreview.pdf');
  }

