 check_back_params(){
  let back_params: any = sessionStorage.getItem('back_url') ? JSON.parse(sessionStorage.getItem('back_url')??'[]'): '[]';
  if(back_params && back_params.redirected){
    this.isRedirected =  true;
    this.searchForm.controls.fromDate.setValue(back_params.from_date);
    this.searchForm.controls.toDate.setValue(back_params.to_date);
    this.selectedManagers = back_params.selectedManagers;
    if(this.is_super_admin){
      this.searchForm.controls.companylocation.setValue(back_params.companylocations);
      this.searchForm.controls.managers.setValue(back_params.selectedManagers);
    }
    
    if(this.employeelist && this.employeelist.length == 0){
      this.employeelist = back_params.users;
      this.filteredEmployees = this.employeelist;
    }
     
     
    this.searchForm.controls.Users.setValue(back_params.userId);        
    this.Searchform();
  }  else {
    this.isRedirected =  false;
    sessionStorage.setItem('back_url','');
    this.is_super_admin?null:this.Searchform();
  }
 }

