    getAddress(r:any,type:any ){
      let address = '';
      if(type === 'start'){
        if(r.start_address && r.start_address.toString().length > 0){
          address = r.start_address;
        }
        else if(r.location && r.location.toString().length  > 0){
          address = r.location;
        }
      }
      if(type === 'end'){
        if(r.end_address && r.end_address.toString().length > 0){
          address = r.end_address;
        }
        else if(r.location && r.location.toString().length  > 0){
          address = r.location;
        }
      }
      return address;
    }
    
    getDetailsForPdf(details: any,type:any,add_string:any = '\n') {
      //  if (type !== 'pdf') {
      //   return '';
      // }
      let val: any[] = []; // Changed from string to array to handle images correctly
      let str_val:string = '';
      details.forEach((det: any) => {
        if(type == 'pdf'){
          if(val && val.length) val.push('\n');
          if (det.activity_type) val.push(det.activity_type+add_string);
          if (det.client_name) val.push('Client: ' + det.client_name+add_string);
          if (det.attendance_type) val.push(det.attendance_type+add_string);
          if (det.notes && !det.notes.includes('MOBILEAPP'))  val.push('Notes: ' + det.notes+add_string); 
          if (det.imageData && det.imageData.image && add_string != ' ') {           
            val.push({ image: det.imageData.image, width: 50, height: 50,  alignment: 'center' });
          }
        }
        else str_val = (str_val + ((det.activity_type)?det.activity_type:'') +  ((det.client_name)?' Client: ' + det.client_name:'')+' '+((det.attendance_type)?det.attendance_type:'')+ ((det.notes && !det.notes.includes('MOBILEAPP'))? ' Notes: ' + det.notes:'') + ', ');
      });  
      return type == 'pdf'?val:str_val; // Return array instead of string
    }
