    convertToKms(distance:any){
      return { 
        val:distance && isNumber(distance) ? Number(distance/1000).toFixed(3) + ' km':'',
        key: distance?' km':''
      };
    }
    
    getFormattedTimeDifference(seconds :any = null,type:any = 'Travel'){
      if(seconds  && seconds .toString().length) {
        var hours = Math.floor(seconds / 60 / 60);
        var minutes = Math.floor(seconds / 60 % 60);
        var remainingSeconds = seconds % 60;
        if(type === 'Stay')
        return ( hours? hours+ 'hours ':'')+ (minutes?minutes + 'min ':'')  + (remainingSeconds?remainingSeconds + 'sec':'');
        else 
        return ( hours? hours+ 'hours ':'')+ (minutes?minutes + 'min ':'') + (remainingSeconds?remainingSeconds + 'sec':'');
       
      }
      else return '';
    }
    changeDisplay(row:any,det:any){
      row.details?.forEach((d:any)=>{
        d.display = false;
        if(det.client_id){
          if(d.client_id && d.client_id === det.client_id  ){
            d.display = true;
          }
        }else{
          if(d.requestid && d.requestid === det.requestid  ){
            d.display = true;
          }
        }
      });
    }

    
Searchform_tracking(data:any) {
  this.List_tracking = [];
  this.isLoading = true;
    this.spinner.show();
    this.crm.getCrmSelectedEmployeeRoutesOnDates(data).subscribe((res: any) => {
      this.spinner.hide();
      let sno = 1;
      this.List_tracking=res.data;
      if(this.List_tracking && this.List_tracking.length){
        this.showExportButtons = true;
        this.List_tracking.forEach((row:any)=>{
          row.sno = sno++;
        });
        this.isLoading = false;
        this.spinner.show();
        this.dataSource_tracking = new MatTableDataSource(this.List_tracking);
        this.dataSource_tracking.paginator = this.paginator_tracking;
        this.dataSource_tracking.sort = this.sort_tracking;
        this.spinner.hide();
      }
      this.pageLoading=false;
    }, error => {
      this.isLoading = false;
      error.error.text
    });
}
getEmployeeName(){
  let emp_name = '';    
  let userId = this.searchForm.controls.Users.value;
  if (userId == '0' || userId == '') {
    userId=null;
  }
    if(this.filteredEmployees && this.filteredEmployees.length){
      if(userId){
        this.filteredEmployees.forEach((e:any)=>{
          if(e.empid == userId && emp_name == '')
            emp_name = e.empname;
        })
      }
      else emp_name = 'All';      
    }
  return emp_name; 
}   

getSelectedManagerNames(){
  let selectedManagerNames:string ='';
  if(this.selectedManagers && this.selectedManagers.length){
    this.managersDetails?.forEach((md:any)=>{
      if(this.selectedManagers.includes(md.manager_emp_id)){
        selectedManagerNames = selectedManagerNames + (selectedManagerNames == ''?'': ', ')+ md.manager_name;
      }
    });
  }
  return selectedManagerNames;
}

getSelectedLocationNames(){
  let selectedLocationNames:string ='';
  if(this.selectedLocations && this.selectedLocations.length){
    this.worklocationDetails?.forEach((wl:any)=>{
      if(this.selectedLocations.includes(wl.id)){
        selectedLocationNames = selectedLocationNames + (selectedLocationNames == ''?'': ', ')+ wl.location;
      }
    });
  }
  return selectedLocationNames;
}

