import { Component, OnInit, Inject } from '@angular/core';
import { Router } from '@angular/router';
import { Location } from '@angular/common';
import { MatDialog, MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';
// No runtime rxjs imports needed for dummy data
import { LearnService } from '../../learn.service';

@Component({
  selector: 'app-quiz-details',
  templateUrl: './quiz-details.component.html',
  styleUrls: ['./quiz-details.component.scss']
})
export class QuizDetailsComponent implements OnInit {

  currentQuestion: number = 0;
  questions: any[] = [];
  loading: boolean = false;
  reviewMode: boolean = true; // Always in review mode - show correct answers
  
  // Course metadata
  section_id: number = 0;
  course_id: number = 0;
  course_name: string = '';
  employee_name: string = '';
  points: number = 0;
  difficulty: string = '';
  attemptCount: number = 0;
  passStatus: string = '';
  score: number = 0;
  totalPoints: number = 0;
  
  // Course details
  modules: any[] = [];
  sections: any[] = [];

  userSession: any;
  reviewComment: string = '';
  reviewSaved: boolean = false;
  tabIndex: number = -1; // -1 = mycourses tab, 1 = reviewer tab
  review_id: number | null = null; // For reviewer tab

  constructor(private router: Router, private location: Location, private learnService: LearnService, private dialog: MatDialog) {
    // Get data from navigation state
    const navigation = this.router.getCurrentNavigation();
    const state = navigation?.extras.state;
    
    if (state) {
      this.section_id = state.section_id;
      this.course_id = state.course_id;
      this.course_name = state.course_name;
      this.employee_name = state.employee_name;
      this.tabIndex = state.tab_index ?? -1; // Default to -1 if not provided
      this.review_id = state.review_id ?? null; // Extract review_id from reviewer tab
    }
    
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '{}');
  }

  ngOnInit(): void {
    // If a course_id was passed via navigation state, fetch real questions from API
    if (this.course_id && this.course_id > 0) {
      this.loadQuizDetails();
      return;
    }
  }

  loadQuizDetails(): void {
    if (!this.course_id || this.course_id === 0) {
      console.error('course_id is required to fetch course questions');
      this.loading = false;
      return;
    }

    this.loading = true;

    this.learnService.getcoursesQuestions(this.course_id).subscribe({
      next: (res: any) => {
        // Normalize response: API may return { questions: [...] } or an array directly
        const rawQuestions = Array.isArray(res) ? res : res.questions || res.data || [];

        this.questions = rawQuestions.map((q: any) => ({
          question_text: q.question_text || q.question || '',
          choices: q.options ? this.parseOptions(q.options) : (q.choices || []),
          correct_answer: q.correct_answer || q.answer || null,
          imageUrls: q.image ? (Array.isArray(q.image) ? q.image : [q.image]) : [],
          question_id: q.question_id || q.id || null,
          selected: q.selected_answer||null
        }));

        this.loading = false;
      },
      error: (err: any) => {
        console.error('Failed to load course questions:', err);
        this.loading = false;
      }
    });
  }

  parseOptions(optionsString: string): any[] {
    try {
      const parsed = JSON.parse(optionsString);
      return Object.entries(parsed).map(([letter, text]) => ({ letter, text }));
    } catch {
      return [];
    }
  }

  navigateToQuestion(i: number): void {
    this.currentQuestion = i;
  }

  previousQuestion(): void {
    if (this.currentQuestion > 0) {
      this.currentQuestion--;
    }
  }

  nextQuestion(): void {
    if (this.currentQuestion < this.questions.length - 1) {
      this.currentQuestion++;
    }
  }

  goBack(): void {
    this.location.back();
  }

  approveReview(): void {
    if (this.reviewSaved) return;
    this.reviewSaved = true;
    const payload = {
      review_id: this.review_id,
      new_status: 'approved',
      remarks: this.reviewComment,
      reviewed_by: this.userSession?.id
    };
    this.learnService.storereviewDecision(payload).subscribe({
      next: (response: any) => {
        console.log('Review approved successfully', response);
        this.showSuccessDialog('Your review has been approved successfully');
      },
      error: (err: any) => {
        console.error('Error approving review', err);
        this.reviewSaved = false; // Reset on error
      }
    });
  }

  rejectReview(): void {
    if (this.reviewSaved) return;
    this.reviewSaved = true;
    const payload = {
      review_id: this.review_id,
      new_status: 'rejected',
      remarks: this.reviewComment,
      reviewed_by: this.userSession?.id
    };
    this.learnService.storereviewDecision(payload).subscribe({
      next: (response: any) => {
        console.log('Review rejected successfully', response);
        this.showSuccessDialog('Your review has been rejected successfully');
      },
      error: (err: any) => {
        console.error('Error rejecting review', err);
        this.reviewSaved = false; // Reset on error
      }
    });
  }

  private showSuccessDialog(message: string): void {
    this.dialog.open(ReviewSuccessDialog, {
      width: '400px',
      data: { message },
      disableClose: true
    }).afterClosed().subscribe(() => {
      // Navigate back to the previous page when OK is clicked
      this.location.back();
    });
  }

}

// Success dialog component
@Component({
  selector: 'app-review-success-dialog',
  template: `
    <div class="dialog-container">
      <div class="dialog-icon">
        <mat-icon class="success-icon">check_circle</mat-icon>
      </div>
      <p>{{ data.message }}</p>
      <div class="dialog-actions">
        <button mat-raised-button color="primary" (click)="dialogRef.close()">OK</button>
      </div>
    </div>
  `,
  styles: [`
    .dialog-container {
      text-align: center;
      padding: 20px;
    }
    .dialog-icon {
      margin-bottom: 15px;
    }
    .success-icon {
      font-size: 48px;
      width: 48px;
      height: 48px;
      color: #4caf50;
    }
    h2 {
      margin: 15px 0;
      color: #333;
    }
    p {
      margin: 10px 0 20px 0;
      color: #666;
      font-size: 14px;
    }
    .dialog-actions {
      margin-top: 20px;
    }
  `]
})
export class ReviewSuccessDialog {
  constructor(public dialogRef: MatDialogRef<ReviewSuccessDialog>, @Inject(MAT_DIALOG_DATA) public data: any) {}
}
