import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { MatTableDataSource } from '@angular/material/table';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { Router } from '@angular/router';
import moment from 'moment';
import { TdsService } from '../../tds.service'
import { TdsDialogsComponent } from '../../dialogs/tds-dialogs/tds-dialogs.component';
@Component({
  selector: 'app-configure-tax-regime',
  templateUrl: './configure-tax-regime.component.html',
  styleUrls: ['./configure-tax-regime.component.scss']
})
export class ConfigureTaxRegimeComponent implements OnInit {
  displayedColumns: string[] = ['id', 'section_name','sub_sections', 'sub_sections_one', 'max_exemption_amount', 'amount'];
  subDisplayedColumns: string[] = ['id', 'section_name','sub_sections', 'sub_sections_one','max_exemption_amount', 'amount'];
  groupTotal:any=null
  exemptionDisplayedColumns: string[] = ['s_no', "type", 'open_date', 'close_date', 'request_extension_closure_date']
  exemptionDataSource: MatTableDataSource<any> = <any>[]
  dataSource: MatTableDataSource<any> = <any>[]
  subDataSource: MatTableDataSource<any> = <any>[]
  userSession:any;
  activeChild:any;
  activeModule:any;
  validationMessage:boolean=false;
  regimes:any;
  groupLimit:any;
  subTotal:any=null;
  isDeclarationDateClosed:boolean=false;
  grandTotal:any=0;
  constructor(private dialog: MatDialog,private TdsService:TdsService,private router: Router ) { 
    const navigation = this.router.getCurrentNavigation();
    let nav = navigation?.extras.state?.['activeScreen']; // Access data
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.activeChild = JSON.parse(sessionStorage.getItem('activeChild')||'')
    this.activeModule = JSON.parse(sessionStorage.getItem('activeModule')||'');
  }
  financialYear:any;
  @ViewChild('targetSection') targetSection!: ElementRef;
  netAnnualSalary:any;
  isDisableFinalSubmit:boolean = false;
  async ngOnInit() {
    this.getIncomeTaxSectionGroups();
    this.financialYear = await this.getFinancialYears();
    this.getFinalSubmitStatus();
    this.getSectionOptions();
    this.getAllSections();
    this.validateEmployeeTaxExemptionStatus();
    this.getEmpBasicDeclarationDetails();
   this.regimes = await this.getRegimes();
   this.getEmployeeAnnualNetSalary()
  }
  confirm(regimeId:number){

    let dialogRef1 = this.dialog.open(TdsDialogsComponent, {
      position:{top:`50px`},
      disableClose: true,
      data: {message:'Are you sure you want to go with the opted regime? The regime can be changed till '+this.basicDeclarationDetail[0].declaration_close_date+' and cannot be changed after this date for this financial year.'}
    });
    dialogRef1.afterClosed().subscribe((result:any)=>{
      if(result){
        this.configureEmployeeTaxRegime(regimeId)
      }
    })
  }

    /** getFinancialYears Data*/
    getFinancialYears() {
      return new Promise((resolve) => {
        this.TdsService.getFinancialYears().subscribe((result: any) => {
          if (result.status && result.data.length) {
            resolve(result.data[0].financial_year)
          } else {
            resolve('')
          }
        });
      });
    }
    newArray :any= [];
    getAllSections(){
      this.TdsService.getTdsIncomeTaxSections(this.financialYear,this.userSession.id).subscribe((results)=>{
        if(results && results.status && results.data && results.data.length){
         
          results.data = results.data.filter((ele:any,index:number ) => {
            ele.amount = null
            ele.actions = false;
            ele.sub_sections=''
            ele.sub_sections_one=''
            if(!ele.max_exemption_amount){
              ele.max_exemption_amount = 'No Limit'

            }else{
              ele.max_exemption_amount = Number(ele.max_exemption_amount)
            }
            for(let i =0;i<this.groupSections.length;i++){
              this.groupSections[i].amount = null
              this.groupSections[i].sub_sections = '';   // Extract the first half
              this.groupSections[i].sub_sections_one= '';
              this.groupSections[i].group_limit = Number(this.groupSections[i].group_limit);

              this.groupSections[i].max_exemption_amount = Number(this.groupSections[i].max_exemption_amount);
              if(i=== 0){
                const middleIndex = Math.ceil(this.option80c.length / 2); // Find the middle index
                this.groupSections[i].sub_sections = this.option80c.slice(0, middleIndex);   // Extract the first half
                this.groupSections[i].sub_sections_one= this.option80c.slice(middleIndex); 
              }
              if(this.groupSections[i].section_name == ele.section_name){  
                return false;
              } 
            }
            return true; // Keep in the original array
          });
          this.subDataSource = new MatTableDataSource(this.groupSections);

          this.dataSource = new MatTableDataSource(results.data);
        }
      })
    }
    getSectionFlags(){
      this.TdsService.getSectionFlags().subscribe((_results)=>{
      })
    }
    option80c :any = []
    getSectionOptions(){
      this.TdsService.getSectionOptions(2).subscribe((results)=>{
        this.option80c = results.data;
      })
    }
    validateEmployeeTaxExemptionStatus(){
      this.validationMessage =false;
      this.TdsService.validateEmployeeTaxExemptionStatus(this.userSession.id,this.financialYear).subscribe((results)=>{
        if(results && results.status&& results.data){
          if(results.data[0] && results.data[0].tds_status.toString().includes(this.activeChild?.screenid)){
            this.validationMessage = true;
            this.validation(results.data[0].tds_message)
          }
        }
      })
    }

    message(message: any) {
     let dialogRef = this.dialog.open(ReusableDialogComponent, {
        position: { top: `70px` },
        disableClose: true,
        data: message,
      });
    }
    validation(message:any){
      let dialogRef1 = this.dialog.open(TdsDialogsComponent, {
        position:{top:`50px`},
        disableClose: true,
        data: {message:message,flag:true}
      });
      dialogRef1.afterClosed().subscribe((result:any)=>{
        if(result){
        }
      })
    }

    bothRegime:boolean=false
    employeeOldTaxRegime : any=[];
    employeeNewTaxRegime : any=[];

   async generateBothRegime(){
      let total = this.groupTotal+this.subTotal
      if(this.regimes && this.regimes[0] && this.regimes[1]){
       this.employeeNewTaxRegime = await this.getRegimeWisePayableTaxForEmployee(this.regimes[1]?.id,0)
       this.employeeOldTaxRegime = await this.getRegimeWisePayableTaxForEmployee(this.regimes[0]?.id,total||0)
       if(!this.employeeOldTaxRegime.length || !this.employeeNewTaxRegime.length){
        this.message('Please contact your Finance Manager and get confirmed if your gross salary information was added to the application.')
        return 
       }
       this.bothRegime = true;
       setTimeout(()=>{
        this.targetSection.nativeElement.scrollIntoView({ behavior: 'smooth', block: 'end' });
       },1000)
       }
    }

    getRegimes(){
     return new Promise((resolve) => {
        this.TdsService.getIncomeTaxRegimes().subscribe((results:any)=>{
        if(results && results.status && results.data){
          resolve(results.data)
        } else {
          resolve(null)
        }
      })
    });
    }

    getRegimeWisePayableTaxForEmployee(regimeId:number,amount:number=0){
      return new Promise((resolve)=>{
        let input = {
          employeeId :this.userSession.id,
          financialYear:this.financialYear,
          regimeId:regimeId,
          exemptionAmount :amount
        }
        this.TdsService.getRegimeWisePayableTaxForEmployee(input).subscribe((results:any)=>{
          if(results && results.status && results.data){
            resolve(results.data)
          }else if(results.code && results.code == 404){
            resolve([])
          }else{
            resolve([])
          }
        })
      })

    }

  change(event: any, ele: any) {
    this.calculateGrandTotal();

    if (this.grandTotal > this.netAnnualSalary) {
      setTimeout(() => {
      this.TdsService.showSnackBar('You cannot declare beyond the annual net salary.')
      ele.amount = null;
      this.calculateGrandTotal()
    }, 100);
    }

    if( typeof ele.max_exemption_amount === "string"){
 
      return
    
    }
      if (event > ele.max_exemption_amount) {
        setTimeout(() => {
        this.TdsService.showSnackBar('You cannot declare beyond the section maximum limit.')
        ele.amount = ele.max_exemption_amount
        this.calculateGrandTotal()
      }, 100);
      }
  }


  
  groupChange(event: any, ele: any) {

      this.calculateSum(); // total calculations
      //bellow condition is for exclude current field and add remaining fields amount
      const existingData = this.groupSections.filter((t:any)=>t.amount !=null && ele.section_name != t.section_name)
      .map((item:any) => item.amount).reduce((sum:any, amount:any) => sum + amount, 0); 

      if(ele.group_limit <= this.groupTotal && existingData){ // this condition handles group limit if exceeds group limit reset to remaining amount
        setTimeout(() => {
          this.TdsService.showSnackBar('You cannot declare beyond the group maximum limit of Rs.'+ele.group_limit+'.')
          ele.amount = Number((ele.group_limit-existingData).toFixed(2))
        },100)
        return
      }

      if (event > ele.max_exemption_amount) { // this condition handles individual limit
        setTimeout(() => {
        this.TdsService.showSnackBar('You cannot declare beyond the section maximum limit.')
        ele.amount = ele.max_exemption_amount
      }, 100);
      }
  }
  calculateSum(){
    const totalAmount = this.groupSections.reduce((sum:number, current:any) => {
      let a =  sum + (current.amount || 0);
      if(current.group_limit < a){ // this condition checks don't cross group limit if cross set to group_limit
        return current.group_limit
      }
      return a // Default to 0 if amount is missing
    }, 0);
    this.groupTotal=Number(totalAmount.toFixed(2));
    this.grandTotal = Number((this.subTotal+this.groupTotal).toFixed(2))
  }

  groupSections:any=[]
  getIncomeTaxSectionGroups(){
    this.TdsService.getIncomeTaxSectionGroups().subscribe((results:any)=>{
      if(results && results.status){
        this.groupSections = results.data;
        this.groupLimit ='Group Limit - '+this.formatCurrency(this.groupSections[0].group_limit);
      }
    })
  }

  calculateGrandTotal(){
  let total = this.dataSource.data.reduce((sum:any, ele:any) => sum + ele.amount, 0);
  this.subTotal = Number(total.toFixed(2))
  this.grandTotal = Number((this.subTotal+this.groupTotal).toFixed(2))
  }


  clear(){
    this.groupTotal=null;
    this.subTotal=null;
    this.grandTotal =null;
    this.subDataSource.data.forEach((ele:any)=>{
      ele.amount=null;
    })
    this.dataSource.data.forEach((ele:any)=>{
      ele.amount=null;
    })
    this.bothRegime = false;
    // this.targetSection.nativeElement.scrollIntoView({ behavior: 'smooth', block: 'start' });

  }

  configureEmployeeTaxRegime(regimeId:number){
    let input = {
      employeeId:this.userSession.id,
      financialYear:this.financialYear,
      regimeId:regimeId
    }
    this.TdsService.configureEmployeeTaxRegime(input).subscribe((results:any)=>{
      if(results && results.status){
        let dialogRef1 = this.dialog.open(TdsDialogsComponent, {
          position:{top:`50px`},
          disableClose: true,
          data: {regimeFlag:true,flag:true, message:regimeId == this.regimes[0].id?'Your regime is configured to Old Tax Regime successfully! You will be redirected to "Tax Exemption Declarations" screen.':'Your regime is configured to New Tax Regime successfully! No declarations are required from your side. You will be redirected to "TDS Details" page.'}
        });
        dialogRef1.afterClosed().subscribe((res:any)=>{
          if(res){
            if(results.data && results.data[0][0].nav){
              let successRoute=this.activeModule.module.menu_items.filter((ele:any)=>{return ele.screenid == results.data[0][0].nav})
              sessionStorage.setItem('activeChild', JSON.stringify(successRoute[0]));
              this.router.navigateByUrl('/', { skipLocationChange: true })
              .then(() => this.router.navigate([successRoute[0].routename]));
            }    
          }
        })
      }

    })
  }
    // Method to format the amount
    formatCurrency(value: number): string {
      return new Intl.NumberFormat('en-IN', {
        style: 'currency',
        currency: 'INR'
       }).format(value);
    }
  
    isNumber(value: any): boolean {
      return !isNaN(parseFloat(value)) && isFinite(value);
    }



    basicDeclarationDetail:any;
    getEmpBasicDeclarationDetails() {

      this.TdsService.getEmpBasicDeclarationDetails(this.userSession.id, this.financialYear).subscribe((_results) => {
        if (_results && _results.status) {
          this.basicDeclarationDetail = _results.data;
          this.validateDates(this.basicDeclarationDetail[0].declaration_open_date, this.basicDeclarationDetail[0].declaration_close_date,this.basicDeclarationDetail[0].upload_open_date,this.basicDeclarationDetail[0].upload_close_date)
          let tempArray = [{ s_no: 1, type: 'Tax Exemption Declaration Window', open_date: this.basicDeclarationDetail[0].declaration_open_date, close_date: this.basicDeclarationDetail[0].declaration_close_date, request_extension_closure_date: '' },
                { s_no: 2, type: 'Tax Exemption Proof Upload Window', open_date: this.basicDeclarationDetail[0].upload_open_date, close_date: this.basicDeclarationDetail[0].upload_close_date, request_extension_closure_date: "" }
                ]
        this.exemptionDataSource = new MatTableDataSource(tempArray);
        this.basicDeclarationDetail[0].declaration_close_date = moment(this.basicDeclarationDetail[0].declaration_close_date).format('DD-MM-YYYY')

        }
      })
    }

    validateDates(declarationOpenDate: any, declarationClosureDate: any, proofUploadOpenDate: any, proofUploadClosureDate: any) {
      // if (!isUploadFile) {
        if (!declarationOpenDate) { //dates not declared 
          this.message("The tax exemption declaration window is not yet declared. Please proceed with tax regime configuration once the window is declared.")
          // this.expandedIndex = null;
          this.validationMessage =true;

          return false
        } else if (declarationOpenDate && moment().startOf('day').toDate() < moment(declarationOpenDate).startOf('day').toDate()) { //dates declared but not opened
          this.message("The tax exemption declaration window is not yet opened. Please proceed with tax regime configuration once the window is declared.");
          this.validationMessage =true;
          return false
        }

        else if( moment().startOf('day').toDate() > moment(declarationClosureDate).startOf('day').toDate()){ //dates closed 
          this.message("The tax exemption declaration window is closed. Please contact your Finance Manager to proceed with tax regime configuration.");
          this.validationMessage =true;
          this.isDeclarationDateClosed = true;
          return
        }
      // }
      // else {
        // if (!proofUploadOpenDate) { //proof uploaded dates not declared 
        //   this.message("The tax exemption proof upload window is not yet declared. Please proceed with uploading the proofs once the window is declared.");
        //   return false;
        // }
        // else if (proofUploadOpenDate && new Date() < new Date(proofUploadOpenDate)) {//proof uploaded declared but not open
        //   this.message("The tax exemption proof upload window is not yet opened. Please proceed with uploading proofs once the window is opened.");
        //   return false;
        // }
        // else if( proofUploadOpenDate && new Date() > new Date(proofUploadClosureDate)){ //proof uploaded dates closed 
        //   this.message("The tax exemption proof upload window is closed. Please contact your Finance Manager to proceed with uploading proofs.");
        //   return;
        // }
      // }
      return true
  
  
    }

    // message(message: any, isClose = false) {
    //   let dialogRef = this.dialog.open(ReusableDialogComponent, {
    //     position: { top: `70px` },
    //     disableClose: true,
    //     data: message,
    //   });
     
    // }

    preventPlusMinus(event: KeyboardEvent): void {
      if (event.key === '+' || event.key === '-') {
        event.preventDefault();
      }
    }

    limitDecimal(event: Event): void {
      const input = event.target as HTMLInputElement;
      let value = input.value;
      // Remove any occurrences of 'e' or 'E' directly
      value = value.replace(/[eE]/g, '');

      // Allow only numbers with up to 10 digits before decimal and 2 after decimal
      const regex = /^\d{0,10}(\.\d{0,2})?$/;

      if (!regex.test(value)) {
        // Extract only valid numeric portion
        const match = value.match(/^\d{0,10}(\.\d{0,2})?/);
        input.value = match ? match[0] : '';
      } else {
        // If the input is valid, assign it back
        input.value = value;
      }
    }
    getEmployeeAnnualNetSalary(){
      this.TdsService.getEmployeeAnnualNetSalary(this.financialYear,this.userSession.id).subscribe((results:any)=>{
        if(results?.status && results?.data.length > 0 ){
          this.netAnnualSalary = results.data[0].annual_net_salary;
        }
      })
    }

    getFinalSubmitStatus(){
      this.TdsService.getFinalSubmitStatus(this.financialYear,this.userSession.id).subscribe((results) => {
        if (results && results.status && results.data) {
            this.isDisableFinalSubmit  = results.data[0].enable_status? false : true;
        }
      })
    }
}
