// ─────────────────────────────────────────────────────────────────────────────
// Interfaces
// ─────────────────────────────────────────────────────────────────────────────

interface Resource {
  resource_id?: number;
  resourceType: 'link' | 'document';
  link?: string;
  file?: File;
  linkName?: string;
  docUrl?: string;
  docName?: string;
  editingResource?: boolean;
  replaceMode?: boolean;
  tempNewDocUrl?: string;
  tempNewDocName?: string;
}

interface QuestionItem {
  question: string;
  A: string;
  B: string;
  C: string;
  D: string;
  answer: 'A' | 'B' | 'C' | 'D';
  content?: string;
  contentFile?: File | null;
}

interface Section {
  section_id?: number;
  title: string;
  showContentOptions: boolean;
  selectedContentType?: string;
  videoUrl?: string;
  documentUrl?: string;
  sanitizedDocumentUrl?: SafeResourceUrl;
  editingDescription?: boolean;
  description?: string;
  tempDescription?: string;
  textContent?: string;
  documentFile?: File;
  file?: File;
  questionsDraft?: QuestionItem[];
  showResourceForm?: boolean;
  selectedResourceTab?: number;
  resources: Resource[];
  tempLink: string;
  tempLinkName: string;
  tempDocumentUrl: string;
  tempDocumentName: string;
  isManualQuiz?: number;
}

interface Module {
  id: number | undefined;
  module_id?: number;
  description: any;
  title: string;
  sections: Section[];
  _savedModuleId?: number;
}

