  async submitCourse() {
    try {
      this.inFlight = true;

      // 🔥 START PROGRESS
      this.progressValue = 5;
      this.progressMessage = 'Updating course details...';
      this.cdr.markForCheck();

      // 1️⃣ COURSE
      const coursePayload = {
        course_id: this.editingCourse?.course_id || 0,
        course_name: this.courseForm.value.courseTitle,
        description: this.courseForm.value.courseDescription,
        instructor_id: this.userSession.id,
        category: this.courseForm.value.selectCategory,
        difficulty_level: this.courseForm.value.selectLevel,
        prerequisites: this.courseForm.value.prerequisites,
        tags: this.courseForm.value.tags,
        thumbnail: this.finalBase64,
        created_by: this.userSession.id,
      };

      const courseRes: any = await this.learnService.addCourse(coursePayload).toPromise();
      const courseId = courseRes.course_id;

      this.progressValue = 20;
      this.progressMessage = 'Updating modules...';
      this.cdr.markForCheck();

      // 2️⃣ MODULES
      for (const module of this.modules) {

        const modulePayload = {
          module_id: module.id || 0,
          course_id: courseId,
          module_name: module.title,
          description: module.description,
          created_by: this.userSession.id,
        };

        const moduleRes: any = await this.learnService.addModule(modulePayload).toPromise();
        const moduleId = moduleRes.module_id;

        this.progressValue += 10;

        // 3️⃣ SECTIONS
        for (const section of module.sections) {

          this.progressMessage = 'Updating sections...';
          this.cdr.markForCheck();

          const formData = new FormData();

          formData.append('section_id', section.section_id?.toString() || '0');
          formData.append('module_id', moduleId.toString());
          formData.append('section_name', section.title);
          formData.append('description', section.description || '');
          formData.append('created_by', this.userSession.id.toString());
          formData.append('is_manual', section.isManualQuiz?.toString() || '0');

          if (section.file) {
            formData.append('content', section.file);
          }

          const sectionRes: any = await this.learnService.addSection(formData).toPromise();
          const sectionId = sectionRes.section_id;

          // 4️⃣ QUESTIONS
          if (section.isManualQuiz === 1 && section.questionsDraft?.length) {
            this.progressMessage = 'Saving quiz questions...';
            this.cdr.markForCheck();

            await this.learnService.addQuestions({
              section_id: sectionId,
              created_by: this.userSession.id,
              questions: section.questionsDraft
            }).toPromise();
          }

          // 5️⃣ RESOURCES
          if (section.resources?.length) {
            this.progressMessage = 'Uploading resources...';
            this.cdr.markForCheck();

            const resourcesPayload = section.resources.map(r => {
              let resourceContent = this.cleanString(r.link || r.docUrl || '');
              resourceContent = resourceContent.replace(/"/g, '');

              return {
                section_id: sectionId,
                resource_name: r.resourceType === 'link'
                  ? this.cleanString(r.linkName)
                  : this.cleanString(r.docName || this.extractFileName(r.docUrl)),
                resource_content: resourceContent,
                created_by: this.userSession.id,
              };
            });

            await this.learnService.addResources(resourcesPayload).toPromise();
          }

          this.progressValue += 5;
          this.cdr.markForCheck();
        }
      }

      this.progressMessage = 'Removing deleted items...';
      // ── 6️⃣ SUBMIT TO TRACKER ─────────────────────────────────
      this.progressMessage = 'Submitting course for review...';
      this.progressValue = 95;
      this.cdr.markForCheck();

      const reviewerId = this.approvalForm.value.selectedReviewer;
      const approverId = this.approvalForm.value.selectedApprover;

      if (!reviewerId || !approverId) {
        alert('Please select a reviewer and approver before submitting.');
        this.inFlight = false;
        return;
      }

      const submitPayload = {
        course_id: courseId,
        instructor_id: this.userSession.id,
        reviewer_id: reviewerId,
        approver_id: approverId
      };
      console.log('Submitting course with payload:', submitPayload);

      await this.learnService.instructorSubmitCourse(submitPayload).toPromise();
      // ─────────────────────────────────────────────────────────
      await this.handleDeletes();
      this.progressValue = 100;
      this.progressMessage =  'Course updated successfully!';
      this.cdr.markForCheck();

       setTimeout(() => {
  this.inFlight = false;
  this.progressValue = 0;
  this.progressMessage = '';
  this.isEditMode = false;
  this.editingCourse = null;
  this.selectedTab = 0;
  this.loadCourses();
  this.cdr.markForCheck();
}, 2000);

    } catch (err) {
      console.error(err);
      this.inFlight = false;
      this.progressValue = 0;
      this.progressMessage = '';
      this.cdr.markForCheck();
      alert('Error updating course ❌');
      this.backToChecklist();
      this.inFlight = false;
    }
  }

 
  async handleDeletes() {
    try {
      if (this.deletedModules.length) {
        await this.learnService.softDeleteModules({
          module_ids: this.deletedModules
        }).toPromise();
      }

      if (this.deletedSections.length) {
        await this.learnService.softDeleteSections({
          section_ids: this.deletedSections
        }).toPromise();
      }

      if (this.deletedResources.length) {
        await this.learnService.softDeleteResources({
          resource_ids: this.deletedResources
        }).toPromise();
      }

    } catch (err) {
      console.error('Delete error:', err);
    }
  }

  extractFileName(url?: string): string {
    if (!url) return 'File';

    try {
      url = decodeURIComponent(url);
    } catch { }

    const parts = url.split('/');
    return parts[parts.length - 1].replace(/^"+|"+$/g, '');
  }

