  private _getVideoDuration(file: File): Promise<number> {
    return new Promise(resolve => {
      const url = URL.createObjectURL(file);
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.src = url;
      video.onloadedmetadata = () => { URL.revokeObjectURL(url); resolve(video.duration || 0); };
      video.onerror = () => { URL.revokeObjectURL(url); resolve(0); };
    });
  }

  private _htmlToFormattedText(html: string): string {
    const tempDiv = document.createElement('div');
    tempDiv.innerHTML = html;
    let result = '';
    let inCodeBlock = false;

    const processNode = (node: Node): void => {
      if (node.nodeType === Node.TEXT_NODE) {
        const text = node.textContent || '';
        if (inCodeBlock) { result += text; }
        else { const t = text.trim(); if (t) result += t; }
      } else if (node.nodeType === Node.ELEMENT_NODE) {
        const el = node as Element;
        const tagName = el.tagName.toLowerCase();
        switch (tagName) {
          case 'h1': result += '\n# '; break;
          case 'h2': result += '\n## '; break;
          case 'h3': result += '\n### '; break;
          case 'p': if (!inCodeBlock) result += '\n'; break;
          case 'br': result += '\n'; return;
          case 'pre':
            result += '\n[CODE]\n';
            inCodeBlock = true;
            result += el.textContent || '';
            result += '\n[/CODE]\n';
            inCodeBlock = false;
            return;
          case 'code':
            if (el.parentElement?.tagName.toLowerCase() !== 'pre') {
              result += '\n[CODE]\n' + (el.textContent || '') + '\n[/CODE]\n';
              return;
            }
            break;
          case 'li':
            const parentList = el.closest('ol, ul');
            if (parentList?.tagName.toLowerCase() === 'ol') {
              result += `\n${Array.from(parentList.children).indexOf(el) + 1}. `;
            } else { result += '\n• '; }
            break;
          case 'ul': case 'ol': result += '\n'; break;
        }
        if (tagName !== 'pre' && !(tagName === 'code' && el.parentElement?.tagName.toLowerCase() !== 'pre')) {
          node.childNodes.forEach(c => processNode(c));
        }
        if (['h1', 'h2', 'h3', 'p', 'ul', 'ol', 'li'].includes(tagName) && !inCodeBlock) result += '\n';
      }
    };

    tempDiv.childNodes.forEach(n => processNode(n));
    return result.replace(/\n{3,}/g, '\n\n').trim();
  }

  private _assignCourses(tab: string, courses: any[]): void {
    if (tab === 'Needs Update') {
      this.reviewerCoursesEdit = courses.filter(c => c.status_code === 2);
      this.approverCoursesEdit = courses.filter(c => c.status_code === 5);
      this.updateCourseEdit = courses.filter(c => c.status_code === 7);
    } else if (tab === 'Courses Overview') {
      this.overviewCourses = courses;
      this.overviewFiltered = [...courses];
      this.overviewActiveFilter = null;
      const countMap = new Map<number, number>();
      courses.forEach(c => countMap.set(c.status_code, (countMap.get(c.status_code) || 0) + 1));
      this.overviewStats = Array.from(countMap.entries()).map(([code, count]) => ({
        code, count,
        label: STATUS_MAP[code]?.label || 'Unknown',
        color: STATUS_MAP[code]?.color || '#94A3B8',
      }));
    } else if (tab === 'Under Review') {
      this.reviewerCourses = courses;
    } else if (tab === 'Pending Approval') {
      this.approverCourses = courses;
    }
  }

