  /**
   * Add a new empty suggestion to the array
   */
  addSuggestion(): void {
    this.improvementSuggestions.push('');
    this.cdr.markForCheck();
  }

  /**
   * Remove a suggestion at the specified index
   */
  removeSuggestion(index: number): void {
    if (this.improvementSuggestions.length > 1) {
      this.improvementSuggestions.splice(index, 1);
      this.cdr.markForCheck();
    }
  }

  /**
   * Check if there are any valid (non-empty) suggestions
   */
  hasValidSuggestions(): boolean {
    return this.improvementSuggestions.some(suggestion => suggestion.trim().length > 0);
  }

  /**
   * Get only the valid (non-empty) suggestions
   */
  getValidSuggestions(): string[] {
    return this.improvementSuggestions.filter(suggestion => suggestion.trim().length > 0);
  }

  /**
   * Initialize suggestions when viewing a course in restricted mode
   */
  initializeSuggestions(): void {
    this.improvementSuggestions = [''];
    this.cdr.markForCheck();
  }

  /**
   * Open the reject confirmation dialog
   */
  openRejectConfirmation(course: any): void {
    this.selectedCourseForAction = course;
    console.log('Selected course for rejection:', this.selectedCourseForAction);
    if (!this.hasValidSuggestions()) {
      console.warn('Cannot reject without suggestions');
      return;
    }

    this.dialog.open(this.rejectConfirmDialog, {
      width: '600px',
      disableClose: false,
      autoFocus: true
    });
  }

  /**
   * Open the approve confirmation dialog
   */
  openApproveConfirmation(): void {
    this.dialog.open(this.approveConfirmDialog, {
      width: '500px',
      disableClose: false,
      autoFocus: true
    });
  }

  /**
   * Handle rejection confirmation
   */
  onConfirmReject(): void {
    if (!this.isRestrictedTab()) return;
    console.log('Course in confirm:', this.selectedCourseForAction); // DEBUG

    if (!this.selectedCourseForAction) {
      console.error('No course selected!');
      return;
    }

    const validSuggestions = this.getValidSuggestions();

    const rejectionData = {
      course_id: this.selectedCourseForAction.course_id,  // ✅ FIXED
      suggestions: validSuggestions,
      status: 'rejected',
      empId: this.userSession?.id,
      currentTab: this.currentTabLabel
    };

    console.log('Reject payload:', rejectionData);

    this.isLoading = true;
    this.isRejecting = true;
    this.cdr.markForCheck();

    this.learnService.reviewerRejectCourse(rejectionData)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: () => {
          this.isLoading = false;
          this.isRejecting = false;
          this.dialog.closeAll();
          this.improvementSuggestions = [''];
          this.selectedCourseForAction = null;
          this.courseCache.delete(this.currentTabLabel);
          this.loadCourses();
          this.displayCourseList();   // ← exits stepper, returns to Under Review tab
          this.cdr.markForCheck();
        },
        error: (error) => {
          this.isLoading = false;
          this.isRejecting = false;
          console.error('Error rejecting course:', error);
          this.cdr.markForCheck();
        }
      });
  }

  /**
   * Handle approval confirmation
   */
  onConfirmApprove(): void {
    if (!this.editingCourse) {
      console.error('No course selected for approval!');
      return;
    }

    // Double-check validation: ensure no suggestions exist
    if (this.hasValidSuggestions()) {
      alert('Cannot approve course with pending suggestions.');
      this.dialog.closeAll();
      return;
    }

    const approvalData = {
      course_id: this.editingCourse.course_id,  // ✅ FIXED
      status: 'approved',
      empId: this.userSession?.id,
      currentTab: this.currentTabLabel
    };

    console.log('Approve payload:', approvalData);

    this.isLoading = true;
    this.isApproving = true;
    this.cdr.markForCheck();

    this.learnService.reviewerApproveCourse(approvalData)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (response) => {
          console.log('Course approved successfully:', response);
          this.isLoading = false;
          this.isApproving = false;
          this.dialog.closeAll();
          this.improvementSuggestions = [''];
          this.selectedCourseForAction = null;
          this.courseCache.delete(this.currentTabLabel);
          this.loadCourses();
          this.displayCourseList();
          this.cdr.markForCheck();
        },
        error: (error) => {
          this.isLoading = false;
          this.isApproving = false;
          console.error('Error approving course:', error);
          alert('Failed to approve course. Please try again.');
          this.cdr.markForCheck();
        }
      });
  }

  clearApprovalSelection(): void {
  this.approvalForm.reset();

  // Optional: reset search filters also
  this.reviewerSearchText = '';
  this.approverSearchText = '';

  this.filteredReviewersForSearch = [...this.filteredReviewers];
  this.filteredApproversForSearch = [...this.filteredApprovers];
}
