import { Component, OnInit } from '@angular/core';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { Router } from '@angular/router';
import { MatDialog } from '@angular/material/dialog';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { NgxSpinnerService } from 'ngx-spinner';
import { LeavesService } from '../../../leaves/leaves.service'
import { MainComponent } from '../../../../pages/main/main.component'
import { EmsService } from 'src/app/modules/ems/ems.service';
import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';
import { TranslateService } from '@ngx-translate/core';
// src\app\modules\leaves\leaves.service.ts

@Component({
  selector: 'app-companylogo',
  templateUrl: './companylogo.component.html',
  styleUrls: ['./companylogo.component.scss']
})
export class CompanylogoComponent implements OnInit {
  // file !:File=null;
  file:any;
  imageurls =[{
    base64String: "data:image/png;base64,"
  }];
  base64String: any;
  name: any;
  imagePath: any;
  formData: FormData = new FormData();
  userSession:any;
  isFileImage:boolean=false;
  msgEM124:any;
  msgEM71:any;
  msgEM72:any;
  msgEM73:any;
  msgEM74:any;
  msgEM75:any;
  activeModule:any;
  logoId:any=null;
  imageInfo:any=null;
  messageList:any=[];
  constructor(private MainComponent:MainComponent,private LMS:LeavesService,
    private LM:CompanySettingService,private dialog: MatDialog,private router: Router,
    private spinner:NgxSpinnerService,private  emsService:EmsService,private dialogService:ReusableDialogService, private translate: TranslateService) { }
  languages = [
    { code: 'english', label: 'ENGLISH', name: 'English' },
    { code: 'arabic', label: 'ARABIC', name: 'Arabic' }
  ];
  ngOnInit() {
     const savedLang = localStorage.getItem('lang');
   this.translate.use(savedLang || 'english');
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.activeModule = JSON.parse(sessionStorage.getItem('activeModule') || '');
    this.getUploadImage();
    this.getMessages();

  }

  // removeImage(i) {
  //   this.imageurls.splice(i, 1);
  //   this.fileImageToggler();
  // }
  isRemoveImage:boolean=true;
  // msgEM124:any='';
  // msgEM71:any='';
  // msgEM72:any='';
  // msgEM73:any='';
  removeImage() {

    // let info = {
    //   'employeeId':0,
    //   'filecategory': 'LOGO',
    //   'moduleId':2,
    //   'requestId':null,
    // }
    // this.LMS.getFilesMaster(info).subscribe((result) => {
      this.LMS.deleteFilesMaster(this.logoId).subscribe(data=>{
        if(data && data.status){
          // let info =JSON.stringify(result.data[0])
          this.LM.removeImage(this.imageInfo).subscribe((data) => {})
          this.dialogService.openDialog(this.msgEM75);
          let dialogRef = this.dialog.open(ReusableDialogComponent, {
            position: {top: `70px`},
            disableClose: true,
            data: this.msgEM75
          });
          this.getUploadImage()
          this.MainComponent.ngOnInit()
        }else{
          this.dialogService.openDialog(this.msgEM73);
        }
      })
  }
  cancelImage(){
    this.isRemoveImage=true;
    this.getUploadImage();
    this.fileImageToggler();
  }
  onSelectFile(event:any) {
    this.isRemoveImage=false;
    this.imageurls = [];
    this.file=null;
    this.file = event.target.files[0];
    this.fileImageToggler();
    let uploadeddata = this.file.type.split('/')
    if (this.file && uploadeddata[0] == "image") {
      if (this.file.size <= 1024000) {
        if (event.target.files && event.target.files[0]) {
          var filesAmount = event.target.files.length;
          for (let i = 0; i < filesAmount; i++) {
            var reader = new FileReader();
            reader.onload = (event: any) => {
              this.imageurls.push({ base64String: event.target.result, });
            }
            reader.readAsDataURL(event.target.files[i]);
          }
        }
      }else {
        this.dialogService.openDialog(this.msgEM124);
        this.isFileImage = false;
        this.getUploadImage();
      }
    }else {
      this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Admin/CompanyLogo"]));
      this.dialogService.openDialog('Please select valid image');
    }
  }

  saveImage()
  {
    let uploadeddata =this.file.type.split('/')
    if(this.file && uploadeddata[0] == "image"){
      this.spinner.show();
        this.LMS.getFilepathsMaster(2).subscribe((result) => {
          if(result && result.status){
            let obj = {
              'id':this.logoId?this.logoId:null,
              'employeeId':0,
              'filecategory': 'LOGO',
              'moduleId':2,
              'documentnumber':'',
              'fileName':this.file.name,
              'modulecode':result.data[0].module_code,
              'requestId':null,
              'status':'Submitted'
            }
            this.LMS.setFilesMaster(obj).subscribe((data) => {
              if(data && data.status) {
                this.LM.removeImage(this.imageInfo).subscribe((data) => {})
                    let info =JSON.stringify(data.data[0])
                this.formData.append("info",info)
                this.formData.append('file', this.file);
                this.LMS.setProfileImage(this.formData).subscribe((result) => {
                  this.formData.delete('file');
                        this.formData.delete('info');
                        this.spinner.hide();
                        if(data && data.status){
                          if(this.logoId){
                            // this.LM.removeImage(this.imageInfo).subscribe((data) => {})
                          }
                          this.dialogService.openDialog(this.msgEM74);
                          this.MainComponent.ngOnInit()
                        }else{
                          this.dialogService.openDialog(this.msgEM71);
                         }
                  this.file = null;
                 // this.getUploadImage();
                  this.fileImageToggler();
                  this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
    this.router.navigate(["/Admin/CompanyLogo"]));
                        this.isRemoveImage=true;
                });
              }else{
                this.spinner.hide();
                this.dialogService.openDialog(this.msgEM71);
              }
           })
        }else{
          this.spinner.hide();
          this.dialogService.openDialog(this.msgEM71);
        }})
    } else {
      this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
            this.router.navigate(["/Admin/CompanyLogo"]));
      this.dialogService.openDialog('Please select valid image');
    }

  }
  fileImageToggler()
  {
    this.isFileImage = !this.isFileImage;
  }
  getUploadImage(){
    let info = {
      'employeeId': 0,
      "candidateId": null,
      "moduleId": 2,
      "filecategory": 'LOGO',
      "requestId": null,
      'status': 'Submitted'


    }
    this.LMS.getFilesMaster(info).subscribe((result) => {
      if(result && result.status && result.data[0]){
        this.logoId=result.data[0].id;
       this.imageInfo =JSON.stringify(result.data[0]);
       result.data[0].employeeId=0;
       let info = result.data[0]
       this.LMS.getProfileImage(info).subscribe((imageData) => {
        if(imageData.success){
          let TYPED_ARRAY = new Uint8Array(imageData.image.data);
          const STRING_CHAR = TYPED_ARRAY.reduce((data, byte)=> {
            return data + String.fromCharCode(byte);
          }, '');

          let base64String= btoa(STRING_CHAR)
          this.imageurls[0].base64String='data:image/png;base64,'+base64String;


        }
      else{
        this.isRemoveImage=false;
        this.imageurls =[{
          base64String: "data:image/png;base64,"
        }];

      }
    })
  }else{
    this.isRemoveImage=false;
    this.imageurls =[{
      base64String: "data:image/png;base64,"
    }];

  }

})
  }

  getMessages() {
    let data =
    {
      "code": null,
      "pagenumber": 1,
      "pagesize": 1000
    }
    this.emsService.getMessagesListApi(data).subscribe((result: any) => {
      this.messageList = result.data;
      this.messageList.forEach((message:any)=>{
        if(message.code == 'EM124')
          {
            this.msgEM124 = message.message
          }
          else if(message.code == 'EM71')
          {
            this.msgEM71 = message.message
          }
          else if(message.code == 'EM72')
          {
            this.msgEM72 = message.message
          }
          else if(message.code == 'EM73')
          {
            this.msgEM73 = message.message
          }
          else if(message.code == 'EM74')
          {
            this.msgEM74 = message.message
          }
          else if(message.code == 'EM75')
          {
            this.msgEM75 = message.message
          }
  
      })
    })
  }
}
