  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatPaginator) paginator1!: MatPaginator;
  @ViewChild(MatPaginator) paginator2!: MatPaginator;
  selection = new SelectionModel<any>(true, []);
  pageLoading = true;
  pageLoading1 = true;
  pageLoading2 = true;
  isRequestView = false;
  isEditView = false;
  uniqueId: any = '';
  pipe = new DatePipe('en-US');
  messagesDataList: any = [];
  requiredField: any;
  requiredOption: any;
  dataSave: any;
  dataNotSave: any;
  deptdata: any = null;
  desdata: any = null;
  allmails: any = [];
  alldata: any = [];
  allempid: any = [];
  allesid: any = [];
  scheduleid: any;
  availableDesignations: any = [];
  availableDepartments: any = [];
  availableprogramtypes: any = [];
  conductlist: any = [];
  min: any;
  mintime: any;
  startTime: any;
  endTime: any;
  mdate: any = new Date();
  isAdd: boolean = false;
  isAddChecklist: boolean = false;
  isUpdateChecklist: boolean = false;
  isedit: boolean = false;
  isCancel: boolean = false;
  isView: boolean = false;
  isdata: boolean = true;
  userSession: any;
  companyList: any = ['Attended', 'Not Attended'];
  rolesList: any = ['Manager', 'Admin', 'HR', 'Staff'];
  minDate = new Date('2000/01/01'); maxDate = new Date("2200/01/01");
