import { Pipe, PipeTransform, ChangeDetectorRef, OnDestroy } from '@angular/core';
import { TranslateByTypeService } from '../services/translate-by-type.service';
import { Subscription } from 'rxjs';

@Pipe({
  name: 'translateByType',
  pure: false // impure so Angular re-renders when value changes
})
export class TranslateByTypePipe implements PipeTransform, OnDestroy {
  private translatedValue: string = '';
  private currentLang: string = 'english';
  private langSub?: Subscription;

  constructor(
    private translate: TranslateByTypeService,
    private cdr: ChangeDetectorRef
  ) {
    // 🔁 Auto update when language changes
    this.langSub = this.translate.language$.subscribe((lang:any) => {
      this.currentLang = lang;
      this.translatedValue = ''; // reset
      this.cdr.markForCheck();
    });
  }

  transform(value: string, type: string): string {
    if (!value || !type) return '';

    const lang = this.currentLang;

    // ✅ English → return directly
    if (lang === 'english') return value;

    // ✅ Check cache
    const translated = this.translate.translate(type, lang, value);
    if (translated !== value) {
      this.translatedValue = translated;
      return this.translatedValue;
    }

    // ⏳ Load async if not cached yet
    this.translate.loadData(type, lang).subscribe(() => {
      this.translatedValue = this.translate.translate(type, lang, value);
      this.cdr.markForCheck();
    });

    return this.translatedValue || value;
  }

  ngOnDestroy() {
    this.langSub?.unsubscribe();
  }
}