import { Component, OnInit, TemplateRef, ViewChild, ViewContainerRef } from '@angular/core';
import { MatPaginator } from '@angular/material/paginator';
import { MatTableDataSource } from '@angular/material/table';
import { TdsService } from '../../tds.service';
import { MatDialog } from '@angular/material/dialog';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DialogComponent } from '../../dialog/dialog.component';

export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};

@Component({
  selector: 'app-previous-company-payments-approvals',
  templateUrl: './previous-company-payments-approvals.component.html',
  styleUrls: ['./previous-company-payments-approvals.component.scss'],
  providers: [
      { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
  
      { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
    ],
})
export class PreviousCompanyPaymentsApprovalsComponent implements OnInit {

userSession: any;
financialYear: any;
displayedColumns1: string[] = ['s_no','empid', 'employee_name',  "company_name", 'city','TAN','status', 'actions']
displayedColumns: string[] = ['s_no','empid', 'employee_name',  "company_name", 'city','TAN','from_date','to_date', 'actions','action']

dataSource: MatTableDataSource<any> = <any>[];
dataSourceHistory: MatTableDataSource<any> = <any>[];

emptyData = new MatTableDataSource([{ empty: "row" }]);
pageLoading: boolean = true;
pageLoadingHistory: boolean = true;
searchControlForControl = new FormControl('');
filteredCountryDetails: any = [];

searchControlForSate = new FormControl('');
filteredStateDetails: any = [];

searchControlForCity = new FormControl('');
filteredCityDetails: any = [];
countryDetails:any=[];
finYearEndDate:any=[];
finYearStartDate:any=[];
isReject : boolean = false;
editRowDetails:any=null;


@ViewChild('firstPaginator') paginator!: MatPaginator;
@ViewChild('firstPaginatorTwo') paginatorHistory!: MatPaginator;

@ViewChild('popupTemplate', { static: true }) popupTemplate!: TemplateRef<any>;
previousCompanyPaymentsApprovals: any = []
previousCompanyPaymentsHistory:any = [];
  companyForm = new FormGroup({
    id: new FormControl(null),
    financialYear:new FormControl(null),
    employeeId:new FormControl(null),
    companyNameValue: new FormControl(null, Validators.required),
    address1: new FormControl(null, Validators.required),
    address2: new FormControl(null, Validators.required),
    city: new FormControl(null, Validators.required),
    state: new FormControl(null, Validators.required),
    country: new FormControl(null, Validators.required),
    companyTan: new FormControl(null, Validators.required),
    fromDate: new FormControl(null, Validators.required),
    toDate: new FormControl(null, Validators.required),
    grossPaidAmount: new FormControl(null, Validators.required),
    basicSalary: new FormControl(null, Validators.required),
    hra: new FormControl(null, Validators.required),
    deductedTaxAmount: new FormControl(null, Validators.required),
    rentPaid: new FormControl(null, Validators.required),
    documentPath:new FormControl(null),
    fileName:new FormControl(null),
    submissionStatus:new FormControl(''),
    createdBy:new FormControl(null),
    updatedBy:new FormControl(null),
    approvedBy:new FormControl(null),
  });
  companyDBName:any=null;
  stateDetails:any=[];
  cityDetails:any=[];
  minFromDate:any;
  maxFromDate = new Date();
  minToDate:any;
  maxToDate = new Date();
  titleName: string = '';
  rejectReason: any;

      // related to file upload
  selectedFile: any = null;
  filesize: boolean = true;
  fileNameError: boolean = true
  fileType:boolean =true;
  fileName: any = null
      
      
    
  constructor(
    private tdsService: TdsService, 
    private dialog: MatDialog, 
    private vcr: ViewContainerRef,
    private router:Router,
    private companyService: CompanySettingService,
  ) { 
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.companyDBName = sessionStorage.getItem('companyName')
    ? sessionStorage.getItem('companyName')
    : null;
    this.fnGetCurrentFinYearDates(); 
    // if (this.userSession.dateofjoin != null) {
    //   const dateofjoin = new Date(this.userSession.dateofjoin);  
    //   this.maxFromDate = dateofjoin;
    //   this.maxToDate = dateofjoin;
    // }

  }


  async ngOnInit(): Promise<void> {
    this.financialYear = await this.getFinancialYears();
    this.getEmployeePreviousCompanyPaymentsHistory();
    this.getPrevCompanyPayRequestsForApproval();
    this.getCountry();
    this.companyForm.get('country')?.valueChanges.subscribe((selectedValue) => {
      this.stateDetails = [];
      this.companyService.getStatesc(selectedValue).subscribe((data) => {
        this.stateDetails = data.data;
        this.filteredStateDetails = this.stateDetails;
      });
    });

    this.getCities()
    this.companyForm.get('state')?.valueChanges.subscribe((selectedValue) => {
      this.cityDetails = [];
      this.companyForm.controls.city.setValue(null);
      this.companyService.getCities(selectedValue).subscribe((data) => {
        this.cityDetails = data.data;
        this.filteredCityDetails = this.cityDetails;
      });
    });

    this.searchControlForCity.valueChanges.subscribe(searchText => {
      this.filterCityDetails(searchText);
    });

    this.searchControlForSate.valueChanges.subscribe(searchText => {
      this.filterStateDetails(searchText);
    });

    this.searchControlForControl.valueChanges.subscribe(searchText => {
      this.filterCountryDetails(searchText)
    });
  }

  getCities(){
    this.companyForm.get('state')?.valueChanges.subscribe((selectedValue) => {
      this.cityDetails = [];
      this.companyForm.controls.city.setValue(null);
      this.companyService.getCities(selectedValue).subscribe((data) => {
        this.cityDetails = data.data;
        this.filteredCityDetails = this.cityDetails;
      });
    });
  }

  getFinancialYears() {
    return new Promise((resolve) => {
      this.tdsService.getFinancialYears().subscribe((result: any) => {
        if (result.status && result.data.length) {
          resolve(result.data[0].financial_year)
        } else {
          resolve('')
        }
      });
    });
  }

  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.dataSource.data.length < 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  getPageSizesHistory(): number[] {
    var customPageSizeArray = [];
    if (this.dataSourceHistory.data.length < 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSourceHistory.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSourceHistory.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSourceHistory.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSourceHistory.data.length);
    return customPageSizeArray;
  }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();

    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

  applyFilterHistory(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSourceHistory.filter = filterValue.trim().toLowerCase();

    if (this.dataSourceHistory.paginator) {
      this.dataSourceHistory.paginator.firstPage();
    }}
 
  info: any = null;
  onlyView:boolean=false;

  addPaymentApprovals(ele: any ,view:boolean=false) {
    this.info = ele;
    this.vcr.clear(); // Clear previous views if any
    this.vcr.createEmbeddedView(this.popupTemplate); // Render the popup template
    this.onlyView =view;
    if(!view){
      this.editRowDetails = this.info;
      this.companyForm.setValue({
        id: ele.id,
        financialYear:this.financialYear,
        employeeId:this.userSession.id,
        companyNameValue: ele.company_name,
        address1: ele.address1,
        address2: ele.address2,
        country: ele.country_id,
        state: ele.state_id,
        city: ele.city_id,
        companyTan: ele.company_tan,
        fromDate: ele.employment_from_date,
        toDate: ele.employment_to_date,
        grossPaidAmount: ele.total_gross_paid_amount ? ele.total_gross_paid_amount.slice(0,-3) : ele.total_gross_paid_amount,
        basicSalary: ele.basic_salary ? ele.basic_salary.slice(0,-3) : ele.basic_salary,
        hra: ele.house_rent_allowance ? ele.house_rent_allowance.slice(0,-3) : ele.house_rent_allowance,
        deductedTaxAmount: ele.deducted_tax_amount ? ele.deducted_tax_amount.slice(0,-3) : ele.deducted_tax_amount,
        rentPaid: ele.rent_paid ? ele.rent_paid.slice(0,-3) : ele.rent_paid,
        documentPath:ele.document_path,
        fileName:ele.file_name,
        submissionStatus:"Approved",
        createdBy:this.userSession.id,
        updatedBy:this.userSession.id,
        approvedBy: this.userSession.id,
      });
      this.fileName = ele.file_name;
      this.companyForm.updateValueAndValidity();  
      Object.keys(this.companyForm.controls).forEach(control => {
        const controlErrors = this.companyForm.get(control)?.errors;
        if (controlErrors) {
          console.log(`Control: ${control}, Errors:`, controlErrors);
        }
      });  
    }
  }
  setEmployeePreviousCompanyPayment(){
 
    if(this.companyForm.invalid){
      Object.keys(this.companyForm.controls).forEach(control => {
        const controlErrors = this.companyForm.get(control)?.errors;
        if (controlErrors) {
          console.log(`Control: ${control}, Errors:`, controlErrors);
        }
      });

    }else{
      
        this.tdsService.setEmployeePreviousCompanyPayment(this.companyForm.getRawValue(),this.selectedFile).subscribe((results:any)=>{
          if (results.status && results.data[0].output === 1) {
            this.tdsService.message("Previous company payment edited and approved successfully.")
            this.companyForm.reset()
            this.closePopup();
            this.fileName = null;
            this.getPrevCompanyPayRequestsForApproval();
          }
          else {
            this.tdsService.message('Please try again later.')
          }
        })
    }
   
  }

  closePopup() {
    this.info = null;
    this.vcr.clear();
    this.onlyView=false;
    this.editRowDetails =null;

  }
  approve(info:any){
    let data  = {
      ptepm_id_value : info.id,
      submission_status_value: this.isReject ? 'Rejected' : 'Approved',
      mgr_id_value:this.userSession.id,
      rejection_reason_value:this.rejectReason ? this.rejectReason : null,
    }
    this.tdsService.approveEmployeePreviousCompanyPayment(data).subscribe((result:any)=>{
    if(result.data[0].output === 1){
      this.tdsService.message(this.rejectReason ? 'The previous company details rejected successfully.' : 'The previous company details approved successfully.');
      this.cancel();
    }else{
      this.tdsService.message('Please try again later.')
    }     
    })
  }

  reject(info:any){
  this.isReject = true;
  this.titleName = "Reason For Rejection";
  this.openDialog(info);
  }

  getPrevCompanyPayRequestsForApproval(){
    this.tdsService.getPrevCompanyPayRequestsForApproval(this.financialYear).subscribe((result:any)=>{
      if(result && result.status){
        this.previousCompanyPaymentsApprovals = result.data;
        this.dataSource = new MatTableDataSource(result.data)
        this.dataSource.paginator =this.paginator;
        this.pageLoading = result.data.length <= 10 ? true : false;
      }
    })
  }

  getEmployeePreviousCompanyPaymentsHistory(){
    this.tdsService.getEmployeePreviousCompanyPaymentsHistory(this.financialYear).subscribe((result:any)=>{
      this.previousCompanyPaymentsHistory = result.data;
      this.dataSourceHistory = new MatTableDataSource(result.data)
      this.dataSourceHistory.paginator =this.paginatorHistory;
      this.pageLoadingHistory = result.data.length <= 10 ? true : false;
    })
  }
  cancel(){
    this.router
    .navigateByUrl('/', { skipLocationChange: true })
    .then(() => this.router.navigate(['/Payroll/previousCompanyPaymentApprovals']));
  }
  getCountry() {
    this.countryDetails = [];
    this.companyService
      .getCountry('countrymaster', null, 1, 10, this.companyDBName)
      .subscribe((result:any) => {
        this.countryDetails = result.data;
        this.filteredCountryDetails = this.countryDetails;
      });
  }
  filterCityDetails(searchText: any) {
    this.filteredCityDetails = this.cityDetails.filter((val: any) =>
      val.location.toLowerCase().includes(searchText.toLowerCase()));
    if (this.filteredCityDetails.length <= 0) {
      this.searchControlForCity.setValue('');
    }
  }
  filterStateDetails(searchText: any) {
    this.filteredStateDetails = this.stateDetails.filter((val: any) =>
      val.state.toLowerCase().includes(searchText.toLowerCase()));
    if (this.filteredStateDetails.length <= 0) {
      this.searchControlForSate.setValue('');
    }
  }

  filterCountryDetails(searchText: any) {
    this.filteredCountryDetails = this.countryDetails.filter((val: any) =>
      val.country.toLowerCase().includes(searchText.toLowerCase()));
    if (this.filteredCountryDetails.length <= 0) {
      this.searchControlForControl.setValue('');
    }
  }

  fnGetCurrentFinYearDates(){
    this.tdsService.fnGetCurrentFinYearDates().subscribe((result:any)=>{
      if(result.status){
        this.finYearEndDate=result.data[0].end_date;
        this.finYearStartDate = result.data[0].start_date;
      }
      this.minFromDate= this.finYearStartDate.toString();
      // this.maxFromDate=this.finYearEndDate.toString();
      // this.maxToDate=this.finYearEndDate.toString();
      this.minToDate = this.finYearStartDate.toString();
      this.maxFromDate = this.finYearEndDate.toString();
      this.maxToDate = this.finYearEndDate.toString();
    })
  }

    openDialog(data: any): void {
      const dialogRef = this.dialog.open(DialogComponent, {
        width: '600px', position: { top: `100px` },
        data: { name: this.titleName, reason: this.rejectReason, }
      });
      dialogRef.afterClosed().subscribe(result => {
        if (result != undefined) {
          if (result !== true) {
            this.rejectReason = result.reason;
            this.approve(data);
          }
        }
      });
    }

  showPdf(path: any, file_name: any) {
    this.tdsService.showPdf(path,file_name)
  }

  deleteDocument() {
    this.fileName = null;
  }

  onFileSelected(event: Event): void {

    const input = event.target as HTMLInputElement;
  
    if (input.files && input.files[0]) {
      const file = input.files[0];
      if (file) {
        const maxSize = 5 * 1024 * 1024; // 5 MB in bytes
        this.filesize = true;
        this.fileNameError = true;
        this.fileType =true;  
        const allowedExtensions = ['jpg', 'png', 'pdf', 'jpeg'];
        const fileExtension = file.name.split('.').pop()?.toLowerCase();
        if (!fileExtension || !allowedExtensions.includes(fileExtension)) {
          this.fileType =false  
          this.selectedFile = null      
          return;
        }
       if (file.size > maxSize) {
          this.filesize = false;
          this.selectedFile = null
          return
        } 
         if (file.name.length > 90) {
          this.fileNameError = false;
          this.selectedFile = null
          return
        } else {
          this.selectedFile = file
        }
      }
    }
  }

  changeAmount(){
    let grossAmt = Number(this.companyForm.get('grossPaidAmount')?.value);
    let basicAmt = Number(this.companyForm.get('basicSalary')?.value);
    let houseRent = Number(this.companyForm.get('hra')?.value);
    let deductionAmt = Number(this.companyForm.get('deductedTaxAmount')?.value);
    let totalSubAmt = basicAmt + houseRent + deductionAmt;
   
    if(basicAmt > grossAmt || totalSubAmt > grossAmt){
      this.tdsService.showSnackBar('You cannot declare beyond the gross amount.');
      this.companyForm.controls.basicSalary?.setValue(null);
  
    } else if(houseRent > grossAmt || totalSubAmt > grossAmt){
      this.tdsService.showSnackBar('You cannot declare beyond the gross amount.')
      this.companyForm.controls.hra?.setValue(null);
   
    } else if(deductionAmt > grossAmt || totalSubAmt > grossAmt){
      this.tdsService.showSnackBar('You cannot declare beyond the gross amount.');
      this.companyForm.controls.deductedTaxAmount?.setValue(null);
    } 
  }

}
