import { Directive, HostListener } from '@angular/core';
import { NgControl } from '@angular/forms';

@Directive({
  selector: '[numbersSpecialChars]'
})
export class NumbersSpecialCharsDirective {

constructor(private ngControl: NgControl) {}

  @HostListener('input', ['$event']) 
  onInput(event: Event): void {
    const input = event.target as HTMLInputElement;

    // Replace any alphabets (both upper and lower case)
    const cleanedValue = input.value.replace(/[a-zA-Z]/g, '');

    // Update the input value if it was modified
    if (input.value !== cleanedValue) {
      input.value = cleanedValue;
      if (this.ngControl?.control) {
        this.ngControl.control.setValue(cleanedValue);
      }
    }
  }

}
