import { Component, OnInit, ViewChild, ElementRef } from '@angular/core';
import {
  UntypedFormGroup, Validators,
  UntypedFormBuilder
} from '@angular/forms';
import { Router } from '@angular/router';
import { MatDialog } from '@angular/material/dialog';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { EmsService } from '../../ems.service';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { AdminService } from 'src/app/modules/admin/admin.service';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { TranslateService } from '@ngx-translate/core';

@Component({
  selector: 'app-users-login',
  templateUrl: './users-login.component.html',
  styleUrls: ['./users-login.component.scss'],
})
export class UsersLoginComponent implements OnInit {
 // @HostListener('window:scroll')
  usersloginForm: any = UntypedFormGroup;
  designations: any = [];
  min: any = new Date();
  max: any = new Date();
  isview: boolean = true;
  ishide: boolean = false;
  pageLoading = true;
  EM134: any;
  EM135: any;
  displayedColumns: string[] = [
    'sno',
    'empid',
    'empname',
    'contactnumber',
    'location',
    'email',
    'userid',
    // 'status',
    'action',
  ];
  // dataSource = new MatTableDataSource<PeriodicElement>(Sample_Data);
  dataSource: MatTableDataSource<any> = <any>[];
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
   @ViewChild('useridInput') useridInput!: ElementRef;
  companyName: any;
  companyDBName: any;
  constructor(
    private formBuilder: UntypedFormBuilder,
    private router: Router,
    private ES: EmsService,
    public dialog: MatDialog,
    private EM: AdminService,
    private companyServices: CompanySettingService,
     private translate: TranslateService
  ) { }
  userLoginList: any = [];
  userSession:any=[];
  btnDisable:boolean = false;
    languages = [
    { code: 'english', label: 'ENGLISH', name: 'English' },
    { code: 'arabic', label: 'ARABIC', name: 'Arabic' }
  ];
  ngOnInit(): void {
    const savedLang = localStorage.getItem('lang');
   this.translate.use(savedLang || 'english');

    this.userSession = sessionStorage.getItem('companyName') || '';
    this.companyDBName = this.userSession;
    this.getUserLoginData();
    this.getMessageList();
    this.getCompanyInformation();
    this.usersloginForm = this.formBuilder.group({
      empcode: [{ value: '', disabled: true }],
      empname: [{ value: '', disabled: true }],
      location: [{ value: '', disabled: true }],
      email: [{ value: '', disabled: true }],
      userid: [
        '',
        [
          Validators.required,
          Validators.minLength(3),
          Validators.maxLength(50),
        ],
      ],
      password: [{ value: 'Welcome1!', disabled: true }, Validators.required],
      status: [{ value: '', disabled: true }],
      empid: [''],
    });
  }
  close() {
    this.router
      .navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/Admin/users-login']));
  }
  edit(event: any, data: any) {
    this.ishide = true;
    this.isview = false;
    this.usersloginForm.controls.empcode.setValue(data.empid);
    this.usersloginForm.controls.empname.setValue(data.empname);
    this.usersloginForm.controls.location.setValue(data.location);
    this.usersloginForm.controls.email.setValue(data.officeemail);
    this.usersloginForm.controls.userid.setValue(
      (data.login === 'null' ? data.login : data.officeemail)
    );
    this.usersloginForm.controls.status.setValue('Active');
    this.usersloginForm.controls.empid.setValue(data.id);
    window.scroll({
      top: 0,
      left: 0,
      behavior: 'smooth',
    });
    setTimeout(() => {
    this.useridInput.nativeElement.focus();
  }, 100);
  }
  delete() {}

  getUserLoginData() {
    this.ES.getUserLoginData().subscribe((res: any) => {
      if (res.status && res.data.length != 0) {
        this.userLoginList = res.data;
        this.dataSource = new MatTableDataSource(res.data);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        if (res.data.length > 20) {
          this.pageLoading = false;
        }
      }
    });
  }
  submit() {
    if (this.usersloginForm.valid) {
      if (this.userLoginList != undefined) {
        const email = this.userLoginList.find(
          (value: any) =>
            value.login ==
            this.usersloginForm.controls.userid.value.trim().toLowerCase()
        );
        if (email != undefined) {
          let dialogRef = this.dialog.open(ReusableDialogComponent, {
            disableClose: true,
            data: 'Already existing this user id. Please try another',
          });
        } else {
          this.saveUserLogin();
        }
      } else {
        this.saveUserLogin();
      }
    }
  }
  saveUserLogin() {
    if (this.usersloginForm.valid) {
      if (this.btnDisable) {
        return;
      }
      let data = {
        empname:this.usersloginForm.controls.empname.value,
        email:this.usersloginForm.controls.email.value,
        empid: this.usersloginForm.controls.empid.value,
        userid: this.usersloginForm.controls.userid.value,
        password: this.usersloginForm.controls.password.value,
        status: this.usersloginForm.controls.status.value,
        companyname: this.companyName,
        companyCode:this.companyDBName
      };
      this.btnDisable = true;
      this.ES.usersLogin(data).subscribe((res: any) => {
        if (res.status&&res.successstate!=1) {
          this.router.navigateByUrl('/', { skipLocationChange: true })
            .then(() => this.router.navigate(['/Admin/users-login']));
          this.ishide = true;
          this.isview = false;
          let dialogRef = this.dialog.open(ReusableDialogComponent, {
            position: { top: `70px` },
            disableClose: true,
            data: this.EM134,
          });
        } else if(res.successstate==1){
          let dialogRef = this.dialog.open(ReusableDialogComponent, {
            position: { top: `70px` },
            disableClose: true,
            data: "Already existing this user id."+this.EM135,
          });
          this.btnDisable = false;
        }
        else {
          let dialogRef = this.dialog.open(ReusableDialogComponent, {
            position: { top: `70px` },
            disableClose: true,
            data: this.EM135,
          });
          this.btnDisable = false;
        }
      });
    }
  }
  getPageSizes(): number[] {
     
  var customPageSizeArray = [];
  if (this.dataSource.data.length > 5) {
    customPageSizeArray.push(5);
  }
  if (this.dataSource.data.length > 10) {
    customPageSizeArray.push(10);
  }
  if (this.dataSource.data.length > 20) {
    customPageSizeArray.push(20);
  }
  customPageSizeArray.push(this.dataSource.data.length);
  return customPageSizeArray;
  }
  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }
  getMessageList(){
    let info={
      "code": null,
      "pagenumber":1,
      "pagesize":1000
    }
    this.EM.getEMSMessagesList(info).subscribe((result: any) => {
      if(result && result.status){
        for(let i=0;i<result.data.length;i++){
          if(result.data[i].code =='EM134'){
            this.EM134=result.data[i].message;

          }else if(result.data[i].code =='EM135'){
            this.EM135=result.data[i].message;

          }
        }

      }

    })

  }
  getCompanyInformation(){
    this.companyServices.getCompanyInformation('companyinformation',null,1,10,this.companyDBName).subscribe((data:any)=>{
      if (data.status && data.data.length != 0) {
         this.companyName=data.data[0].companyname;

      }else {
        }

    })

  }
}
