  constructor(private zone: NgZone, private cdr: ChangeDetectorRef, private chatbotService: ChatbotService, private loginService: LoginService

  ) {
  }


  ngOnInit(): void {

    this.loadUserData();
    const margin = 20;
    const iconSize = 70;
    this.posX = window.innerWidth  - iconSize - margin;
    this.posY = window.innerHeight - iconSize - margin;

    this.loginService.loggedIn$.subscribe((loggedIn) => {
      this.isLoggedIn = loggedIn;
      if (loggedIn) {
        this.loadUserData();
        this.refreshChatbot();
        this.resetLanguage(); // Reset language on logout

      }
    });

   const User = sessionStorage.getItem('user');
    if (User) {
      this.isLoggedIn = true;
      if (!sessionStorage.getItem('welcomeMessageShown')) {
        this.refreshChatbot();
      }
    }


    if (this.isLoggedIn && !sessionStorage.getItem("welcomeMessageShown")) {
      this.showWelcomeMessage = true;
      sessionStorage.setItem("welcomeMessageShown", "true");

      setTimeout(() => {
        this.showWelcomeMessage = false;
        if (this.messages.length > 0) {
          this.messages.pop();
        }
        this.cdr.detectChanges();
      }, 6000);
    } else {
      this.showWelcomeMessage = false;
    }




  const SpeechRecognition =
    (window as any).SpeechRecognition ||
    (window as any).webkitSpeechRecognition;


  if (SpeechRecognition) {
    this.recognition = new SpeechRecognition();

    // Use selectedLanguage 
    this.recognition.lang = this.selectedLanguage;
    this.recognition.interimResults = true;
    this.recognition.continuous = false;

      this.recognition.onstart = () => {
        this.isListening = true;
      };

      this.recognition.onresult = (event: any) => {
        let interimTranscript = '';
        for (let i = event.resultIndex; i < event.results.length; i++) {
          if (event.results[i].isFinal) {
            this.zone.run(() => {
              this.userMessage = event.results[i][0].transcript.trim();
            });
          } else {
            interimTranscript += event.results[i][0].transcript;
            this.zone.run(() => {
              this.userMessage = interimTranscript.trim();
            });
          }
        }
      };

      this.recognition.onerror = (event: any) => {
        console.error('Speech recognition error:', event.error);
        this.isListening = false;
      };

      this.recognition.onend = () => {
        this.isListening = false;
        if (this.userMessage.trim()) {
          this.sendMessage();
        }
      };
    } else {
      console.error('SpeechRecognition API is not supported in this browser.');
    }



  }


  resetLanguage() {
    this.selectedLanguage = "en-US"; // ✅ Reset to default
    sessionStorage.removeItem('selectedLanguage'); // ✅ Clear stored language
  }

  

  loadUserData() {
    const storedUser = sessionStorage.getItem('user');
    if (storedUser) {
      this.user = JSON.parse(storedUser);
      this.empId = this.user.id;
      this.roles = Array.isArray(this.user.roles)
        ? this.user.roles.map((r: any) => r.role_name)
        : [];
      this.companyCode = sessionStorage.getItem('companyName') || '';

      if (this.roles.some((role: string) =>
        /^(super\s*admin|finance\s*admin)$/i.test(role.trim())
      )) {
        this.userRole = 'SuperAdmin';

      } else if (this.roles.some((role: string) => {
        const lower = role.trim().toLowerCase();
        return lower.includes('admin');
      })
      ) {
        this.userRole = 'Admin';
    } else if (this.roles.some((role: string) => role.toLowerCase().includes("manager"))) {
      this.userRole = "Manager";
    } else if (this.roles.some((role: string) => role.toLowerCase().includes("employee") || role.toLowerCase().includes("executive"))) {
      this.userRole = "Employee";
    }


    }
  }

selectModule(module: string) {
  this.selectedModule = module;
  // grab the array of QAItems for this module+role (or empty array)
  const items = this.qaMap[module]?.[this.userRole] || [];
  // extract just the questions
  this.selectedQuestions = items.map(item => item.question);
}

  
