  // chatbot.component.ts

refreshChatbot() {
  // clear out any prior conversation
  this.messages = [];
  this.isChatOpen = false;

  // reset module/question selection
  this.selectedModule = null;
  this.selectedQuestions = [];

  // optional: also clear whatever was typed
  this.userMessage = '';

  // your existing welcome-message logic…
  if (!localStorage.getItem('welcomeMessageShown')) {
    this.showWelcomeMessage = true;
    localStorage.setItem('welcomeMessageShown', 'true');
    setTimeout(() => {
      this.showWelcomeMessage = false;
      this.cdr.detectChanges();
    }, 10000);
  }
}



// 3) In your setLanguage(...) handler, also update the recognizer:
setLanguage(event: Event) {
  const target = event.target as HTMLSelectElement;
  this.selectedLanguage = target.value;
  sessionStorage.setItem('selectedLanguage', this.selectedLanguage);

  // Sync speech-recognition engine immediately
  if (this.recognition) {
    this.recognition.lang = this.selectedLanguage;
  }
}




  // // Adjust your existing selectQuestion() if needed so that clicking a question adds it as a message.
  // selectQuestion(question: string) {
  //   // For example, add the question as a user message (or perform any intended action)
  //   this.userMessage = question;
  //   this.sendMessage();
  // }

selectQuestion(question: string) {
  // show the user’s question
  this.messages.push({ sender: 'user', text: question });

  if (this.selectedModule) {
    const items = this.qaMap[this.selectedModule]?.[this.userRole] || [];
    const match = items.find(item => item.question === question);
    if (match) {
      // display the canned answer
      this.messages.push({ sender: 'bot', text: match.answer });
      this.scrollToBottom();
      return;
    }
  }

  // fallback to API if not in qaMap
  this.sendMessage();
}



readAloud(text: string, index: number) {
  const messageId = `msg-${index}`;

  // 1) If already playing, toggle pause/resume
  if (this.playingMessageId === messageId && this.audioMap[messageId]) {
    const audio = this.audioMap[messageId];
    audio.paused ? audio.play() : audio.pause();
    this.cdr.detectChanges();
    return;
  }

  // 2) Stop any other playback
  if (this.playingMessageId && this.audioMap[this.playingMessageId]) {
    this.audioMap[this.playingMessageId].pause();
  }

  // 3) Show spinner
  this.ttsLoading[messageId] = true;

  // 4) Build the request payload _before_ you call fetch
  const detectedLang = franc(text);
  const languageCode = this.languageMap[detectedLang] || "en-US";
  const requestBody = {
    input: { text },
    voice: { languageCode, ssmlGender: "NEUTRAL" },
    audioConfig: { audioEncoding: "MP3" }
  };

  // 5) Fire your fetch
  fetch(
    `https://texttospeech.googleapis.com/v1/text:synthesize?key=${this.googleApiKey}`,
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(requestBody)     // ← now requestBody is defined
    }
  )
    .then(resp => resp.json())
    .then(data => {
      this.ttsLoading[messageId] = false;
      if (data.audioContent) {
        const audio = new Audio("data:audio/mp3;base64," + data.audioContent);
        this.audioMap[messageId] = audio;
        this.playingMessageId = messageId;
        audio.play();
        this.cdr.detectChanges();
        audio.onended = () => {
          this.playingMessageId = null;
          this.cdr.detectChanges();
        };
      } else {
        console.error("TTS error:", data);
      }
    })
    .catch(err => {
      this.ttsLoading[messageId] = false;
      console.error("Fetch error:", err);
    });
}




  detectLanguage(text: string): string {
    if (!text || text.trim().length < 3) return 'eng';

    const detectedLang = franc(text);
    return detectedLang !== 'und' ? detectedLang : 'eng';
  }




  toggleChat() {
    this.showWelcomeMessage = false;
    this.isChatOpen = !this.isChatOpen;
  }

  onInput(event: Event) {
    const inputElement = event.target as HTMLInputElement;
    this.userMessage = inputElement.value;
  }



  sendMessage() {
    if (this.userMessage.trim()) {
      this.zone.run(() => {
        this.messages.push({ sender: 'user', text: this.userMessage });
        this.isProcessing = true;



        const selectedLangObj = this.languageOptions.find(lang => lang.code === this.selectedLanguage);
        const selectedLanguageName = selectedLangObj ? selectedLangObj.name : "English";

        this.chatbotService.sendMessage(this.userMessage, this.empId, this.companyCode, this.roles, selectedLanguageName)
          .subscribe(
            (response) => {
              this.messages.push({ sender: 'bot', text: response.answer });
              this.isProcessing = false;
              this.scrollToBottom();
            },
            (error) => {
              console.error('Error:', error);
              this.messages.push({ sender: 'bot', text: 'Unable to answer the question at this moment.' });
              this.isProcessing = false;
              this.scrollToBottom();
            }
          );

        this.userMessage = '';
        this.scrollToBottom();
      });
    }
  }




  scrollToBottom() {
    try {
      setTimeout(() => {
        this.chatboxBody.nativeElement.scrollTop =
          this.chatboxBody.nativeElement.scrollHeight;
      });
    } catch (err) {
      console.error('Scroll Error:', err);
    }
  }



  // In chatbot.component.ts

toggleSpeechRecognition() {
  const SpeechRecognition =
    (window as any).SpeechRecognition ||
    (window as any).webkitSpeechRecognition;

  if (!SpeechRecognition) {
    alert('Speech recognition is not supported in this browser. Please use Google Chrome or a compatible browser.');
    return;
  }

  // If we haven't yet created a recognition instance, do so now
  if (!this.recognition) {
    this.recognition = new SpeechRecognition();
    this.recognition.continuous = false;
    this.recognition.interimResults = false;
    this.recognition.lang = this.selectedLanguage;

    this.recognition.onstart = () => {
      this.isListening = true;
      this.cdr.detectChanges();
    };

    this.recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      this.userMessage = transcript;
      this.sendMessage();
    };

    this.recognition.onerror = (event: any) => {
      console.error('Speech Recognition Error:', event.error);
    };

    this.recognition.onend = () => {
      this.isListening = false;
      this.cdr.detectChanges();
    };
  }

  // Toggle listening state
  if (this.isListening) {
    this.recognition.stop();
    // .onend handler will flip isListening to false
  } else {
    // Always ensure the recognizer uses the latest dropdown choice
    this.recognition.lang = this.selectedLanguage;
    this.recognition.start();
  }
}


