private setInitialPosition() {
    const margin = 20, iconSize = 70;
    this.posX = window.innerWidth  - iconSize - margin;
    this.posY = window.innerHeight - iconSize - margin;
  }

  private constrainPosition() {
    const margin = 20, iconSize = 70;
    const maxX = window.innerWidth  - iconSize - margin;
    const maxY = window.innerHeight - iconSize - margin;
    this.posX = Math.min(Math.max(this.posX, 0), maxX);
    this.posY = Math.min(Math.max(this.posY, 0), maxY);
  }

