onDialogManagersChange() {
  if (!this.dialogSelectedManagerIds.length) {
    this.dialogEmployees = [];
    this.filteredDialogEmployees = [];
    this.dialogSelectedEmployeeIds = [];
    return;
  }

  this.learnService
    .getEmployeesbyManager(this.dialogSelectedManagerIds, this.assigningCourseId) // ✅ pass courseId instead of null
    .subscribe({
      next: (emps: any[]) => {
        this.dialogEmployees = emps.map(emp => ({
          ...emp,
          statusText: this.getStatusText(emp.course_status),
          statusClass: this.getStatusClass(emp.course_status),
          selectable: emp.course_status === '0'  // ✅ only Not Enrolled can be selected
        }));

        this.filteredDialogEmployees = this.dialogEmployees;

        // ✅ auto-select only the "Not Enrolled" employees
        this.dialogSelectedEmployeeIds = this.dialogEmployees
          .filter(e => e.selectable)
          .map(e => e.employee_id);
      },
      error: err => {
        console.error('Error loading dialog employees', err);
        this.dialogEmployees = [];
        this.filteredDialogEmployees = [];
      }
    });
}

// 🔹 Helper method to validate and sanitize text input (letters and spaces only)
private validateTextOnly(input: string): string {
  return input.replace(/[^a-zA-Z ]/g, '');
}

// 🔹 Prevent typing of non-text characters (numbers, symbols, special chars)
onTextKeyPress(event: KeyboardEvent): void {
  // Allow only letters (a-z, A-Z) and space
  const isLetter = /^[a-zA-Z ]$/.test(event.key);
  const isBackspace = event.key === 'Backspace';
  const isDelete = event.key === 'Delete';
  const isArrow = event.key.startsWith('Arrow');
  const isTab = event.key === 'Tab';
  
  if (!isLetter && !isBackspace && !isDelete && !isArrow && !isTab) {
    event.preventDefault();
  }
}

filterDialogEmployees(searchValue: string): void {
  if (!searchValue || searchValue.trim().length === 0) {
    this.filteredDialogEmployees = this.dialogEmployees;
    return;
  }

  this.learnService.searchEmployees(searchValue).subscribe({
    next: (response: any) => {
      let emps = response.employees || response;
      // only show employees that exist in the current dialog list
      const allowed = new Set(this.dialogEmployees.map(e => e.employee_id));
      emps = emps.filter((r: any) => allowed.has(r.id));
      
      const mappedSearchResults = emps.map((emp: any) => {
        const originalEmp = this.dialogEmployees.find(e => e.employee_id === emp.id);
        return {
          ...originalEmp,
          ...emp,
          employee_id: emp.id,
          emp_name: emp.full_name,
          statusText: this.getStatusText(originalEmp?.course_status || emp.course_status),
          statusClass: this.getStatusClass(originalEmp?.course_status || emp.course_status),
          selectable: (originalEmp?.course_status || emp.course_status) === '0'
        };
      });

      // 🔥 IMPORTANT: Also include already-selected employees that didn't match search
      // This ensures selections remain visible even after filtering
      const searchResultIds = new Set(mappedSearchResults.map((e: any) => e.employee_id));
      const selectedButNotInResults = this.dialogEmployees.filter(
        (e: any) => this.dialogSelectedEmployeeIds.includes(e.employee_id) && !searchResultIds.has(e.employee_id)
      );

      // Combine search results with already-selected employees, avoiding duplicates
      this.filteredDialogEmployees = mappedSearchResults;
    },
    error: (err) => {
      console.error('Error searching employees', err);
      this.filteredDialogEmployees = this.dialogEmployees;
    }
  });
}

