// 🔹 Main dashboard employees dropdown filter
filterDashboardEmployees(searchValue: string): void {
  // reuse the same validator if you like
  const sanitized = this.validateTextOnly(searchValue);
  if (!sanitized || sanitized.trim().length === 0) {
    this.filteredDashboardEmployees = this.employees;
    return;
  }

  const term = sanitized.toLowerCase().trim();
  this.learnService.searchEmployees(term).subscribe({
    next: (response: any) => {
      // normalize into array
      let emps: any[] = [];
      const raw = response?.employees ?? response;
      if (Array.isArray(raw)) {
        emps = raw;
      } else if (raw && typeof raw === 'object') {
        emps = [raw];
      }

      const allowed = new Set(this.employees.map(e => e.employee_id));
      emps = emps.filter((r: any) => allowed.has(r.id));
      
      const mappedSearchResults = emps.map((emp: any) => ({
        ...emp,
        employee_id: emp.id,
        emp_name: emp.full_name,
        statusText: this.getStatusText(emp.course_status),
        statusClass: this.getStatusClass(emp.course_status),
        selectable: emp.course_status === '0'
      }));

      // 🔥 IMPORTANT: Also include already-selected employees that didn't match search
      // This ensures selections remain visible even after filtering
      const searchResultIds = new Set(mappedSearchResults.map((e: any) => e.employee_id));
      const selectedButNotInResults = this.employees.filter(
        (e: any) => this.selectedEmployeeIds.includes(e.employee_id) && !searchResultIds.has(e.employee_id)
      );

      // Combine search results with already-selected employees, avoiding duplicates
      this.filteredDashboardEmployees = mappedSearchResults;
    },
    error: (err) => {
      console.error('Error searching employees', err);
      this.filteredDashboardEmployees = this.employees;
    }
  });
}

