// 🔹 Compare employees by ID for MatSelect with dynamic filtering
compareEmployees(e1: any, e2: any): boolean {
  if (e1 === null || e1 === undefined) return e2 === null || e2 === undefined;
  if (e2 === null || e2 === undefined) return false;
  return e1 === e2; // compares by ID value (number), not object reference
}

// 🔹 Helpers for status mapping
getStatusText(status: string): string {
  switch (status) {
    case '0': return 'Not Enrolled';
    case '1': return 'Assigned';
    case '2': return 'Enrolled';
    case '3': return 'Completed';
    default: return '';
  }
}

getStatusClass(status: string): string {
  switch (status) {
    case '0': return 'status-not-enrolled';  // green
    case '1': return 'status-assigned';      // blue
    case '2': return 'status-enrolled';      // orange
    case '3': return 'status-completed';     // gray
    default: return '';
  }
}


