// Unified toggle method for all tooltips - hides and re-shows to refresh content
toggleTooltip(key: string, tooltip?: MatTooltip, event?: MouseEvent): void {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }

  this.expandedTooltips[key] = !this.expandedTooltips[key];

  // Force tooltip to update by hiding and showing it with updated content
  if (tooltip) {
    const wasVisible = tooltip._isTooltipVisible();
    tooltip.hide();

    // Use a timeout to ensure the tooltip has time to hide before showing again
    setTimeout(() => {
      if (wasVisible) {
        tooltip.show();
      }
    }, 50);
  }
  this.cdr.detectChanges();
}

// Hover handlers to display tooltips with proper content
onEnrolledHover(): void {
  // This will trigger the tooltip to show with the current expanded state
  this.cdr.detectChanges();
}

