import { Component, OnInit,ChangeDetectorRef } from '@angular/core';
import { BaseService } from '../../services/base.service';
import { CompanyInformationService } from "../../services/company-information.service";
import { NgxSpinnerService } from "ngx-spinner";
import { Router } from "@angular/router";
import { MainService } from "../../services/main.service";
import { MatDialog } from '@angular/material/dialog';
import { LoginService } from 'src/app/services/login.service';
import { TranslateService } from '@ngx-translate/core';
@Component({
  selector: 'app-header',
  templateUrl: './header.component.html',
  styleUrls: ['./header.component.scss']
})
export class HeaderComponent implements OnInit {
  checkHeadNav: any;
  checkToggleBar: any;
  toggleValue: any;
  subscription: any;
  pic:any;
  usersession:any;
  data:any;
  empname:any;
  email:any;
  imageurls:any;
  companyName: any;
  companyinfo: any;
  activeModule:any;
  companyDBName: any;
  infodata: any;
  valid: boolean = false;
  flag: boolean = true;
  selectedModule: any = '';
  isSuperAdmin: boolean=false;
  isProductAdmin: boolean=false;
  openDialogsCount: number = 0;

  currentLang:any;
  languages = [
    { code: 'english', label: 'ENGLISH', name: 'English' },
    { code: 'arabic', label: 'ARABIC', name: 'Arabic' }
  ];

  constructor(private baseService: BaseService,private mainService:MainService,private dialog: MatDialog,private cdr: ChangeDetectorRef,
    private LM: CompanyInformationService, public router: Router,private loginService: LoginService,private translate: TranslateService
  ) {
    let savedLang = localStorage.getItem('lang') || 'english';
    this.currentLang = savedLang;
    this.translate.use(savedLang || 'english');
    // // translate.setDefaultLang('english');
    // translate.use(savedLang);

      this.usersession = JSON.parse(sessionStorage.getItem('user') ?? '');
      this.companyDBName = sessionStorage.getItem('companyName');
      if (this.usersession.firstlogin == "N") {
        this.flag = true;
      }
      else {
        this.flag = false;
      }
      if (this.usersession.is_super_admin =="1") {
        this.isSuperAdmin = true;
        this.isProductAdmin = false;
      } 
      else if(this.usersession.roles[0].role_name == "Product Admin"){
        this.isSuperAdmin = false;
        this.isProductAdmin = true;
      }else
        {
        this.isSuperAdmin = false;
        this.isProductAdmin = false;
      }
     }
  subscriptionExpiryMessage:any;
  expiryDays:any;
  expiryAlert:boolean = false;
  ngOnInit(): void {
    let savedLang = localStorage.getItem('lang') || 'english';
    this.currentLang = savedLang;
    this.translate.use(savedLang || 'english');
    this.baseService.setHeadNav("admin");
    this.getHeadNav();
    this.getToggleSideBar()
    this.selectedModule =sessionStorage.getItem('selectedModule')??'';
   // this.activeModule = JSON.parse(sessionStorage.getItem('activeModule') || '');
    this.getLogo()
    this.getUploadImage();
    this.getCompanyInformation();
    this.empname = this.usersession.firstname;
    this.email = this.usersession.officeemail;
    const expirationDate = sessionStorage.getItem('expirydate')??''; 
    // const expirationDate = "2024-11-21"; 
    this.subscriptionExpiryMessage = this.calculateDaysUntilExpiry(expirationDate); 
     
  }
  ngAfterViewInit() {
    let  savedLang = localStorage.getItem('lang');
    this.translate.use(savedLang || 'english');
    this.cdr.detectChanges(); // ✅ refresh view safely
  }
    changeLanguage(langCode: any) {
    console.log("language",langCode)
    this.translate.use(langCode);
    localStorage.setItem('lang', langCode);
    window.location.reload();
  }
  logout(){
    this.dialog.closeAll();
    sessionStorage.removeItem('companyFullName');
    sessionStorage.removeItem('client_Id');
    sessionStorage.removeItem('companyName');
    sessionStorage.removeItem('expirydate');
    sessionStorage.removeItem('moduleData');
    sessionStorage.removeItem('user')
    sessionStorage.removeItem('sidemenu');
    sessionStorage.removeItem('activeModule');
    sessionStorage.removeItem('token');
    sessionStorage.removeItem('compOffEnabled');
    sessionStorage.clear();
    this.loginService.setLoggedInState(false);
    var login = '/Login'
    this.router.navigate([login]);
  }
  
  onClickMainDashboard(){
    if(this.usersession.roles[0].role_name == "Product Admin"){
      this.router.navigate(['/Admin/product-admin-dashboard']);
    }
    else if(this.usersession.is_super_admin =="1"){
      this.router.navigate(['/main/client-superadmin-dashboard']);
     }else{
      this.router.navigate(['/main/MainDashboard']);
    }
     sessionStorage.setItem('selectedModule','' );
    this.selectedModule =sessionStorage.getItem('selectedModule')??'';
  }

  setHeadNav(data:any): void {
    this.baseService.setHeadNav(data);
    this.baseService.clearSubSideNav();
    this.baseService.clearToggleSideBar();
    if(data === "self")
      this.baseService.setSideNav("dashboard");
    else if(data === "myTeam")
      this.baseService.setSideNav("leaveManagement");
    else if(data === "admin")
      this.baseService.setSideNav("adminDashboard");
      this.setToggleSideBar("Show");

  }
  clearHeadNav(): void {
    // clear messages
    this.baseService.clearHeadNav();
  }
  getHeadNav(): void
  {
    this.baseService.getHeadNav().subscribe((message:any) => {
      if (message) {
        this.checkHeadNav = message;
      } else {
        this.checkHeadNav = '';
      }
    });
  }
  setToggleSideBar(data:any): void
  {
    this.baseService.setToggleSideBar(data);
    if(data == "Show") {
      this.toggleValue = "Hide";
    }
    else if(data == "Hide")
    {
      this.toggleValue = "Show";
    }
  }
  getToggleSideBar(): void
  {
    this.baseService.getToggleSideBar().subscribe((message:any) => {
      if (message) {
        this.checkToggleBar = message;
      } else {
        this.checkToggleBar = '';
      }
    });
  }
  changePassword(){
    this.dialog.closeAll();
    sessionStorage.setItem('selectedModule','Change Password');
    this.router.navigate(['Attendance/ChangePassword'])
  }

  editProfile(){
    this.dialog.closeAll();
    sessionStorage.setItem('selectedModule','Edit Profile');
    this.router.navigate(['LeaveManagement/EditProfile']);
  }
  getLogo()
  {
    let info ={
      employeeId: 0,
      candidateId: null,
      filecategory: 'LOGO',
      moduleId: 2,
      requestId: null,
      status: 'Submitted',
    };
    this.mainService.getFilesMaster(info).subscribe((result) => {
      if(result && result.status &&  result.data[0]){
       result.data[0].employeeId=0;
       let info = result.data[0]
       this.mainService.getProfileImage(result.data[0]).subscribe((imageData) => {
        if(imageData.success){
          let TYPED_ARRAY = new Uint8Array(imageData.image.data);
          const STRING_CHAR = TYPED_ARRAY.reduce((data, byte)=> {
            return data + String.fromCharCode(byte);
          }, '');

          let base64String= btoa(STRING_CHAR)
          this.pic='data:image/png;base64,'+base64String;


        }
      else{
        // this.isRemoveImage=false;
        this.pic ="data:image/png;base64,";

      }
    })
  }else{
    // this.isRemoveImage=false;
    this.pic ="data:image/png;base64,";

  }
})

  }

  getUploadImage(){
    let info = {
      employeeId: this.usersession.id,
      candidateId: null,
      filecategory: 'PROFILE',
      moduleId: 1,
      requestId: null,
      status: 'Submitted',
    };
    this.mainService.getFilesMaster(info).subscribe((result) => {
      // if(result && result.status &&  result.data[0]){
      //  result.data[0].employeeId=this.usersession.id;
      //   let info = result.data[0]
      this.valid = false;
      if (result && result.status && result.data.length > 0) {

        for (let i = 0; i < result.data.length; i++) {
          if (result.data[i].file_category == 'PROFILE') {
            result.data[i].employeeId = this.usersession.id;
            this.infodata = result.data[i]
            this.valid = true;
            break;
          }
          else {
            this.imageurls = '';
          }
        }
        if (this.valid) {
          this.mainService.getProfileImage(result.data[0]).subscribe((imageData) => {
            if (imageData.success) {
              let TYPED_ARRAY = new Uint8Array(imageData.image.data);
              const STRING_CHAR = TYPED_ARRAY.reduce((data, byte) => {
                return data + String.fromCharCode(byte);
              }, '');

              let base64String = btoa(STRING_CHAR)
              this.imageurls = 'data:image/png;base64,' + base64String;
            
            }
            else {
              this.imageurls = '';

            }
          })
        } else {
          this.imageurls = '';

        }

      }
      else {
        this.imageurls = '';
      }
    })
  }
  getCompanyInformation(){
    this.LM.getCompanyInformation('companyinformation',null,1,10,this.companyDBName).subscribe((data:any)=>{
      if(data.status && data.data.length!=0) {
        this.companyName=data.data[0].companyname;
        sessionStorage.setItem("companyFullName", this.companyName);
      }else {
      }
    })

  }
  onClickSuperAdminDashboard() {
    this.router.navigate(['/main/MainDashboard']);
    sessionStorage.setItem('selectedModule',this.companyName );
    this.selectedModule =sessionStorage.getItem('selectedModule')??'';
  }

  isPopupOpen() {
    this.dialog.afterAllClosed.subscribe(() => {
      this.openDialogsCount = 0;
    });
    this.dialog.afterOpened.subscribe(() => {
      this.openDialogsCount++;
    });
    if(this.openDialogsCount)
      return true;
    else return false;
  }

  onClickFAQ() {
    this.router.navigate(['/main/FAQ']);
    sessionStorage.setItem('selectedModule','' );
    this.selectedModule =sessionStorage.getItem('selectedModule')??'';
  }
  onClickUserguide() {
    this.router.navigate(['/main/UserGuide']);
    sessionStorage.setItem('selectedModule','' );
    this.selectedModule =sessionStorage.getItem('selectedModule')??'';
  }

  onClickTicket() {
    this.router.navigate(['/main/raise_ticket']);
    sessionStorage.setItem('selectedModule','' );
    this.selectedModule =sessionStorage.getItem('selectedModule')??'';
  }

  calculateDaysUntilExpiry(expiryDate: string): any {
    const currentDate = new Date();
    const expDate = new Date(expiryDate);
    const diffInTime = expDate.getTime() - currentDate.getTime();
    const diffInDays = Math.ceil(diffInTime / (1000 * 3600 * 24));

    
     if (diffInDays === 0) {
      this.expiryAlert = true;
      return `Your subscription expires today. Please contact your Admin to maintain continuous service.`;
  
    } else if (diffInDays === 1) {
      this.expiryAlert = true;
      return `Your subscription expires tomorrow. Please contact your Admin to maintain continuous service.`;

    } else if (diffInDays < 8 ) {
      this.expiryAlert = true;
      return `Your subscription expires in ${diffInDays} days. Please contact your Admin to maintain continuous service.`;
    }
  }
}



