import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
@Component({
  selector: 'app-detailed-course-information',
  templateUrl: './detailed-course-information.component.html',
  styleUrls: ['./detailed-course-information.component.scss']
})
export class DetailedCourseInformationComponent implements OnInit {

  displayLearn: boolean = true;
  constructor(
    private router: Router,
  ) { }
  list: any = ['MySQL', 'MySQL-Intro', 'MySQL-features', 'Advantages', 'MySQL-Types', 'MySQL-Rules'];
  ngOnInit(): void {
  }
  Chapter() {
    this.displayLearn = true;
  }
  Excercise() {
    this.displayLearn = false;
  }
  navigationToPrevScreen() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/learning/chaptersList']));
  }
  navigateToTest() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/learning/testScreen']));
  }
}
