import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { LearnService } from '../../learn.service';



@Component({
  selector: 'app-lms-assessment',
  templateUrl: './lms-assessment.component.html',
  styleUrls: ['./lms-assessment.component.scss']
})



export class LmsAssessmentComponent implements OnInit {

  showQuestionNav = false;
  userSession: any

  currentQuestion: number = 0;
  sectionId!: number;
  showTimerButton: boolean = false;
  directionsVisible: boolean = false;
  showQuestionList: boolean = false;
  questions: any = [];
  isPassed: boolean | null = null;

  showResultPopup = false;
  reviewMode = false;
  // New state for result popup:
  showAnswers = false;
  answeredCount = 0;
  unansweredCount = 0;
  correctCount = 0;
  wrongCount = 0;
  userScore = 0;

  courseId!: number;       


  pointsPerQuestion = 2;
  submitting: boolean = false;
  private selectionsSaved: boolean = false;

  constructor(public router: Router, private route: ActivatedRoute, private learnService: LearnService) {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');

  }

  ngOnInit(): void {
    this.route.queryParams.subscribe(params => {
      const sectionId = params['section'];
      if (params['section']) {
              this.sectionId = +params['section'];
              this.courseId  = +params['course'];         
              this.loadQuestions(this.sectionId);
     }
        
    });


    this.learnService.getScoreconfig().subscribe((cfg: any[]) => {
      const pq = cfg.find(x => x.id === 4);
      if (pq) this.pointsPerQuestion = +pq.attribute_value;
    });



  }

  loadQuestions(sectionId: number): void {
    this.learnService.getQuestions(sectionId).subscribe({
      next: (data: any) => {
        this.questions = data.questions.map((q: any) => ({
          ...q,
          choices: this.parseOptions(q.options),
          imageUrls: q.image || [],
          selected: null,
          review: false,
          answered: false
        }));
      }
    });
  }

  parseOptions(optionsString: string): any[] {
    try {
      const parsed = JSON.parse(optionsString);
      return Object.entries(parsed).map(([letter, text]) => ({ letter, text }));
    } catch {
      return [];
    }
  }

  selectChoice(qIndex: number, cIndex: number): void {
    const q = this.questions[qIndex];
    q.selected = cIndex;
    q.answered = true;
  }

  markForReview(i: number) { this.questions[i].review = !this.questions[i].review; }
  navigateToQuestion(i: number) { this.currentQuestion = i; }

  Submit(): void {
    if (this.submitting) return;
    this.submitting = true;
    this.answeredCount   = this.questions.filter((q: { selected: null; }) => q.selected !== null).length;
    this.unansweredCount = this.questions.length - this.answeredCount;
    this.correctCount    = this.questions.filter((q: { selected: string | number | null; choices: { [x: string]: { letter: any; }; }; correct_answer: any; }) =>
      q.selected !== null &&
      q.choices[q.selected]?.letter === q.correct_answer
    ).length;
    this.wrongCount      = this.answeredCount - this.correctCount;
    this.userScore       = this.correctCount * this.pointsPerQuestion;

    // call backend
    const payload = {
      user_id:    this.userSession.id,
      section_id:        this.sectionId,                   // or pass sectionId
      acquired_points:   String(this.userScore),
      total_test_points: String(this.questions.length * this.pointsPerQuestion)
    };

    this.learnService.savePointsDetails(payload).subscribe({
      next: res => {
        this.isPassed         = res.is_passed === 1;
        this.showResultPopup  = true;
        // persist each answered question choice to backend
        this.saveSelectionsToBackend();
        this.submitting = false;
      },
      error: err => {
        console.error('Save points failed', err);
        // still show popup as failed
        this.isPassed         = false;
        this.showResultPopup  = true;
        // attempt to persist answers even if scoring failed
        this.saveSelectionsToBackend();
        this.submitting = false;
      }
    });
  }

  private saveSelectionsToBackend(): void {
    if (this.selectionsSaved) return;
    if (!this.questions || !this.questions.length) return;
    this.selectionsSaved = true;
    const sent = new Set<string|number>();
    this.questions.forEach((q: any) => {
      if (q.selected == null) return;
      const question_id = q.question_id ?? q.id ?? null;
      const selected_option = q.choices?.[q.selected]?.letter ?? null;
      if (!question_id || selected_option == null) return;
      if (sent.has(question_id)) return;
      sent.add(question_id);
      const payload = { question_id, selected_option };
      this.learnService.storeUserChoice(payload).subscribe({
        next: () => { /* saved */ },
        error: (err) => console.error('Failed to store user choice', err)
      });
    });
  }



  /** reset everything to let them retake */
  retakeTest(): void {
    this.showResultPopup = false;
    this.reviewMode      = false;
    this.isPassed        = null;
    this.questions.forEach((q: { selected: null; answered: boolean; review: boolean; }) => {
      q.selected = null;
      q.answered = false;
      q.review   = false;
    });
    this.currentQuestion = 0;
  }



  toggleShowAnswers() {
    this.showAnswers = !this.showAnswers;
  }

  

  closePopup(): void {
    this.showResultPopup = false;
    this.router.navigate(['/learning', 'LmsViewCourse', this.courseId]);
  }
  



  startReview(): void {
    this.showResultPopup = false;
    this.reviewMode = true;
    // jump back to the first question
    this.currentQuestion = 0;
  }



  previousQuestion(): void {
    if (this.currentQuestion > 0) {
      this.currentQuestion--;
    }
  }

  nextQuestion(): void {
    if (this.currentQuestion < this.questions.length - 1) {
      this.currentQuestion++;
    }
  }

  toggleQuestionNav(): void {
    this.showQuestionNav = !this.showQuestionNav;
  }



  toggleDirections() {
    this.directionsVisible = !this.directionsVisible;
  }




}
