export function noAllZerosValidator(): ValidatorFn {
  return (control: AbstractControl): ValidationErrors | null => {
    const value = control.value;
    if (value && /^0+$/.test(value)) {
      return { allZeros: true };
    }
    return null; // Valid
  };
}


