      this.dataSource.filter = selectedSearch.trim().toLowerCase();
      this.dataSource_pending.filter = selectedSearch.trim().toLowerCase();
      this.dataSource_progress.filter = selectedSearch.trim().toLowerCase();
      this.dataSource_paid.filter = selectedSearch.trim().toLowerCase();
      this.dataSource_rejected.filter = selectedSearch.trim().toLowerCase();
