validate_dupicates(bill_id:any){  
  let no_duplicate = '';
  let bill_date = this.datePipe.transform(this.billForm.controls.bill_date.value, 'yyyy-MM-dd') ;  
    this.bills.forEach((b:any) => {       
      console.log(b.bill_id , bill_id);
      if(b.bill_id != bill_id && no_duplicate == ''){         
        if(this.billForm.controls.bill_no.value.toString() == b.bill_no.toString() && bill_date == this.datePipe.transform(b.bill_date, 'dd-MM-yyyy')  && Number(this.billForm.controls.bill_amount.value) == Number(b.bill_amount))
          no_duplicate = 'Duplicate bills data not allowed';
        if(this.billForm.get('bill_image')?.value == b.bill_image && no_duplicate == '')
          no_duplicate = 'Duplicate bill image not allowed';
      }
    });
  return no_duplicate;
}

