  getReimbursementTypeName(id: number): string {
    const type = this.rbsData.find((item: { id: number; }) => item.id === id);
    return type ? type.rbs_type : 'Unknown';  // Return 'Unknown' if no match is found
  }

  // Function to delete a bill from the table
  deleteBill(index: number): void { 
    const message = this.translate.instant('DeleteBillMessage');
    const yesText = this.translate.instant('YES');
    const noText = this.translate.instant('NO');
     // Open a confirmation dialog
     let dialogRef = this.dialog.open(ComfirmationDialogComponent, {
      position: { top: `70px` }, disableClose: true,
      // data: { message: "Are you sure you want to delete this bill?", YES: 'YES', NO: 'No' }
      data: { message: message, YES: yesText, NO: noText }
    });
    dialogRef.afterClosed().subscribe(result => {
      console.log(result)
      if (result === yesText) {
        let bill = this.bills[index];
        let requestData = {
          claim_id :0,
          bill_id :bill.bill_id,
          rbs_type_id :bill.rbs_type,
          bill_no  :bill.bill_no.value,
          bill_date : this.datePipe.transform(bill.bill_date, 'yyyy-MM-dd'), 
          bill_amount:bill.bill_amount,
          file_name: bill.file_name,
          bill_image:bill.bill_image.split(',')[1],
          remarks: '',
          action_by:this.userSession.id,
          action_on: this.datePipe.transform(new Date(), 'yyyy-MM-dd HH:mm:ss'), 
          action_status: 'Deleted'
        }
    
        this.claims.setClaimRequestBill(requestData).subscribe((res:any)=>{
            if(res.status == true && res.data && res.data[0]){
              this.bills.splice(index, 1);
              this.bills = [...this.bills];
              this.calculateTotalRequestAmount();  // Recalculate the total after deletion
              this.bill_ids = this.bill_ids.filter((item:any) => item !== bill.bill_id);                 
            }
            else this.image_error = res.data && res.data[0] && res.data[0].resultmsg?res.data[0].resultmsg:'Found error';
          });
        }
    });
  }

