
import { Component, Inject, OnInit } from '@angular/core';
import { UntypedFormBuilder,UntypedFormArray, UntypedFormGroup, UntypedFormControl } from '@angular/forms';
import { MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';
import { CrmService } from '../../crm.service';
import { Router, RouterModule } from '@angular/router';
import { EmsService } from 'src/app/modules/ems/ems.service';

interface DynamicObject {
  [key: string]: any;
}
 
@Component({
  selector: 'app-crm-rptcolumns-popup',
  templateUrl: './crm-rptcolumns-popup.component.html',
  styleUrls: ['./crm-rptcolumns-popup.component.scss']
})
 
export class CrmRptcolumnsPopupComponent implements OnInit {
  // columns:any = [
  //   // { id: 1, name: 'Employee Status',keyname:'employee_status_value' },
  //   // { id: 2, name: 'Employee Type',keyname:'employee_type' },
  // ];
  columns:any = [];
  dynamicArr: number[] = [];
  userSession:any;
  route_name:any;
  report_name:any;
 
  get earningsFormArray() {
    return this.reportpopupForm.controls.earnings as UntypedFormArray;
  }
  reportpopupForm:any= UntypedFormGroup;
  status!:boolean;
  data:any=[];
  isindeterminate:boolean=false;
  ischecked:boolean=false;
  constructor(
    public dialogRef: MatDialogRef<CrmRptcolumnsPopupComponent>,
    private crm:CrmService,
    private ES:EmsService,
    @Inject(MAT_DIALOG_DATA) public injectedData: any,
    private router: Router,
    private formBuilder: UntypedFormBuilder) {
      this.columns = this.injectedData?(this.injectedData.columns??[]):[];
      this.route_name = this.injectedData?(this.injectedData.route??''):'';
      this.report_name = this.injectedData?(this.injectedData.report_name??''):'';
      this.reportpopupForm=this.formBuilder.group({
        check:[],
        earnings: new UntypedFormArray([]),
      });
      this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
      this.addCheckboxes();
      
  }
  onNoClick(): void {
    this.dialogRef.close();
  }

  private addCheckboxes() {
    this.earningsFormArray.reset();
    this.columns.forEach(() => this.earningsFormArray.push(new UntypedFormControl(false)));
  }
  /**This function used for select all functionality. */
  onChange($event:any){
    this.dynamicArr = [];
    if($event.checked){
      this.columns.forEach(() =>{
        this.dynamicArr.push(Number(1));
      });
      this.earningsFormArray.setValue(this.dynamicArr);
      this.isindeterminate = false;
      this.ischecked =true
    }
    else{
      this.columns.forEach(() => {
        this.dynamicArr.push(Number(0));
      });
      this.earningsFormArray.setValue(this.dynamicArr);
      this.isindeterminate = false;
      this.ischecked =false
    }
 }

  ngOnInit() {
    this.getFunction();
  }

 getFunction(){
 
  if(this.report_name.toLowerCase() === 'client report'){
    this.getClientReportColumns();
  }
 }

 getClientReportColumns(){
  this.ischecked = true;
  this.isindeterminate = false;
    this.crm.getCrmClientReportColumnConfigures({empid:this.userSession.id}).subscribe((result:any)=>{
    this.data = result.data;
    if(result.data && result.data[0] && result.data[0].configurations){
        let arr = JSON.parse(JSON.stringify(result.data[0].configurations)).split(',');
        this.dynamicArr = [];
        var count = 0,setval='';
        this.earningsFormArray.reset();
        arr.forEach((val:number)=>{
          count = Number(count) + Number(val);
          this.dynamicArr.push(Number(val));
          setval = setval +(setval.toString().length?',':'')+val.toString();
        });

        this.earningsFormArray.setValue(this.dynamicArr);
        this.ischecked = (count === arr.length)?true:false;
        this.isindeterminate = (arr.length-count>0)?true:false;
        this.reportpopupForm.controls.check.setValue(this.ischecked);
      }
  })
 }

 

  save(){    
    const earningselectedIds = this.reportpopupForm.value.earnings
      .map((checked:any, i:any) => checked ? 1 : 0)
      .filter((v:any) => v !== null);
    var dynamicArray: DynamicObject[] = [{ empid:this.userSession.id }];
    this.columns.forEach((col:any)=>{
      dynamicArray[0][col.keyname.toString()]= (earningselectedIds[col.id]);
    });
    
   
    if(this.report_name.toLowerCase() === 'client report'){
      this.setClientReportColumns(dynamicArray[0]);
      this.dialogRef.close({closed:true});
    }
  }

  setClientReportColumns(data:any){
    this.crm.setCrmClientReportColumnConfiguration(data).subscribe((res:any)=>{
      if(res.status){
          this.router.navigate([this.route_name]);
      }
    })
  }
   
}
