  clearfamily() {
    // this.candidateFamilyForm.controls.familyfirstname.setValue('');
    // this.candidateFamilyForm.controls.relation.setValue('');
    // this.candidateFamilyForm.controls.familycontact.setValue('');
    // this.candidateFamilyForm.controls.familygender.setValue('');
    // this.isfamilyedit = false;
    //this.candidateFamilyForm.valid = true;

    this.candidateFamilyForm.patchValue({
      familyfirstname: '',
      familycontact: '',
      familygender: null,
      relation: null,
      familystatus: null
    });

    // Reset validation states
    this.candidateFamilyForm.markAsPristine();
    this.candidateFamilyForm.markAsUntouched();

    // Make controls valid without emitting events
    Object.keys(this.candidateFamilyForm.controls).forEach(key => {
      const control = this.candidateFamilyForm.candidateFamilyForm.patchValue({
        familyfirstname: '',
        relation: '',
        familycontact: '',
        familygender: '',
      });
      this.candidateFamilyForm.markAsPristine();
      this.candidateFamilyForm.markAsUntouched();
      this.candidateFamilyForm.updateValueAndValidity({ emitEvent: false });
      this.candidateFamilyForm.get(key);
      control.setErrors(null);
    });

    this.candidateFamilyForm.updateValueAndValidity({ emitEvent: false });
    this.isfamilyedit = false;
  }

