filterSection(event: any) {
  const value = event.target.value.toLowerCase().trim();

  if (!value) {
    this.section = [...this.filteredSections];
    return;
  }

  this.section = this.filteredSections.filter((sec: any) =>
    sec.section_name.toLowerCase().includes(value)
  );
}


  addNew(item: any) {
    let department = this.personalInfoForm.controls.department.value;
    if (this.ismappingEnable == true) {
      if (department == '') {
        let dialogRef = this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: 'Please select department.',
        });
        return;
      }
    } else {
      department = 1
    }
    const dialogRef = this.dialog.open(AddNewDialogComponent, {
      width: '800px',
      position: { top: `70px` },
      data: { 'addTo': item, 'ismappingEnable': this.ismappingEnable, 'departmentid': department },
    });
    dialogRef.afterClosed().subscribe((result) => {
      if (result === 'Designation') {
        this.getAvailableDesignations();
      } else if (result === 'Department') {
        this.getDepartmentsMaster();
      }
    });
  }
  getDesignationDepartmentMappingEnabledFlag() {
    this.companyService
      .getDesignationDepartmentMappingEnabledFlag()
      .subscribe((data: any) => {
        this.mappingValue = data.data[0].value;

        if (this.mappingValue == 0) {
          this.ismappingEnable = false;
        } else if (this.mappingValue == 1) {
          this.ismappingEnable = true;
        }
        this.getAvailableDesignations();
      });
  }

  getMappedDesignations() {
    this.section= [];
    this.sectionflag ? this.getSectionsForDepartment(this.personalInfoForm.controls.department.value) : [];
    if (this.ismappingEnable) {
      this.personalInfoForm.controls.designation.setValue('')
      this.getAvailableDesignations();
     
    }
  }

  filterRole(searchText: any) {
    this.filteredAddtionalRoles = this.additionalRoles.filter(
      (val: any) =>
        val.name.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredAddtionalRoles.length <= 0) {
      this.searchControlforAddRole.setValue('');
    }
  }
    getSectionsForDepartment(deptId:any){
      this.section = [];
      this.emsService.getSectionsForDepartment(deptId).subscribe((data: any) => {
        if (data.status && data.data.length != 0) {
          this.section =  data.data;
          this.filteredSections = data.data;    
           this.section = [...this.filteredSections];
        }
      });
  }
     validateAletterDownload() {
    this.emsService.validateAletterDownload(this.loginEmpId).subscribe((res: any) => {

      if (res.status) {
        if (res.data[0].statuscode == 1) {
          const dialogRef = this.dialog.open(AppointmentLetterDialogComponent, {
            width: '800px',
            position: { top: `70px` },
            data: { employeeInfo: this.employeeInformationData, noticePeriod: this.noticePeriod }
          });
        } else {
          let dialogRef = this.dialog.open(ReusableDialogComponent, {
            position: { top: `70px` },
            disableClose: true,
            data: res.data[0].message
          });
          return;
        }
      }
    })
  }

