import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';

type CourseType = 'trending' | 'enrolled' | 'assigned' | 'recommended' | 'popular';

@Component({
  selector: 'app-employee-dashboard',
  templateUrl: './employee-dashboard.component.html',
  styleUrls: ['./employee-dashboard.component.scss']
})
export class EmployeeDashboardComponent implements OnInit {

  trendingDisplayCourseNames = ['React Js', 'Angular', 'NodeJS', 'Java', 'SQL', 'Python']
  enrolledCourses = ['Full Stack Java', 'React', 'Angular', 'Node Js', 'Python', 'SQL']
  assignedCourses = ['Full Stack Java', 'React', 'Angular', 'Node Js']
  recommendedCourses = ['Vue.js', 'TypeScript', 'MongoDB', 'Express.js', 'Docker']
  popularCourses = ['JavaScript', 'Python', 'Java', 'C++', 'Go', 'Rust']

  currentIndex: Record<CourseType, number> = {
    trending: 0,
    enrolled: 0,
    assigned: 0,
    recommended: 0,
    popular: 0
  }

  itemsPerView = 4

  constructor(
    private router: Router,
  ) { }

  ngOnInit(): void {
  }

  navigationToCourselist() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/learning/courseList']));
  }

  navigateCourses(direction: 'left' | 'right', courseType: CourseType) {
    const courses = this.getCoursesByType(courseType)
    const maxIndex = Math.max(0, courses.length - this.itemsPerView)
    
    if (direction === 'left') {
      this.currentIndex[courseType] = Math.max(0, this.currentIndex[courseType] - 1)
    } else {
      this.currentIndex[courseType] = Math.min(maxIndex, this.currentIndex[courseType] + 1)
    }
  }

  getCoursesByType(type: CourseType): string[] {
    switch(type) {
      case 'trending': return this.trendingDisplayCourseNames
      case 'enrolled': return this.enrolledCourses
      case 'assigned': return this.assignedCourses
      case 'recommended': return this.recommendedCourses
      case 'popular': return this.popularCourses
      default: return []
    }
  }

  getVisibleCourses(courseType: CourseType): string[] {
    const courses = this.getCoursesByType(courseType)
    const start = this.currentIndex[courseType]
    return courses.slice(start, start + this.itemsPerView)
  }

  isLeftDisabled(courseType: CourseType): boolean {
    return this.currentIndex[courseType] === 0
  }

  isRightDisabled(courseType: CourseType): boolean {
    const courses = this.getCoursesByType(courseType)
    // Only disable if we can't scroll right (at the end)
    return courses.length <= this.itemsPerView || this.currentIndex[courseType] >= courses.length - this.itemsPerView
  }
}
