  private refreshSummaryTable() {
    this.summaryDataSource._updateChangeSubscription();

    setTimeout(() => {
      if (this.summaryPaginator) {
        this.summaryDataSource.paginator = this.summaryPaginator;
      }
    });
  }

  fetchSummaryReport() {
    const filters = {
      role: this.summaryFilters.role || '',
      course_name: this.summaryFilters.course_name || '',
      status: this.summaryFilters.status || '',
      instructor_id: this.summaryFilters.instructor_id
      ? Number(this.summaryFilters.instructor_id)
      : 0, // ✅ ADD
      empid: this.userSession.id,
      date_from: this.formatLocalDate(this.summaryFilters.date_from) || '',
      date_to: this.formatLocalDate(this.summaryFilters.date_to) || ''
    };

    if (this.router.url.includes('LmsInstructorReports')) {

      this.learn.getInstructorSummaryReports(filters).subscribe(res => {
        this.summaryDataSource.data = res.data || [];
        this.refreshSummaryTable();
      });

    } else if (this.router.url.includes('LmsHRManagerReports')) {

      // 🔥 HR API
      this.learn.getHRSummaryReports(filters).subscribe(res => {
        this.summaryDataSource.data = res.data || [];
        this.refreshSummaryTable();
      });

    } else {

      this.learn.getManagerSummaryReports(filters).subscribe(res => {
        this.summaryDataSource.data = res.data || [];
        this.refreshSummaryTable();
      });

    }
  }

