  loadManagersByBranch(): void {
  if (!this.selectedDepartmentIds.length || !this.selectedBranchIds.length) return;

  this.learn
    .getManagersbyDept(this.selectedDepartmentIds, this.selectedBranchIds)  // ← pass array
    .subscribe((m) => {
      this.managers = m;
      this.selectedManagerIds = this.managers.map(x => x.manager_id);

      this.learn.getEmployeesbyManager(this.selectedManagerIds, null).subscribe((arrays) => {
        const flat = ([] as any[]).concat(...arrays);
        this.employees = Array.from(
          new Map(flat.map(e => [e.employee_id, e])).values()
        );
        this.selectedEmployeeIds = this.employees.map(x => x.employee_id);
      });
    });
}

