  /**
   * Format a date as local YYYY-MM-DD (supports Date and Moment)
   */
  private formatLocalDate(d: Date | any): string | null {
    if (!d) return null;
    // Moment object
    if (d._isAMomentObject && typeof d.format === 'function') {
      return d.format('YYYY-MM-DD');
    }
    const dt: Date = d as Date;
    const yyyy = dt.getFullYear();
    const mm = ('0' + (dt.getMonth() + 1)).slice(-2);
    const dd = ('0' + dt.getDate()).slice(-2);
    return `${yyyy}-${mm}-${dd}`;
  }

  /** Download current table as CSV */
  downloadDetailedExcel(): void {
  const rows = this.dataSource.data;

  if (!rows.length) {
    alert('No data to download!');
    return;
  }

  const data = rows.map((r: any) => ({
    Employee: r.employee_name,
    Enrolled: r.enrolled_count,
    'Not Enrolled': r.not_enrolled_count,
    Completed: r.completed_count,
    'Not Completed': r.not_completed_count,
    'Enrolled Courses': r.enrolled_course_names,
    'Completed Courses': r.completed_course_names,
    Points: r.total_acquired_points,
    Badges: r.total_earned_badges,
    Certificates: r.total_earned_certificates
  }));

  const worksheet = XLSX.utils.json_to_sheet(data);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, 'Detailed Report');

  const excelBuffer = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });
  const blob = new Blob([excelBuffer], { type: 'application/octet-stream' });

  saveAs(blob, 'Detailed_Report.xlsx');
}

