  exportAsXLSX() {
  if (!this.table || !this.table.nativeElement) {
    console.error("Table element not found!");
    return;
  }

  const element = this.table.nativeElement.querySelector('table');

  if (!element) {
    console.error("No <table> element found inside #table wrapper!");
    return;
  }

  const ws: XLSX.WorkSheet = XLSX.utils.table_to_sheet(element);
  const wb: XLSX.WorkBook = XLSX.utils.book_new();

  XLSX.utils.book_append_sheet(wb, ws, 'Leave_Balance_Report');
  XLSX.writeFile(wb, 'Leave_Balance_Report.xlsx');
}


