  Searchform() {
    if (this.searchForm.valid) {
      this.List = [];
      this.dataSource = new MatTableDataSource(this.List);
      let userId = this.searchForm.controls.Users.value == '0'?null: this.searchForm.controls.Users.value;
      let data = { 
            'manager_employee_id':userId?null:JSON.stringify(this.selectedManagers),
            'location_id': JSON.stringify(this.selectedLocations),
            'employee_id': userId        
          };

      this.spinner.show();
      this.isLoading = true;
     this.payrollService.getSelectedEmployeesLeaveBalanceReport(data).subscribe((res: any) => {
       this.spinner.hide();
        this.isLoading = false;
         this.List = res.data;
          this.headersList = Object.keys(res.data[0]);
          this.headersList = this.headersList.filter((key:any) => key !== 'Employee Id'); 
       // this.dataSource = new MatTableDataSource(this.List);       
      }, error => {       
        error.error.text;
      });
    }
  }

  getColVal(a:any){
      return a.replace(/_/g, ' ');
  }
