import { DatePipe } from '@angular/common';
import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { FormControl, UntypedFormBuilder, UntypedFormGroup, Validators } from '@angular/forms';
import { MatDialog } from '@angular/material/dialog';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { Router } from '@angular/router';
import { ReportsService } from 'src/app/modules/reports/reports.service';
import { AdminService } from '../../admin.service';
import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';
import { CompanySettingService } from 'src/app/services/companysetting.service';

@Component({
  selector: 'app-mapping-ids',
  templateUrl: './mapping-ids.component.html',
  styleUrls: ['./mapping-ids.component.scss']
})

export class MappingIdsComponent implements OnInit {

  searchControl = new FormControl('');
  searchControlWorkLocation = new FormControl('');
  mappingIdsForm!: UntypedFormGroup;
  pipe = new DatePipe('en-US');
  todayWithPipe: any;
  displayedColumns: string[] = ['sno', 'biometricid', 'empid', 'empname','contactnumber','aadharnumber',"worklocationname"];
  dataSource: MatTableDataSource<any> = <any>[];
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  arrayList: any = [];
  workTypeData: any;
  userSession: any;
  pageLoading = true;
  isAdd: boolean = false;
  isdata: boolean = true;
  noData:boolean=false;
  @ViewChild('searchInput') searchInput!: ElementRef;
  constructor(private formBuilder: UntypedFormBuilder, private adminService: AdminService,
     private LMS: CompanySettingService,
    public dialog: MatDialog, public datePipe: DatePipe, private router: Router, 
    public reportsService: ReportsService,private dialogService:ReusableDialogService,
  ) {

  }
  workLocationList: any = []
  folteredLocations: any = []
  employeelist: any=[];
  filteredEmp:any=[];
  ngOnInit(): void {

    this.mappingIdsForm = this.formBuilder.group(
      { locationid: ['', Validators.required],
        biometricid: ['', Validators.required],
        empid: ['', Validators.required],
      });
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    this.getWorkLocation();
    this.getMappingIdsList();
    this.searchControl.valueChanges.subscribe((searchText: any) => {
      this.filterEmp(searchText);
    })
      this.searchControlWorkLocation.valueChanges.subscribe((searchControlWorkLocation: any) => {
      this.filterWorkLocation(searchControlWorkLocation);
    })
    this.mappingIdsForm.valueChanges.subscribe((location: any) => {
       console.log(location.locationid);
       this.getEmployeelist(location.locationid);
    });
   
  }
   getWorkLocation() {   
    this.LMS.getactiveWorkLocation({ id: null }).subscribe((result) => {
      if (result && result.data && result.data.length > 0) {
        this.workLocationList = result.data;    
        this.folteredLocations = this.workLocationList;
      }
    })
  }
    filterWorkLocation(searchControlWorkLocation: any) {
    this.folteredLocations = this.workLocationList.filter((val: any) =>
      val.location.toLowerCase().includes(searchControlWorkLocation.toLowerCase())
    );
    if (this.folteredLocations.length == 0){
      this.noData=true;
    }else{
      this.noData=false;
    }
  }
  Add() {
    this.isAdd = true;
    this.isdata = false;
  }

  getEmployeelist(locationid:any) {
    this.reportsService.getActiveEmployeesListForBiometricMapping(locationid).subscribe((res: any) => {
      if (res.status) {
        this.employeelist = [];
        this.employeelist = res.data;
        this.filteredEmp = this.employeelist

      }

    });
  }
  getMappingIdsList() {
    this.arrayList = [];
    let obj = {
      "boon_emp_id": null,
      "biometric_id": null,
    };
    this.adminService.getIntegrationEmpidsLookup(obj).subscribe((res: any) => {
      if (res.status) {
        this.arrayList = res.data;
        this.dataSource = new MatTableDataSource(this.arrayList);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading=false;
      } else {
        this.arrayList = [];
        this.dataSource = new MatTableDataSource(this.arrayList);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
      }
    })
  };
  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();

    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }
  
  saveMappingIds() {
    if (this.mappingIdsForm.invalid) {
      return;
    } else {
      if (this.arrayList.length > 0) {
     let index = this.arrayList.findIndex((e:any) => e.deviceempid === parseInt(this.mappingIdsForm.controls.biometricid.value) 
          ||  e.boonempid === this.mappingIdsForm.controls.empid.value);
         if(index >= 0){
          this.dialogService.openDialog('Already mapped the selected employee or bio-metric id');

        }else{
          let obj = {
            "boon_emp_id": this.mappingIdsForm.controls.empid.value,
            "biometric_id": this.mappingIdsForm.controls.biometricid.value,
          };
  
          this.adminService.setIntegrationEmpidsLookup(obj).subscribe((res: any) => {
          if (res.status) {
            this.dialogService.openDialog(res.message);
            this.resetform();
          }else{
            this.dialogService.openDialog(res.message);
          }
          })
         }
      }
      else{
        let obj = {
          "boon_emp_id": this.mappingIdsForm.controls.empid.value,
          "biometric_id": this.mappingIdsForm.controls.biometricid.value,
        };

        this.adminService.setIntegrationEmpidsLookup(obj).subscribe((res: any) => {
          this.dialogService.openDialog(res.message);
          if (res.status) {
            this.dialogService.openDialog(res.message);
            this.resetform();
          }else{
            this.dialogService.openDialog(res.message);
          }
        })
      }
    }
  }

  resetform() {

    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Admin/MappingIds"]));
  }

  getPageSizes(): number[] {
    var customPageSizeArray = [];
    
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
     
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  filterEmp(searchText: any) {
    this.filteredEmp = this.employeelist.filter((val: any) =>
      val.emp_name.toLowerCase().includes(searchText.toLowerCase()) 
     || val.empid.toLowerCase().includes(searchText.toLowerCase())
     || val.contactnumber.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredEmp.length == 0){
      this.noData=true;
    }else{
      this.noData=false;
    }
  }
  onDropdownOpen(isOpen: boolean) {
    if (isOpen) {
      setTimeout(() => {
        this.searchInput.nativeElement.focus(); // Focus the input field
      });
    }
  }
}
