  exportAsXLSX() {
    // if (this.messageflag) {
    if (true) {
      // this.year = this.searchForm.controls.fromDate.value.getFullYear();
      this.year = this.date.value._d.getFullYear();
      for (let i = 0; i < this.months.length; i++) {
        // if ((this.searchForm.controls.fromDate.value).getMonth() == this.months[i].id) {
        if (this.date.value._d.getMonth() == this.months[i].id) {
          this.monthdata = this.months[i].month;
          break;
        }
      }
      const headerKeys = [
        'sno', 'UAN','empid' ,'Employee_Name','location','deptname',...(this.sectionflag ? ['section_name'] : []), 'pfaccountnumber', 'gross_salary',
         'employee_epf_wage', 'employee_epf_value', 'eps_wage',  'employer_eps_value',
        'edli_wage', 'epf_eps_difference', 'ncp_days', 'refunds', 'cost_center_name', 'employer_bank', 'employer_ifsc', 'employer_account'
      ];
      const headerMap: { [key: string]: string } = {
        'sno': 'S.No',
        'UAN': 'UAN No.',
        'empid': 'EmpCode',
        'Employee_Name': 'Emp. Name',
        'location':'Location',
        'deptname':'Department',
        ...(this.sectionflag ? { section_name: 'Section' } : {}),
        'pfaccountnumber': 'PF Acc.No.',
        'gross_salary': 'Gross',
        'employee_epf_value': ' EPF ', //Employee PF Value
        'eps_wage': ' EPS ', // Employer PS Wage
        'edli_wage': ' EDLI ',
        'employer_eps_value': ' EPS ', //Employer PS Value
        'employee_epf_wage': ' EPF ',   //Employee PF Wage
        'epf_eps_difference': ' EPF ',
        // 'er': ' EPF ',
        'ncp_days': 'NCP ',
        'refunds': 'Refunds',
        'cost_center_name': 'Cost center',
        'employer_bank': 'Employer Bank Name',
        'employer_ifsc': 'Employer IFSC Code',
        'employer_account': 'Employer Account Number'
      };

      // --- Step 3: Extract and Prepare Data ---
      // Ensure the reportData exists and has the IFSC field.
      const exportData = this.List.map((row: any, index:number) => {
        const newRow: any = {};
        // Iterate over the defined keys to select and map data
        headerKeys.forEach(key => {
          if (key === 'sno') {
           newRow[key] = index + 1;  // Generate S.NO
          }else if (key === 'refunds') {
          newRow[key] = "0";   // Because refunds is hardcoded in UI
         } else {
            newRow[key] = row[key];
          }
        //   newRow[key] = row[key]; // Copy the required data value
        });
        return newRow;
      });

      // --- Step 4: Generate Worksheet from JSON Data ---
      // Use json_to_sheet, specifying the order and custom headers.
      var ws: XLSX.WorkSheet = XLSX.utils.json_to_sheet(exportData, {
        header: headerKeys, // Specifies the order of columns
        skipHeader: false // Includes the header row
      });

      // --- Step 5: Apply Custom Headers (Optional but recommended) ---
      // Loop through the first row (headers) and replace keys with titles from headerMap.
      const range = XLSX.utils.decode_range(ws['!ref'] || 'A1:A1');
      for (let C = range.s.c; C <= range.e.c; ++C) {
        const cellRef = XLSX.utils.encode_cell({ r: range.s.r, c: C }); // r=0, first row
        const cell = ws[cellRef];
        if (cell && cell.v) {
          // The cell.v holds the key from headerKeys (e.g., 'emp_id').
          // Replace it with the friendly name (e.g., 'Employee ID').
          const key = cell.v;
          cell.v = headerMap[key] || key;
        }
      }
    Object.keys(ws).forEach(cellRef => {
      if (cellRef[0] === '!') return;
      const cell = ws[cellRef];
      if (!cell || cell.v == null) return;
      cell.t = 's';
      cell.z = '@';               // text format
      cell.v = String(cell.v);    //  string
      });

      // --- Step 6: Export the file ---
      const wb: XLSX.WorkBook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, 'EPF_challan_report');

      /* save to file */
      XLSX.writeFile(wb, 'epf_report_for_financeteam_' + this.monthdata + '_' + this.year + '.xlsx');
    }
    else {
      let dialogRef = this.dialog.open(ReusableDialogComponent, {
        position: { top: `70px` },
        disableClose: true,
        data: this.message
      });
    }
  }

