  validation(data: any) {
    this.successRoute = null
    if (data.nav) {
      this.successRoute = this.activeModule.module.menu_items.filter((ele: any) => { return ele.screenid == data.nav })
    }

    let dialogRef1 = this.dialog.open(TdsDialogsComponent, {
      position: { top: `50px` },
      disableClose: true,
      data: { message: data.tds_message, flag: true }
    });

    dialogRef1.afterClosed().subscribe((result: any) => {
      if (result && data.nav) {

        if (this.successRoute) {
          sessionStorage.setItem('activeChild', JSON.stringify(this.successRoute[0]));
        }
        this.router
          .navigateByUrl('/', { skipLocationChange: true })
          .then(() => this.router.navigate(['/Payroll/configureTaxRegime']));
      }

    })
  }

