  fileNameError: boolean = true;

  onSelectFile(event: any, ele: any) {
    const input = event.target as HTMLInputElement;
    if (input.files && input.files[0]) {
      const file = input.files[0];
      if (file) {
        const maxSize = 5 * 1024 * 1024; // 5 MB in bytes
        this.filesize = true;
        this.fileNameError = true;
        const allowedExtensions = ['jpg', 'png', 'pdf', 'jpeg'];
        const fileExtension = file.name.split('.').pop()?.toLowerCase();
        if (!fileExtension || !allowedExtensions.includes(fileExtension)) {
          this.selectedFile = null
          this.tdsService.showSnackBar('Invalid file type. Please upload only .jpg, .png,.jpeg or .pdf files.', true)
          setTimeout(() => { input.value = '' }, 1000)
          ele.document = null
          return;
        }
        if (file.size > maxSize) {
          this.tdsService.showSnackBar('File size must not exceed 5 MB. reduce size and re-upload file', true)
          this.filesize = false;
          this.selectedFile = null
          setTimeout(() => { input.value = '' }, 1000)
          ele.document = null
          return
        } if (file.name.length > 90) {
          this.tdsService.showSnackBar('File name must not exceed 90 characters.reduce name and re-upload file', true)
          this.fileNameError = false;
          this.selectedFile = null
          setTimeout(() => { input.value = '' }, 1000)
          ele.document = null
          return
        } else {
          this.selectedFile = file
          ele.document = file.name

        }
      }
    }
  }

