  validateDates(declarationOpenDate: any, declarationClosureDate: any, proofUploadOpenDate: any, proofUploadClosureDate: any, isUploadFile: boolean = false, onclick: boolean = false, records: boolean = true) {
    return new Promise((resolve: any) => {
      if (!isUploadFile) {
        if (!declarationOpenDate) { //dates not declared 
          this.message("The tax exemption declaration window is not yet declared. Please proceed with declarations once the window is declared.")
          resolve(false)
        } else if (declarationOpenDate && moment().startOf('day').toDate() < moment(declarationOpenDate).startOf('day').toDate()) { //dates declared but not opened
          this.message("The tax exemption declaration window is not yet opened. Please proceed with declarations once the window is opened.");
          resolve(false)
        }
        else if (moment().startOf('day').toDate() > moment(declarationClosureDate).startOf('day').toDate()) { //dates closed 
          // this.message("The tax exemption declaration window is closed. Please contact your Finance Manager to proceed with declarations.", true);
          this.isDeclarationDatesClosed = true;
          resolve(false)
        }
      }
      else {
        if (!proofUploadOpenDate) { //proof uploaded dates not declared 
          this.message("The tax exemption proof upload window is not yet declared. Please proceed with uploading the proofs once the window is declared.", true);
          resolve(false)
        }
        else if (proofUploadOpenDate && moment().startOf('day').toDate() < moment(proofUploadOpenDate).startOf('day').toDate()) {//proof uploaded declared but not open
          this.message("The tax exemption proof upload window is not yet opened. Please proceed with uploading proofs once the window is opened.", true);
          resolve(false)
        }
        // else if( proofUploadOpenDate && new Date() > new Date(proofUploadClosureDate)){ //proof uploaded dates closed 
        //   this.message("The tax exemption proof upload window is closed. Please contact your Finance Manager to proceed with uploading proofs.");
        //   return;
        // }
      }
      resolve(true)
    })

  }


