  async onChangeResetRemainingFields(rowData: any, columns: any, keyField: any) {
    let allColumn = JSON.parse(JSON.stringify(columns))
    let index = allColumn.findIndex((item: any) => item == keyField)
    if (index !== -1) {
      allColumn.splice(0, index + 1); // Remove elements before the found index
      for (let i = 0; i < allColumn.length; i++) {
        await new Promise((resolve: any) => {
          setTimeout(() => {
            rowData[allColumn[i].toString()] = null;
            if (allColumn[i].toString() === 'document') {
              rowData.documentName = null;
            }
            resolve('done');
          }, 1)
        })
      }
    }
  }

  validationsAllValues(ele: any, columns: any = [], keyField: any) {
    return new Promise((resolve: any) => {
      let allColumn = JSON.parse(JSON.stringify(columns))
      allColumn.shift();
      let index = allColumn.findIndex((item: any) => item == keyField)
      if (index !== -1) {
        allColumn.splice(index, allColumn.length - index + 1); // Remove elements before the found index
      }
      for (let a = 0; a < allColumn.length; a++) {
        // if (a != 0 && a != allColumn.length - 1) {
        if (!ele[allColumn[a].toString()]) {
          let message = allColumn[a] == 'amount' ? 'Please Enter ' : allColumn[a] == 'age' ? 'Please Enter ' : allColumn[a] == 'disability' ? 'Please Enter ' : 'Please Select '
          this.tdsService.showSnackBar(message + allColumn[a].replace(/([a-z])([A-Z])/g, '$1 $2')
            .replace(/([A-Z])([A-Z][a-z])/g, '$1 $2')
            .replace(/^./, (str: any) => str.toUpperCase()), true)
          resolve(false);
          return
        }
        // }
      }
      resolve(true);
    })
  }

