  async finalSubmitValidation() {
    let isDeclared = await this.checkAnyRecordsSubmittedForFirstGroup()
    if (!isDeclared) {
      isDeclared = await this.checkAnyRecordsSubmittedForSecondGroup()
    }
    if (!isDeclared) {
      let dialogRef1 = this.dialog.open(TdsDialogsComponent, {
        position: { top: `50px` },
        disableClose: true,
        data: { regimeFlag: true, message: 'Are you sure you want to Final Submit without declaring any exemption? You will not be able to add, edit or delete tax exemptions, house properties, house rents or previous company payments for this financial year once you hit the Final Submit button.' }
      });
      dialogRef1.afterClosed().subscribe((result: any) => {
        if (result) {
          this.finalSubmit()
        }
      })
    } else {
      let dialogRef1 = this.dialog.open(TdsDialogsComponent, {
        position: { top: `50px` },
        disableClose: true,
        data: { regimeFlag: true, message: 'Are you sure you want to hit the Final Submit button? You will not be able to add, edit or delete tax exemptions, house properties, house rents or previous company payments for this financial year once you hit the Final Submit button.' }
      });
      dialogRef1.afterClosed().subscribe((result: any) => {
        if (result) {
          this.finalSubmit()
        }
      })
    }
  }


  finalSubmit() {
    let input = {
      employeeId: this.userSession.id,
      financialYear: this.financialYear
    }
    if (this.isNewEmployee) {
      this.tdsService.calculateTdsAmountsForNewEmployee(input).subscribe((results: any) => {
        if (results && results.status) {
          this.getFinalSubmitStatus();
          this.tdsService.message('Your Final Submit for TDS exemption declarations is submitted successfully. Your TDS deductions will commence when the deduction cycle starts.')
        } else {
          this.tdsService.message('Please try again later.')
        }
      })
    } else {
      this.tdsService.calculateTdsAmountsForEmployee(input).subscribe((results: any) => {
        if (results && results.status) {
          this.getFinalSubmitStatus();
          this.tdsService.message('Your Final Submit for TDS exemption declarations is submitted successfully. Your TDS deductions will commence when the deduction cycle starts.')
        } else {
          this.tdsService.message('Please try again later.')
        }
      })
    }

  }



  checkAnyRecordsSubmittedForFirstGroup() {
    return new Promise((resolve: any) => {
      for (let i = 0; i < this.groupSections.length; i++) {
        if (this.groupSections[i].records && this.groupSections[i].records.length) {
          resolve(true)
          return
        }
      }
      resolve(false)
    })

  }
  checkAnyRecordsSubmittedForSecondGroup() {
    return new Promise((resolve: any) => {

      for (let i = 0; i < this.FirstGroupSections.length; i++) {
        if (this.FirstGroupSections[i].records && this.FirstGroupSections[i].records.length) {
          resolve(true)
          return
        }
      }
      resolve(false)
    })
  }



  afterAgeEnter(ele: any) {

    if (this.subArray.length > 1) {
      let sameValue = false;
      for (let a = 0; a < this.subArray.length; a++) {
        if (this.subArray[a].relationship == ele.relationship && this.subArray[a].age != ele.age) {
          sameValue = true;
        }
      }
      if (sameValue) {
        this.tdsService.showSnackBar('The age entered for the selected relationship does not match with that in the previous submissions.', true)
        setTimeout(() => { ele.age = null }, 100);
        return
      }
    }
    this.ageDisabilityValidation(ele)
  }

  afterDisabilityEnter(ele: any) {

    if (ele.disability < this.section80ddDetails[0].minimum_disability_percentage) {
      this.tdsService.showSnackBar('Please enter a valid disability percentage value of greater than or equal to ' + this.section80ddDetails[0].minimum_disability_percentage + '%.', true)
      setTimeout(() => { ele.disability = null; }, 100)
      return
    }
    let sameValue = false;
    for (let a = 0; a < this.subArray.length; a++) {
      if (this.subArray[a].relationship == ele.relationship && this.subArray[a].disability != ele.disability &&
        this.subArray[a].submittedStatus != "Rejected") {
        sameValue = true;
      }
    }
    if (sameValue) {
      this.tdsService.showSnackBar('The disability percentage entered for the selected relationship does not match with that in the previous submissions.', true)
      setTimeout(() => { ele.disability = null }, 100);
      return;
    }
    this.ageDisabilityValidation(ele, false)
  }

