  limitDecimal(event: Event): void {
    const input = event.target as HTMLInputElement;
    let value = input.value;

    // Remove any occurrences of 'e' or 'E' directly
    value = value.replace(/[eE]/g, '');

    // Allow only numbers with up to 10 digits before decimal and 2 after decimal
    const regex = /^\d{0,10}(\.\d{0,2})?$/;

    if (!regex.test(value)) {
      // Extract only valid numeric portion
      const match = value.match(/^\d{0,10}(\.\d{0,2})?/);
      input.value = match ? match[0] : '';
    } else {
      // If the input is valid, assign it back
      input.value = value;
    }
  }

