  is80tta80ttb(ele: any) {
    if (this.ttAttB && ele.id == 19) { /** TTA */
      /**1.Submitted amount is less than max limit then set max limit to submitted one
       * 2.If it is grater than max-limit no change required for max-limit
        */
      if (ele.max_exemption_amount >= Number(this.ttAttB.vamount)) {
        ele.max_exemption_amount = Number(this.ttAttB.vamount);
      }
      /**1.TTA-Status is zero show the message*/
      if (!this.ttAttB.tta_status) { /** TTA */
        ele.message = this.ttAttB.error_message
      }
      if (this.ttAttB.tta_status && Number(this.ttAttB.vamount) === 0) {
        ele.message = this.ttAttB.message
      }
    }
    if (this.ttAttB && ele.id == 22) { /** TTB */
      /**1.Submitted amount is less than max limit then set max limit to submitted one
          * 2.If it is grater than max-limit no change required for max-limit
           */
      if (ele.max_exemption_amount >= Number(this.ttAttB.vamount)) {
        ele.max_exemption_amount = Number(this.ttAttB.vamount);
      }
      /**1.TTB-Status is zero show the message*/


      if (this.ttAttB.ttb_status === 0) {
        ele.message = this.ttAttB.error_message
      }
      if (this.ttAttB.ttb_status && Number(this.ttAttB.vamount) === 0) {
        ele.message = this.ttAttB.message
      }
    }
    /** if your hit's Final submit button, not submitted section show bellow message */
    if (!ele.records && this.isDisableFinalSubmit) {
      ele.message = 'Submissions of tax exemptions is not permitted after hitting Final Submit button. Please contact your Finance Manager. '
    }
  }


