  ageDisabilityValidation(ele: any, age: boolean = true) {
    if (age) {
      for (let i = 0; i < this.section80ddbDetails.length; i++) {
        if (this.section80ddbDetails[i].age_lower_limit <= ele.age && ele.age <= this.section80ddbDetails[i].age_upper_limit) {
          ele.ageValidation = this.section80ddbDetails[i]
        } else if (this.section80ddbDetails[i].age_lower_limit <= ele.age && !this.section80ddbDetails[i].age_upper_limit) {
          ele.ageValidation = this.section80ddbDetails[i]
        }
      }
    } else {
      for (let i = 0; i < this.section80ddDetails.length; i++) {
        if (this.section80ddDetails[i].disability_lower_limit <= ele.disability && ele.disability <= this.section80ddDetails[i].disability_upper_limit) {
          ele.disabilityValidation = this.section80ddDetails[i];
        } else if (this.section80ddDetails[i].disability_lower_limit <= ele.disability && !this.section80ddDetails[i].disability_upper_limit) {
          ele.disabilityValidation = this.section80ddDetails[i];
        }
      }
    }

  }


