import { Component, ViewChild, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { jsPDF } from "jspdf";
import { Location } from "@angular/common";
import { PayrollService } from '../../payroll.service';
import { ToWords } from 'to-words';
import { CompanyInformationService } from 'src/app/services/company-information.service';
import { MainService } from 'src/app/services/main.service';
import { CompanySettingService } from 'src/app/services/companysetting.service';
@Component({
  selector: 'app-pay-slips-view',
  templateUrl: './pay-slips-view.component.html',
  styleUrls: ['./pay-slips-view.component.scss']
})
export class PaySlipsViewComponent implements OnInit {
  payslipdata: any = [];
  getpayslipdata: any = [];
  alldata: any = [];
  earningsdata: any = [];
  deductiondata: any = [];
  leavesdata: any = [];
  empname: any;
  designation: any;
  dateofjoin: any;
  payperiod: any;
  paydate: any;
  uanumber: any;
  esi: any;
  netamount: any;
  words: any;
  pic: any
  paiddays: any;
  lopDays: any;
  usersession: any;
  companyDBName: any;
  companyName: any;
  companyinfo: any;
  companylocation: any;
  companyCity: any;
  department:any;
  section:any;
  sectionflag:any;

  bankName: any;
  accountNo: any;
  ifsc: any;
  panNumber: any;
  getBankDetails: any = [];
  lopAmount: any;
  actualGrossEarnings: any;
  totalDeduction: any;
  grossEarnings: any;
  arrearAmount: any;
  arrearAmountVisible: boolean = false;
  extra_days: any;
  extraEarnings: any;
  isExtradaysVisible: boolean = false;
  isLopVisible: boolean = false;
  isLeaveEncashVisible: boolean = false;
  leaveEncashmentAmount: any;
  constructor(private router: Router, private location: Location, private PR: PayrollService, private LM: CompanyInformationService, private mainService: MainService, private companyService: CompanySettingService) {
    this.payslipdata = this.location.getState();
    this.usersession = JSON.parse(sessionStorage.getItem('user') || '');
    this.companyDBName = sessionStorage.getItem('companyName');
    if (!this.payslipdata.userData) {
      this.router.navigate(["Payroll/PaySlips"]);
    }
    else {
      this.getEmployeePayslipDetails(this.payslipdata.userData);
    }
  }
  @ViewChild('payslip') payslip: any;
  ngOnInit(): void {
   this.sectionflag = Number(sessionStorage.getItem('section')) == 1 ? true :false;
    this.getCompanyInformation();
    this.getWorkLocation()

  }
  Back() {
    if (this.payslipdata.userData.superadmin == true) {
      this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
        this.router.navigate(["/Payroll/componentWisePayrollReport"], { state: { paydate: this.paydate } }));
    } else {
      this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
        this.router.navigate(["/Payroll/PaySlips"]));
    }
  }
  getWorkLocation() {
    this.companyService
      .getactiveWorkLocation({ id: null, companyName: this.companyDBName })
      .subscribe((result) => {
        for (let i = 0; i < result.data.length; i++) {
          if (this.usersession.branch == result.data[i].location) {
            if (result.data[i].location != '' || result.data[i].location != null) {
              this.companylocation = result.data[i].location;
              this.companyCity = result.data[i].cityname;

            } else {
              this.companylocation = result.data[i].cityname
            }


          }
        }
      });
  }
  getEmployeePayslipDetails(userdata: any) {
    let data = {
      id: parseInt(userdata.id),
      empid: parseInt(userdata.empid)
    }
    this.PR.getEmployeePayslipDetails(data).subscribe((result: any) => {
      if (result.status && result.data.length > 0) {

        const toWords: any = new ToWords();
        this.getpayslipdata = result.data[0];
        if (result.data[1].length > 0) {
          this.getBankDetails = result.data[1][0];
          this.bankName = this.getBankDetails.bankname;
          this.accountNo = this.getBankDetails.bankaccountnumber;
          this.ifsc = this.getBankDetails.ifsccode == "null" || null ? '' : this.getBankDetails.ifsccode;
          this.panNumber = this.getBankDetails.pan == "null" || null ? '' : this.getBankDetails.pan;
        }

        for (let i = 0; i < this.getpayslipdata.length; i++) {
          if (this.getpayslipdata[i].component_name == "Employee Name") {
            this.empname = this.getpayslipdata[i].data_value;

          }
          else if (this.getpayslipdata[i].component_name == "Department") {
            this.department = this.getpayslipdata[i].data_value;

          }
          else if (this.getpayslipdata[i].component_name == "Section" && this.sectionflag) {
            this.section = this.getpayslipdata[i].data_value;

          }
          else if (this.getpayslipdata[i].component_name == "Designation") {
            this.designation = this.getpayslipdata[i].data_value;

          }
          else if (this.getpayslipdata[i].component_name == "Date of Joining") {
            this.dateofjoin = this.getpayslipdata[i].data_value;

          }
          else if (this.getpayslipdata[i].component_name == "Pay Period") {
            this.payperiod = this.getpayslipdata[i].data_value;

          }
          else if (this.getpayslipdata[i].component_name == "Pay Date") {
            this.paydate = this.getpayslipdata[i].data_value;

          }
          else if (this.getpayslipdata[i].component_name == "UA Number") {
            this.uanumber = this.getpayslipdata[i].data_value == "null" || null ? '' : this.getpayslipdata[i].data_value;

          }
          else if (this.getpayslipdata[i].component_name == "ESI") {
            this.esi = this.getpayslipdata[i].data_value == "null" || null ? '' : this.getpayslipdata[i].data_value
          }
          else if (this.getpayslipdata[i].component_name == "Total Net Payable") {
            this.netamount = this.getpayslipdata[i].data_value;
            this.words = toWords.convert(this.netamount, { currency: true });
          }
          else if (this.getpayslipdata[i].component_name == "Paid Days") {
            let days = this.getpayslipdata[i].data_value;
            this.paiddays = days.slice(0, -1);

          }
          else if (this.getpayslipdata[i].component_name == "LoP Days") {
            let days = this.getpayslipdata[i].data_value;
            this.lopDays = days.slice(0, -1);

          } else if (this.getpayslipdata[i].component_name == "LOP Amount") {
            this.lopAmount = this.getpayslipdata[i].data_value;
            this.lopAmount != '0' ? this.isLopVisible = true : this.isLopVisible = false;

          } else if (this.getpayslipdata[i].component_name == "Actual Gross Earnings") {
            this.actualGrossEarnings = this.getpayslipdata[i].data_value;

          } else if (this.getpayslipdata[i].component_name == "Gross Earnings") {
            this.grossEarnings = this.getpayslipdata[i].data_value;

          }
          else if (this.getpayslipdata[i].component_name == "Total Statutory Deductions") {
            this.totalDeduction = this.getpayslipdata[i].data_value;
          }
          else if (this.getpayslipdata[i].component_name == "Arrear Amount") {
            this.arrearAmountVisible = true;
            this.arrearAmount = this.getpayslipdata[i].data_value;
          }
          else if (this.getpayslipdata[i].component_name == "Extra Days Amount") {
            this.isExtradaysVisible = true;
            this.extraEarnings = this.getpayslipdata[i].data_value;

          }
          else if (this.getpayslipdata[i].component_name == "Extra Days") {
            let days = this.getpayslipdata[i].data_value;
            this.extra_days = days.slice(0, -1);
          }
          else if (this.getpayslipdata[i].component_name == "Leave Encashment") {
            this.leaveEncashmentAmount = this.getpayslipdata[i].data_value;
            this.leaveEncashmentAmount != '0' ? this.isLeaveEncashVisible = true : this.isLeaveEncashVisible = false;

          }
          else {
            this.alldata.push(this.getpayslipdata[i])
          }
        }
        for (let i = 0; i < this.alldata.length; i++) {
          if (this.alldata[i].type_value == "Earnings") {
            this.earningsdata.push(this.alldata[i])

          }
          else if (this.alldata[i].type_value == "Deductions" || this.alldata[i].component_name == "Total Deductions") {

            this.deductiondata.push(this.alldata[i]);

          } else if (this.alldata[i].type_value == "Leave") {

            this.leavesdata.push(this.alldata[i]);
          }


        }
        this.getLogo();
      }
    })
  }

  Download() {
    const DATA = this.payslip.nativeElement;
    const doc: jsPDF = new jsPDF('l', 'mm', [Number(window.innerWidth) - 400, window.innerHeight + 400]);
    // const doc: jsPDF = new jsPDF('l', 'mm', [297, 210]);
    doc.html(DATA, {
      callback: (doc) => {
        doc.setFont('fa-solid-900', 'normal');
        doc.save(this.empname + '-' + this.payperiod + "- payslip.pdf");
      }
    });

  }


  getLogo() {
    let info = {
      employeeId: 0,
      candidateId: null,
      filecategory: 'LOGO',
      moduleId: 2,
      requestId: null,
      status: 'Submitted',
    };
    this.mainService.getFilesMaster(info).subscribe((result: any) => {
      if (result && result.status && result.data[0]) {
        result.data[0].employeeId = 0;
        let info = result.data[0]
        this.mainService.getProfileImage(result.data[0]).subscribe((imageData) => {
          if (imageData.success) {
            let TYPED_ARRAY = new Uint8Array(imageData.image.data);
            const STRING_CHAR = TYPED_ARRAY.reduce((data, byte) => {
              return data + String.fromCharCode(byte);
            }, '');

            let base64String = btoa(STRING_CHAR)
            this.pic = 'data:image/png;base64,' + base64String;


          }
          else {
            // this.isRemoveImage=false;
            this.pic = "data:image/png;base64,";

          }
        })
      } else {
        // this.isRemoveImage=false;
        this.pic = "data:image/png;base64,";

      }
    })

  }
  getCompanyInformation() {
    this.LM.getCompanyInformation('companyinformation', null, 1, 10, this.companyDBName).subscribe((data: any) => {
      if (data.status && data.data.length != 0) {
        this.companyinfo = data.data[0];
        this.companyName = data.data[0].companyname;
      } else {
      }
    })
  }
}
