import { Component, Inject, OnInit,ChangeDetectorRef } from '@angular/core';
import { MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';
import { TranslateService } from '@ngx-translate/core';
@Component({
  selector: 'app-reusable-dialog',
  templateUrl: './reusable-dialog.component.html',
  styleUrls: ['./reusable-dialog.component.scss']
})
export class ReusableDialogComponent implements OnInit {
  status!:boolean;
  constructor(private translate: TranslateService, private changeDetectorRef: ChangeDetectorRef, public dialogRef: MatDialogRef<ReusableDialogComponent>,
    @Inject(MAT_DIALOG_DATA) public message: string) { }
  onNoClick(): void {
    this.dialogRef.close();
  }
  ngOnInit() {
     let  savedLang = localStorage.getItem('lang');
    this.translate.use(savedLang || 'english');
  }

  ngAfterViewInit() {
    let  savedLang = localStorage.getItem('lang');
    this.translate.use(savedLang || 'english');
    this.changeDetectorRef.detectChanges(); // ✅ refresh view safely
  }

}
