
import { Component, HostListener } from '@angular/core';
import { Router } from '@angular/router';
import { BnNgIdleService } from 'bn-ng-idle';
import { MatDialog } from '@angular/material/dialog';
import { InternetstatusService } from './services/internetstatus.service';
import { LoginService } from './services/login.service';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.scss']
})
export class AppComponent {

  title = 'Spryple';
  isOnline = true;
  constructor(public router:Router,
  private bnIdle: BnNgIdleService,
  private dialogRef: MatDialog,
  private networkStatusService:InternetstatusService,
  private loginService: LoginService,) {
    this.networkStatusService.isOnline$.subscribe(status => {
      this.isOnline = status;
    });
}
  ngOnInit(): void {
  this.bnIdle.startWatching(1800).subscribe((res) => {
     if (res) {
      sessionStorage.removeItem('companyName');
      sessionStorage.removeItem('user');
      sessionStorage.removeItem('sidemenu');
      sessionStorage.removeItem('token');
      sessionStorage.removeItem('moduleData');
      sessionStorage.removeItem('compOffEnabled');
      sessionStorage.removeItem('selectedModule');
      sessionStorage.removeItem('expirydate');
      sessionStorage.removeItem('activeChild');
      var login = '/Login'
      this.router.navigate([login]);
      this.dialogRef.closeAll();
      this.loginService.setLoggedInState(false);
      }
    });

 }


}
