import { Component, Inject, OnInit } from '@angular/core';
import { UntypedFormBuilder, UntypedFormGroup } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';

@Component({
  selector: 'app-halfday-dialogbox',
  templateUrl: './halfday-dialogbox.component.html',
  styleUrls: ['./halfday-dialogbox.component.scss']
})
export class HalfdayDialogboxComponent implements OnInit {
  halfdayForm!:UntypedFormGroup;
  regulardayForm!:UntypedFormGroup;
    constructor(public dialogRef: MatDialogRef<HalfdayDialogboxComponent>,
   
      @Inject(MAT_DIALOG_DATA) public data: any, private formBuilder: UntypedFormBuilder,) { 
  
      }
    halfdayTypeList:any = [ {id:1,name:"Attendance"},{id:2,name:"Leave"} ];
    regularTypeList:any =
       [ {id:1,name:"Full day - Attendance"},
         {id:2,name:"Full day - Leave"},
         {id:3,name:"Half day - Attendance & Half day - Leave"},
     ];
    halfDayType!:string;
    isAttendance:boolean=false;
    regularType:any;
    isHalfdayType:boolean=false;
    isRegularType:boolean=false;
    isLogoutTime:any;
    isLogoutTimeStatus:boolean = true;
    ngOnInit(): void {
      this.halfdayForm = this.formBuilder.group({
        regType:[''],
        mixedRegularType:[''],
      });
      this.regulardayForm = this.formBuilder.group({
        mixedRegularType:[''],
      })
      this.regularType = this.data.regularType;
      this.isLogoutTime = this.data.isLogoutTime;
    if(this.regularType == 'halfday') {
      this.isHalfdayType = true;
      this.isRegularType = false;
  
    } else if(this.regularType == 'regular'){
      this.isHalfdayType = false;
      this.isRegularType = true;
    }
  
      switch (this.data.halfDaytype) {
        case 'A1':
          this.halfDayType = "First Half Attendance"
            break;
        case 'A2':
          this.halfDayType = "Second Half Attendance"
            break;
        case 'L1':
          this.halfDayType = "First Half Leave"
            break;
        case 'L2':
          this.halfDayType = "Second Half Leave"
            break;
      }
      if(this.isLogoutTime !=null){
        this.isLogoutTimeStatus = false;
      }
    }
    
    halfDaySubmit(){
      if(this.halfdayForm.valid){
        if(this.halfdayForm.controls.regType.value == '1'){
          this.halfdayAttendanceSubmit();
  
        } else if(this.halfdayForm.controls.regType.value == '2') {
          this.halfdayLeaveSubmit();
        }
      }
    }
    halfdayAttendanceSubmit(){
      this.dialogRef.close('attendance',);
    }
  
    halfdayLeaveSubmit(){
      this.dialogRef.close('leave');
    }
  
    mixedRegularSubmit(){
      if(this.regulardayForm.valid){
        if(this.regulardayForm.controls.mixedRegularType.value == '1'){
          this.mixedDayAttendanceSubmit();
  
        } else if(this.regulardayForm.controls.mixedRegularType.value == '2') {
          this.mixedDayLeaveSubmit();
  
        } else if(this.regulardayForm.controls.mixedRegularType.value == '3') {
          this.mixedDayHalfSubmit();
        }
      }
    }
  
    mixedDayAttendanceSubmit(){
      this.dialogRef.close('attendance',);
    }
  
    mixedDayLeaveSubmit(){
      this.dialogRef.close('leave');
    }
  
    mixedDayHalfSubmit(){
      this.dialogRef.close('halfday_attendance_leave');
    }
  }
  