import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable, throwError } from 'rxjs';
import { catchError, tap } from 'rxjs/operators';
import { environment } from 'src/environments/environment';

@Injectable({
  providedIn: 'root',
})
export class ChatbotService {

  mainUrl = environment.flaskapiUrl;
  httpOptions: any;

  constructor(private http: HttpClient) {
    this.refreshSession();
  }

  refreshSession() {
    const token = sessionStorage.getItem('token');
    this.httpOptions = {
      headers: new HttpHeaders({
        'Content-Type': 'application/json',
        Authorization: token ? `Bearer ${token}` : '', // JWT token
      }),
    };
  }

  sendMessage(question: string, empId: string, companyCode: string, role: string, language:string): Observable<any> {
    this.refreshSession();
    const payload = {
      question,
      emp_id: empId,
      company_code: companyCode,
      role: role ,
      language: language,
    };
    return this.http.post(`${this.mainUrl}/response`, payload, this.httpOptions).pipe(
      catchError((error) => {
        console.error('Error Response from Backend:', error);
        return throwError(() => new Error('Something went wrong'));
      })
    );    
  }


}
