  exportAsXLSX1() {
    if (this.messageflag) {
      this.year = this.date.value.getFullYear();
      for (let i = 0; i < this.months.length; i++) {
        if (this.date.value.getMonth() == this.months[i].id) {
          this.monthdata = this.months[i].month;
          break;
        }
      }
      // var ws:XLSX.WorkSheet=XLSX.utils.table_to_sheet('Payroll_report_for_financeteam_');
      var ws: XLSX.WorkSheet = XLSX.utils.table_to_sheet(
        document.getElementById('table')
      );
      Object.keys(ws).forEach(cell => {
      if (cell[0] === '!') return; // skip metadata
      if (ws[cell].t === 'n') {
        ws[cell].t = 's';                // force string
        ws[cell].v = ws[cell].v.toString();
      }
    });
      const wb: XLSX.WorkBook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, 'ESI_report_for_financeteam_');
      /* save to file */
      // XLSX.writeFile('Payroll_report_for_financeteam_'+this.monthdata,'Payroll_report_for_financeteam_'+this.monthdata+'_'+this.year+'.xlsx')
      XLSX.writeFile(
        wb,
        'ESI_report_for_financeteam_' +
        this.monthdata +
        '_' +
        this.year +
        '.xlsx'
      );
    } else {
      let dialogRef = this.dialog.open(ReusableDialogComponent, {
        position: { top: `70px` },
        disableClose: true,
        data: this.message,
      });
    }
  }


  exportAsXLSX() {
    if (true) {
      // this.year = this.searchForm.controls.date.value.getFullYear();
      this.year = this.date.value._d.getFullYear();
      for (let i = 0; i < this.months.length; i++) {
        // if (this.searchForm.controls.date.value.getMonth() == this.months[i].id)
        if (this.date.value._d.getMonth() == this.months[i].id) {
        
          this.monthdata = this.months[i].month;
          break;
        }
      }

      let headerKeys = [
        'ESI',
        'empid',
        'Employee_Name',
        'deptname',
        ...(this.sectionflag ? ['section_name'] : []),
        'paid_days',
        'Gross_Salary',
        'employee_esi_value',
        'employer_esi_value',
        'total_contribution',
        'location',
        'employer_esi',
        'employer_bank',
        'employer_ifsc',
        'employer_account',
        'cost_center_name'
      ];

      const headerMap: { [key: string]: string } = {
        'ESI': 'Employee ESI No',
        'empid':'Emp Code',
        'Employee_Name': 'Emp. Name',
        'deptname':'Department',
         ...(this.sectionflag ? { section_name: 'Section' } : {}),
        'paid_days': 'Paid Days',
        'Gross_Salary': 'Gross Salary',
        'employee_esi_value': 'Employee Contribution ',
        'employer_esi_value': 'Employer Contribution',
        'total_contribution': ' Total Contibution',
        'location': ' Location',
        'cost_center_name': ' Cost Center Name',
        'employer_esi': ' Employer ESI No.',
        'employer_bank': 'Employer Bank Name',
        'employer_ifsc': 'Employer IFSC Code',
        'employer_account': 'Employer Account Number'
      };

      if (this.vno <= 0) {
        const costCenterIndex = headerKeys.indexOf('cost_center_name');
        if (costCenterIndex > -1) {
          headerKeys.splice(costCenterIndex, 1);
        }
      }

      const exportData = this.list.map((row: any) => {
        const newRow: any = {};
        headerKeys.forEach(key => {
          newRow[key] = row[key];
        });
        return newRow;
      });

      var ws: XLSX.WorkSheet = XLSX.utils.json_to_sheet(exportData, {
        header: headerKeys,
        skipHeader: false
      });

      const range = XLSX.utils.decode_range(ws['!ref'] || 'A1:A1');
      for (let C = range.s.c; C <= range.e.c; ++C) {
        const cellRef = XLSX.utils.encode_cell({ r: range.s.r, c: C });
        const cell = ws[cellRef];
        if (cell && cell.v) {
          const key = cell.v;
          cell.v = headerMap[key] || key;
        }
      }
      Object.keys(ws).forEach(cellRef => {
      if (cellRef[0] === '!') return;
      const cell = ws[cellRef];
      if (!cell || cell.v == null) return;
      cell.t = 's';
      cell.z = '@';               // text format
      cell.v = String(cell.v);    //  string
      });

        

      const wb: XLSX.WorkBook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, 'ESI_report_for_financeteam_');
      /* save to file */
      // XLSX.writeFile('Payroll_report_for_financeteam_'+this.monthdata,'Payroll_report_for_financeteam_'+this.monthdata+'_'+this.year+'.xlsx')
      XLSX.writeFile(
        wb,
        'ESI_report_for_financeteam_' +
        this.monthdata +
        '_' +
        this.year +
        '.xlsx'
      );
    }
    else {
      let dialogRef = this.dialog.open(ReusableDialogComponent, {
        position: { top: `70px` },
        disableClose: true,
        data: this.message
      });
    }
  }

