  Searchform() {
    this.getESIValuesForChallan();
  }

  getESIValuesForChallan() {
    let data = {
      year: this.date.value._d.getFullYear(),
      month: this.date.value._d.getMonth() + 1,
      state: Number(this.selectedStateId),
    };
    this.dataSource = new MatTableDataSource();
    if (this.searchForm.valid) {
      this.PR.getESIValuesForChallan(data).subscribe((result: any) => {
        if (result.status) {
          this.list = result.data[0]
          this.dataSource = new MatTableDataSource(this.list);
          this.dataSource.paginator = this.paginator;
          this.dataSource.sort = this.sort;
          this.pageLoading = false;
          this.validateEsiChallanDownload();
          this.vno = result.data[1][0].vno;
          if (this.vno > 0  && !this.displayedColumns.includes('cost_center_name')) {
            this.displayedColumns.push('cost_center_name');
          }
        }
      });
    } else {
      this.searchForm.markAllAsTouched();
    }
  }

  validateEsiChallanDownload() {
    let data = {
      year: this.date.value._d.getFullYear(),
      month: this.date.value._d.getMonth() + 1,
    };
    this.PR.validateEsiChallanDownload(data).subscribe((result: any) => {
      if (result.status && result.data[0].validity == 0) {
        this.messageflag = false;
        this.message = result.data[0].message;
      } else {
        this.messageflag = true;
        this.message = '';
      }
    });
  }

  resetform() {
    this.router
      .navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/Payroll/EsiReport']));
  }

  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }
  filterStates(searchText: any) {
    this.filteredStateList = this.stateslist.filter((val: any) =>
      val.state.toLowerCase().includes(searchText.toLowerCase()));
    if (this.filteredStateList.length <= 0) {
      this.searchControl.setValue('');
    }
  }

generatePDF() {
  let formattedDate: string =
    this.datePipe.transform(this.date.value._d, 'MMMM-yyyy') || '';

  const doc = new jsPDF({ orientation: 'landscape' });
  const reportName = 'ESI Report';
  let manager = '';
  let locationName = '';
  let reportDate = formattedDate;

  this.pdfService.generatePDFHeader(
    doc,
    reportName,
    locationName,
    manager,
    reportDate,
    false,
    false
  );

  /* -------------------- TABLE HEADERS -------------------- */
  const headColumns: string[] = [
    'ESI No.',
    'Emp Code',
    'Emp. Name',
    'Department'
  ];

  if (this.sectionflag) {
    headColumns.push('Section');
  }

  headColumns.push(
    'Paid Days',
    'Gross Salary',
    'Employee Contribution',
    'Employer Contribution',
    'Total Contribution',
    'Location'
  );

  if (this.vno > 0) {
    headColumns.push('Cost Center Name');
  }

  /* -------------------- TABLE BODY -------------------- */
  const tableData = this.list.map((emp: any) => {
    const row: any[] = [
      emp.ESI,
      emp.empid,
      emp.Employee_Name,
      emp.deptname
    ];

    if (this.sectionflag) {
      row.push(emp.section_name || '');
    }

    row.push(
      emp.paid_days,
      emp.Gross_Salary,
      emp.employee_esi_value,
      emp.employer_esi_value,
      emp.total_contribution,
      emp.location
    );

    if (this.vno > 0) {
      row.push(emp.cost_center_name);
    }

    return row;
  });

  /* -------------------- PDF TABLE -------------------- */
  autoTable(doc, {
    head: [headColumns],
    body: tableData,
    startY: 40,
    styles: { fontSize: 9 },
    headStyles: { fontSize: 11 }
  });

  doc.save('Esi_Report.pdf');
}


  getEmployerDetails(row: any): string {
    return [
      ` Esi no: ${row.employer_esi || ''} |`,
      `Bank Name: ${row.employer_bank || ''} |`,
      `IFSC Code: ${row.employer_ifsc || ''} |`,
      `Account: ${(row.employer_account || '')} |`,
    ].join('\n');
  }
