import { Injectable } from '@angular/core';
import {HttpClient, HttpHeaders} from "@angular/common/http";
import {Observable} from "rxjs/index";
import { environment } from 'src/environments/environment';
@Injectable({
    providedIn: 'root'
})
export class RoleMasterService {
    mainBeUrl= environment.apiUrl;
    httpOptions:any;
    companyName:any;
    constructor(private hClient: HttpClient) {
      this.companyName=sessionStorage.getItem("companyName");
      this.httpOptions = {
        headers: new HttpHeaders({
          'content-Type': 'application/json',
          "Authorization": JSON.parse(JSON.stringify(sessionStorage.getItem('token') || '')),
        })
      };
    }

    getRoleMaster(){
        return this.hClient.get(this.mainBeUrl + 'adminApi/getrolemaster/'+this.companyName, this.httpOptions);
    }

    getFunctionalitesMaster(){
        return this.hClient.get(this.mainBeUrl + 'adminApi/getfunctionalitiesmaster/'+this.companyName, this.httpOptions);
    }
    getScreenFunctionalities() {
        return this.hClient.get(this.mainBeUrl + 'adminApi/getscreenfunctionalitiesmaster/'+this.companyName, this.httpOptions);
    }
    getRoleScreenFunctionalities(roleId: Observable<any>) {

        return this.hClient.get(this.mainBeUrl + 'adminApi/getrolescreenfunctionalities/' + roleId+'/'+this.companyName, this.httpOptions);

    }
    setRoleMaster(info: any): Observable<any> {
        info.companyName =this.companyName;
        return this.hClient.post(this.mainBeUrl + 'adminApi/setRoleMaster', JSON.stringify(info), this.httpOptions);
    }
    setRoleAccess(info: any): Observable<any> {
      info.companyName =this.companyName;
      return this.hClient.post(this.mainBeUrl + 'adminApi/setRoleAccess', JSON.stringify(info), this.httpOptions);
    }

}
