@Component({
  selector: 'app-crm-references-master',
  templateUrl: './crm-references-master.component.html',
  styleUrls: ['./crm-references-master.component.scss']
})
export class CrmReferencesMasterComponent implements OnInit {

  referenceForm!: UntypedFormGroup;
  reference_name: any;
  userSession:any;
  pipe = new DatePipe('en-US');
  issubmitted: boolean = false;
  isvalid: boolean = false;
  isView: boolean = false;
  isAdd: boolean = false;
  isdata: boolean = true;
  isEdit: boolean = true;
  isSave: boolean = false;
  isDelete: boolean = true;
  enable: any = null;
  valid: boolean = false;
  activitystatus:any=null;
  selected_color:any =null;
  todayDate:any=new Date();
  displayedColumns: string[] = ['sno','reference_name','color', 'status', 'Action'];
  arrayValue: any;
  dataSource: MatTableDataSource<any> = <any>[];
  pageLoading = true;
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  valid_color:any = null;
  languages = [
    { code: 'english', label: 'ENGLISH', name: 'English' },
    { code: 'arabic', label: 'ARABIC', name: 'Arabic' }
  ];

  constructor(private crmService:CrmService,private Company:CompanySettingService,private formBuilder: UntypedFormBuilder, private router: Router,
    private dialog: MatDialog, private translate: TranslateService) { }

  ngOnInit(): void {
    const savedLang = localStorage.getItem('lang');
   this.translate.use(savedLang || 'english');
    this.getstatuslist();
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.getCrmReferences();
    this.referenceForm = this.formBuilder.group( {
      reference_name: ["",[Validators.required ]],
      color:[""],
      }, );

    this.referenceForm.get('color')?.valueChanges.subscribe((selected:any) => {
      this.selected_color = this.hexToRgb(selected);
    });
  }
 

  getstatuslist(){
    this.Company.getstatuslists().subscribe((result:any) => {     
      if(result.status){
        this.arrayValue = result.data;
      }
    })
  }

  status(status:any,row:any){
      let data={
        reference_id:row.reference_id,
        reference_name:row.reference_name,
        color:row.color,
        is_active:status,
        created_by: this.userSession.id,
        created_on: this.pipe.transform(new Date(), 'yyyy-MM-dd HH:mm:ss')
    }
    this.setReference(data);
  }
  
  getCrmReferences() {
    let params = {
      pagenumber:1,
      pagesize:100
    }
    this.crmService.getSprypleData(params,'get_crm_references_master').subscribe((res:any)=>{
      if(res.status) {
        // res.data?.forEach((r:any)=>{
        //   r.color = this.rgbsplit(r.color);
        // });
       // this.reference_Data =  res.data;
        this.dataSource = new MatTableDataSource(res.data);        
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
      }
    })
  }

  check_color(data:any){
    let valid_color:any = null; 
   
    this.dataSource.data?.forEach((r:any)=>{
      
      if(!valid_color && !data.reference_id && r.color == data.color){        
          valid_color = 'Color already exists.';
      }
      if(!valid_color && data.reference_id && data.reference_id != r.reference_id && r.color == data.color){         
          valid_color = 'Color already exists.';
      }
    });
     
    return valid_color;
  }

  setReference(data:any) {
      this.valid_color = this.check_color(data);
      if(this.valid_color){
        let dialogRef = this.dialog.open(ReusableDialogComponent,{position:{top:`70px`},disableClose:true,  data:this.valid_color });
        return;
      }
      data.reference_name = data.reference_name.trim();
      data.reference_name = data.reference_name.replace(/\s+/g, ' ');
     
      if(data.reference_name && data.reference_name.toString().length){
        this.crmService.setCrmReference(data).subscribe((res:any)=>{
          if(res.status) {
            this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
            this.router.navigate(["/Crm/CrmReferences"]));
            this.dataSource.paginator = this.paginator;
            let dialogRef = this.dialog.open(ReusableDialogComponent, {
            position: { top: `70px` },
            disableClose: true,
            data:res.data[0].resultmsg,
          });
        }
        else {
          let dialogRef = this.dialog.open(ReusableDialogComponent, { position:{top: `70px` }, disableClose: true,
            data: "Unable to add Reference name. Please try again. "
          });
        }
      })
    }
  }

  Add() {
    this.isAdd = true;
    this.isdata = false;
    this.referenceForm.controls.reference_name.setValue('')
  }

  cancel() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Crm/CrmReferences"]));
  }
  

edit(row: any) {    
    this.enable = row.reference_id;
    this.isEdit = false;
    this.isDelete = false;    
    this.isSave = true;
    this.referenceForm.controls.reference_name.setValue(row.reference_name);
    this.referenceForm.controls.color.setValue(this.rgbToHex(row.color));
    //this.referenceForm.controls.color.setValue(row.color);
  }

  save(event: any,row: any, reference_name: any, color:any) {    
    if (this.referenceForm.valid) {
      this.enable = null;
      this.isEdit = true;
      this.isSave = false;
      this.isDelete = true;
        let data={ 
          reference_id:row.reference_id, 
          reference_name:reference_name, 
          color:this.hexToRgb(color), 
          is_active:row.is_active, 
          created_by: this.userSession.id,
          created_on: this.pipe.transform(new Date(), 'yyyy-MM-dd HH:mm:ss')
        };
        this.setReference(data);
    }
  }

  AddData(){
    let data = { 
      reference_id:0,
      reference_name:this.referenceForm.controls.reference_name.value,
      color:this.hexToRgb(this.referenceForm.controls.color.value), 
      is_active:true, 
      created_by: this.userSession.id,
      created_on: this.pipe.transform(new Date(), 'yyyy-MM-dd HH:mm:ss')
     };
    this.setReference(data);
  }           
  canceledit(event: any, id: any) {   
    this.enable = null;
    this.isEdit = true;
    this.isSave = false;
    this.isDelete = true;
    this.ngOnInit();
  }

  getPageSizes(): number[] {
    var customPageSizeArray = [];
    
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
     
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }
  
    getMessages() {
      let data =  {  "code": null, "pagenumber": 1, "pagesize": 1000  };    
    }

    /**Search functionality */
    applyFilter(event: Event) {
      const filterValue = (event.target as HTMLInputElement).value;
      this.dataSource.filter = filterValue.trim().toLowerCase();
      if (this.dataSource.paginator) {
        this.dataSource.paginator.firstPage();
      }  
    }
    delete(event:any,reference_id:any,row:any) {   
      let message = this.translate.instant('DeleteReferenceMessage', { name: `<span style='color:red;font-weight:bold;'>${row.reference_name || ''}</span>` });;
      let yesText = this.translate.instant('YES');
      let noText = this.translate.instant('NO');    
      let dialogRef = this.dialog.open(ComfirmationDialogComponent, { position: { top:`70px`}, disableClose: true,
        // data: { message:  `Are you sure you want to delete the reference with name <span style="color: red; font-weight: bold;">${row.reference_name ? row.reference_name : ''}</span> ?`, YES: 'YES', NO: 'No' }
        data: { message: message , YES: yesText, NO: noText }
      });
      dialogRef.afterClosed().subscribe(result => {
        console.log('Dialog result:', result); 
        //  (result?.toUpperCase() === 'YES') 
        (result && result.toString().toUpperCase() === 'YES')
         ?  this.deleteReference(event,reference_id):null;        
      });
    }

    deleteReference(event:any,reference_id:any){       
      this.crmService.deleteCrmReference({reference_id:reference_id,empid:this.userSession.id}).subscribe((data:any)=>{
        if(data && data.status){
          let dialogRef = this.dialog.open(ReusableDialogComponent,{ position:{top:`70px`}, disableClose: true, data: data.data[0].resultmsg });
          this.router.navigateByUrl('/', { skipLocationChange: true }).then(() => this.router.navigate(["/Crm/CrmReferences"]));
        }else {
          let dialogRef = this.dialog.open(ReusableDialogComponent, { position:{top:`70px`}, disableClose: true,  data: 'Demo status not deleted.'  });
        }
      })
    }
    disableStatus(row:any){
     return (this.enable == row.reference_id)?true:false;
    }

    //  rgbToHex(data:any){
    //   if(data){
    //   let selected_color = data;
    //   let rgb = data.substring(4, data.length-1).replace(/ /g, '').split(',');
    //   selected_color = "#" + ((1 << 24) + (rgb[0] << 16) + (rgb[1] << 8) + rgb[2]).toString(16).slice(1);
    //   return selected_color;
    //   }
    //   else return data;
    // }
    rgbToHex(rgb: string): string {
      const result = rgb.match(/\d+/g);
      if (!result || result.length < 3) return '#000000'; // fallback

      const r = parseInt(result[0]).toString(16).padStart(2, '0');
      const g = parseInt(result[1]).toString(16).padStart(2, '0');
      const b = parseInt(result[2]).toString(16).padStart(2, '0');

      return `#${r}${g}${b}`;
    }
    hexToRgb(hex:any) {
      var result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
        if(result){
          var r= parseInt(result[1], 16);
          var g= parseInt(result[2], 16);
          var b= parseInt(result[3], 16);
          return "rgb("+ r +","+ g +","+ b+")";//return 23,14,45 -> reformat if needed
        }
      return null;
    }
}


