 /** */

 getEmployeeAdvanceSalaryRequests(empid:any){
  let data = {
    empid:empid
  }
   this.PR.getEmployeeAdvanceSalaryRequests(data).subscribe((result:any)=>{
      if(result.status){
        result.data?.forEach((rcd:any)=>{
          rcd.payable_salary = rcd.gross_salary - rcd.request_amount > 0 ? rcd.request_amount : rcd.gross_salary;
          rcd.payable_salary = Math.floor(rcd.payable_salary).toFixed(2);
        });
        this.dataSource = new MatTableDataSource(result.data);
        this.pageLoading = false;
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        }
      else
      {

      }
    })

 }
  submit(approveddata: any, status: any, approverId: any) {
 
   let data = {
    empid:approveddata.employee_id,
    easrd_id_value:approveddata.id,
    paid_amount_value:approveddata.request_amount,
    created_by_value:this.userSession.id,
    reject_reason_value:null,
    status_value:"Approved"

   }
    this.PR.setEmployeeAdvanceSalaryApprovalByManager(data).subscribe((result:any)=>{
      if(result.status){
        this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
                    this.router.navigate(["/Payroll/advanceSalaryApproval"]));
              let dialogRef = this.dialog.open(ReusableDialogComponent, {
                position:{top:`70px`},
                disableClose: true,
                data: 'Advance salary request approved successfully.'
              }); 

      }
      else{

              let dialogRef = this.dialog.open(ReusableDialogComponent, {
                position:{top:`70px`},
                disableClose: true,
                data: 'Unable to approve advance salary request.'
              }); 

      }
    })
    
  }

  Reject(data: any, status: any, rejectId: any) {
    this.titleName="Reject"
    this.openDialog(data);
  }
  canceledit(event: any, id: any) {
    this.enable = null;
    this.isEdit = true;
    this.isSave = false;
    this.ngOnInit();

  }

  save(event: any, requestPayable: any, approveddata: any) {
    // let value = approveddata.payable_salary - approveddata.paidAmount
    let value = Number(approveddata.payable_salary|| approveddata.gross_salary) || 0;
    let entered = Number(this.AdvanceSalaryRequestform.controls.requestPayable.value) || 0;
    // if(this.AdvanceSalaryRequestform.controls.requestPayable.value <= value){
    if (entered > 0 && entered <= value) {
      let data = {
        empid:approveddata.employee_id,
        easrd_id_value:approveddata.id,
        paid_amount_value:this.AdvanceSalaryRequestform.controls.requestPayable.value,
        created_by_value:this.userSession.id,
        reject_reason_value:null,
        status_value:"Approved"
    
       }

        this.PR.setEmployeeAdvanceSalaryApprovalByManager(data).subscribe((result:any)=>{
          if(result.status){
             let dialogRef = this.dialog.open(ReusableDialogComponent, {position:{top:`70px`},  disableClose: true, data: 'Advance salary request approved successfully.' });        
                dialogRef.afterClosed().subscribe(result => {
                  this.router.navigateByUrl('/', { skipLocationChange: true }).then(() => this.router.navigate(["/Payroll/advanceSalaryApproval"]));
                });
            }
          else{       
              let dialogRef = this.dialog.open(ReusableDialogComponent, { position:{top:`70px`},  disableClose: true,    data: 'Unable to approve advance salary request.' });        
          }
        })
      }else{
        let dialogRef = this.dialog.open(ReusableDialogComponent, { position:{top:`70px`},  disableClose: true,  data: 'Advance salary cannot be greater than Gross salary.' });             
        this.AdvanceSalaryRequestform.controls.requestPayable.setValue(approveddata.payable_salary);
      }
  }

  Edit(i:any){
    this.AdvanceSalaryRequestform.controls.requestPayable.setValue(i.payable_salary);
    this.enable = i.id;
    this.isEdit = false;
    this.isSave = true;

  }
  openDialog(approveddata:any): void {
    const dialogRef = this.dialog.open(ReviewAndApprovalsComponent, {
      width: '600px',position:{top:`100px`},
      data: {name: this.titleName, reason: this.reason,}
    });

    dialogRef.afterClosed().subscribe(result => {

      if(result!=undefined ){
        if(result !==true){
          let data = {
            empid:approveddata.employee_id,
            easrd_id_value:approveddata.id,
            paid_amount_value:approveddata.request_amount,
            created_by_value:this.userSession.id,
            reject_reason_value:result.reason,
            status_value:"Rejected"
        
           }
           this.PR.setEmployeeAdvanceSalaryApprovalByManager(data).subscribe((result:any)=>{
             if(result.status){
               this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
                           this.router.navigate(["/Payroll/advanceSalaryApproval"]));
                     let dialogRef = this.dialog.open(ReusableDialogComponent, {
                       position:{top:`70px`},
                       disableClose: true,
                       data: 'Advance salary request rejected successfully.'
                     }); 
           
             }
             else{
           
                     let dialogRef = this.dialog.open(ReusableDialogComponent, {
                       position:{top:`70px`},
                       disableClose: true,
                       data: 'Unable to rejected advance salary request.'
                     }); 
           
             }
           })
        
        // //  this.leaveApprove(leave, 'Rejected', null);
        // this.employeeId = leave.empid;
          // this.getEmployeeEmailData(leave ,'Rejected',null);
        }
      }
    });
  }

