  generateExcel() {
    let headers: any[] = [];
    let tblWidths: any[] = [];
    let cols: any[] = this.displayedColumns;
    cols.push('record_status');
    let col_widths: any = {
      organization_name: '40%', contact_person: '30%', email: '30%', phone: '10%', address1: '40%', address2: '30%',
      pincode: '10%', city: '15%', state: '15%', country: '15%', lead_source: '15%', estimated_price: '10%', deal_price: '10%',
      lead_status: '15%', activity_status: '15%', employee: '15%', created_date: '10%', latitude: '10%', longitude: '10%', notes: '40%',
      record_status: '10%', remarks: '20%'
    };

    cols?.forEach((col: any) => {
      headers.push(this.denormalizeColumnName(col));
      tblWidths.push(col_widths[col]);
    });
    let tblBody = [];
    tblBody.push(headers);

    this.viewdata?.forEach((row: any) => {
      let rd: any = [];
      headers.forEach((h: any) => { rd.push(row[this.normalizeColumnName(h)]); });
      tblBody.push(rd);
    });

    const totalWidth = 100;
    const maxCharacters = 100;
    const columnWidths = tblWidths.map(width => ({ wch: Math.floor((parseInt(width, 10) / totalWidth) * maxCharacters), }));
    let wb: XLSX.WorkBook = XLSX.utils.book_new();
    let ws: XLSX.WorkSheet = XLSX.utils.json_to_sheet(tblBody, { skipHeader: true });
    ws['!cols'] = columnWidths;
    Object.keys(ws).forEach((cellKey) => {
      if (cellKey.startsWith('!')) return;
      ws[cellKey].s = { font: { bold: false, size: 12 }, alignment: { horizontal: "left", vertical: "center", wrapText: true } };
    });
    XLSX.utils.book_append_sheet(wb, ws, 'Clients list');
    XLSX.writeFile(wb, `${this.fileName} - Verified by Spryple.xlsx`);

  }

  validateLatLng(r: any) {
    let vstatus = true;
    if (r['latitude'] == '' || r['latitude'] == '') return false;
    let vlat: any = r['latitude'] ? Number(r['latitude']) : 0;
    let vlng: any = r['longitude'] ? Number(r['longitude']) : 0;
    if (isNaN(vlat) || isNaN(vlng)) vstatus = false;
    if (vstatus) {
      let latStatus = !isNaN(vlat) && (vlat >= -90) && (vlat <= 90);
      let lngStatus = !isNaN(vlng) && (vlng >= -180) && (vlng <= 180);
      return latStatus && lngStatus;
    }
    return vstatus;
  }

  get_col_width(col: any) {
    let col_widths: any = {
      organization_name: '40%', contact_person: '30%', email: '30%', phone: '10%', address1: '40%', address2: '30%',
      pincode: '10%', city: '15%', state: '15%', country: '15%', lead_source: '15%', estimated_price: '10%', deal_price: '10%',
      lead_status: '15%', activity_status: '15%', employee: '15%', created_date: '10%', latitude: '10%', longitude: '10%', notes: '40%',
      record_status: '10%', remarks: '20%'
    };

    return col_widths[col];
  }

  get_row_style(col: any, e: any) {
    let cols: any = { address1: '250px', address2: '200px', notes: '250px', remarks: '150px', organization_name: '250px' };
    let cwidth: any = cols[col] ? cols[col] : 'auto';
    let bgcolor: any = 'white';
    if (e.in_valid)
      bgcolor = 'rgba(212, 148, 148, 0.282)';
    if (e.record_status == 'in_valid')
      bgcolor = 'rgba(211, 131, 131, 0.71)';

    if (e.upload_status && e.upload_status == 1)
      bgcolor = 'rgba(113, 163, 118, 0.77)';
    if (col == 'organization_name')
      bgcolor = 'whitesmoke';
    return { 'background': bgcolor, 'min-width': cwidth, 'max-width': cwidth };
  }
