
import { SelectionModel } from '@angular/cdk/collections';
import { Component, OnInit, ViewChild } from '@angular/core';
import { FormArray, FormBuilder, FormControl, FormGroup, UntypedFormGroup, Validators } from '@angular/forms';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { PayrollService } from '../../payroll.service';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { MatDialog } from '@angular/material/dialog';
import { Router } from '@angular/router';
import { MatPaginatorModule } from '@angular/material/paginator';


export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
interface Employee {
  empid: number;
  empCode: string;
  empName: string;
}
@Component({
  selector: 'app-health-insurence-configuration',
  templateUrl: './health-insurence-configuration.component.html',
  styleUrls: ['./health-insurence-configuration.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class HealthInsurenceConfigurationComponent implements OnInit {
  UserSession: any;
  companyName: any;
  constructor(
    private fb: FormBuilder,
    private payroll: PayrollService,
    private dialog: MatDialog,
    private router: Router,
  ) {
    this.UserSession = JSON.parse(sessionStorage.getItem('user') ?? '');
  }
  employeeForm: any = UntypedFormGroup;
  editForm: any = UntypedFormGroup;
  @ViewChild('paginator1', { static: false }) paginator!: MatPaginator;
  @ViewChild('paginator2') paginator2!: MatPaginator;
  @ViewChild('sort') sort!: MatSort;
  @ViewChild('sort2') sort2!: MatSort;
  // pageSizeOptions: number[] = [5, 10, 20];
  // pageSizeOptions2: number[] = [5, 10, 20];
  pageLoading = true;
  pageLoading2 = true;

  displayedColumns: string[] = ['select', 'sno', 'empCode', 'empName', 'designation', 'deptname', 'amount'];
  dataSource: MatTableDataSource<Employee> = <any>[];

  displayedColumns2: string[] = ['sno', 'empCode', 'empName', 'designation', 'deptname', 'monthAmount', 'yearlyAmount', 'action'];
  dataSource2: MatTableDataSource<any> = <any>[];


  selectedEmployees: Set<number> = new Set();
  employeeList: any = [];
  employeeHistory: any = [];
  btnDisable: boolean = false;
  branchSelected: boolean = true;

  employeeArray: any;
  selection = new SelectionModel<any>(true, []);
  insurenceAmount: FormControl[] = [];
  selectedEmployeesList: any[] = [];
  enable: any = null;

  isdata: boolean = false;
  ngOnInit(): void {
    this.employeeForm = this.fb.group({

      employees: this.fb.array([]),

    });
    this.editForm = this.fb.group({
      insuranceAmt: ['', Validators.required]
    })
    this.getEmployeeList();
    this.getInsurenceEmployeeDetails();
  }

  ngAfterViewInit(): void {
    if (this.dataSource) {
      this.dataSource.paginator = this.paginator;
      this.dataSource.sort = this.sort;
    }

    if (this.dataSource2) {
      this.dataSource2.paginator = this.paginator2;
      this.dataSource2.sort = this.sort2;
    }
  }


  add() {
    this.isdata = true;
    setTimeout(() => {
      if (this.dataSource) {
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
      }
    }, 0);
  }

  getEmployeeList() {

    this.payroll.getEmployeeForHealthInsuranceAddition().subscribe((res: any) => {
      if (res.status) {
        this.employeeList = res.data;
        this.dataSource = new MatTableDataSource(this.employeeList);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading2 = false;
        this.initEmployeeFormArray();


      } else {
        this.employeeList = [];
        this.dataSource = new MatTableDataSource(this.employeeList);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading2 = false;
      }
    });
  }

  getInsurenceEmployeeDetails() {

    let employeeList: any = []
    this.payroll.getEmployeeHealthInsuranceDetails().subscribe((res: any) => {
      if (res.status) {
        employeeList = res.data
        this.dataSource2 = new MatTableDataSource(employeeList);
        this.dataSource2.paginator = this.paginator2;
        this.dataSource2.sort = this.sort2;
        this.pageLoading = false;
      } else {
        this.dataSource2 = new MatTableDataSource(employeeList);
        this.dataSource2.paginator = this.paginator;
        this.dataSource2.sort = this.sort;
        this.pageLoading = false;

      }
    });
  }


  initEmployeeFormArray() {
    this.employeeArray = this.employeeForm.get('employees') as FormArray;
    this.employeeArray.clear();

    if (this.dataSource?.data) {
      this.dataSource.data.forEach((employee: any) => {
        this.employeeArray.push(this.fb.group({
          empid: employee.id,
          empname: employee.employee_name,
          insurenceAmount: ['']
        }));
      });
    }
  }

  isRowSelected(row: any): boolean {

    return this.selectedEmployeesList.some(selected => selected.id === row.id);
  }


  toggleRowSelection(row: any): void {
    const index = this.selectedEmployeesList.findIndex(selected => selected.id === row.id);
    if (index === -1) {
      this.selectedEmployeesList.push(row);
    } else {
      this.selectedEmployeesList.splice(index, 1);
    }
    this.selection.toggle(row);
  }

  getAmountControler(empid: any): FormControl | any {
    const employeesFormArray = this.employeeForm.get('employees') as FormArray;
    const formGroup = employeesFormArray.controls.find(control =>
      control.get('empid')?.value === empid
    );

    return formGroup ? (formGroup.get('insurenceAmount') as FormControl) : null;
  }


  isFormValid(): boolean {
    const employeesFormArray = this.employeeForm.get('employees') as FormArray;
    if (this.selectedEmployeesList.length === 0) return false;
    for (let selected of this.selectedEmployeesList) {
      const formGroup = employeesFormArray.controls.find(control =>
        control.get('empid')?.value === selected.id

      );
      if (formGroup) {
        const amountControler = formGroup.get('insurenceAmount');
        if (!amountControler ||
          amountControler.invalid ||
          amountControler.value === null ||
          amountControler.value === '' ||
          isNaN(Number(amountControler.value))) {
          return false;
        }
      } else {
        return false;
      }
    }
    return true;
  }


  masterToggle() {
    if (this.isSomeSelected()) {
      this.selection.clear();
      this.selectedEmployeesList = []
    } else {
      this.isAllSelected()
        ? this.selection.clear()
        : this.dataSource.data.forEach((row: any) => this.selection.select(row));
      this.selectedEmployeesList = this.dataSource.data.slice();
    }
  }

  isSomeSelected() {
    return this.selection.selected.length > 0;
  }

  isAllSelected() {
    const numSelected = this.selection.selected.length;
    const numRows = this.dataSource.data.length;
    return numSelected === numRows;
  }
  onSubmit() {

    if (this.employeeForm.valid) {
      if (this.selectedEmployeesList.length > 0) {
        if (this.btnDisable) {
          return;
        }
        if (this.isFormValid()) {
          const employeesFormArray = this.employeeForm.get('employees') as FormArray;
          const submittedData = this.selectedEmployeesList.map(selected => {
            const formGroup = employeesFormArray.controls.find(control =>
              control.get('empid')?.value === selected.id
            );

            return {
              emp_id: selected.id,
              amount: Number(formGroup?.get('insurenceAmount')?.value)
            };
          });

          let obj = {
            emp_amounts_array: JSON.stringify(submittedData),
            user_id_value: this.UserSession.id,
          };
          this.btnDisable = true;
          this.setHealthInsuranceAmounts(obj)
        }
        else {
          this.dialog.open(ReusableDialogComponent, {
            position: { top: `70px` },
            disableClose: true,
            data: 'Please enter insurance pay amount.',
          });
          return;
        }

      } else {
        this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: 'Select atleast one employee.',
        });
      }
    }

  }
  setHealthInsuranceAmounts(obj: any) {
    this.payroll.setHealthInsuranceAmounts(obj).subscribe((res: any) => {
      if (res.status && res.data[0].successState === 0) {
        this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: 'Insurance amount submitted successfully.',
        });
        this.btnDisable = false;
        this.cancel();
      } else {
        this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: 'Unable to save data.',
        });
        this.btnDisable = false;
      }
    })
  }
  save(row: any) {

    if (this.employeeForm.valid) {
      if (Number(row.deductible_amount) !== Number(this.editForm.controls.insuranceAmt.value)) {
        let submittedData = [{
          emp_id: row.employee_id,
          amount: Number(this.editForm.controls.insuranceAmt.value)
        }]
        let obj = {
          emp_amounts_array: JSON.stringify(submittedData),
          user_id_value: this.UserSession.id,
        };
        this.setHealthInsuranceAmounts(obj)
      } else {
        this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: 'Please change the value to edit insurance amount.',
        });
      }

    }
  }
  editRow(data: any) {
    this.enable = data.employee_id;
    let amount = data.deductible_amount.slice(0, -3)
    this.editForm.controls.insuranceAmt.setValue(amount)
  }

  deleteRow(data: any) {

    let payload = {
      id_value: data.id,
      updated_by_value: this.UserSession.id
    }
    this.payroll.deleteEmpFromHealthInsurance(payload).subscribe((res: any) => {
      if (res.status) {
        this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: 'Insurance amount deleted successfully.',
        });
        this.getInsurenceEmployeeDetails()
      } else {
        this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: 'Unable to delete.',
        });
      }
    })
  }


  canceledit() {
    this.enable = null;

  }
  cancel() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/Payroll/healthInsurance']));
  }


  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.dataSource2.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource2.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource2.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource2.data.length);
    return customPageSizeArray;
  }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
      this.employeeArray = this.employeeForm.get('employees') as FormArray;
      this.employeeArray.clear();
      if (this.dataSource?.filteredData) {
        this.dataSource.filteredData.forEach((employee: any) => {
          this.employeeArray.push(this.fb.group({
            empid: employee.id,
            empname: employee.employee_name,
            insurenceAmount: ['']
          }));
        });

      }
    }
    this.dataSource2.filter = filterValue.trim().toLowerCase();
    if (this.dataSource2.paginator) {
      this.dataSource2.paginator.firstPage();
    }
  }

  getPageSizes2() {
    var customPageSizeArray = [];
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;

  }

}
