import { DatePipe } from '@angular/common';
import { Component, ElementRef, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, FormControl, FormGroup, Validators  } from '@angular/forms';
import { MatDialog } from '@angular/material/dialog';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { ReportsService } from '../../reports.service';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';

import * as _moment from 'moment';
import * as pdfMake from "pdfmake/build/pdfmake";
import { ShiftEmployeesDialogComponent } from '../shift-employees-dialog/shift-employees-dialog.component';
import { NgxSpinnerService } from 'ngx-spinner';
import { ExcelExportService } from 'src/app/services/excel-export.service';

const moment = _moment;

export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};
@Component({
  selector: 'app-shifts-wise-report',
  templateUrl: './shifts-wise-report.component.html',
  styleUrls: ['./shifts-wise-report.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },
    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class ShiftsWiseReportComponent implements OnInit {

  constructor(public reportsService: ReportsService, public datePipe: DatePipe,
    public formBuilder: FormBuilder, public dialog: MatDialog,
    private excelExportService: ExcelExportService, private reportService: ReportsService, private spinner: NgxSpinnerService) { }

  List: any[] = [];
  employeelist: any;
  Users: any;
  minDate = new Date('2020/01/01');
  maxDate = new Date();
  minFromDate = new Date('2020/01/01');
  minToDate = this.maxDate;
  userSession: any;
  headersList: any = [];
  @ViewChild('table') table!: ElementRef;

  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort) sorter!: MatSort;
  filter = new FormControl();
  shiftReportForm: any = FormGroup;

  shiftDataList: any = [];
  employeesList: any = [];
  headerlist: any = [];
  rmId: any;
  companyName: any;
  ngOnInit() {
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    this.companyName = sessionStorage.getItem('companyFullName');
    this.rmId = this.userSession.id;
    this.shiftReportForm = this.formBuilder.group(
      {
        fromDate: [new Date()],
        toDate: [new Date(),  Validators.required],
       

      });
    this.shiftReportForm.get('fromDate')?.valueChanges.subscribe((selectedValue: any) => {
      if (selectedValue != null) {
        // this.shiftReportForm.get('toDate')?.reset();
        this.minToDate = selectedValue;
      }
      const toDate = this.shiftReportForm.get('toDate')?.value;
      // Clear toDate if it's before fromDate
      if (toDate && new Date(toDate) < new Date(selectedValue)) {
        this.shiftReportForm.get('toDate')?.setValue(null);
      }
    })
    this.getShiftWiseReportList();
  }

  Searchform() {
    this.getShiftWiseReportList();
  }

  getShiftWiseReportList() {
       if (this.shiftReportForm.invalid) {
    this.shiftReportForm.markAllAsTouched(); // show validation errors
    return; // stop API call
  }
    this.shiftDataList = [];
    let fromDate = this.datePipe.transform(this.shiftReportForm.controls.fromDate.value, "y-MM-d");
    let toDate = this.datePipe.transform(this.shiftReportForm.controls.toDate.value, "y-MM-d");
    let data = {
      "rm_id_value": this.rmId,
      "from_date_value": fromDate,
      "to_date_value": toDate,
    }
    this.spinner.show();
    this.reportService.getShiftsWiseEmployeesCountsByDates(data).subscribe((res) => {
      if (res.status) {
        this.shiftDataList = res.data;
        // this.headersList.push(this.shiftDataList[0]);
         this.headersList = [ this.shiftDataList[0] ];
        // this.headersList.slice(1);
        this.spinner.hide();
      } else {
        this.shiftDataList = [];
        this.spinner.hide();
      }
      this.spinner.hide();
    })
  }

  getObjectKeys(obj: any): string[] { return Object.keys(obj); }

  view(data: any) {
    let givenData = {
      "rm_id_value": this.rmId,
      "date_value": data,
    }
    let dialogRef = this.dialog.open(ShiftEmployeesDialogComponent, {
      width: '800px', position: { top: `100px` },
      disableClose: true,
      data: givenData

    });

  }


  resetform() {
    this.shiftReportForm.reset();
    this.shiftReportForm.controls.fromDate.setValue(new Date());
    this.shiftReportForm.controls.toDate.setValue(new Date());
    this.Searchform();
  }

  removeLastColumn(table: HTMLTableElement): void {
    const rows = table.querySelectorAll('tr');
    rows.forEach((row) => {
      const cells = row.querySelectorAll('td, th');
      if (cells.length > 0) {
        const lastCell = cells[cells.length - 1];
        row.removeChild(lastCell);
      }
    });
  }


  public exportPDF(): void {
    let fdate = (this.datePipe.transform(this.shiftReportForm.controls.fromDate.value, "dd-MM-YYYY"));
    let tdate = (this.datePipe.transform(this.shiftReportForm.controls.toDate.value, "dd-MM-YYYY"));

    const pdfTable = this.table.nativeElement;
    this.removeLastColumn(pdfTable);

    const headers: any = [];
    pdfTable.querySelectorAll('thead tr th').forEach((header: HTMLElement) => {
      headers.push({ text: header.innerText, bold: true, fillColor: '#eeeeee', alignment: 'center', fontSize: 9, margin: [1, 3, 1, 3], noWrap: false  });
    });

    const body: any = [];
    pdfTable.querySelectorAll('tbody tr').forEach((row: HTMLElement) => {
      const dataRow: any = [];
      row.querySelectorAll('td').forEach((cell: HTMLElement) => {
        dataRow.push({ text: cell.innerText, alignment: 'center', fontSize: 9, noWrap: false,  margin: [1, 2, 1, 2] });
      });
      body.push(dataRow);
    });
    const tableBody = [headers, ...body];

    // Create PDF using pdfMake
    pdfMake.createPdf({
      info: {
        title: `${fdate} To ${tdate} - Shift Wise Report`,
        author: 'Sreeb tech',
        subject: 'Theme',
        keywords: 'Report'
      },
      footer: function (currentPage, pageCount) {
        return {
          margin: 10,
          columns: [
            {
              fontSize: 8,
              text: 'Page ' + currentPage.toString() + ' of ' + pageCount,
              alignment: 'center'
            }
          ]
        };
      },
      content: [
        {
          columns: [
            { text: this.companyName, style: 'title', alignment: 'center', fontSize: 12 },

          ],
        },
        {
          columns: [
            // { text: 'Shift Wise Report', style: 'subtitle', alignment: 'left', margin: [0, 5, 0, 10] },
            // { text: `Date: ${fdate} to ${tdate} `, style: 'subtitle', alignment: 'right' },
              { text: 'Shift Wise Report', bold: true, fontSize: 10, alignment: 'left', margin: [0, 5, 0, 10] },
             { text: `Date: ${fdate} to ${tdate}`, fontSize: 10, alignment: 'right' }
        
          ],

        },
        {
          canvas: [{ type: 'line', x1: 0, y1: 0, x2: 1000, y2: 0, lineWidth: 1, },],
        }, '\n',
        // {
        //   text: `${fdate} To ${tdate} - Shift Wise Report \n\n`,
        //   style: 'header',
        //   alignment: 'center',
        //   fontSize: 14
        // },
        {
          table: {
            widths: Array(headers.length).fill('*'),  // Makes columns fill the width equally
            body: tableBody  // Uses manually created table content
          },
          layout: {
            hLineWidth: function (i, node) {
              return (i === 0 || i === node.table.body.length) ? 2 : 1;
            },
            vLineWidth: function (i) {
              return 1;
            },
            hLineColor: function (i) {
              return 'black';
            },
            vLineColor: function (i) {
              return 'black';
            }
          }
        //     layout: {
        //   hLineWidth: () => 0.5,
        //   vLineWidth: () => 0.5,
        //   hLineColor: () => 'black',
        //   vLineColor: () => 'black'
        // }
        }
      ],
      // styles: {
      //   header: {
      //     bold: true,
      //     fontSize: 14,
      //     margin: [0, 0, 0, 10]
      //   }
      // },
      pageOrientation: 'landscape',
      // pageSize: "EXECUTIVE"
      pageSize: "A3"
    }).download("Shift_Wise_Report.pdf");

    this.Searchform();
  }



  exportToExcel(): void {
    // Add S.No to each row in shiftDataList
    const dataToExport = this.shiftDataList.map((item: any, index: any) => ({
      'S.No': index + 1, // Adding S.No starting from 1
      ...item            // Spread the rest of the object properties
    }));
    this.excelExportService.exportAsExcelFile(dataToExport, 'Shift Wise Report');
  }


}
