 /** */
  isAllSelected() {
    const numSelected = this.selection.selected.length;
    const numRows = this.dataSource.data.length;
    return numSelected === numRows && numRows > 0;
  }
/** */
  isFormValid(): boolean {
    if (!this.searchForm.get('companylocation')?.valid || !this.searchForm.get('fromDate')?.valid) {
      return false;
    }
    const employeesFormArray = this.searchForm.get('employees') as FormArray;

    if (this.selectedEmployeesList.length === 0) return false;

    for (let selected of this.selectedEmployeesList) {
      const formGroup = employeesFormArray.controls.find(control =>
        control.get('employeeId')?.value === selected.employeeId
      );
      if (formGroup) {
        const tdsAmountControl = formGroup.get('tdsAmount');
        if (!tdsAmountControl ||
          tdsAmountControl.invalid ||
          isNaN(Number(tdsAmountControl.value))) {
          return false;
        }
      } else {
        return false;
      }
    }
    return true;
  }
/** */
  toggleRowSelection(row: any): void {
  if (this.selection.isSelected(row)) {
    this.selection.deselect(row);
  } else {
    this.selection.select(row);
  }
}

