  /**Add Speial Allowances */
  submitSpecialAllowance() {
    if (this.allowanceForm.valid) {
      const allowanceValue = this.allowanceForm.controls.allowance.value.trim().toLowerCase();
      const allowanceExists = this.allowanceList.some((cc: any) => cc.allowance_name.trim().toLowerCase() === allowanceValue);

      if (allowanceExists) {
        let dialogRef = this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: 'Allowane already exists'
        });
        return;
      }
      const payload = {
        id_value: this.isEditallowance ? this.id : null,
        allowance_name_value: this.allowanceForm.controls.allowance.value.trim(),
        ibld_value: this.selectedAllownceType.toString(),
        status_value:1,
        created_by_value: this.userSession.id,
      };
      this.payrollService.setSpecialAllowance(payload).subscribe((response: any) => {

        if (response.status) {
          console.log("response.data.message",response.data.message)
            let dialogRef = this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data:response.data[0].message
            });
            this.allowanceForm.reset();
            this.getallowance()
            // this.reset();
 
        }

      });
    }
    else {

      this.allowanceForm.markAllAsTouched();
    }

  }
 
