/**Employee Allowance Mapping */
submit() {
  const allowanceId = this.searchForm.get('allowance')?.value;
  const cityBranchId = this.searchForm.get('companylocation')?.value;
  const selectedEmployees = this.selection.selected.map(row => ({
    emp_id: row.employee_id || row.id,
    amount: row.amount ? Number(row.amount) : 0
  }));
  if (!allowanceId) {
    alert("Please select Allowance");
    return;
  }
  if (!cityBranchId) {
    alert("Please select City - Branch");
    return;
  }
  if (selectedEmployees.length === 0) {
    let dialogRef = this.dialog.open(ReusableDialogComponent, {
      position: { top: `70px` },
      disableClose: true,
      data: 'Please Select atleaset one employee.'
    });
    return;
  }
  /** CHECK IF ANY EMPLOYEE HAS amount = 0, null, or empty String */ 
  const hasInvalidAmount = selectedEmployees.some(e => !e.amount || e.amount === 0);
  if (hasInvalidAmount) {
    let dialogRef = this.dialog.open(ReusableDialogComponent, {
      position: { top: `70px` },
      disableClose: true,
      data: 'Please enter amount for all selected employees'
    });
    return;
  }

let body = {
  mapping_data: JSON.stringify({
    mapping_data: selectedEmployees.map(item => ({
      ...item,
      psam_id: allowanceId
    }))
  }),
  created_by_value: this.userSession.id
};

   this.payrollService.SetEmployeeSpecialAllowanceDetails(body).subscribe((result: any) => {
      let dialogRef = this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data:result.data[0].message
            });
            this.reset();
    
   })

}


  isSubmitDisabled(): boolean {
    const formValid = this.searchForm?.valid;
    const hasEmployeesSelected = this.selectedEmployeesList.length > 0;
    const hasDataInTable = this.dataSource.data.length > 0;

    return !formValid || !hasEmployeesSelected || !hasDataInTable;
  }
  /**Allowance edit oprion */
  editallowance(row: any) {
    this.isEditallowance = true;
    this.id = row.id;
    this.allowanceList.forEach((sa: any) => {
      if (sa.allowance_name === row.allowance_name) {
        this.allowanceList.splice(this.allowanceList.indexOf(sa), 1);
      }
    });

    this.allowanceForm.patchValue({
      allowance: row.allowance_name,
    });
  }


