/** */
onAmountChange(event: any, row: any) {
  const amount = Number(event.target.value);
  const id = row.employee_code || row.employee_id || row.emp_id || row.id;
  const index = this.dataSource.data.findIndex(
    (emp: any) =>
      (emp.employee_code || emp.employee_id || emp.emp_id || emp.id) === id
  );
  if (index !== -1) {
    this.dataSource.data[index].amount = amount;  // update table dataset
    row.amount = amount; // update UI row also
  }
  console.log("Updated Row:", this.dataSource.data[index]);
}

/** Allowing Only Numers */
allowNumbersAndDecimal(event: KeyboardEvent) {
  const char = event.key;

  // allow digits, decimal point, backspace
  if (!/[\d\.]/.test(char) && char !== 'Backspace') {
    event.preventDefault();
  }

  // allow only one decimal point
  const input = event.target as HTMLInputElement;
  if (char === '.' && input.value.includes('.')) {
    event.preventDefault();
  }
}


