        days = Math.floor(diff / (60 * 60 * 24 * 1000));
        hours = Math.floor(diff / (60 * 60 * 1000)) - (days * 24);
        minutes = Math.floor(diff / (60 * 1000)) - ((days * 24 * 60) + (hours * 60));

