  getExtradaysAndPenaltiesReport(data: any): Observable<any> {
    data.companyName = this.getCompany();
    const encryptedPayload = this.encryptData(data);
    return this.http.post(this.mainUrl + 'attendanceApi/getExtradaysAndPenaltiesReport', { encryptedData: encryptedPayload }, this.httpOptions);
  }

  encryptData(data: any): string {
    const secretKey = "a3fcb1234b5c6d789e0f12a3b4567890a3fcb1234b5c6d789e0f12a3b4567890";
    const encryptedData = CryptoJS.AES.encrypt(JSON.stringify(data), secretKey).toString();
    return encryptedData;
  }

