  is_modulename_present(modulename: any) {
      let menuList:any = sessionStorage.getItem("moduleData");
      let is_module_present = false;
      if(menuList && menuList.toString().length) {
         menuList = JSON.parse(menuList);
        if(menuList && menuList.length){
          menuList.forEach((m:any) => {
            let m_name = m.modulename?.toString().toLowerCase().replace('management','').replace(' ','').trim();
            if(!is_module_present && modulename.toString().toLowerCase().trim() == m_name) is_module_present = true;            
          });
        }
      }
      return is_module_present;   
  }
    is_module_present(moduleid: any) {
      let menuList:any = sessionStorage.getItem("moduleData");
      let is_module_present = false;
      if(menuList && menuList.toString().length) {
         menuList = JSON.parse(menuList);
        if(menuList && menuList.length){
          menuList.forEach((m:any) => {             
            if(!is_module_present && moduleid == m.id) is_module_present = true;            
          });
        }
      }
      return is_module_present;   
  }

  getModuleName(moduleid:any){
     let menuList:any = sessionStorage.getItem("moduleData");
     let module_name:any = null;
      if(menuList && menuList.toString().length) {
         menuList = JSON.parse(menuList);
        if(menuList && menuList.length){
          menuList.forEach((m:any) => {             
            if(!module_name && moduleid == m.id) module_name = m.modulename;            
          });
        }
      }
      return module_name; 
  }
