import { Component, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, FormControl, FormGroup, UntypedFormGroup, Validators } from '@angular/forms';
import { MatDialog } from '@angular/material/dialog';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { Router } from '@angular/router';
import { PayrollService } from 'src/app/modules/payroll/payroll.service';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';

@Component({
  selector: 'app-deductions-reimbursements',
  templateUrl: './deductions-reimbursements.component.html',
  styleUrls: ['./deductions-reimbursements.component.scss']
})
export class DeductionsReimbursementsComponent implements OnInit {


  pageLoading = true;
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort) sort!: MatSort;
  reimbursementForm!: UntypedFormGroup;
  dataSource: MatTableDataSource<any> = <any>[];
  displayedColumns = ['sno', 'componentName', 'deductions', 'reimbursements', 'duration']
  btnDisable: boolean = false;
  userSession: any;
  searchControl = new FormControl('');
  deductionList: any[] = []


  constructor(
    private formBuilder: FormBuilder,
    private payrollService: PayrollService,
    private router: Router,
    private dialog: MatDialog
  ) { }

  ngOnInit(): void {
    this.reimbursementForm = this.formBuilder.group(
      {
        componentName: ["", [Validators.required]],
        months: ["", [Validators.required]],
        deduction: [""],
        reimbursement: [""],
      })
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    this.getDeductionsAndReimbursements();
    this.searchControl.valueChanges.subscribe(searchText => {
      if (Number(searchText) > 24) {
        this.reimbursementForm.controls.months.setValue('');
        this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: 'Please enter months less than or equal to 24.'
        });

      } else {
        this.reimbursementForm.controls.months.setValue(searchText)
      }
    });
  }

  getInvalidControls(form: FormGroup): string[] {
    const invalid = [];
    const controls = form.controls;
    for (const name in controls) {
      if (controls[name].invalid) {
        invalid.push(name);
      }
    }
    return invalid;
  }

  edit(row: any) {

  }
  cancel() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Payroll/reimbursements"]));
  }
  setDeductionAndDisbursements() {
    if (this.reimbursementForm.valid) {
      let componentName = this.reimbursementForm.controls.componentName.value;
      if (this.deductionList.includes(componentName)) {
        this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: 'This component name already exists. Please enter a different component name.'
        });
        return;
      }
      if (!this.reimbursementForm.controls.deduction.value && !this.reimbursementForm.controls.reimbursement.value) {
        this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: 'Please select at least one option between Deduction and Reimbursement.'
        });
        return;
      }
      if ((this.reimbursementForm.controls.deduction.value && this.reimbursementForm.controls.reimbursement.value) || (this.reimbursementForm.controls.deduction.value && !this.reimbursementForm.controls.reimbursement.value)) {
        let data = {
          id_value: null,
          component_name_value: this.reimbursementForm.controls.componentName.value,
          d_enabled: this.reimbursementForm.controls.deduction.value ? 1 : 0,
          r_enabled: this.reimbursementForm.controls.reimbursement.value ? 1 : 0,
          months_value: Number(this.reimbursementForm.controls.months.value),
          updated_by_value: this.userSession.id,
        }
        this.payrollService.setDeductionsAndDisbursements(data).subscribe((res: any) => {
          if (res.status) {
            this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: res.data[0].message
            });
            this.cancel()
          }
        })
      } else if (!this.reimbursementForm.controls.deduction.value && !this.reimbursementForm.controls.reimbursement.value) {
        this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: 'Deduction should be selected.'
        });
      } else if (!this.reimbursementForm.controls.deduction.value && this.reimbursementForm.controls.reimbursement.value) {
        this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: 'Reimbursement cannot be selected without selecting Deduction.'
        });
      }

    } else {
      console.log(this.getInvalidControls(this.reimbursementForm));
    }

  }
  getDeductionsAndReimbursements() {
    this.payrollService.getDeductionsAndReimbursements().subscribe((res: any) => {
      res.data.forEach((element: any) => {
        this.deductionList.push(element.component_name)
      });

      this.dataSource = new MatTableDataSource(res.data);
      this.dataSource.paginator = this.paginator;
      this.dataSource.sort = this.sort;
      this.pageLoading = false;

    })
  }

  getPageSizes(): number[] {
    var customPageSizeArray = [];

    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);

    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }
  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }

  }

}
