  message(message: any) {
    this.dialog.open(ReusableDialogComponent, {
      position: { top: `70px` },
      disableClose: true,
      data: message,
    });
  }

  openDialog(record:any): void {
    const dialogRef = this.dialog.open(ReviewAndApprovalsComponent, {
      width: '600px',position:{top:`100px`},
      data: {name: "Reason For Rejection", reason: '',}
    });

    dialogRef.afterClosed().subscribe(result => {
      if(result){
        record.status = 'Rejected'
        this.getEmployeesTdsDeductionExemptionApproveHistory(record)
      }
    });
  }
  historyData:any=[];
  getEmployeesTdsDeductionExemptionApproveHistory(record:any){
    this.data = this.data.filter((item:any) => item.s_no !== record.s_no);
    this.dataSource.data = this.data
    this.historyData.push(record)
    this.historyDataSource = new MatTableDataSource(this.historyData);
    this.pageHistoryLoading=false;
    this.historyDataSource.paginator = this.HistoryPaginator
    this.historyDataSource.sort = this.historySort
  }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.historyDataSource.filter = filterValue.trim().toLowerCase();
    this.dataSource.filter = filterValue.trim().toLowerCase();
  
    if (this.historyDataSource.paginator) {
      this.historyDataSource.paginator.firstPage();
    }
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }
