  private parseTimeToMinutes(v: string | null | undefined): number | null {
    if (!v) { return null; }
    // Match HH:MM format. This is the only format our validator uses.
    const m = (v || '').toString().trim().match(/^(\d{1,2}):(\d{2})$/);
    if (!m) { return null; }
    const hh = parseInt(m[1], 10);
    const mm = parseInt(m[2], 10);
    if (isNaN(hh) || isNaN(mm)) { return null; }
    return hh * 60 + mm;
  }
