  /**
   * VALIDATOR
   * This validator places errors on minProductiveHalf and minProductiveFull,
   * but NOT on totalHours.
   */
  productiveTimesValidator(group: AbstractControl): ValidationErrors | null {
    const halfCtrl = group.get('minProductiveHalf');
    const fullCtrl = group.get('minProductiveFull');
    const totalCtrl = group.get('totalHours');

    if (!halfCtrl || !fullCtrl || !totalCtrl) {
      return null;
    }

    // Helper to clear errors
    const clearError = (ctrl: AbstractControl, key: string) => {
      if (ctrl.hasError(key)) {
        const errors = { ...ctrl.errors };
        delete errors[key];
        ctrl.setErrors(Object.keys(errors).length ? errors : null);
      }
    };

    // --- Reset all our custom errors ---
    clearError(halfCtrl, 'notLessThanTotal');
    clearError(halfCtrl, 'notLessThanFull');
    clearError(fullCtrl, 'greaterThanTotal');
    clearError(fullCtrl, 'lessOrEqualHalf');
    // Clear errors from totalHours (we will never set them)
    clearError(totalCtrl, 'notGreaterThanHalf');
    clearError(totalCtrl, 'notGreaterThanFull');


    // Get values
    const halfMin = this.parseTimeToMinutes(halfCtrl.value);
    const fullMin = this.parseTimeToMinutes(fullCtrl.value);
    // .value gets the value even if the control is disabled
    const totalMin = this.parseTimeToMinutes(totalCtrl.value);

    // --- Apply Validation Rules ---

    // Rule 1: minProductiveFull > minProductiveHalf (Error if full <= half)
    if (halfMin !== null && fullMin !== null) {
      if (fullMin <= halfMin) {
        fullCtrl.setErrors({ ...(fullCtrl.errors || {}), lessOrEqualHalf: true });
      }
      if (halfMin >= fullMin) {
        halfCtrl.setErrors({ ...(halfCtrl.errors || {}), notLessThanFull: true });
      }
    }

    // Check against totalHours only if it has a value
    if (totalMin !== null) {

      // Rule 2: totalHours >= minProductiveFull (Error if full > total)
      // Error is ALWAYS set on fullCtrl
      if (fullMin !== null && fullMin > totalMin) {
        fullCtrl.setErrors({ ...(fullCtrl.errors || {}), greaterThanTotal: true });
      }

      // Rule 3: totalHours > minProductiveHalf (Error if half >= total)
      // Error is ALWAYS set on halfCtrl
      if (halfMin !== null && halfMin >= totalMin) {
        halfCtrl.setErrors({ ...(halfCtrl.errors || {}), notLessThanTotal: true });
      }
    }

    return null;
  }


  onMinProductiveHalfInput(event: Event) {
    const input = event.target as HTMLInputElement;
    if (!input) { return; }

    // Prevent editing if totalHours not set
    // Use .value to check disabled control
    const totalHoursVal = this.shiftForm?.get('totalHours')?.value;
    if (!totalHoursVal) {
      this.dialog.open(ReusableDialogComponent, {
        position: { top: `70px` },
        disableClose: true,
        data: 'Please select Start Time and End Time first.',
      });
      input.value = '';
      this.shiftForm?.get('minProductiveHalf')?.setValue('', { emitEvent: false });
      return;
    }

    // keep only digits, limit to 4 digits (HHMM)
    let digits = (input.value || '').replace(/\D/g, '').slice(0, 4);

    // build formatted value, insert ":" after 2 digits
    let formatted = digits;
    if (digits.length > 2) {
      formatted = digits.slice(0, 2) + ':' + digits.slice(2);
    }

    // update visible input and form control without triggering additional valueChanges
    input.value = formatted;
    this.shiftForm?.get('minProductiveHalf')?.setValue(formatted, { emitEvent: false });
    this.shiftForm?.get('minProductiveHalf')?.setErrors(null);
  }
