  /**
   * CORRECTED getDifference
   * Sets value in HH:MM format
   */
  getDifference(start: any, stop: any) {
    if (!this.flexibleShift) {
      // getting startTime timestamp:
      let startTimestamp = this.getTimestamp(start);
      // getting stopTime timestamp:
      let stopTimestamp = this.getTimestamp(stop);
      // getting the difference
      let differenceInSecs = stopTimestamp - startTimestamp;

      // Format as HH:mm:ss
      let inHhMmSsFormat = new Date(differenceInSecs * 1000)
        .toISOString()
        .slice(11, 19); // "08:00:00"

      // --- THIS IS THE FIX ---
      // Slice to HH:MM format ("08:00") so the validator can parse it
      let inHhMmFormat = inHhMmSsFormat.slice(0, 5);

      // Set the "08:00" value, which will trigger the group validator
      this.shiftForm.controls.totalHours.setValue(inHhMmFormat);
    } else {
      this.shiftForm.controls.totalHours.enable();
    }
  }

  getTimestamp(time: any) {
    let timeFirst = time.split(', ')[0].split('/');
    let timeY = timeFirst[2];
    let timeM = timeFirst[1];
    let timeD = timeFirst[0];
    let timeSecond = time.split(', ')[1];
    let timestamp =
      new Date(
        Date.parse(
          timeY + '-' + timeM + '-' + timeD + ' ' + timeSecond + '+0000'
        )
      ).getTime() / 1000;
    return timestamp;
  }
