  /**
   * SHIFT TYPE CHANGE HANDLER
   * Added updateValueAndValidity() to trigger re-validation
   */
  onShiftTypeChange(event: any) {
    this.shiftForm.controls.totalHours.setValue('');
    this.shiftType = Number(event.value || 0);
    let time = new Date();
    time.setHours(0, 0, 0, 0);
    if (event.value === '3') {
      const postCtrl = this.shiftForm.get('postShiftWindow');
      postCtrl?.clearValidators();
      postCtrl?.updateValueAndValidity();
      const pretCtrl = this.shiftForm.get('preShiftWindow');
      pretCtrl?.clearValidators();
      pretCtrl?.updateValueAndValidity();
      const graceInCtrl = this.shiftForm.get('graceInTime');
      graceInCtrl?.clearValidators();

      const graceOutCtrl = this.shiftForm.get('graceOutTime');
      graceOutCtrl?.clearValidators();

      this.shiftForm.get('startTime')?.setValue(time);
      this.shiftForm.get('startTime')?.disable();
      this.shiftForm.get('endTime')?.setValue(time);
      this.shiftForm.get('endTime')?.disable();

      this.shiftForm.get('startTime')?.clearValidators();
      this.shiftForm.get('endTime')?.clearValidators();

      const totalCtrl = this.shiftForm.get('totalHours');
      totalCtrl?.setErrors(null);
      totalCtrl?.enable(); // <-- ENABLES for flexible

    }
    else if (event.value === '2') {

      // This is FLEXIBLE shift logic
      this.flexibleShift = true;
      const postCtrl = this.shiftForm.get('postShiftWindow');
      postCtrl?.setValidators([Validators.required]);
      postCtrl?.updateValueAndValidity();

      const pretCtrl = this.shiftForm.get('preShiftWindow');
      pretCtrl?.clearValidators();
      pretCtrl?.updateValueAndValidity();

      const graceInCtrl = this.shiftForm.get('graceInTime');
      graceInCtrl?.clearValidators();
      graceInCtrl?.updateValueAndValidity();

      const graceOutCtrl = this.shiftForm.get('graceOutTime');
      graceOutCtrl?.clearValidators();
      graceOutCtrl?.updateValueAndValidity();

      // enable manual entry of totalHours for flexible shifts
      const totalCtrl = this.shiftForm.get('totalHours');
      totalCtrl?.enable(); // <-- ENABLES for flexible
      totalCtrl?.setValidators([Validators.required, this.totalHoursValidator]); // Add specific validator
      totalCtrl?.setValue('', { emitEvent: false });
      totalCtrl?.setErrors(null);
      this.shiftForm.get('startTime')?.setValue('');
      this.shiftForm.get('startTime')?.enable();

      this.shiftForm.get('endTime')?.setValue('');
      this.shiftForm.get('endTime')?.disable();

      this.shiftForm.get('startTime')?.clearValidators();
      this.shiftForm.get('endTime')?.clearValidators();

    } else {
      this.shiftForm.get('startTime')?.setValue('');
      this.shiftForm.get('startTime')?.enable();

      this.shiftForm.get('endTime')?.setValue('');
      this.shiftForm.get('endTime')?.enable();

      this.shiftForm.get('startTime')?.clearValidators();
      this.shiftForm.get('endTime')?.clearValidators();
      // This is FIXED shift logic
      this.flexibleShift = false;
      const preCtrl = this.shiftForm.get('preShiftWindow');
      preCtrl?.setValidators([Validators.required]);
      preCtrl?.updateValueAndValidity();

      const postCtrl = this.shiftForm.get('postShiftWindow');
      postCtrl?.clearValidators();
      postCtrl?.updateValueAndValidity();

      const totalCtrl = this.shiftForm.get('totalHours');

      // Re-disable the control when switching back to a fixed shift
      totalCtrl?.disable(); // <-- DISABLES for fixed
      totalCtrl?.setValidators([Validators.required]); // It's still required, but will be auto-filled
      totalCtrl?.clearValidators(); // Clear specific validators

    }

    // --- THIS IS KEY ---
    // Force the whole form to re-validate
    this.shiftForm.updateValueAndValidity();
  }

  onStartTimeSelected(event: any) {
    const shiftType = this.shiftForm.get('shiftType')?.value;
    if (!shiftType) {
      const msg = 'Please select shift type';
      this.dialog.open(ReusableDialogComponent, {
        position: { top: `70px` },
        disableClose: true,
        data: msg,
      });
      this.shiftForm.get('startTime')?.setValue('');
      return;
    } else {
      if (shiftType === '2') {
        const startValue = this.shiftForm.get('startTime')?.value ?? event?.value ?? event;
        if (!startValue) {
          return;
        }
        const startDate = new Date(startValue);
        // subtract one minute
        const endDate = new Date(startDate.getTime() - 60 * 1000);

        // set endTime to one minute less and disable the control
        this.shiftForm.get('endTime')?.setValue(endDate);
        this.shiftForm.get('endTime')?.disable();

        // update internal formatted strings and totalHours calculation
        const startStr = this.pipe.transform(startDate, 'dd/MM/yyyy, HH:mm:ss');
        const endStr = this.pipe.transform(endDate, 'dd/MM/yyyy, HH:mm:ss');
        this.starttime = startStr;
        this.endtime = endStr;
        this.getDifference(startStr, endStr);

      }

    }
  }

  onMinProductiveHalfBlur() {
    const control = this.shiftForm?.get('minProductiveHalf');
    if (!control) { return; }

    // normalization logic (existing)
    let v = (control.value || '').toString().trim();
    if (!v) {
      // Manually trigger validation update on blur if field is cleared
      this.shiftForm.updateValueAndValidity();
      return;
    }

    const digits = v.replace(/\D/g, '').slice(0, 4);
    let hh = digits.slice(0, 2); let mm = digits.slice(2);
    if (hh.length === 1) { hh = '0' + hh; }
    if (!mm) { mm = '00'; }
    if (mm.length === 1) { mm = mm + '0'; }

    let hhNum = parseInt(hh, 10); let mmNum = parseInt(mm, 10);
    if (isNaN(hhNum)) { hhNum = 0; } if (isNaN(mmNum)) { mmNum = 0; }
    if (hhNum > 23) { hhNum = 23; mmNum = 59; }
    if (mmNum > 59) { mmNum = 59; }

    const normalized = `${hhNum.toString().padStart(2, '0')}:${mmNum.toString().padStart(2, '0')}`;
    control.setValue(normalized, { emitEvent: false });

    // trigger form-level validation
    this.shiftForm.updateValueAndValidity({ onlySelf: false, emitEvent: false });
  }


