  totalHoursValidator(control: AbstractControl): ValidationErrors | null {
    const v = (control.value || '').toString().trim();
    if (!v) { return null; }
    // This regex only matches HH:MM
    const match = v.match(/^(\d{1,2}):(\d{2})$/);
    if (!match) { return { invalidTime: true }; }
    const hh = parseInt(match[1], 10);
    const mm = parseInt(match[2], 10);
    if (isNaN(hh) || isNaN(mm)) { return { invalidTime: true }; }
    if (hh < 0 || hh > 24) { return { invalidTime: true }; }
    if (mm < 0 || mm > 59) { return { invalidTime: true }; }
    if (hh === 24 && mm !== 0) { return { invalidTime: true }; }
    return null;
  }

  // Called while typing in totalHours input — auto-inserts ":" after 2 digits and restricts to digits
  onTotalHoursInput(event: Event) {
    const input = event.target as HTMLInputElement;
    if (!input) { return; }

    // keep only digits, limit to 4 digits (HHMM)
    let digits = (input.value || '').replace(/\D/g, '').slice(0, 4);

    // build formatted value, insert ":" after 2 digits
    let formatted = digits;
    if (digits.length > 2) {
      formatted = digits.slice(0, 2) + ':' + digits.slice(2);
    }

    input.value = formatted;
    this.shiftForm?.get('totalHours')?.setValue(formatted, { emitEvent: false });
    // clear validation until blur
    this.shiftForm?.get('totalHours')?.setErrors(null);
  }

  // Normalize and validate on blur
  onTotalHoursBlur() {
    const control = this.shiftForm?.get('totalHours');
    if (!control) { return; }

    let v = (control.value || '').toString().trim();
    if (!v) {
      // Manually trigger validation update on blur if field is cleared
      this.shiftForm.updateValueAndValidity();
      return;
    }

    const digits = v.replace(/\D/g, '').slice(0, 4);
    let hh = digits.slice(0, 2);
    let mm = digits.slice(2);

    if (hh.length === 0) { hh = '00'; }
    if (hh.length === 1) { hh = '0' + hh; }
    if (!mm) { mm = '00'; }
    if (mm.length === 1) { mm = mm + '0'; }

    let hhNum = parseInt(hh, 10);
    let mmNum = parseInt(mm, 10);
    if (isNaN(hhNum)) { hhNum = 0; }
    if (isNaN(mmNum)) { mmNum = 0; }

    // clamp minutes
    if (mmNum > 59) { mmNum = 59; }

    // ensure maximum allowed is 24:00 — normalize any >24 or 24:xx to 24:00
    if (hhNum > 24) {
      hhNum = 24;
      mmNum = 0;
    } else if (hhNum === 24 && mmNum > 0) {
      mmNum = 0;
    }

    const normalized = `${hhNum.toString().padStart(2, '0')}:${mmNum.toString().padStart(2, '0')}`;
    control.setValue(normalized, { emitEvent: false });

    // apply validator and trigger form-level validation
    const err = this.totalHoursValidator(control);
    // We only set the specific 'invalidTime' error here
    control.setErrors(err);
    // Re-run the group validator
    this.shiftForm.updateValueAndValidity({ onlySelf: false, emitEvent: false });
    control.markAsTouched();
  }

  onPostShiftWindowInput(event: Event) {
    const input = event.target as HTMLInputElement;
    if (!input) { return; }

    // keep only digits and limit to 4 chars
    let val = (input.value || '').replace(/\D/g, '').slice(0, 4);

    input.value = val;
    this.shiftForm?.get('postShiftWindow')?.setValue(val, { emitEvent: false });
  }

