import { Component, OnInit, ViewChild } from '@angular/core';
import { FormArray, FormBuilder, FormControl, FormGroup, UntypedFormGroup, Validators } from '@angular/forms';
import { MatTableDataSource } from '@angular/material/table';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { UserData } from '../other-deduction/other-deduction.component';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { SelectionModel } from '@angular/cdk/collections';
import { PayrollService } from '../../payroll.service';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { MatDialog } from '@angular/material/dialog';
import { Router } from '@angular/router';
import { TranslateService } from '@ngx-translate/core';

@Component({
  selector: 'app-cost-center-mapping',
  templateUrl: './cost-center-mapping.component.html',
  styleUrls: ['./cost-center-mapping.component.scss']
})
export class CostCenterMappingComponent implements OnInit {
  @ViewChild('firstPaginator') paginator!: MatPaginator;
  @ViewChild('sort1', { static: false }) sort1!: MatSort;
  @ViewChild('sort2', { static: false }) sort2!: MatSort;
  @ViewChild('secondPaginator') paginatorcompleted!: MatPaginator;
  @ViewChild('thirdPaginator') paginator3!: MatPaginator;
  @ViewChild('sort3', { static: false }) sort3!: MatSort;

  searchForm!: UntypedFormGroup;
  costCenterMappingForm!: UntypedFormGroup;
  searchControlforLoc = new FormControl('');
  searchControlforCc = new FormControl('');
  searchControl = new FormControl('');
  worklocationDetails: any[] = [];
  filteredLocations: any = [];
  filteredCompanyLocations: any = [];
  dataSource1: MatTableDataSource<UserData> = <any>[];
  dataSource: MatTableDataSource<UserData> = <any>[];
  dataSource2: MatTableDataSource<UserData> = <any>[];
  companyName: string = localStorage.getItem('companyName') || '';
  selection = new SelectionModel<any>(true, []);
  selectedEmployeesList: any[] = [];
  displayedColumns: string[] = [
    'select',
    'sno',
    'employeeid',
    'empname',
    'FathersName',
    'designation',
    'costcentername'
  ];
  displayedColumns1: string[] = [
    'sno',
    'costCenterName',
    'bankAccount',
    'details',
    'empCount',
    'actions'
  ]

  displayedColumns2: string[] = [
    'sno',
    'empcode',
    'empname',
    'fatherName',
    'designation',
    'currentCostCenter',
    'assignedOn',
    // 'bankname',
    'previousCostCenter',
  ]
  pageLoading = true;
  pageLoading1 = true;
  pageLoading2 = true;
  branchSelected: boolean = true;
  btnDisable: boolean = false;
  filteredBankAccountsList: any = [];
  bankAccountsList: any = [];
  costCenterList: any = [];
  isEditCostCenter: boolean = false;
  filteredCostCenterList: any = [];
  userSession: any = JSON.parse(sessionStorage.getItem('user') ?? '');
  addNew: boolean = false;
  id: any;

  constructor(private companyService: CompanySettingService, private formBuilder: FormBuilder, public payrollService: PayrollService,
    private dialog: MatDialog, private router: Router, private translate: TranslateService
  ) {
    this.searchForm = this.formBuilder.group({
      companylocation: ['', Validators.required],
      costCenter: ['', Validators.required],
    });
    this.costCenterMappingForm = this.formBuilder.group({
      bankAccounts: ['', Validators.required],
      costCenter: ['', Validators.required],
    });


  }

  ngOnInit(): void {
    const savedLang = localStorage.getItem('lang');
    this.translate.use(savedLang || 'english');
    this.getBankDetails();
    this.getWorkLocation();
    this.getCostCenter();
    this.getEmployeeCostCenterDetails();
    this.searchControl.valueChanges.subscribe(searchText => {
      this.filterBankAccounts(searchText);
    });
    this.searchControlforLoc.valueChanges.subscribe(searchText => {
      this.filterLocations(searchText);
    })
    this.searchControlforCc.valueChanges.subscribe(searchText => {
      this.filterCostCenters(searchText);
    })
  }
  filterBankAccounts(searchText: any) {
    this.filteredBankAccountsList = this.bankAccountsList.filter((val: any) =>
      val.bankname.toLowerCase().includes(searchText.toLowerCase()) || val.ifsccode.toLowerCase().includes(searchText.toLowerCase())
    );
    // if (this.filteredBankAccountsList.length <= 0) {
    //   this.searchControl.setValue('');
    // }
  }

  filterLocations(searchText: any) {
    this.filteredLocations = this.worklocationDetails.filter((val: any) =>
      val.cityname.toLowerCase().includes(searchText.toLowerCase()) || val.location.toLowerCase().includes(searchText.toLowerCase())
    );
    // if (this.filteredLocations.length <= 0) {
    //   this.searchControlforLoc.setValue('');
    // }
  }
  filterCostCenters(searchText: any) {
    this.filteredCostCenterList = this.costCenterList.filter((val: any) =>
      val.cost_center_name.toLowerCase().includes(searchText.toLowerCase()) || val.bankname.toLowerCase().includes(searchText.toLowerCase())
    );
    // if (this.filteredCostCenterList.length <= 0) {
    //   this.searchControlforCc.setValue('');
    // }
  }


  getWorkLocation() {
    this.companyService.getactiveWorkLocation({ id: null, companyName: this.companyName }).subscribe((result) => {
      this.worklocationDetails = result.data;
      this.filteredLocations = this.worklocationDetails;
      this.filteredCompanyLocations = this.worklocationDetails;
    })
  }
  applyFilter(event: any) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource1.filter = filterValue.trim().toLowerCase();

    if (this.dataSource1.paginator) {
      this.dataSource1.paginator.firstPage();
    }
  }
  applyFilter1(event: any) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();

    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

  applyFilter2(event: any) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource2.filter = filterValue.trim().toLowerCase();

    if (this.dataSource2.paginator) {
      this.dataSource2.paginator.firstPage();
    }
  }
  masterToggle() {
    if (this.isAllSelected()) {
      this.selection.clear();
      this.selectedEmployeesList = [];
    } else {
      this.dataSource.data.forEach((row: any) => {
        this.selection.select(row);
      });
      this.selectedEmployeesList = [...this.dataSource.data];
    }
  }

  isSomeSelected() {
    return this.selection.selected.length > 0 && !this.isAllSelected();
  }

  isAllSelected() {
    const numSelected = this.selection.selected.length;
    const numRows = this.dataSource.data.length;
    return numSelected === numRows && numRows > 0;
  }

  isFormValid(): boolean {
    if (!this.searchForm.get('companylocation')?.valid || !this.searchForm.get('fromDate')?.valid) {
      return false;
    }
    const employeesFormArray = this.searchForm.get('employees') as FormArray;

    if (this.selectedEmployeesList.length === 0) return false;

    for (let selected of this.selectedEmployeesList) {
      const formGroup = employeesFormArray.controls.find(control =>
        control.get('employeeId')?.value === selected.employeeId
      );
      if (formGroup) {
        const tdsAmountControl = formGroup.get('tdsAmount');
        if (!tdsAmountControl ||
          tdsAmountControl.invalid ||
          isNaN(Number(tdsAmountControl.value))) {
          return false;
        }
      } else {
        return false;
      }
    }
    return true;
  }
  toggleRowSelection(row: any): void {
    const empId = row.employee_code || row.employee_id || row.emp_id || row.id;
    const index = this.selectedEmployeesList.findIndex(
      selected => (selected.employee_code || selected.employee_id || selected.emp_id || selected.id) === empId
    );

    if (index === -1) {
      // Not selected, add it
      this.selectedEmployeesList.push(row);
      this.selection.select(row);
    } else {
      // Already selected, remove it
      this.selectedEmployeesList.splice(index, 1);
      this.selection.deselect(row);
    }
  }

  // Fixed: use employee_code (or employee_id) consistently
  isRowSelected(row: any): boolean {
    const empId = row.employee_code || row.employee_id || row.emp_id || row.id;
    return this.selectedEmployeesList.some(
      selected => (selected.employee_code || selected.employee_id || selected.emp_id || selected.id) === empId
    );
  }


  getPageSizes1() {
    var customPageSizeArray = [];

    if (this.dataSource1.filteredData.length < 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource1.filteredData.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource1.filteredData.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource1.filteredData.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource1.filteredData.length);
    return customPageSizeArray;

  }

  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.dataSource.data.length < 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  getPageSizes2() {
    var customPageSizeArray = [];

    if (this.dataSource2.filteredData.length < 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource2.filteredData.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource2.filteredData.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource2.filteredData.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource2.filteredData.length);
    return customPageSizeArray;

  }
  submitCostCenter() {

    if (this.costCenterMappingForm.valid) {
      const costCenterValue = this.costCenterMappingForm.controls.costCenter.value.trim().toLowerCase();
      const costCenterExists = this.costCenterList.some((cc: any) => cc.cost_center_name.trim().toLowerCase() === costCenterValue);

      if (costCenterExists) {
        let dialogRef = this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: 'Cost Center already exists'
        });
        return;
      }
      const payload = {
        id_value: this.isEditCostCenter ? this.id : null,
        cost_center_name_value: this.costCenterMappingForm.controls.costCenter.value.trim(),
        bank_id_value: this.costCenterMappingForm.controls.bankAccounts.value,
        created_by_value: this.userSession.id,
      };

      this.payrollService.setCostCenter(payload).subscribe((response: any) => {

        if (response.status) {
          if (response.data[0].output === 0) {
            if (!this.isEditCostCenter) {
              let dialogRef = this.dialog.open(ReusableDialogComponent, {
                position: { top: `70px` },
                disableClose: true,
                data: 'Cost Center Mapped Successfully'
              });
            } else {
              let dialogRef = this.dialog.open(ReusableDialogComponent, {
                position: { top: `70px` },
                disableClose: true,
                data: 'Cost Center Updated Successfully'
              });
            }

            this.getCostCenter();
            this.costCenterMappingForm.reset();
            this.isEditCostCenter = false;

          } else if (response.data[0].output === 1) {

            let dialogRef = this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: 'Cost Center Already Mapped'
            });
          } else {
            let dialogRef = this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: 'Error in Mapping Cost Center'
            });
          }
        }

      });
    }
    else {

      this.costCenterMappingForm.markAllAsTouched();
    }

  }

  getCostCenter() {
    this.payrollService.getCostCenters().subscribe((result: any) => {

      this.costCenterList = result.data ? result.data : [];
      this.filteredCostCenterList = this.costCenterList;

      this.dataSource1 = new MatTableDataSource(result.data);
      this.dataSource1.paginator = this.paginatorcompleted;
      this.dataSource1.sort = this.sort2;
      this.pageLoading1 = false;
    });


  }

  cancel() {
    this.isEditCostCenter = false;
    this.costCenterMappingForm.reset();
    this.searchControl.reset();
    this.filteredBankAccountsList = this.bankAccountsList;
    this.getCostCenter();
  }

  clearSelection() {
    this.searchForm.reset();
    this.selectedEmployeesList = [];
    this.dataSource = new MatTableDataSource();
    this.searchControlforCc.reset();
    this.filteredCostCenterList = this.costCenterList;
    this.searchControlforLoc.reset();
    this.filteredLocations = this.worklocationDetails;
    this.selection.clear();
  }

  getBankDetails() {
    this.dataSource = new MatTableDataSource();
    this.payrollService.getBankAccounts({}).subscribe((result: any) => {

      this.bankAccountsList = []
      result.data.forEach((bank: any) => {
        if (bank.status === 'Active') {
          this.bankAccountsList.push(bank);
        }
      });
      this.filteredBankAccountsList = this.bankAccountsList;
    });
  }

  submit() {
    if (this.searchForm.valid) {
      const ccValue = this.searchForm.get('costCenter')?.value;
      const ccId = (typeof ccValue === 'number')
        ? ccValue
        : (ccValue?.id ?? ccValue?.cc_id ?? ccValue?.cost_center_id ?? ccValue?.costCenterId ?? ccValue);

      const mappingdata = this.selectedEmployeesList.map((emp: any) => {
        const empId = emp.employeeId ?? emp.empId ?? emp.employee_id ?? emp.employeeid ?? emp.id;
        return { emp_id: Number(empId), cc_id: Number(ccId) };
      });
      let data = { mapping_data: mappingdata };

      const payload = {
        mapping_data: JSON.stringify(data),
        created_by_value: this.userSession.id,
      };
      this.payrollService.setEmployeeCostCenterMapping(payload).subscribe((response: any) => {


        if (response.status) {
          if (response.data[0].output === 0) {

            let dialogRef = this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: 'Cost Center Mapped Successfully'
            });
            this.getEmployeesForCostCenterAssignment(ccId);
            this.reset();
          } else if (response.data[0].output === 1) {

            let dialogRef = this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: 'Cost center Already mapped'
            });
          } else {
            let dialogRef = this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: 'Unable to map cost center, please try again'
            });
          }
        }

      });
    } else {
      console.log('Form is invalid');
    }

  }
  isSubmitDisabled(): boolean {
    const formValid = this.searchForm?.valid;
    const hasEmployeesSelected = this.selectedEmployeesList.length > 0;
    const hasDataInTable = this.dataSource.data.length > 0;

    return !formValid || !hasEmployeesSelected || !hasDataInTable;
  }
  editCostCenter(row: any) {
    this.isEditCostCenter = true;
    this.id = row.cost_center_id;
    this.costCenterList.forEach((cc: any) => {
      if (cc.cost_center_name === row.cost_center_name) {
        this.costCenterList.splice(this.costCenterList.indexOf(cc), 1);
      }
    });

    this.costCenterMappingForm.patchValue({
      costCenter: row.cost_center_name,
      bankAccounts: row.bank_id
    });
  }

  getEmployeesForCostCenterAssignment(res: any) {
    let locationId = JSON.stringify([res]);
    this.payrollService.getEmployeesForCostCenterAssignment(locationId).subscribe((result: any) => {
      this.dataSource = new MatTableDataSource(result.data);
      this.dataSource.paginator = this.paginator;
      this.dataSource.sort = this.sort1;
      this.pageLoading = false;
      this.searchForm.controls['costCenter'].setValue('');
      this.selection.clear();
      this.selectedEmployeesList = [];
    });

  }
  addNewMapping() {
    this.addNew = true;
  }

  reset() {

    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Payroll/costCenter"]));
  }

  getEmployeeCostCenterDetails() {
    this.payrollService.getEmployeeCostCenterDetails().subscribe((result: any) => {
      this.dataSource2 = new MatTableDataSource(result.data);
      this.dataSource2.paginator = this.paginator3;
      this.dataSource2.sort = this.sort3;
      this.pageLoading2 = false;
    });
  }
  getCostCenterTooltip(row: any): string {
    return [
      `Bank Account: ${row.bankname || ''} |`,
      `IFSC Code: ${row.ifsccode || ''} |`,
      `Address: ${(row.address1 || '') + (row.address2 ? ' ' + row.address2 : '')} |`,
      `Location: ${row.location || ''} |`,
      `State: ${row.state || ''} |`,
      `Country: ${row.country || ''} |`,
      `Account Number: ${row.accountnumber || ''} `
    ].join('\n');
  }
  onTabChange(event: any) {

    if (event.index === 0) {
      this.addNew = false;
      // this.searchControl.reset();
      // this.filteredBankAccountsList = this.bankAccountsList;
      // this.searchControlforCc.reset();
      // this.filteredCostCenterList = this.costCenterList;
      // this.searchControlforLoc.reset();
      // this.filteredLocations = this.worklocationDetails;
      this.reset();
    } else if (event.index === 1) {
      this.getEmployeeCostCenterDetails();
      this.costCenterMappingForm.reset();
      this.isEditCostCenter = false;
    }
  }
}
