import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { CourseListComponent } from './pages/course-list/course-list.component';
import { MainComponent } from 'src/app/pages/main/main.component';
import { AssignCourseComponent } from './pages/assign-course/assign-course.component';
import { SkillTrackerReportComponent } from './pages/skill-tracker-report/skill-tracker-report.component';
import { TestScreenComponent } from './pages/test-screen/test-screen.component';
import { EmployeeDashboardComponent } from './pages/employee-dashboard/employee-dashboard.component';
import { ChaptersScreenComponent } from './pages/chapters-screen/chapters-screen.component';
import { ChaptersListComponent } from './pages/chapters-list/chapters-list.component';
import { DetailedCourseInformationComponent } from './pages/detailed-course-information/detailed-course-information.component';
import { CourseDocumentsComponent } from './pages/course-documents/course-documents.component';
import { CourseLinksComponent } from './pages/course-links/course-links.component';
import { CertificatesScreenComponent } from './pages/certificates-screen/certificates-screen.component';
import { TestResultScreenComponent } from './pages/test-result-screen/test-result-screen.component';
import { TestReportComponent } from './pages/test-report/test-report.component';
import { CertificateComponent } from './pages/certificate/certificate.component';
import { LmsAddCourseComponent } from './pages/lms-add-course/lms-add-course.component';
import { LmsEmpDashboardComponent } from './pages/lms-emp-dashboard/lms-emp-dashboard.component';
import { LmsAssessmentComponent } from './pages/lms-assessment/lms-assessment.component';
import { LmsCourseListComponent } from './pages/lms-course-list/lms-course-list.component';
import { LmsViewCourseComponent } from './pages/lms-view-course/lms-view-course.component';
import { LmsDashboardComponent } from './pages/lms-dashboard/lms-dashboard.component';
import { LmsConfigurationsComponent } from './pages/lms-configurations/lms-configurations.component';
import { LmsAchivementsComponent } from './pages/lms-achivements/lms-achivements.component';
import { LmsReportsComponent } from './pages/lms-reports/lms-reports.component';
import { ClientSaDashboardLearningComponent } from './pages/client-sa-dashboard-learning/client-sa-dashboard-learning.component';
import { LmsEmployeeReviewerComponent } from './pages/lms-employee-reviewer/lms-employee-reviewer.component';
import { QuizDetailsComponent } from './pages/quiz-details/quiz-details.component';
import { LmsCourseChecklistComponent } from './pages/lms-course-checklist/lms-course-checklist.component';
const routes: Routes = [
  {
    path: '', component: MainComponent,
    children: [
      { path: 'courseList', component: CourseListComponent },
      { path: 'assignCourse', component: AssignCourseComponent },
      { path: 'skillTrackerReport', component: SkillTrackerReportComponent },
      { path: 'testScreen', component: TestScreenComponent },
      { path: 'emp_dashboard', component: EmployeeDashboardComponent },
      { path: 'chapterScreen', component: ChaptersScreenComponent },
      { path: 'chaptersList', component: ChaptersListComponent },
      { path: 'detailedCourseInformation', component: DetailedCourseInformationComponent },
      { path: 'coursePDF', component: CourseDocumentsComponent },
      { path: 'courseLinks', component: CourseLinksComponent },
      { path: 'certificates', component: CertificatesScreenComponent },
      { path: 'testResult', component: TestResultScreenComponent },
      { path: 'testReport', component: TestReportComponent },
      { path: 'resultCertificate', component: CertificateComponent },
      { path: 'LmsAddCourse', component: LmsAddCourseComponent },
      { path: 'LmsEmpDashboard', component: LmsEmpDashboardComponent },
      { path: 'LmsViewCourse/:id', component: LmsViewCourseComponent },
      { path: 'LmsCourseList', component: LmsCourseListComponent },
      { path: 'LmsAssessment', component: LmsAssessmentComponent },
      { path: 'LmsInstructorDashboard', component: LmsDashboardComponent },
      { path: 'LmsManagerDashboard', component: LmsDashboardComponent },
      { path: 'LmsHRManagerDashboard', component: LmsDashboardComponent },
      { path: 'LmsAdminDashboard', component: LmsDashboardComponent },
      { path: 'LmsConfigurations', component: LmsConfigurationsComponent },
      { path: 'LmsAchivements', component: LmsAchivementsComponent }, 
      { path: 'LmsManagerReports', component: LmsReportsComponent },  
      { path: 'LmsHRManagerReports', component: LmsReportsComponent },  
      { path: 'LmsInstructorReports', component: LmsReportsComponent }, 
      { path: 'ClientSaDashboardLearning', component: ClientSaDashboardLearningComponent },
      {path: 'Employee/LmsEmployeeReviewer', component: LmsEmployeeReviewerComponent},
      {path: 'LmsQuizDetails', component: QuizDetailsComponent},
      {path: 'Manager/LmsCourseChecklist', component: LmsCourseChecklistComponent},
      {path: 'HRManager/LmsCourseChecklist', component: LmsCourseChecklistComponent},
      {path: 'Instructor/LmsCourseChecklist', component: LmsCourseChecklistComponent}

    ]
  }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class LearningRoutingModule { }
