import { Component, OnInit, ViewChild,Inject,ElementRef, LOCALE_ID,Injectable  } from '@angular/core';
import { MapInfoWindow, MapMarker,GoogleMap } from '@angular/google-maps';
@Injectable({
  providedIn: 'root'
})
export class MapService {
    @ViewChild(GoogleMap, { static: false }) googleMap: GoogleMap | undefined;
  userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
  savedLang:any = localStorage.getItem('lang')||'english'; 
  languagecode:any = 'en';
  private mapInitialized: boolean = false;
  initMap(): Promise<void> {
    this.savedLang = localStorage.getItem('lang')||'english'; 
    if(this.savedLang){
      this.languagecode = this.savedLang.slice(0, 2);
    }
    if (!this.mapInitialized) {       
      return new Promise<void>((resolve, reject) => {
        // Define the callback function
        (window as any)['initMap'] = () => {
          this.mapInitialized = true;
          resolve();
        };
        const script = document.createElement('script');
        script.src = `https://maps.googleapis.com/maps/api/js?key=${this.userSession.google_map_apikey}&language=${this.languagecode}&libraries=places&version=weekly&callback=initMap`;
        script.async = true;
        script.defer = true;
        script.onload = () => {
          // The API script has loaded, but the callback may not have been called yet
          if (!this.mapInitialized) {
            reject('Failed to initialize the map');
          }
        };
        script.onerror = (error: Event | string) => reject(error);
        document.head.appendChild(script);
      });
    } else {
      return Promise.resolve();
    }
  }
  constructor() { }
}
