
import { UntypedFormGroup, UntypedFormBuilder, Validators, FormControl } from '@angular/forms';
import { Component, OnInit, ViewChild } from '@angular/core';
import { Router } from '@angular/router';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { AdminService } from '../../admin.service';
import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';
@Component({
  selector: 'app-extradays-slab-configuration',
  templateUrl: './extradays-slab-configuration.component.html',
  styleUrls: ['./extradays-slab-configuration.component.scss']
})
export class ExtradaysSlabConfigurationComponent implements OnInit {

  breaksSlabForm: any = UntypedFormGroup;
  payGroupRequestForm!: UntypedFormGroup;
  isEarnings: boolean = true;
  isDeductions: boolean = true;
  expandedElement: any;
  Educations: any;
  companyName: any;
  constructor(private router: Router, private formBuilder: UntypedFormBuilder,
    private adminService: AdminService,
    private companyService: CompanySettingService,
    private dialogService: ReusableDialogService) {
    this.companyName = sessionStorage.getItem('companyName');
  }
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  displayedColumns: string[] = ['sno', 'designation', 'mindays', 'maxdays', 'extradays', 'action'];
  displayedColumns2: string[] = ['sno', 'designation', 'status'];
  dataSource: MatTableDataSource<any> = <any>[];
  dataSource2: MatTableDataSource<any> = <any>[];
  userSession: any;
  pageLoading = true;
  isAdd: boolean = false;
  isdata: boolean = true;
  isEdit: boolean = false;
  btnDisable: boolean = false;

  slabRangeList: any = [];
  penalityDesignationList: any = [];
  mindays: any;
  maxdays: any;
  selectedDesignation: any;
  btndisable: boolean = false;
  designationsList: any = [];
  desigSearchControl = new FormControl('');
  filteredDesignations: any = [];
  isUpdate: boolean = false;
  extradaysList: any = [{ value: 0.5 }, { value: 1 }, { value: 2 }, { value: 3 }, { value: 4 }, { value: 5 }];
  addExtraDaysList: any = [];
  selectedRecordId: any;
  ngOnInit(): void {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.breaksSlabForm = this.formBuilder.group(
      {
        minDays: ["", Validators.required],
        maxDays: ["", Validators.required],
        extraDays: ["", Validators.required],
        designation: ["", Validators.required],
      });
    this.getDesignationsMaster();
    this.getSlabsList();
  }
  getDesignationsMaster() {
    this.companyService.getMastertable('designationsmaster', '1', 1, 1000, this.companyName).subscribe(data => {
      this.designationsList = data.data;
      this.filteredDesignations = data.data;
    })
  }
  getSlabsList() {
    this.slabRangeList = [];
    let desigId = this.breaksSlabForm.controls.designation.value != "" ? this.breaksSlabForm.controls.designation.value : 0;

    this.adminService.getAttendanceExtraDaysSlabDetails(desigId).subscribe((res: any) => {
      if (res.status && res.data.length != 0) {
        this.slabRangeList = res.data;
        this.dataSource = new MatTableDataSource(this.slabRangeList);
        this.pageLoading = false;
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.mindays = 0;
        this.maxdays = 0;
      }
    })
  }
  
  isValidRange(): boolean {
    let selectedDesig = Number(this.breaksSlabForm.controls.designation.value);
    if (this.mindays > 30 || this.maxdays > 30) {
      this.dialogService.openDialog('Minimum days and maximum days must be less than 30 days');
      return false;
    }

    if (this.mindays >= this.maxdays) {
      this.dialogService.openDialog('Minimum days must be less than Maximum days');
      return false;
    }
    
    if (this.addExtraDaysList.length > 0) {
      for (const existingRange of this.addExtraDaysList) {
          if ( selectedDesig === this.selectedDesignation &&
            this.mindays === existingRange.minimum_value ||
            this.maxdays === existingRange.maximum_value ||
            this.mindays === existingRange.minimum_value && this.maxdays === existingRange.maximum_value
          ) {
            this.dialogService.openDialog('The slab range is already in the selected designation.');
            return false;
          }
      }
    }
    
    if (this.slabRangeList.length > 0) {
      for (const existingRange of this.slabRangeList) {
        if (existingRange.designationId === this.selectedDesignation &&
            this.mindays <= existingRange.maximumDays && this.maxdays >= existingRange.minimumDays) {
              this.dialogService.openDialog('The slab range is a duplicate for the selected designation.');
            return false;
        }
      }
    }

    return true;
  }

  addRow() {
    this.addValidators();
    if (this.breaksSlabForm.valid) {
      this.mindays = Number(this.breaksSlabForm.controls.minDays.value);
      this.maxdays = Number(this.breaksSlabForm.controls.maxDays.value);
      this.selectedDesignation = Number(this.breaksSlabForm.controls.designation.value)
      if (this.isValidRange()) {
        this.addExtraDaysList.push({
          id: null,
          minimum_value: this.mindays,
          maximum_value: this.maxdays,
          extra_days: Number(this.breaksSlabForm.controls.extraDays.value)
        });
        this.clearFields();
        this.clearValidators();
      }
    }
  }

  submit() {
    if (this.addExtraDaysList.length > 0) {
      if (this.btnDisable) {
        return;
      }
      let data = {
        "designation_id": this.breaksSlabForm.controls.designation.value,
        "extra_days_slab": this.addExtraDaysList,
        "user_id": this.userSession.id,
      }
      this.btndisable = true;
      this.adminService.setAttendanceExtraDaysSlab(data).subscribe((data: any) => {
        if (data.status && data.data[0].statusCode == 0) {
          this.dialogService.openDialog('Extradays slab configuration saved sucessfully.');
          this.btndisable = false;
          this.cancel();
        } else if (data.status && data.data[0].statusCode == 1) {
          this.dialogService.openDialog('Slab already exists.');
          this.btndisable = false;
        } else {
          this.dialogService.openDialog('Unable to add slab. Please try again.');
          this.btndisable = false;
        }
      });
    }
  }

  isUpdateValidRange(): boolean {
    let selectedDesig = Number(this.breaksSlabForm.controls.designation.value);
    if (this.mindays >= this.maxdays) {
      this.dialogService.openDialog('Minimum days must be less than Maximum days');
      return false;
    }

    if (this.addExtraDaysList.length > 0) {
      for (const existingRange of this.addExtraDaysList) {
        if (selectedDesig === this.selectedDesignation && this.selectedRecordId != existingRange.extradayId) {
          if (this.mindays === existingRange.minimum_value ||
            this.maxdays === existingRange.maximum_value ||
            this.mindays === existingRange.minimum_value && this.maxdays === existingRange.maximum_value
          ) {
            this.dialogService.openDialog('The slab range is already in the selected designation.');
            return false;
          }
        }
      }
    }

    if (this.slabRangeList.length > 0) {
      for (const existingRange of this.slabRangeList) {
        if (existingRange.designationId === this.selectedDesignation &&
            this.selectedRecordId != existingRange.extradayId &&
            this.mindays <= existingRange.maximumDays && this.maxdays >= existingRange.minimumDays) {
            this.dialogService.openDialog('The slab range is a duplicate for the selected designation.');
          return false;
        }
      }
    }
    return true;
  }

  updateData() {

    if (this.breaksSlabForm.valid) {
      this.mindays = Number(this.breaksSlabForm.controls.minDays.value);
      this.maxdays = Number(this.breaksSlabForm.controls.maxDays.value);
      this.selectedDesignation = Number(this.breaksSlabForm.controls.designation.value)
      if (this.isUpdateValidRange()) {
        this.addExtraDaysList.push({
          id: this.selectedRecordId,
          minimum_value: this.mindays,
          maximum_value: this.maxdays,
          extra_days: Number(this.breaksSlabForm.controls.extraDays.value)
        });
        let data = {
          "designation_id": this.breaksSlabForm.controls.designation.value,
          "extra_days_slab": this.addExtraDaysList,
          "user_id": this.userSession.id,
        }
        this.btndisable = true;
        this.adminService.setAttendanceExtraDaysSlab(data).subscribe((data: any) => {
          if (data.status && data.data[0].statusCode == 0) {
            this.dialogService.openDialog('Extradays slab configuration saved sucessfully.');
            this.btndisable = false;
            this.cancel();
          } else if (data.status && data.data[0].statusCode == 1) {
            this.dialogService.openDialog('Slab already exists.');
            this.btndisable = false;
          } else {
            this.dialogService.openDialog('Unable to add slab. Please try again.');
            this.btndisable = false;
          }

        });
     
      }
    }
  }

  cancel() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/Admin/extradays-slab"]));
  }


  edit(data: any) {
    this.breaksSlabForm.controls.designation.setValue(data.designationId);
    this.breaksSlabForm.controls.minDays.setValue(data.minimumDays);
    this.breaksSlabForm.controls.maxDays.setValue(data.maximumDays);
    this.breaksSlabForm.controls.extraDays.setValue(Number(data.extraDays));
    this.selectedRecordId = data.extradayId;
    this.isEdit = true;
    this.isAdd = true;
    this.isdata = false;
  }


  getPageSizes(): number[] {
    var customPageSizeArray = [];

    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);

    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  filterDesignations(searchText: any) {
    this.filteredDesignations = this.designationsList.filter((val: any) =>
      val.designation.toLowerCase().includes(searchText.toLowerCase())
    );
  }
  Add() {
    this.isAdd = true;
    this.isdata = false;
  }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();

    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }

  removeText(index: number) {
    this.addExtraDaysList.splice(index, 1);
  }
  clearFields() {

    this.breaksSlabForm.controls.minDays.reset();
    this.breaksSlabForm.controls.minDays.markAsPristine();
    this.breaksSlabForm.controls.minDays.markAsUntouched();

    this.breaksSlabForm.controls.maxDays.setValue('');
    this.breaksSlabForm.controls.maxDays.markAsPristine();
    this.breaksSlabForm.controls.maxDays.markAsUntouched();

    this.breaksSlabForm.controls.extraDays.setValue('');
    this.breaksSlabForm.controls.extraDays.markAsPristine();
    this.breaksSlabForm.controls.extraDays.markAsUntouched();
  }

  clearValidators() {
    this.breaksSlabForm.get("minDays").clearValidators();
    this.breaksSlabForm.get("minDays").updateValueAndValidity();
    this.breaksSlabForm.get("maxDays").clearValidators();
    this.breaksSlabForm.get("maxDays").updateValueAndValidity();
    this.breaksSlabForm.get("extraDays").clearValidators();
    this.breaksSlabForm.get("extraDays").updateValueAndValidity();
  }

  addValidators() {
    this.breaksSlabForm.get("minDays").setValidators(Validators.required);
    this.breaksSlabForm.get("minDays").updateValueAndValidity();
    this.breaksSlabForm.get("maxDays").setValidators(Validators.required);
    this.breaksSlabForm.get("maxDays").updateValueAndValidity();
    this.breaksSlabForm.get("extraDays").setValidators(Validators.required);
    this.breaksSlabForm.get("extraDays").updateValueAndValidity();
  }

  isBack() {
    this.isAdd = false;
    this.isdata = true;
  }
  tabClick(event: any) {
    if (event.index == 0) {
    
    } else {
     this.getPenaltiesDesignationsList();
    //  this.isAdd = false;
    //  this.isdata = true;
    }
  }
  getPenaltiesDesignationsList() {
    this.penalityDesignationList = [];
     this.adminService.getPenaltiesDesignationsMapping().subscribe((res: any) => {
      if (res.status && res.data.length != 0) {
        this.penalityDesignationList = res.data;
       
      }
    })
  }
  onToggleChange(data:any){
    let updateStatus = data.status;
    let status = data.status ? 1 : 0;
    let input = {
      "desig_id": data.designation_id,
      "desig_status": status,
    }

    this.adminService.setPenaltiesDesignationsMapping(input).subscribe((data: any) => {
      if (data.status && data.data[0].successstate == 0) {
        if(updateStatus){
          this.dialogService.openDialog('Penalty designation activated sucessfully');
        } else{
          this.dialogService.openDialog('Penalty designation deactivated sucessfully');
        }
         this.getPenaltiesDesignationsList();
      } else {
        this.dialogService.openDialog('Unable to update data. Please try again.');
      }
    });
  }
}
