import { Component, OnInit, ViewChild,Inject,ElementRef, LOCALE_ID,  } from '@angular/core';
import {UntypedFormBuilder,  Validators, } from '@angular/forms';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';
import { NgxSpinnerService } from 'ngx-spinner';
import {CrmService} from "../../crm.service";
import { DatePipe } from '@angular/common';
import {MapService} from "src/app/modules/crm/map.service"; 
import { Observable } from 'rxjs';
import { FormControl } from '@angular/forms';
import { GoogleMap } from '@angular/google-maps';

@Component({
  selector: 'app-get-geo-location',
  templateUrl: './get-geo-location.component.html',
  styleUrls: ['./get-geo-location.component.scss']
})
export class GetGeoLocationComponent implements OnInit {
  @ViewChild(GoogleMap, { static: false }) googleMap: GoogleMap | undefined;
  locationForm:any;
  stateDetails:any = [];
  cityDetails:any = [];
  selected_location:any = null;
  userSession:any ;
  CountryDetails:any;
  formattedDate:any;
  formattedTime:any;
  timeStampVal:any;
  currentDate:any; 
  pipe:any; 
  address:any;
  zone: any;
  predictions: google.maps.places.AutocompletePrediction[] = [];
 
  pageTitle:any = 'Add Location';
  //location_icon_val:any = 'location_on';
 
  isWebRestricted:any = 1;
  mapInitialized:any=false;
  zoom:any = 16;
  mapOptions: google.maps.MapOptions = {
    zoom: 16,
  };
  marker:any= null; //google.maps.marker.AdvancedMarkerElement | undefined;
  geocoder: any;
  displayOptions: any[] = [];
  myControl = new FormControl();
  track_radius = new FormControl();
  measure =  new FormControl();
  tickMarks: number[] = [];
  markerSelected:any = null;
  map:any = null; // google.maps.Map;
  center:any={lat :0,lng: 0};
  isSelected:any = false;
  searchClientOnMap:any = false;
  fetchedAddress:any = null;
  autocomplete:any;
  localdata:any;
  editMode:any = false;
  service:any;
  circle!: google.maps.Circle;
  circle_measure!: google.maps.Circle;
  address_ids:any = true;
  crm_track_radius:any = 0;

  constructor(@Inject(LOCALE_ID) private locale: string, public dialogRef: MatDialogRef<GetGeoLocationComponent>,private crm:CrmService,private spinner: NgxSpinnerService,
    private FormBuilder:UntypedFormBuilder,private company:CompanySettingService, private mapService:MapService,
    @Inject(MAT_DIALOG_DATA) public data: any) {

      this.locationForm=this.FormBuilder.group({
        address1:["",[Validators.required ]],
        address2:[""],
        city: ["",Validators.required],
        state: ["",Validators.required],
        pincode: ["",Validators.required],
        country: ["",Validators.required],
        latitude:[""],
        longitude:[""],
        measure:['0'],
        track_radius:['0']

      });
    }

  async ngOnInit() {
    this.userSession = JSON.parse(sessionStorage.getItem('user') ?? '');
    if (this.userSession.isCrmWebDisabled !== undefined) {
      this.isWebRestricted = Number(this.userSession.isCrmWebDisabled );
    }
    await this.setmap(); 
    
    for (let i = 0; i < 6000; i += 500) {
      this.tickMarks.push(i);
    }
    this.pipe = new DatePipe(this.locale);
    this.currentDate = new Date();
    this.formattedDate = this.pipe.transform(this.currentDate, 'yyyy-MM-dd');
    this.formattedTime = this.currentDate.toLocaleTimeString(undefined, {hour12: false, hour: '2-digit',minute: '2-digit', second: '2-digit' });
    this.timeStampVal = this.currentDate.getTime();
    this.locationForm.get('country')?.valueChanges.subscribe((selectedValue: any) => {
      this.stateDetails= [];
      this.crm.getStates(selectedValue).subscribe((data)=>{
        this.stateDetails = data.data;
      })
    });

    this.locationForm.get('state')?.valueChanges.subscribe((selectedValue: any) => {
      this.locationForm.controls.city.setValue("");
      this.cityDetails = [];
       this.company.getCities(selectedValue).subscribe((data)=>{
            this.cityDetails=data.data
        })
      })
    this.myControl.setValue('');
    this.myControl.valueChanges.subscribe((val: any) => {     
       this.displayOptions = []; 
      //if(!this.isSelected){
        if(val.toString().length>=3){
          this.initAsyncMapPlaces(val);
        }
    });

    this.measure.setValue(0);
    this.track_radius.setValue(0);
    this.track_radius.valueChanges.subscribe((val: any) => {     
      this.locationForm.controls.track_radius.setValue(val);
      this.updateRadius();
    });

    this.measure.valueChanges.subscribe((val: any) => {     
      this.locationForm.controls.measure.setValue(val);
      this.updateMeasure();
    });

  }

  ngAfterViewInit(): void {
    this.is_mapInitialized();
  }
 
    async initAsyncMapPlaces(val:any): Promise<void> {
    if(typeof val === 'string'){
      this.isSelected = false;
      
      this.service =  new google.maps.places.PlacesService(this.map);
      this.service.findPlaceFromQuery( {query: val,fields: ["name","geometry",'formatted_address', 'place_id', 'rating'] },(places:any, status:any) => {
        if (status === google.maps.places.PlacesServiceStatus.OK && places) {
          this.displayOptions = []; 
          places?.forEach(async ( place:any ) => { 
            if(!this.displayOptions.includes(place))
            this.displayOptions?.push(place);
          });
        }
      });
    }
  }
 async setmap(){
    if(!this.mapInitialized){
      console.log(new Date(),'loading map');
      this.spinner.show();
     // setTimeout(async() => {        
        console.log(new Date(),'setTimeout - loading map');
        this.mapService.initMap().then(async() => {
        this.spinner.hide();
        this.geocoder = new google.maps.Geocoder();
        //@ts-ignore
        const [{ Map }, { AdvancedMarkerElement }] = await Promise.all([
          google.maps.importLibrary("marker"),
          google.maps.importLibrary("places"),
        ]);
        this.map = new google.maps.Map(document.getElementById("map") as HTMLElement, {
          center: this.center,
          zoom: this.zoom, 
          mapTypeControl: false,
          mapId: "DEMO_MAP_ID"
        }); 

         
          await this.is_mapInitialized();
         // this.marker = google.maps.marker.AdvancedMarkerElement ;
       
      }).catch((error: any) => {
        console.log(error);
        console.error('Error initializing map:', error);  // Handle any errors that occurred during map initialization
      });
  //  }, 200); 
    }
  }

  async is_mapInitialized(){
    for(let i=0;i<3;i++){
      if(!this.mapInitialized){
        setTimeout(async() =>  {  
          if(google && this.map instanceof google.maps.Map){
          console.log(new Date(),'map Initialized');
          this.mapInitialized = true;    
          if(!this.localdata){
            if(this.data && this.data.worklocationdata){
              this.localdata = this.data.worklocationdata;    
              this.crm_track_radius = this.data.crm_track_radius;
              this.getCountry(this.localdata.country,{state:this.localdata.state, city:this.localdata.city});    
              this.showLocalData();   
              this.pageTitle = 'Edit Location';
            } else {
              this.editMode = true;
              this.getCountry();
              this.initAsyncMap();
            }
          }         
         }
        }, 500); 
      }
    }
  }

  async initAsyncMap(coords:any = null)  {
    if(this.mapInitialized){
       
      this.displayOptions = [];
      if(!coords){
        this.locationForm.controls.latitude.setValue(0);
      this.locationForm.controls.longitude.setValue(0);
      navigator.geolocation.getCurrentPosition( (position) => {
        this.center ={lat : position.coords.latitude,lng: position.coords.longitude};
        this.selected_location = this.center;
      },(error) => console.log(error));
      } else {     
        this.locationForm.controls.latitude.setValue(coords.lat);
        this.locationForm.controls.longitude.setValue(coords.lng);
        this.center = coords;
        this.selected_location = coords;
      }
      this.addMarker(this.selected_location);
    } else this.setmap();
   
  }
    

  
async addMarker(position: any) {
   //@ts-ignore
   if(!this.mapInitialized){
    await this.setmap();
    }
    if(this.mapInitialized){
    if (!position) return;
     this.map.setCenter(position);
    if (typeof google !== 'undefined' && this.marker) {
      this.marker.setMap(null);
    }
      this.marker = new google.maps.Marker({position,map:this.map });
      this.updateRadius();
      this.updateMeasure();
   }
   
}

  selectValue(option:any) {
    this.address_ids = false;
    this.displayOptions = [];
    this.isSelected = true;
    this.myControl.setValue(option.name +', '+ option.formatted_address);
   
    this.selected_location = {lat: option.geometry.location.lat(),lng: option.geometry.location.lng() };
    this.addMarker(this.selected_location);
    this.crm.fetchMapLocationDetails(this.selected_location ).subscribe((data) => {
      this.fixFetchedAddress(data,this.selected_location,option);
      this.locationForm.controls.latitude.setValue(this.selected_location.lat);
      this.locationForm.controls.longitude.setValue(this.selected_location.lng);
    }); 

    this.updateRadius();
    this.updateMeasure();
   
  }
  refreshMap(){
    this.myControl.setValue('');
    this.displayOptions =[];
    this.searchClientOnMap = false;
    this.fetchedAddress= null;
    this.selected_location = null;
   
    if(this.localdata){
      this.showLocalData();
    }else if(this.editMode && !this.localdata){
      this.locationFormReset();
      this.initAsyncMap();      
    }
  }

  searchlocationOnMap(){
    this.searchClientOnMap = true;
  }

  async fixFetchedAddress(data:any = null,coords:any = null,option:any = null){  
    if(option && option.formatted_address){
      this.locationForm.controls.address1.setValue(option.formatted_address);
    } else {
      this.geocodeAddress(coords);
    }
    if(coords){
      this.locationForm.controls.latitude.setValue(coords.lat);
      this.locationForm.controls.longitude.setValue(coords.lng);
    }
    if(data && this.editMode){       
      this.locationForm.controls.address2.setValue(data.display_name);
      this.locationForm.controls.pincode.setValue(data.address.postcode);     
      this.getCountry(data.address.country,data.address);
    }
    else{
      this.locationForm.get('address2').reset().setErrors(null);
      this.locationForm.get('country').reset().setErrors(null);
      this.locationForm.get('state').reset().setErrors(null);
      this.locationForm.get('city').reset().setErrors(null);
      this.locationForm.get('pincode').reset().setErrors(null);
      this.locationForm.get('latitude').reset().setErrors(null);
      this.locationForm.get('longitude').reset().setErrors(null);
      this.locationForm.get('measure').reset().setErrors(null);
      this.locationForm.get('track_radius').reset().setErrors(null);
    }   
  
  }
  
 
 
 

  getClientLocationFromMap(){
    this.address_ids = false;
    this.searchClientOnMap = false;
    this.editMode = true;
     
      navigator.geolocation.getCurrentPosition( (position) => {
        this.selected_location = {lat: position.coords.latitude,lng: position.coords.longitude};
        this.crm.fetchMapLocationDetails(this.selected_location ).subscribe((data) => {
          this.fixFetchedAddress(data,this.selected_location);
          this.addMarker(this.selected_location);
          this.map.setCenter(this.selected_location);
          this.updateMeasure();
          this.updateRadius();
          this.locationForm.controls.latitude.setValue(this.selected_location.lat);
          this.locationForm.controls.longitude.setValue(this.selected_location.lng);
        });         
      },(error) => console.log(error));
  }


  locationFormReset(){
   this.locationForm.reset();
   this.locationForm.get('address1').reset().setErrors(null);
   this.locationForm.get('address2').reset().setErrors(null);
   this.locationForm.get('country').reset().setErrors(null);
   this.locationForm.get('state').reset().setErrors();
   this.locationForm.get('city').reset().setErrors(null);
   this.locationForm.get('pincode').reset().setErrors(null);
   this.locationForm.get('latitude').reset().setErrors(null);
   this.locationForm.get('longitude').reset().setErrors(null);
   this.locationForm.get('measure').reset().setErrors(null);
   this.locationForm.get('track_radius').reset().setErrors(null);
  }
/**Here saved location details send as response */
  submittedLocation(){  
    if(this.locationForm.valid){
      
      //let locationinfo ={  
        this.localdata.address1=this.locationForm.controls.address1.value,
        this.localdata.address2=this.locationForm.controls.address2.value?this.locationForm.controls.address2.value:'',
        this.localdata.country=this.locationForm.controls.country.value,
        this.localdata.state=this.locationForm.controls.state.value,
        this.localdata.city=this.locationForm.controls.city.value,
        this.localdata.pincode=this.locationForm.controls.pincode.value,
        this.localdata.createdby=this.userSession.id,
        this.localdata.latitude=this.locationForm.controls.latitude.value,
        this.localdata.longitude=this.locationForm.controls.longitude.value,
        this.localdata.measure=this.locationForm.controls.measure.value,
        this.localdata.track_radius=this.locationForm.controls.track_radius.value,
     // }
       
      this.dialogRef.close(this.localdata);
    }

  }
  
  getCountry(country:any=null,address:any = null){
    let countryId = 0;
    this.address_ids  ? countryId = (country || 0) : country = country?.toString().toLowerCase().trim();
    this.spinner.show();
    this.crm.getCountry(null,1,10).subscribe((results)=>{
      this.spinner.hide();
      this.CountryDetails=results.data;
      if(country){
        if( !this.address_ids){
          let countryDet = this.CountryDetails.find((c:any) => country == c.country.toString().toLowerCase().trim());
          countryId = countryDet.id;
        } 
        this.locationForm.patchValue({ country: countryId});
        if(address && address.state) this.getStatesc(countryId,address);
      }
    });
  }

  backArrow(){
    this.dialogRef.close();
  }
 
  clearData(){
    this.dialogRef.close();
  }
onInputChange(event:any) {
    if (!this.address) {
      this.predictions = [];
      return;
    }
 
    let autocompleteService = new google.maps.places.AutocompleteService();

    autocompleteService.getPlacePredictions( { input: this.address  },
      (predictions: google.maps.places.AutocompletePrediction[]| null, status: google.maps.places.PlacesServiceStatus) => {
        this.zone.run(() => {
          if (status === google.maps.places.PlacesServiceStatus.OK) {
            this.predictions = predictions?predictions :[];
          } else this.predictions = [];
          
        });
      }
    );
  }

  // getLocationIconColor(){
  //   if(!(Number(this.locationForm.controls.latitude.value) && Number(this.locationForm.controls.longitude.value)) ){
  //     this.location_icon_val = 'location_off';
  //     return  'red';
  //   }
  //   else {
  //     this.location_icon_val = 'location_on';
  //     return 'green';
  //   }  
  // }


  getCities(stateId:any,address:any=null){
    let cityId = 0;
    (address && address.city &&  this.address_ids ) ? cityId = (address.city || 0) : address.city = address.city?.toString().toLowerCase().trim();
    this.spinner.show();
    this.crm.getCities(stateId).subscribe((data)=>{
      this.spinner.hide();
      this.cityDetails=data.data;
      if(address && address.city){
        if(!this.address_ids){
          let cityDet = this.cityDetails.find((s:any) =>  (address.city == s.location.toString().toLowerCase().trim()) ||  ((address.city.split(' ')[0]) == s.location.toString().toLowerCase().trim())  );
          cityId = cityDet.id;
        } 
        this.locationForm.patchValue({ city: cityId});
      }
    })
  }

  getStatesc(countryId:any,address:any=null){
    let stateId = 0;
     (address && address.state && this.address_ids ) ? stateId = (address.state || 0) : address.state = address.state?.toString().toLowerCase().trim();
     this.spinner.show();
     this.crm.getStates(countryId).subscribe((data)=>{
      this.spinner.hide();
      this.stateDetails=data.data;
      if(address && address.state){
        if(!this.address_ids){
          let stateDet = this.stateDetails.find((s:any) =>  address.state == s.state.toString().toLowerCase().trim());
          stateId = stateDet.id;
        } 
        this.locationForm.patchValue({ state: stateId });
        if(address && address.state) this.getCities(stateId,address);
      }
    })
}

 

  showLocalData(){
    this.editMode = true;
    this.locationForm.patchValue({
      address1:this.localdata.address1,
      address2:this.localdata.address2,
      country: this.localdata.country,
      state: this.localdata.state,
      city: this.localdata.city,  
      pincode:this.localdata.pincode,   
      latitude:this.localdata.latitude,
      longitude:this.localdata.longitude,
      measure:this.localdata.measure,
      track_radius:this.localdata.track_radius,
    });
    this.track_radius.setValue(this.localdata.track_radius);
    this.measure.setValue(this.localdata.measure);
    if(this.locationForm.controls.latitude.value && this.locationForm.controls.longitude.value){
        this.selected_location = {lat:Number(this.locationForm.controls.latitude.value),lng:Number(this.locationForm.controls.longitude.value)};
    }
      this.initAsyncMap(this.selected_location);
      this.searchClientOnMap = false;
  }

  async geocodeAddress(coords:any) {
    let lat =  Number(coords.lat);
    let lng =  Number(coords.lng);
    this.geocoder.geocode({ location: {lat,lng} }, (results:any, status:any) => {
      if (status === google.maps.GeocoderStatus.OK && results && results[0]) {
          this.locationForm.controls.address1.setValue(results[0].formatted_address);
      }
    });
  }
  updateRadius() {
    if(this.crm_track_radius){
      if(this.circle){
        this.circle.setRadius(this.locationForm.controls.track_radius.value?Number(this.locationForm.controls.track_radius.value):0);
        this.circle.setCenter(this.selected_location);
      } else{
        this.circle = new google.maps.Circle({
          center: this.selected_location,
          radius: this.locationForm.controls.track_radius.value?Number(this.locationForm.controls.track_radius.value):0, 
          map: this.map,
          fillColor: "blue",
          fillOpacity: 0.2,
          strokeColor: "blue",
          strokeOpacity: 0.5,
          strokeWeight: 2,
        });
      }
    }
    
  }

  updateMeasure() {
  
      if(this.circle_measure){
        this.circle_measure.setRadius(this.locationForm.controls.measure.value?Number(this.locationForm.controls.measure.value):0);
        this.circle_measure.setCenter(this.selected_location);
      } else{
        this.circle_measure = new google.maps.Circle({
          center: this.selected_location,
          radius: this.locationForm.controls.measure.value?Number(this.locationForm.controls.measure.value):0, 
          map: this.map,
          fillColor: "darkgreen",
          fillOpacity: 0.3,
          strokeColor: "darkgreen",
          strokeOpacity: 0.7,
          strokeWeight: 2,
        });
      }
    
    
  }


  onRadiusChange(){
    if(this.locationForm.controls.track_radius?.value){
      this.track_radius.setValue(this.locationForm.controls.track_radius?.value || 0);
    } 
    this.updateRadius();
  }

  onMeasureChange(){
    if(this.locationForm.controls.measure?.value){
      this.measure.setValue(this.locationForm.controls.measure?.value || 0);
    } 
    this.updateMeasure();
  }

  restrictToNumbers(event: KeyboardEvent,max:number = 6000) {
    if (!/[0-9]/.test(event.key) && event.key !== "Backspace") {
      event.preventDefault();
    } else if(event.key !== "Backspace"){
      const input = (event.target as HTMLInputElement).value;
      const next = input + event.key;
      if(max){
        if (+next > max) {
          event.preventDefault();
        }
      }
     
    } 
  }
  
  displayMarkerInGoogle(markerSelected:any) {
    let url = `https://maps.google.com/?q=${Number(markerSelected.lat)},${Number(markerSelected.lng)}`;
    window.open(url, '_blank');
  }


}




