import { Component, OnInit, ViewChild } from '@angular/core';
import { TdsService } from '../../tds.service'
import { TdsDialogsComponent } from '../../dialogs/tds-dialogs/tds-dialogs.component';
import { MatDialog } from '@angular/material/dialog';
import { MatTableDataSource } from '@angular/material/table';
import moment from 'moment';
import { MatPaginator } from '@angular/material/paginator';

@Component({
  selector: 'app-tds-details',
  templateUrl: './tds-details.component.html',
  styleUrls: ['./tds-details.component.scss']
})
export class TdsDetailsComponent implements OnInit {
  userSession:any
  activeChild:any;
  validationMessage:boolean=false;
  constructor(private tdsService: TdsService, private dialog: MatDialog) {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.activeChild = JSON.parse(sessionStorage.getItem('activeChild')||'');
   }
  displayedColumns: string[] = ['s_no', 'month_name', 'planned_deduction_amount', 'is_deducted','deducted_amount','deduction_ytd','deposit_status','deposited_on'];
  // dataSource:any= [
  //   {s_no: 1, month_name: "SEP 2024", planned_deduction_amount: "20000", is_deducted: "Deducted",deducted_amount:'20000',deduction_ytd:'20000',deposit_status:'Deposited',deposited_on:'01-09-2024'},
  //   {s_no: 2, month_name: "OCT 2024", planned_deduction_amount: "20000", is_deducted: "Exempted",deducted_amount:'0',deduction_ytd:'20000',deposit_status:'-',deposited_on:'-'},
  //   {s_no: 3, month_name: "NOV 2024", planned_deduction_amount: "20000", is_deducted: "Deducted",deducted_amount:'40000',deduction_ytd:'40000',deposit_status:'Deposited',deposited_on:'01-11-2024'},
  //   {s_no: 4, month_name: "DEC 2024", planned_deduction_amount: "20000", is_deducted: "Request_for_Exemption",deducted_amount:'-',deduction_ytd:'-',deposit_status:'-',deposited_on:'-'},
  // ];
  dataSource:MatTableDataSource<any> = <any>[]
  emptyData = new MatTableDataSource([{ empty: "row" }]);
  @ViewChild(MatPaginator) paginator!: MatPaginator;

  tdsDetails:any=[];
  pageLoading:boolean=true;

  async ngOnInit() {
    this.financialYear  = await this.getFinancialYears();
    this.validateEmployeeTaxExemptionStatus();
    this.getTdsDetails();
  }
  financeYears:any=[];
  financialYear:any;

    /** getFinancialYears Data*/
    getFinancialYears() {
      return new Promise((resolve) => {
        this.tdsService.getFinancialYears().subscribe((result: any) => {
          if (result.status && result.data.length) {
            this.financeYears = result.data;
            resolve(result.data[0].financial_year)
          } else {
            resolve('')
          }
        });
      });
    }


    // /** getFinancialYears Data*/
    // getFinancialYears() {
    //   this.tdsService.getFinancialYears().subscribe((result: any) => {
    //     this.financeYears=[]
    //     if (result.status && result.data.length > 0) {
    //       this.financeYears = result.data;
    //       this.financialYear=this.financeYears[0].financial_year;
    //       // this.tdsService.getEmployeeTdsDetails(this.userSession.id,this.financialYear);
    //       // this.tdsService.validateTaxDeductExemptionSubmissionStatus(this.userSession.id,this.financialYear)
    //       // this.getEmployeePayslips(this.financeyears[0].financial_year)
    //     }
    //     else {
    //       this.financeYears = []
    //     }
    //   })
    // }

    validateEmployeeTaxExemptionStatus(){
      this.tdsService.validateEmployeeTaxExemptionStatus(this.userSession.id,this.financialYear).subscribe((results)=>{
        if(results && results.status&& results.data){
          if(results.data[0] && results.data[0].tds_status.toString().includes(this.activeChild?.screenid)){
            this.validationMessage = true;
            this.validation(results.data[0].tds_message)
          }
        }
      })
    }

    validation(message:any){
      let dialogRef1 = this.dialog.open(TdsDialogsComponent, {
        position:{top:`50px`},
        disableClose: true,
        data: {message:message,flag:true}
      });
      dialogRef1.afterClosed().subscribe((result:any)=>{
        if(result){
        }
      })
    }

    getTdsDetails(){
      this.tdsDetails = [];
      this.tdsService.getEmployeeTdsDetails(this.userSession.id,this.financialYear).subscribe((results:any)=>
      {
        if(results && results.status){
          results.data.forEach((ele:any)=>{
            if(ele.deposited_on){
              ele.deposited_on =  moment(ele.deposited_on).format('DD-MM-YYYY')
            }
          })
          this.tdsDetails = results.data;
          this.dataSource = new MatTableDataSource(this.tdsDetails)
          this.dataSource.paginator = this.paginator;
          this.pageLoading = this.tdsDetails.length <= 20?true:false;
  
        }
      });
    }

    setEmployeeTdsDeductionExemptionRequest(val:any){
      let input = {
        employeeId : this.userSession.id,
        year:val.year_value,
        month:val.month_name,
        monthlyGrossSalary: 50000, //val.monthly_gross_salary,
        deductibleAmount:val.planned_deduction_amount,
        createdBy:this.userSession.id, 

      }
      this.tdsService.setEmployeeTdsDeductionExemptionRequest(input).subscribe((results:any)=>{
        if(results && results.status){
          
        }
      })
    }


    request(val:any){    
    let dialogRef1 = this.dialog.open(TdsDialogsComponent, {
      position:{top:`50px`},
      disableClose: true,
      data: {message:'Are you sure you want to request exemption of deduction for the selected month?'}
    });
    dialogRef1.afterClosed().subscribe((result:any)=>{
      if(result){
        this.setEmployeeTdsDeductionExemptionRequest(val)
      }
    })
    }
    
    getPageSizes(): number[] {
      var customPageSizeArray = [];
      if (this.dataSource.data.length < 5) {
        customPageSizeArray.push(5);
      }
      if (this.dataSource.data.length > 5) {
        customPageSizeArray.push(5);
      }
      if (this.dataSource.data.length > 10) {
        customPageSizeArray.push(10);
      }
      if (this.dataSource.data.length > 20) {
        customPageSizeArray.push(20);
      }
      customPageSizeArray.push(this.dataSource.data.length);
      return customPageSizeArray;
    }
    // Are you sure you want to request exemption of deduction for the selected month?

    applyFilter(event: Event) {
      const filterValue = (event.target as HTMLInputElement).value;
      this.dataSource.filter = filterValue.trim().toLowerCase();
    
      if (this.dataSource.paginator) {
        this.dataSource.paginator.firstPage();
      }
    }

    changeFinancialYear(){
      this.getTdsDetails()
    }

}
