
import { Component, Inject,OnInit } from '@angular/core';
import { FormBuilder,FormControl, FormGroup, Validators } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { decimalWithDotTwoDirective } from '../../../../custom-directive/decimal-with-dot-two/decimal-with-dot-two.directive'
@Component({
  selector: 'app-approve-earning-dialog',
  templateUrl: './approve-earning-dialog.component.html',
  styleUrls: ['./approve-earning-dialog.component.scss']
})
export class ApproveEarningDialogComponent implements OnInit {

  earningForm: FormGroup;

  constructor(
    private fb: FormBuilder,
    public dialogRef: MatDialogRef<ApproveEarningDialogComponent>,
    @Inject(MAT_DIALOG_DATA) public data: any
  ) {
    this.earningForm = new FormGroup({
      item:new FormControl({value:data}),
      earningAmount:new FormControl( { value: data.earning_amount_declared, disabled: true }),
      approveAmount: new FormControl(
        data.earning_amount_declared ,
        [Validators.required,  decimalWithDotTwoDirective()],
      ),
    });
  }

  ngOnInit(): void {
  }
  onSubmit(): void {
    if (this.earningForm.valid) {
      this.dialogRef.close(this.earningForm.value); // Pass data back to the parent
    }
  }

  onCancel(): void {
    this.dialogRef.close(null); // Close without data
  }
  onBlur() {
    this.earningForm.get('approveAmount')?.markAsTouched();
  }
}
