import { Component, OnInit,ViewChild } from '@angular/core';
import { animate, state, style, transition, trigger } from '@angular/animations';
import { UntypedFormGroup, UntypedFormBuilder, Validators, FormControl } from '@angular/forms';
import { Router, ActivatedRoute } from '@angular/router';
import { PayrollService } from '../../payroll.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatDialog } from '@angular/material/dialog';
import { DatePipe } from "@angular/common";
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { map } from 'rxjs/operators';
import { ReviewAndApprovalsComponent } from 'src/app/modules/leaves/dialog/review-and-approvals/review-and-approvals.component';
@Component({
  selector: 'app-approval-salaries',
  templateUrl: './approval-salaries.component.html',
  styleUrls: ['./approval-salaries.component.scss']
})
export class ApprovalSalariesComponent implements OnInit {

  displayedColumns2: string[] = ['sno','empid','empname', 'location', 'paygroupname', 'grass', 'earnings','deductions','status','action'];
  getGrossSalary:any=[];
  dataSource2:any = [];
  userSession:any;
  pageLoading = true;
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  titleName:any;
  reason:any;
  constructor(private router: Router, private companyService: CompanySettingService,private ActivatedRoute: ActivatedRoute, private formBuilder: UntypedFormBuilder, private PR: PayrollService, private dialog: MatDialog) { }

  ngOnInit(): void {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.getGrossSalaryIntermediary();
  }
    /**get_gross_salary_intermediary */
  getGrossSalaryIntermediary(){
    let data = {
     id_value:null,
     emp_id:null,
     paygroup_id:null,
     status_value:null
    }
    this.getGrossSalary = [];
    this.PR.getGrossSalaryIntermediary(data).subscribe((result: any) => {
      if (result.status && result.data.length > 0) {
        this.getGrossSalary = result.data;
        this.dataSource2 = new MatTableDataSource(result.data);
        this.dataSource2.paginator = this.paginator;
        this.dataSource2.sort = this.sort;
        this.pageLoading = false;
      }
    })
  }
  getPageSizes(): number[] {

    var customPageSizeArray = [];
    if (this.dataSource2.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource2.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource2.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource2.data.length);
    return customPageSizeArray;
  }


 applyFilter(event: Event) {
  console.log(event)
    const filterValue = (event.target as HTMLInputElement).value;
    console.log("test",filterValue)
    this.dataSource2.filter = filterValue.trim().toLowerCase();
    if (this.dataSource2.paginator) {
      this.dataSource2.paginator.firstPage();
    }
  }

  /**Approve Salary */
  approveSalary(row:any) {
    let data = {
      empid :row.emp_id,
      paygroupid:row.pay_group_id,
      data:JSON.parse(row.components_json),
      esi_applicable:row.esi_applicable,
      CTC:row.annual_gross_salary,
      l_id:row.id
    }
    this.PR.assignPayGroup(data).subscribe((result: any) => {
      console.log("result.data[0].statuscode",result.data)
      console.log("result.data[0].statuscode",result.data[0][0])
       console.log("result.data[0].statuscode",result.data[0][0].statuscode)
        if (result.status) {
          if(result.data[0][0].statuscode == 0 || result.data[0].statuscode == 0){
            let dialogRef = this.dialog.open(ReusableDialogComponent, {
            position: { top: `70px` },
            disableClose: true,
            data:result.data[0][0].message
          });
          this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
            this.router.navigate(["/Payroll/aGSApprovals"]));

        }
        else{
            let dialogRef = this.dialog.open(ReusableDialogComponent, {
            position: { top: `70px` },
            disableClose: true,
            data:result.data[0][0].statuscode
          });

        }
          }
       
        else {
          let dialogRef = this.dialog.open(ReusableDialogComponent, {
            position: { top: `70px` },
            disableClose: true,
            data: 'unable to approve'
            
          });
        }
      })

  }
  /**Reject Salary */
   SalaryReject(data: any, status: any, approverId: any) {
    this.titleName = "Gross Annual Salary Rejection Reason"
    this.openDialog(data)

  }
    openDialog(row: any): void {
      const dialogRef = this.dialog.open(ReviewAndApprovalsComponent, {
        width: '600px', position: { top: `100px` },
        data: { name: this.titleName, reason: this.reason, }
      });
  
      dialogRef.afterClosed().subscribe(result => {
  
        if (result != undefined) {
          if (result !== true) {
            let data = {
                  id_value:row.id,
                  empid:row.emp_id,
                  grosssalary: row.annual_gross_salary,
                  paygroupid: row.pay_group_id,
                  data: JSON.parse(row.components_json),
                  esi_applicable: row.esi_applicable,
                  submitted_by_value:this.userSession.id,
                  status_value:'Rejected',
                  reason:result.reason
            }
      console.log("test",data)
            this.PR.setGrossSalary(data).subscribe((result: any) => {
              if (result.status) {
                if(result.data[0].statuscode == 0){
                    let dialogRef = this.dialog.open(ReusableDialogComponent, {
                      position: { top: `70px` },
                      disableClose: true,
                      data:result.data[0].message
                    });
                    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
                      this.router.navigate(["/Payroll/aGSApprovals"]));
                  }
                  else{
                    let dialogRef = this.dialog.open(ReusableDialogComponent, {
                      position: { top: `70px` },
                      disableClose: true,
                      data: result.data[0].message
                    });
                  }
              }
              else {
                let dialogRef = this.dialog.open(ReusableDialogComponent, {
                  position: { top: `70px` },
                  disableClose: true,
                  data: 'unable to reject'
                }); 
              }
          })
            
          }
        }
      });
    }

}
