/**Author Mounika */
exportAsXLSX() {
  const excelData = this.List.map((row, index) => ({
    'S.No': index + 1,
    'Name': row.employee_name,
    'Contact Number': row.contact,
    'Email Address': row.email,
    'Client': row.client_name,
    'Associate Type': row.employee_type,
    'Qualification': row.qualification_type,
    'Specialization': row.specialization_type,
    'Created By': row.created_by,
 
   
    'Created On': row.created_on ? new Date(row.created_on) : null
  }));
 
  const ws: XLSX.WorkSheet = XLSX.utils.json_to_sheet(excelData);
 

  this.formatExcelDateColumn(ws, 'Created On');
 
  const wb: XLSX.WorkBook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Client Associates Report');
 
  XLSX.writeFile(wb, 'Client  Associates Report.xlsx');
}
 
formatExcelDateColumn(ws: XLSX.WorkSheet, headerName: string) {
  const range = XLSX.utils.decode_range(ws['!ref'] as string);
 
  let colIndex = -1;
 
  // find column
  for (let C = range.s.c; C <= range.e.c; ++C) {
    const cell = ws[XLSX.utils.encode_cell({ r: 0, c: C })];
    if (cell?.v === headerName) {
      colIndex = C;
      break;
    }
  }
 
  if (colIndex === -1) return;
 
  for (let R = 1; R <= range.e.r; ++R) {
    const addr = XLSX.utils.encode_cell({ r: R, c: colIndex });
    const cell = ws[addr];
 
    if (cell?.v instanceof Date) {
      cell.t = 'n';
      cell.z = 'dd-mm-yyyy';
 
 
      cell.v = (cell.v.getTime() / 86400000) + 25569;
    }
  }
}
