openFilterDialog(template: TemplateRef<any>) {

  //  RESET FORM BEFORE OPENING FILTER
  this.searchForm.reset({
    associateTypes: null,
    qualifications: null,
    specializations: null,
    fromDate: this.searchForm.value.fromDate, // keep dates if you want
    toDate: this.searchForm.value.toDate
  });

  // Clear selected ID arrays
  this.selectedAssociationTypes = [];
  this.selectedQualifications = [];
  this.selectedSpecializations = [];

  // Reset select-all UI flags
  this.empIshide = false;
  this.qualIshide = false;
  this.spIshide = false;

  this.empIschecked = false;
  this.qualIschecked = false;
  this.spIschecked = false;

  this.filterDialogRef = this.dialog.open(template, {
    width: '550px',
    maxWidth: '95vw'
  });
}


cancel() {
  // Clear all filters and form values
  this.resetform();

  // Close filter dialog
  if (this.filterDialogRef) {
    this.filterDialogRef.close();
  }
}





