exportAsXLSX(): void {
  if (!this.date?.value) return; // safety check

  // Get selected month/year from date picker (Moment object)
  const selectedMoment = this.date.value as _moment.Moment; // Moment type
  const year: number = selectedMoment.year();
  const monthIndex: number = selectedMoment.month(); // 0-based index
  const monthName: string = this.months[monthIndex].month;

  // Columns to exclude from Excel
  const excludedColumns = ['Pay Slip', 'NetSalaryId', 'EmpId'];

  // Filter columns to include
  const columnsToExport: string[] = this.tablecolumns.filter((col: string) => !excludedColumns.includes(col));

  // Prepare Excel data
  const excelData: any[] = this.dataSource.data.map((row: any, index: number) => {
    const newRow: any = { 'S.No': index + 1 }; // Add S.No first

    // Copy only allowed columns
    columnsToExport.forEach((col: string) => {
      newRow[col] = row[col];
    });

    return newRow;
  });

  // Convert JSON to worksheet
  const ws: XLSX.WorkSheet = XLSX.utils.json_to_sheet(excelData);

  // Create workbook and append worksheet
  const wb: XLSX.WorkBook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'payroll_detailreport');

  // Save Excel file with selected month/year
  XLSX.writeFile(wb, `payroll_detail_report_${monthName}_${year}.xlsx`);
}




