import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { BehaviorSubject, Observable, of } from 'rxjs';
import { catchError, tap } from 'rxjs/operators';

@Injectable({
  providedIn: 'root'
})
export class TranslateByTypeService {
  private cache: { [key: string]: any } = {}; // e.g., { city_arabic: {...}, state_arabic: {...} }
  private languageSubject = new BehaviorSubject<string>(this.getInitialLanguage());

  language$ = this.languageSubject.asObservable();

  constructor(private http: HttpClient) {} // removed ChangeDetectorRef

  private getInitialLanguage(): string {
    return localStorage.getItem('lang')?.toLowerCase() || 'english';
  }

  /** Change language globally */
  setLanguage(lang: string) {
    localStorage.setItem('lang', lang);
    this.languageSubject.next(lang.toLowerCase());
  }

  private getCacheKey(type: string, lang: string): string {
    return `${type}-${lang}`;
  }

  /** Load translation JSON only for non-English */
  loadData(type: string, lang: string): Observable<any> {
    if (lang === 'english') return of({});
    let key = this.getCacheKey(type, lang);

    if (this.cache[key]) return of(this.cache[key]);

    let url = `assets/i18n/${type}-list/${lang}.json`;

    return this.http.get(url).pipe(
      tap((data: any) => {
        this.cache[key] = data;
      }),
      catchError(() => {
        console.warn(`⚠️ No translation file found for: ${url}`);
        return of({});
      })
    );
  }

  /** Translate a single value */
  translate(type: string, lang: string, name: string): string {
    if (lang === 'english') return name;
    let key = this.getCacheKey(type, lang);
    return this.cache[key]?.[name] || name;
  }

  clearCache() {
    this.cache = {};
  }
}
