import { Component, Inject, OnInit } from '@angular/core';
import { MatTableDataSource } from '@angular/material/table';
import { ReportsService } from '../../reports.service';
import { DialogDetailComponent } from '../dialog-detail/dialog-detail.component';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { PdfHeaderService } from 'src/app/services/pdf-header-service/pdf-header.service';
import { DatePipe } from '@angular/common';
import * as XLSX from 'xlsx';
import * as _moment from 'moment';
@Component({
  selector: 'app-checkin-out-summary-report-dialog',
  templateUrl: './checkin-out-summary-report-dialog.component.html',
  styleUrls: ['./checkin-out-summary-report-dialog.component.scss'],
})
export class CheckinOutSummaryReportDialogComponent implements OnInit {
  empId: any;
  empName: any;
  present: any;
  absent: any;
  total: any;
  dataSource: MatTableDataSource<any> = <any>[];
  List: any = [];
  empid: any;
  employeeName: any;
  displayedColumns: any = [
    'sno',
    'date',
    'intime',
    'outtime',
    'totalHours',
    'breaks',
    'breakTime',
    'productiveHours',
    'otHours',
    'permissionHours',
  ];
  constructor(
    private reportsService: ReportsService,
    private pdfService: PdfHeaderService,
    public datePipe: DatePipe,
    public dialogRef: MatDialogRef<DialogDetailComponent>,
    @Inject(MAT_DIALOG_DATA) public data: any
  ) { }

  ngOnInit(): void {
    this.getAttendanceDetailedSummaryReport();
    this.empid = this.data.employeeId;
    this.employeeName = this.data.empname;
  }
  getAttendanceDetailedSummaryReport() {
    let obj = {
      empname: this.data.employeeId,
      calenderDate: this.data.calenderDate,
    };
    this.List = [];
    this.reportsService
      .getAttendanceDetailedSummaryReport(obj)
      .subscribe((res: any) => {
        if (res.status) {
          let responseData = res.data.map((item: any) => {
            return {
              ...item,
              breaks: item.breaks
                ?.split(',')
                ?.map((each: any) => each?.slice(11,16)),
              totalhours:item.totalhours?.slice(0,5),
              breaktime:item.breaktime?.slice(0,5),
              productivehours:item.productivehours?.slice(0,5),
              overtime_minutes:item.overtime_minutes?.slice(0,5),
              permissionhours:item.permissionhours?.slice(0,5), 
            };
          });
          this.List = responseData;
          this.dataSource = new MatTableDataSource(this.List);
        }
      });
  }

  generatePDF() {
  
  
   const doc = new jsPDF({ orientation: 'landscape' });
    const reportName = 'Detailed Punch Summary Report';
    let manager = this.employeeName;
    let locationName = '';
    let reportDate = this.datePipe.transform(this.data.calenderDate, "MMMM-yyyy");
     this.pdfService.generatePDFHeader(doc, reportName,locationName,manager,reportDate,false,true);
    const tableData = this.List.map((
      emp: { 
        attendancedate: any; 
        firstlogintime: any; 
        lastlogouttime: any, 
        totalhours: any, 
        breaks: any, 
        breaktime: any, 
        productivehours: any, 
        overtime_minutes: any, 
        permissionhours: any, 
      },
       index: number) => [
      
      index + 1,
      this.datePipe.transform(emp.attendancedate, "dd-MM-yyyy"),
      this.datePipe.transform(emp.firstlogintime, "HH:mm"),
      this.datePipe.transform(emp.lastlogouttime, "HH:mm"),
      emp.totalhours,
      emp.breaks.join('\n'),
      emp.breaktime,
      emp.productivehours,
      emp.overtime_minutes,
      emp.permissionhours,
    ]);
          autoTable(doc, {
            head: [['S. No.', 'Date', 'First In', 'Last out','Total Hrs','Punches','Break Hrs','Productive Hrs','OT Hrs','Permission Hrs']],
            body:tableData,
            startY: 47,
            styles: { fontSize: 10 },
            headStyles: { fontSize: 12 },
            bodyStyles: { cellPadding: 2, valign: 'middle' },
          });
       doc.save('Detailed_Punch_Summary_Report.pdf');
  } 

  exportToExcel() {
    let reportDate = this.datePipe.transform(this.data.calenderDate, "MMMM-yyyy");
  
    const exportData = this.List.map((row: any, index: any) => ({
      "S.No": index + 1,
      "Date": this.datePipe.transform(row.attendancedate, "dd-MM-yyyy"),
      "First In": this.datePipe.transform(row.firstlogintime, "HH:mm"),
      "Last Out": this.datePipe.transform(row.lastlogouttime, "HH:mm"),
      "Total Hours": row.totalhours,
      "Punches": (row.breaks || []).join('\r\n'), 
      "Break Hrs": row.breaktime,
      "Productive Hours": row.productivehours,
      "OT Hours": row.overtime_minutes,
      "Permission Hours": row.permissionhours
    }));
  
    const ws: XLSX.WorkSheet = XLSX.utils.json_to_sheet(exportData);
      const wscols = [
      { wch: 5 },  
      { wch: 12 }, 
      { wch: 10 },
      { wch: 10 }, 
      { wch: 12 },
      { wch: 30 }, 
      { wch: 10 }, 
      { wch: 18 },
      { wch: 10 }, 
      { wch: 15 }, 
    ];
    ws['!cols'] = wscols;
 
    const wb: XLSX.WorkBook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Detailed_Punch_Summary_Report');
    XLSX.writeFile(wb, reportDate + " - " + 'Detailed_Punch_Summary_Report.xlsx');
  }
  
}
