  on_change_created_by($event: any, index: any, keyname: any) {
     
    this.ishiding[keyname][index] = Number($event.checked ? 1 : 0);
    let count = 0;
    this.ishiding[keyname].forEach((val: any) => {
      count = count + Number(val);
    });
    this.ischecked[keyname] = (this.ids[keyname].length === count) ? true : false;
    this.isindeterminate[keyname] = (this.ids[keyname].length - count > 0) ? true : false;
    
  }

  onChange($event: any) {
    this.ishiding['columns'] = [];
    //this.dynamicArr = [];
    if ($event.checked) {
      this.columns.forEach(() => {
        this.ishiding['columns'].push(Number(1));
      });
      this.earningsFormArray.setValue(this.ishiding['columns']);
      this.isindeterminate['columns'] = false;
      this.ischecked['columns'] = true
    }
    else {
      this.columns.forEach((c:any) => {
        let num = (this.columns_default.includes(c.keyname))?1:0; 
        this.ishiding['columns'].push(Number(num));         
      });
      this.earningsFormArray.setValue(this.ishiding['columns']);
      this.isindeterminate['columns'] = this.columns_default.length?true:false;
      this.ischecked['columns'] = false
    }
  }
