import { Component, OnInit } from '@angular/core';
import { LearnService } from '../../learn.service';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import { Router } from '@angular/router';

@Component({
  selector: 'app-lms-course-list',
  templateUrl: './lms-course-list.component.html',
  styleUrls: ['./lms-course-list.component.scss']
})
export class LmsCourseListComponent implements OnInit {
  courses: any[] = []; // This will store the list of courses
  modules: any[] = []; // To store modules for the selected course
  isModuleView: boolean = false; // Toggle between course list and module view
  selectedCourseId: number = 0;
  selectedCourseName: string = "";  // And its name for display
  expandedModuleId: number | null = null;
  sectionsMap = new Map<number, any[]>();
  selectedCourse: any = null;
  userSession: any

  departments: any[] = [];
  difficultyLevels: any[] = [];
  timeFilters: any[] = [];
  instructors:any[]=[];
  CourseStatuses:any[]=[];

  selectedDeptId: number = 0;
  selectedDifficultyId: number = 0;
  selectedTimeFilterId: number = 0;
  selectedStatusId:number=4;
  selectedInstructorId:number=0;


  searchText: string = '';
  filteredCourses: any[] = [];
  

  showConfirmDialog = false;
  selectedEnrollCourseId: number | null = null;
  enrollmentComplete = false;
  enrollmentSuccessMessage = '';
  enrollmentInProgress = false;
  isLoadingCourses = false;


  showCertificateDialog = false;
  certificates: any[] = [];

  constructor(private learnService: LearnService, private sanitizer: DomSanitizer, private router: Router) {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');

  }

  ngOnInit(): void {
    this.lms_get_course();
    this.loadDropdowns();  
  }


  courseContinue(courseId: number): void {
    this.router.navigate(['/learning/LmsViewCourse', courseId]);
  }

  enrollCourse(courseId: number): void {
    this.selectedEnrollCourseId = courseId;
    this.showConfirmDialog = true;
    this.enrollmentComplete = false;
    this.enrollmentSuccessMessage = '';
  }

  confirmEnroll(): void {
    if (this.selectedEnrollCourseId == null) return;
  
    this.enrollmentInProgress = true;
  
    // ← define both userId and courseId
    const userId   = this.userSession.id;
    const courseId = this.selectedEnrollCourseId;
  
    // ← now courseId exists!
  
    this.learnService
      .setEnrollment(userId, courseId)
      .subscribe({
        next: (res: any) => {
          this.enrollmentSuccessMessage = res.message || 'Enrollment successful';
          this.enrollmentComplete       = true;
          this.enrollmentInProgress     = false;
        },
        error: (err) => {
          console.error('Enrollment error:', err);
          this.enrollmentSuccessMessage = 'Enrollment failed. Please try again.';
          this.enrollmentComplete       = true;
          this.enrollmentInProgress     = false;
        }
      });
  }
  

  // Called when user clicks “No”
  cancelEnroll(): void {
    this.showConfirmDialog = false;
    this.selectedEnrollCourseId = null;
  }

  // After success, proceed to view-course
  proceedToCourse(): void {
    if (this.selectedEnrollCourseId != null) {
      this.showConfirmDialog = false;
      this.router.navigate(
        ['/learning/LmsViewCourse', this.selectedEnrollCourseId]
      );
    }
  }



filterCourses(): void {
  const search = this.searchText.trim().toLowerCase();
  this.filteredCourses = this.courses
    .filter(course =>
      // only keep courses with > 1 section
      course.total_sections > 0 &&
      // and matching the search term
      course.course_name.toLowerCase().includes(search)
    );
}
  
  
loadDropdowns(): void {
  this.learnService.getDepartments().subscribe((res) => {
    this.departments = [{ id: 0, deptname: 'All' }, ...res.departments];
  });

  this.learnService.getDifficultylevels().subscribe((res) => {
    this.difficultyLevels = [{ id: 0, level_name: 'All' }, ...res.levels];
  });

  this.learnService.getTimeFilters().subscribe((res) => {
    this.timeFilters = res.filters;
  });

  this.learnService.getInstructors().subscribe((res) => {
    this.instructors = [{ instructor_id: 0, instructor_name: 'All' }, ...res.instructors];
  });

  this.learnService.getCourseStatus().subscribe((res) => {
    this.CourseStatuses = [{ status_id: 4, status_name: 'All' }, ...res.status];
  });

}

  getSafeImageUrl(course: any): SafeUrl {
    return this.sanitizer.bypassSecurityTrustUrl('data:image/png;base64,' + course.thumbnail);
  }


lms_get_course(): void {
  this.isLoadingCourses = true;

  this.learnService.get_lms_course(
    0,
    this.userSession.id,
    this.selectedDeptId,
    this.selectedDifficultyId,
    this.selectedTimeFilterId,
    this.selectedInstructorId,
    this.selectedStatusId
  ).subscribe({
    next: (data: any) => {
      this.courses = data.courses || [];
      this.filterCourses();
      this.isLoadingCourses = false;
    },
    error: () => {
      this.isLoadingCourses = false;
    }
  });
}


  onFilterChange(): void {
  // nuke previous results right away
  // this.courses = [];
  // this.filteredCourses = [];
  this.lms_get_course();
}

  showModules(course: any): void {
    // Store the entire course object
    this.selectedCourse = course;
    this.selectedCourseId = course.course_id;

    // Now fetch modules for this course
    this.learnService.getModules(0, course.course_id).subscribe({
      next: (data: any) => {
        this.modules = data.modules;
        this.isModuleView = true;
      },
      error: (error: any) => {
        console.error('Error fetching modules:', error);
      }
    });
  }





  // Called when the Back button is pressed in module view.
  goBack(): void {
    this.isModuleView = false;
    this.modules = []; // Optionally clear modules
  }







  toggleModuleExpansion(module: any): void {
    // If the module is already expanded, collapse it
    if (this.expandedModuleId === module.id) {
      this.expandedModuleId = null;
      return;
    }
    // Otherwise, expand it and fetch sections if not already fetched
    this.expandedModuleId = module.id;

    // If we haven't fetched sections for this module yet, do so
    if (!this.sectionsMap.has(module.id)) {
      this.learnService.getSections(0,0, module.id,1).subscribe({
        next: (data: any) => {
          this.sectionsMap.set(module.id, data.modules || data.sections || []);
        },
        error: (err) => console.error('Error fetching sections:', err)
      });
    }
  }


  getDifficultyClass(difficulty: string): string {
    switch (difficulty?.toLowerCase()) {
      case 'beginner':
        return 'beginner';
      case 'intermediate':
        return 'intermediate';
      case 'advanced':
        return 'advanced';
      default:
        return ''; // fallback
    }
  }


  getThumbnail(thumbnail: string): SafeUrl {
    if (thumbnail && !thumbnail.startsWith('data:image')) {
      return this.sanitizer.bypassSecurityTrustUrl(`data:image/png;base64,${thumbnail}`);
    }
    return this.sanitizer.bypassSecurityTrustUrl(thumbnail);
  }


  getFormattedDuration(duration: string): string {
    const [hours, minutes] = duration.split(':').map(num => parseInt(num));
    return `${hours.toString().padStart(2, '0')}hr : ${minutes.toString().padStart(2, '0')}min`;
  }

  getProgress(course: any): number {
    if (!course.total_sections || course.total_sections === 0) return 0;
    const completed = course.completed_sections || 0;
    return Math.floor((completed / course.total_sections) * 100);
  }

  viewCertificate(courseId: number): void {
    // fetch and then show
    this.learnService
      .getEmployeeCertificates(this.userSession.id, courseId)
      .subscribe({
        next: (data: any) => {
          this.certificates = data;
          this.showCertificateDialog = true;
        },
        error: (err) => {
          console.error('Error loading certificates', err);
        }
      });
  }

// ─── add a close helper ───
  closeCertificateDialog(): void {
    this.showCertificateDialog = false;
    this.certificates = [];
  }


}